window.KAN=[{"id":"2016-1","s":0,"q":"国民の生存権と国の社会的な役割について、日本国憲法第25条に定められているものはどれか。","o":["すべて国民は、個人として尊重される。","何人も、いかなる奴隷的拘束も受けない。","すべて国民は、勤労の権利を有し、義務を負う。","国民は、すべての基本的人権の享有を妨げられない。","すべて国民は、健康で文化的な最低限度の生活を営む権利を有する。"],"a":4,"e":"憲法第25条第1項は「すべて国民は、健康で文化的な最低限度の生活を営む権利を有する」と定めている(生存権)。ほかは第13条・第18条・第27条・第11条の内容。","l":"日本国憲法 第25条","c":""},{"id":"2016-2","s":0,"q":"建築物衛生法に定められている内容として、誤っているものはどれか。","o":["特定建築物の敷地・構造・設備・用途についての最低の基準を定めている。","公衆衛生の向上と増進に役立つことを目的にしている。","保健所は、多くの人が使う建物の維持管理について、環境衛生上の正しい知識を広める。","保健所は、多くの人が使う建物の維持管理について、環境衛生上の相談に応じ、必要な指導を行う。","特定建築物の維持管理について、環境衛生上必要な事項などを定めている。"],"a":0,"e":"建築物の敷地・構造・設備・用途の最低の基準を定めているのは建築基準法である。建築物衛生法は維持管理の面から定めている。","l":"建築物衛生法 第1条、第3条","c":""},{"id":"2016-3","s":0,"q":"特定建築物の定義とその判断について、誤っているものはどれか。","o":["建築基準法でいう建築物であること。","同じ敷地に独立した建物が複数ある場合は、それらを合計した延べ面積で判断する。","特定用途に付属する廊下・階段・便所などの共用部分は、特定用途の延べ面積に含める。","特定用途に使われる部分の延べ面積が3,000m²以上(学校教育法第1条の学校などは8,000m²以上)であること。","特定建築物の延べ面積の計算方法は、建築基準法の定義による計算方法と違う場合がある。"],"a":1,"e":"特定建築物かどうかは建物1棟ごとに判断する。同じ敷地に独立した建物が複数あっても、合計はしない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2016-4","s":0,"q":"特定建築物の用途に当たらないものはどれか。","o":["美術館","飲食店","銀行","映画館","寺院"],"a":4,"e":"寺院などの宗教施設は、特定用途に含まれない。美術館は博物館、飲食店・銀行は店舗・事務所、映画館は興行場に当たる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2016-5","s":0,"q":"次の建築物のうち、特定建築物に当たらないものはどれか。","o":["教室3,200m²、実習室700m²、職員室100m²をもつ各種学校","事務所3,800m²、商品倉庫200m²をもつ事務所ビル","宿泊施設2,800m²、宴会場700m²をもつホテル","売り場3,800m²、商品倉庫200m²をもつデパート","共同住宅3,200m²、店舗800m²をもつ複合ビル"],"a":4,"e":"共同住宅は特定用途に含まれないため、特定用途の部分は店舗の800m²だけとなり、3,000m²に届かない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2016-6","s":0,"q":"特定建築物の届出について、誤っているものはどれか。","o":["特定建築物を使い始めてから1か月以内に届け出る。","届出事項には、特定建築物の名称・所在場所・用途・構造設備の概要が含まれる。","届出は、厚生労働大臣が定めた様式で行う。","届出は、都道府県知事(保健所を設置する市・特別区は市長・区長)あてに行う。","届出事項が変わったときは、その日から1か月以内に届け出る。"],"a":2,"e":"この記述が誤り。施行規則は届書に書く事項を定めているが、厚生労働大臣が定めた届出の様式によるとはされていない。","l":"建築物衛生法 第5条、施行規則 第1条","c":""},{"id":"2016-7","s":0,"q":"建築物衛生法で備えておかなければならない帳簿書類として、誤っているものはどれか。","o":["飲用の給水配管の系統図","空気環境の測定結果の記録","昇降機(エレベーター)の点検整備の記録","ねずみ等の生息状況の調査結果の記録","排水設備の点検整備の記録"],"a":2,"e":"帳簿書類は、空気環境の調整・給排水の管理・清掃・ねずみ等の防除の状況や、維持管理に関する設備の配置・系統図などで、昇降機の点検整備記録は含まれない。","l":"建築物衛生法施行規則 第20条","c":""},{"id":"2016-8","s":0,"q":"建築物環境衛生管理基準について、誤っているものはどれか。","o":["特定建築物の所有者等で維持管理について権原をもつ者は、管理基準に従って維持管理をしなければならない。","空気調和設備のある特定建築物では、浮遊粉じんの量・一酸化炭素・二酸化炭素・窒素酸化物の含有率・温度・相対湿度・気流について、それぞれの基準値を守らなければならない。","管理基準は、空気環境の調整、給水・排水の管理、清掃、ねずみ等の防除など、環境衛生上良い状態を保つのに必要な措置を定めている。","管理基準でいう「ねずみその他の厚生労働省令で定める動物」とは、昆虫など、人の健康を損なうおそれのある動物をいう。","特定建築物でなくても、多くの人が使う建物の維持管理について権原をもつ者は、管理基準に従って維持管理するよう努めなければならない。"],"a":1,"e":"空気環境の管理基準の項目は、浮遊粉じん・一酸化炭素・二酸化炭素・温度・相対湿度・気流・ホルムアルデヒドで、窒素酸化物は含まれない。","l":"建築物衛生法施行令 第2条第1号","c":""},{"id":"2016-9","s":0,"q":"ある事務室の空気環境の測定結果の一部は次のとおりである。建築物環境衛生管理基準に合わない項目の組合せはどれか。\n【1回目】一酸化炭素 1.5ppm、二酸化炭素 1,100ppm、温度 22.5℃、相対湿度 30%\n【2回目】一酸化炭素 3.5ppm、二酸化炭素 1,200ppm、温度 23.0℃、相対湿度 35%","o":["一酸化炭素の含有率と温度","一酸化炭素の含有率と相対湿度","二酸化炭素の含有率と温度","二酸化炭素の含有率と相対湿度","温度と相対湿度"],"a":3,"e":"基準は、二酸化炭素1,000ppm以下、相対湿度40%以上70%以下なので、この2つが合わない。一酸化炭素(6ppm以下)と温度(18℃以上28℃以下)は基準内。","l":"建築物衛生法施行令 第2条第1号イ","c":"元の問題は表で示されていたが、数値を問題文に書き出した。解説の基準値は2022年4月改正後の現行値(一酸化炭素6ppm以下、温度18℃以上)で示した(正答は変わらない)。"},{"id":"2016-10","s":0,"q":"建築物環境衛生管理基準にもとづく給排水設備の衛生上の措置について、正しいものはどれか。","o":["飲料水の貯水槽の清掃が終わった後は、槽の中の消毒を2回以上行うこと。","雨水や工業用水などを原水とする雑用水の大腸菌の検査は、3か月以内ごとに1回、定期に行うこと。","飲料水の貯水槽を清掃して水張りが終わった後、給水栓と貯水槽内の結合残留塩素が100万分の0.2以上であることを確かめること。","飲むために給水設備を設ける場合は、建築基準法の規定に合った水を供給すること。","給湯用の貯湯槽の清掃は、2年以内ごとに1回、定期に行うこと。"],"a":0,"e":"告示では、貯水槽の清掃後に槽内の消毒を2回以上行うとされている。雑用水の大腸菌検査は2か月以内ごと、水張り後に確かめるのは遊離残留塩素、飲料水は水道法の水質基準、貯湯槽の清掃は1年以内ごとである。","l":"空気調和設備等の維持管理及び清掃等に係る技術上の基準(平成15年厚生労働省告示第119号)","c":""},{"id":"2016-11","s":0,"q":"建築物環境衛生管理技術者について、最も適当なものはどれか。","o":["選任された特定建築物に常駐しなければならない。","特定建築物の環境衛生上の維持管理の帳簿書類を備える義務がある。","特定建築物維持管理権原者に、設備改善などを命令できる。","建築物環境衛生管理基準に関する測定や検査の結果を評価する。","環境衛生上の維持管理に従事する職員を雇う。"],"a":3,"e":"管理技術者は、維持管理が適正に行われるよう全体を監督する立場で、測定・検査結果の評価などを行う。帳簿の備え付けは所有者等の義務で、権原者には意見を述べることができる。","l":"建築物衛生法 第6条","c":""},{"id":"2016-12","s":0,"q":"建築物環境衛生管理技術者免状について、誤っているものはどれか。","o":["免状の返納を命じられ、その日から1年を過ぎていない人には、免状が交付されない場合がある。","免状をなくしたときは、再交付を申請できる。","免状の交付を受けようとする人は、都道府県知事に申請書を出さなければならない。","免状の記載事項が変わったときは、書換え交付を申請できる。","免状をもつ人が建築物衛生法に違反したときは、免状の返納を命じられることがある。"],"a":2,"e":"免状は厚生労働大臣が交付するもので、申請書は厚生労働大臣に提出する。","l":"建築物衛生法 第7条、施行規則 第9条","c":""},{"id":"2016-13","s":0,"q":"建築物衛生法の事業の登録の対象になっている業種はどれか。","o":["建築物の浄化槽の清掃を行う事業(建築物浄化槽清掃業)","建築物の排水槽の清掃を行う事業(建築物排水槽清掃業)","建築物の空気調和設備の管理を行う事業(建築物空気調和設備管理業)","建築物の廃棄物処理を行う事業(建築物廃棄物処理業)","建築物の排水管の清掃を行う事業(建築物排水管清掃業)"],"a":4,"e":"登録の対象は、清掃業、空気環境測定業、空気調和用ダクト清掃業、飲料水水質検査業、飲料水貯水槽清掃業、排水管清掃業、ねずみ昆虫等防除業、環境衛生総合管理業の8業種である。","l":"建築物衛生法 第12条の2","c":""},{"id":"2016-14","s":0,"q":"国や地方公共団体が使う特定建築物について、誤っているものはどれか。","o":["特定建築物の届出が必要である。","建築物環境衛生管理基準が適用される。","都道府県知事等は、改善措置の勧告ができる。","都道府県知事等は、立入検査ができる。","都道府県知事等は、維持管理の記録の提出を求めることができる。"],"a":3,"e":"国や地方公共団体の特定建築物には、立入検査の規定は適用されない。","l":"建築物衛生法 第13条","c":""},{"id":"2016-16","s":0,"q":"地域保健法にもとづく保健所の業務として、正しいものはどれか。","o":["介護認定の審査を行う。","労働災害の報告の届け先である。","人口動態統計に関する業務を行っている。","特定健康診査の実施主体である。","国民健康保険に関する業務を行っている。"],"a":2,"e":"人口動態統計その他地域保健に関する統計は、保健所の事業である。","l":"地域保健法 第6条","c":""},{"id":"2016-17","s":0,"q":"学校保健安全法の学校環境衛生基準に定められていない検査項目はどれか。","o":["運動場の微小粒子状物質の濃度","水泳プールの水の水質","校舎内のネズミの生息状況","教室内の照度","教室内の騒音レベル"],"a":0,"e":"運動場の微小粒子状物質の濃度は、学校環境衛生基準の検査項目にない。","l":"学校環境衛生基準(学校保健安全法 第6条)","c":""},{"id":"2016-18","s":0,"q":"旅館業法第4条第1項の次の文の(ア)〜(ウ)に入る語句の組合せとして、正しいものはどれか。\n「営業者は、営業の施設について、( ア )、採光、照明、( イ )及び清潔その他宿泊者の( ウ )に必要な措置を講じなければならない。」","o":["ア 換気　イ 保湿　ウ 衛生","ア 換気　イ 防湿　ウ 衛生","ア 防音　イ 保湿　ウ 安全","ア 防音　イ 防湿　ウ 安全","ア 防音　イ 防湿　ウ 衛生"],"a":1,"e":"旅館業法第4条は「換気、採光、照明、防湿及び清潔その他宿泊者の衛生に必要な措置」を講じるよう定めている。","l":"旅館業法 第4条","c":""},{"id":"2016-19","s":0,"q":"環境基本法の大気の汚染に係る環境基準に定められていない物質はどれか。","o":["浮遊粒子状物質","一酸化炭素","二酸化炭素","二酸化窒素","光化学オキシダント"],"a":2,"e":"二酸化炭素には、大気の環境基準が定められていない。","l":"大気の汚染に係る環境基準(環境基本法 第16条)","c":""},{"id":"2016-21","s":1,"q":"健康に影響する環境要因のうち、「化学的要因」として最も不適当なものはどれか。","o":["二酸化炭素","粉じん","オゾン","硫黄酸化物","振動"],"a":4,"e":"振動は物理的要因に分類される。","l":"法令外","c":""},{"id":"2016-22","s":1,"q":"臓器系のはたらきについて、最も不適当なものはどれか。","o":["筋骨格系は、体の形づくりと運動を受け持つ。","感覚器系は、外からの刺激を受けて神経系に伝える。","腎臓・泌尿器系は、血液の中から老廃物などを尿として出す。","呼吸器系は、循環器系が運んできた全身からの酸素を体の外に出す。","消化器系は、栄養や水を取り入れ、体内で再合成と排泄を行う。"],"a":3,"e":"呼吸器系は、酸素を取り入れ、循環器系が全身から運んできた二酸化炭素を体の外に出す。","l":"法令外","c":""},{"id":"2016-23","s":1,"q":"体の機能の恒常性を乱す有害なストレッサーになりうる要因として、最も不適当なものはどれか。","o":["物理的な刺激","加齢","化学的な刺激","社会的な要因","精神的な要因"],"a":1,"e":"加齢は、外から加わる刺激(ストレッサー)ではなく、体の側の変化である。","l":"法令外","c":""},{"id":"2016-24","s":1,"q":"下の図は、気温と、体の各部位(顔・手・足・直腸)の温度および平均皮膚温との関係を示している。図のア〜オのうち、直腸温として最も適当なものはどれか。","o":["ア","イ","ウ","エ","オ"],"a":0,"e":"直腸温は体の内部の温度(核心温)で、外気温が変わってもほとんど変わらず、最も高い。図で気温に関係なく36℃あたりでほぼ一定のアが直腸温である。外気の影響を最も受けて大きく変わるオは足の温度にあたる。","l":"法令外","c":"","g":["img/2016-24.png"]},{"id":"2016-25","s":1,"q":"体の熱を逃がすはたらき(熱放散機能)として、最も適当な組合せはどれか。\nア 食べ物の代謝　イ 筋肉の緊張　ウ ふるえ　エ 皮膚の血管の拡張　オ 発汗","o":["アとイ","アとオ","イとウ","ウとエ","エとオ"],"a":4,"e":"皮膚の血管の拡張と発汗が熱を逃がすはたらきである。食べ物の代謝・筋肉の緊張・ふるえは熱をつくるはたらき。","l":"法令外","c":""},{"id":"2016-26","s":1,"q":"ヒトの温熱的な快適さに影響する因子として、最も不適当なものはどれか。","o":["代謝量","室内の相対湿度","室内の二酸化炭素濃度","性別の差","加齢"],"a":2,"e":"二酸化炭素濃度は空気の汚れの指標であり、温熱的な快適さを決める因子ではない。","l":"法令外","c":""},{"id":"2016-27","s":1,"q":"熱中症で起こる症状として、最も不適当なものはどれか。","o":["けいれん","失神","下痢・嘔吐","体温の低下","頭痛・めまい"],"a":3,"e":"熱中症では体温が上がる。体温の低下は熱中症の症状ではない。","l":"法令外","c":""},{"id":"2016-28","s":1,"q":"空気汚染物質と健康障害の組合せとして、最も不適当なものはどれか。","o":["オゾン ― 気道の粘膜への刺激","ホルムアルデヒド ― シックハウス症候群","ハウスダスト ― 喘息","たばこの煙 ― 慢性閉塞性肺疾患(COPD)","二酸化窒素 ― 過敏性肺炎"],"a":4,"e":"過敏性肺炎は、カビなどの有機物の粉じんを繰り返し吸い込むことで起こる病気であり、二酸化窒素による健康障害の組合せとしては不適当。","l":"法令外","c":""},{"id":"2016-29","s":1,"q":"建築物環境衛生管理基準のホルムアルデヒドの量の基準値として、正しいものはどれか。","o":["1mg/m³以下","0.5mg/m³以下","0.15mg/m³以下","0.1mg/m³以下","0.08mg/m³以下"],"a":3,"e":"ホルムアルデヒドの量は、空気1m³につき0.1mg以下とされている。","l":"建築物衛生法施行令 第2条第1号イ","c":""},{"id":"2016-30","s":1,"q":"浮遊粉じんについての次の文の(ア)(イ)に入る数値の組合せとして、最も適当なものはどれか。\n「粒径( ア )μm以下の粉じんは長い時間浮かんでいて、ヒトの気道に取りこまれる。特に肺に沈着して体に有害な影響を与えるのは、ふつう( イ )μm前後から下の大きさである。」","o":["ア 50　イ 10","ア 40　イ 10","ア 20　イ 5","ア 10　イ 5","ア 10　イ 1"],"a":4,"e":"粒径10μm以下の粉じんは長く浮遊して気道に入り、特に1μm前後以下のものが肺に沈着しやすい。","l":"法令外","c":""},{"id":"2016-31","s":1,"q":"アスベストが原因となる病気として、最も適当な組合せはどれか。\nア 悪性中皮腫　イ 過敏性肺炎　ウ 肺がん　エ 肺線維症　オ 気管支喘息","o":["アとイとウ","アとウとエ","アとエとオ","イとウとオ","イとエとオ"],"a":1,"e":"アスベストは、悪性中皮腫、肺がん、肺線維症(石綿肺)の原因になる。","l":"法令外","c":""},{"id":"2016-32","s":1,"q":"室内の空気環境について、最も不適当なものはどれか。","o":["良い室内空気環境を保つには、1人あたり10m³/h以上の換気量が必要である。","室内環境では、窒素による体への健康影響はない。","酸素欠乏症等防止規則では、酸素濃度18%未満を酸素欠乏と定めている。","二酸化炭素濃度は、室内空気の汚れや換気の総合的な指標として使われる。","窒素は、大気の約78%を占める。"],"a":0,"e":"良い室内空気環境を保つのに必要な換気量は、一般に1人あたり30m³/h以上とされている(2022年度問28でも「30m³/h以上」が正しい記述とされている)。","l":"法令外","c":""},{"id":"2016-33","s":1,"q":"一酸化炭素について、最も不適当なものはどれか。","o":["日本では、大気汚染物質としての濃度が増えている。","ヘモグロビンとの結びつきは、酸素より200倍以上強い。","石油や都市ガスなどが不完全燃焼したときに発生する。","においのない気体である。","血液中の一酸化炭素ヘモグロビンの濃度が5%未満なら、症状はみられない。"],"a":0,"e":"日本の大気中の一酸化炭素濃度は、自動車排出ガス対策などで減ってきており、増えてはいない。","l":"法令外","c":""},{"id":"2016-34","s":1,"q":"音について、最も不適当なものはどれか。","o":["1m離れた会話の声が55〜65dBのとき、騒音レベルが45dB以下なら、十分に聞きとれる。","聴覚の周波数特性で補正した尺度を、A特性音圧レベルという。","聞こえる範囲の上限の周波数は、約20kHzである。","年をとると、低い周波数から聴力が落ちる。","ヒトの耳が最も敏感な周波数は、4,000Hz付近である。"],"a":3,"e":"加齢による聴力の低下は、高い周波数の音から始まる。","l":"法令外","c":""},{"id":"2016-35","s":1,"q":"LED(発光ダイオード)の性質について、最も不適当なものはどれか。","o":["熱に強い","小さくて軽い","白色の光源として使える","指向性が強い","効率が高く、寿命が長い"],"a":0,"e":"LEDは熱に弱く、温度が高いと寿命や効率が落ちる(2020年度問35でも「熱に弱い」が正しい記述とされている)。","l":"法令外","c":""},{"id":"2016-36","s":1,"q":"VDT作業(情報機器作業)での目の疲れの対策について、最も不適当なものはどれか。","o":["キーボードの上の照度は、300lx以上にする。","ディスプレイの周りの視野の中の輝度を、ほぼ同じレベルにする。","ディスプレイ画面の照度を、800lx以下にする。","まぶしさ(グレア)を防ぐ照明器具を使う。","反射を防ぐタイプのディスプレイを使う。"],"a":2,"e":"ガイドラインでは、ディスプレイ画面上の照度は500lx以下とされている。","l":"法令外(情報機器作業における労働衛生管理のためのガイドライン)","c":""},{"id":"2016-37","s":1,"q":"紫外線の性質・はたらきとして、最も不適当なものはどれか。","o":["赤外線と比べて、皮膚を通り抜けやすい","皮膚の悪性黒色腫が起こる","電気性眼炎が起こる","ビタミンDがつくられる","殺菌作用"],"a":0,"e":"紫外線は皮膚の表面近くで吸収されるため、赤外線より皮膚を通り抜けにくい(2023年度問39でも「紫外線は皮膚表層で吸収される」が正しい記述とされている)。","l":"法令外","c":""},{"id":"2016-38","s":1,"q":"放射線の体への影響には早期影響と晩発影響がある。晩発影響として最も適当なものはどれか。","o":["不妊","皮膚の潰瘍","白血病","白血球の減少","脱毛"],"a":2,"e":"白血病は、被ばくから長い時間がたって現れる晩発影響である。不妊・皮膚潰瘍・白血球減少・脱毛は早期影響。","l":"法令外","c":""},{"id":"2016-39","s":1,"q":"健康な成人と水について、最も不適当なものはどれか。","o":["体内で食べ物が代謝されるときにできる代謝水は、1日約0.3Lである。","ふつうの食事と水分のとり方で、1日に1〜2Lの尿を出す。","老廃物を出すために必要な尿の量は、1日に0.1〜0.2Lである。","体重50kgの人の体内の水分量は、ふつう30kg前後である。","ヒトが生理的に1日に必要とする水分量は、約1.5Lである。"],"a":2,"e":"老廃物を出すために最低限必要な尿(不可避尿)の量は、1日約0.4〜0.5Lとされる。","l":"法令外","c":""},{"id":"2016-40","s":1,"q":"カドミウムについて、最も不適当なものはどれか。","o":["合金・塗料・電池などに使われる。","とりすぎると大脳にたまって、中枢神経の障害を起こす。","富山県神通川流域の環境汚染で、イタイイタイ病の原因となった。","水道法の水質基準の項目に含まれている。","水質汚濁防止法の、健康に関わる有害物質の排水基準の項目に含まれている。"],"a":1,"e":"カドミウムは主に腎臓にたまり、腎臓の障害や骨の障害(イタイイタイ病)を起こす。中枢神経の障害は水銀などの代表的な影響である。","l":"法令外","c":""},{"id":"2016-41","s":1,"q":"次の感染症のうち、細菌によって起こるものの組合せとして、正しいものはどれか。\nア 白癬症　イ レジオネラ症　ウ 結核　エ マラリア　オ 発疹チフス","o":["アとイ","アとオ","イとウ","ウとエ","エとオ"],"a":2,"e":"レジオネラ症と結核は細菌による。白癬症は真菌、マラリアは原虫、発疹チフスはリケッチアによる。","l":"法令外","c":""},{"id":"2016-42","s":1,"q":"食べ物や水が主な感染源となる感染症として、最も適当なものはどれか。","o":["デング熱","A型肝炎","インフルエンザ","梅毒","日本脳炎"],"a":1,"e":"A型肝炎は、ウイルスに汚染された食べ物や水を口にすることで感染する。デング熱と日本脳炎は蚊、インフルエンザは飛沫、梅毒は性的接触でうつる。","l":"法令外","c":""},{"id":"2016-43","s":1,"q":"次の感染症対策のうち、感受性対策(うつされる側の対策)として最も適当な組合せはどれか。\nア 患者の隔離　イ 手洗いの徹底　ウ 予防接種　エ 抵抗力を高めること　オ マスクの着用","o":["アとイ","アとオ","イとウ","ウとエ","エとオ"],"a":3,"e":"感受性対策は、うつされる側の免疫や抵抗力を高める対策で、予防接種と抵抗力の向上が当たる。患者の隔離は感染源対策、手洗いやマスクは感染経路対策。","l":"法令外","c":""},{"id":"2016-44","s":1,"q":"消毒と滅菌について、最も不適当なものはどれか。","o":["次亜塩素酸ナトリウムは、消毒する物に有機物が多く含まれるほど効き目が強くなる。","熱による滅菌の方法には、乾熱滅菌法や高圧蒸気滅菌法がある。","酸化エチレン(エチレンオキサイド)は、ガス滅菌に使われる。","放射線による滅菌では、X線やγ線が使われる。","消毒用エタノールは、芽胞と一部のウイルスには効かない。"],"a":0,"e":"次亜塩素酸ナトリウムは、有機物が多いと有機物と反応して消費されるため、効き目が弱くなる(2022年度問45でも同じ趣旨の記述が誤りとされている)。","l":"法令外","c":""},{"id":"2016-45","s":1,"q":"5%溶液として売られている次亜塩素酸ナトリウム50mLを水50Lに加えたとき、この溶液の次亜塩素酸ナトリウム濃度に最も近いものはどれか。","o":["25mg/L","50mg/L","100mg/L","500mg/L","1,000mg/L"],"a":1,"e":"有効成分は50mL×0.05=2.5mL(約2.5g=2,500mg)。これが50Lに溶けるので、2,500mg÷50L=50mg/L。","l":"法令外(計算)","c":""},{"id":"2016-46","s":2,"q":"熱と湿気の用語と単位の組合せのうち、誤っているものはどれか。","o":["比エンタルピー ― kJ/kg(DA)","水蒸気分圧 ― kPa","比容積 ― m³/kg(DA)","貫流熱流量 ― W/m²","熱伝導抵抗 ― m・K/W"],"a":4,"e":"熱伝導抵抗は、厚さ÷熱伝導率で求めるので単位はm²・K/W(2025年度問47の計算参照)。m・K/Wは熱伝導率の逆数の単位である。","l":"法令外","c":""},{"id":"2016-47","s":2,"q":"下の図は、建築材料表面(白色ペイント、黒色ペイント、酸化した亜鉛鉄板、光ったアルミ箔)の長波長放射率と日射吸収率の関係を示している。A〜Dの組合せとして、最も適当なものはどれか。","o":["A 光ったアルミ箔/B 白色ペイント/C 酸化した亜鉛鉄板/D 黒色ペイント","A 光ったアルミ箔/B 酸化した亜鉛鉄板/C 白色ペイント/D 黒色ペイント","A 酸化した亜鉛鉄板/B 光ったアルミ箔/C 黒色ペイント/D 白色ペイント","A 白色ペイント/B 酸化した亜鉛鉄板/C 光ったアルミ箔/D 黒色ペイント","A 白色ペイント/B 光ったアルミ箔/C 黒色ペイント/D 酸化した亜鉛鉄板"],"a":4,"e":"白色ペイントは日射をあまり吸収しないが長波長はよく放射する(A)。光ったアルミ箔はどちらも小さい(B)。黒色ペイントはどちらも大きい(C)。酸化した亜鉛鉄板は日射吸収率が大きく、長波長放射率は小さめ(D)。","l":"法令外","c":"","g":["img/2016-47.png"]},{"id":"2016-48","s":2,"q":"下の図は、厚さの異なるA、B、C部材で構成された建築物外壁における定常状態の内部温度分布を示している。この図に関する次の記述のうち、最も不適当なものはどれか。","o":["B部材の方がC部材より熱伝導率は大きい。","熱伝達率は、屋外側の方が室内側より大きい。","B部材が主体構造体であるとすれば、この図は外断熱構造を示している。","A部材とB部材を流れる単位面積当たりの熱流量は等しい。","壁表面近傍で温度が急激に変化する部分を境界層という。"],"a":2,"e":"温度が大きく下がっているC部材(室内側)が断熱材。断熱材が主体構造体Bの室内側にあるので内断熱構造であり、外断熱ではない。","l":"法令外","c":"","g":["img/2016-48.png"]},{"id":"2016-49","s":2,"q":"下に示す湿り空気線図に関する次の記述のうち、最も不適当なものはどれか。","o":["乾球温度14℃、相対湿度50%の空気を伝熱ヒーターで29℃に温めると相対湿度は約20%となる。","乾球温度10℃、相対湿度50%の空気は、乾球温度30℃、相対湿度10%の空気より絶対湿度が高い。","露点温度14℃の空気は、乾球温度25℃において約60%の相対湿度となる。","乾球温度21℃の空気が含むことのできる最大の水蒸気量は、0.015kg/kg(DA)より大きい。","乾球温度22℃、相対湿度60%の空気が表面温度13℃の窓ガラスに触れると結露する。"],"a":2,"e":"露点14℃の空気の絶対湿度は約0.010kg/kg(DA)。25℃の飽和絶対湿度は約0.020なので、相対湿度は約50%になり、60%ではない。","l":"法令外","c":"","g":["img/2016-49.png"]},{"id":"2016-50","s":2,"q":"浮遊粒子の動きにかかわる性質のうち、粒径が大きくなるほど値が大きくなるものとして、最も適当なものはどれか。","o":["終末沈降速度","荷電数が同じ粒子の電気移動度","拡散係数","水平ダクトでの鉛直面への沈着速度","ブラウン運動による移動量"],"a":0,"e":"終末沈降速度は粒径の2乗に比例して大きくなる(2020年度問59)。電気移動度・拡散係数・拡散による沈着・ブラウン運動は、小さい粒子ほど大きい。","l":"法令外","c":""},{"id":"2016-51","s":2,"q":"流体について述べた次の文のうち、最も不適当なものはどれか。","o":["流体の粘性力に対する慣性力の比を表す無次元数がレイノルズ数である。","直線ダクトの圧力損失は、風速の2乗に比例する。","開口部を通る風量は、開口部前後の圧力差の2乗に比例して増える。","ベルヌーイの定理は、流れの力学的エネルギーが保存されるという仮定から導かれる。","無秩序な乱れによって流体のかたまりが混ざり合う流れを乱流という。"],"a":2,"e":"開口部を通る風量は、圧力差の平方根に比例する(2022年度問51でも正しい記述)。","l":"法令外","c":""},{"id":"2016-52","s":2,"q":"空気の流れについて述べた次の文のうち、最も不適当なものはどれか。","o":["天井面に沿った噴流の到達距離は、自由噴流より長くなる。","天井面に沿って流れる暖かい気流は、速度が弱いと途中ではがれて下に降りることがある。","吹出しの影響は遠くまで及ぶが、吸込みの影響は吸込口の近くに限られる。","流量係数が最も大きい開口部の形はベルマウスで、約1.0になる。","自由噴流の第3域では、中心軸速度が吹出口からの距離に反比例して小さくなる。"],"a":1,"e":"暖かい空気は軽く上に向かうので、天井からはがれて下に降りるのは冷たい気流の場合である(2021年度問50でも冷房の噴流として正しい記述)。","l":"法令外","c":""},{"id":"2016-53","s":2,"q":"自然換気の換気力について述べた次の文のうち、最も不適当なものはどれか。","o":["温度差による換気力は、室内外の空気の密度差に比例して大きくなる。","温度差による換気力は、給気口と排気口の高さの差の2乗に比例して大きくなる。","風力による換気力は、風圧係数に比例して大きくなる。","風力による換気力は、外の風速の2乗に比例して大きくなる。","開口部の風圧係数は、正と負の値をとる。"],"a":1,"e":"温度差による換気力は、開口部の高さの差に比例する(2025年度問51でも正しい記述)。2乗ではない。","l":"法令外","c":""},{"id":"2016-54","s":2,"q":"東京都の建築物環境衛生管理基準にかかわる空気環境の測定結果について、次の文が表す項目として最も適当なものはどれか。\n「建築物衛生法の施行時から平成10年度までの不適率は10〜20%だったが、近年は30%前後で推移しており、不適率がだんだん増える傾向が見られる。」","o":["温度","相対湿度","二酸化炭素の含有率","浮遊粉じんの量","気流"],"a":2,"e":"二酸化炭素の不適率は、施行当時10〜20%台で(2024年度問57でも正しい記述)、近年は省エネのための外気量削減などで増える傾向にある。","l":"法令外","c":""},{"id":"2016-55","s":2,"q":"エアロゾル粒子と、その測定される粒径の組合せとして、最も適当なものはどれか。","o":["細菌 ― 0.01μm","ウイルス ― 5.0μm","たばこ煙 ― 10μm","花粉(スギ) ― 30μm","雨滴(霧雨) ― 50μm"],"a":3,"e":"スギ花粉は30μm程度である(花粉は10〜100μm程度。2020年度問145で正答)。細菌は1μm前後で、ウイルスやたばこ煙はもっと小さい。","l":"法令外","c":""},{"id":"2016-56","s":2,"q":"空気汚染物質の特徴を示した次のア〜エのうち、オゾンの特徴にあたるものの組合せとして最も適当なものはどれか。\nア 常温で独特の刺激臭がある不安定な気体である。\nイ 一酸化窒素と結びつき、二酸化窒素と酸素をつくる。\nウ 人為的な発生源には、自動車の排気ガスや燃焼器具から出るものがある。\nエ 比較的分子の小さい有機化合物である。","o":["アとイ","アとウ","イとウ","イとエ","ウとエ"],"a":0,"e":"オゾンは刺激臭のある不安定な気体で(2025年度問55)、一酸化窒素と反応して二酸化窒素と酸素になる。有機化合物ではない。","l":"法令外","c":""},{"id":"2016-57","s":2,"q":"室容積500m³の居室が換気回数1.0回/hで換気されている。汚染物質が一定量ずつ発生しており、初期濃度0.01mg/m³が1時間後に0.02mg/m³に増えた。このときの汚染物質の発生量に最も近いものはどれか。室内は完全混合、外気濃度は0.01mg/m³、e＝2.7とし、室内濃度は次の式で表される。\nC＝C0＋(Cs－C0)×1/e^(nt)＋(M/Q)×(1－1/e^(nt))\n(C:室内濃度、Cs:初期濃度、C0:外気濃度[mg/m³]、M:発生量[mg/h]、Q:換気量[m³/h]、n:換気回数[回/h]、t:時間[h])","o":["3mg/h","5mg/h","8mg/h","13mg/h","16mg/h"],"a":2,"e":"Q＝500×1.0＝500m³/h、nt＝1。Cs＝C0なので第2項は0。0.02＝0.01＋(M/500)×(1－1/2.7)＝0.01＋M/500×0.63。M＝0.01×500÷0.63≒7.9≒8mg/h。","l":"計算","c":""},{"id":"2016-58","s":2,"q":"次の室内の汚染物質のうち、石油の燃焼で発生しないものはどれか。","o":["浮遊粉じん","アスベスト","硫黄酸化物","窒素酸化物","一酸化炭素"],"a":1,"e":"アスベストは天然の鉱物繊維で、断熱材などの建材から出るもの(2016年度問60参照)。燃焼で発生するものではない。","l":"法令外","c":""},{"id":"2016-59","s":2,"q":"放射線は非電離放射線と電離放射線に分けられる。非電離放射線に含まれるものはどれか。","o":["紫外線","γ線","α線","中性子線","エックス線"],"a":0,"e":"紫外線は非電離放射線。γ線・α線・中性子線・エックス線は電離放射線である(2024年度問55参照)。","l":"法令外","c":""},{"id":"2016-60","s":2,"q":"室内空気汚染物質と発生源の組合せとして、最も不適当なものはどれか。","o":["臭気 ― 喫煙","キシレン ― 塗料の溶剤","クリソタイル ― 断熱材の除去工事","ラドン ― 土壌・岩石","アスペルギルス ― 防虫剤"],"a":4,"e":"アスペルギルスはカビの一種で(2024年度問54)、湿気の多い場所などで増える。防虫剤から出るものではない。","l":"法令外","c":""},{"id":"2016-61","s":2,"q":"アレルゲンと微生物について述べた次の文のうち、最も不適当なものはどれか。","o":["住まいのおもなダニアレルゲンは、ヒョウヒダニ類のふんと虫体である。","カビアレルゲンの大部分は、ナノサイズの粒子である。","黒カビは、結露した壁などの表面で増える。","疫学調査で、カビと子どもの呼吸器の病気の間に有意な関係があることがわかっている。","オフィス内の浮遊細菌濃度には、エアフィルタの捕集率が関係する。"],"a":1,"e":"カビアレルゲンの大部分は数μm以上の粒子である(2021年度問58でも正しい記述)。ナノサイズではない。","l":"法令外","c":""},{"id":"2016-62","s":2,"q":"湿り空気の混合についての次の文の[ア]・[イ]に入る数値の組合せとして、最も適当なものはどれか。\n「A点は乾球温度26℃・絶対湿度0.013kg/kg(DA)、B点は乾球温度34℃・絶対湿度0.025kg/kg(DA)である。A点の空気300kg/hとB点の空気100kg/hを混ぜた空気は、乾球温度[ア]℃、絶対湿度[イ]kg/kg(DA)である。」","o":["ア 28/イ 0.016","ア 28/イ 0.019","ア 30/イ 0.019","ア 32/イ 0.016","ア 32/イ 0.022"],"a":0,"e":"質量の割合による加重平均。温度＝(300×26＋100×34)÷400＝11,200÷400＝28℃。絶対湿度＝(300×0.013＋100×0.025)÷400＝6.4÷400＝0.016kg/kg(DA)。","l":"計算","c":""},{"id":"2016-63","s":2,"q":"熱負荷計算での負荷の種類と、その設定条件の単位の組合せとして、最も不適当なものはどれか。","o":["外気 ― L/(m³・s)","在室者 ― 人/m²","照明 ― W/m²","すき間風 ― 回/h","構造体 ― W/(m²・K)"],"a":0,"e":"この組合せが誤り。外気量は時間あたりの風量(m³/hなど)で設定するもので、L/(m³・s)は外気の条件を表す単位として成り立たない。","l":"法令外","c":""},{"id":"2016-64","s":2,"q":"空調の熱負荷について述べた次の文のうち、最も不適当なものはどれか。","o":["装置蓄熱負荷は、熱源負荷に含まれる。","送風機による負荷は、空調機負荷に含まれる。","地面に接する床の構造体負荷は、一般に冷房時には無視する。","外気負荷では、一般に潜熱負荷を無視する。","人体負荷には、顕熱負荷と潜熱負荷がある。"],"a":3,"e":"外気には水蒸気が含まれるので、外気負荷には潜熱負荷もあり無視しない(2024年度問61で正答)。","l":"法令外","c":""},{"id":"2016-65","s":2,"q":"次の空調設備のうち、個別方式にあたらないものはどれか。","o":["ターミナルエアハンドリングユニット","空気熱源ヒートポンプパッケージ","ウォールスルー型ユニット","水熱源ヒートポンプパッケージ","ビル用マルチパッケージ"],"a":0,"e":"ターミナルエアハンドリングユニットは、熱源設備から冷温水を受けて使う中央方式の機器である(2025年度問64でも同じ内容が正答)。","l":"法令外","c":""},{"id":"2016-66","s":2,"q":"ヒートポンプ方式について述べた次の文のうち、最も不適当なものはどれか。","o":["1台で温熱源と冷熱源を兼ねられる。","冷水と温水を同時に取り出せる機種がある。","水熱源方式は、空気熱源方式より一般に成績係数が高い。","電動冷凍機＋ボイラ方式より、夏と冬の電力消費の差を小さくできる。","空気熱源方式より、水熱源方式の方が多く使われている。"],"a":4,"e":"多く使われているのは空気熱源方式の方である(2025年度問65でも同じ内容が正答)。","l":"法令外","c":""},{"id":"2016-67","s":2,"q":"蒸気圧縮冷凍サイクルについて述べた次の文のうち、最も不適当なものはどれか。","o":["圧縮機で、冷媒の比エンタルピーが増える。","凝縮器で、冷媒が液体になる。","凝縮器で、冷媒の圧力が上がる。","膨張弁で、冷媒の圧力が下がる。","蒸発器で、冷媒が気体になる。"],"a":2,"e":"冷媒の圧力を上げるのは圧縮機である。凝縮器では圧力はほぼ一定のまま、熱を捨てて液体になる(2024年度問67参照)。","l":"法令外","c":""},{"id":"2016-68","s":2,"q":"下の図は、吸収冷凍機の冷凍サイクルを示したものである。図中のA、B、Cに対応する蒸気、冷水、冷却水の組合せとして、最も適当なものはどれか。","o":["蒸気 A/冷水 B/冷却水 C","蒸気 A/冷水 C/冷却水 B","蒸気 B/冷水 A/冷却水 C","蒸気 B/冷水 C/冷却水 A","蒸気 C/冷水 B/冷却水 A"],"a":3,"e":"再生器(B)には溶液を加熱する蒸気が入る。凝縮器(A)には冷媒を冷やして液にする冷却水が通る。蒸発器(C)では冷媒の蒸発で冷水がつくられる。","l":"法令外","c":"","g":["img/2016-68.png"]},{"id":"2016-69","s":2,"q":"空気調和設備の温熱源について述べた次の文のうち、最も不適当なものはどれか。","o":["鋳鉄製ボイラは、鋳鉄製のセクション内部の清掃が難しい。","炉筒煙管ボイラは、洗浄・消毒などに高圧蒸気が必要な病院・ホテルなどで多く採用されている。","貫流ボイラは、蒸気を熱媒としている。","真空式温水発生機は、高温水を熱媒としている。","水管ボイラは、蒸気を熱媒としている。"],"a":3,"e":"真空式温水発生機は、缶体内を真空に保って低い温度で水を沸騰させ、熱交換器で温水をつくる機器である(2023年度問65)。高温水を熱媒とするものではない。","l":"法令外","c":""},{"id":"2016-70","s":2,"q":"空気調和機について述べた次の文のうち、最も不適当なものはどれか。","o":["エアハンドリングユニットは、冷却・加熱のための熱源を内蔵している。","エアハンドリングユニットは、使う目的に合わせて構成機器の組合せを変えられる。","ファンコイルユニットは、ダクト併用ファンコイルユニット方式の端末ユニットとして使われる。","ファンコイルユニットには、設置方法によって床置き型や天吊り型などの種類がある。","パッケージ型空気調和機は、蒸気圧縮冷凍サイクルの機器でできている。"],"a":0,"e":"エアハンドリングユニットは熱源を内蔵せず、熱源設備から送られる冷温水などを使う(2021年度問71で同じ内容が正答)。","l":"法令外","c":""},{"id":"2016-71","s":2,"q":"空気調和設備での湿度調整について述べた次の文のうち、最も不適当なものはどれか。","o":["加湿装置は、おもに暖房時に使う。","湿度調整は、有害な微生物の発生や感染の防止に役立つ。","加湿装置の維持管理が不十分だと、装置の中で微生物が増えることがある。","水噴霧式の加湿装置には、温度が下がらないという特長がある。","除湿には、冷却減湿法や化学的減湿法がある。"],"a":3,"e":"水噴霧式は水が蒸発するときに熱を奪うので、空気の温度が下がる(2025年度問72でも正しい記述)。温度が下がらないのは蒸気式である。","l":"法令外","c":""},{"id":"2016-72","s":2,"q":"空気調和設備の送風機の特性と送風系についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「送風機の特性曲線は、横軸に[ア]、縦軸に[イ]をとって示す。送風系の[ウ]曲線は、同じグラフ上で原点を通る二次曲線として示され、2つの曲線の交点が運転点になる。」","o":["ア 静圧/イ 風量/ウ 抵抗","ア 動力/イ 静圧/ウ 性能","ア 動力/イ 風量/ウ 静圧","ア 風量/イ 静圧/ウ 抵抗","ア 風量/イ 動力/ウ 性能"],"a":3,"e":"特性曲線は横軸に風量、縦軸に静圧(圧力)をとり、ダクト系の抵抗曲線は原点を通る二次曲線になる(2024年度問72で同じ内容が正答)。","l":"法令外","c":""},{"id":"2016-73","s":2,"q":"ダクト系に関係する用語として、最も不適当なものはどれか。","o":["フレキシブル継手","たわみ継手","キャビテーション","多翼型ダンパ","混合ユニット"],"a":2,"e":"キャビテーションは、ポンプなどで液体の圧力が下がって気泡ができる現象で(2024年度問74)、空気を送るダクト系の用語ではない。","l":"法令外","c":""},{"id":"2016-74","s":2,"q":"ダクトと付属品について述べた次の文のうち、最も不適当なものはどれか。","o":["ダクトの材料には、用途によって亜鉛鉄板、塩化ビニル被覆鋼板、ステンレス鋼板などが使われる。","ダクト系には、風量調整ダンパのほか、防火ダンパや防煙ダンパが使われる。","グラスウールダクトには消音効果がある。","ダクトの形には、角ダクトのほか丸ダクトがある。","防火ダンパは、煙感知器と連動して流路を閉じる。"],"a":4,"e":"煙感知器と連動して閉じるのは防煙ダンパ(2017年度問73でも正しい記述)。防火ダンパは温度ヒューズが熱で溶けて閉じる。","l":"法令外","c":""},{"id":"2016-75","s":2,"q":"空気浄化装置について述べた次の文のうち、最も不適当なものはどれか。","o":["自動巻取型エアフィルタのろ材には、合成繊維やガラス繊維が使われている。","ガス除去用フィルタは、使っても圧力損失の変化が、一般のエアフィルタより小さい。","ガス除去用フィルタには、シリカゲルを使うものがある。","HEPAフィルタの圧力損失は、一般空調用フィルタより小さい。","ろ過式フィルタは、適切な時期に交換しないと、とらえた粉じんが再び飛び散ることがある。"],"a":3,"e":"HEPAフィルタはろ材の目が細かいため、一般空調用フィルタより圧力損失が大きい(2021年度問75で同じ内容が正答)。","l":"法令外","c":""},{"id":"2016-76","s":2,"q":"ポンプについて述べた次の文のうち、最も不適当なものはどれか。","o":["サージングが起きるかどうかの判断には、有効吸込みヘッド(NPSH)を使う。","ダイヤフラムポンプは、容積型に分類される。","全揚程は、損失水頭と実揚程の和である。","渦流ポンプは、小水量で高揚程なのが特徴である。","渦巻きポンプは、ターボ型に分類される。"],"a":0,"e":"有効吸込みヘッド(NPSH)はキャビテーションが起きないかを判断する指標である(2022年度問77・2017年度問76参照)。","l":"法令外","c":""},{"id":"2016-77","s":2,"q":"空気調和設備の配管の種類と、関係する温度または圧力の組合せとして、最も不適当なものはどれか。","o":["高温水配管 ― 80〜90℃","冷却水配管 ― 20〜40℃","冷水配管 ― 5〜10℃","高圧蒸気配管 ― 0.1〜1MPa","低圧蒸気配管 ― 0.01〜0.05MPa"],"a":0,"e":"80〜90℃程度は温水の範囲で、高温水は100℃を超える水を指す(2022年度問76で同じ内容が正答)。","l":"法令外","c":""},{"id":"2016-78","s":2,"q":"空調設備の配管材料と使い道の組合せとして、最も不適当なものはどれか。","o":["配管用炭素鋼鋼管(白管) ― 冷温水","配管用炭素鋼鋼管(黒管) ― 油","フランジ付硬質塩化ビニルライニング鋼管 ― 冷却水","硬質ポリ塩化ビニル管 ― 蒸気","配管用ステンレス鋼管 ― 蒸気還管"],"a":3,"e":"硬質ポリ塩化ビニル管は熱に弱く、高温の蒸気には使えない(2024年度問75参照)。","l":"法令外","c":""},{"id":"2016-79","s":2,"q":"換気について述べた次の文のうち、最も不適当なものはどれか。","o":["排気フードは、局所換気に使われる。","ハイブリッド換気は、自然換気に機械換気や空調設備を補助的に組み合わせたものである。","第1種機械換気では、室内の圧力を正圧にも負圧にも設定できる。","第3種機械換気は、給気口と排風機でできている。","感染症室などの汚染室の換気では、室内の圧力を周りより高くする。"],"a":4,"e":"汚染室は汚れた空気が周りに漏れないよう、室内の圧力を周りより低く(負圧に)する(2020年度問52参照)。","l":"法令外","c":""},{"id":"2016-80","s":2,"q":"温熱環境の測定器について述べた次の文のうち、最も不適当なものはどれか。","o":["温度の測定には、金属の膨張を利用する方法がある。","熱線風速計には、定電圧式と定温度式がある。","アウグスト乾湿計の乾球温度は、一般に湿球温度より高い値を示す。","グローブ温度計の値は、平均放射温度(MRT)と反比例の関係にある。","相対湿度の測定器には、電気抵抗を利用するものがある。"],"a":3,"e":"この記述が誤り。周りの壁などの温度(平均放射温度)が高いほどグローブ温度も高くなるので、反比例の関係ではない。","l":"法令外","c":""},{"id":"2016-81","s":2,"q":"浮遊粉じんの測定法と測定器について述べた次の文のうち、最も不適当なものはどれか。","o":["浮遊粉じんの測定法には、捕集測定法と浮遊測定法がある。","散乱光法は、浮遊粉じんの浮遊測定法の一つである。","デジタル粉じん計は、粉じんによる散乱光の波長から相対濃度を測る。","建築物環境衛生管理基準にもとづきローボリウムエアサンプラ法を使うときは、分粒装置を付ける必要がある。","デジタル粉じん計の受光部などは経年劣化するので、定期的に較正する。"],"a":2,"e":"デジタル粉じん計は、散乱光の強さ(量)から相対濃度を測る(2023年度問77で同じ内容が正答)。","l":"法令外","c":""},{"id":"2016-82","s":2,"q":"汚染物質と、その濃度または強さを表す単位の組合せとして、最も不適当なものはどれか。","o":["パラジクロロベンゼン ― μg/m³","放射性物質 ― Sv","浮遊細菌 ― CFU/m³","アスベスト ― f/cm³","二酸化硫黄 ― ppb"],"a":1,"e":"放射性物質の強さ(放射能)の単位はBq(ベクレル)である(2025年度問79・2017年度問84)。Sv(シーベルト)は人が受ける放射線の影響の大きさを表す単位。","l":"法令外","c":""},{"id":"2016-83","s":2,"q":"環境要素と測定法の組合せとして、最も不適当なものはどれか。","o":["ダニアレルゲン ― エライザ(ELISA)法","オゾン ― 検知管法","微生物 ― ザルツマン法","アスベスト ― 光学顕微鏡法","二酸化炭素 ― 非分散型赤外線吸収法"],"a":2,"e":"ザルツマン法は窒素酸化物の測定法である(2020年度問80でも正しい組合せ)。","l":"法令外","c":""},{"id":"2016-84","s":2,"q":"空気調和・換気設備の維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["空調用ダクトは、年数がたつにつれて内部の清掃を考える。","空気調和・換気設備に関係する健康障害には微生物によるものがあり、ビル関連病(BRI)に代表される。","建築物環境衛生管理基準では、加湿装置は使用開始時と使用期間中の3か月以内ごとに1回、定期に汚れの状況を点検する。","冷却塔に供給する水は、水道法の水質基準に適合していることが求められる。","建築物環境衛生管理基準では、冷却塔は1年以内ごとに1回、定期に清掃する。"],"a":2,"e":"加湿装置の汚れの点検は、使用開始時と使用開始後1か月以内ごとに1回(施行規則第3条の18第3号)。冷却塔の清掃1年以内ごと、供給水の水質基準も同条のとおり。","l":"建築物衛生法施行規則 第3条の18","c":""},{"id":"2016-85","s":2,"q":"夏のピーク時の空気調和設備の節電対策について述べた次の文のうち、最も不適当なものはどれか。","o":["冷凍機の冷却水の入口温度を下げる。","空気調和機のエアフィルタを清掃する。","熱源機の熱交換器を洗浄する。","ヒートポンプ屋外機の熱交換器に散水する。","冷凍機の冷水の出口温度を下げる。"],"a":4,"e":"冷水の出口温度を下げると、冷凍機はより低い温度をつくるために多くの電力を使うので、節電にはならない。節電には冷水温度を上げる方向で調整する。","l":"法令外","c":""},{"id":"2016-86","s":2,"q":"音の用語の説明として、最も不適当なものはどれか。","o":["暗騒音 ― ある騒音環境で、対象とする特定の音以外の音の総称","吸音率 ― 入ってきた音のエネルギーに対する、透過したエネルギーの割合","純音 ― 1つの周波数だけでできた音波","拡散音場 ― 空間に音のエネルギーが一様に分布し、音があらゆる方向に伝わっている状態","遮音 ― 壁などで音をさえぎり、通り抜ける音のエネルギーを小さくすること"],"a":1,"e":"透過したエネルギーの割合は透過率。吸音率は、入ってきた音のうち反射されなかった(吸収と透過を合わせた)エネルギーの割合である(2021年度問85参照)。","l":"法令外","c":""},{"id":"2016-87","s":2,"q":"上階で発生させた軽量床衝撃音の床衝撃音レベルを下室で周波数ごとに測定した結果、63Hzで78dB、125Hzで75dB、250Hzで75dB、500Hzで73dB、1,000Hzで67dB、2,000Hzで64dB、4,000Hzで64dBであった。この床の遮音等級として、最も適当なものはどれか。下の図の遮音等級の基準周波数特性を用いて求めよ。","o":["Lr-75","Lr-70","Lr-65","Lr-60","Lr-55"],"a":0,"e":"すべての周波数で測定値が基準曲線以下になる、いちばん小さい等級を選ぶ。500Hzの73dBはLr-70の曲線(70dB)を超えるが、Lr-75の曲線(75dB)以下で、ほかの周波数もLr-75以下に収まる。よってLr-75。","l":"法令外","c":"","g":["img/2016-87.png"]},{"id":"2016-88","s":2,"q":"騒音・振動問題の対策について述べた次の文のうち、最も不適当なものはどれか。","o":["固体伝搬音を減らすには、振動源の振動を減らすことや防振対策が重要である。","外部騒音が同じなら、コンサートホールやオペラハウスの方が録音スタジオより高い遮音性能が求められる。","空気伝搬音を減らすには、窓・壁・床などを遮音する必要がある。","設備機器などの振動が建物の躯体を伝わって居室の内装材から出る音は、固体伝搬音である。","寝室の騒音では、骨伝導で感じる固体伝搬音も確かめるため、立った姿勢・座った姿勢・寝た姿勢で評価する。"],"a":1,"e":"わずかな雑音も録音されてしまう録音スタジオの方が、高い遮音性能が求められる(2023年度問86で同じ内容が正答)。","l":"法令外","c":""},{"id":"2016-89","s":2,"q":"地表で直射日光による法線面照度が90,000lxのとき、直射日光による水平面照度に最も近いものはどれか。ただし太陽高度は30度とする。","o":["23,800lx","30,000lx","39,000lx","45,000lx","78,000lx"],"a":3,"e":"水平面照度＝法線面照度×sin(太陽高度)＝90,000×sin30°＝90,000×0.5＝45,000lx。","l":"計算","c":""},{"id":"2016-90","s":2,"q":"照明器具の光源の交換方式についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「点灯しなくなった光源をそのつど交換する[ア]は、小規模な照明施設や交換しやすい場所に向くが、光源が切れる時期がばらばらなので交換の回数が多くなり、保守にかかる[イ]がかさむ。一方、大規模で交換が比較的難しい場所では、あらかじめ決めた交換時期に全数を交換する[ウ]で交換することがある。」","o":["ア 個別交換方式/イ 人件費/ウ 集団的個別交換方式","ア 個別交換方式/イ 人件費/ウ 集団交換方式","ア 個別交換方式/イ 部品費/ウ 集団交換方式","ア 個別的集団交換方式/イ 人件費/ウ 集団的個別交換方式","ア 個別的集団交換方式/イ 部品費/ウ 集団的個別交換方式"],"a":1,"e":"切れたらそのつど替えるのが個別交換方式で、何度も作業に行くため人件費がかさむ。時期を決めて全部替えるのが集団交換方式(2024年度問90参照)。","l":"法令外","c":""},{"id":"2016-91","s":3,"q":"建築物と都市環境について、最も不適当なものはどれか。","o":["両側を高い建物で連続して囲まれた道路空間は、半分閉じた空間のようになるので、ストリートキャニオンと呼ばれる。","熱容量が大きい材料は、日射の熱をためこみにくい。","地盤沈下は、典型7公害の一つである。","都市化によって都市の中心部の気温が郊外より高くなる現象を、ヒートアイランド現象という。","無計画な開発などで市街地が広がることを、スプロール現象という。"],"a":1,"e":"熱容量が大きい材料は、日射の熱をためこみやすい(2023年度問92でも「蓄熱しやすい」が正しい記述とされている)。","l":"法令外","c":""},{"id":"2016-92","s":3,"q":"建物の設計・施工での実施設計図書として、最も不適当なものはどれか。","o":["建築構造図","電気設備図","維持管理書","給排水衛生設備図","標準仕様書"],"a":2,"e":"実施設計図書は、工事に必要な設計図と仕様書であり、維持管理書は含まれない。","l":"建築士法 第2条第6項","c":""},{"id":"2016-93","s":3,"q":"建築計画と建築士法について、最も不適当なものはどれか。","o":["一級建築士は、建築士法にもとづき、国土交通大臣の免許を受ける資格である。","二級建築士は、建築士法にもとづき、都道府県知事の免許を受ける資格である。","建築士法により、一定規模の建物の設備設計では、建築設備士が設備関係規定に合っているかの確認をしなければならない。","貸事務所で、収益を生む部分の床面積を延べ面積で割ったものを、レンタブル比という。","建物の共用スペース・設備スペース・構造用の耐力壁などをまとめた区画を、コアという。"],"a":2,"e":"一定規模以上の建物の設備関係規定への適合性の確認が義務づけられているのは、設備設計一級建築士である。建築設備士は建築士に意見を述べる立場。","l":"建築士法 第20条の3","c":""},{"id":"2016-94","s":3,"q":"鉄筋コンクリート構造とその材料について、最も不適当なものはどれか。","o":["柱の主筋は4本以上とし、主筋に直角になるように帯筋を配筋する。","直接土に接しない柱や梁では、鉄筋に対するコンクリートのかぶり厚さを3cm以上にしなければならない。","構造耐力上主要な部分の梁は、圧縮側と引張側の両方に主筋を入れた複筋梁にする。","鉄筋とコンクリートの線膨張係数は、ほぼ等しい。","鉄筋に対するコンクリートのかぶり厚さとは、コンクリートの表面から鉄筋の中心までの距離をいう。"],"a":4,"e":"かぶり厚さは、コンクリートの表面から、いちばん外側にある鉄筋の表面までの距離をいう。鉄筋の中心までではない。","l":"建築基準法施行令 第79条","c":""},{"id":"2016-95","s":3,"q":"鉄骨構造とその鋼材について、最も不適当なものはどれか。","o":["鋼材の強さは温度が上がると下がり、1,000℃ではほとんど0になる。","梁に使うH形鋼のウェブは、主にせん断力に抵抗する。","デッキプレートは波形の薄い鋼板で、床の下地に使われる。","鋼材の耐火被覆の工法には、吹付け工法・巻付け工法・成形板張り工法などがある。","高力ボルト摩擦接合は、材と材の間の引張力によって力を伝える。"],"a":4,"e":"高力ボルト摩擦接合は、ボルトを強く締め付けて材と材を押しつけ(材間圧縮力)、そこに生じる摩擦力で力を伝える。","l":"法令外","c":""},{"id":"2016-96","s":3,"q":"構造計画と構造設計について、最も不適当なものはどれか。","o":["水平ブレースは、床面や屋根面のような水平の構面に入れる斜めの材である。","偏心率は、建物の平面的なバランスに関する規定である。","積雪地帯の吹きだまりとは、風に吹かれてできる局所的な積雪をいう。","層間変形角は、各階の高さを、その層の層間変位で割った値である。","擁壁は、土の圧力に抵抗して、盛土や切土の斜面を支える壁の構造物である。"],"a":3,"e":"層間変形角は、層間変位を各階の高さで割った値である(割る数と割られる数が逆)。","l":"法令外","c":""},{"id":"2016-97","s":3,"q":"建築材料と部材の性質について、最も不適当なものはどれか。","o":["鉄筋コンクリート構造の陸屋根は、屋根の勾配がとてもゆるいか、水平なものをいう。","2枚の板ガラスを一定の間をあけて密封したものは、複層ガラスである。","モルタルは、水とセメントを練り混ぜたものである。","内壁の仕上げ材料には、音を吸う性質や、質感(テクスチャ)の良さなどが求められる。","コンクリートの性質を良くするためのものとして、混和材料がある。"],"a":2,"e":"モルタルは、水・セメント・砂を練り混ぜたものである。水とセメントだけのものはセメントペースト。","l":"法令外","c":""},{"id":"2016-98","s":3,"q":"建築材料について、最も不適当なものはどれか。","o":["合板は、薄い板を、繊維の方向がたがいに交わるように接着剤で重ね合わせたものである。","板ガラスは、不燃材料である。","高流動コンクリートは、CFT構造や自己充填コンクリートに使われる。","アルミニウムの比重は、鋼の約1/3である。","一般の建築用木材の出火危険温度は、450℃前後である。"],"a":4,"e":"この記述が誤り。木材の出火危険温度は、一般に260℃前後とされている。","l":"法令外","c":""},{"id":"2016-99","s":3,"q":"都市ガス(13A)とLPガスの性質についての次の文の(ア)〜(エ)に入る語句の組合せとして、最も適当なものはどれか。\n「都市ガス(13A)は空気より( ア )、LPガスは空気より( イ )。ガス1m³を燃やすのに必要な空気量は、都市ガス(13A)に比べてLPガスのほうが( ウ )。また、容積あたりの発熱量は、LPガスに比べて都市ガス(13A)のほうが( エ )。」","o":["ア 軽く　イ 重い　ウ 多い　エ 少ない","ア 軽く　イ 重い　ウ 少ない　エ 多い","ア 重く　イ 軽い　ウ 多い　エ 少ない","ア 重く　イ 軽い　ウ 少ない　エ 多い","ア 重く　イ 軽い　ウ 少ない　エ 少ない"],"a":0,"e":"都市ガス(13A)は空気より軽く、LPガスは空気より重い。LPガスは発熱量が大きいぶん、燃やすのに必要な空気量も多い(2025年度問97でも同じ趣旨)。","l":"法令外","c":""},{"id":"2016-100","s":3,"q":"建築設備について、最も不適当なものはどれか。","o":["緊急ガス遮断装置は、大規模な地下街、超高層建築物、中圧ガス設備のある建物などに設置が義務づけられている。","空気調和・換気設備のファンや、給排水設備のポンプには、直流電動機が広く使われている。","建築基準法により、高さ31mを超える建物には、原則として非常用の昇降機を設けなければならない。","ESCOとは、省エネルギー診断・システム設計・設備導入工事から効果の検証まで、一貫したサービスを提供するエネルギーの総合サービス事業のことである。","受変電設備とは、電力会社から高圧で受けた電気を決められた電圧に下げて、建物の中に配る設備である。"],"a":1,"e":"建物の設備のファンやポンプには、交流の三相誘導電動機が多く使われている(2023年度問97でも同じ趣旨の記述が正しいとされている)。","l":"法令外","c":""},{"id":"2016-101","s":3,"q":"防災などに関する語句の組合せとして、最も不適当なものはどれか。","o":["マグニチュード ― 地震の規模を表す指標","ライフライン ― 建物を保全するための諸設備","震度階級 ― 観測点での地震の揺れの強さを示す指標","耐震診断 ― 建築物の耐震改修の促進に関する法律","マイコンメータ ― 地震のとき自動でガスを止めるガスメータ"],"a":1,"e":"ライフラインとは、電気・ガス・水道・通信など、生活を支えるための諸施設のことである(2024年度問102でも同じ趣旨)。","l":"法令外","c":""},{"id":"2016-102","s":3,"q":"建物の火災のときの避難と消火について、最も不適当なものはどれか。","o":["非常用の進入口は、外から開けたり壊したりして室内に入れる構造にする。","非常用の進入口は、原則として3階以上の階に設けることが義務づけられている。","非常用エレベーターは、火災のときは、かごの戸を開けたままで使うことができる。","非常用エレベーターは、火災のときは、入居者より消防隊の使用が優先される。","一般の乗用エレベーターは、火災のときは、最寄りの階に止めるのが一般的である。"],"a":4,"e":"一般の乗用エレベーターは、火災のときは避難階に止める(火災時管制運転)。最寄り階に止めるのは地震時である。","l":"法令外","c":""},{"id":"2016-103","s":3,"q":"次の工作物のうち、建築基準法でいう建築物に当たらないものはどれか。","o":["屋根と壁のある建物","屋根と柱のある建物","高架の工作物の中に設けた倉庫","鉄道のプラットホームの上家","屋根のない観覧場"],"a":3,"e":"鉄道の線路敷地内の運転保安施設やプラットホームの上家などは、建築基準法の建築物から除かれている。","l":"建築基準法 第2条第1号","c":""},{"id":"2016-104","s":3,"q":"建築基準法の建築物の制限について、最も不適当なものはどれか。","o":["建築面積は、壁・柱などの内側で囲まれた部分の水平投影面積で求める。","敷地面積は、土地の高低差に関係なく、水平投影面積で求める。","建ぺい率とは、建築面積を敷地面積で割った比である。","容積率とは、建物の延べ面積を敷地面積で割った比である。","建物の高さの制限として、北側高さ制限がある。"],"a":0,"e":"建築面積は、壁・柱などの「中心線」で囲まれた部分の水平投影面積で求める。","l":"建築基準法施行令 第2条第1項第2号","c":""},{"id":"2016-105","s":3,"q":"建築物の管理について、最も不適当なものはどれか。","o":["ファシリティマネジメント(FM)とは、企業・団体などが活動のために施設とその環境を総合的に企画・管理・活用する経営活動と定義されている。","二次エネルギーとは、一次エネルギーを変換・加工して得られるエネルギーのことで、電気が代表的である。","設備管理のライフサイクルとは、設備の計画・設計・製作・運用・保全をへて、廃却または再利用までを含むすべての段階・期間と定義されている。","CASBEEとは、中央監視・エネルギー管理・ビル管理・施設管理を含んだ包括的なシステムである。","設備の保全活動には、維持活動と改善活動がある。"],"a":3,"e":"CASBEEは建築環境総合性能評価システムで、建物の環境性能を評価する仕組みである。中央監視やエネルギー管理を含む包括的なシステムはBEMSなど。","l":"法令外","c":""},{"id":"2016-106","s":4,"q":"給水・排水の管理で使う用語と、その単位の組合せとして、最も不適当なものはどれか。","o":["精密ろ過膜の有効径 ― μm","色度 ― 度","腐食速度 ― mm/y","排水基準でのリン含有量 ― %","加熱装置の能力 ― kW"],"a":3,"e":"リン含有量は濃度で表すので、単位は mg/L である(2017年問106で「下水道におけるリン含有量 ― mg/L」が正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2016-107","s":4,"q":"給水設備に関する記述として、最も不適当なものはどれか。","o":["配水管から給水管が分かれる箇所では、配水管の最小動水圧として150kPa以上を確保する。","簡易専用水道の設置者は、水槽の清掃を1年以内ごとに1回、定期に行う。","簡易専用水道とは、水道事業の水道から受ける水だけを水源とし、水槽の有効容量の合計が10m³を超えるものをいう。","建築物環境衛生管理基準では、給水栓の水について、7日以内ごとに1回の遊離残留塩素の検査が定められている。","水道法の水質基準で、鉛及びその化合物の基準値は0.05mg/L以下である。"],"a":4,"e":"鉛及びその化合物の基準値は、鉛の量として0.01mg/L以下である(水質基準に関する省令)。簡易専用水道の水槽清掃(毎年1回以上、水道法施行規則第55条)、遊離残留塩素の7日以内ごとの検査(建築物衛生法施行規則第4条)は現行の規定どおり。","l":"水質基準に関する省令(表)、水道法施行規則 第55条、建築物衛生法施行規則 第4条","c":""},{"id":"2016-108","s":4,"q":"水中の塩素化合物(モノクロラミン・ジクロラミン・次亜塩素酸・次亜塩素酸イオン)を、消毒力の強い順に並べたものとして、最も適当なものはどれか。","o":["ジクロラミン > モノクロラミン > 次亜塩素酸 > 次亜塩素酸イオン","モノクロラミン > ジクロラミン > 次亜塩素酸イオン > 次亜塩素酸","次亜塩素酸イオン > モノクロラミン > ジクロラミン > 次亜塩素酸","次亜塩素酸 > 次亜塩素酸イオン > モノクロラミン > ジクロラミン","次亜塩素酸 > 次亜塩素酸イオン > ジクロラミン > モノクロラミン"],"a":4,"e":"消毒力は、遊離残留塩素の次亜塩素酸(HOCl)>次亜塩素酸イオン(OCl⁻)>結合残留塩素のジクロラミン(NHCl₂)>モノクロラミン(NH₂Cl)の順に強い。","l":"法令外","c":""},{"id":"2016-109","s":4,"q":"建築物の給水方式に関する記述として、最も不適当なものはどれか。","o":["直結直圧方式は、水道水が汚染されるおそれが少ない。","直結増圧方式は、引込み管の管径に制限がある。","高置水槽方式は、安定した水圧と水量が得られる。","圧力水槽方式は、受水槽がいらない方式である。","ポンプ直送方式では、小型の圧力水槽を設けている例が多い。"],"a":3,"e":"圧力水槽方式は受水槽を必要とする方式で、受水槽の水をポンプで圧力水槽に送って給水する。","l":"法令外","c":""},{"id":"2016-110","s":4,"q":"給水設備に関する記述として、最も不適当なものはどれか。","o":["事務所ビルのゾーニングの上限給水圧力は、一般に0.5MPaである。","受水槽の容量は、一般に1日最大使用水量の1/10である。","一般の水栓に最低限必要な水圧は、30kPaである。","給水配管の適正な流速は、0.9〜1.2m/sとされている。","大便器洗浄弁に最低限必要な水圧は、70kPaである。"],"a":1,"e":"受水槽の有効容量は、一般に1日使用水量の1/2程度である(2021年問112で正しい記述として出題)。1/10は高置水槽の目安。","l":"法令外","c":""},{"id":"2016-111","s":4,"q":"給水設備の配管に関する記述として、最も不適当なものはどれか。","o":["飲料水の配管は、ほかの配管系統と見分けがつくようにしなければならない。","建物の揺れや配管の振動などによるずれを吸収するため、貯水槽と配管の接続には可とう継手を使う。","揚水管は、高置水槽に向かって上り勾配で配管する。","ウォータハンマ防止器は、ウォータハンマが起こる場所の近くに設ける。","上向き配管方式の場合は、先下がりの配管にする。"],"a":4,"e":"上向き配管方式で「先下がり配管とする」とした記述が誤り。","l":"法令外","c":""},{"id":"2016-112","s":4,"q":"飲料用貯水槽に関する記述として、最も不適当なものはどれか。","o":["屋内に置く貯水槽は、建物の躯体を利用してつくってはならない。","受水槽を独立した部屋に置く場合は、出入口にかぎをかける。","オーバフロー管は、排水口空間を確保して間接排水とする。","流入管は、水が入るときの波立ちを防ぐため、水の中に沈める。","水のよどみを防ぐため、流入口と流出口を対角線の位置に配置する。"],"a":3,"e":"流入管は受水槽の中で水に沈めず、吐水口空間を確保する(2022年問114で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-113","s":4,"q":"給水設備の汚染に関する記述として、最も不適当なものはどれか。","o":["クロスコネクションとは、飲料水の系統とほかの配管系統を、配管などで直接つなぐことである。","逆サイホン作用とは、給水管内にできた負圧で、水受け容器にいったん出た水が給水管内に逆流することである。","大便器洗浄弁には、大気圧式バキュームブレーカを設ける。","バキュームブレーカには、大気圧式と圧力式がある。","洗面器の吐水口空間とは、水栓の吐水口の端から、水受け容器のオーバフロー口までの垂直距離である。"],"a":4,"e":"洗面器の吐水口空間は、給水栓の吐水口と洗面器のあふれ縁との垂直距離である(2025年問116で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-114","s":4,"q":"給水設備の機器・配管材料に関する記述として、最も不適当なものはどれか。","o":["仕切弁は、玉形弁より流量の調整に向いている。","ステンレス鋼板製の貯水槽は、気相部の耐食性を考える必要がある。","ポリブテン管の接合方法には、メカニカル形接合や融着接合がある。","合成樹脂ライニング鋼管のねじ接合には、管端防食継手を使う。","FRP製の貯水槽は機械的強度が低いので、耐震補強が必要である。"],"a":0,"e":"流量の調整に向いているのは玉形弁である(2023年問75で「玉形弁は流量調整用として用いられる」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-115","s":4,"q":"給水設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["防錆剤の注入と管理の業務は、建築物衛生法の建築物飲料水水質検査業の登録を受けた者が行わなければならない。","貯水槽の定水位弁や電極棒などの点検を怠ると、正しく動かなくなって断水や溢水(あふれ)事故が起こるおそれがある。","管更生工法で管の内側に合成樹脂ライニングをする場合は、技術評価・審査証明を受けた工法を選ぶのがよい。","高置水槽と受水槽の清掃は原則として同じ日に行い、受水槽の清掃後に高置水槽を清掃する。","受水槽の水位制御の作動確認は、槽内のボールタップを手で動かして行う。"],"a":0,"e":"防錆剤の注入・管理を飲料水水質検査業の登録業者が行わなければならない、という決まりはない(2022年問116・2024年問117でも誤りとして出題)。受水槽→高置水槽の順の清掃は告示第119号 第2のとおり。","l":"平成15年厚生労働省告示第119号 第2(選択肢4)","c":""},{"id":"2016-116","s":4,"q":"高置水槽の電極棒による水位制御について、下の図のA〜Eの電極棒と、その役割の組合せとして、最も適当なものはどれか。","o":["A:満水警報 ― B:給水開始 ― C:給水停止 ― D:減水警報 ― E:共通","A:満水警報 ― B:給水停止 ― C:給水開始 ― D:減水警報 ― E:共通","A:共通 ― B:給水停止 ― C:満水警報 ― D:減水警報 ― E:給水開始","A:共通 ― B:満水警報 ― C:給水停止 ― D:給水開始 ― E:減水警報","A:共通 ― B:満水警報 ― C:給水開始 ― D:給水停止 ― E:減水警報"],"a":1,"e":"いちばん長いEが常に水につかる共通電極になる。短い順に、Aは水位が上がりすぎたときの満水警報、Bは給水停止、Cは給水開始、Dは水位が下がりすぎたときの減水警報である。","l":"法令外","c":"","g":["img/2016-116.png"]},{"id":"2016-117","s":4,"q":"給湯設備で扱う水の性質に関する記述として、最も不適当なものはどれか。","o":["水に溶けている空気は、配管内の圧力が高いと分離しにくい。","水は、ほとんど圧縮されない流体(非圧縮性流体)として扱える。","15℃の水の比熱は、4.186kJ/(kg・℃)である。","配管内の水に溶ける気体の量(溶解度)は、水温が上がると減る。","4℃以上の水は、温度が上がると比体積が小さくなる。"],"a":4,"e":"4℃以上の水は温度が上がると密度が小さくなる(2025年問121で正しい記述として出題)。比体積は密度の逆数なので、大きくなる。","l":"法令外","c":""},{"id":"2016-118","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["エネルギーと水を節約するため、湯と水を別々の水栓から出さずに混合水栓を使う。","貯蔵式湯沸器は90℃以上の高温の湯が得られ、飲用に使われる。","ホテルの宿泊部分の設計給湯量は、30〜50L/(人・日)である。","壁掛けシャワーの使用温度は、42℃程度である。","厨房の業務用皿洗い機のすすぎに使う給湯の温度は、70〜90℃である。"],"a":2,"e":"ホテルの宿泊部分の設計給湯量は150〜250L/(人・日)程度である(2024年問120で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-119","s":4,"q":"給湯設備の配管に関する記述として、最も不適当なものはどれか。","o":["配管の伸び縮みを吸収するため、配管の形に柔軟性をもたせ、長い直線の配管には伸縮管継手を設ける。","スリーブ形の伸縮管継手は、ベローズ形より伸縮を吸収できる量が大きい。","密閉式給湯方式の横管は勾配をつけずに配管し、管理しやすい位置に自動空気抜き弁を設ける。","凹形の配管になる場合は、水を抜くための止水弁を設ける。","厨房のように連続して湯を使う系統の枝管には、返湯管を設けないことが多い。"],"a":2,"e":"給湯の横管を「無勾配で配管する」とした記述が誤り。","l":"法令外","c":""},{"id":"2016-120","s":4,"q":"給湯設備の循環ポンプに関する記述として、最も不適当なものはどれか。","o":["ポンプは、返湯管に設置する。","ポンプは、背圧に耐えられるものを選ぶ。","ポンプの揚程は、循環管路で最も大きくなる管路の摩擦抵抗・局部抵抗による圧力損失から決める。","循環水量は、配管からの熱損失に反比例する。","省エネルギーのため、ポンプは連続運転せず、返湯管の温度が下がったときに動かす。"],"a":3,"e":"循環水量は、配管からの熱損失に比例する(2021年問121の算定式 Q=0.0143×H_L÷Δt のとおり、熱損失H_Lが大きいほど循環流量Qも大きい)。","l":"法令外","c":""},{"id":"2016-121","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["貯湯槽の容量は、ピーク時に必要な量の1〜2時間分を目安に、加熱能力とのバランスで決める。","返湯管に銅管を使う場合は、潰食を考えて管内の流速を1.2m/s以下にする。","逃し管の立ち上げの高さは、補給水槽(高置水槽)の水面より少し低い位置にする。","給湯設備の金属材料の腐食は、同じ材料を給水設備に使う場合より早く起こり、腐食の速さも速い。","湯を均等に循環させるには、返湯管に定流量弁を設けるとよい。"],"a":2,"e":"逃し管は、水を供給する高置水槽の水面よりも高く立ち上げる(2025年問119で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-122","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["器具のワッシャには、細菌が増えるのを防ぐため天然ゴムを使う。","第二種圧力容器は、1年以内ごとに1回、定期自主検査を行う。","給湯配管は、1年に1回以上、給水系統の配管の洗浄方法に準じて洗浄することが望ましい。","給湯栓から出る湯が分離した気体で白くにごる場合は、自動空気抜き弁の空気の出口が詰まっている可能性がある。","簡易ボイラ・小型ボイラ以外のボイラは、1か月以内ごとに1回、定期自主検査を行う。"],"a":0,"e":"器具のワッシャには、細菌の繁殖を防ぐため合成ゴム製のものを使う(2024年問124で正しい記述として出題)。第二種圧力容器(ボイラー及び圧力容器安全規則第88条)とボイラー(同第32条)の定期自主検査の頻度は現行の規定どおり。","l":"ボイラー及び圧力容器安全規則 第32条・第88条(選択肢2・5)","c":""},{"id":"2016-123","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["逃し弁は、1か月に1回、作動を確認する。","各種の弁は、1年に1回以上分解清掃する。","シャワーヘッドは、1年に1回以上分解清掃する。","維持管理が適切に行われ、末端の給水栓で50℃以上の水温が保てる場合は、残留塩素の検査を省略できる。","基準値を超える一般細菌が見つかった場合は、70℃以上の湯を循環させて加熱処理する。"],"a":3,"e":"(4)の記述が誤り。","l":"法令外","c":""},{"id":"2016-124","s":4,"q":"雑用水設備に関する記述として、最も不適当なものはどれか。","o":["配管にスライムが発生した場合は、残留塩素濃度を高めて洗浄する。","雑用水の原水には、1年を通して安定して確保できる排水を優先して使う。","雑用水受水槽は、槽内の水がよどまないようにする。","水栓には、雑用水であることを示す飲用禁止の表示やステッカーなどを付ける。","広域循環方式で雑用水を使うと、下水道への負荷が軽くなる。"],"a":4,"e":"広域循環方式で下水道への負荷が軽くなる、とした記述が誤り(2023年問123でも、広域循環方式で下水道への排水量が減るとした記述は誤りとして出題)。","l":"法令外","c":""},{"id":"2016-125","s":4,"q":"雨水利用設備の装置と、維持管理の項目の組合せとして、最も不適当なものはどれか。","o":["集水装置 ― 屋根面の汚れを取り除く","スクリーン ― 固形物を取り除く","ストレーナ ― 逆洗洗浄装置を点検する","沈砂槽 ― 空気の供給量を調整する","ろ過装置 ― 詰まり具合を点検する"],"a":3,"e":"沈砂槽の維持管理項目を「空気供給量の調整」とした組合せが誤り。","l":"法令外","c":""},{"id":"2016-126","s":4,"q":"建築物衛生法施行規則で定める雑用水の水質基準の項目と基準の組合せとして、正しいものはどれか。","o":["臭気 ― 異常でないこと","pH値 ― 5以上9以下であること","外観 ― 浮遊物を含まないこと","大腸菌 ― 100CFU/mL以下であること","濁度 ― 5度以下であること"],"a":0,"e":"臭気は「異常でないこと」が基準である。なおpH値は5.8以上8.6以下、外観は「ほとんど無色透明であること」、大腸菌は「検出されないこと」、濁度は2度以下(施行規則第4条の2)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2016-127","s":4,"q":"排水の水質に関する記述として、最も不適当なものはどれか。","o":["BOD/COD比が高い排水には、物理化学処理法より生物処理法が向いている。","全窒素とは、無機性窒素の合計である。","リン化合物は、閉鎖性水域の富栄養化の原因物質の一つである。","油脂類を多く含む排水は、ノルマルヘキサン抽出物質の測定値が高い。","総アルカリ度は、硝化・脱窒反応の指標として使われている。"],"a":1,"e":"全窒素は、有機性窒素・アンモニア性窒素・亜硝酸性窒素・硝酸性窒素の総和である(2025年問127で正しい記述として出題)。無機性窒素だけではない。","l":"法令外","c":""},{"id":"2016-128","s":4,"q":"排水トラップと阻集器に関する語句の組合せとして、最も不適当なものはどれか。","o":["わんトラップ ― サイホントラップに分類","プラスタ阻集器 ― プラスタや貴金属をせき止め、分けて集める","雨水トラップ ― ルーフドレンからの悪臭を防ぐ","オイル阻集器 ― ガソリンや油類をせき止め、分けて集める","ドラムトラップ ― 非サイホントラップに分類"],"a":0,"e":"わんトラップはサイホントラップではなく、非サイホントラップに分類される(2023年問127でも「わんトラップ ― サイホントラップ」は誤りの組合せとして出題)。","l":"法令外","c":""},{"id":"2016-129","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["管径125mmの排水横管の最小勾配は、1/150である。","排水管の掃除口の間隔は、管径100mm以下の場合30m以内とする。","伸頂通気方式の排水横主管の水平曲がりは、排水立て管の底部から3m以内に設けてはならない。","通気立て管の上部は、最も高い位置の衛生器具のあふれ縁から150mm以上高い位置で、伸頂通気管につなぐ。","排水立て管のオフセット部の上下600mm以内には、排水横枝管を設けてはならない。"],"a":1,"e":"管径100mm以下の排水管の掃除口の間隔は15m以内とする(2023年問128・2025年問131で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-130","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["排水ポンプは、排水槽の吸込みピットの壁などから200mm以上離して設置する。","敷地排水管の直管が長い場合、排水ますは管内径の200倍を超えない範囲に設ける。","間接排水管の口径が65mmの場合、排水口空間は最小150mmである。","雨水ますの流出管は、流入管より管底を20mm程度下げて設ける。","通気管の末端を窓や換気口などの近くに設ける場合は、その上端から600mm以上立ち上げて大気に開放する。"],"a":1,"e":"敷地排水管の直管が長い場合、排水ますは管内径の120倍を超えない範囲に設置する(2021年問132・2023年問130で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-131","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["厨房用の排水槽から排水を出すには、汚水ポンプを使う。","トラップの封水強度とは、排水管内に正圧や負圧が生じたときにトラップの封水を保つ能力である。","雨水浸透方式は、透水性舗装・浸透ます・浸透地下トレンチなどでできている。","排水槽のマンホールは、水中ポンプやフート弁の真上に設ける。","通気立て管の下部を排水立て管から取り出す位置は、最も低い排水横枝管より低くする。"],"a":0,"e":"厨房用の排水槽から排水を除くには、汚物ポンプを使う(2025年問132で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-132","s":4,"q":"排水通気設備の保守管理に関する語句の組合せとして、最も不適当なものはどれか。","o":["高圧洗浄法 ― 排水槽や排水管の清掃","排水槽の開口部への防虫網の設置 ― チョウバエ類の発生を防ぐ","厨房排水槽の排水ポンプ ― フロートスイッチによる水位制御","逆流防止弁 ― 排水通気管からの臭気の逆流を防ぐ","ロッド法 ― 敷地排水管の清掃"],"a":3,"e":"逆流防止弁は、下水本管からの排水の逆流を防ぐために設ける(2017年問133で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-133","s":4,"q":"排水通気設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["排水槽の清掃は、まず酸素欠乏状態でないこと、かつ硫化水素濃度が10ppm以下であることを確かめてから作業する。","高圧洗浄による排水管の清掃では、0.5〜3MPaの圧力の水を噴射して洗う。","水中ポンプのメカニカルシール部のオイルは、6か月〜1年に1回交換する。","グリース阻集器のグリースは、7〜10日に1回の間隔で取り除く。","排水槽の悪臭対策として、タイマによる強制排水を行うことが望ましい。"],"a":1,"e":"高圧洗浄による排水管の清掃では、5〜30MPaの圧力の水を噴射する(2023年問134・2024年問135で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-134","s":4,"q":"排水通気設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["排水管に付いた有機性の汚れは、アルカリ性洗浄剤で取り除く。","ウォータラム法は、圧縮空気を一気に放出し、その衝撃で詰まりを取り除く方法である。","排水ポンプは6か月に1回絶縁抵抗を測り、1MΩ以上あることを確かめる。","排水槽の清掃を6か月以内ごとに1回、定期に行うことが、建築物衛生法で定められている。","排水横管の清掃にスネークワイヤ法を使う場合、一般に長さ25m程度が限界とされている。"],"a":2,"e":"排水ポンプの絶縁抵抗の測定は1か月に1回行う(2023年問134で正しい記述として出題)。なお(4)は施行規則第4条の3のとおり。","l":"建築物衛生法施行規則 第4条の3(選択肢4)","c":""},{"id":"2016-135","s":4,"q":"大便器に関する記述として、最も不適当なものはどれか。","o":["洗浄弁方式は、利用者の多い事務所・店舗・駅・ホテルなどの共用部に採用される。","洗い出し式は、たまり水がかなり浅いので跳ね返りが少ないが、臭いが出やすい。","ブローアウト式は、噴出穴から洗浄水を強く噴き出し、その勢いで汚物を便器の外に出す方式である。","サイホンゼット式は、臭いが出にくく、ボウルの乾いた面に汚物がほとんど付かない。","洗い落とし式は、洗浄水がトラップを満水にしてサイホンを起こし、汚水を吸い出す方式である。"],"a":4,"e":"洗い落とし式の説明として誤り。","l":"法令外","c":""},{"id":"2016-136","s":4,"q":"厨房排水の除害施設に関する記述として、最も不適当なものはどれか。","o":["生物処理法は浮上分離法と比べて、ランニングコストが高い傾向がある。","厨房排水のBODとSSは、ほかの雑排水より高濃度である。","除害施設を設ける目的の一つに、下水道の詰まりを防ぐことがある。","浮上分離法としては、一般に加圧浮上法が使われる。","悪臭成分が多く出るので、処理施設の臭気対策が必要になる。"],"a":0,"e":"(1)の記述が誤り。","l":"法令外","c":""},{"id":"2016-137","s":4,"q":"浄化槽法で定める浄化槽の定義について、次の文の【 】内の語句のうち、誤っているものはどれか。\n「【(1)便所】と連結して、し尿とこれに併せて【(2)雨水】を処理し、下水道法の終末処理場をもつ公共下水道以外に放流するための【(3)設備又は施設】であって、同法の公共下水道と【(4)流域下水道】、ならびに廃棄物処理法の計画に従って市町村が設置した【(5)し尿処理施設】以外のものをいう。」","o":["便所","雨水","設備又は施設","流域下水道","し尿処理施設"],"a":1,"e":"浄化槽がし尿と併せて処理するのは「雑排水」である。雑排水からは工場廃水や雨水などの特殊な排水は除かれている(浄化槽法第2条第1号)。","l":"浄化槽法 第2条第1号","c":""},{"id":"2016-138","s":4,"q":"処理対象人員500人、1人1日あたりの汚水量200L/(人・日)、流入汚水のBODが200mg/Lのとき、BOD容積負荷から求めたばっ気槽の有効容量として、最も適当なものはどれか。ただし、BOD容積負荷は0.2kg/(m³・日)とする。","o":["40m³","100m³","125m³","250m³","400m³"],"a":1,"e":"1日の汚水量は500人×0.2m³=100m³。BODの量は100m³×200g/m³=20kg/日。有効容量は20kg/日÷0.2kg/(m³・日)=100m³となる。","l":"法令外","c":""},{"id":"2016-139","s":4,"q":"浄化槽のばっ気槽の点検項目として、最も不適当なものはどれか。","o":["水温","活性汚泥浮遊物質(MLSS)濃度","生物膜の付き具合","30分間汚泥沈殿率(SV30)","溶存酸素(DO)濃度"],"a":2,"e":"生物膜の生成状況を点検するのは接触ばっ気槽である(2020年問139で正しい組合せとして出題)。活性汚泥法のばっ気槽の点検項目ではない。","l":"法令外","c":""},{"id":"2016-140","s":4,"q":"消火設備に関する記述として、最も不適当なものはどれか。","o":["消火器は、火災を見つけた初期の段階で消火するためのものである。","泡消火設備は、駐車場や飛行機の格納庫などに設けられる。","屋内消火栓は、公設消防隊が使うもので、消防隊専用栓とも呼ばれる。","スプリンクラー設備は、火災が起きると自動で散水して初期消火するものである。","屋外消火栓には、消火栓弁・ホース・ノズルを内蔵した屋外消火栓箱型、地下ピット格納型、地上スタンド型がある。"],"a":2,"e":"屋内消火栓は公設消防隊専用の設備ではない(2024年問140でも「公設消防隊の専用使用」は誤りとして出題)。","l":"法令外","c":""},{"id":"2016-141","s":5,"q":"「建築物における衛生的環境の維持管理について」(平成20年1月25日 健発第0125001号)に示された建築物環境衛生維持管理要領について述べた次の文のうち、最も不適当なものはどれか。","o":["建築物の清掃は、用途、使用状況、劣化状況、建築資材などを考えた年間作業計画と作業手順書をつくり、それにもとづいて行う。","天井など日常の清掃が届きにくい箇所や照明器具、給排気口などは、6か月以内ごとに1回、定期に汚れを点検し、必要に応じて除じん・洗浄を行う。","廃棄物の収集・運搬設備、貯留設備などの廃棄物処理設備は、1年以内ごとに1回、定期に点検し、必要に応じて補修・消毒などを行う。","清掃用機械などは、6か月以内ごとに1回、定期に点検し、必要に応じて整備・取替えなどを行う。","建築物内で出る廃棄物について、所有者等は分別できる環境を整え、利用者に分別を促す。"],"a":2,"e":"廃棄物処理設備の点検は6か月以内ごとに1回である(2024年度問141・2022年度問141で同じ内容)。日常清掃しない箇所の6か月以内ごとの点検は告示第119号第5の一の3のとおり。","l":"平成15年厚生労働省告示第119号 第5(維持管理要領)","c":""},{"id":"2016-142","s":5,"q":"建築物清掃で、一般に日常清掃として行うものはどれか。","o":["玄関ホールのフロアマットの洗浄","エスカレーターのランディングプレートの除じん","廊下の壁の洗浄","駐車場の排水溝の集じん","ドアノブなど金属類の磨き"],"a":1,"e":"エスカレーターのランディングプレートの除じんは日常清掃で行う(2021年度問141・2020年度問142でも日常清掃とされている)。洗浄や磨きは定期清掃の作業。","l":"法令外","c":""},{"id":"2016-143","s":5,"q":"建築物清掃の作業場所(管理区域)について述べた次の文のうち、最も不適当なものはどれか。","o":["外装区域の窓ガラスは、汚れの固着を防ぐため、1〜2か月に1回程度清掃する。","管理用区域は一般の人が立ち入らないので、年2回程度清掃する。","共用区域は建築物の中で最もよく使われるので、1日に1〜2回清掃する。","専用区域は、1日に1回以上清掃して清潔を回復するよう努める。","外周区域は公共の場所としての役割もあるので、1日に1回程度清掃する。"],"a":1,"e":"この記述が誤り。管理用区域(中央監視室など)も人が日常的に使う場所なので、年2回程度の清掃では足りない(2017年度問143でも同じ内容が誤りとされている)。","l":"法令外","c":""},{"id":"2016-144","s":5,"q":"建築物清掃の品質について述べた次の文のうち、最も不適当なものはどれか。","o":["清掃の品質は、作業結果のよしあしを評価する作業品質と、組織品質でできている。","現場管理品質には、作業計画の立案や現場での教育訓練が含まれる。","評価範囲は、汚れの度合いが高い箇所などに重点を絞る。","評価者は、改善を指示したときは改善されたかを再点検する。","目視点検は原始的な方法なので、評価方法として適切でない。"],"a":4,"e":"清掃のきれいさの評価は、おもに目視などの官能検査で行う(2021年度問144・2020年度問144参照)。","l":"法令外","c":""},{"id":"2016-145","s":5,"q":"ビルクリーニングで汚れやしみを取るために必要な知識(ビルクリーニングの5原則)として、最も不適当なものはどれか。","o":["点検評価の知識","建材の知識","作業方法の知識","汚れの知識","洗剤の知識"],"a":0,"e":"この選択肢が誤り。汚れやしみを取るための知識として挙げられるのは、建材・汚れ・洗剤・作業方法などに関するもので、点検評価の知識は含まれない。","l":"法令外","c":""},{"id":"2016-146","s":5,"q":"ほこりの予防などについて述べた次の文のうち、最も不適当なものはどれか。","o":["ほこりの予防には、侵入を防ぐ対策と発生を防ぐ対策がある。","ほこりの侵入を防ぐには、建築物の出入口にフロアマットなどを敷くのが効果的である。","建築物内のほこりは、外から入ってきた綿ほこりの割合が高い。","土ほこりの除じん作業では、作業回数を適切に決めることが大切である。","建築物内でほこりが出る原因には、事務作業や生活動作などがある。"],"a":2,"e":"この記述が誤り。綿ほこりは衣類や紙などから建物の中で出るもので、外から入ってくるのはおもに土砂(土ほこり)である。","l":"法令外","c":""},{"id":"2016-147","s":5,"q":"床みがき機について述べた次の文のうち、最も適当なものはどれか。","o":["自動床洗浄機は、洗剤供給式床みがき機とドライ式真空掃除機を組み合わせたものである。","凹凸のある床には、研磨粒子の付いたパッドを付けて洗う。","床みがき機のブラシは、直径60cm以上のものが多く使われる。","超高速バフ機の回転数は、毎分1,000〜3,000回転である。","超高速床みがき機は、ふつうカーペットのシャンプークリーニングに使える。"],"a":3,"e":"超高速バフ機は毎分1,000〜3,000回転で磨く(2017年度問148でも正しい記述)。自動床洗浄機は吸水式真空掃除機と組み合わせたもの、凹凸の床はブラシを使う。","l":"法令外","c":""},{"id":"2016-148","s":5,"q":"カーペット洗浄用の機械・器具について述べた次の文のうち、最も適当なものはどれか。","o":["洗剤供給式床みがき機は、化学繊維のタフテッドカーペットより、ウールのウィルトンカーペットに向いている。","ドライフォーム方式の洗浄機は、洗剤液を泡にして縦回転ブラシで洗う。","パイルの奥の土砂は、カーペットスイーパで取る。","スチーム洗浄機は、温水を吹き付けて汚れを分解する。","エクストラクタは、ノズルから泡を吹き付けて洗い、すぐに吸い取る。"],"a":1,"e":"ドライフォーム方式は泡と縦回転ブラシで洗う(2021年度問146でも正しい記述)。洗剤供給式はタフテッド向き(2020年度問148)、スイーパは表面の粗ごみ用、エクストラクタは洗浄液を吹き付ける。","l":"法令外","c":""},{"id":"2016-149","s":5,"q":"清掃作業に使う洗剤について述べた次の文のうち、最も適当なものはどれか。","o":["床や家具の洗浄に使う一般用洗剤は、ふつうpH4〜6の弱酸性である。","鉄分を含む水あかや尿石を取るには、アルカリ性洗剤が有効である。","洗剤の助剤は、界面活性剤の表面張力を高めて洗浄力を上げる。","真ちゅう金物の洗浄には、研磨剤入り洗剤を使う。","リノリウムに付いた油汚れを取るには、アルカリ性洗剤を使う。"],"a":3,"e":"真ちゅう金物には研磨剤入り洗剤を使う(2020年度問150でも正しい組合せ)。尿石・水あかには酸性洗剤、リノリウムはアルカリに弱い。","l":"法令外","c":""},{"id":"2016-150","s":5,"q":"剥離剤の性質と使い方について述べた次の文のうち、最も適当なものはどれか。","o":["塩化ビニル系床材に変色などの影響を与える。","フロアシーラを簡単にはがせる。","酸性で、樹脂床維持剤の皮膜を溶かす。","木質床材に変色や組織の破壊などの影響を与える。","剥離剤を使った後のすすぎ拭きは1回にして、樹脂床維持剤を塗る。"],"a":3,"e":"剥離剤はアルカリ性で、アルカリに弱い木質床材を変色させたり傷めたりする(2024年度問153参照)。フロアシーラは簡単には除去できず、すすぎ拭きは十分に行う(2021年度問147)。","l":"法令外","c":""},{"id":"2016-151","s":5,"q":"カーペット清掃について述べた次の文のうち、最も適当なものはどれか。","o":["カーペットのほつれは、年に1〜2回まとめて処理する。","しみ取り作業は、定期作業で行う。","カーペットスイーパは、回転ブラシを電動モーターで回して掃き取り、中に巻き込む仕組みである。","全面クリーニング方式の一つとして、パウダー方式がある。","パイルの上部の汚れを取るには、拭取り方式を使う。"],"a":4,"e":"パイルの上部にある汚れは拭取り方式で取る。しみ取りは日常作業で行い(2024年度問151)、カーペットスイーパは手押しで回転ブラシを回す器具である。","l":"法令外","c":""},{"id":"2016-152","s":5,"q":"床維持剤について述べた次の文のうち、最も適当なものはどれか。","o":["フロアシーラは仕上げ剤として使い、床の保護と美観を高める。","フロアオイルは、おもに表面加工された木質床材の保護に使う。","水性フロアポリッシュは、ろう状物質や合成樹脂を水に溶かしたり乳化させたりしたものである。","フロアフィニッシュは、顔料などの着色剤を含む。","フロアポリッシュは、おもに目止め剤として使う。"],"a":2,"e":"水性フロアポリッシュは、ろう状物質や合成樹脂を水に溶かす・乳化させてつくる。目止めに使うのはフロアシーラ(2017年度問151)。","l":"法令外","c":""},{"id":"2016-153","s":5,"q":"床材の特徴について述べた次の文のうち、最も不適当なものはどれか。","o":["花崗岩は、アルカリに弱い。","コンクリートは、酸に弱い。","ゴムタイルは、すり減りにくい。","テラゾは、酸に弱い。","セラミックタイルは、酸にもアルカリにも強い。"],"a":0,"e":"花崗岩にはアルカリ性洗剤を使ってよく(2022年度問152でも正しい記述)、アルカリに弱いわけではない(弱点は熱。2024年度問152)。","l":"法令外","c":""},{"id":"2016-154","s":5,"q":"床以外の清掃作業について述べた次の文のうち、最も不適当なものはどれか。","o":["湯沸室で使う資機材は、湯沸室専用としてほかの場所と区別する。","エレベーターのインジケータや扉の汚れは、水溶性のものが多い。","空気調和用の吹出口などはほこりが付きやすいので、定期的な清掃が必要である。","人の手による汚れは、マイクロファイバークロスなど化学繊維の製品を使うと取りやすい。","階段の壁は、ほかの共用区域の壁よりほこりが多く付く。"],"a":1,"e":"この記述が誤り。エレベーターの押しボタンや扉の汚れは、手あか(皮脂)などの油性の汚れが多い。","l":"法令外","c":""},{"id":"2016-155","s":5,"q":"外装の清掃について述べた次の文のうち、最も適当なものはどれか。","o":["自動窓拭き設備による窓ガラス清掃は、人の作業より仕上がりがよい。","陶磁器タイルはほかの素材より汚れが目立ちやすいので、清掃回数を多くする。","光触媒(酸化チタン)コーティングには、清掃回数を減らす効果が期待されている。","ガラスの遮光用や飛散防止用のフィルムは、はがしてから清掃する。","臨海工業地帯にある建築物のアルミニウム外壁は、1年に1回清掃する。"],"a":2,"e":"光触媒コーティングは汚れを分解・付きにくくするので、清掃回数を減らす効果が期待される(2017年度問156でも正しい記述)。自動窓拭きは仕上がりが人に及ばない(2022年度問154)。","l":"法令外","c":""},{"id":"2016-156","s":5,"q":"日本の廃棄物処理政策の移り変わりについて述べた次の文のうち、最も不適当なものはどれか。","o":["昭和45年に廃棄物処理法が制定され、産業廃棄物と一般廃棄物に分けられた。","平成3年に廃棄物処理法が改正され、廃棄物の排出抑制が法律の目的に加えられた。","平成7年に容器包装リサイクル法が制定され、容器包装の分別排出や再商品化などが図られることになった。","平成12年に循環型社会形成推進基本法が制定され、同法にもとづく基本計画で発生抑制(リデュース)、再使用(リユース)、再生利用(リサイクル)を進めることになった。","平成24年に家電リサイクル法が制定され、使用済小型電子機器などに使われている金属などを回収し、再資源化を進めることになった。"],"a":4,"e":"使用済小型電子機器などの金属の回収を進めるのは小型家電リサイクル法(使用済小型電子機器等の再資源化の促進に関する法律)で、家電リサイクル法ではない(2017年度問160参照)。","l":"使用済小型電子機器等の再資源化の促進に関する法律","c":""},{"id":"2016-157","s":5,"q":"廃棄物について述べた次の文のうち、最も不適当なものはどれか。","o":["一般廃棄物はし尿とごみに大きく分けられ、ごみは家庭系ごみと事業系ごみに分かれる。","近年の水洗化率は、平成23年度の約93%から少しずつ上がっている。","平成23年度には、全国の焼却施設の約4分の1で余熱を使った発電が行われている。","一般廃棄物の埋立処分は、安定型最終処分場に埋め立てなければならない。","ごみの焼却処理では、800℃以上の高温で焼却する。"],"a":3,"e":"安定型最終処分場は、廃プラスチック類など腐らない安定型産業廃棄物を埋め立てる処分場である(廃棄物処理法施行令第6条)。一般廃棄物は一般廃棄物の最終処分場に埋め立てる(2023年度問158で同じ内容が正答)。","l":"廃棄物処理法施行令 第6条第1項第3号","c":""},{"id":"2016-158","s":5,"q":"ごみの処理について述べた次の文のうち、最も不適当なものはどれか。","o":["家庭系一般廃棄物は、原則として市町村が一般廃棄物処理計画に従い、清掃事業として処理している。","分別とは、出るところであらかじめ区分することで、リサイクルを進めるうえでとても大切である。","ごみの排出量を減らすため、収集袋の有料化や粗大ごみの有料化などが行われている。","事業系一般廃棄物の処理は、原則として都道府県が自らの責任で行っている。","ごみの最終処分場の確保は難しく、焼却処理や資源化で埋立量を減らしている。"],"a":3,"e":"事業活動で出た廃棄物は、事業者が自らの責任で適正に処理しなければならない(廃棄物処理法第3条第1項)。都道府県が処理するのではない。","l":"廃棄物処理法 第3条第1項","c":""},{"id":"2016-159","s":5,"q":"廃棄物処理法にもとづく産業廃棄物の取扱いについて述べた次の文のうち、最も不適当なものはどれか。","o":["産業廃棄物の処理業者が、受託した産業廃棄物の移動や処理の状況を自ら把握するため、産業廃棄物管理票制度(マニフェスト制度)が設けられている。","ビルピット汚泥のうち、し尿を含まない雑排水槽からのものは産業廃棄物にあたる。","産業廃棄物の適正な処理を確保するため、処理基準や委託基準が定められている。","都道府県は、産業廃棄物の適正な処理を確保するため、自ら処理する必要があると認める産業廃棄物の処理を事務として行うことができる。","産業廃棄物の収集・運搬や処分を行う処理業者は、専ら再生利用の目的となる場合を除き、都道府県知事の許可を受けなければならない。"],"a":0,"e":"マニフェスト制度は、処理を委託した排出事業者が移動や処理の状況を把握するための制度である(廃棄物処理法第12条の3。2021年度問158参照)。処理業者のための制度ではない。","l":"廃棄物処理法 第12条の3","c":""},{"id":"2016-160","s":5,"q":"建築物内の廃棄物処理の基本について述べた次の文のうち、最も不適当なものはどれか。","o":["紙くず類の収集には、一般にキャンバス製のコレクタが使われる。","厨芥類の収集には、悪臭防止などのため、ふた付きのポリバケツやステンレス製のコレクタが使われる。","収集運搬用具は廃棄物の種類ごとに用意し、種類ごとに収集の時間帯を決めておく。","吸い殻を集めるときは、金属製のふた付き容器を使う。","感染性廃棄物は、長い期間保管することを考えて保管場所を決める。"],"a":4,"e":"感染性廃棄物はできるだけ短い期間で処理し、長く保管しないようにする(2020年度問162でも同じ内容が誤りとされている)。","l":"法令外","c":""},{"id":"2016-161","s":5,"q":"建築物内廃棄物にかかわる人たちの基本的な役割について述べた次の文のうち、最も不適当なものはどれか。","o":["国・地方公共団体は、廃棄物の分別・再利用・再資源化の普及・啓発に努める。","ビルの入居者は、廃棄物処理のルールを徹底させるため責任者を選ぶ。","廃棄物処理業者・ビルメンテナンス業者は、廃棄物の容積を小さくするよう努める。","廃棄物収集運搬・処分業者は、契約にもとづいて、出された廃棄物の収集・運搬・処分を行う。","ビルメンテナンス業者は、建築物内廃棄物の処理に必要な容器、集積場所、保管場所などを適切に用意する。"],"a":4,"e":"容器や集積場所・保管場所を用意するのは、建築物維持管理権原者(建物の所有者側)の役割である(2020年度問163でも正しい記述)。","l":"法令外","c":""},{"id":"2016-162","s":5,"q":"産業廃棄物を出す事業者が行う処理の委託と、産業廃棄物管理票(マニフェスト)の扱いについて述べた次の文のうち、最も不適当なものはどれか。","o":["返送されたマニフェストの伝票は3年間保存する。","委託業者の管理では、最新の許可業者リストの確認、契約書のチェック、マニフェストの確認を定期的に行う。","処理を頼んでから90日たってもB2票とD票が戻らないときは、委託業者に問い合わせる。","処理を頼んでから180日たってもE票が戻らないときは、委託業者に問い合わせる。","委託業者を選ぶときは、許可の有無や期限、事業の範囲などを調べて選ぶ。"],"a":0,"e":"返送された管理票の写しの保存期間は5年である(廃棄物処理法施行規則第8条の26)。90日・180日は同規則第8条の28のとおり。","l":"廃棄物処理法施行規則 第8条の26・第8条の28","c":""},{"id":"2016-163","s":5,"q":"事務所建築物から厨芥が1日あたり0.20m³出ていて、その質量は全廃棄物の質量の5%を占めていた。全廃棄物の質量を1日あたり2.0tとすると、厨芥の単位容積質量値として正しいものはどれか。","o":["400kg/m³","500kg/m³","600kg/m³","700kg/m³","800kg/m³"],"a":1,"e":"厨芥の質量は2,000kg×0.05＝100kg。単位容積質量値＝100kg÷0.20m³＝500kg/m³。","l":"計算","c":""},{"id":"2016-164","s":5,"q":"建築物内廃棄物の中間処理の方法について述べた次の文のうち、最も不適当なものはどれか。","o":["厨芥類を処理する生ごみ処理機には、減量のための乾燥機や、リサイクルのための堆肥化装置がある。","缶類の処理方法として、スチール缶とアルミ缶を自動で分けて圧縮し、ブロック状にする方式がある。","発泡スチロールの処理に使う溶融固化装置は、薬液を加えて溶かし固める方式である。","紙類の処理には、保管スペースを確保するため圧縮・梱包機が使われる。","厨芥類の保管には、保管用の冷蔵庫が多く使われている。"],"a":2,"e":"溶融固化装置は、熱を加えて溶かし固める方式である(2025年度問162でも正しい記述)。","l":"法令外","c":""},{"id":"2016-165","s":5,"q":"廃棄物の処理・保管などに関する組合せとして、最も不適当なものはどれか。","o":["容器方式 ― 初期費用が低い","貯留・排出機方式 ― 防災・防犯性が高い","真空収集方式 ― 初期費用が高い","コンパクタ・コンテナ方式 ― 小規模な建築物に向く","廃棄物計量管理システム ― テナントへの課金制度に使う"],"a":3,"e":"コンパクタ・コンテナ方式は大規模な建築物に向く方式である(2025年度問164で同じ内容が正答)。","l":"法令外","c":""},{"id":"2016-166","s":6,"q":"蚊の主な発生源に関する記述として、最も不適当なものはどれか。","o":["アカイエカは、下水溝や雨水ますで発生する。","ヒトスジシマカは、人工の容器や雨水ますで発生する。","シナハマダラカは、水田や湿地帯で発生する。","チカイエカは、浄化槽や湧水槽で発生する。","コガタアカイエカは、海岸線近くの汽水域で発生する。"],"a":4,"e":"コガタアカイエカの幼虫は、主に水田や湿地で発生する(2025年問166で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-167","s":6,"q":"蚊の防除に関する記述として、最も不適当なものはどれか。","o":["昆虫成長制御剤(IGR)は、成虫を殺す効果がない。","浄化槽の中の防除効果は、粘着トラップでとれた成虫の数で判定する。","殺虫剤を処理した後も浄化槽の成虫が減らない場合は、薬剤抵抗性が発達していることを考える必要がある。","ULV処理は、一般に成虫に対してすぐに効く力(速効性)が低い。","乳剤に含まれる界面活性剤や有機溶剤は、浄化槽の中の微生物に影響するおそれがある。"],"a":3,"e":"ULV処理は成虫に対する速効性が高い処理法であり、「低い」とした記述が誤り(2022年問166でも同じ記述が誤りとして出題)。","l":"法令外","c":""},{"id":"2016-168","s":6,"q":"ゴキブリに関する記述として、最も不適当なものはどれか。","o":["ゴキブリ類は、昼より夜に活発に活動する。","トビイロゴキブリの日本での分布は、限られた地域だけである。","ゴキブリ類が集まるのは、体節から出るホルモンの働きによる。","チャバネゴキブリが一生のうちに産卵する回数は、約5回である。","ゴキブリ類の食べ物の好みは、成長の段階によって変わらない。"],"a":2,"e":"ゴキブリ類の集合を体節から分泌されるホルモンの作用とした記述が誤り。","l":"法令外","c":""},{"id":"2016-169","s":6,"q":"ゴキブリの防除に関する記述として、最も適当なものはどれか。","o":["ゴキブリは部屋中を歩き回る習性があるので、殺虫剤の残留処理は部屋の内部の全面に行わなければならない。","7か所に3日間置いた粘着トラップでとれたゴキブリの合計が210匹の場合、ゴキブリ指数は20である。","毒餌を置くとき、毒餌に殺虫剤を噴霧すると効果が高まる。","燻煙処理を効果的に行うため、部屋の気密性を保ち、引出しや戸棚の戸を開けて、すみずみまで薬剤が行きわたるようにする。","有機リン剤は、ゴキブリ類に追い出し効果を示す。"],"a":3,"e":"燻煙処理では部屋の気密性を保ち、引出しや戸棚を開けて薬剤を行きわたらせる。なお(2)のゴキブリ指数は210÷7÷3=10である。","l":"法令外","c":""},{"id":"2016-170","s":6,"q":"ダニに関する記述として、最も適当なものはどれか。","o":["ダニの体は、頭部・顎体部・胴体部に分けられる。","マダニ類は、幼虫・若虫・成虫のすべての段階で吸血する。","ツメダニ類はヒトから吸血し、激しいかゆみを起こす。","タカラダニ類は、冬に鉢植えなどで発生する。","イエダニは、ペットによって室内に持ち込まれる。"],"a":1,"e":"マダニ類は、幼虫・若虫・成虫のすべての発育段階で吸血する(2022年問170でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-171","s":6,"q":"ハエ類に関する記述として、最も不適当なものはどれか。","o":["イエバエの主な発生源は、畜舎やごみ処理場である。","ニクバエ類は、卵ではなく幼虫を産む卵胎生のハエである。","クロバエ類は、気温の低い時期に発生する大型のハエである。","キンバエ類は、ハエ症の原因になる。","ショウジョウバエ類は、浄化槽の表面に浮いているスカムから大量に発生する。"],"a":4,"e":"ショウジョウバエ類が浄化槽のスカムから大量発生するとした記述が誤り。","l":"法令外","c":""},{"id":"2016-172","s":6,"q":"殺虫剤とその剤型に関する記述として、最も不適当なものはどれか。","o":["ピレスロイド剤を液化炭酸ガスに溶かした製剤がある。","ペルメトリンを有効成分とするゴキブリ用の食毒剤がある。","ジクロルボスを有効成分とする樹脂蒸散剤がある。","プロペタンホスを有効成分とするマイクロカプセル(MC)剤がある。","有機リン剤でノックダウンした虫は、生き返らずに死ぬことが多い。"],"a":1,"e":"ペルメトリンを有効成分とするゴキブリ用食毒剤があるとした記述が誤り。","l":"法令外","c":""},{"id":"2016-173","s":6,"q":"ネズミの防除に関する記述として、最も不適当なものはどれか。","o":["クマネズミをねらった毒餌は、植物性の餌を材料にする。","ネズミが入らないよう、ドアのまわりのすき間は1cm以内にする。","ドブネズミは警戒心が強く、毒餌やトラップでの防除が難しい。","ハツカネズミは、農村地帯や港湾地域に分布している。","防除の基本は、餌を絶つこと、巣をつくらせないこと、通り道をふさぐことである。"],"a":2,"e":"警戒心が強く防除が難しいのはクマネズミで、クマネズミはドブネズミより警戒心が強い(2025年問175で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-174","s":6,"q":"薬剤を使ったネズミの防除に関する記述として、最も不適当なものはどれか。","o":["ワルファリンに抵抗性をもつネズミに使う抗凝血性殺鼠剤として、ジフェチアロールがある。","カプサイシンには、処理した区域からネズミを追い出す効果がある。","シリロシドは、1回食べさせるだけで死に至らせる急性殺鼠剤である。","第1世代の抗凝血性殺鼠剤であるワルファリンやフマリンは、効き目がゆっくり現れる。","殺鼠剤で死んだネズミから悪臭やハエが出ることがあるので、死んだネズミをなるべく回収する。"],"a":1,"e":"カプサイシンは、ケーブルなどのかじり防止や、かじられた穴の修理に使われる(2021年問174で正しい記述として出題)。ネズミを追い出す効果をもつとした記述が誤り。","l":"法令外","c":""},{"id":"2016-175","s":6,"q":"感染症と衛生動物の組合せとして、最も不適当なものはどれか。","o":["レプトスピラ症 ― ネズミ類","重症熱性血小板減少症候群(SFTS) ― マダニ類","日本紅斑熱 ― アカイエカ","デング熱 ― ヒトスジシマカ","日本脳炎 ― コガタアカイエカ"],"a":2,"e":"日本紅斑熱を媒介するのはマダニ類である(2024年問177で正しい記述として出題)。","l":"法令外","c":""},{"id":"2016-176","s":6,"q":"衛生害虫と健康被害に関する記述として、最も不適当なものはどれか。","o":["コロモジラミは頭部に寄生するシラミで、血を吸われた後のかゆみが強い。","宿泊施設で、トコジラミによる吸血被害が問題になっている。","ヒョウヒダニ類は、小児喘息の原因になりうる。","日本でのノミの吸血被害は、ネコノミによるものが多い。","イエバエは、腸管出血性大腸菌O157を運ぶものとして注目されている。"],"a":0,"e":"コロモジラミを頭部に寄生するシラミとした記述が誤り。","l":"法令外","c":""},{"id":"2016-177","s":6,"q":"殺虫剤・殺鼠剤の毒性や安全性に関する記述として、最も不適当なものはどれか。","o":["衛生害虫用の殺虫剤は、医薬品医療機器等法の規制にもとづき、安全性・薬理・効力などの資料の審査を経て承認される。","薬剤のヒトや動物への安全性は、毒性の強さ、摂取量、摂取期間などで決まる。","薬剤を実験動物に与えて求めたLD50の値は、殺虫剤の急性毒性の評価基準になる。","殺鼠剤の多くは選択毒性が低く、ヒトにも強い毒性を示す成分が多い。","殺虫製剤には、毒薬にあたる毒性値を示すものが多い。"],"a":4,"e":"殺虫製剤に毒薬にあたる毒性値を示すものが多いとした記述が誤り。","l":"法令外","c":""},{"id":"2016-178","s":6,"q":"殺虫剤の処理や保管に関する記述として、最も不適当なものはどれか。","o":["建築物衛生法の特定建築物で殺虫剤によるゴキブリ防除を行う場合は、医薬品または医薬部外品として承認された薬剤を使わなければならない。","殺虫剤を散布する場合は、散布の前後3日間、そのことを利用者に知らせる。","殺虫剤の散布中に中毒が起きた場合は、氷などで体温を下げる。","乳剤や油剤を一定量以上保管する場合は、消防法にもとづく少量危険物倉庫の届出が必要になる。","煙霧処理やULV処理で、煙感知器が誤って作動することがある。"],"a":2,"e":"中毒を起こした場合に「氷などで体温を下げる」とした記述が誤り。なお(1)は建築物衛生法施行規則第4条の5第2項第2号の定めどおり。","l":"建築物衛生法施行規則 第4条の5第2項第2号(選択肢1)","c":""},{"id":"2016-179","s":6,"q":"建築物衛生法の特定建築物で行うねずみ等の防除に関する記述として、最も適当なものはどれか。","o":["IPM(総合的有害生物管理)で「警戒水準」とは、すぐに防除作業が必要な状況をさす。","環境的な対策は、PCO(ねずみ等の防除業者)が日ごろから行うこととされている。","調査は目視調査や聞き取り調査を中心に行い、トラップなどによる捕獲調査は必要ない。","食料を扱う区域など、ねずみ等が発生しやすい場所では、2か月以内ごとに発生状況の調査を行う。","防除は、発生時の対策に重点を置いて行う。"],"a":3,"e":"食料を扱う区域や排水槽・阻集器・廃棄物保管設備の周辺など、ねずみ等が発生しやすい場所は、2か月以内ごとに1回生息状況を調査する(告示第119号 第6の二)。","l":"平成15年厚生労働省告示第119号 第6の二","c":""},{"id":"2016-180","s":6,"q":"衛生害虫や殺虫剤に関する記述として、最も不適当なものはどれか。","o":["殺虫剤抵抗性は、同じ殺虫剤にさらされ続けることで、1世代のうちに発達する。","殺虫剤の基礎的な効力は、KT50・LD50・LC50などの値で評価される。","昆虫などへの不快感の程度は、第三者が客観的に判断するのは難しい。","農薬は、建築物衛生法の特定建築物での蚊の防除には使えない。","吸血害虫の中には、雌雄ともに吸血する種類がいる。"],"a":0,"e":"殺虫剤抵抗性が1世代のうちに発達するとした記述が誤り。なお特定建築物での防除に医薬品または医薬部外品を使うことは施行規則第4条の5第2項第2号に定めがある。","l":"建築物衛生法施行規則 第4条の5第2項第2号(選択肢4)","c":""},{"id":"2017-1","s":0,"q":"現在の行政組織について、最も適当なものはどれか。","o":["下水道事業を受け持つ省庁は、総務省と環境省である。","水質汚濁防止法を受け持つ省庁は、厚生労働省である。","労働衛生行政の地方組織として、都道府県ごとに都道府県労働局がある。","保健所には、労働基準監督官が置かれている。","建築基準法でいう特定行政庁とは、国土交通省のことである。"],"a":2,"e":"労働衛生行政は、国の機関である都道府県労働局と労働基準監督署が地方で受け持っている。下水道は国土交通省と環境省、水質汚濁防止法は環境省の所管である。","l":"法令外(厚生労働省設置法)","c":""},{"id":"2017-2","s":0,"q":"次の建物で、特定用途に使われる部分の延べ面積は( ア )m²となり、この建物は特定建築物に( イ )。(ア)(イ)の組合せとして正しいものはどれか。なお、A〜C社はお互いに関係がない。\n【建物の内訳】A社の事務所 2,000m²、B社の店舗 600m²、A社とB社の共用部分 200m²、B社の店舗の駐車場 400m²、C社の倉庫 300m²","o":["ア 3,500　イ 当たる","ア 3,200　イ 当たる","ア 3,100　イ 当たる","ア 2,800　イ 当たらない","ア 2,600　イ 当たらない"],"a":1,"e":"事務所2,000+店舗600+共用部分200+店舗の駐車場400=3,200m²。どの特定用途にも付属しないC社の倉庫は入れない。3,000m²以上なので特定建築物に当たる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2017-3","s":0,"q":"建築物衛生法施行令にある特定建築物の用途に「当たらないもの」の組合せはどれか。","o":["博物館と寄宿舎と旅館","図書館と遊技場","共同住宅と百貨店","集会場と旅館と図書館","寄宿舎と共同住宅"],"a":4,"e":"寄宿舎と共同住宅は、施行令の特定用途に含まれない。博物館・図書館・遊技場・百貨店・集会場・旅館は含まれる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2017-4","s":0,"q":"次の建築物のうち、特定建築物に当たらないものはどれか。","o":["延べ面積10,000m²の高等専門学校","延べ面積4,000m²の研修所","延べ面積9,000m²の幼保連携型認定こども園","延べ面積5,000m²の各種学校","延べ面積7,000m²の特別支援学校"],"a":4,"e":"特別支援学校は学校教育法第1条の学校なので、特定建築物になるのは延べ面積8,000m²以上の場合である。7,000m²では当たらない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2017-5","s":0,"q":"特定建築物の届出について、最も適当なものはどれか。","o":["用途の変更で特定建築物に当たらなくなったときは、届出をする必要がある。","届け出る特定建築物の名称は、建築確認のときの名称と同じでなければならない。","特定建築物の所有者等は、使い始めた日から1年以内に届け出る。","国や地方公共団体が使う特定建築物は、届出が免除される。","特定建築物の届出は、厚生労働大臣あてに行う。"],"a":0,"e":"用途の変更などで特定建築物に当たらなくなったときは、その日から1か月以内に届け出る。届出先は都道府県知事(保健所設置市・特別区は市長・区長)である。","l":"建築物衛生法 第5条第3項","c":""},{"id":"2017-6","s":0,"q":"備えておく帳簿書類についての次の文で、【 】の中の語句のうち誤っているものはいくつあるか。\n「建築物衛生法第10条の帳簿書類として、施行規則では次のものなどが定められている。\n① 空気環境の調整、給水及び排水の管理、清掃並びに【廃棄物処理】の状況(測定・検査の結果や設備の点検・整備の状況を含む)を書いた帳簿書類\n② 特定建築物の平面図・断面図と、維持管理に関する設備の【配置及び系統】を明らかにした図面\n③ その他その特定建築物の【維持管理】に関し環境衛生上必要な事項を書いた帳簿書類\nまた、①と③の帳簿書類は【10年間】保存しなければならない。」","o":["0個(なし)","1個","2個","3個","4個(すべて)"],"a":2,"e":"誤りは2つ。①は「ねずみ等の防除」の状況、保存期間は「5年間」が正しい。「配置及び系統」と「維持管理」は正しい。","l":"建築物衛生法施行規則 第20条","c":"出題時は「省令で次の3項目が規定されている」という文だったが、現在の施行規則第20条には管理技術者の兼任確認の結果を書いた書面も加わり4項目になったため、「次のものなどが定められている」と書き直した(正答は変わらない)。"},{"id":"2017-7","s":0,"q":"建築物環境衛生管理基準にもとづく空気環境の測定方法について、正しいものはどれか。","o":["6か月以内ごとに1回、定期に行う。","居室の中央部の床上75cm以上150cm以下の位置で行う。","温度は、午前と午後の測定値の平均を求める。","建物のふだんの使用時間中を避けて行う。","奇数階か偶数階ごとに行う。"],"a":1,"e":"測定は、ふだんの使用時間中に、各階ごとに、居室の中央部の床上75cm以上150cm以下の位置で、2か月以内ごとに1回行う。","l":"建築物衛生法施行規則 第3条の2","c":""},{"id":"2017-8","s":0,"q":"空気調和設備の病原体による汚染を防ぐための衛生上の措置として、誤っているものはどれか。","o":["冷却塔は、使い始めるときと、その後2か月以内ごとに1回、定期に汚れの点検をし、必要に応じて清掃や換水などを行う。","空気調和設備の中の排水受けは、使い始めるときと、その後1か月以内ごとに1回、定期に汚れや詰まりの点検をし、必要に応じて清掃する。","冷却塔と加湿装置に供給する水を、水道法第4条の水質基準に適合させるため必要な措置をとる。","冷却塔、冷却水の水管、加湿装置の清掃を、それぞれ1年以内ごとに1回、定期に行う。","加湿装置は、使い始めるときと、その後1か月以内ごとに1回、定期に汚れの点検をし、必要に応じて清掃する。"],"a":0,"e":"正しくは、冷却塔と冷却水の汚れの点検は、使用開始時と使用開始後「1か月以内ごとに1回」行う。","l":"建築物衛生法施行規則 第3条の18","c":""},{"id":"2017-9","s":0,"q":"建築物環境衛生管理基準にもとづく雑用水の衛生上の措置について、誤っているものはどれか。","o":["水洗便所に使う水からは、一般細菌が検出されないこと。","遊離残留塩素の検査を、7日以内ごとに1回、定期に行うこと。","水洗便所に使う水の外観の基準は、ほとんど無色透明であること。","給水栓の水の遊離残留塩素を、100万分の0.1以上に保つこと。","雑用水の水槽の点検など、有害物や汚水などで水が汚染されるのを防ぐための措置をとること。"],"a":0,"e":"雑用水の基準は「大腸菌が検出されないこと」であり、一般細菌は基準の項目ではない。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2017-10","s":0,"q":"事業の登録に必要な物的要件について、誤っているものはどれか。","o":["建築物飲料水水質検査業には、水質検査を的確に行える検査室が必要である。","建築物飲料水貯水槽清掃業には、機械器具として内視鏡・高圧ホース・洗浄ノズルが必要である。","建築物排水管清掃業には、機械器具を適切に保管できる専用の保管庫が必要である。","建築物ねずみ昆虫等防除業には、機械器具として真空掃除機、防毒マスク(または防毒機能をもつ電動ファン付き呼吸用保護具)、消火器が必要である。","建築物空気調和用ダクト清掃業には、機械器具として電子天びんまたは化学天びん、集じん機、真空掃除機が必要である。"],"a":1,"e":"内視鏡が必要なのは空気調和用ダクト清掃業である。貯水槽清掃業には、揚水ポンプ・高圧洗浄機・残水処理機・換気ファンなどが必要。","l":"建築物衛生法施行規則 第26条〜第29条","c":"選択肢(4)の「防毒マスク」は、現行の施行規則第29条で「防毒マスク又は防毒機能を有する電動ファン付き呼吸用保護具」となっているため、現行の言い方に合わせた(正答は変わらない)。"},{"id":"2017-11","s":0,"q":"建築物環境衛生総合管理業についての次の文の(ア)〜(ウ)に入る語句の組合せとして、正しいものはどれか。\n「総合管理業の業務は、( ア )、空気調和設備と機械換気設備の運転・日常的な点検・補修(運転等)と空気環境の測定、給水・排水の設備の運転等、給水栓の水に含まれる( イ )の検査と給水栓の水の色・濁り・臭い・味の検査であって、特定建築物の( ウ )に必要な程度のものである。」","o":["ア 清掃　イ 遊離残留塩素　ウ 衛生的環境の維持管理","ア 清掃　イ pH値　ウ 構造設備の保全管理","ア ねずみ等の防除　イ 遊離残留塩素　ウ 衛生的環境の維持管理","ア ねずみ等の防除　イ pH値　ウ 衛生的環境の維持管理","ア ねずみ等の防除　イ pH値　ウ 構造設備の保全管理"],"a":0,"e":"施行規則では、総合管理業の業務を、清掃、空調・換気設備の運転等と空気環境の測定、給排水設備の運転等、給水栓の遊離残留塩素の検査などで、特定建築物の衛生的環境の維持管理に必要な程度のものとしている。","l":"建築物衛生法施行規則 第24条","c":""},{"id":"2017-12","s":0,"q":"都道府県知事等による立入検査について、最も適当なものはどれか。","o":["特定建築物の立入検査は、前もって日時を知らせなければならない。","管理基準に従った維持管理がされていないときは、すぐに改善命令を出さなければならない。","特定建築物の立入検査は、犯罪捜査のために行う。","特定建築物の立入検査を行う職員を、環境衛生監視員という。","特定建築物の中の住居には、住んでいる人の承諾なしに強制的に立ち入ることができる。"],"a":3,"e":"立入検査の職権を行う職員は環境衛生監視員と呼ばれる。立入検査は犯罪捜査のためではなく、住居に入るには居住者の承諾が必要である。","l":"建築物衛生法 第11条、施行規則 第21条","c":""},{"id":"2017-13","s":0,"q":"国や地方公共団体が使う特定建築物についての次の文の(ア)〜(ウ)に入る語句の組合せとして、正しいものはどれか。\n「国や地方公共団体が使う特定建築物で、管理基準に従った維持管理がされず、人の健康を損なうなど環境衛生上とても不適当な事態があると認めるときは、都道府県知事は、その国・地方公共団体の( ア )者にその旨を通知するとともに、維持管理の方法の( イ )べきことを( ウ )することができる。」","o":["ア 建築物環境衛生管理技術　イ 掲示などで利用者に知らせる　ウ 勧告","ア 建築物環境衛生管理技術　イ 改善その他の必要な措置を採る　ウ 助言","ア 建築物環境衛生管理技術　イ 改善その他の必要な措置を採る　ウ 命令","ア 機関の長又はその委任を受けた　イ 掲示などで利用者に知らせる　ウ 助言","ア 機関の長又はその委任を受けた　イ 改善その他の必要な措置を採る　ウ 勧告"],"a":4,"e":"法第13条第3項では、知事は国・地方公共団体の機関の長またはその委任を受けた者に通知し、維持管理の方法の改善その他の必要な措置を採るべきことを勧告できると定めている。","l":"建築物衛生法 第13条第3項","c":""},{"id":"2017-14","s":0,"q":"保健所について、最も不適当なものはどれか。","o":["保健所は、人口動態統計の業務を行う。","全国の保健所のうち、都道府県が設置したものが最も多い。","保健所は、住宅の衛生に関する業務を行う。","保健所は、労働災害統計の業務を行う。","保健所は、地域保健に関する調査・研究を行う。"],"a":3,"e":"労働災害統計は労働行政の業務であり、保健所の業務ではない。","l":"地域保健法 第6条、第7条","c":""},{"id":"2017-15","s":0,"q":"学校保健安全法で、教室の空気の検査を職務として行う人はだれか。","o":["学校の設置者","学校薬剤師","学校医","校長","学校保健技師"],"a":1,"e":"教室の空気などの環境衛生検査に従事するのは、学校薬剤師の職務である。","l":"学校保健安全法施行規則 第24条","c":""},{"id":"2017-16","s":0,"q":"下水道法第1条の目的について、次の文の(ア)(イ)に入る語句の組合せとして、正しいものはどれか。\n「この法律は、流域別下水道整備総合計画の策定に関する事項と、公共下水道・流域下水道・都市下水路の設置その他の管理の基準などを定めて下水道の整備を図り、( ア )及び公衆衛生の向上に寄与し、あわせて公共用水域の( イ )に資することを目的とする。」","o":["ア 国民の生命・財産の保護　イ 水質の保全","ア 国民の生命・財産の保護　イ 環境の保護","ア 生活排水対策の実施の推進　イ 水質の保全","ア 生活排水対策の実施の推進　イ 環境の保護","ア 都市の健全な発達　イ 水質の保全"],"a":4,"e":"下水道法の目的は、都市の健全な発達及び公衆衛生の向上に寄与し、あわせて公共用水域の水質の保全に資することである。","l":"下水道法 第1条","c":""},{"id":"2017-17","s":0,"q":"興行場法についてのア〜オの記述のうち、誤っているものの組合せはどれか。\nア 興行場とは、映画・演劇・音楽・スポーツ・演芸・見せ物を、公衆に見せたり聞かせたりする施設をいう。\nイ 業として興行場を経営しようとする者は、都道府県知事(保健所設置市・特別区は市長・区長)に届け出なければならない。\nウ 興行場の営業者は、換気・照明・防湿・清潔その他入場者の衛生に必要な措置を講じなければならない。\nエ 入場者の衛生に必要な措置の基準は、厚生労働省令で定められている。\nオ 入場者は、場内をひどく不潔にするなど、公衆衛生に害を及ぼすおそれのある行為をしてはならない。","o":["アとイ","アとウ","イとエ","ウとオ","エとオ"],"a":2,"e":"イとエが誤り。興行場の経営には届出ではなく「許可」が必要で、入場者の衛生に必要な措置の基準は都道府県等の「条例」で定められる。","l":"興行場法 第2条、第3条","c":""},{"id":"2017-18","s":0,"q":"廃棄物の処理及び清掃に関する法律第1条の目的について、次の文の(ア)〜(ウ)に入る語句の組合せとして、正しいものはどれか。\n「この法律は、廃棄物の排出を抑え、廃棄物を適正に分別・保管・収集・運搬・再生・( ア )などの処理をし、( イ )することによって、( ウ )及び公衆衛生の向上を図ることを目的とする。」","o":["ア 焼却　イ 生活環境を清潔に　ウ 生活環境の保全","ア 焼却　イ 資源を有効に活用　ウ 経済の発展","ア 焼却　イ 良好な景観を形成　ウ 生活環境の保全","ア 処分　イ 生活環境を清潔に　ウ 生活環境の保全","ア 処分　イ 資源を有効に活用　ウ 経済の発展"],"a":3,"e":"廃棄物処理法第1条は、廃棄物の「処分」等の処理をし、「生活環境を清潔に」することにより、「生活環境の保全」及び公衆衛生の向上を図ることを目的としている。","l":"廃棄物の処理及び清掃に関する法律 第1条","c":""},{"id":"2017-19","s":0,"q":"事務所衛生基準規則第17条の便所の設置基準に定められていないものはどれか。","o":["流れ出るきれいな水を十分に供給する手洗い設備を設けること。","男性用小便所の数は、同時に働く男性労働者30人以内ごとに1個以上とすること。","女性用便所の便房の数は、同時に働く女性労働者20人以内ごとに1個以上とすること。","便所の中に、高齢者や障害者などが使いやすい構造の水洗器具を設けた便房を1個以上設けること。","男性用と女性用に区別すること。"],"a":3,"e":"高齢者・障害者などが使いやすい便房を設けることは、事務所衛生基準規則第17条には定められていない。","l":"事務所衛生基準規則 第17条","c":""},{"id":"2017-20","s":0,"q":"特定建築物の建築基準法での取扱いについて、次の文の(ア)〜(ウ)に入る語句の組合せとして、正しいものはどれか。\n「建築主事又は( ア )は、特定建築物に当たる建物の建築確認の申請書を受け取ったときは、遅れることなく、その建物の工事場所または所在地を管轄する( イ )に通知しなければならない。( イ )は、必要と認めるときは、許可や確認について、建築主事又は( ウ )に対して意見を述べることができる。」","o":["ア 指定確認検査機関　イ 保健所長　ウ 特定行政庁","ア 指定確認検査機関　イ 市町村長　ウ 特定行政庁","ア 都道府県知事　イ 保健所長　ウ 国土交通省","ア 都道府県知事　イ 市町村長　ウ 国土交通省","ア 都道府県知事　イ 市町村長　ウ 特定行政庁"],"a":0,"e":"特定建築物の確認申請を受け取った建築主事等や指定確認検査機関は保健所長に通知し、保健所長は特定行政庁や建築主事等に意見を述べることができる。","l":"建築基準法 第93条第5項・第6項","c":""},{"id":"2017-21","s":1,"q":"空気調和設備がある事務所について、事務所衛生基準規則の項目と基準値の組合せとして、最も不適当なものはどれか。","o":["二酸化炭素の含有率 ― 1,000ppm以下","気流 ― 0.5m/s以下","気温 ― 23〜28℃","相対湿度 ― 40〜70%","照度(一般的な事務作業) ― 300lx以上"],"a":2,"e":"事務所衛生基準規則では、空気調和設備がある場合、室の気温を18℃以上28℃以下にするよう努めることとされている。","l":"事務所衛生基準規則 第5条、第10条","c":"出題時の選択肢(5)は「照度(普通作業) 150lx以上」だったが、2022年12月施行の改正で照度の区分が「一般的な事務作業 300lx以上/付随的な事務作業 150lx以上」に変わったため、今の基準に直した。気温の下限も当時の17℃から今は18℃になっている(選択肢(3)は誤りのままで、正答は変わらない)。"},{"id":"2017-22","s":1,"q":"体の臓器系と病気の組合せとして、最も不適当なものはどれか。","o":["内分泌系 ― 腎不全","呼吸器系 ― 肺気腫","神経系 ― パーキンソン病","循環器系 ― 心筋梗塞","造血器系 ― 白血病"],"a":0,"e":"腎不全は、腎臓など泌尿器系の病気であり、内分泌系の病気ではない。","l":"法令外","c":""},{"id":"2017-23","s":1,"q":"体の機能の恒常性について、最も不適当なものはどれか。","o":["有害なストレッサーは恒常性を乱し、病気の発症や経過に影響する。","フィードバックの仕組みによって、体の機能の恒常性が壊れる。","熱射病は、高温にさらされて体温調節機能が壊れることで起こる。","恒常性は、神経系・内分泌系・免疫系などのはたらきで保たれている。","ストレスによる影響は、人によって大きく違う。"],"a":1,"e":"フィードバックの仕組みは、体の状態を一定に保つ(恒常性を維持する)ためにはたらくものである。","l":"法令外","c":""},{"id":"2017-24","s":1,"q":"次の温熱環境指数のうち、人体の熱のつり合いの式をもとにし、着衣量やエネルギー代謝量を使って求めるものはどれか。","o":["予測平均温冷感申告(PMV)","不快指数(DI)","修正有効温度(CET)","黒球温度(Tg)","湿球黒球温度(WBGT)"],"a":0,"e":"PMVは、人体の熱平衡式をもとに、気温・湿度・気流・放射に加えて着衣量と代謝量の6要素から求める指標である。","l":"法令外","c":""},{"id":"2017-25","s":1,"q":"エネルギー代謝について、最も不適当なものはどれか。","o":["基礎代謝とは、朝起きてすぐの空腹時に、あお向けに寝た姿勢でのエネルギー代謝のことである。","日本人の30歳代の平均基礎代謝量は、男性2,650kcal/日、女性1,950kcal/日である。","安静時の代謝量は、基礎代謝のおよそ20%増しである。","体の熱は、食べた物の代謝による化学的エネルギーから生まれる。","眠っているときのエネルギー消費量は、基礎代謝量より低い。"],"a":1,"e":"この記述が誤り。示された数値は30歳代の平均基礎代謝量としては大きすぎる。","l":"法令外","c":""},{"id":"2017-26","s":1,"q":"建物の中の湿度が低いことによる影響として、最も不適当なものはどれか。","o":["ほこりが舞い上がりやすくなる。","インフルエンザウイルスが生き残りやすくなる。","静電気が起きる。","体感温度が上がる。","皮膚や粘膜が乾燥する。"],"a":3,"e":"湿度が低いと汗が蒸発しやすくなるため、体感温度は下がる。体感温度が上がるのは湿度が高いとき。","l":"法令外","c":""},{"id":"2017-27","s":1,"q":"シックビル症候群でみられる症状として、最も不適当なものはどれか。","o":["めまい","頭痛","下痢","息切れ","疲れた感じ"],"a":2,"e":"シックビル症候群では、目・鼻・のどの刺激、頭痛、めまい、息切れ、疲労感などがみられるが、下痢は代表的な症状ではない。","l":"法令外","c":""},{"id":"2017-28","s":1,"q":"アスベストについて、最も適当なものはどれか。","o":["人工的に合成された化学物質である。","過去に断熱材として建物に使われたが、今は残っていない。","過敏性肺炎の原因になる。","労働安全衛生法により、試験研究用を除いて使用が禁止されている。","健康障害は、アスベスト製品をつくる工場の従業員だけに起こる。"],"a":3,"e":"アスベストは労働安全衛生法(施行令)で、試験研究用などを除いて製造・使用が禁止されている。","l":"労働安全衛生法 第55条、同施行令 第16条","c":""},{"id":"2017-29","s":1,"q":"アレルギー疾患について、最も不適当なものはどれか。","o":["湿度が低いことは、アトピー性皮膚炎を悪化させる要因である。","真菌(カビ)は、アレルゲンになる。","花粉症は、アレルギー疾患である。","アレルゲンを特定することは、症状を防いだり治療したりするうえで大切である。","湿度が低いと、気管支喘息の症状がやわらぐ。"],"a":4,"e":"湿度が低いことは、気管支喘息を悪化させる要因である。","l":"法令外","c":""},{"id":"2017-30","s":1,"q":"ホルムアルデヒドについて、最も不適当なものはどれか。","o":["シックハウス症候群と関係がある。","たばこの煙の中にある。","刺激が少ない。","発がん性が認められる。","建築物衛生法で室内の基準値が定められている。"],"a":2,"e":"ホルムアルデヒドは、目や鼻・のどの粘膜への刺激が強い物質である。","l":"法令外","c":""},{"id":"2017-31","s":1,"q":"オゾンについて、最も不適当なものはどれか。","o":["光化学オキシダントの主な成分である。","特有のにおいがある。","紫外線による光化学反応でできる。","静電式のコピー機は、発生源になる。","水に溶けやすい。"],"a":4,"e":"オゾンは水に溶けにくい(2023年度問31でも「水に溶けにくい」が正しい記述とされている)。","l":"法令外","c":""},{"id":"2017-32","s":1,"q":"一酸化炭素について、最も適当なものはどれか。","o":["ヘモグロビンとの結びつきやすさは、酸素と同じくらいである。","日本では、大気汚染物質としての環境中の濃度が増えている。","特有のにおいがある。","たばこを吸うことで発生する。","建築物衛生法の基準値は、1ppm以下である。"],"a":3,"e":"一酸化炭素は、たばこなど物が不完全に燃えるときに発生する。無色・無臭で、ヘモグロビンとの結びつきは酸素の200倍以上強い。建築物衛生法の基準値は6ppm以下。","l":"建築物衛生法施行令 第2条第1号イ","c":""},{"id":"2017-33","s":1,"q":"呼吸中枢が刺激されて、呼吸の増加、脈拍・血圧の上昇、頭痛、めまいなどの症状が出るときの二酸化炭素濃度として、最も適当なものはどれか。","o":["500ppm","1,000ppm","5,000ppm","10,000ppm","40,000ppm"],"a":4,"e":"二酸化炭素濃度が3〜4%(30,000〜40,000ppm)になると、呼吸の増加、脈拍・血圧の上昇、頭痛、めまいなどが起こる。","l":"法令外","c":""},{"id":"2017-34","s":1,"q":"騒音について、最も不適当なものはどれか。","o":["住民の騒音の苦情の大半は、聞きとりの妨げと心理的影響による。","超音波は、強い場合には耳鳴り・頭痛・吐き気などの体への影響を起こす。","大きく高い騒音に一時的にさらされて起こる聴力低下は、一時的なことが多く、安静にすれば戻る。","一般の環境騒音では、1日の等価騒音レベルが70dB未満なら、永久的な聴力障害はほとんど起こらない。","騒音で自律神経が刺激されると、末梢の血管が広がり、血圧が下がる。"],"a":4,"e":"騒音で自律神経(交感神経)が刺激されると、末梢の血管は縮み、血圧は上がる。","l":"法令外","c":""},{"id":"2017-35","s":1,"q":"振動について、最も不適当なものはどれか。","o":["全身振動による健康影響として、末梢神経障害がある。","手で持つ工具などの振動は、オクターブバンドの中心振動数で約8〜1,000Hzの振動が問題になる。","全身振動の大きさの感じ方は、振動が続く時間によって変わる。","振動を感じる最小の値(振動感覚閾値)は、地震の震度0(無感)の限界にあたる振動レベル55dBである。","振動数が低く振幅が大きい振動では、乗り物酔いや動揺病などが起こりやすい。"],"a":0,"e":"末梢神経障害(手指のしびれなど)は、手持ち工具などによる局所振動で起こる健康影響である。","l":"法令外","c":""},{"id":"2017-36","s":1,"q":"光と色の知覚について、最も適当なものはどれか。","o":["網膜の視細胞には杆体細胞と錐体細胞があり、錐体細胞はロドプシンを含んでいて光への感度がとても高い。","網膜の錐体細胞は解像力に優れ、色を感じるのに必要な化学物質を含んでいる。","明るい所から暗い所への順応を暗順応といい、およそ2分ほどで順応が終わる。","網膜の錐体細胞には、赤・青・黄の光にそれぞれ反応する3種類がある。","見る対象を正確に認識することを明視といい、その条件は大きさと明るさの2つである。"],"a":1,"e":"錐体細胞は解像力に優れ、色を感じる物質を含む。ロドプシンを含み感度が高いのは杆体細胞、暗順応には長い時間がかかり、錐体は赤・緑・青に反応する。","l":"法令外","c":""},{"id":"2017-37","s":1,"q":"VDT作業(情報機器作業)と健康について、最も不適当なものはどれか。","o":["VDT作業では、ふだん使っている遠近両用メガネを使えば、目の疲れを防げる。","VDT作業では、画面を見つめるため、まばたきの回数が減る。","視野の中に輝度の高いものがあると網膜の感度が下がり、疲れにつながる。","厚生労働省のガイドラインでは、ディスプレイ画面上の照度は500lx以下とされている。","VDT作業者の健康調査で最も多い自覚症状は、目に関するものである。"],"a":0,"e":"遠近両用メガネは画面を見る距離に合わないことがあり、無理な姿勢や目の疲れの原因になるため、作業に合ったメガネを使う必要がある。","l":"法令外(情報機器作業における労働衛生管理のためのガイドライン)","c":""},{"id":"2017-38","s":1,"q":"紫外線のはたらきとして、最も不適当なものはどれか。","o":["皮膚の悪性黒色腫が起こる","熱中症が起こる","白内障が起こる","電気性眼炎が起こる","殺菌作用"],"a":1,"e":"熱中症の原因になるのは赤外線(熱)である。紫外線は皮膚がん、白内障、電気性眼炎の原因となり、殺菌作用もある。","l":"法令外","c":""},{"id":"2017-39","s":1,"q":"電離放射線について、最も適当なものはどれか。","o":["β線は、鉛や鉄の板を通り抜ける。","放射線が体に与える影響の単位は、シーベルト(Sv)である。","放射線の健康影響のうち、がんへの影響には閾値がある。","放射線の影響を最も受けやすい細胞は、神経細胞である。","胸のX線検査1回で受ける線量は、自然放射線から1年間に受ける線量の世界平均より多い。"],"a":1,"e":"放射線が体に与える影響の大きさはシーベルト(Sv)で表す。β線は薄い金属板で止まり、がんは閾値のない確率的影響、感受性が最も高いのはリンパ球である。","l":"法令外","c":""},{"id":"2017-40","s":1,"q":"環境基本法の水質汚濁に係る環境基準で、人の健康の保護に関する項目に含まれていないものはどれか。","o":["全シアン","ヒ素","ホルムアルデヒド","ベンゼン","トリクロロエチレン"],"a":2,"e":"ホルムアルデヒドは、水質汚濁に係る環境基準の健康項目に含まれていない。","l":"水質汚濁に係る環境基準(環境基本法 第16条にもとづく告示)","c":""},{"id":"2017-41","s":1,"q":"水銀について、最も不適当なものはどれか。","o":["一般に、有機水銀と無機水銀に分けられる。","有機水銀は、生物濃縮を起こすことが知られている。","水俣病は、メチル水銀による公害病である。","重要な影響の一つに、中枢神経の障害がある。","皮膚がんの原因になることが知られている。"],"a":4,"e":"皮膚がんの原因として知られているのはヒ素などであり、水銀の代表的な健康影響は中枢神経の障害である。","l":"法令外","c":""},{"id":"2017-42","s":1,"q":"感染症と病原体の種類の組合せとして、最も適当なものはどれか。","o":["麻しん ― ウイルス","ワイル病 ― 真菌","カンジダ症 ― 細菌","つつが虫病 ― 原虫","クリプトスポリジウム症 ― リケッチア"],"a":0,"e":"麻しんはウイルスによる。ワイル病は細菌(レプトスピラ)、カンジダ症は真菌、つつが虫病はリケッチア、クリプトスポリジウム症は原虫による。","l":"法令外","c":""},{"id":"2017-43","s":1,"q":"水系感染症の特徴について、最も適当なものはどれか。","o":["一般に、特定の年齢層や職業に集中して起こる。","一般に重い例が多く、死亡する割合が高い。","起こるのは、おおむね梅雨から夏に限られる。","最初の患者が出てから数日で、爆発的に患者が増える。","一般に、水の汚染が証明・確定されることは少ない。"],"a":3,"e":"水系感染症は、同じ水を使う人に一斉に広がるため、最初の患者から数日で爆発的に患者が増える。年齢・職業・季節に関係なく起こり、軽症例が多い。","l":"法令外","c":""},{"id":"2017-44","s":1,"q":"ノロウイルスについて、最も不適当なものはどれか。","o":["ヒトからヒトへ感染する。","感染しても発症しない場合がある。","潜伏期間は1週間である。","ノロウイルス感染症は、冬を中心に起こる。","ノロウイルス感染症の主な症状は、嘔吐・下痢などである。"],"a":2,"e":"ノロウイルスの潜伏期間は、1〜2日程度と短い。","l":"法令外","c":""},{"id":"2017-45","s":1,"q":"10%溶液として売られている次亜塩素酸ナトリウムを水で薄めて、50mg/Lの溶液を80Lつくるとき、必要な10%溶液の量に最も近いものはどれか。","o":["0.4mL","1.6mL","4mL","16mL","40mL"],"a":4,"e":"必要な有効成分は50mg/L×80L=4,000mg=4g。10%溶液なので 4g÷0.1=40g(約40mL)。","l":"法令外(計算)","c":""},{"id":"2017-46","s":2,"q":"用語と単位の組合せのうち、誤っているものはどれか。","o":["音の強さ ― W/m²","熱量 ― J","色温度 ― K","立体角 ― sr","光度 ― cd/m²"],"a":4,"e":"光度の単位はcd(カンデラ)。cd/m²は、光度を見かけの面積で割った輝度の単位である(2021年度問89参照)。","l":"法令外","c":""},{"id":"2017-47","s":2,"q":"湿り空気について述べた次の文のうち、最も不適当なものはどれか。","o":["相対湿度が同じなら、温度が低い方が比エンタルピーは大きい。","絶対湿度を変えずに温度を下げると、相対湿度は上がる。","乾球温度が同じなら、絶対湿度が上がると水蒸気分圧は上がる。","絶対湿度が下がると、露点温度は下がる。","比エンタルピーが同じなら、温度が高い湿り空気の方が、温度が低い湿り空気より絶対湿度は低い。"],"a":0,"e":"相対湿度が同じなら、温度が高い方が含む水蒸気も多く、比エンタルピーは大きい(2023年度問48でも正しい記述)。","l":"法令外","c":""},{"id":"2017-48","s":2,"q":"湿気について述べた次の文のうち、最も不適当なものはどれか。","o":["冬の戸建住宅では、外気に面した壁の出隅部分の室内側で表面結露が起きやすい。","室内で家具などを外壁にくっつけて置くと、結露防止に効果がある。","断熱が部分的に途切れて熱橋になった部分は結露しやすい。","壁の内部結露を防ぐには、水蒸気分圧の高い側に防湿層を設けるのが有効である。","室内で出る水蒸気の量を必要以上に増やさないことが、結露防止に大切である。"],"a":1,"e":"家具を外壁に密着させると、裏側の壁の温度が下がって結露しやすくなる(2024年度問49で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-49","s":2,"q":"建築材料の表面の長波長放射率と日射吸収率について述べた次の文のうち、最も不適当なものはどれか。ただし値の大小は0.5より大きいか小さいかで判断する。","o":["酸化した亜鉛鉄板は、日射吸収率が小さく、長波長放射率も小さい。","光ったアルミ箔は、日射吸収率が小さく、長波長放射率も小さい。","黒色ペイントは、日射吸収率が大きく、長波長放射率も大きい。","新しい亜鉛鉄板は、日射吸収率が大きく、長波長放射率が小さい。","白色ペイントは、日射吸収率が小さく、長波長放射率が大きい。"],"a":0,"e":"酸化した亜鉛鉄板は日射吸収率が大きい(2025年度問50で「光ったアルミ箔より日射吸収率が大きい」とされている)。日射吸収率が小さいとするこの記述が誤り。","l":"法令外","c":""},{"id":"2017-50","s":2,"q":"エアロゾル粒子の相当径には幾何相当径と物理相当径がある。幾何相当径に分類されるものはどれか。","o":["光散乱径","電気移動度径","円等価径","ストークス径","空気力学径"],"a":2,"e":"円等価径は、粒子の投影面積と同じ面積の円の直径で、形から決める幾何相当径(2022年度問57で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-51","s":2,"q":"エアロゾル粒子の壁面への沈着と再飛散について述べた次の文のうち、最も不適当なものはどれか。","o":["再飛散とは、沈着した粒子が壁から離れて再び空気中に取り込まれる現象である。","層流でストークス領域の粒子は、一定の室内気流のもとでは再飛散がほとんどない。","沈着速度とは、粒子が壁に沈着するときにぶつかる速さである。","粒子が表面に付く力には、ファンデルワールス力がある。","気流と平行な鉛直の壁への沈着数は、濃度が同じなら小さい粒子ほど多い。"],"a":2,"e":"沈着速度は、単位時間あたりの沈着量を空気中の濃度で割った値である(2023年度問58でも正しい記述)。ぶつかる速さではない。","l":"法令外","c":""},{"id":"2017-52","s":2,"q":"流体の基礎についての次の文の[ア]〜[ウ]に入る語句の組合せとして、正しいものはどれか。\n「流管の2つの断面A・Bの間で流れの力学的エネルギーが保存されると考えると、(1/2)ρUA²＋PA＋ρghA＝(1/2)ρUB²＋PB＋ρghB が得られる。この式は[ア]と呼ばれ、各辺の第1項を[イ]、第2項を[ウ]、第3項を位置圧という。」(ρ:密度、U:速度、P:圧力、g:重力加速度、h:高さ)","o":["ア ベルヌーイの定理/イ 動圧/ウ 静圧","ア ベルヌーイの定理/イ 静圧/ウ 動圧","ア ベルヌーイの定理/イ 動圧/ウ 絶対圧","ア 連続の式/イ 動圧/ウ 静圧","ア 連続の式/イ 動圧/ウ 絶対圧"],"a":0,"e":"力学的エネルギーの保存を表す式はベルヌーイの定理で、第1項が動圧、第2項が静圧(2024年度問51でも同じ内容)。連続の式は質量の保存を表す式である。","l":"法令外","c":""},{"id":"2017-53","s":2,"q":"室内の気流について述べた次の文のうち、最も不適当なものはどれか。","o":["置換換気は、室温より少し低い空気を床近くから低速で供給し、天井近くで排気する方式である。","コールドドラフトは、冷たい壁の近くなどで自然対流による下降流が原因で起きることがある。","ドラフトとは不快な局部的な気流のことで、風速、気流変動の大きさ、空気温度の影響を受ける。","壁の上部から水平に吹き出す空調方式では、冷房時に居住域に空気のよどみができ、上下の温度差が大きくなりやすい。","天井中央付近から下向きに吹き出す空調方式では、冷房時に冷気が床近くに広がり、室の上部によどみができやすい。"],"a":3,"e":"壁の上部から水平に吹き出す方式で居住域によどみができ上下温度差が大きくなりやすいのは、暖かい空気が上にたまる暖房時である(2023年度問53でも暖房時として正しい記述)。","l":"法令外","c":""},{"id":"2017-54","s":2,"q":"室内の温度と湿度について述べた次の文のうち、最も不適当なものはどれか。","o":["暖房期の低湿度の改善は、室内空気環境の管理にかかわる大きな課題である。","同じ室内でも温度は上下にも水平にも多少ばらつくことが多く、差が小さければ問題ないが、大きいと不快感や生理的障害の原因になる。","東京都が建築確認申請時に審査した建築物で採用された加湿方式は、近年、水スプレーの割合がほかの方式より最も多い。","東京都の調査では、室内温度の不適率は近年3〜4%と低く推移してきたが、平成23年度は節電の影響もあり2割近くが不適だった。","室内の空気中の水分量そのものの空間的なばらつきは比較的小さい。"],"a":2,"e":"この記述が誤り。近年の採用割合が最も多い加湿方式は水スプレーではない。","l":"法令外","c":""},{"id":"2017-55","s":2,"q":"空気汚染物質の特徴を示した次のア〜エのうち、ホルムアルデヒドの特徴にあたるものの組合せとして最も適当なものはどれか。\nア 常温で淡黄色の気体である。\nイ 発生源には、複合フローリング材や合板などがある。\nウ 人為的な発生より、火山や森林火災など自然発生の量が多いと推定されている。\nエ 水に溶ける有機化合物である。","o":["アとイ","アとウ","イとウ","イとエ","ウとエ"],"a":3,"e":"ホルムアルデヒドは無色の気体で(2022年度問56)、合板や複合フローリングから出て、水によく溶ける(水溶液がホルマリン)。","l":"法令外","c":""},{"id":"2017-56","s":2,"q":"空気汚染物質と発生源の組合せとして、最も不適当なものはどれか。","o":["一酸化炭素 ― 自動車の排気","パラジクロロベンゼン ― 防虫剤","窒素酸化物 ― ガスストーブ","フューム ― 断熱材","タール ― たばこ煙"],"a":3,"e":"フュームは溶接などで金属が蒸発・凝縮してできる微粒子で、断熱材から出るものではない。","l":"法令外","c":""},{"id":"2017-57","s":2,"q":"喫煙室で1時間に15本のたばこが吸われているときの、定常状態の粉じん濃度に最も近いものはどれか。\n局所換気以外の換気システムはなく、局所換気で排出される空気量は200m³/h。たばこで出た粉じんの80%は局所換気で直接排気され、残りは喫煙室全体に一様に広がって喫煙室の空気として排気される。たばこ1本あたりの粉じん発生量は10mg、喫煙室に入ってくる空気の粉じん濃度は0.05mg/m³とし、たばこ以外の粉じん発生や壁への吸着などは無視できる。","o":["0.15mg/m³","0.20mg/m³","0.30mg/m³","0.75mg/m³","0.80mg/m³"],"a":1,"e":"発生量は15×10＝150mg/h。そのうち室内に広がるのは20%の30mg/h。室内濃度＝入ってくる空気の濃度＋室内発生量÷換気量＝0.05＋30÷200＝0.20mg/m³。","l":"計算","c":""},{"id":"2017-58","s":2,"q":"におい物質についての次の文の[(1)]〜[(5)]の語句のうち、最も不適当なものはどれか。\n「におい物質は、[(1)揮発性、化学反応性]に富む比較的[(2)低分子]の[(3)有機化合物]である。におい成分をつくる元素として、[(4)炭素(C)]、水素(H)、酸素(O)、窒素(N)、硫黄(S)、塩素(Cl)が挙げられる。臭気強度＝比例定数×[(5)臭気物質濃度]の関係が成り立つ。」","o":["揮発性、化学反応性","低分子","有機化合物","炭素(C)","臭気物質濃度"],"a":4,"e":"人の感覚の強さは刺激の対数に比例する(ウェーバー・フェヒナーの法則)ので、臭気強度＝比例定数×log(臭気物質濃度)となる。濃度そのものに比例するのではない。","l":"法令外","c":""},{"id":"2017-59","s":2,"q":"アレルゲンと微生物について述べた次の文のうち、最も不適当なものはどれか。","o":["建築物衛生法では、ダニまたはダニアレルゲンに関する基準を定めている。","酵母は真菌に分類される。","ウイルスは、生きている細胞の中でしか増えられない。","ペニシリウムは、アレルギー症状を起こす原因物質の一つである。","ダニアレルゲンの大部分は、数μm以上の粒子である。"],"a":0,"e":"建築物衛生法の空気環境の管理基準(施行令第2条)は、浮遊粉じん・一酸化炭素・二酸化炭素・温度・相対湿度・気流・ホルムアルデヒドで、ダニやダニアレルゲンの基準はない。","l":"建築物衛生法施行令 第2条","c":""},{"id":"2017-60","s":2,"q":"冷房時における単一ダクト方式の空気調和システムを図-Aに示す。図-Bは、図-Aのa〜eにおける空気の状態変化を湿り空気線図上に表したものである。図-A中のdに相当する図-B中の状態点はどれか。","o":["ア","イ","ウ","エ","オ"],"a":3,"e":"外気a=ア、室内e=ウ、その混合b=イ。冷却器で冷やして除湿した点c=オ、そのあと加熱器で温め直して(絶対湿度はそのまま)吹き出すのがd=エ。","l":"法令外","c":"","g":["img/2017-60.png"]},{"id":"2017-61","s":2,"q":"湿り空気線図(h-x線図)で相対湿度を求めるときに使う2つの項目の組合せとして、最も不適当なものはどれか。","o":["乾球温度と湿球温度","湿球温度と絶対湿度","比エンタルピーと乾球温度","露点温度と比エンタルピー","絶対湿度と露点温度"],"a":4,"e":"露点温度は絶対湿度だけで決まるので、絶対湿度と露点温度は同じ情報を表しており、2つでは状態点が決まらない(2025年度問61参照)。","l":"法令外","c":""},{"id":"2017-62","s":2,"q":"平成15年の改正で、建築物衛生法施行令第2条から「中央管理方式の」という文言が削られた。その理由や結果について述べた次の文のうち、最も不適当なものはどれか。","o":["個別方式の空気調和設備が、比較的大規模な建築物にも採用されるようになったという背景がある。","中央管理方式の空気調和設備は、個別方式より換気量不足による室内空気汚染が起きやすいと心配される。","個別方式の空気調和設備は湿度管理が難しく、冬に低湿度になりがちである。","空気調和方式が個別方式か中央管理方式かにかかわらず、同じ管理基準で適切に維持管理する必要がある。","空気調和方式の個別方式と中央管理方式の区別がはっきりしなくなってきた。"],"a":1,"e":"換気量不足が心配されたのは、外気を取り入れる機能をもたないことが多い個別方式の方である(2023年度問59・2025年度問76参照)。現行の施行令第2条も「空気調和設備を設けている場合」として方式を区別していない。","l":"建築物衛生法施行令 第2条","c":""},{"id":"2017-63","s":2,"q":"次の空調熱負荷のうち、潜熱負荷を含むものはどれか。","o":["構造体負荷","ガラス面負荷","すき間風負荷","ダクトでの負荷","ポンプによる負荷"],"a":2,"e":"すき間風は水蒸気を含む外気が入ってくるので、顕熱と潜熱の両方の負荷がある(外気負荷と同じ。2024年度問61参照)。","l":"法令外","c":""},{"id":"2017-64","s":2,"q":"ダクト併用ファンコイルユニット方式について述べた次の文のうち、最も不適当なものはどれか。","o":["単一ダクト方式にファンコイルユニットを組み合わせて、個別に制御しやすくしたシステムである。","ファンコイルユニットごとに運転・停止できる。","ファンコイルユニットは、熱負荷の変動が小さいインテリアゾーンに置かれることが多い。","単一ダクト方式より、空気調和機や主ダクトを小さくできる。","ダクトからの吹出し空気とファンコイルからの吹出し空気が混ざって、混合損失が出ることがある。"],"a":2,"e":"ファンコイルユニットは、外の影響で熱負荷が大きく変わるペリメータゾーンに置かれることが多い(2022年度問60でも正しい記述)。","l":"法令外","c":""},{"id":"2017-65","s":2,"q":"個別方式の空気調和設備について述べた次の文のうち、最も不適当なものはどれか。","o":["分散設置の水熱源ヒートポンプ方式では、一般に冷房運転と暖房運転を混在させることはできない。","圧縮機を動かす力には、電力によるものとガスエンジンによるものがある。","ふつうは外気処理能力をもたないので、外調機などの外気処理装置と組み合わせるなどの対策が必要である。","分散設置空気熱源方式のマルチ型では、1台の室外機に複数の室内機がつながる。","分散設置空気熱源ヒートポンプ方式では、インバーターで容量制御する機種が増え、部分負荷効率がよくなった。"],"a":0,"e":"分散設置の水熱源ヒートポンプ方式は、冷房と暖房が混在するときに熱回収運転ができる(2023年度問59でも正しい記述)。","l":"法令外","c":""},{"id":"2017-66","s":2,"q":"空気調和設備の熱源方式の特徴について述べた次の文のうち、最も不適当なものはどれか。","o":["ガスエンジンヒートポンプ方式は、エンジンの排熱を回収して活用できるので、寒冷地の暖房熱源に向いている。","吸収冷凍機と蒸気ボイラを組み合わせる方式は、病院やホテルでよく採用される。","電動冷凍機とボイラを組み合わせる方式は、1年を通して電力消費量の変化が小さい。","直焚吸収冷温水機は、1台で冷水か温水、またはその両方を同時につくれる。","電力需要を中心に運転するコージェネレーション方式では、空調などの熱需要に追いつけない場合がある。"],"a":2,"e":"電動冷凍機とボイラの組合せでは、冷房に電力を使う夏に電力消費がピークとなり、季節による差が大きい(2021年度問66・2025年度問65参照)。","l":"法令外","c":""},{"id":"2017-67","s":2,"q":"蒸気圧縮式冷凍機を構成する機器として、最も不適当なものはどれか。","o":["圧縮機","凝縮器","膨張弁","吸収器","蒸発器"],"a":3,"e":"蒸気圧縮式冷凍機は、圧縮機・凝縮器・膨張弁・蒸発器でできている(2024年度問67参照)。吸収器は吸収冷凍機の機器である。","l":"法令外","c":""},{"id":"2017-68","s":2,"q":"ボイラについて述べた次の文のうち、最も不適当なものはどれか。","o":["炉筒煙管ボイラは、直径の大きな横型ドラムを本体とし、燃焼室と煙管群でできている。","鋳鉄製ボイラは、スケールを防ぐため、装置の系統を開放系として設計・使用する。","貫流ボイラは、水管壁で囲まれた燃焼室と、水管群による対流伝熱面でできている。","真空式温水発生機では、真空中で水蒸気を発生させて熱交換器に熱を伝える。","真空式温水発生機は、容量に関係なくボイラの取扱い資格がいらない。"],"a":1,"e":"鋳鉄製ボイラは、スケールを防ぐため密閉系で設計・使用する(2020年度問68でも正しい記述)。","l":"法令外","c":""},{"id":"2017-69","s":2,"q":"空気調和機を構成する機器について述べた次の文のうち、最も不適当なものはどれか。","o":["エアハンドリングユニットは、熱源設備から送られる冷水・温水・蒸気などで空調空気をつくり、ダクトで各ゾーン・各室に送る。","パッケージ型空調機のセパレート型は、一般に、圧縮機と膨張弁を収めた室外機と、蒸発器・凝縮器と送風機を収めた室内機でできている。","ファンコイルユニットは、送風機、熱交換器、エアフィルタとケーシングでできた室内設置用の小型空調機である。","ターミナルエアハンドリングユニットは小風量タイプで、機械室を使わず天井隠ぺい型などとして設置でき、個別に制御しやすい。","冷房専用のパッケージ型空調機は、凝縮器の冷やし方によって水冷型と空冷型に分けられる。"],"a":1,"e":"セパレート型では、熱を捨てる凝縮器は圧縮機とともに室外機に入り、室内機には蒸発器と送風機が入る。凝縮器を室内機に収めるのではない。","l":"法令外","c":""},{"id":"2017-70","s":2,"q":"空気調和設備の加湿装置・減湿(除湿)装置について述べた次の文のうち、最も不適当なものはどれか。","o":["空気調和機内の冷却コイルの表面で結露させて減湿するのは、標準的な冷却減湿法である。","吸収減湿法では、塩化リチウムや塩化カルシウムなどの水溶液を使って減湿する。","空気を圧縮・冷却して結露させて除湿し、乾燥空気をつくるのは圧縮減湿法である。","蒸気吹出方式の加湿では、加湿装置によって空気が微生物で汚染されることがある。","気化式の加湿装置では、温度が下がる。"],"a":3,"e":"蒸気式は水を沸騰させた蒸気を使うので、微生物で空気を汚染するおそれはない(2023年度問71で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-71","s":2,"q":"熱交換器について述べた次の文のうち、最も不適当なものはどれか。","o":["回転型全熱交換器(空気-空気)は、吸湿性のあるエレメントでできたロータに対して流れる給気と排気の間で熱交換する。","顕熱交換器(空気-空気)の給排気の仕切りには湿気を通さない金属エレメントなどが使われ、寒冷地での熱回収などに使われる。","ヒートパイプ(空気-空気)は、中に封入した作動流体が蒸発と凝縮をくり返して熱を運ぶ。","プレート式熱交換器(水-水)は、多管式熱交換器より設置面積や重さが大きくなる。","多管式熱交換器にはU字管式・全固定式・フローティングヘッド式などがあり、蒸気-水や高温水-水の熱交換に向いている。"],"a":3,"e":"プレート式熱交換器はコンパクトで、多管式より設置面積や重さが小さい(2024年度問68・2022年度問71参照)。","l":"法令外","c":""},{"id":"2017-72","s":2,"q":"送風機について述べた次の文のうち、最も不適当なものはどれか。","o":["送風機は吐出し圧力の大きさでファンとブロワに分けられ、空気調和用の送風機にはファンが使われる。","軸流式送風機では、空気が軸方向から入り、軸に対して斜めに通り抜ける。","多翼送風機はシロッコファンとも呼ばれ、遠心式送風機に分類される。","送風機の特性曲線は、横軸に風量、縦軸に各風量での圧力・効率・軸動力・騒音値をとって表したものである。","送風系の抵抗曲線は、特性曲線と同じグラフ上では二次曲線で表される。"],"a":1,"e":"軸流式送風機では、空気が軸方向から入って軸方向に抜ける(2021年度問73でも正しい記述)。軸に対して斜めに抜けるのは斜流式である。","l":"法令外","c":""},{"id":"2017-73","s":2,"q":"ダクトと付属品について述べた次の文のうち、最も不適当なものはどれか。","o":["湿気の多い場所に設けるダクトや耐食性が必要なダクトには、ステンレス鋼板を使う。","鋼板製の長方形ダクトどうしをつなぐ継手には、アングルフランジ工法継手と共板フランジ工法継手がある。","防煙区画を貫通するダクトには、煙感知器と連動して閉じる防煙ダンパを設ける。","防火ダンパの羽根とケーシングは、一般に厚さ1.5mm以上の鋼板でつくる。","たわみ継手は、おもにダクトと吹出口をつなぐときに位置を合わせるために使う。"],"a":4,"e":"たわみ継手は、送風機など振動する機器とダクトをつなぐときに使う(2020年度問74でも正しい記述)。位置合わせに使うのはフレキシブル継手である。","l":"法令外","c":""},{"id":"2017-74","s":2,"q":"吹出口と吸込口について述べた次の文のうち、最も不適当なものはどれか。","o":["ふく流吹出口は、ほかの吹出口より誘引効果が高く、ムラの少ない温度分布が得られる。","軸流吹出口は、誘引比が小さいので到達距離が長い。","線状吹出口は、ペリメータ負荷の処理のため窓の近くに設置されることが多い。","面状吹出口は、天井板に細かい穴をあけた有孔天井を使い、天井全面から弱い風速で吹き出す方式が一般的である。","吸込口の吸込気流には方向性があるので、吸い込む向きに注意が必要である。"],"a":4,"e":"吸込気流には吹出気流のような方向性はほとんどない(2025年度問73で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-75","s":2,"q":"空気調和設備の空気浄化装置について述べた次の文のうち、最も不適当なものはどれか。","o":["空気浄化装置(エアフィルタ)が取り除く対象は、空気中の粉じんと有害ガスである。","ろ過式粒子用エアフィルタは、さえぎり、慣性、拡散、静電気などの作用で粉じんをろ材の繊維にとらえる。","HEPAフィルタは、有害ガスを化学吸着でとらえるための専用フィルタである。","粒子用エアフィルタの性能は、圧力損失・粉じん捕集率・粉じん保持容量で表す。","ガス除去用エアフィルタのガス除去容量は、使用限界までにとらえたガスの質量で表す。"],"a":2,"e":"HEPAフィルタは、ごく小さな粒子を高い効率でとらえるフィルタで、ガスを取るものではない(2024年度問73で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-76","s":2,"q":"空気調和設備のポンプ・配管について述べた次の文のうち、最も不適当なものはどれか。","o":["ポンプのキャビテーションを防ぐには、有効吸込みヘッドが必要有効吸込みヘッドより常に大きいことが必要である。","損失水頭は、管内流速の2乗に比例する。","水撃作用を防ぐ方法として、緩閉式逆止弁を使う方法がある。","サージングとは、脈動をともなう不安定な状態をいう。","渦流ポンプは、ターボ型ポンプに分類される。"],"a":4,"e":"この記述が誤り。渦流ポンプはターボ型ではなく、特殊型ポンプに分類される。","l":"法令外","c":""},{"id":"2017-77","s":2,"q":"弁類について述べた次の文のうち、最も不適当なものはどれか。","o":["バタフライ弁は、軸を回すと弁体が開閉する構造である。","リフト式逆止弁は、立て配管に取り付ける。","玉形弁は、弁体と弁座のすき間を変えて流量を調節する。","ボール弁は抵抗が少なく、流量の調整ができる。","空気抜き弁は、配管中にたまった空気を自動的に排出する。"],"a":1,"e":"リフト式逆止弁は、弁体が上下して開閉する構造なので水平配管に取り付ける。立て配管にも使えるのはスイング式逆止弁である。","l":"法令外","c":""},{"id":"2017-78","s":2,"q":"換気について述べた次の文のうち、最も不適当なものはどれか。","o":["換気回数とは、換気量を室の容積で割ったものである。","温度差による換気力は、室内外の空気の密度差に比例する。","第2種機械換気は、汚染空気が入ってくることを許さない手術室などの清浄室に使われる。","第3種機械換気は、給気口と排風機でできている。","風力による換気力は、外の風速に比例する。"],"a":4,"e":"風力による換気力(風圧)は、外の風速の2乗に比例する(2022年度問50でも正しい記述)。","l":"法令外","c":""},{"id":"2017-79","s":2,"q":"空気調和設備の維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["空気調和機内の細菌・真菌は、冷房期にも暖房期にもすんでいる。","スライム防止、レジオネラ属菌対策、腐食防止の効果をもつ多機能型薬剤は、連続的に注入するのが効果的である。","冷却水系のレジオネラ属菌の増殖を抑えるには、化学的洗浄と殺菌剤の添加を組み合わせるのが望ましい。","空気調和用ダクト内の粉じん中の細菌・真菌の量は、還気ダクトより給気ダクトの方が多い。","冷却塔の強制ブローは、スケール防止に役立つ。"],"a":3,"e":"還気ダクトには室内のほこりや微生物を含む空気が戻ってくるので、エアフィルタを通った後の給気ダクトより細菌・真菌の量は多い。","l":"法令外","c":""},{"id":"2017-80","s":2,"q":"温熱環境の測定器について述べた次の文のうち、最も不適当なものはどれか。","o":["超音波風速計は、超音波の強さと気流の関係を利用している。","熱線風速計は、電流で加熱した白金線などから気流に奪われる熱量が風速に関係することを利用している。","電気抵抗式湿度計は、感湿部の電気抵抗が吸湿や脱湿で変わることを利用している。","アスマン通風乾湿計は、まわりの気流や熱放射の影響を防ぐ構造になっている。","グローブ温度計の示す値が安定するまでには、15〜20分かかる。"],"a":0,"e":"超音波風速計は、超音波が伝わる時間が気流で変わることを利用している(2023年度問78で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-81","s":2,"q":"室内環境の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["二酸化炭素の測定法に、化学発光法がある。","アスベストの測定法に、位相差顕微鏡による方法がある。","浮遊真菌の測定法に、フィルタ法がある。","ホルムアルデヒドの測定法に、検知管法がある。","花粉アレルゲンの測定法に、免疫学的な方法がある。"],"a":0,"e":"二酸化炭素は非分散型赤外線吸収法などで測る(2023年度問80参照)。化学発光法はオゾンや窒素酸化物の測定法である(2025年度問80参照)。","l":"法令外","c":""},{"id":"2017-82","s":2,"q":"光散乱式の粉じん計で室内の浮遊粉じんの相対濃度を測ったところ、6分間で120カウントだった。この粉じん計のバックグランド値は1分間6カウント、標準粒子に対する感度は1分間1カウントあたり0.001mg/m³、室内浮遊粉じんに対する較正係数は1.3である。室内浮遊粉じんの濃度に最も近いものはどれか。","o":["0.010mg/m³","0.013mg/m³","0.018mg/m³","0.020mg/m³","0.026mg/m³"],"a":2,"e":"1分あたりの測定値は120÷6＝20cpm。濃度＝(20－6)×0.001×1.3＝0.0182≒0.018mg/m³。","l":"計算","c":""},{"id":"2017-83","s":2,"q":"測定対象と測定に使うものの組合せとして、最も不適当なものはどれか。","o":["温度 ― 熱電対","臭気 ― 官能試験","熱放射 ― ピトー管","酸素 ― ガルバニ電池","気流 ― サーミスタ"],"a":2,"e":"ピトー管は風速を測る器具(2024年度問77参照)。熱放射はグローブ温度計などで測る。","l":"法令外","c":""},{"id":"2017-84","s":2,"q":"汚染物質と、その濃度または強さを表す単位の組合せとして、最も不適当なものはどれか。","o":["アスベスト ― 本/L","ダニアレルゲン ― CFU/m³","キシレン ― μg/m³","放射能 ― Bq","二酸化窒素 ― ppb"],"a":1,"e":"CFUは微生物の数の単位。ダニアレルゲンの濃度はng/m³などで表す(2025年度問79・2022年度問78参照)。","l":"法令外","c":""},{"id":"2017-85","s":2,"q":"揮発性有機化合物(VOCs)の測定法について述べた次の文のうち、最も不適当なものはどれか。","o":["VOCsの測定には、基本的にガスクロマトグラフ質量分析計を使う。","加熱脱着法は、溶媒抽出法より測定感度が高い。","VOCsのパッシブサンプリング法は、静電気力を利用している。","TVOCの簡易な定量には、トルエン換算法がある。","市販のTVOCモニタは、標準ガスによる定期的な較正が欠かせない。"],"a":2,"e":"パッシブサンプリング法は、ポンプを使わずに物質が拡散して捕集材に届くこと(分子拡散)を利用する方法で、静電気力ではない。","l":"法令外","c":""},{"id":"2017-86","s":2,"q":"音について述べた次の文のうち、最も不適当なものはどれか。","o":["線音源からの音圧レベルは、音源からの距離が10倍になると約20dB下がる。","騒音は、人の聴覚の周波数特性で補正したA特性音圧レベルで測定・評価する。","時間で変動する騒音は、等価騒音レベルで評価する。","音圧レベルは人の感覚に合うように定めた尺度で、人が聞こえる最小の音圧2×10⁻⁵Paを基準とする。","音速は、空気の温度が1℃上がるごとに約0.6m/s速くなる。"],"a":0,"e":"線音源では距離が10倍になると約10dB下がる(2021年度問86で正答)。約20dB下がるのは点音源である。","l":"法令外","c":""},{"id":"2017-87","s":2,"q":"床衝撃音についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「重量床衝撃音は、[ア]ときに発生し、衝撃音は[イ]におもな成分を含む。対策としては[ウ]が効果的である。」","o":["ア 食器を落とした/イ 高周波数域/ウ 柔らかい床仕上げ材","ア 食器を落とした/イ 低周波数域/ウ 床躯体構造の質量を増やすこと","ア 人が床の上で飛び跳ねたりした/イ 高周波数域/ウ 柔らかい床仕上げ材","ア 人が床の上で飛び跳ねたりした/イ 低周波数域/ウ 柔らかい床仕上げ材","ア 人が床の上で飛び跳ねたりした/イ 低周波数域/ウ 床躯体構造の質量を増やすこと"],"a":4,"e":"重量床衝撃音は飛び跳ねなどで起き、低い周波数が中心で、床の躯体を重くするのが効果的(2025年度問84で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-88","s":2,"q":"環境振動について述べた次の文のうち、最も不適当なものはどれか。","o":["時間率レベルとは、あるレベル以上の振動にさらされる時間が観測時間に占める割合のことである。","防振溝は、道路交通振動など建築物の外からの振動対策として設けられる。","人体への振動を扱うときは、振幅と同時に振動の方向をはっきりさせる必要がある。","人は一般に低い周波数に対して感覚が鋭く、周波数が上がるにつれて感覚が鈍くなる。","空気調和設備による振動は、間欠的で周期性のない形で起きる。"],"a":4,"e":"空気調和設備の振動は、送風機やポンプなどが回転し続けることで連続的・周期的に起きる(2022年度問84で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-89","s":2,"q":"光の用語の説明として、誤っているものはどれか。","o":["照度均斉度 ― 一定期間使った後の作業面の平均照度と、初期の平均照度の比","輝度 ― 見る方向から見た、見かけの面積あたりの光度","演色性 ― 基準の光で照らしたときの色を、どれだけ忠実に再現するかを判定する指標","照度 ― 単位面積あたりに入ってくる光束","昼光率 ― 全天空照度に対する、室内のある点の昼光による照度の比率"],"a":0,"e":"一定期間使った後の平均照度と初期平均照度の比は「保守率」の定義(2022年度問88・2025年度問90でも正しい定義)。照度均斉度は照度のばらつき(最小照度と平均照度の比など)を表す。","l":"法令外","c":""},{"id":"2017-90","s":2,"q":"ある部屋の作業面に必要な照度が750lxである。ランプ1灯あたりの光束が2,500lmのとき、必要なランプの数に最も近いものはどれか。ただし床面積は80m²、照明率は0.5、保守率は0.75とする。","o":["24灯","32灯","48灯","64灯","100灯"],"a":3,"e":"灯数＝照度×面積÷(1灯の光束×照明率×保守率)＝750×80÷(2,500×0.5×0.75)＝60,000÷937.5＝64灯。","l":"計算","c":""},{"id":"2017-91","s":3,"q":"郊外と比べたときの、都市の環境の特徴について、最も不適当なものはどれか。","o":["年平均気温が高い。","年平均相対湿度が低い。","雨水をためる力(保水能力)が小さい。","年平均風速が大きい。","年平均二酸化炭素濃度が高い。"],"a":3,"e":"都市では建物が風をさえぎるため、年平均の風速は郊外より小さくなる(局所的なビル風は別)。","l":"法令外","c":""},{"id":"2017-92","s":3,"q":"建築物の設計図書について、最も不適当なものはどれか。","o":["日影図は、直射日光でできる建物の影の形を、1日の時間ごとに描いた図である。","配置図は、部屋の配置を示した図である。","立面図は、建物の外観を示した図である。","断面図は、建物を垂直に切った断面を投影した図である。","矩計図は、基礎を含む主な外壁部分の各部の寸法を示した断面詳細図である。"],"a":1,"e":"配置図は、敷地の中での建物の位置(建物と敷地の関係)を示した図である。部屋の配置を示すのは平面図。","l":"法令外","c":""},{"id":"2017-93","s":3,"q":"建築物の計画と設計について、最も不適当なものはどれか。","o":["街路や広場などに面した、建物の正面の外観をファサードという。","スケルトン・インフィル建築物とは、建物の躯体と、設備・内装仕上げなどを分けてつくる工法の建物である。","コンペティションとは、設計者を選ぶ方式の一つである。","多目的ホールで使われる可動席の床を、フリーアクセスフロアという。","テクスチャとは、材料の質感・材質感のことである。"],"a":3,"e":"フリーアクセスフロアは、床を二重にして配線などを自由に通せるようにした床で、事務所の情報機器用などに使われる。可動席の床のことではない。","l":"法令外","c":""},{"id":"2017-94","s":3,"q":"建築物の基礎構造と地盤について、最も不適当なものはどれか。","o":["圧密沈下とは、粘土質の地盤が圧力で沈むことをいう。","標準貫入試験は、地盤の強さや変形などの性質を調べる試験である。","連続フーチング基礎は、高層建築物の基礎によく使われる。","沖積層は新しい堆積層で、一般に軟らかい。","地盤の短期許容応力度は、長期許容応力度より大きく決められている。"],"a":2,"e":"連続フーチング基礎(布基礎)は、主に低層の建物に使われる基礎である。高層建築物には、べた基礎や杭基礎などが使われる。","l":"法令外","c":""},{"id":"2017-95","s":3,"q":"鉄筋コンクリート構造とその材料について、最も不適当なものはどれか。","o":["梁に入れるせん断補強筋を、あばら筋という。","直接土に接する床では、鉄筋に対するコンクリートのかぶり厚さを4cm以上にしなければならない。","コールドジョイントができると付着が弱くなり、構造上の欠陥になりやすい。","鉄筋コンクリート用棒鋼SD294Aの記号の数値は、降伏点の強さを表す。","床のコンクリートの厚さは、一般に10cm程度である。"],"a":4,"e":"この記述が誤り。一般的な床スラブのコンクリートの厚さは、10cm程度より厚くする。","l":"法令外","c":""},{"id":"2017-96","s":3,"q":"建築物とその構造について、最も不適当なものはどれか。","o":["コンクリートの中性化は、構造体の寿命に大きく影響する。","クリープとは、一定の大きさの荷重がかかり続けることで、時間とともにひずみが大きくなる現象をいう。","耐震補強には、強さを高める方法と、変形する能力を高める方法がある。","塑性とは、部材に荷重をかけて生じた変形が、荷重を取り除くと元に戻る性質をいう。","免震構造には、アイソレータを使って地盤から建物を切り離す方法がある。"],"a":3,"e":"荷重を取り除くと元に戻る性質は「弾性」である。塑性は、荷重を取り除いても変形が残る性質。","l":"法令外","c":""},{"id":"2017-97","s":3,"q":"建築材料の特徴について、最も不適当なものはどれか。","o":["木材の熱伝導率は、コンクリートより大きい。","Low-Eガラスは、ガラスの表面に特殊な金属の膜をコーティングしたものである。","鉄鋼の線膨張係数は、コンクリートとほぼ等しい。","ステンレス鋼は、鉄にクロムやニッケルなどを加えた特殊鋼である。","アルミ材は軽いので、カーテンウォールに使われる。"],"a":0,"e":"木材は熱を伝えにくく、熱伝導率はコンクリートより小さい。","l":"法令外","c":""},{"id":"2017-98","s":3,"q":"建築材料と部材の性質について、最も不適当なものはどれか。","o":["トタンは、鋼板にすずめっきをしたものである。","銅は延ばしたり広げたりしやすく(展延性に富み)、加工しやすい。","板ガラスは、部分的に熱せられると割れやすい。","ポルトランドセメントには、普通・早強・中庸熱などの種類がある。","ブリージングとは、コンクリートを打った後、セメントや骨材が沈んで、分かれた水が浮き上がる現象をいう。"],"a":0,"e":"トタンは鋼板に亜鉛めっきをしたものである。すずめっきをしたものはブリキ。","l":"法令外","c":""},{"id":"2017-99","s":3,"q":"建築設備に関する用語の組合せとして、最も不適当なものはどれか。","o":["LAN ― 情報通信設備","ITV ― 防犯設備","EV ― 搬送設備","CAV ― 空気調和設備","ESCO ― 排水設備"],"a":4,"e":"ESCOは、省エネルギーの診断から改修、効果の検証までを提供するエネルギーサービス事業で、排水設備とは関係ない。","l":"法令外","c":""},{"id":"2017-100","s":3,"q":"消火設備について、最も不適当なものはどれか。","o":["消火の方法は、燃焼の3要素(燃える物・酸素・火のもと)の1つ以上を取り除くことが原則である。","金属の火災では、水で消すと危険になる場合がある。","消火器は、火災を見つけた初めの段階での消火に使われる。","連結送水管は消防隊が使うもので、消防隊専用栓と呼ばれる。","泡消火設備は、薄める作用(希釈作用)によって消火する。"],"a":4,"e":"泡消火設備は、燃えている物を泡で覆って酸素を断つ窒息作用と、冷却作用によって消火する。","l":"法令外","c":""},{"id":"2017-101","s":3,"q":"防災について、最も不適当なものはどれか。","o":["火災荷重とは、建築部材などの燃える物が出しうる熱量を、木材の発熱量で換算した、単位面積あたりの燃える物の重さのことである。","差動式熱感知器は、周りの温度が決められた一定の温度以上になると作動する。","火災の部屋の温度が急に上がり、炎が噴き出して、一気に部屋全体に燃え広がる現象をフラッシュオーバーという。","防炎物品は、カーテンやじゅうたんなどに薬剤処理をして、火がつきにくく燃え広がりにくくしたものである。","防煙・排煙対策の目的は、煙の動きをコントロールして、安全な避難経路や消防活動の拠点を確保することである。"],"a":1,"e":"周りの温度が一定の温度以上になると作動するのは定温式熱感知器である。差動式は、温度が急に上がる(温度上昇率が一定以上になる)と作動する。","l":"法令外","c":""},{"id":"2017-102","s":3,"q":"建築基準法について、正しいものはどれか。","o":["建築基準法は、建物の意匠・装飾についての設計指針を定めている。","建築基準法は、建物の敷地・構造・設備・用途についての望ましい基準を定めている。","建物の所有者・管理者・占有者は、その建物の敷地・構造・建築設備をいつも法律に合った状態に保つよう努めなければならない。","建物に関する規定のうち、建物そのものの安全・防火・避難・衛生などの技術的基準を定めた規定をまとめて集団規定という。","建築基準法は、建物の工事監理を行う技術者の資格を定めている。"],"a":2,"e":"建築基準法第8条で、所有者・管理者・占有者は敷地・構造・建築設備を常時適法な状態に維持するよう努めなければならないとされている。建築基準法は「最低の基準」を定め、建物そのものの基準は単体規定という。","l":"建築基準法 第1条、第8条","c":""},{"id":"2017-103","s":3,"q":"建築基準法とその施行令について、誤っているものはどれか。","o":["戸建住宅は、特殊建築物ではない。","基礎は、主要構造部である。","住宅の納戸は、居室ではない。","建物に設ける煙突は、建築設備である。","小屋組は、構造耐力上主要な部分である。"],"a":1,"e":"主要構造部は壁・柱・床・梁・屋根・階段で、基礎は含まれない(基礎は構造耐力上主要な部分には含まれる)。","l":"建築基準法 第2条第5号","c":""},{"id":"2017-104","s":3,"q":"建築基準法の行政手続などについて、最も不適当なものはどれか。","o":["建築設備でも、建築確認が必要なものがある。","建築主は、特定工程を含む建築工事を行う場合には、中間検査の申請が免除される。","建築主事は、確認申請書を審査し、法に合っていると確認したら、建築主に確認済証を交付する。","特定行政庁は、違反建築物に対して必要な措置を命じることができる。","建築主事は、市区町村や都道府県の職員で、建築基準適合判定資格者の登録を受けた人の中から、市区町村長または都道府県知事が命じる。"],"a":1,"e":"特定工程を含む工事では、その工程が終わったときに中間検査を申請しなければならない。免除されるのではない。","l":"建築基準法 第7条の3","c":""},{"id":"2017-105","s":3,"q":"建築物の管理について、最も不適当なものはどれか。","o":["ライフサイクルとは、JISの設備管理用語で「設備の製作、運用、保全」と定義されている。","エネルギー管理で勧められるPDCAサイクルを回すには、見える化の機能が役立つ。","ファシリティマネジメントは、コストと品質の最適なバランスを目指すものである。","放射空調は、温度ムラによる不快感が起こりにくい。","設備の保全活動には、維持活動と改善活動がある。"],"a":0,"e":"JISでは、設備のライフサイクルを、計画・設計・製作・運用・保全をへて廃棄・再利用までを含むすべての段階としている(2022年度問105でも同じ記述が誤りとされている)。","l":"法令外(JIS Z 8141)","c":""},{"id":"2017-106","s":4,"q":"給水・排水の管理で使う用語と、その単位の組合せとして、最も不適当なものはどれか。","o":["下水道でのリン含有量 ― mg/L","ゲージ圧力 ― Pa","病院の単位給湯量 ― L/(床・日)","水の比熱 ― J/℃","化学的酸素要求量 ― mg/L"],"a":3,"e":"比熱は質量あたりの量なので、単位は kJ/(kg・℃) などになる(2025年問121で「15℃の水の比熱は4.186kJ/(kg・℃)」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-107","s":4,"q":"給水・排水の管理に関する用語と説明として、最も不適当なものはどれか。","o":["バルキング ― 排水槽の底に沈んだ固形物や油脂などが集まったもの","酸化保護被膜 ― 酸化でできる金属表面のうすい膜","ファージ ― 細菌を宿主細胞とするウイルスの総称","トリハロメタン ― 有機物と消毒用の塩素が反応してできる物質","スケール ― 炭酸カルシウムや炭酸マグネシウムなどの析出物"],"a":0,"e":"バルキングは、活性汚泥が沈降しにくくなる現象である(2020年問107で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2017-108","s":4,"q":"水道法に関する記述として、最も不適当なものはどれか。","o":["簡易専用水道とは、水道事業の水道から受ける水だけを水源とし、水槽の有効容量の合計が10m³以下のものをいう。","水道とは、導管などの工作物によって、人が飲むのに適した水を供給する施設全体をいう。","専用水道とは、寄宿舎などの自家用水道で、100人を超える人に居住に必要な水を供給するもの、または人の生活に使う1日最大給水量が20m³を超えるものをいう。","上水道事業とは、一般に計画給水人口が5,001人以上の水道事業をいう。","給水装置とは、需要者に水を届けるため、水道事業者が設けた配水管から分かれた給水管と、これに直結する給水用具をいう。"],"a":0,"e":"簡易専用水道から除かれるのが有効容量10m³以下のもので、簡易専用水道は10m³を超えるものをいう(水道法第3条第7項、水道法施行令第2条)。専用水道の20m³は施行令第1条第2項のとおり。","l":"水道法 第3条、水道法施行令 第1条・第2条","c":""},{"id":"2017-109","s":4,"q":"水質基準に関する省令で定める基準値として、誤っているものはどれか。","o":["一般細菌は、検水1mLでできる集落数が100以下であること。","銅及びその化合物は、銅の量として10mg/L以下であること。","ホルムアルデヒドは、0.08mg/L以下であること。","pH値は、5.8以上8.6以下であること。","色度は、5度以下であること。"],"a":1,"e":"銅及びその化合物の基準は、銅の量として1.0mg/L以下である(水質基準に関する省令)。ほかの4つは現行の基準どおり。","l":"水質基準に関する省令(表)","c":""},{"id":"2017-110","s":4,"q":"給水設備に関する記述として、最も適当なものはどれか。","o":["事務所建築の1日あたりの設計給水量は、150〜200L/人とする。","受水槽の有効容量は、一般に1日最大使用水量の1/10とする。","給水配管の管径は、管内の流速が最大2.0m/s以下になるように選ぶ。","高置水槽方式は、ほかの給水方式に比べて水質汚染の可能性が低い方式である。","直結増圧方式は、引込み管に増圧ポンプユニットを設けて水圧を高め、飲料水をためておく機能が必要な高層建築物にも使えるようにした方式である。"],"a":2,"e":"給水配管の管径は、管内の流速が2.0m/s以下になるように選ぶ(2025年問115でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-111","s":4,"q":"給水設備の配管に関する記述として、最も不適当なものはどれか。","o":["給水管と排水管を並べて埋める場合は、給水管の上に排水管を埋める。","ポンプに弁や配管を付けるときは、その重さが直接ポンプにかからないように支える。","給水配管の枝管を下向きに分ける場合は、下から取り出す。","止水弁は、主管からの分岐、各系統の起点、機器との接続部などに設ける。","飲料水の配管は、ほかの配管系統と見分けがつくようにしなければならない。"],"a":0,"e":"給水管と排水管を平行に埋める場合は、給水管を排水管より上に埋める(2021年問114で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-112","s":4,"q":"給水設備の機器に関する記述として、最も不適当なものはどれか。","o":["木製の貯水槽は断熱性に優れているので、結露対策がいらない。","ステンレス鋼板製の貯水槽は、気相部の腐食対策が必要である。","渦巻きポンプは、羽根車を高速で回して水に向心力を与え、吐き出す。","FRP製の貯水槽は機械的強度が低いので、耐震補強が必要である。","受水槽から高置水槽へ水を送る揚水ポンプは、高置水槽の水位によって起動・停止させる。"],"a":2,"e":"渦巻きポンプについて「水に向心力を与えて吐き出す」とした点が誤り(2024年問114でも同じ記述が誤りとして出題)。","l":"法令外","c":""},{"id":"2017-113","s":4,"q":"給水設備の配管に関する語句の組合せとして、最も不適当なものはどれか。","o":["ステンレス鋼管(フランジ接合) ― テフロン製(テフロン被覆)ガスケット","合成樹脂ライニング鋼管(ねじ接合) ― 管端防食継手","ポリブテン管 ― 接着接合","銅管 ― 酸化保護被膜","架橋ポリエチレン管 ― さや管ヘッダ工法"],"a":2,"e":"ポリブテン管の接合方法は、メカニカル形接合や融着接合である(2016年問114で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-114","s":4,"q":"給水設備の汚染に関する記述として、最も不適当なものはどれか。","o":["飲料用貯水槽のオーバフロー管は、排水をスムーズにするため、一般の排水管に直接つなぐ。","吐水口空間を設けることは、逆サイホン作用を防ぐ基本である。","大便器洗浄弁には、大気圧式バキュームブレーカを設ける。","上水の系統とそれ以外の系統は、どんな理由があっても直接つないではならない。","屋内の貯水槽は、6面から点検できるように床の上に独立して置く。"],"a":0,"e":"オーバフロー管は排水口空間を確保して間接排水とする(2016年問112で正しい記述として出題)。一般の排水管に直接つないではならない。","l":"法令外","c":""},{"id":"2017-115","s":4,"q":"貯水槽の清掃に関する記述として、最も不適当なものはどれか。","o":["清掃のときは、必要に応じてマンホールのふたを開けた後、換気用のファンやダクトを置いて槽内を換気するなど、事故防止の対策をする。","受水槽と高置水槽の清掃は原則として同じ日に行い、受水槽の清掃後に高置水槽を清掃する。","清掃が終わったら、塩素剤を使って2回以上、貯水槽の中を消毒する。","清掃後の水洗いと水張りは、消毒が終わってから少なくとも30分以上たってから行う。","清掃後の水質検査で、遊離残留塩素濃度の基準値は0.1mg/L以上である。"],"a":4,"e":"清掃後の水張り時の検査で、遊離残留塩素の基準は0.2mg/L(百万分の0.2)以上である(告示第119号 第2の一の1(四))。","l":"平成15年厚生労働省告示第119号 第2の一の1","c":""},{"id":"2017-116","s":4,"q":"給水設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["貯水槽の清掃で出た汚泥などの廃棄物は、廃棄物処理法や下水道法などの決まりに従って適切に処理する。","防錆剤の使用は、配管の布設替えが行われるまでの応急処置とする。","管更生工法で管の内側に合成樹脂ライニングをする場合は、技術評価・審査証明を受けた工法を選ぶのがよい。","ポンプ直送方式では、ポンプが止まったときや性能が落ちたときなどに、下の階のほうが給水管内が負圧になりやすい。","配管は、損傷・さび・腐食・水漏れがないか点検し、必要に応じて補修する。"],"a":3,"e":"ポンプ直送方式で負圧になりやすいのは上層階である(2024年問117で正しい記述として出題)。なお(2)は告示第119号 第2の二の4のとおり。","l":"平成15年厚生労働省告示第119号 第2(選択肢1・2)","c":""},{"id":"2017-117","s":4,"q":"給湯設備の配管に関する記述として、最も不適当なものはどれか。","o":["逃し弁には、加熱で膨らんだ湯を逃がすための排水管を設ける。","配管内の空気や水が抜けやすいように、凹凸のある配管にはしない。","給湯設備の金属材料の腐食は、給水設備で使う場合より早く起こり、腐食の速さも速い。","中央式給湯方式の循環ポンプは、給湯主管に設置する。","業務用厨房のように連続して湯を使う給湯枝管には、返湯管を設けないことが多い。"],"a":3,"e":"中央式給湯方式の循環ポンプは返湯管に設置する(2016年問120で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-118","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["中央式給湯方式の循環ポンプの循環流量は、加熱装置での給湯温度と返湯温度の差に反比例する。","ヒートポンプは、排熱回収用の給湯熱源機器として使われる。","排水から熱を回収する場合は、熱効率を上げるために直接熱交換を行う。","エネルギーと水を節約するため、湯と水を別々の水栓から出さずに混合水栓を使う。","給湯配管から逃げる熱を減らすため、配管経路を短くし、配管を断熱するなどの配管計画を立てる。"],"a":2,"e":"排水から熱を回収する場合は、熱交換器の腐食などによる湯の汚染を防ぐため、間接熱交換方式にする(2023年問117で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-119","s":4,"q":"給湯設備の機器に関する記述として、最も不適当なものはどれか。","o":["加熱コイル付き貯湯槽は、蒸気などの熱媒が得られる場合に一般的に使われる。","貯蔵式湯沸器は、加熱ヒータ・温度調節装置・密閉式貯湯槽・減圧弁・逃し弁でできている。","ガスマルチ式給湯機には、小型の瞬間湯沸器を何台もつないでユニットにし、台数を切り替えて運転するものがある。","ボイラは、伝熱面積やゲージ圧力などで、簡易ボイラ・小型ボイラ・ボイラに分けられる。","給湯用の貫流ボイラは温水を取り出す小型ボイラで、水管群でできていて耐圧性に優れる。"],"a":1,"e":"貯蔵式湯沸器は、貯める部分が大気に開放されている(2022年問119で正しい組合せとして出題)。密閉式貯湯槽や減圧弁で構成されるとした記述が誤り。","l":"法令外","c":""},{"id":"2017-120","s":4,"q":"給湯設備の配管に関する記述として、最も不適当なものはどれか。","o":["ステンレス鋼管の線膨張係数は、架橋ポリエチレン管より小さい。","銅管は、循環配管を設けない一過式の配管では、腐食がほとんど起こらない。","循環式給湯設備で下向き配管方式とする場合、給湯横主管は1/200以上の上り勾配にする。","耐熱性硬質ポリ塩化ビニル管は、90℃以下で使う。","ステンレス鋼管は、すき間腐食や残留応力腐食などによる腐食が起こるおそれがある。"],"a":2,"e":"下向き配管方式の給湯横主管は、1/200以上の下り勾配とする(2020年問118・2025年問118で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-121","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["シャワーヘッドは、1年に1回以上、分解清掃を行う。","中央式給湯方式の循環ポンプは、1年に1回、作動確認をかねて分解清掃を行う。","第一種圧力容器は、1年に1回、定期自主検査を行う。","給湯配管は、1年に1回管洗浄を行う。","各種の弁は、1年に1回以上、分解清掃を行う。"],"a":2,"e":"第一種圧力容器の定期自主検査は1か月以内ごとに1回行う(ボイラー及び圧力容器安全規則第67条)。","l":"ボイラー及び圧力容器安全規則 第67条","c":""},{"id":"2017-122","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["休止していた貯湯槽を再び使うときは、点検・清掃をし、給湯系統内が設定温度になるまで加熱してから使う。","貯湯槽は、定期的に底部にたまった水を出す。","ベローズ形の伸縮管継手は、ベローズの疲労破壊によって水漏れすることがある。","給湯水の流量を調節するには、仕切弁を使う。","配管系統の末端では、定期的にたまった水を出し、温度を測る。"],"a":3,"e":"流量の調節には仕切弁ではなく玉形弁が向いている(2023年問75で「玉形弁は流量調整用として用いられる」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-123","s":4,"q":"雑用水設備に関する記述として、最も不適当なものはどれか。","o":["地区循環方式で雑用水を使うと、下水道への負荷が軽くなる。","排水再利用設備に入る原水にし尿を含む雑用水は、残留塩素が基準値以上あれば散水用の水に使える。","雑用水の原水には、1年を通して安定して確保できる排水を優先して使う。","工事完成時に雑用水に色を付けて通水試験を行い、上水の器具から色の付いた水が出ないことを確かめる。","雑用水は、洗面器や手洗器など、誤って飲んだり使ったりするおそれのある器具にはつながない。"],"a":1,"e":"散水・修景・清掃に使う雑用水には、し尿を含む水を原水として使ってはならない(建築物衛生法施行規則第4条の2第1項第3号イ)。残留塩素の値とは関係がない。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2017-124","s":4,"q":"雑用水処理設備に使われる膜分離活性汚泥処理装置に関する記述として、最も不適当なものはどれか。","o":["分離膜には、主に逆浸透膜(RO膜)が使われる。","分離膜は、主に活性汚泥と処理水を分けるために使われる。","膜モジュールは、一般に生物処理槽の中にひたして使う。","処理水には消毒が必要である。","槽内浸漬型で生物処理槽をばっ気するのは、微生物に酸素を送るためと、膜の表面を洗うためでもある。"],"a":0,"e":"膜分離活性汚泥処理装置の分離膜には、主に精密ろ過膜(MF膜)が使われる(2022年問126で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-125","s":4,"q":"建築物衛生法施行規則第4条の2にもとづく散水・修景・清掃用の雑用水の水質検査で、2か月以内ごとに1回、定期に行う項目として、正しいものはどれか。","o":["pH","臭気","外観","濁度","BOD"],"a":3,"e":"散水・修景・清掃用の雑用水で2か月以内ごとに1回検査するのは、大腸菌と濁度である。pH値・臭気・外観は7日以内ごとに1回で、BODは検査項目にない(施行規則第4条の2)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2017-126","s":4,"q":"排水の水質に関する記述として、最も不適当なものはどれか。","o":["浮遊物質とは、水中に浮かんでいる2mm以上の物質である。","BODは、20℃・暗所・5日間で使われた溶存酸素の量を表したものである。","窒素化合物は、閉鎖性水域の富栄養化の原因物質の一つである。","ノルマルヘキサン抽出物質は、主に比較的揮発しにくい油脂類などである。","汚泥容量指標(SVI)は、活性汚泥の沈みやすさを表す指標である。"],"a":0,"e":"浮遊物質(SS)は、試料を孔径1μmのガラスファイバろ紙でこして、ろ紙の上に残ったものの重さで表す(2023年問126で正しい記述として出題)。2mm以上の物質とした記述が誤り。","l":"法令外","c":""},{"id":"2017-127","s":4,"q":"排水通気方式と通気配管に関する記述として、最も不適当なものはどれか。","o":["結合通気管は、高層建築物でブランチ間隔15以上の排水立て管に、最下階から数えてブランチ間隔15以内ごとに設ける。","通気立て管の上部は、最も高い位置の衛生器具のあふれ縁から150mm以上高い位置で伸頂通気管につなぐ。","ループ通気方式は、最上流の器具排水管が排水横枝管につながる位置のすぐ下流から通気管を立ち上げ、通気立て管につなぐ方式である。","通気立て管の下部は、最も低い排水横枝管より低い位置で、排水立て管から取り出す。","特殊継手排水システムは、排水横枝管につながる器具の数が比較的少ない集合住宅やホテルの客室系統に多く採用されている。"],"a":0,"e":"結合通気管は、ブランチ間隔10以上の排水立て管に、最上階から数えてブランチ間隔10以内ごとに設ける(2024年問131・2025年問128で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-128","s":4,"q":"排水管の掃除口と排水ますに関する記述として、最も不適当なものはどれか。","o":["掃除口の間隔は、排水管の管径が100mm以下の場合は15m以内とする。","掃除口は、排水横主管と敷地排水管がつながる場所の近くに設ける。","排水管の管径が125mmの場合、掃除口の口径は75mmとする。","排水ますの大きさは、配管を埋める深さ、つながる配管の大きさと本数、点検のしやすさなどを考えて決める。","敷地排水管の直管が長い場合は、管内径の120倍を超えない範囲に排水ますを設ける。"],"a":2,"e":"排水管の管径が125mmの場合、掃除口の口径は100mmとする(2021年問132で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-129","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["間接排水管の口径が100mmの場合、排水口空間は最小150mmである。","排水ポンプは、排水槽の吸込みピットの壁などから200mm以上離して設置する。","管径125mmの排水横管の最小勾配は、1/150である。","伸頂通気方式の排水横主管の水平曲がりは、排水立て管の底部から2m以内に設ける。","雨水ますの流出管は、流入管より管底を20mm程度下げて設ける。"],"a":3,"e":"伸頂通気方式の排水横主管の水平曲がりは、排水立て管の底部から3m以内に設けてはならない(2025年問130で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-130","s":4,"q":"排水通気設備に関する語句の組合せとして、最も不適当なものはどれか。","o":["防水床用の排水トラップ ― 水抜き孔を設ける","通気弁 ― 寒冷地の集合住宅の通気管に使う","通気口の通気率 ― 通気口の開口面積/管内断面積","即時排水型ビルピット設備 ― 排水槽の悪臭防止に効果がある","トラップの封水強度 ― 毛管現象が起きたときに封水を保つ能力"],"a":4,"e":"トラップの封水強度とは、排水管内に正圧や負圧が生じたときに封水を保つ能力をいう(2021年問129・2025年問133で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-131","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["排水槽の底の勾配は、吸込みピットに向かって1/15以上1/10以下とする。","排水立て管のオフセット部の近くに排水横枝管を設ける場合は、オフセット部の上下500mm以内に設ける。","排水槽のマンホールの大きさは、直径600mm以上の円が内接できるものとする。","トラップが組み込まれていない阻集器には、出口側にトラップを設ける。","伸頂通気方式では、排水立て管と排水横主管の接続に大曲がりベンドを使う。"],"a":1,"e":"排水立て管のオフセット部の上下600mm以内には、排水横枝管を設けてはならない(2023年問132・2025年問130で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-132","s":4,"q":"排水設備の保守管理の内容と、その実施頻度の組合せとして、最も不適当なものはどれか。","o":["排水槽の清掃 ― 6か月以内に1回","排水ポンプのメカニカルシールの交換 ― 3〜5年に1回","通気管の点検 ― 1年に1回","グリース阻集器のトラップの清掃 ― 2か月に1回","排水ポンプの絶縁抵抗の測定 ― 1か月に1回"],"a":1,"e":"排水ポンプのメカニカルシールの交換は1〜2年に1回程度である(2023年問134・2025年問135で正しい記述として出題)。排水槽の清掃は施行規則第4条の3のとおり6か月以内ごとに1回。","l":"建築物衛生法施行規則 第4条の3(選択肢1)","c":""},{"id":"2017-133","s":4,"q":"排水通気設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["逆流防止弁は、下水本管からの排水の逆流を防ぐために設ける。","厨房排水槽の水位制御には、一般にフロートスイッチが使われる。","グリース阻集器のグリースは、7〜10日に1回の間隔で取り除く。","排水管に付いた有機性の汚れは、アルカリ性洗剤で取り除く。","排水横管の清掃にワイヤを通す方法を使う場合、一般に長さ35m程度が限界とされている。"],"a":4,"e":"スネークワイヤを排水横管に使う場合の限界は、長さ25m程度である(2020年問135・2025年問134で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-134","s":4,"q":"排水通気設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["敷地排水管の清掃に使うロッド法は、1〜1.8mのロッドをつなぎ、手で排水管に入れて清掃する方法である。","排水槽の悪臭対策として、5〜6時間を超えて排水をためないよう、タイマ制御で強制排水する。","床下に設ける掃除口は、砲金製のものが適している。","ウォータラム法は、圧縮空気を一気に放出し、その衝撃で詰まりを取り除く方法である。","飲食店などのグリース阻集器で出る廃棄物は、産業廃棄物として処理する。"],"a":1,"e":"タイマ制御による強制排水は、1〜2時間を超えて排水をためないように行う(2021年問133で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-135","s":4,"q":"大便器と小便器に関する記述として、最も不適当なものはどれか。","o":["大便器の洗浄タンクの中の汚れの状態は、6か月に1回、定期に点検する。","JISでは、節水Ⅱ形の大便器の洗浄水量を6.5L以下としている。","ロータンクの中のボールタップは、水を止める機能をもっていなければならない。","小便器のリップの高さとは、床面からあふれ縁までの垂直距離をいう。","使用頻度の高い公衆便所用の小便器の排水トラップは、小便器と一体のものが向いている。"],"a":4,"e":"使用頻度の高い公衆便所用小便器のトラップを「小便器一体のものが適している」とした記述が誤り(2023年問136でも同じ記述が誤りとして出題)。","l":"法令外","c":""},{"id":"2017-136","s":4,"q":"衛生器具設備に関する記述として、最も不適当なものはどれか。","o":["節水機器を入れる場合は、器具から出る水の量を減らすだけでなく、排水管内の流れ方などにも配慮する。","小便器は乾いた面が広いので、きちんと洗浄しないと臭いが出る。","温水洗浄便座の給水に、雑用水系統であることを表示した再利用水の配管をつなぐ。","節水のための小便器には、一人ひとりを感知して洗う方式や、照明スイッチと連動して洗う方式などが使われている。","上質水供給設備では、末端の水栓で決められた残留塩素を確保するため、必要最小限の塩素を注入する。"],"a":2,"e":"温水洗浄便座への給水には上水を使う(2023年問135で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-137","s":4,"q":"浄化槽の高度処理で、取り除く物質と、その除去法の組合せとして、最も不適当なものはどれか。","o":["浮遊性の残った有機物 ― 凝集沈殿法","溶解性の残った有機物 ― 活性炭吸着法","窒素化合物 ― 生物学的硝化・脱窒法","アンモニア ― イオン交換法","リン化合物 ― 急速砂ろ過法"],"a":4,"e":"リン化合物の除去法を急速砂ろ過法とした組合せが誤り。","l":"法令外","c":""},{"id":"2017-138","s":4,"q":"浄化槽法にもとづく浄化槽管理者の役割に関する記述として、最も不適当なものはどれか。","o":["設置届を出すこと。","清掃を行うこと。","保守点検を行うこと。","浄化槽設備士を置くこと。","法定検査を受けること。"],"a":3,"e":"浄化槽設備士を営業所ごとに置かなければならないのは浄化槽工事業者であり(浄化槽法第29条)、浄化槽管理者ではない。保守点検・清掃は浄化槽管理者の義務である(同法第10条)。","l":"浄化槽法 第10条・第29条","c":""},{"id":"2017-139","s":4,"q":"浄化槽の装置と、その点検内容の組合せとして、最も不適当なものはどれか。","o":["流入管渠 ― 異物などが付いていないか","嫌気ろ床槽 ― 目詰まりの状況","汚泥貯留槽 ― スカムのたまり具合","沈殿槽 ― たまった汚泥のでき具合","接触ばっ気槽 ― MLSS濃度"],"a":4,"e":"接触ばっ気槽では生物膜の生成状況を点検する(2020年問139で正しい組合せとして出題)。MLSSはばっ気槽(活性汚泥)の指標である。","l":"法令外","c":""},{"id":"2017-140","s":4,"q":"特殊設備の維持管理に関する記述として、最も不適当なものはどれか。","o":["厨房機器に求められる条件として、食品にふれる部分が衛生的で、洗浄・殺菌しやすい構造であることがあげられる。","入浴設備の打たせ湯に、循環している浴槽の水を使う。","プール水の消毒設備では、塩素剤に加えてオゾン消毒や紫外線消毒を併用する例がある。","HACCPとは、原材料の受入れから最終製品の出荷までの各段階のリスク分析にもとづき、重点管理点を決めて連続的に監視する、安全確保のための衛生管理手法である。","水景施設へ上水系統から補給する水は、必ず吐水口空間を設けて間接的に給水する。"],"a":1,"e":"打たせ湯には、循環している浴槽水を使わない(2022年問139で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-141","s":5,"q":"「空気調和設備等の維持管理及び清掃等に係る技術上の基準」(平成15年厚生労働省告示第119号)の清掃について述べた次の文のうち、誤っているものはどれか。","o":["床面の清掃は、日常の除じん作業のほか、床維持剤の塗布の状況を点検し、必要に応じて塗り直しなどを行うこと。","日常的に清掃を行わない箇所は、6か月以内ごとに1回、定期に汚れの状況を点検し、必要に応じて除じん・洗浄などを行うこと。","廃棄物の収集・運搬設備、貯留設備その他の処理設備は、定期に点検し、必要に応じて補修・消毒などを行うこと。","カーペット類に洗剤を使った場合は、洗剤分が残らないようにすること。","カーペット類の清掃は、1か月以内ごとに1回、定期的にしみ抜きを行うこと。"],"a":4,"e":"告示ではカーペット類について「日常の除じん作業のほか、汚れの状況を点検し、必要に応じ、シャンプークリーニング、しみ抜き等を行う」とされ、1か月以内ごとのしみ抜きという定めはない(告示第119号 第5の一の2)。","l":"平成15年厚生労働省告示第119号 第5","c":""},{"id":"2017-142","s":5,"q":"建築物清掃の作業計画について述べた次の文のうち、最も不適当なものはどれか。","o":["作業計画をつくるときは、ムリ・ムダ・ムラがないかに気をつける。","日常清掃で取る汚れと定期的に取る汚れを区別しなくても、作業を進められる。","作業記録を残しておくと、さまざまなトラブルへの対応が早くなる。","作業内容がはっきりしているので、管理者への対応が的確にできる。","作業内容がはっきりしているので、統一した指導ができる。"],"a":1,"e":"日常清掃で取る汚れと定期的に取る汚れを分けて計画することで、作業の効率と成果が上がる(2023年度問144でも正しい記述)。","l":"法令外","c":""},{"id":"2017-143","s":5,"q":"建築物清掃の作業計画について述べた次の文のうち、最も適当なものはどれか。","o":["作業頻度による分類では、日常清掃、定期清掃、臨時清掃に分けられる。","廊下の壁のスポット洗浄は、日常清掃で行う。","湯沸室の流し台の洗浄は、一般に定期清掃で行う。","管理用区域は汚れが少ないので、清掃は年2回程度行う。","エスカレーターのパネル類の洗剤拭きは、一般に日常清掃で行う。"],"a":0,"e":"清掃は頻度によって日常清掃・定期清掃・臨時清掃に分けられる。廊下の壁のスポット洗浄は定期清掃で行う(2024年度問143で正答)。","l":"法令外","c":""},{"id":"2017-144","s":5,"q":"建築物清掃管理の評価について述べた次の文のうち、最も不適当なものはどれか。","o":["品質評価の第一歩は、自らセルフインスペクションを行い、求められる品質との差を確かめることである。","組織品質は、事業所管理品質と作業品質の2つでできている。","評価の結果、改善が必要と判断したときは、清掃責任者に指示する。","評価方法には、光沢度計などの測定機器を使う検査と、目視などによる官能検査がある。","作業の改善点は、仕様書や作業基準表に限らずに見つける必要がある。"],"a":1,"e":"組織品質は、事業所管理品質と現場管理品質でできている(2025年度問145・2022年度問143参照)。","l":"法令外","c":""},{"id":"2017-145","s":5,"q":"ほこりや汚れの除去について述べた次の文のうち、最も適当なものはどれか。","o":["油に溶ける物質は水に混ざりにくいので、ブラシを使って物理的に取る。","おがくずを使う方法は、ほこりを付着させる効果が小さい。","はたきがけは、建築物の室内の清掃方法に向いている。","アルミニウム建材の汚れは、弱アルカリ性洗剤で取る。","水で湿らせたタオルで汚れの部分を軽くこすり、タオルに付けば水溶性の汚れである。"],"a":4,"e":"湿ったタオルに移れば水溶性と判断できる(2021年度問145で正答)。おがくず法は付着効果が大きく(2025年度問147)、アルミニウムはアルカリに弱い(2022年度問145)。","l":"法令外","c":""},{"id":"2017-146","s":5,"q":"床の洗浄作業での環境対策について述べた次の文のうち、最も不適当なものはどれか。","o":["作業の頻度を高くすることに気を配って方法を選ぶ。","使った後の酸性・アルカリ性の洗剤は、中和してから流す。","洗剤や水を使うときの温度は、汚れや建材の性質を考えて適切に決める。","洗剤容器などは、廃棄物として環境の負担にならないものを選ぶ。","パッドやブラシは、汚れの状態に応じて研磨剤の種類や量を考えて選ぶ。"],"a":0,"e":"作業の頻度が上がると洗剤や水、エネルギーの使用量が増え、環境負荷も大きくなる。環境対策としては作業時間の短縮などが求められる(2020年度問146参照)。","l":"法令外","c":""},{"id":"2017-147","s":5,"q":"予防清掃について述べた次の文のうち、最も適当なものはどれか。","o":["現代の建築物では、窓やすき間がほこりの侵入路として重視されている。","建材に洗剤分を残すと、汚れを防ぐ効果が得られる。","水になじむ(親水性の)建材には、水溶性の物質が付きにくい。","建材を選ぶときは、清掃の立場も考えて選ぶ。","予防清掃としての建材の加工・改良は、人による汚れには効果があるが、自然による汚れには効果がない。"],"a":3,"e":"汚れにくく清掃しやすい建材を選ぶことは予防清掃の基本である。気密性の高い現代の建築物では窓やすき間からの侵入は少なく(2024年度問146)、洗剤分を残すと汚れやすくなる(2022年度問146)。","l":"法令外","c":""},{"id":"2017-148","s":5,"q":"床みがき機について述べた次の文のうち、最も不適当なものはどれか。","o":["凹凸のある床は、研磨粒子の付いたパッドを付けて洗う。","超高速バフ機の回転数は、毎分1,000〜3,000回転である。","床みがき機はスクラバマシンとも呼ばれる。","樹脂皮膜の剥離に使う床用パッドは、黒や茶が多い。","低速回転の洗剤供給式床みがき機は、カーペットのシャンプークリーニングに使える。"],"a":0,"e":"パッドは平らな面にしか当たらないので、凹凸のある床はブラシを付けて洗う(2024年度問148で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-149","s":5,"q":"カーペットクリーニングについて述べた次の文のうち、最も不適当なものはどれか。","o":["エクストラクタは、水に強いカーペットの洗浄に向いている。","アップライト型真空掃除機は、カーペットのほこりを取るのに向いている。","ふつうのフィルタ付き真空掃除機は、0.3μm程度の細かい粒子をとらえるように設計されている。","真空掃除機は、電動ファンで機械の中に空気の低圧部をつくり、ほこりを吸い込む。","スチーム洗浄機は、カーペットのしみ取りにも使われる。"],"a":2,"e":"この記述が誤り。0.3μm程度の細かい粒子までとらえるのはHEPAフィルタなどの高性能フィルタで、ふつうの真空掃除機のフィルタはそこまでとらえるように設計されていない。","l":"法令外","c":""},{"id":"2017-150","s":5,"q":"清掃作業に使う洗剤について述べた次の文のうち、最も適当なものはどれか。","o":["洗剤に使う界面活性剤は、陰イオン系と非イオン系の2つに大きく分けられる。","表面洗剤は、泡立ちがよい。","リノリウムに付いた油汚れを取るには、アルカリ性洗剤を使う。","合成洗剤の助剤はビルダと呼ばれ、洗浄効果を高める。","アルカリ性洗剤は、小便器に付いた尿石や鉄分を含む水あかを取るのに有効である。"],"a":3,"e":"助剤(ビルダ)は洗浄効果を高める(2023年度問150参照)。表面洗剤は泡立ちが少なく、リノリウムはアルカリに弱く、尿石や水あかには酸性洗剤を使う(2025年度問149)。","l":"法令外","c":""},{"id":"2017-151","s":5,"q":"床維持剤について述べた次の文のうち、最も適当なものはどれか。","o":["フロアフィニッシュは、顔料などの着色剤を含む床用塗料である。","フロアシーラは目止め剤として使い、床を保護し美観を高める。","フロアポリッシュは、物理的・化学的な方法でも簡単には除去できない製品群である。","フロアオイルは、おもに表面加工した木質系床材の保護に使う。","フロアポリッシュは、水性ワックスタイプが多く使われている。"],"a":1,"e":"フロアシーラは床材のすき間を埋める目止めとして使い、床を保護する。簡単に除去できないのはシーラの方で(2024年度問149)、フロアポリッシュはポリマータイプが主流である。","l":"法令外","c":""},{"id":"2017-152","s":5,"q":"床材の特徴について述べた次の文のうち、最も不適当なものはどれか。","o":["塩化ビニルタイルは、水に強い。","塩化ビニルシートは、床維持剤の密着不良が起きやすい。","セラミックタイルは、酸にもアルカリにも強い。","ゴムタイルは、溶剤に強い。","大理石には、酸性洗剤を使えない。"],"a":3,"e":"この記述が誤り。ゴムタイルは溶剤に弱く、溶剤で傷みやすい。","l":"法令外","c":""},{"id":"2017-153","s":5,"q":"繊維床材の特徴について述べた次の文のうち、最も不適当なものはどれか。","o":["玄関など人の通行が多い場所ほど汚れやすい。","日常作業として、パイルの表面の粗いごみをカーペットスイーパーなどで取る。","ポリプロピレン製のパイル素材は、親水性の汚れが取れにくい。","パイル素材のうち、ウールは含水率が高い。","しみは、繊維に吸着していただけのものが、時間がたって染み付いたものである。"],"a":2,"e":"ポリプロピレンは水をはじく素材で、親水性の汚れはしみになりにくい(2024年度問151でも正しい記述)。","l":"法令外","c":""},{"id":"2017-154","s":5,"q":"ドライメンテナンスについて述べた次の文のうち、最も不適当なものはどれか。","o":["一定期間を通した平均的な美観の度合いが高い。","ウェットメンテナンス法より部分補修がしやすい。","ドライバフ法は、研磨剤を含んだフロアパッドで磨いて光沢を戻す作業である。","ドライバフ法で使う床みがき機は、回転数が高いほど光沢を戻しやすい。","ウェットメンテナンス法より、作業の標準化・システム化がしやすい。"],"a":2,"e":"この記述が誤り(公式正答)。(1)(2)(4)(5)は2025年度問153・2022年度問150でも正しい記述として出題されている。","l":"法令外","c":""},{"id":"2017-155","s":5,"q":"床以外の清掃作業について述べた次の文のうち、最も不適当なものはどれか。","o":["廊下の壁は、階段の壁よりほこりが多く付く。","玄関ホールの清掃品質は、視線の向きや高さを変えて確かめる。","トイレの清掃用具は、便器用と洗面器などに使うものとで分ける。","エレベーターの壁などは手あかで汚れやすいので、表面に保護膜を塗っておくとよい。","人の手による汚れは、マイクロファイバークロスなど化学繊維の製品を使うと取りやすい。"],"a":0,"e":"ほこりが付きやすいのは、空気が上下に動く階段の壁の方である(2021年度問152・2025年度問154参照)。","l":"法令外","c":""},{"id":"2017-156","s":5,"q":"外装の清掃作業について述べた次の文のうち、最も不適当なものはどれか。","o":["窓ガラスの清掃は、ガラスに水や専用洗剤を塗り、窓用スクイジーでかき取る。","臨海工業地帯の窓ガラスは汚れが付きやすいので、3〜6か月に1回洗う。","金属材の外壁の清掃は、汚れが軽く固まらないうちに行う。","石材や陶磁器タイルの壁は少しずつ汚れていくので、3〜5年に1回程度洗う。","光触媒の酸化チタンコーティングには、清掃回数を減らす効果が期待されている。"],"a":1,"e":"窓ガラスは一般でも1〜2か月に1回洗う(2025年度問155・2021年度問153)ので、汚れやすい臨海工業地帯で3〜6か月に1回では間隔が長すぎる。","l":"法令外","c":""},{"id":"2017-157","s":5,"q":"建築物の清掃・消毒について述べた次の文のうち、最も不適当なものはどれか。","o":["ふだんの清掃の衛生管理の基本はゾーニング管理で、使う清掃用具を分けて作業する。","感染症が出たときの消毒に備え、建築物の衛生管理担当者は消毒剤の種類や使い方、対象物などの理解を深めておく必要がある。","ノロウイルス感染で吐いたと思われたので、吐いた物をふき取り、その部分を含む広い範囲を消毒した。","ノロウイルスに対して消毒効果が高い消毒薬として、逆性石けんがある。","感染症対策として、トイレ清掃のときに消毒剤(次亜塩素酸、過酸化水素水など)を含む洗剤を使った。"],"a":3,"e":"逆性石けん(第四級アンモニウム塩)はノロウイルスにはほとんど効かない(2025年度問156で同じ内容が正答)。","l":"法令外","c":""},{"id":"2017-158","s":5,"q":"ごみの処理の段階と環境保全対策の組合せとして、最も不適当なものはどれか。","o":["保管 ― 悪臭防止対策","収集・運搬 ― 騒音防止対策","最終処分 ― 水質汚濁防止対策","焼却処理 ― 大気汚染防止対策","破砕・圧縮処理 ― 地盤沈下防止対策"],"a":4,"e":"この組合せが誤り。破砕・圧縮処理で問題になるのは機械の騒音・振動などで、地盤沈下ではない。","l":"法令外","c":""},{"id":"2017-159","s":5,"q":"平成23年度の廃棄物の排出・処理の状況について述べた次の文のうち、最も不適当なものはどれか。","o":["ごみの中間処理量は4,010万トンで、そのうち焼却処理が85%である。","ごみの総資源化量は930万トンで、そのうち住民団体による集団回収量が265万トンである。","ごみの総排出量は4,539万トンで、そのうち71%が事業系ごみ、29%が家庭系ごみである。","業種別の産業廃棄物の排出量では、電気・ガス・熱供給・水道業が最も多い。","産業廃棄物の総排出量の52%にあたる約2億トンが再生利用されている。"],"a":2,"e":"家庭系と事業系が逆で、家庭系ごみが約7割を占める(2023年度問157・2025年度問157でも家庭系約70%が正しい内容)。統計の数字は年度で変わる。","l":"法令外(環境省の統計)","c":""},{"id":"2017-160","s":5,"q":"リサイクルを進めるための個別の法律について述べた次の文のうち、最も不適当なものはどれか。","o":["家電リサイクル法では、小売業者の責務によって、掃除機、電子レンジ、パソコンなどの廃家電の再商品化を進めることとされている。","容器包装リサイクル法では、容器包装の製造事業者と利用事業者は再商品化を進めることとされている。","小型家電リサイクル法では、消費者と事業者は、使用済小型電子機器などに使われている金属などの回収を進めることとされている。","食品リサイクル法では、食品関連事業者は、再生利用などの基準に従って再生利用を進めることとされている。","建設リサイクル法では、建設事業者は、建設資材廃棄物の分別解体と再資源化を進めることとされている。"],"a":0,"e":"家電リサイクル法の対象は、エアコン、テレビ、冷蔵庫・冷凍庫、洗濯機・衣類乾燥機の4品目で(特定家庭用機器再商品化法施行令第1条)、掃除機・電子レンジ・パソコンは含まれない。","l":"特定家庭用機器再商品化法施行令 第1条","c":""},{"id":"2017-161","s":5,"q":"ごみ2m³あたりの質量を600kgとするとき、60Lのごみ容器に入るごみの量として正しいものはどれか。","o":["6.0kg","10.0kg","12.0kg","18.0kg","36.0kg"],"a":3,"e":"2m³＝2,000Lなので1Lあたり600÷2,000＝0.3kg。60L×0.3kg/L＝18kg。","l":"計算","c":""},{"id":"2017-162","s":5,"q":"建築物内廃棄物について述べた次の文のうち、最も不適当なものはどれか。","o":["吸い殻を集めるときは、金属製のふた付き容器を使う。","大規模な建築物では、専任の収集・整理・搬出の作業員が配置されていることがある。","ビルの所有者は、必要な容器、集積場所、保管場所などを適切に用意する。","し尿を含まないビルピットの汚泥は、産業廃棄物である。","家庭から出る廃棄物より、事務所建築物の廃棄物の方が単位容積質量値は大きい。"],"a":4,"e":"事務所の廃棄物は紙くずが多くかさばるため、家庭の廃棄物より単位容積質量値は小さい(2020年度問162でも同じ内容が誤りとされている)。","l":"法令外","c":""},{"id":"2017-163","s":5,"q":"建築物内の廃棄物の種類と中間処理の方法の組合せとして、最も不適当なものはどれか。","o":["厨芥 ― 粉砕","新聞紙 ― 切断","プラスチック ― 圧縮","缶 ― 圧縮","段ボール ― 梱包"],"a":1,"e":"新聞紙はそのまま資源として回収するので、切断はしない(2021年度問163・2020年度問165参照)。","l":"法令外","c":""},{"id":"2017-164","s":5,"q":"建築物内廃棄物の保管場所について述べた次の文のうち、最も不適当なものはどれか。","o":["ほかの用途と兼ねない。","厨芥類などの臭気対策として、冷蔵庫や冷房設備は有効である。","排水槽や廃棄物保管設備の周辺など、ねずみ等が発生しやすい場所の点検は、6か月以内ごとに1回行う。","床の排水のため、適度な床の勾配をつける。","廃棄物処理に関する帳簿書類の保存期間は5年である。"],"a":2,"e":"排水槽や廃棄物保管設備の周辺など、特にねずみ等が発生しやすい箇所の調査は2か月以内ごとに1回(告示第119号 第6)。帳簿の5年保存は施行規則第20条のとおり。","l":"平成15年厚生労働省告示第119号 第6、建築物衛生法施行規則 第20条","c":""},{"id":"2017-165","s":5,"q":"廃棄物処理法に定める廃棄物の区分と、その対象となる廃棄物の組合せとして、最も不適当なものはどれか。","o":["専ら再生利用の目的となる廃棄物 ― 廃プラスチック類","産業廃棄物 ― グリース阻集器中の油分","特別管理廃棄物 ― 感染性廃棄物","再生利用認定制度の対象となる廃棄物 ― 廃ゴムタイヤ","一般廃棄物 ― 厨芥"],"a":0,"e":"専ら再生利用の目的となる廃棄物は、古紙・くず鉄・あきびん類・古繊維の4品目で、廃プラスチック類は含まれない(2024年度問159参照)。","l":"廃棄物処理法 第7条第1項・第14条第1項(ただし書)","c":""},{"id":"2017-166","s":6,"q":"蚊に関する記述として、最も不適当なものはどれか。","o":["チカイエカは、吸血しないで産卵することができる。","アカイエカは、有機物の多い下水溝などで発生する。","アカイエカとチカイエカの雌成虫は、外見で見分けることができる。","ヒトスジシマカの主な発生源として、公園・道路・公共施設などの雨水ますがある。","コガタアカイエカは、田んぼや湿地などの水域で発生する。"],"a":2,"e":"アカイエカとチカイエカの雌成虫は、外部形態で区別することができない。","l":"法令外","c":""},{"id":"2017-167","s":6,"q":"蚊の防除に関する記述として、最も不適当なものはどれか。","o":["昆虫成長制御剤(IGR)は、幼虫をすぐに殺す効果がある。","ライトトラップや粘着トラップでとれた蚊の数は、維持管理の水準を評価するのに役立つ。","チカイエカの対策として、浄化槽の通気管に防虫網を付ける。","樹脂蒸散剤は、密閉性が保たれた空間では1〜3か月間の効果が期待できる。","成虫を防除するための燻煙やULV処理には、残効性は期待できない。"],"a":0,"e":"IGRは幼虫を速効的に殺す薬剤ではない。IGRで処理しても成虫の密度がすぐに下がることはない(2021年問180で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-168","s":6,"q":"ゴキブリの防除に関する記述として、最も不適当なものはどれか。","o":["ローチスポットを確かめることは、ゴキブリの生息状況を知るよい方法の一つである。","ベイト剤(毒餌)は、処理が簡単ですぐに効くので、飲食店での使用に向いている。","昼間は物陰に隠れているので、薬剤を直接かけて防除するのは難しい。","空間処理をするときは、気密性を高める必要がある。","フェニトロチオン製剤による残留処理は、効果が大きい。"],"a":1,"e":"ベイト剤(毒餌)を「速効性」があるとした記述が誤り。","l":"法令外","c":""},{"id":"2017-169","s":6,"q":"ゴキブリの防除に関する記述として、最も適当なものはどれか。","o":["粘着式トラップはゴキブリに警戒心を起こさせるので、毎日置く場所を変えると効果的である。","残留処理とは、餌として薬剤を食べさせて中毒死させる方法である。","ULV処理には、専用の油剤を使う。","空間処理では、ホウ酸やヒドラメチルノンを有効成分とする製剤がよく使われる。","チャバネゴキブリでは、毒餌を食べようとしない喫食抵抗性をもつ個体が知られている。"],"a":4,"e":"チャバネゴキブリでは、毒餌への喫食抵抗性を示す個体が知られている(2020年問167でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-170","s":6,"q":"ダニ類に関する記述として、最も適当なものはどれか。","o":["マダニ類は、雌も雄も吸血する。","ダニの体は、頭部・胸部・胴体部に分けられる。","ツメダニ類はヒトから吸血し、激しいかゆみを起こす。","タカラダニは、冬に鉢植えなどで発生する。","イエダニは、屋内のちりなどを食べて育つ。"],"a":0,"e":"マダニ類は雌雄とも吸血する(2022年問170でも、マダニ類は幼虫・若虫・成虫のすべての段階で吸血するとされている)。","l":"法令外","c":""},{"id":"2017-171","s":6,"q":"ダニの防除に関する記述として、最も不適当なものはどれか。","o":["イエダニの被害があった場合は、室内にネズミの巣がある可能性が高い。","ヒゼンダニによる被害は、高齢者施設や病院で見られる。","ツメダニの被害は、ヒョウヒダニ類の防除対策で減らせる。","家のまわりにマダニ類を発生させないためには、ペットの衛生管理が重要である。","ケナガコナダニは、長い間の乾燥に強い。"],"a":4,"e":"ケナガコナダニの対策では乾燥状態を保つことが重要とされており(2024年問170で正しい記述として出題)、乾燥に強いとした記述が誤り。","l":"法令外","c":""},{"id":"2017-172","s":6,"q":"次の害虫のうち、吸血するものはどれか。","o":["チカイエカの雄成虫","オオチョウバエの雌成虫","セスジユスリカの雌成虫","トコジラミの雄成虫","ネコノミの幼虫"],"a":3,"e":"トコジラミは雄も雌も吸血する。","l":"法令外","c":""},{"id":"2017-173","s":6,"q":"害虫に関する記述として、最も不適当なものはどれか。","o":["イガは、繊維や衣類の害虫である。","ネコノミは、イヌやヒトからも吸血する。","ユスリカ類の防除では、性フェロモンを使ったトラップを使う。","ニクバエ類は、卵ではなく幼虫を産む卵胎生のハエである。","カツオブシムシ類は、乾燥食品や動物性の製品に害を与える。"],"a":2,"e":"ユスリカ類の防除に性フェロモンを使ったトラップを使うとした記述が誤り。","l":"法令外","c":""},{"id":"2017-174","s":6,"q":"殺虫剤の有効成分とその効き目に関する記述として、最も不適当なものはどれか。","o":["ピレスロイド剤は、物陰にいる虫を開けた場所に飛び出させるフラッシング効果を示す。","対称型の有機リン剤に抵抗性をもつ昆虫の集団にも、非対称型の有機リン剤は実用的な効果を示す。","すぐに効く有効成分には、残効性が期待できないものが多い。","除虫菊に含まれる殺虫成分と、合成されたそれに似た物質をまとめて、カーバメート系殺虫剤と呼ぶ。","昆虫成長制御剤(IGR)の中には、昆虫のホルモンと同じような働きをするものがある。"],"a":3,"e":"除虫菊の殺虫成分とその類似化合物の総称はピレスロイドである(2024年問173で正しい記述として出題)。","l":"法令外","c":""},{"id":"2017-175","s":6,"q":"殺虫剤とその剤型に関する記述として、最も適当なものはどれか。","o":["フェノトリンを有効成分とするゴキブリ用の食毒剤がある。","フェニトロチオンを有効成分とするマイクロカプセル(MC)剤がある。","炭酸ガス製剤は、有機溶剤に溶かした有効成分を、液化炭酸ガスで噴射する製剤である。","フィプロニルを有効成分とする樹脂蒸散剤がある。","エトフェンプロックスは、カーバメート系殺虫剤である。"],"a":1,"e":"フェニトロチオンを有効成分とするマイクロカプセル剤がある。なお液化炭酸ガス製剤に有機溶媒は使われず(2021年問177)、エトフェンプロックスはピレスロイド様化合物である(2024年問172)。","l":"法令外","c":""},{"id":"2017-176","s":6,"q":"ネズミの防除に関する記述として、最も不適当なものはどれか。","o":["捕獲の効果を上げるため、餌をつけたうえで数日間はトラップが作動しないようにするなどの工夫をする。","防鼠構造・工事基準案では、ドアのまわりのすき間は2cm以内にすることとしている。","よく食べる餌を確かめるため、毒餌を置く前の2〜3日間は何種類かの餌で予備調査をする。","目で見て生息や活動のしるしを確かめる調査方法がある。","防除では、餌を絶つことや、巣の材料を管理することなどが重要である。"],"a":1,"e":"ドアのまわりのすき間は1cm以内にする(2016年問173で正しい記述として出題)。2cm以内とした記述が誤り。","l":"法令外","c":""},{"id":"2017-177","s":6,"q":"ネズミ用の薬剤に関する記述として、最も適当なものはどれか。","o":["置いた毒餌から、貯穀害虫や食品害虫が発生することはない。","抗凝血性殺鼠剤に抵抗性をもつネズミの集団は知られていない。","カプサイシンは、第2世代の抗凝血性殺鼠剤である。","殺鼠剤は、口から取り込ませることで効果を発揮する。","シクロヘキシミドには、処理した区域からネズミを追い出す効果がある。"],"a":3,"e":"殺鼠剤は口から取り込ませて効かせる。皮膚から取り込ませて効く殺鼠剤はない(2020年問174)。","l":"法令外","c":""},{"id":"2017-178","s":6,"q":"衛生害虫と病気に関する記述として、最も不適当なものはどれか。","o":["イエバエは、腸管出血性大腸菌O157などの病原体を運ぶものとして注目されている。","トコジラミは、感染症の媒介にはかかわらないと考えられている。","コガタアカイエカが媒介する日本脳炎の患者は、西日本を中心に出ている。","ヒトスジシマカは住まいのまわりで発生し、デング熱やチクングニア熱を媒介する。","日本では、ヒトノミによる吸血被害が多い。"],"a":4,"e":"日本でヒトノミによる吸血被害が多いとした記述が誤り。","l":"法令外","c":""},{"id":"2017-179","s":6,"q":"次の文を読んで、解析・評価として最も適当なものはどれか。\nレストランの厨房で、チャバネゴキブリの防除のため殺虫剤を処理した。処理前に3か所へ3日間置いた粘着トラップでとれた数は合計180匹だった。処理後に3か所へ4日間置いたトラップでは合計24匹だった。","o":["処理前のゴキブリ指数は60である。","処理後のゴキブリ指数は8である。","この殺虫剤処理による防除率は90%である。","建築物の維持管理マニュアルの標準的な目標水準にあてはめると、処理後の状況は「警戒水準」にあたる。","すぐに再び防除作業をする必要はなく、6か月以内に1回、発生の多い場所では2か月以内に1回の定期調査を続ける。"],"a":2,"e":"ゴキブリ指数は「捕獲数÷トラップ数÷日数」。処理前は180÷3÷3=20、処理後は24÷3÷4=2。防除率は(20−2)÷20=90%となる。","l":"法令外","c":""},{"id":"2017-180","s":6,"q":"衛生害虫や殺虫剤に関する記述として、最も適当なものはどれか。","o":["殺虫剤抵抗性は、いろいろな系統の殺虫剤にくり返しふれることで免疫を獲得して発達する。","昆虫などへの不快感の程度は、第三者が客観的に判断するのは難しい。","殺虫剤の速効性は、LD50の値で評価される。","農薬は、建築物衛生法の特定建築物でのゴキブリの防除に使える。","ドバトが建物に巣をつくることは、ヒトへのヒゼンダニの寄生被害の原因になる。"],"a":1,"e":"不快感は主観的なもので、その程度を第三者が客観的に判断するのは難しい(2020年問180・2021年問180でも同じ趣旨の記述が正しいとされている)。なお特定建築物では医薬品または医薬部外品を使う必要がある(施行規則第4条の5第2項第2号)ので(4)は誤り。","l":"建築物衛生法施行規則 第4条の5第2項第2号(選択肢4)","c":""},{"id":"2018-1","s":0,"q":"医学に関する歴史上の人物とその功績の組合せとして、誤っているものはどれか。","o":["ヒポクラテス ― 西洋医学の体系の基礎をつくった。","ナイチンゲール ― 公衆衛生の概念を定義した。","パスツール ― 生命の自然発生説に異を唱えた。","コッホ ― 結核に関する研究の業績でノーベル賞を受賞した。","フレミング ― ペニシリンの発見に成功した。"],"a":1,"e":"公衆衛生の概念を定義したのはアメリカのウィンスローである。ナイチンゲールは看護の基礎を築いた人物として知られる。","l":"法令外","c":""},{"id":"2018-2","s":0,"q":"次の建築物のうち、建築物衛生法に基づく特定建築物に該当しないものはどれか。","o":["延べ面積が4,000m²の複合型映画館(シネマコンプレックス)","延べ面積が5,000m²の市民ホール","延べ面積が9,000m²の高等専門学校","延べ面積が9,000m²の製品試験研究所","延べ面積が4,000m²の地方銀行"],"a":3,"e":"製品試験研究所のような自然科学系の研究所は、特定用途(事務所など)に当たらないので特定建築物にならない。映画館は興行場、市民ホールは集会場、銀行は事務所・店舗に当たり、高等専門学校は8,000m²以上なので該当する。","l":"建築物衛生法 第2条、施行令 第1条","c":""},{"id":"2018-3","s":0,"q":"建築物衛生法に基づく特定建築物の延べ面積について、誤っているものはどれか。","o":["事務所に付随する廊下、階段、便所等の共用部分は、除外される。","店舗ビルに隣接しているが、独立して設置された客用立体駐車場は、除外される。","同一敷地内に独立した複数の建築物がある場合は、一棟の建築物ごとに算出する。","百貨店内の商品倉庫は、含まれる。","鉄道の運転保安施設は、除外される。"],"a":0,"e":"廊下・階段・便所などの共用部分は、特定用途に付随する部分として延べ面積に含める。独立した駐車場や鉄道の運転保安施設は含めない。","l":"建築物衛生法 第2条、施行令 第1条","c":""},{"id":"2018-4","s":0,"q":"建築物衛生法令の主な制度改正について、誤っているものはどれか。ただし、記載された年については判断しないものとする。","o":["昭和45年に、特定建築物の届出が厚生省(現 厚生労働省)から都道府県知事等に変更された。","昭和55年に、一定の人的・物的基準を要件とする事業者の都道府県知事による登録制度が設けられた。","平成13年に、新たに建築物空気調和用ダクト清掃業と建築物排水管清掃業が追加された。","平成14年に、建築物環境衛生管理基準の大幅な改正及び特定建築物の範囲の見直しが行われた。","平成22年に、特定建築物の届出事項に特定建築物の維持管理権原者の氏名などが追加された。"],"a":0,"e":"昭和45年は建築物衛生法そのものができた年で、届出先は最初から都道府県知事等である。「厚生省から変更された」という事実はない。","l":"法令外(建築物衛生法の改正の経緯)","c":""},{"id":"2018-5","s":0,"q":"建築物衛生法に基づく特定建築物の届出について、施行規則に定められていない事項はどれか。","o":["名称","構造設備の概要","建築確認済の年月日","用途","使用されるに至った年月日"],"a":2,"e":"施行規則第1条の届出事項は、名称・所在場所・用途・延べ面積・構造設備の概要・維持管理権原者や所有者の氏名・管理技術者の氏名・使用開始の年月日などで、建築確認済の年月日は含まれない。","l":"建築物衛生法施行規則 第1条","c":""},{"id":"2018-6","s":0,"q":"建築物環境衛生管理基準に基づく空気環境の調整について、正しいものはどれか。","o":["温度の基準は、15℃以上29℃以下である。","相対湿度の基準は、40%以上70%以下である。","粉じん計は、経済産業大臣の登録を受けた者が較正したものを使う。","ホルムアルデヒドの測定は、毎年6月1日から9月30日までの間に行う。","測定位置は、居室の中央部の床上70cm以上160cm以下である。"],"a":1,"e":"相対湿度の基準は40%以上70%以下である。温度は18℃以上28℃以下、粉じん計は厚生労働大臣の登録を受けた者が較正したもの、ホルムアルデヒドは新築・大規模修繕などの後の最初の6月1日〜9月30日に1回、測定位置は床上75cm以上150cm以下。","l":"建築物衛生法施行令 第2条第1号、施行規則 第3条の2","c":"出題時の選択肢(3)は「粉じん計は、2年以内ごとに1回較正する」(当時は1年以内ごとに1回が正しいとされた)だったが、現行の施行規則第3条の2には較正の間隔が書かれておらず誤りと言い切れないため、条文にある「較正を行う者」を誤らせた記述に差し替えた(正答は変わらない)。"},{"id":"2018-7","s":0,"q":"建築物衛生法に基づく空気環境の測定方法について、誤っているものはどれか。","o":["温度の測定器は、0.5度目盛の温度計を使用する。","相対湿度の測定器は、0.5度目盛の乾湿球湿度計を使用する。","一酸化炭素の含有率の測定は、検知管方式による一酸化炭素検定器を使用する。","二酸化炭素の含有率の測定は、検知管方式による二酸化炭素検定器を使用する。","気流の測定には、0.5メートル毎秒以上の気流を測定することのできる風速計を使用する。"],"a":4,"e":"気流は、0.2m/秒以上の気流を測れる風速計で測る。0.5m/秒からしか測れないと、基準(0.5m/秒以下)を満たす弱い気流を測れない。","l":"建築物衛生法施行規則 第3条の2","c":""},{"id":"2018-8","s":0,"q":"建築物衛生法で定める空気環境について、その要因と人体への影響の記述として、最も不適当なものはどれか。","o":["浮遊粉じんの人体への影響は著しいものがあり、特に呼吸器系に対しては直接的である。","二酸化炭素は極めて有毒な気体であり、中毒死、あるいは死に至らなくとも脳障害の後遺症が残る等、人体に対する影響は重大である。","室内温度と外気温度の差を無視した過度の冷房による神経痛などの冷房病、また過度の暖房による呼吸器系疾患など、温度は人体への影響が大きい。","気流は、湿度と同様に、温度との関連に注意する必要があり、冷風の人体に対する影響を考慮して規定されている。","ホルムアルデヒドは、不快感を伴う目・鼻・喉への刺激、さらに高濃度になれば催涙・呼吸困難等の症状を引き起こす。"],"a":1,"e":"中毒死や脳障害の後遺症を起こす極めて有毒な気体は一酸化炭素である。二酸化炭素の基準は、それ自体の毒性よりも、換気が足りているかの目安として決められている。","l":"法令外","c":""},{"id":"2018-9","s":0,"q":"空気調和設備である加湿装置の維持管理について、最も適当なものはどれか。","o":["加湿装置の汚れの点検は、使用期間中に1回行う。","加湿装置の清掃は、2年以内ごとに1回行う。","加湿装置により、居室内部の空気が病原体によって汚染されることはない。","加湿装置に供給する水は、水道法の水質基準に適合した水を使用する。","加湿装置の排水受け(ドレンパン)に、水が常時十分に溜まっていることを確認する。"],"a":3,"e":"加湿装置に入れる水は、水道法第4条の水質基準に合う必要がある。汚れの点検は使用開始時と使用中1か月以内ごとに1回、清掃は1年以内ごとに1回。ドレンパンに水がたまると菌が増えるので、たまらないようにする。","l":"建築物衛生法施行規則 第3条の18","c":""},{"id":"2018-10","s":0,"q":"建築物環境衛生管理技術者の免状を持っている者であっても、建築物衛生法に基づく事業の登録で、人的基準の要件として認められないものはどれか。","o":["建築物空気環境測定業の空気環境測定実施者","建築物排水管清掃業の排水管清掃作業監督者","建築物空気調和用ダクト清掃業のダクト清掃作業監督者","建築物飲料水貯水槽清掃業の貯水槽清掃作業監督者","建築物ねずみ昆虫等防除業の防除作業監督者"],"a":4,"e":"防除作業監督者は、免状を持っていても、厚生労働大臣の登録を受けた者が行う防除作業監督者講習を修了していなければならない。ほかの4つは、免状を持つ人が講習修了者と同等以上の者として認められている。","l":"建築物衛生法施行規則 第26条、第26条の3、第28条、第28条の3、第29条","c":""},{"id":"2018-11","s":0,"q":"建築物衛生法第12条の6に基づき、厚生労働大臣が指定した登録業者等の団体(指定団体)の業務として、最も不適当なものはどれか。","o":["登録業者の業務を適正に行うための技術上の基準の設定","登録業者の業務についての指導","登録業者の業務を受託する料金の統一","登録業者の業務に従事する者の福利厚生に関する施設","登録業者の業務に従事する者に対する業務に必要な知識及び技能についての研修"],"a":2,"e":"指定団体の業務は、技術上の基準の設定、業務の指導、従事者の研修、従事者の福利厚生施設の4つである。料金を統一することは含まれない。","l":"建築物衛生法 第12条の6","c":""},{"id":"2018-12","s":0,"q":"建築物衛生法に基づく、国又は地方公共団体の用に供する特定建築物について、正しいものはどれか。","o":["建築物環境衛生管理技術者の選任は必要ない。","建築物環境衛生管理基準は適用されない。","都道府県知事等は、立入検査を行うことができない。","都道府県知事等は、維持管理記録の提出を求めることができない。","都道府県知事等は、改善措置の勧告をすることができない。"],"a":2,"e":"国や地方公共団体の特定建築物には、立入検査(第11条)と改善命令(第12条)が適用されない。その代わり、説明や資料の提出を求めたり、改善を勧告したりできる。管理技術者の選任と管理基準は、ほかの特定建築物と同じく必要である。","l":"建築物衛生法 第13条","c":""},{"id":"2018-13","s":0,"q":"建築物衛生法に基づく立入検査と改善命令について、次の文の( )に入る語句の組合せとして、正しいものはどれか。\n「都道府県知事(保健所を設置する市又は特別区にあっては市長又は区長)が必要と認めるときは、( ア )に、立入検査を行わせることができる。この立入検査によって、特定建築物の維持管理が建築物環境衛生管理基準に従って行われておらず、かつ、その特定建築物内における( イ )をそこない、又はそこなうおそれのあるときは、その特定建築物の( ウ )に対して維持管理の方法の改善、その他必要な措置をとることを命ずることができる。」","o":["ア 環境衛生監視員　イ 人の健康　ウ 維持管理権原者","ア 環境衛生指導員　イ 人の健康　ウ 環境衛生管理技術者","ア 環境衛生指導員　イ 公衆の利益　ウ 維持管理権原者","ア 環境衛生監視員　イ 公衆の利益　ウ 環境衛生管理技術者","ア 環境衛生監視員　イ 人の健康　ウ 環境衛生管理技術者"],"a":0,"e":"立入検査を行う職員は環境衛生監視員である。改善命令は「人の健康」をそこなうおそれがあるときに、維持管理について権原を持つ者(維持管理権原者)に出す。管理技術者は命令の相手ではない。","l":"建築物衛生法 第11条、第12条","c":""},{"id":"2018-14","s":0,"q":"保健所の事業として、最も不適当なものはどれか。","o":["地域保健に関する思想の普及及び向上に関する事項","栄養の改善及び食品衛生に関する事項","住宅、水道、下水道、廃棄物の処理、清掃その他の環境の衛生に関する事項","医事及び薬事に関する事項","労働者の衛生に関する事項"],"a":4,"e":"労働者の衛生は、労働基準監督署など労働行政の仕事であり、地域保健法第6条の保健所の事業には入っていない。","l":"地域保健法 第6条","c":""},{"id":"2018-15","s":0,"q":"水道法第4条(水道により供給される水が備えなければならない要件)の条文に定められているものとして、誤っているものはどれか。","o":["銅、鉄、フッ素、フェノールを含まないこと。","病原生物に汚染され、又は病原生物に汚染されたことを疑わせるような生物若しくは物質を含むものでないこと。","異常な酸性又はアルカリ性を呈しないこと。","異常な臭味がないこと。ただし、消毒による臭味を除く。","外観は、ほとんど無色透明であること。"],"a":0,"e":"条文は「銅、鉄、弗素、フェノールその他の物質をその許容量をこえて含まないこと」であり、まったく含まないことまでは求めていない。","l":"水道法 第4条","c":""},{"id":"2018-16","s":0,"q":"下水道法について、最も不適当なものはどれか。","o":["下水とは生活若しくは事業(耕作の事業を除く。)に起因し、若しくは付随する廃水又は雨水をいう。","公共下水道の排水区域内の土地の所有者、使用者又は占有者は、その土地の下水を公共下水道に流入させるために必要な排水設備を設置しなければならない。","公共下水道管理者は、公共下水道を設置しようとするときは、あらかじめ、事業計画を定めなければならない。","公共下水道の設置、改築、修繕、維持その他の管理は、原則として都道府県が行う。","公共下水道管理者は、公共下水道などに著しく悪影響を及ぼすおそれのある下水を継続して排除して公共下水道を使用する者に対し、除害施設の設置などの必要な措置をしなければならない旨を定めることができる。"],"a":3,"e":"公共下水道の設置や管理は、原則として市町村が行う(下水道法第3条)。都道府県が行うのは主に流域下水道である。","l":"下水道法 第2条、第3条、第4条、第10条、第12条","c":""},{"id":"2018-17","s":0,"q":"興行場法第3条の次の条文の( )に入る語句の組合せとして、正しいものはどれか。\n「営業者は、興行場について、換気、( ア )、( イ )及び清潔その他入場者の衛生に必要な措置を講じなければならない。その措置の基準については、( ウ )で、これを定める。」","o":["ア 採光　イ 防湿　ウ 都道府県が条例","ア 採光　イ 防湿　ウ 厚生労働省が省令","ア 照明　イ 防湿　ウ 都道府県が条例","ア 照明　イ 保温　ウ 厚生労働省が省令","ア 採光　イ 保温　ウ 都道府県が条例"],"a":2,"e":"興行場法第3条は「換気、照明、防湿及び清潔」の措置を求め、その基準は都道府県が条例で定めるとしている。映画館などは窓が少ないので「採光」ではなく「照明」である。","l":"興行場法 第3条","c":""},{"id":"2018-18","s":0,"q":"次の生活衛生関係営業のうち、施設の開設又は営業に当たって許可を要しないものの組合せとして、正しいものはどれか。\nア 映画館　イ ホテル　ウ 理容所　エ 公衆浴場　オ クリーニング所","o":["アとイ","アとウ","イとエ","ウとオ","エとオ"],"a":3,"e":"理容所とクリーニング所は、開設するときに届出をすればよく、許可はいらない。映画館(興行場法)、ホテル(旅館業法)、公衆浴場(公衆浴場法)は許可が必要である。","l":"理容師法 第11条、クリーニング業法 第5条、興行場法 第2条、旅館業法 第3条、公衆浴場法 第2条","c":""},{"id":"2018-19","s":0,"q":"労働安全衛生法に定める事業者の責務として、最も不適当なものはどれか。","o":["事業場の規模に応じて、産業医を選任しなければならない。","事業場の規模に応じて、健康診断の結果を保健所長に報告しなければならない。","有害な業務を行う屋内作業場その他の作業場で、必要な作業環境測定を行い、及びその結果を記録しておかなければならない。","一定規模の事業場においては、常時使用する労働者に対し、医師、保健師等による心理的な負担の程度を把握するための検査を行わなければならない。","伝染性の疾病その他の疾病で、厚生労働省令で定めるものにかかった労働者については、その就業を禁止しなければならない。"],"a":1,"e":"健康診断の結果の報告先は、保健所長ではなく所轄の労働基準監督署長である(常時50人以上の労働者を使う事業場)。","l":"労働安全衛生法 第13条、第65条、第66条の10、第68条、労働安全衛生規則 第52条","c":""},{"id":"2018-20","s":0,"q":"建築物衛生法と関連する法律について、最も不適当なものはどれか。","o":["地域保健法に基づいて設置された保健所は、建築物環境衛生に関する相談指導などを行う。","建築基準法は、建築物について環境衛生上の維持管理を行うことを定めている。","労働安全衛生法は、労働者という特定の集団を対象として、工場など特定の作業場における環境条件などを定めている。","学校保健安全法は、児童及び生徒という特定の集団を対象として、学校における環境条件などを定めている。","建築物衛生法は、給水の水質基準などについて水道法の基準の一部を準用している。"],"a":1,"e":"建築基準法は、建物の構造・設備など建てるときの最低基準を定める法律である。建てた後の環境衛生上の維持管理を定めているのは建築物衛生法である。","l":"法令外(建築基準法 第1条、建築物衛生法 第1条)","c":""},{"id":"2018-21","s":1,"q":"環境基本法に基づく環境基準の説明として、最も不適当なものはどれか。","o":["人の健康を保護する上で維持することが望ましい基準である。","実験室内での動物実験などの生物学的研究を判断に用いている。","罹患状況の疫学調査を判断に用いている。","経験的に証明されている有害濃度を基礎とした安全度を考慮している。","地球環境を保全する上で維持することが望ましいものである。"],"a":4,"e":"環境基準は「人の健康を保護し、及び生活環境を保全する上で維持されることが望ましい基準」(環境基本法第16条)である。地球環境の保全を目的とした基準ではない。","l":"環境基本法 第16条","c":""},{"id":"2018-22","s":1,"q":"作業区分とその例の組合せとして、最も不適当なものはどれか。なお、単位のm²は体表面積である。(平均代謝率の数値は、ISO 7243、JIS Z 8504による。)","o":["安静(平均代謝率65W/m²) ― 仰臥位(仰向け)","低代謝率(平均代謝率100W/m²) ― 軽い手作業","中程度代謝率(平均代謝率165W/m²) ― のこぎりをひく","高代謝率(平均代謝率230W/m²) ― コンクリートブロックを積む","極高代謝率(平均代謝率290W/m²) ― 階段を登る"],"a":2,"e":"のこぎりをひく作業は、腕と胴体を強く使うので高代謝率の作業に分類される。中程度代謝率の例は、くぎ打ちや普通の速さで歩くことなどである。","l":"法令外","c":""},{"id":"2018-23","s":1,"q":"高齢者の快適温度について、最も不適当なものはどれか。","o":["一般に若年者に比べ、暖かい温度を好むとされている。","冬季には、室温は若年者と比較して高い場合が多い。","冬季には、若年者に比べ深部体温は低い傾向にある。","放射熱がない場合、高齢者の8割を満足させる気温の範囲は青年に比べ狭い範囲となる。","高齢者では、寒冷環境に曝露された際の血圧の変動が若年者に比べ顕著である。"],"a":1,"e":"高齢者は暖かい温度を好むが、寒さを感じにくいことなどから、実際の冬の室温は若年者より低い場合が多い。","l":"法令外","c":""},{"id":"2018-24","s":1,"q":"熱中症について、最も不適当なものはどれか。","o":["熱失神は、頭頸部が直射日光などにさらされたことにより末梢血管の拡張を生じることによって起こる。","熱射病では、体温調節中枢の機能に障害を来し、自力での体温調節ができず体温が急激に上昇する。","熱疲労は、多量の発汗により体内の水分や塩分が不足することに加え、全身的な循環不全による重要諸臓器の機能低下によって起こる。","熱けいれんは、過剰な発汗により血液中の塩分が濃縮されることによって起こる。","熱射病の治療は、全身の冷却が第一であるが冷やし過ぎには十分に注意する。"],"a":3,"e":"熱けいれんは、大量の汗で塩分が失われたところに水だけを飲み、血液中の塩分が薄くなって起こる。塩分が濃くなるのではない。","l":"法令外","c":""},{"id":"2018-25","s":1,"q":"冬季の暖房時の留意事項の組合せとして、最も適当なものはどれか。\nア 床上0.1mと1.1mの温度差を、3℃以下とする。\nイ 気流は、1.5m/s程度に保つ。\nウ ウォームビズの導入によりCO2排出量を削減できる。\nエ 低湿度では、呼吸器疾患に罹患しやすい。","o":["アとイとウとエ","アとウとエ","アとエ","イとウとエ","ウとエ"],"a":1,"e":"1.5m/sの気流は強すぎて寒く感じるので誤り(建築物衛生法の基準も0.5m/s以下)。上下の温度差3℃以下、ウォームビズによる省エネ、低湿度で呼吸器の病気にかかりやすいことは正しい。","l":"法令外","c":""},{"id":"2018-26","s":1,"q":"シックビル症候群について、最も不適当なものはどれか。","o":["仕事のストレスは、発症の危険因子である。","揮発性有機化合物が原因の一つと考えられる。","特異的な症状を呈する。","アトピー体質は、発症の危険因子である。","問題となるビルから離れれば症状は治まる。"],"a":2,"e":"シックビル症候群の症状は、目・鼻・喉の刺激感や頭痛、だるさなど、この病気だけに特有ではない「非特異的」なものである。","l":"法令外","c":""},{"id":"2018-27","s":1,"q":"室内の空気汚染による健康影響が一因となる疾患として、最も不適当なものはどれか。","o":["ジカウイルス感染症","気管支喘息","慢性閉塞性肺疾患","肺癌","レジオネラ症"],"a":0,"e":"ジカウイルス感染症は、蚊(ネッタイシマカやヒトスジシマカ)に刺されてうつる病気で、室内の空気汚染とは関係がない。","l":"法令外","c":""},{"id":"2018-28","s":1,"q":"ホルムアルデヒドについて、最も不適当なものはどれか。","o":["可燃性である。","防腐剤として用いられる。","発がん性がある。","水に溶けにくい。","建築基準法により、含有建材の使用が制限されている。"],"a":3,"e":"ホルムアルデヒドは水によく溶ける。その水溶液がホルマリンで、防腐剤などに使われる。","l":"建築基準法 第28条の2(選択肢5)","c":""},{"id":"2018-29","s":1,"q":"たばこについて、最も不適当なものはどれか。","o":["喫煙により、肺気腫のリスクが増大する。","受動喫煙により、小児の呼吸器系疾患のリスクが増加する。","副流煙は、喫煙者が吐き出す煙のことである。","妊娠中の喫煙により、低出生体重児の頻度が高くなる。","主流煙と副流煙の組成は異なる。"],"a":2,"e":"副流煙は、火のついたたばこの先から立ちのぼる煙のことである。喫煙者が吐き出す煙は「呼出煙」という。","l":"法令外","c":""},{"id":"2018-30","s":1,"q":"建築物衛生法による一酸化炭素の含有率の基準値として、最も適当なものはどれか。","o":["1ppm以下","2ppm以下","5ppm以下","6ppm以下","50ppm以下"],"a":3,"e":"建築物環境衛生管理基準では、一酸化炭素の含有率は100万分の6(6ppm)以下と決められている。","l":"建築物衛生法施行令 第2条第1号イ","c":"出題時の正解の選択肢(4)は「原則10ppm以下」だったが、2022年4月施行の施行令改正で基準が6ppm以下になり、外気が汚れている場合の特例(「原則」の部分)もなくなったため、選択肢(4)を「6ppm以下」にし、すべての選択肢から「原則」を外した。"},{"id":"2018-31","s":1,"q":"二酸化炭素について、次の文の( )に入る数値の組合せとして、最も適当なものはどれか。\n「大気中の二酸化炭素濃度は( ア )ppm程度である。建築物衛生法では、室内の二酸化炭素の含有率の基準は( イ )ppm以下と定められている。」","o":["ア 100　イ 1,000","ア 400　イ 1,000","ア 400　イ 5,000","ア 4,000　イ 5,000","ア 4,000　イ 10,000"],"a":1,"e":"大気中の二酸化炭素はおよそ400ppm(0.04%)である。建築物環境衛生管理基準では、室内の二酸化炭素は1,000ppm以下とされている。","l":"建築物衛生法施行令 第2条第1号イ","c":""},{"id":"2018-32","s":1,"q":"騒音について、最も不適当なものはどれか。","o":["騒音によって起こる4,000Hz付近の聴力低下を、C5ディップという。","大きく高い騒音に一時的に曝露されることによる聴力の低下を、一過性聴力閾値低下という。","騒音によって、末梢血管の収縮、血圧の上昇、胃の働きの抑制等が起きる。","マスキング効果は、マスクされる音の最小可聴値の音圧レベル上昇量で示される。","騒音による永久性難聴の程度や進行具合には、個人差が大きい。"],"a":1,"e":"一時的に聞こえにくくなる現象は「一過性聴力閾値上昇」という。聞こえる最も小さい音のレベル(閾値)が上がるので、「低下」ではなく「上昇」である。","l":"法令外","c":""},{"id":"2018-33","s":1,"q":"光の知覚について、最も不適当なものはどれか。","o":["視力はランドルト環の切れ目を見ることで測る。","杆体細胞は暗いときに働き、錐体細胞は明るいときに働く。","明るい場所から暗い場所への順応を暗順応といい、完全に順応するには40分以上かかる。","視細胞には杆体細胞と錐体細胞があるが、数は錐体細胞の方が多い。","照明の質を高めるためには、グレアを防止することが必要である。"],"a":3,"e":"視細胞の数は、杆体細胞(約1億2,000万個)の方が錐体細胞(約600万個)よりずっと多い。","l":"法令外","c":""},{"id":"2018-34","s":1,"q":"VDT作業と健康について、最も不適当なものはどれか。","o":["エアコンからの風が当たる場所では、ドライアイを引き起こす可能性がある。","ディスプレイ画面の明るさや、書類・キーボード面の明るさと、周りの明るさとの差は、なるべく小さくする。","グレアを防止するためには、視野内の輝度はほぼ同じレベル(最大でも1:10程度)にする。","ディスプレイ画面に太陽光が入射する場合には、カーテンなどで調節する。","書類上及びキーボード上における照度は200lx以下とする。"],"a":4,"e":"情報機器作業のガイドラインでは、書類やキーボードの上の照度は300lx以上を目安とする。200lx以下では暗すぎる。","l":"法令外(情報機器作業における労働衛生管理のためのガイドライン)","c":"出題時の選択肢(2)は「ディスプレイ画面における照度は500lx以下とする」だったが、2021年12月のガイドライン改正でこの目安が削除されたため、改正後のガイドラインにある「明るさの差をなるべく小さくする」という正しい記述に差し替えた(正答は変わらない)。"},{"id":"2018-35","s":1,"q":"赤外線の作用による疾患として、最も適当なものはどれか。","o":["熱中症","皮膚癌","無精子症","白血病","急性角膜炎"],"a":0,"e":"赤外線は主に熱として働くので、強く浴びると熱中症や白内障、やけどの原因になる。皮膚癌や急性角膜炎は紫外線、無精子症や白血病は電離放射線による。","l":"法令外","c":""},{"id":"2018-36","s":1,"q":"電場・磁場・電磁波について、最も不適当なものはどれか。","o":["電場の単位は、V/mである。","磁場の単位は、A/mである。","電子レンジは、超短波(VHF波)を利用している。","電磁波に含まれるエックス線、γ線は電離放射線と呼ばれる。","電磁波の周波数が高くなると波長は短くなる。"],"a":2,"e":"電子レンジが使っているのは、周波数2.45GHzのマイクロ波である。超短波(VHF)はFM放送などに使われる、もっと周波数の低い電波である。","l":"法令外","c":""},{"id":"2018-37","s":1,"q":"放射線の身体的影響のうち、早期影響はどれか。","o":["白内障","不妊","悪性リンパ腫","皮膚癌","胎児の障害"],"a":1,"e":"不妊は、大量に被ばくしてから短い期間で現れる早期影響である。白内障・悪性リンパ腫・皮膚癌は何年もたってから出る晩発影響である。","l":"法令外","c":""},{"id":"2018-38","s":1,"q":"健康な人と水について、最も不適当なものはどれか。","o":["体重当たりの水分欠乏率が2%程度になると、強い口渇が認められる。","体内における食物の代謝過程で生成される代謝水は、1日約0.3Lである。","一般に体重当たりの体内水分量は、女性の方が男性より多い。","成人の体内の水分量は、体重の約50〜70%である。","小児が生理的に必要とする水分量は、体重当たりに換算すると成人より多い。"],"a":2,"e":"女性は男性より脂肪の割合が高く、脂肪は水分が少ないので、体重当たりの水分量は女性の方が少ない。","l":"法令外","c":""},{"id":"2018-39","s":1,"q":"水系感染症の病原体として、最も不適当なものはどれか。","o":["ノロウイルス","麻しんウイルス","A型肝炎ウイルス","赤痢アメーバ","パラチフス菌"],"a":1,"e":"麻しん(はしか)ウイルスは、空気感染や飛沫感染でうつる。水を通してうつる病原体ではない。","l":"法令外","c":""},{"id":"2018-40","s":1,"q":"ヒ素について、最も適当なものはどれか。","o":["5価の化合物の方が3価の化合物よりも毒性が強い。","水俣病は、その慢性中毒である。","慢性影響として、皮膚の色素沈着や角化は認められない。","環境基本法に基づく水質汚濁に係る環境基準項目に含まれない。","ヒトに対する発がん性が認められる。"],"a":4,"e":"ヒ素は人に対して発がん性がある。毒性は3価の方が強く、慢性中毒では皮膚の色素沈着や角化が起こる。水俣病はメチル水銀によるもので、ヒ素は水質汚濁の環境基準項目に含まれる。","l":"法令外","c":""},{"id":"2018-41","s":1,"q":"次の感染症のうち、原虫によって起こる病気の組合せとして、正しいものはどれか。\nア 発しんチフス　イ カンジダ症　ウ クリプトスポリジウム症　エ マラリア　オ ワイル病","o":["アとイ","アとオ","イとウ","ウとエ","エとオ"],"a":3,"e":"クリプトスポリジウム症とマラリアは原虫による。発しんチフスはリケッチア、カンジダ症は真菌(カビ)、ワイル病はスピロヘータ(レプトスピラ)による。","l":"法令外","c":""},{"id":"2018-42","s":1,"q":"感染症法に基づく感染症の類型で、三類感染症に分類されるものはどれか。","o":["マラリア","コレラ","日本脳炎","狂犬病","デング熱"],"a":1,"e":"コレラは三類感染症である。マラリア・日本脳炎・狂犬病・デング熱は、動物や蚊などを介してうつる四類感染症である。","l":"感染症法 第6条","c":""},{"id":"2018-43","s":1,"q":"レジオネラ症について、最も適当なものはどれか。","o":["病原体は、一般に10℃前後で最もよく繁殖する。","病原体は、自然界の土壌や淡水中等に生息している。","感染症法において、二類感染症に分類されている。","垂直感染する感染症である。","感染の起こりやすさに対して、ヒトの個体差や体調差は影響しない。"],"a":1,"e":"レジオネラ属菌は土や川・湖などの淡水に住んでいる。よく増えるのは36℃前後で、感染症法では四類感染症。母子感染(垂直感染)はせず、高齢者や体が弱った人ほどかかりやすい。","l":"感染症法 第6条","c":""},{"id":"2018-44","s":1,"q":"消毒用エタノールを使った薬液消毒について、最も不適当なものはどれか。","o":["70%溶液が至適濃度である。","手指や皮膚の消毒に用いられる。","一部のウイルスには無効である。","殺菌力はホルマリンによって減少する。","芽胞に対して有効である。"],"a":4,"e":"エタノールは、細菌の芽胞(熱や薬に強い休眠状態の形)には効かない。","l":"法令外","c":""},{"id":"2018-45","s":1,"q":"5%溶液として市販されている次亜塩素酸ナトリウム16mLに水を加え、およそ20mg/Lの濃度に薄めるときに加える水の量として、最も近いものはどれか。","o":["0.8L","3.2L","4L","32L","40L"],"a":4,"e":"5%は50,000mg/Lなので、20mg/Lにするには2,500倍に薄める。16mL×2,500=40,000mL=40Lなので、加える水はおよそ40Lである。","l":"法令外","c":""},{"id":"2018-46","s":2,"q":"次の用語とその単位との組合せのうち、誤っているものはどれか。","o":["比エンタルピー ― W/kg(DA)","光度 ― cd","振動加速度 ― m/s²","熱伝導率 ― W/(m・K)","音圧 ― Pa"],"a":0,"e":"比エンタルピーは乾き空気1kgあたりの熱量で、単位はkJ/kg(DA)。W(ワット)は1秒あたりの熱量(仕事率)の単位なので誤り。","l":"法令外","c":""},{"id":"2018-47","s":2,"q":"エアロゾル粒子の一般的な粒径が、大きい順に並んでいるものは次のうちどれか。","o":["霧雨 ― 花粉 ― ウイルス","バクテリア ― ウイルス ― 霧雨","ウイルス ― 霧雨 ― バクテリア","花粉 ― ウイルス ― バクテリア","ウイルス ― バクテリア ― 花粉"],"a":0,"e":"霧雨は数十μm、花粉は数十μm弱、バクテリアは1μm前後、ウイルスは0.1μm以下。大きい順は「霧雨 ― 花粉 ― ウイルス」。","l":"法令外","c":""},{"id":"2018-48","s":2,"q":"壁体の熱貫流率が4W/(m²・K)であるとき、室内温度が24°C、室外温度が4°Cであった。この壁の室内側表面温度に、最も近いものは次のうちどれか。ただし、室内側熱伝達率を10W/(m²・K)、室外側熱伝達率を20W/(m²・K)とする。","o":["8°C","12°C","14°C","16°C","20°C"],"a":3,"e":"壁を通る熱は4×(24－4)＝80W/m²。室内側では80＝10×(24－表面温度)なので、表面温度＝24－8＝16℃。","l":"計算","c":""},{"id":"2018-49","s":2,"q":"一辺が4mの正方形の壁材料を組合せて立方体の室を作り、日射が当たらない条件で床面に固定した。壁材料の熱貫流率を1.25W/(m²・K)、隙間換気は無視できるとし、外気温度が0°Cの条件下で内部を加熱したところ、十分に時間が経過した後の室温度が25°Cになった。なお、床面は完全に断熱されており、床を通しての熱移動はない。このとき、室内での発熱量として、最も適当なものは次のうちどれか。","o":["1,300W","1,600W","2,000W","2,500W","3,000W"],"a":3,"e":"床は断熱されているので、熱が逃げるのは4つの壁と天井の5面で、面積は16m²×5＝80m²。発熱量＝1.25×80×(25－0)＝2,500W。","l":"計算","c":"","g":["img/2018-49.png"]},{"id":"2018-50","s":2,"q":"湿り空気と湿度に関する次の記述のうち、最も不適当なものはどれか。","o":["湿り空気の温度が一定の状態で絶対湿度を増加させると、比エンタルピーは増加する。","絶対湿度とは、湿り空気1kgに含まれる水蒸気の質量のことである。","湿り空気中の水蒸気の持つ分圧を水蒸気分圧という。","露点温度における湿り空気では、乾球温度と湿球温度は等しい。","相対湿度とは、同じ温度での、飽和水蒸気圧に対する水蒸気分圧の比である。"],"a":1,"e":"絶対湿度は、湿り空気ではなく「乾き空気」1kgあたりに含まれる水蒸気の質量(kg/kg(DA))である。","l":"法令外","c":""},{"id":"2018-51","s":2,"q":"ダクト内気流速度が4.0m/sであったとすると、この気流の動圧(速度圧)の値として、最も適当なものは次のうちどれか。ただし、ダクト内の空気の密度は1.2kg/m³とする。","o":["2.4Pa","9.6Pa","19.2Pa","38.4Pa","76.8Pa"],"a":1,"e":"動圧＝1/2×密度×速度²＝0.5×1.2×4.0²＝9.6Pa。","l":"計算","c":""},{"id":"2018-52","s":2,"q":"流体力学に関する次の記述のうち、最も不適当なものはどれか。","o":["無秩序な乱れによる流体塊の混合を伴う流れを乱流という。","直線ダクトの圧力損失は、ダクト長さの2乗に比例する。","摩擦のない理想流体では、ベルヌーイの定理が成立する。","慣性力の粘性力に対する比を表す無次元数がレイノルズ数である。","ダクトの形状変化に伴う圧力損失は、形状抵抗係数と風速の2乗に比例する。"],"a":1,"e":"直線ダクトの圧力損失はダクトの長さに比例し、風速の2乗に比例する。長さの2乗に比例するのではない。","l":"法令外","c":""},{"id":"2018-53","s":2,"q":"室内気流に関する次の記述のうち、最も不適当なものはどれか。","o":["自由噴流では、吹出口から離れた中心軸速度が、距離に反比例して減衰する領域がある。","吸込気流の吸込み速度は、吸込み中心からの距離の2乗におおむね反比例する。","天井面に沿った噴流の到達距離は、自由噴流の場合より短くなる。","ドラフトは、不快な局部気流のことをいい、気流の速度、気流変動の大きさ、空気温度の影響を受ける。","低温空気は室の底部に滞留する傾向があり、その傾向を利用した換気方式に置換換気がある。"],"a":2,"e":"天井に沿って吹き出した噴流は天井面に引き寄せられて広がりにくく、自由噴流より遠くまで届く(到達距離は長くなる)。","l":"法令外","c":""},{"id":"2018-54","s":2,"q":"室内における空気汚染物質に関する次の記述のうち、最も不適当なものはどれか。","o":["一酸化炭素の発生源は、燃焼器具、たばこ等である。","二酸化炭素の室内の発生源は、ヒトの活動(呼吸)などであり、換気の指標とされている。","ホルムアルデヒドの室内の発生源は、コピー機、レーザプリンタ等である。","浮遊粉じんの発生源は、たばこ、ヒトの活動、外気等である。","二酸化炭素の濃度が経時的に高くなる場合には、居室の過密使用などが考えられる。"],"a":2,"e":"コピー機やレーザープリンタから出るのはオゾン。ホルムアルデヒドの主な発生源は、建材・家具の接着剤や喫煙などである。","l":"法令外","c":""},{"id":"2018-55","s":2,"q":"空気清浄化と換気に関する次の記述のうち、最も不適当なものはどれか。","o":["空気交換効率は、室全体の換気効率を表すものである。","電気集じん機は、ガス状物質の除去に利用できる。","必要換気量は、人体への影響、燃焼器具への影響、熱・水蒸気発生の影響等から決定される。","単位時間当たりに室内に取り入れる新鮮空気(外気)量を室容積で除したものを換気回数という。","室内空気の清浄化にとって、換気は重要な役割を果たす。"],"a":1,"e":"電気集じん機は、粉じんに電気を帯びさせて集める装置で、粒子状物質の除去に使う。ガス状物質は除去できない。","l":"法令外","c":""},{"id":"2018-56","s":2,"q":"微生物とアレルゲンに関する次の記述のうち、最も不適当なものはどれか。","o":["ウイルスは、結露水中で増殖しやすい。","真菌は、環境微生物として捉えられる。","空気調和機内は、微生物の増殖にとって好環境となる。","アルテルナリアは、カビアレルゲンとして挙げられる。","ヒョウヒダニの糞と死骸は、アレルゲンになる。"],"a":0,"e":"ウイルスは生きた細胞の中でしか増えない。結露水の中で増えるのはカビや細菌である。","l":"法令外","c":""},{"id":"2018-57","s":2,"q":"図は空気線図上に状態点Aから湿球温度、比エンタルピー、比容積が同じとなる方向を矢印で示している。それぞれの矢印が示す要素として、正しい組合せは次のうちどれか。","o":["ア:湿球温度、イ:比エンタルピー、ウ:比容積","ア:湿球温度、イ:比容積、ウ:比エンタルピー","ア:比エンタルピー、イ:湿球温度、ウ:比容積","ア:比エンタルピー、イ:比容積、ウ:湿球温度","ア:比容積、イ:湿球温度、ウ:比エンタルピー"],"a":2,"e":"空気線図では、比エンタルピー一定の線と湿球温度一定の線はどちらも左上がりに近い向きで、湿球温度の線の方がやや急になる。比容積一定の線は、それよりずっと立った急な線になる。よってア＝比エンタルピー、イ＝湿球温度、ウ＝比容積。","l":"法令外","c":"","g":["img/2018-57.png"]},{"id":"2018-58","s":2,"q":"次の熱負荷のうち、一般に暖房時に無視するものはどれか。","o":["外壁からの構造体負荷","ガラス面の熱通過負荷","送風機による負荷","隙間風負荷","配管による負荷"],"a":2,"e":"送風機が出す熱は室内を暖める方向に働くので、暖房時には安全側として無視する。冷房時には負荷として計算に入れる。","l":"法令外","c":""},{"id":"2018-59","s":2,"q":"空気調和に関する用語として、最も不適当なものは次のうちどれか。","o":["顕熱比","熱水分比","ブリージング","コンタクトファクタ","混合損失"],"a":2,"e":"ブリージングは、打ち込んだコンクリートの表面に水が浮き出てくる現象で、空気調和の用語ではない。","l":"法令外","c":""},{"id":"2018-60","s":2,"q":"湿り空気の状態変化に関する次の記述のうち、最も不適当なものはどれか。","o":["単純加熱操作では、露点温度は変化しない。","単純冷却操作では、相対湿度は上昇する。","冷却除湿操作では、絶対湿度は低下する。","液体吸収除湿操作では、乾球温度は低下する。","水噴霧加湿操作では、露点温度は上昇する。"],"a":3,"e":"液体吸収剤で水蒸気を吸収させると、吸収のときに熱が出るので、空気の乾球温度は上がる。「低下する」は誤り。","l":"法令外","c":""},{"id":"2018-61","s":2,"q":"空気調和方式と設備の構成要素に関する次の組合せのうち、最も不適当なものはどれか。","o":["定風量単一ダクト方式 ― 還気ダクト","分散設置水熱源ヒートポンプ方式 ― 冷却塔","変風量単一ダクト方式 ― 混合ユニット","放射冷暖房方式 ― 放射パネル","ダクト併用ファンコイルユニット方式 ― 冷温水配管"],"a":2,"e":"混合ユニットは、冷風と温風の2本のダクトの空気を混ぜて送る二重ダクト方式の機器である。変風量単一ダクト方式で使うのは変風量(VAV)ユニット。","l":"法令外","c":""},{"id":"2018-62","s":2,"q":"空気調和設備の熱源方式に関連する次の記述のうち、最も不適当なものはどれか。","o":["電動機駆動ヒートポンプ方式は、電動冷凍機とボイラを組合せる方式に比べ夏期と冬期における電力使用量の変化が小さい。","空調用蓄熱システムは、熱源装置容量の削減や夏期冷房期における電力のピークカットに寄与する。","空調用熱源として、地球温暖化防止のため太陽熱や地中熱などの自然エネルギーが注目されている。","不特定多数の需要家に熱供給する熱源プラントは、規模の大小にかかわらず熱供給事業法の適用を受ける。","蒸気ボイラと吸収冷凍機を組合せる方式は、病院・ホテルでの採用例が多い。"],"a":3,"e":"熱供給事業法の対象は、加熱能力の合計が1時間あたり21GJ以上の規模の熱供給に限られる(施行令第2条)。規模の大小にかかわらず適用されるのではない。","l":"熱供給事業法 第2条、同法施行令 第2条","c":""},{"id":"2018-63","s":2,"q":"下の図は、蒸気圧縮冷凍機のサイクルと対応するモリエル線図を描いたものである。図中のア〜エに入る語句の組合せとして正しいものは、次のうちどれか。","o":["ア:蒸発器、イ:圧縮機、ウ:凝縮器、エ:膨張弁","ア:蒸発器、イ:膨張弁、ウ:凝縮器、エ:圧縮機","ア:凝縮器、イ:圧縮機、ウ:蒸発器、エ:膨張弁","ア:凝縮器、イ:膨張弁、ウ:蒸発器、エ:圧縮機","ア:蒸発器、イ:圧縮機、ウ:膨張弁、エ:凝縮器"],"a":0,"e":"①→②で圧力が上がるのが圧縮機(イ)、②→③で冷媒が液化するのが凝縮器(ウ)、③→④で圧力が下がるのが膨張弁(エ)、④→①で冷媒がガス化するのが蒸発器(ア)。","l":"法令外","c":"","g":["img/2018-63.png"]},{"id":"2018-64","s":2,"q":"同じ冷凍能力の蒸気圧縮冷凍機と比較した場合の吸収冷凍機の利点に関する次の記述のうち、最も不適当なものはどれか。","o":["冷凍機本体及び冷却塔容量ともに小さくなる。","回転部分が少なく、騒音・振動が小さい。","消費電力量が少ない。","冷凍機内は真空であり、圧力による破裂などのおそれがない。","特別な運転資格を必要としない。"],"a":0,"e":"吸収冷凍機は熱で動かすため、捨てる熱が多く、冷却塔は蒸気圧縮冷凍機より大きくなる。本体も大きめになる。","l":"法令外","c":""},{"id":"2018-65","s":2,"q":"冷凍機の冷媒に関する次の記述のうち、最も不適当なものはどれか。","o":["オゾン破壊係数( ODP )は、大気中に放出されるガスのオゾン層破壊に関与する影響度を表す指標である。","HCFC系冷媒は、代替フロンと呼ばれオゾン破壊係数( ODP )が 0 である。","CFC系冷媒は、オゾン層破壊問題から全面的に製造中止とされた。","地球温暖化係数( GWP )は、大気中に放出されるガスの地球温暖化に関与する影響度を表す指標である。","自然冷媒の二酸化炭素は、環境負荷の点でフロン系冷媒より優れている。"],"a":1,"e":"HCFC系冷媒は塩素を含むので、量は少ないもののオゾン層を壊す(ODPは0ではない)。ODPが0なのはHFC系や自然冷媒である。","l":"法令外","c":""},{"id":"2018-66","s":2,"q":"一般空調用吸収冷凍機に関する次の記述のうち、最も不適当なものはどれか。","o":["蒸発器では、冷水が取り出される。","凝縮器では、冷媒が液化する。","再生器では、吸収液が濃縮される。","加熱エネルギーを複数段の再生器で利用するものがある。","吸収器では、冷媒を散布する。"],"a":4,"e":"吸収器では、濃い吸収液を散布して、蒸発器で出た冷媒の蒸気を吸収させる。冷媒を散布するのは蒸発器である。","l":"法令外","c":""},{"id":"2018-67","s":2,"q":"加湿装置の基本構造と加湿方式の関係に関する次の組合せのうち、最も不適当なものはどれか。","o":["滴下式 ― 水噴霧方式","赤外線式 ― 蒸気吹出方式","超音波式 ― 水噴霧方式","電極式 ― 蒸気吹出方式","透湿膜式 ― 気化方式"],"a":0,"e":"滴下式は、水を上からしたたらせて加湿材をぬらし、そこに風を通して蒸発させる気化方式である。","l":"法令外","c":""},{"id":"2018-68","s":2,"q":"冷却塔に関する次の記述のうち、最も不適当なものはどれか。","o":["開放式冷却塔は、密閉式冷却塔よりも一般に大型である。","空調用途における冷却塔は、主として冷凍機の凝縮熱を大気に放出するためにある。","密閉式冷却塔は、冷却水の汚染は少なく、冷凍機の性能低下が少ない。","開放式冷却塔では冷却水の水質管理、密閉式冷却塔では散布水の水質管理が重要である。","密閉式冷却塔は、開放式冷却塔に比べて一般に送風機動力が大きい。"],"a":0,"e":"密閉式冷却塔は、冷却水を管の中に通し、その外側に散布水をかける構造のため、開放式より大型になる。","l":"法令外","c":""},{"id":"2018-69","s":2,"q":"空気調和設備に用いられる熱交換器に関する次の記述のうち、最も不適当なものはどれか。","o":["代表的な空気冷却用熱交換器としては、プレートフィン式冷却コイルがある。","空気 − 空気熱交換器は、主に排気熱の回収に用いられる。","静止型全熱交換器は、仕切り板の伝熱性と透湿性により給排気間の全熱交換を行う。","ヒートパイプは、構造・原理が単純で、熱輸送能力の高い全熱交換器である。","プレート式水 − 水熱交換器は、コンパクトで容易に分解洗浄できるという特徴がある。"],"a":3,"e":"ヒートパイプは、中の作動液の蒸発・凝縮で熱を運ぶ顕熱交換器で、湿気(潜熱)は交換しない。全熱交換器ではない。","l":"法令外","c":""},{"id":"2018-70","s":2,"q":"空気調和設備の吹出口に関する次の記述のうち、最も不適当なものはどれか。","o":["ノズル型は、軸流吹出口に分類される。","パン型は、ふく流吹出口に分類される。","天井パネル型は、面状吹出口に分類される。","アネモ型は、ふく流吹出口に分類される。","グリル型は、面状吹出口に分類される。"],"a":4,"e":"グリル型は、軸方向にまっすぐ吹き出す軸流吹出口に分類される。面状吹出口は天井パネル型など。","l":"法令外","c":""},{"id":"2018-71","s":2,"q":"ダクトとその付属品に関する次の記述のうち、最も不適当なものはどれか。","o":["グラスウールダクトは、消音効果がある。","低圧ダクトとは、常用圧力が −490 〜 ＋ 490Paの範囲で用いられるダクトをさす。","亜鉛鉄板ダクトでは、一般に板厚が 0.5〜1.2mmのものが用いられている。","ダクトと吹出口を接続する際に、位置調整が必要となる場合、フレキシブル継手が用いられる。","防火ダンパの温度ヒューズの溶解温度は、一般換気用で120°Cである。"],"a":4,"e":"防火ダンパの温度ヒューズの溶ける温度は、一般換気用で72℃程度、厨房排気用で120℃、排煙用で280℃が目安である。","l":"法令外","c":""},{"id":"2018-72","s":2,"q":"下の図は、送風機の運転と送風量の関係を示している。この図に関連して、次の文章の(　　　)内に入る語句の組合せとして、最も適当なものはどれか。\n\n送風機の( ア )は、グラフの横軸に風量をとり、縦軸に( イ )をとって曲線Pのように示される。一方、送風系の抵抗曲線は、同じグラフ上に、原点を通る二次曲線Rとして示される。ここで、2曲線の交点Aは、運転点を示している。その送風量をQAからQBに減少したい場合には、送風系の( ウ )を操作することで調整できる。","o":["ア:特性曲線、イ:静圧、ウ:インバータ","ア:特性曲線、イ:動圧、ウ:ダンパ","ア:動圧曲線、イ:動圧、ウ:インバータ","ア:特性曲線、イ:静圧、ウ:ダンパ","ア:動圧曲線、イ:静圧、ウ:ダンパ"],"a":3,"e":"風量と静圧の関係を表した曲線Pが送風機の特性曲線。ダンパを絞ると抵抗曲線がRからR'に変わり、運転点がAからBに移って風量がQBに減る。インバータは特性曲線Pの方を変える方法である。","l":"法令外","c":"","g":["img/2018-72.png"]},{"id":"2018-73","s":2,"q":"空気調和設備に用いられる配管の種類とそれに使用する温度又は圧力との組合せとして、最も不適当なものは次のうちどれか。","o":["氷蓄熱用不凍液配管 ― −10〜−5°C","冷水配管 ― 5〜10°C","冷却水配管 ― 20〜40°C","高温水配管 ― 120〜180°C","低圧蒸気配管 ― 0.1〜1MPa"],"a":4,"e":"低圧蒸気配管は0.1MPa未満(おおむね0.01〜0.05MPa)で使われる。0.1〜1MPaは高圧蒸気配管の範囲である。","l":"法令外","c":""},{"id":"2018-74","s":2,"q":"室用途別の1人当たりの専有面積と必要換気量に関する次の組合せのうち、最も不適当なものはどれか。(数値の順は、1人当たりの専有面積[m²/人] ― 必要換気量[m³/(h・m²)])","o":["食堂(営業用) ― 1.0 ― 30.0","ホテル客室 ― 10.0 ― 3.0","宴会場 ― 0.8 ― 37.5","事務所(一般) ― 4.2 ― 4.5","デパート(一般売場) ― 1.5 ― 20.0"],"a":3,"e":"専有面積×必要換気量で1人あたりの換気量が出る。どれも30m³/(h・人)になるが、事務所は4.2×4.5＝18.9で足りない。","l":"法令外","c":""},{"id":"2018-75","s":2,"q":"環境要素の測定に関する次の記述のうち、最も不適当なものはどれか。","o":["グローブ温度計は、室内気流速度が小さくなるにつれ、平均放射温度に近づく傾向にある。","ピトー管による風速測定では、ベルヌーイの式を用いて流速を算出する。","アスマン通風乾湿計の湿球温度は、一般に乾球温度より低い値を示す。","バイメタル式温度計は、2種類の金属の導電率の差を利用している。","超音波風速計は、超音波の到着時間と気流との関係を利用している。"],"a":3,"e":"バイメタル式温度計は、2種類の金属の「熱膨張率」の違いで曲がることを利用している。導電率ではない。","l":"法令外","c":""},{"id":"2018-76","s":2,"q":"室内環境の測定に関する次の記述のうち、最も不適当なものはどれか。","o":["微生物の測定には、ATP法がある。","アスベストの測定には、分析透過電子顕微鏡法がある。","臭気の測定には、官能試験法がある。","花粉アレルゲンの測定には、表面プラズモン共鳴法がある。","オゾンの測定には、赤外線吸収法がある。"],"a":4,"e":"オゾンの測定には紫外線吸収法などが使われる。赤外線吸収法は二酸化炭素などの測定法である。","l":"法令外","c":""},{"id":"2018-77","s":2,"q":"浮遊粉じんの測定に関する次の文章の「　　　」内の語句のうち、最も不適当なものはどれか。\n\n建築物衛生法の測定対象となる浮遊粉じん濃度は、粉じんの「化学的組成」を考慮することなく「幾何相当径」がおおむね「10μm以下の粒子状物質」を対象として、「0.15mg/m³」以下と規定されている。標準となる測定法は「重量法(質量濃度測定法)」である。","o":["化学的組成","幾何相当径","10μm以下の粒子状物質","0.15mg/m³","重量法(質量濃度測定法)"],"a":1,"e":"建築物衛生法では、相対沈降径がおおむね10μm以下の浮遊粉じんを測定対象としている(施行規則第3条の2)。幾何相当径ではない。","l":"建築物衛生法施行令 第2条、同法施行規則 第3条の2","c":""},{"id":"2018-78","s":2,"q":"環境要素とその測定法との組合せとして、最も不適当なものは次のうちどれか。","o":["オゾン ― 検知管法","酸素 ― ポーラログラフ方式","硫黄酸化物 ― 溶液導電率法","二酸化炭素 ― 非分散型紫外線吸収法","一酸化炭素 ― 定電位電解法"],"a":3,"e":"二酸化炭素は、非分散型「赤外線」吸収法で測定する。紫外線吸収法はオゾンなどの測定法である。","l":"法令外","c":""},{"id":"2018-79","s":2,"q":"空気汚染物質とその濃度又は強さを表す単位との組合せとして、最も不適当なものは次のうちどれか。","o":["アセトアルデヒド ― μg/m³","真菌 ― CFU/m³","アスベスト ― 本/L","ダニアレルゲン ― Bq","浮遊粉じん ― mg/m³"],"a":3,"e":"Bq(ベクレル)は放射能の強さの単位。ダニアレルゲンの濃度はng/m³などで表す。","l":"法令外","c":""},{"id":"2018-80","s":2,"q":"建築物衛生法に基づくホルムアルデヒド測定法に関する次の記述のうち、最も不適当なものはどれか。","o":["分析機器を用いて正確に測定値が得られる精密測定法と、現場で簡便に測定値が得られる簡易測定法がある。","DNPH − HPLC法(DNPHカートリッジ捕集 − 高速液体クロマトグラフ法)に用いるDNPHカートリッジは、冷蔵保管が必要である。","DNPH − HPLC法によるパッシブ法の試料は、電動ポンプを用いて採取する。","検知管法においては、サンプリングに電動ポンプを使用する。","簡易測定法は、妨害ガスの影響を受けることがある。"],"a":2,"e":"パッシブ法は、ポンプを使わず、物質が自然に広がって(拡散して)捕集剤に集まるのを利用する方法である。電動ポンプを使うのはアクティブ法。","l":"法令外","c":""},{"id":"2018-81","s":2,"q":"空気調和・換気設備の維持管理に関する次の記述のうち、最も不適当なものはどれか。","o":["物理的劣化とは、機器の持つ機能と時代とともに高度化していく要求機能との乖離が次第に大きくなることをいう。","点検、整備、検査、修理を行う業務は保全業務に位置づけられる。","予防保全は、部品の劣化を保全計画に組み入れて計画的に修理、交換する方法である。","維持管理の目的として、故障、事故の発生の予知、危険・災害の未然防止がある。","平均故障間隔( MTBF )とは、システム、機器、部品等で発生する故障間の動作時間の平均値をいう。"],"a":0,"e":"物理的劣化は、使い続けたり年数がたったりして機能が落ちること。時代とともに求められる機能との差が広がることは社会的劣化という。","l":"法令外","c":""},{"id":"2018-82","s":2,"q":"冷却塔と冷却水の維持管理に関する次の記述のうち、最も不適当なものはどれか。","o":["冷却塔に供給する水は、水道法第4条に規定する水質基準に適合していることが求められる。","スケール防止剤、レジオネラ属菌の殺菌剤等を含有するパック剤は、冷却水中に薬剤が徐々に溶け出す加工がされていて、効果は約1年間持続する。","冷却塔及び冷却水は、使用開始時及び使用期間中の1ヵ月以内ごとに1回、定期に、汚れの状況を点検する。","連続ブローなどの冷却水濃縮管理は、スケール防止に有効である。","開放型冷却塔では、一般に循環水量の2%程度の補給水量を見込んでおく必要がある。"],"a":1,"e":"パック剤(薬剤が徐々に溶け出すもの)の効果が続くのは1〜3か月程度で、約1年ではない。","l":"法令外","c":""},{"id":"2018-83","s":2,"q":"音に関する次の記述のうち、最も不適当なものはどれか。","o":["音速は、波長を周波数で除して求められる。","A特性音圧レベルとは、人間の聴覚の周波数特性を考慮した騒音の大きさを表す尺度である。","音に対する人間の感覚量は、音の強さの対数で表される。","純音の瞬時音圧は、単一の正弦関数で表される。","面音源であっても、音源から十分離れた場所では、点音源に対する減衰特性を示す。"],"a":0,"e":"音速＝波長×周波数で求める。波長を周波数で割るのではない。","l":"法令外","c":""},{"id":"2018-84","s":2,"q":"騒音と振動に関する次の記述のうち、最も不適当なものはどれか。","o":["道路交通振動に対する振動規制は、昼間より夜間の方が厳しい。","点音源の場合、音源までの距離が10倍になると、音圧レベルは約20dB減衰する。","防振溝は、回折減衰効果を利用した振動対策の方法である。","対象騒音が暗騒音より10dB以上大きい場合は、測定音を対象騒音と判断して良い。","不規則かつ大幅に変動する振動に対する振動規制法による規制基準は、最大の振動加速度レベルによって定められている。"],"a":4,"e":"不規則で大きく変わる振動は、測った値の80%レンジの上端の値(振動レベル)で評価する。最大の振動加速度レベルではない。","l":"振動規制法施行規則 第12条・別表第2","c":""},{"id":"2018-85","s":2,"q":"音圧レベル70dBの音源室と面積10m²の隔壁で仕切られた等価吸音面積(吸音力)20m²の受音室の平均音圧レベルを40dBにしたい。このとき、隔壁の音響透過損失として確保すべき値に最も近いものは次のうちどれか。なお、音源室と受音室の音圧レベルには以下の関係がある。\nL1 − L2 = TL + 10log10(A2/Sw)\nただし、L1、L2は音源室、受音室の平均音圧レベル[dB]、A2は受音室の等価吸音面積[m²]、Swは音の透過する隔壁の面積[m²]、TLは隔壁の音響透過損失[dB]である。ただし、log10 2 = 0.3010、log10 3 = 0.4771とする。","o":["24dB","27dB","30dB","33dB","43dB"],"a":1,"e":"70－40＝TL＋10log10(20/10)なので、30＝TL＋10×0.3010。TL＝30－3.01≒27dB。","l":"計算","c":""},{"id":"2018-86","s":2,"q":"振動と遮音に関する次の記述のうち、最も不適当なものはどれか。","o":["固体伝搬音問題には振動が関与する。","対象振動が正弦波の場合、振動加速度の実効値は、最大振幅の1/√2で求められる。","コインシデンス効果が生じると、壁体の透過損失は増加する。","床仕上げ材は、柔らかくなるほど、軽量床衝撃音の減衰性能が向上する。","建物内で感じる道路交通による振動は、不規則で変動も大きい。"],"a":2,"e":"コインシデンス効果が起きると、壁が音と一緒に振動して音を通しやすくなり、透過損失は「減少」する。","l":"法令外","c":""},{"id":"2018-87","s":2,"q":"光・照明に関する次の記述のうち、最も不適当なものはどれか。","o":["光が当たった物体の境界面が平滑な場合、光は正反射して光沢となる。","建築化照明とは、照明器具を建築物の一部として天井、壁等に組み込んだ照明方式である。","間接昼光率は、室内反射率の影響を受ける。","天窓は、同じ面積の側窓より多くの光が得られる。","色温度が高くなると、光色は青→白→黄→赤と変わる。"],"a":4,"e":"色温度が高くなると、光の色は赤→黄→白→青と変わる。順番が逆である。","l":"法令外","c":""},{"id":"2018-88","s":2,"q":"各種光源の相対分光分布を下の図中に示している。最も適当な組合せは次のうちどれか。","o":["A:白熱電球、B:照明用LED、C:北の青空光","A:白熱電球、B:北の青空光、C:照明用LED","A:北の青空光、B:照明用LED、C:白熱電球","A:北の青空光、B:白熱電球、C:照明用LED","A:照明用LED、B:白熱電球、C:北の青空光"],"a":2,"e":"Aは短い波長(青)が強いので北の青空光、Bは青の鋭い山と黄色付近の山がある照明用LED、Cは長い波長(赤)ほど強くなる白熱電球。","l":"法令外","c":"","g":["img/2018-88.png"]},{"id":"2018-89","s":2,"q":"点光源直下2.0mの水平面照度が300 lxである場合、点光源直下3.0mの水平面照度として、最も近いものは次のうちどれか。","o":["100 lx","130 lx","200 lx","450 lx","670 lx"],"a":1,"e":"照度は距離の2乗に反比例する。300×(2.0÷3.0)²＝300×4/9≒133lxなので、最も近いのは130lx。","l":"計算","c":""},{"id":"2018-90","s":2,"q":"光環境の保守に関する次の記述のうち、最も不適当なものはどれか。","o":["保守率は、照明施設をある期間使用した後の作業面上の平均照度と初期平均照度との比で表される。","周辺環境の清浄度が同じ場合、下面開放形の照明器具よりも、完全密閉形の照明器具の方が設計光束維持率が低い。","蛍光ランプは、白熱電球やHIDランプ(高輝度放電ランプ)と比べ、周辺温度による光束変動が大きい。","水銀ランプやメタルハライドランプの光束は、白熱電球や蛍光ランプ、高圧ナトリウムランプよりも点灯姿勢による影響を受けやすい。","照明器具の清掃間隔は、汚れによる照度低下によって損失する照明費をちょうど1回分の清掃費で相殺できる期間が、最も経済的な清掃間隔である。"],"a":1,"e":"完全密閉形の器具は中に汚れが入りにくいので、下面開放形より設計光束維持率は「高い」。","l":"法令外","c":""},{"id":"2018-91","s":3,"q":"都市と建築の熱環境について、最も不適当なものはどれか。","o":["室温は、屋外の気温やその他の気候要素の影響を受けて時々刻々と変化する。","アルベドとは、任意の面に入射した日射量に対し、その面での反射した日射量の割合をいう。","温室効果とは、太陽光線が大気中の二酸化炭素などに吸収され、大気が温まることで地球上の気温が上昇することをいう。","熱容量の相異なる材料に、同一熱量をそれぞれ与えた場合、同じ容積なら熱容量の大きい方が温まりにくい。","水が蒸発すると、その蒸発面は気化熱が奪われ冷える。"],"a":2,"e":"温室効果は、太陽で温まった地面から出る赤外線(熱)を二酸化炭素などが吸収し、地表に戻すことで気温が上がる現象である。太陽光線を直接吸収して温まるのではない。","l":"法令外","c":""},{"id":"2018-92","s":3,"q":"東京で、建築物の晴天日の日射・日照について、最も不適当なものはどれか。","o":["夏至の日の日積算日射量は、南向き鉛直壁面よりも東・西向き鉛直壁面の方が多い。","冬至の日の日積算日射量は、南向き壁面よりも水平面の方が多い。","南向き鉛直壁面が受ける日積算日射量は、夏至の日よりも冬至の日の方が多い。","夏至の日の可照時間は、一年を通して最も長い。","夏至の日の正午における方位別日射受熱量は、水平面が他の鉛直壁面に比べて最も多い。"],"a":1,"e":"冬至は太陽の高さが低いので、日射は水平面より南向きの壁に多く当たる。そのため冬至の日積算日射量は、水平面より南向き壁面の方が多い。","l":"法令外","c":""},{"id":"2018-93","s":3,"q":"建築物の意匠設計図面と空気調和設備設計図面の平面記号について、最も不適当なものはどれか。下の図の記号は、上から順に(1)〜(5)の選択肢に対応している。","o":["引違い戸は、図の(1)の記号で表示される。","出入口一般は、図の(2)の記号で表示される。","アネモ型吹出口は、図の(3)の記号(円の四方に矢印)で表示される。","空調還気ダクトは、図の(4)の記号(―RA―)で表示される。","空調機は、図の(5)の記号(四角にAC)で表示される。"],"a":0,"e":"(1)の記号は、壁の線の中に2枚の建具を描いた「引違い窓」の記号であり、引違い戸の記号ではない。RAは還気(リターンエア)、ACは空調機(エアコンディショナー)を表す。","l":"法令外","c":"","g":["img/2018-93.png"]},{"id":"2018-94","s":3,"q":"建築物の構造について、最も不適当なものはどれか。","o":["折板構造の応力は、主として面内力である。","トラス構造の部材に生じる応力は、曲げモーメントとせん断力である。","壁式構造の組積式には、れんが造、補強コンクリートブロック造がある。","空気膜構造は、膜面に張力を与えている。","制振構造は、建物の揺れを制御し、低減しようとする構造である。"],"a":1,"e":"トラス構造は部材を三角形に組み、接合部をピンとみなすので、部材には軸方向力(引張りか圧縮)だけが生じる。","l":"法令外","c":""},{"id":"2018-95","s":3,"q":"鉄筋コンクリート構造とその材料について、最も不適当なものはどれか。","o":["柱の主筋は、4本以上とする。","直接土に接する壁において、鉄筋に対するコンクリートのかぶり厚さは、4cm以上としなければならない。","一般の壁の厚さは、10〜15cm程度である。","梁せいは、梁断面の下面から上面までの高さをいう。","柱の帯筋は、曲げモーメントに抵抗する。"],"a":4,"e":"柱の帯筋(フープ)は、せん断力に抵抗し、主筋が外へはらみ出すのを防ぐ。曲げモーメントに抵抗するのは主筋である。","l":"建築基準法施行令 第77条、第79条","c":""},{"id":"2018-96","s":3,"q":"建築物の荷重と構造力学について、最も不適当なものはどれか。","o":["床の構造計算をする場合、事務室の積載荷重は、住宅の居室の積載荷重より小さく設定されている。","積雪荷重は、作用時間により常時荷重(長期)と非常時荷重(短期)に分類される。","曲げモーメント荷重は、部材のある点を湾曲させようとする荷重をいう。","単純支持形式において、部材の一端は回転端、もう一端は移動端で支持されている。","トラス構造の部材の接点は、ピン接点として取り扱われる。"],"a":0,"e":"床の構造計算用の積載荷重は、住宅の居室が1,800N/m²、事務室が2,900N/m²で、事務室の方が大きい。","l":"建築基準法施行令 第85条","c":""},{"id":"2018-97","s":3,"q":"建築材料と部材の性質について、最も不適当なものはどれか。","o":["コンクリートは、硬化時に収縮亀裂が生じやすい。","セメントペーストは、水とセメントを練り混ぜたものである。","鋼材は、アルミニウム材料より熱を伝えやすい。","床の仕上げ材には、耐摩耗性、防水性、防音性、踏み心地の良さ等が要求される。","コンクリートの水セメント比は、一般に40〜65%程度である。"],"a":2,"e":"熱の伝えやすさ(熱伝導率)は、アルミニウムの方が鋼材より約4倍大きい。鋼材の方が熱を伝えにくい。","l":"法令外","c":""},{"id":"2018-98","s":3,"q":"建築材料と部材の性質について、最も不適当なものはどれか。","o":["鉄鋼の線膨張係数は、コンクリートとほぼ等しい。","木材は、菌類発生に必要な養分、湿気、空気及び温度の4要素があると腐朽する。","下地材料は、構造躯体と仕上げの中間に用いられる。","カーテンウォールは、建築物の耐力壁として使用される。","レイタンスは、打設したコンクリートの硬化時に、石灰岩や骨材の微粒粉が表面に層状になったものである。"],"a":3,"e":"カーテンウォールは、建物の荷重を負担しない外壁(非耐力壁)である。耐力壁としては使われない。","l":"法令外","c":""},{"id":"2018-99","s":3,"q":"建築生産について、最も不適当なものはどれか。","o":["一般競争入札は、工事内容、入札条件等を公示して行われる。","建築工事の工程は、仮設、地業、躯体、仕上げの各工事に大別される。","建築工事において下請負業者の多くは、職別業者又は設備業者である。","建築生産は、注文生産、一品生産、現場生産の多いことが特徴である。","工事監理は、施工者が建築主の委託を受けて代行することが多い。"],"a":4,"e":"工事監理は、工事が設計図書どおりに行われているかを確かめる仕事で、一般に設計者(建築士)が建築主から委託されて行う。施工者が自分の工事を監理するのではない。","l":"法令外","c":""},{"id":"2018-100","s":3,"q":"建築物の電気設備について、最も不適当なものはどれか。","o":["実効値100Vの交流電圧は、ピーク時の電圧が約140Vである。","受変電設備の容量は、建築物内部の電気設備の負荷合計に利用率を乗じて求める。","電線の配電距離が長くなると、電圧の低下を招くことがある。","磁束密度は、電流の強さとコイルの巻き数との積に比例する。","電気事業法に規定される電圧種別のうち特別高圧に区分されるのは、交流にあっては600Vを超えるものである。"],"a":4,"e":"特別高圧は7,000Vを超えるものである。交流で600Vを超え7,000V以下は高圧、600V以下は低圧に区分される。","l":"電気設備に関する技術基準を定める省令 第2条","c":""},{"id":"2018-101","s":3,"q":"建築設備について、最も不適当なものはどれか。","o":["LPガス容器は、一般に鋼板製のものが多い。","エスカレータの公称輸送能力は、定格速度と踏段幅により決定される。","受変電設備とは、電力会社から送電された電力を受電し、所定の電圧に下げて建物内で利用できるようにする設備である。","油圧式エレベータは汎用性が高く、中高層、超高層建築物に多用されている。","非常用エレベータの設置義務は、建築基準法により定められている。"],"a":3,"e":"油圧式エレベータは昇降できる高さが限られるので、主に低層の建物で使われる。中高層・超高層の建物ではロープ式が使われる。","l":"建築基準法 第34条第2項(選択肢5)","c":""},{"id":"2018-102","s":3,"q":"消防法施行令に定める消防の用に供する設備として、該当しないものはどれか。","o":["屋内消火栓設備","屋外消火栓設備","排煙設備","自動火災報知設備","誘導標識"],"a":2,"e":"消防の用に供する設備は、消火設備・警報設備・避難設備の3つである。排煙設備は「消火活動上必要な施設」に分類される。","l":"消防法施行令 第7条","c":""},{"id":"2018-103","s":3,"q":"地震について、最も不適当なものはどれか。","o":["気象庁震度階級は、地震の規模(大きさ)を表す表記である。","耐震診断は、建築物の耐震改修の促進に関する法律に定められている。","設備の耐震性能確保も、構造体と同様に重要である。","防災管理者は、当該建築物について地震の被害軽減のための自主検査を行う。","液状化現象は、埋立地や砂質地盤等で起こりやすい。"],"a":0,"e":"震度は、それぞれの場所での揺れの強さを表す。地震そのものの規模(エネルギーの大きさ)を表すのはマグニチュードである。","l":"法令外","c":""},{"id":"2018-104","s":3,"q":"建築基準法と建築士法について、誤っているものはどれか。","o":["仕様書は、設計図書に含まれる。","防火性能とは、建築物の周囲において発生する通常の火災による延焼を抑制するための外壁・軒裏に必要な性能である。","建築とは、建築物を新築し、増築し、改築し、又は移転することをいう。","一級建築士は、都道府県知事の免許を受けて得られる資格である。","特殊建築物には、安全、衛生、防災等に関して技術基準に基づく規制がかけられている。"],"a":3,"e":"一級建築士は、国土交通大臣の免許を受ける資格である。都道府県知事の免許を受けるのは二級建築士と木造建築士である。","l":"建築士法 第4条、建築基準法 第2条","c":""},{"id":"2018-105","s":3,"q":"建築基準法とその施行令について、誤っているものはどれか。","o":["病院の病室は、非常用の照明装置の設置が免除される。","屋外階段は、主要構造部に含まれる。","基礎は、構造耐力上主要な部分である。","排水の配管設備は、腐食防止の措置を講ずることが定められている。","避難階は、傾斜地などに建築されている場合には、複数生ずることがある。"],"a":1,"e":"主要構造部は、壁・柱・床・はり・屋根・階段だが、屋外階段は除かれる。基礎は主要構造部には入らないが、構造耐力上主要な部分には入る。","l":"建築基準法 第2条第5号、施行令 第1条第3号、第13条、第126条の4、第129条の2の4","c":""},{"id":"2018-106","s":4,"q":"給水及び排水の管理に関する用語とその単位との組合せとして、最も不適当なものはどれか。","o":["揚水ポンプの揚程 ― m","水の比体積 ― m³/J","精密ろ過膜の有効径 ― μm","塩化物イオン ― mg/L","BOD容積負荷 ― kg/(m³・日)"],"a":1,"e":"比体積は1kgあたりの体積なので、単位は m³/kg になる。J(ジュール)はエネルギーの単位で関係がない。","l":"法令外","c":""},{"id":"2018-107","s":4,"q":"給水及び排水の管理に関する用語の組合せとして、最も不適当なものはどれか。","o":["スカム ― 排水槽で槽の表面に浮上した固形物が集まったもの","スライム障害 ― バイオフィルムの形成","生物膜法 ― 微生物が主要な構成要素となっている膜を利用して汚水を処理する方法","着色障害 ― 給水配管材料の腐食などによる生成物が水に含まれ生じる現象","トリハロメタン ― 無機物質と消毒用塩素が反応して生成される物質"],"a":4,"e":"トリハロメタンは、水中のフミン質などの「有機物」と消毒用の塩素が反応してできる物質である。","l":"法令外","c":""},{"id":"2018-108","s":4,"q":"塩素消毒の効果に関する次の記述のうち、最も不適当なものはどれか。","o":["温度の影響を強く受け、温度が高くなるほど消毒速度は速くなる。","微生物表面の荷電状態は、消毒剤の細胞内への透過性に影響する。","懸濁物質が存在すると、その種類、大きさ、濃度等によって、消毒効果が低下する。","塩素消毒の効果を上げるためには、攪拌が重要である。","微生物を不活化するための消毒剤の濃度と接触時間の関係は比例する。"],"a":4,"e":"濃度を高くすれば短い時間で、濃度が低ければ長い時間で不活化できるので、濃度と接触時間は「反比例」の関係にある。","l":"法令外","c":""},{"id":"2018-109","s":4,"q":"取水施設に関する次の記述のうち、最も不適当なものはどれか。","o":["取水施設の位置の選定には、水量及び水質に対する配慮が必要である。","深層地下水は、地表からの汚染を受けにくく、水質が安定しているが、管の腐食を生ずることがある。","水源となる伏流水は、地表水に比較して、水量及び水質の変化が激しい。","深井戸の揚水中に砂の混入が多いときは、混入しない程度に揚水量を減らす。","集水埋渠は、一般に多数の穴を開けた鉄筋コンクリート管を、伏流水が流れている場所に埋設したものである。"],"a":2,"e":"伏流水は川底や砂利の層を通ってくる水なので、地表水より水量・水質の変化は小さく、安定している。","l":"法令外","c":""},{"id":"2018-110","s":4,"q":"塩素消毒の特徴に関する次の記述のうち、最も不適当なものはどれか。","o":["塩素剤の残留の確認と濃度の定量が容易である。","窒素化合物と反応すると、消毒効果が減少する。","酸性側で消毒効果が急減する。","災害など緊急時の使用に適している。","刺激臭を有するため、異臭味が生じる。"],"a":2,"e":"塩素の消毒効果が急に落ちるのは「アルカリ性側」である。アルカリ性では消毒力の強い次亜塩素酸が、弱い次亜塩素酸イオンに変わるため。","l":"法令外","c":""},{"id":"2018-111","s":4,"q":"給水設備に関する次の記述のうち、最も不適当なものはどれか。","o":["受水槽の容量は、一般に1日最大使用水量の50%程度とする。","超高層集合住宅においてゾーニングする場合の圧力の上限値は、0.7MPaとする。","FRP製高置水槽は、槽内照度が100lx以上になると、光合成により藻類が増殖しやすい。","高置水槽へ送水する揚水ポンプの起動・停止は、高置水槽の水位で行う。","ポンプ直送方式で採用されるインバータ制御は、周波数を変えることで回転数を変化させている。"],"a":1,"e":"給水圧力が高すぎるとウォータハンマなどが起きるため、ゾーニングの上限は集合住宅・ホテルで0.3〜0.4MPa、事務所で0.4〜0.5MPa程度とされる。0.7MPaは高すぎる。","l":"法令外","c":""},{"id":"2018-112","s":4,"q":"給水設備に関する語句と数値との組合せとして、最も不適当なものはどれか。","o":["デパートにおける1日当たりの設計給水量 ― 15〜30L/m²","ホテル客室部における1日当たりの設計給水量 ― 350〜450L/床","事務所建築における1日当たりの設計給水量 ― 60〜100L/人","小便器洗浄弁の最低必要水圧 ― 30kPa","大便器洗浄弁の最低必要水圧 ― 70kPa"],"a":3,"e":"洗浄弁(フラッシュバルブ)は、大便器用も小便器用も最低70kPaの水圧が必要とされる。30kPaは一般の水栓の値である。","l":"法令外","c":""},{"id":"2018-113","s":4,"q":"給水設備に関する次の記述のうち、最も適当なものはどれか。","o":["建築物の揺れ、地盤の不等(不同)沈下、配管の振動等による変位の吸収のために、ショックアブソーバを配管に取り付ける。","木製貯水槽は、断熱性能が低いため、結露対策が必要である。","ポンプ直送方式は、一般に下向き配管が採用される。","飲料用貯水槽の流入管は、波立ち防止を考慮して水没させることが望ましい。","鋼管に形成された腐食電池回路のアノード部とは、電池回路の電極が水中に流出する部分である。"],"a":4,"e":"腐食電池では、金属が水中に溶け出すアノード(陽極)部で腐食が進む。ほかは、変位の吸収には可とう継手を使う、木製槽は断熱性が高い、ポンプ直送は上向き配管、流入管は逆流防止のため水没させない、が正しい。","l":"法令外","c":""},{"id":"2018-114","s":4,"q":"給水設備の機器・配管材料に関する次の記述のうち、最も適当なものはどれか。","o":["TIG溶接は、不活性ガスの雰囲気中で、タングステン電極と溶接母材の間にアークを発生させて溶接する方法である。","ボール弁は、ボール状の弁体を回転させ、管軸と通路とが一致したときが全閉であり、それと90°回転した状態が全開になる。","ステンレス鋼板製貯水槽は、液層部よりも気層部の方が腐食しにくい。","銅管は、銅イオンが水に浸出して白濁水を生じることがある。","架橋ポリエチレン管の接続方法は、一般に接着接合である。"],"a":0,"e":"TIG溶接の説明として正しい。ボール弁は通路が管軸と一致したときが全開、ステンレス槽は塩素がたまる気層部の方が腐食しやすい、銅イオンで出るのは青い水、架橋ポリエチレン管はメカニカル接合や電気融着接合である。","l":"法令外","c":""},{"id":"2018-115","s":4,"q":"ウォータハンマの発生場所・影響・防止方法等に関する次の記述のうち、最も不適当なものはどれか。","o":["瞬間的に開閉できる水栓・弁類を使用する場所で発生しやすい。","揚水ポンプの吸込管(サクション)側に衝撃吸収式逆止弁を設ける。","配管・機器の振動、騒音の発生、配管の破損の原因になる。","配管内の圧力が高い場所で発生しやすい。","配管は極力まっすぐに配管し、むやみに曲折させてはならない。"],"a":1,"e":"ポンプ停止時のウォータハンマを防ぐ衝撃吸収式逆止弁は、ポンプの「吐出側」に設ける。","l":"法令外","c":""},{"id":"2018-116","s":4,"q":"貯水槽清掃後の水質検査項目と基準との組合せとして、最も不適当なものはどれか。","o":["色度 ― 5度以下","濁度 ― 3度以下","臭気 ― 異常でないこと(消毒によるものを除く)","味 ― 異常でないこと(消毒によるものを除く)","残留塩素の含有率 ― 遊離残留塩素0.2mg/L以上"],"a":1,"e":"貯水槽清掃後の水質検査では、濁度は「2度以下」でなければならない。色度5度以下、遊離残留塩素0.2mg/L以上などはそのとおり。","l":"平成15年厚生労働省告示第119号 第2の一の1","c":""},{"id":"2018-117","s":4,"q":"建築物衛生法に基づく特定建築物の給水設備の保守管理に関する次の記述のうち、最も不適当なものはどれか。","o":["貯水槽清掃終了後の消毒には、有効塩素濃度10〜20mg/Lの次亜塩素酸ナトリウム溶液などの塩素剤を用いる。","防錆剤を使用する場合は、定常時においては2カ月以内ごとに1回、防錆剤の濃度を検査しなければならない。","残留塩素が不検出、又はその濃度変動が激しい場合には、一度吐水された水が、給水管へ逆流している可能性がある。","貯水槽は、点検を定期に行い、地震などで貯水槽の構造や水質に影響を与えるような事態が発生した場合には、速やかにその影響を点検する。","受水槽の水位制御の作動点検は、槽内のボールタップを手動で操作して行う。"],"a":0,"e":"貯水槽清掃後の消毒には、有効塩素濃度50〜100mg/Lの次亜塩素酸ナトリウム溶液などを使う。10〜20mg/Lでは薄すぎる。","l":"平成15年厚生労働省告示第119号 第2の一の1、建築物環境衛生維持管理要領","c":""},{"id":"2018-118","s":4,"q":"給湯設備に関する次の記述のうち、最も不適当なものはどれか。","o":["事務所の用途に使用する建築物において、給湯量の設計値は、30L/(人・日)程度である。","ガス瞬間湯沸器の能力で1号とは、流量1L/minを25℃上昇させる能力をいう。","中央式給湯設備の場合の給湯温度は、ピーク使用時においても55℃以上が望ましい。","ステンレス鋼管において単式の伸縮継手を用いる場合、設置間隔は20m程度である。","貯蔵式湯沸器は、90℃以上の高温湯が得られ、飲用として利用される。"],"a":0,"e":"事務所の給湯は手洗い・湯沸かし程度なので、設計給湯量は7〜10L/(人・日)程度と少ない。30Lは多すぎる。","l":"法令外","c":""},{"id":"2018-119","s":4,"q":"循環配管の管長が80m、循環配管からの単位長さ当たりの熱損失が50W/mの給湯設備で給湯循環流量を算出した場合、その値として最も近いものはどれか。ただし、次の算定式を用い、加熱装置における給湯温度と返湯温度の差を5℃とする。\nQ = 0.0143 × HL ÷ Δt\n(Q:循環流量[L/min]、HL:循環配管からの熱損失[W]、Δt:加熱装置における給湯温度と返湯温度との差[℃])","o":["0.14L/min","0.23L/min","11L/min","57L/min","286L/min"],"a":2,"e":"熱損失 HL = 80m × 50W/m = 4,000W。Q = 0.0143 × 4,000 ÷ 5 = 11.44 なので、約11L/minとなる。","l":"法令外","c":""},{"id":"2018-120","s":4,"q":"給湯設備の省エネルギーに関する次の記述のうち、最も不適当なものはどれか。","o":["給湯温度を適切に管理する。","適切な制御方式を採用する。","配管経路の短縮、配管の断熱等に配慮し、放熱損失を低減した適切な配管とする。","混合水栓の使用を避け、湯と水は別々の水栓とする。","器具ごとに定流量弁を設置する。"],"a":3,"e":"湯と水を別々の水栓にすると、ちょうどよい温度にするまでに湯を無駄に流しやすい。省エネには、すぐに適温が出る混合水栓(サーモスタット式など)を使う方がよい。","l":"法令外","c":""},{"id":"2018-121","s":4,"q":"給湯設備に関する次の記述のうち、最も不適当なものはどれか。","o":["密閉式膨張水槽を設ける場合には、逃し弁も設けなければならない。","逃し管(膨張管)は、給湯設備の安全装置である。","銅管の線膨張係数は、ポリブテン管のそれより小さい。","循環ポンプの脈動による騒音・振動の発生対策としてサイレンサを設置する場合には、ポンプの流入側に設置する。","耐熱性硬質ポリ塩化ビニル管の許容圧力は、使用温度が高くなると低下する。"],"a":3,"e":"ポンプの脈動(圧力の波)はポンプから押し出される側に伝わるので、サイレンサはポンプの「吐出側」に設ける。","l":"法令外","c":""},{"id":"2018-122","s":4,"q":"給湯設備に関する次の記述のうち、最も不適当なものはどれか。","o":["リバースリターン方式を採用することは、湯を均等に循環させるには有効でない。","外部電源式電気防食では、犠牲陽極が消耗するため取り換えが必要である。","湯をポンプでくみ上げる場合、吸い上げることのできる高さは、温度が高いほど低くなる。","樹脂管を温度の高い湯に使用すると、塩素による劣化が生じやすい。","返湯管の管径は給湯循環ポンプの循環量から決定するが、一般には給湯管の管径の半分程度である。"],"a":1,"e":"犠牲陽極を使い、それが消耗して交換が必要になるのは「流電陽極式」である。外部電源式は電源装置と消耗しにくい電極で防食電流を流す。なお、リバースリターン方式だけでは均等に循環させるのは難しく、弁による流量調整が必要とされる。","l":"法令外","c":""},{"id":"2018-123","s":4,"q":"貯湯槽の保守管理に関する次の記述のうち、最も不適当なものはどれか。","o":["休止中の貯湯槽を再開するときには、点検・清掃を行い、設定温度になるまで加熱してから使用する。","SUS444製の貯湯槽は、腐食を防止するために電気防食を施す。","定期に貯湯槽の外観検査を行い、漏れや周囲の配管の状態を確認する。","使用していない貯湯槽の水は、停滞水の防止のため抜いておく。","開放式の貯湯槽においては、外部からの汚染の経路となりやすいマンホールの気密性、オーバフロー管の防虫網の完全性を点検する。"],"a":1,"e":"SUS444(フェライト系ステンレス)は電気防食をすると水素ぜい化(水素を吸ってもろくなること)を起こすおそれがあるため、電気防食を施してはならない。","l":"法令外","c":""},{"id":"2018-124","s":4,"q":"雑用水設備に関する次の記述のうち、最も不適当なものはどれか。","o":["個別循環方式の雑用水の利用により、下水道への負荷が軽減される。","雑用水槽へ飲料水を補給する場合は、吐水口空間を設けて給水する。","コンクリート製雑用水受水槽の内面は、合成樹脂防水モルタルなどで防水処理を行う。","雑用水の配管は、飲料水用配管と異なる色で塗装する。","建築物衛生法では、雑用水の水質基準項目として、CODが規定されている。"],"a":4,"e":"建築物衛生法の雑用水の基準項目は、pH値・臭気・外観・大腸菌・濁度(散水などの場合)と残留塩素で、CODは含まれない。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2018-125","s":4,"q":"排水再利用設備の単位装置の維持管理に関する次の記述のうち、最も不適当なものはどれか。","o":["スクリーンにおいては、汚物が堆積しないように適時除去する。","流量調整槽においては、ポンプなどの作動状況及び水位・流量を確認する。","活性炭処理装置においては、通水速度を適正に保持する。","凝集処理装置においては、空気供給量を適正に保持する。","ろ過装置においては、ろ材の洗浄が適切に行われていることを確認する。"],"a":3,"e":"凝集処理装置で適正に保つべきなのは「凝集剤の注入量」である。空気供給量を管理するのは、微生物で処理する生物処理装置(ばっ気槽など)である。","l":"法令外","c":""},{"id":"2018-126","s":4,"q":"排水の水質項目に関する次の記述のうち、最も不適当なものはどれか。","o":["DOとは、水中に溶解している分子状の酸素である。","活性汚泥沈殿率(SV)は、活性汚泥の量や沈降性の指標として用いられる。","全窒素とは、有機性窒素、アンモニア性窒素、亜硝酸性窒素及び硝酸性窒素の総和である。","大腸菌群は、し尿中に多く含まれ、汚水処理の進行に伴いその数は減少する。","BODは、水中の酸化可能性物質、主として有機物質が酸化剤によって酸化される際に消費される酸素量を表したものである。"],"a":4,"e":"選択肢はCOD(化学的酸素要求量)の説明である。BOD(生物化学的酸素要求量)は、有機物が「微生物」によって分解されるときに使われる酸素量を表す。","l":"法令外","c":""},{"id":"2018-127","s":4,"q":"排水配管及び通気配管に関する次の記述のうち、最も不適当なものはどれか。","o":["通気立て管の上部は、最高位の衛生器具のあふれ縁から150mm以上高い位置で、伸頂通気管に接続する。","排水横管に設置する通気管は、排水管断面の垂直中心線上部から45°以内の角度で取り出す。","飲料用貯水槽の間接排水管の排水口空間は、最小150mmとする。","排水立て管のオフセット部の上下600mm以内には、排水横枝管を設けてはならない。","管径125mmの排水横管の最小勾配は、1/200である。"],"a":4,"e":"排水横管の最小勾配は、管径65mm以下で1/50、75・100mmで1/100、125mmで1/150、150〜300mmで1/200である。125mmは1/150が正しい。","l":"法令外","c":""},{"id":"2018-128","s":4,"q":"雨水設備に関する次の記述のうち、最も不適当なものはどれか。","o":["雨水浸透方式は、下水道への負荷の軽減や、地下水の涵養を図るために設ける。","雨水ますの流出管は、流入管よりも管底を20mm程度下げて設置する。","雨水ますの底部には100mm程度の泥だめを設け、土砂などが下水道へ流出することを防止する。","雨水排水管と合流式の敷地排水管を接続する場合は、トラップますを設け、ルーフドレンからの悪臭を防止する。","ルーフドレンのストレーナの開口面積は、それに接続する雨水排水管の2倍程度とする。"],"a":2,"e":"雨水ますの底には、深さ150mm以上の泥だめを設ける。100mm程度では浅すぎる。","l":"法令外","c":""},{"id":"2018-129","s":4,"q":"排水通気設備に関する次の記述のうち、最も不適当なものはどれか。","o":["伸頂通気方式の排水横主管の水平曲りは、排水立て管の底部より3m以内に設けてはならない。","排水ポンプは、排水槽の吸込みピットの壁面から200mm以上離して設置する。","排水管への掃除口の設置間隔は、管径100mm以下の場合には15m以内とする。","排水トラップの脚断面積比(流出脚断面積/流入脚断面積)が、大きくなると封水強度は小さくなる。","敷地内排水設備における分流式排水方式は、汚水と雑排水を別々の系統で排水することをいう。"],"a":3,"e":"流出脚の断面積が流入脚より大きいほど、封水が吸い出されにくくなり、封水強度は「大きく」なる。","l":"法令外","c":""},{"id":"2018-130","s":4,"q":"排水通気設備に関する語句の組合せとして、最も不適当なものはどれか。","o":["特殊継手排水システム ― 高層集合住宅へ適用","貯湯槽の排水管 ― 排水口開放による間接排水","排水トラップの深さ ― ディップからウェアまでの垂直距離","結合通気管 ― 排水立て管内の圧力変動の緩和","排水鋼管用可とう継手 ― 排水用硬質塩化ビニルライニング鋼管の接続"],"a":1,"e":"貯湯槽は飲み水に使う湯をためる槽なので、飲料用貯水槽と同じく、排水が逆流しないよう「排水口空間」を設けた間接排水とする。","l":"法令外","c":""},{"id":"2018-131","s":4,"q":"排水通気設備に関する次の記述のうち、最も不適当なものはどれか。","o":["ループ通気管は、排水横枝管に接続された最上流の器具排水管の上流の位置から立ち上げて、通気立て管へ接続する。","敷地排水管の直管が長い場合には、管内径の120倍を超えない範囲内に排水ますを設置する。","排水槽の底部のこう配面には、点検歩行を容易にするため階段を設ける。","排水管径が100mm以下の掃除口の大きさは、排水管と同一径とする。","寒冷地における敷地排水管は、凍結深度より深く埋設する。"],"a":0,"e":"ループ通気管は、最上流の器具排水管が排水横枝管に接続する位置の「すぐ下流」から立ち上げる。","l":"法令外","c":""},{"id":"2018-132","s":4,"q":"排水通気設備に関する次の記述のうち、最も不適当なものはどれか。","o":["ブランチ間隔が3以上で、ループ通気方式とする場合は、通気立て管を設置する。","即時排水型ビルピット設備は、排水槽の悪臭防止に有効である。","自然流下式の排水横管の勾配は、管内最小流速が2.0m/sとなるように設ける。","間接排水管の配管長が、1,500mmを超える場合は、悪臭防止のために機器・装置に近接してトラップを設ける。","トラップが直接組み込まれていない阻集器には、その出口側にトラップを設ける。"],"a":2,"e":"排水横管の勾配は、管内の最小流速が0.6m/s以上(最大1.5m/s程度)になるように決める。2.0m/sは大きすぎる。","l":"法令外","c":""},{"id":"2018-133","s":4,"q":"排水設備の清掃・診断に関する用語の組合せとして、最も不適当なものはどれか。","o":["ロッド法 ― 排水槽の清掃","超音波厚さ計 ― 排水管の腐食状況の診断","ワイヤ(スネークワイヤ)法 ― グリースなどの固い付着物の除去","内視鏡 ― 管内部の詰り具合の確認","薬品洗浄 ― 有機性付着物の除去"],"a":0,"e":"ロッド法は、つないだ棒(ロッド)を管に差し込んで回し、「排水管」の中を掃除する方法である。排水槽の清掃方法ではない。","l":"法令外","c":""},{"id":"2018-134","s":4,"q":"排水通気設備の保守管理に関する次の記述のうち、最も不適当なものはどれか。","o":["排水槽の清掃は、6カ月以内に1回行うことが建築物衛生管理基準で規定されている。","水中ポンプのメカニカルシール部のオイルは、2年に1回程度交換する。","グリース阻集器は、1カ月に1回程度、槽内の底部、壁面等に付着したグリースや沈殿物を清掃する。","排水ポンプは、1カ月に1回絶縁抵抗の測定を行い、1MΩ以上であることを確認する。","高圧洗浄による排水管の清掃では、5〜30MPaの圧力の水を噴射させて洗浄する。"],"a":1,"e":"メカニカルシール部のオイルは、6か月〜1年に1回程度交換する。2年に1回では間隔が長すぎる。","l":"建築物衛生法施行規則 第4条の3(選択肢1)","c":""},{"id":"2018-135","s":4,"q":"大便器回りの故障の現象とその原因との組合せとして、最も不適当なものはどれか。","o":["便器と床面の間が濡れる ― フランジ部シール材の取り付けが不良である。","汚物が満足に流れない ― 排水路に異物が詰まっている。","洗浄弁のハンドル部から漏水する ― ハンドル押し棒部の取り付けナットがゆるんでいる。","少量の水が流れ放しである ― 洗浄弁のシート又はシートパッキンが損傷している。","吐水時間が短い ― 洗浄弁のピストンバルブのストレーナが詰まりかけている。"],"a":4,"e":"洗浄弁はストレーナを通った水でピストンバルブを閉じるので、ストレーナが詰まりかけると閉じるのが遅れ、吐水時間は「長く」なる。","l":"法令外","c":""},{"id":"2018-136","s":4,"q":"衛生器具設備に関する次の記述のうち、最も不適当なものはどれか。","o":["節水機器を導入する場合は、給水器具からの吐水量の削減だけでなく、排水管内の流下特性などにも配慮する。","洗面器は、取り付け状態を2カ月に1回点検することが望ましい。","衛生器具設備をユニット化すると、防水処理工事や養生作業が軽減される。","JIS A 5207では、節水Ⅰ形の大便器の洗浄水量は13L以下としている。","上質水供給設備の目的には、トリハロメタンなどの有害物質を取り除くことや、ミネラル成分の調整を行うことがある。"],"a":3,"e":"JIS A 5207では、節水Ⅰ形の大便器の洗浄水量は8.5L以下(節水Ⅱ形は6.5L以下)とされている。13L以下は節水形ではない一般形の値である。","l":"法令外(JIS A 5207)","c":""},{"id":"2018-137","s":4,"q":"浄化槽法に規定する放流水の水質の技術上の基準に示されているBODの値として、正しいものはどれか。","o":["20mg/L以下","30mg/L以下","60mg/L以下","90mg/L以下","120mg/L以下"],"a":0,"e":"浄化槽からの放流水のBODは20mg/L以下で、あわせてBOD除去率90%以上とすることが定められている。","l":"環境省関係浄化槽法施行規則 第1条の2","c":""},{"id":"2018-138","s":4,"q":"含水率98%の汚泥5m³と、含水率96%の汚泥15m³を混合したときの含水率として、最も近い値はどれか。","o":["0.96","0.965","0.97","0.975","0.98"],"a":1,"e":"水分量は 5×0.98=4.9m³ と 15×0.96=14.4m³ で合計19.3m³。全体は20m³なので、19.3÷20=0.965となる。","l":"法令外","c":""},{"id":"2018-139","s":4,"q":"特殊設備に関する次の記述のうち、最も不適当なものはどれか。","o":["入浴設備において、浴槽からの循環水を消毒する場合には、消毒に用いる塩素系薬剤の投入口は、ろ過器から出た直後に設置する。","水景設備は、水の持つ親水機能や環境調整機能によって空間を演出するものである。","ちゅう房機器の具備すべき要件として、それに用いる材質は吸水性がなく、耐水性・耐食性を持つものとすることが挙げられる。","プールの循環ろ過にオーバフロー方式を採用する場合には、オーバフローに床の洗浄水が入らない構造とする。","入浴設備において、気泡発生装置、ジェット噴射装置等のエアロゾルを発生させる設備を設置する場合には、空気取入口から土ぼこりが入らないような構造とする。"],"a":0,"e":"レジオネラ属菌はろ過器の中で増えやすいので、塩素系薬剤の投入口はろ過器に入る「直前」に設け、ろ過器の中まで消毒する。","l":"法令外","c":""},{"id":"2018-140","s":4,"q":"消火設備に関する語句とその説明との組合せとして、最も不適当なものはどれか。","o":["屋内消火栓設備 ― 初期発見段階での消火","泡消火設備 ― 油火災を対象","連結送水管 ― 公設消防隊の専用栓","不活性ガス消火設備 ― 負触媒作用による消火","スプリンクラー設備 ― 火災発生時に自動的に散水"],"a":3,"e":"不活性ガス消火設備は、二酸化炭素や窒素などで酸素の濃度を下げる「窒息作用」で火を消す。負触媒作用(燃える化学反応を止める働き)で消すのは、ハロゲン化物消火設備や粉末消火設備である。","l":"法令外","c":""},{"id":"2018-141","s":5,"q":"建築物における衛生的環境の維持管理について(平成20年1月25日健発第0125001号)に示された、建築物環境衛生維持管理要領に関する次の記述のうち、最も不適当なものはどれか。","o":["清掃の実施状況を定期に点検し、必要に応じ適切な措置を講じる。","洗剤や床維持剤は、利用者や清掃従事者等の健康及び環境に配慮したものを用いる。","天井等日常の清掃の及びにくい箇所などについて、1年以内ごとに1回、定期に汚れの状況を点検し、必要に応じ、除じん、洗浄を行う。","清掃用資材の保管庫は、6カ月以内ごとに1回、定期に点検する。","帳簿書類には、清掃、点検及び整備を実施した年月日、作業内容等を記載する。"],"a":2,"e":"天井など日常の清掃が行き届きにくい箇所の点検は、6か月以内ごとに1回行う(告示第119号 第5)。1年以内ごとではない。","l":"平成15年厚生労働省告示第119号 第5","c":""},{"id":"2018-142","s":5,"q":"空気調和設備等の維持管理及び清掃等に係る技術上の基準(平成15年厚生労働省告示第119号)に関する次の記述のうち、誤っているものはどれか。","o":["カーペット類の洗浄後は、防汚剤を塗布する。","建築物内で発生する廃棄物の分別、収集、運搬及び貯留について、衛生的かつ効率的な方法により速やかに処理する。","床面の清掃について、日常における除じん作業のほか、床維持剤の塗布の状況を点検し、必要に応じ、再塗布等を行う。","廃棄物の処理設備は、定期に点検し、必要に応じ、補修、消毒を行う。","カーペット類に洗剤を使用する場合は、洗剤分が残留しないようにする。"],"a":0,"e":"告示では、カーペット類は汚れを点検してシャンプークリーニングやしみ抜きを行い、洗剤分を残さないことが定められているが、防汚剤の塗布は求められていない。","l":"平成15年厚生労働省告示第119号 第5","c":""},{"id":"2018-143","s":5,"q":"建築物清掃の作業計画に関する次の記述のうち、最も適当なものはどれか。","o":["廊下壁面のスポット洗浄は、定期清掃で実施する。","廊下壁面のスイッチ回りの洗剤拭きは、一般に日常清掃として実施する。","エレベータかご内部の除じんは、一般に定期清掃として実施する。","管理用区域は、一般の人が立ち入らないため、清掃は年2回程度実施する。","トイレ・洗面所の換気口の除じんは、日常清掃で実施する。"],"a":0,"e":"廊下の壁のスポット洗浄は定期清掃で行う。スイッチ回りの洗剤拭きは定期、エレベーターかご内の除じんは日常、トイレの換気口の除じんは定期に行う。","l":"法令外","c":""},{"id":"2018-144","s":5,"q":"建築物清掃の資機材倉庫に関する次の記述のうち、最も不適当なものはどれか。","o":["施錠できる構造とする。","適切な照明設備、換気設備を設け、資機材洗浄用の給排水設備を設ける。","建築物の規模・形態等により、エリアごとに資機材倉庫を設ける場合がある。","設置位置は、資機材の移動などが容易に行える場所とする。","濡れたモップなどが置かれる場合があるので、床や壁面を浸透性の建材にする。"],"a":4,"e":"濡れたモップなどを置くので、床や壁は水がしみ込まない不浸透性の材料にする。浸透性の建材は誤り。","l":"法令外","c":""},{"id":"2018-145","s":5,"q":"建築物清掃の品質評価に関する次の記述のうち、最も不適当なものはどれか。","o":["品質評価の年間計画に基づき、評価範囲、実施日、点検時間、点検経路等を決定し実施計画を作成する。","実施計画に従い、事前に作成した品質評価シートなどを活用して点検を実施する。","改善が必要と判断した場合は、評価者が清掃作業者に指示をする。","改善を指示した箇所について、指示どおりに改善されているか再点検し、その結果を基に再評価を実施する。","評価者は、業務に精通していることが望ましい。"],"a":2,"e":"改善が必要なときは、評価者が直接作業者に指示するのではなく、清掃責任者(現場の管理者)を通して指示する。","l":"法令外","c":""},{"id":"2018-146","s":5,"q":"建築物清掃の品質評価と作業改善に関する次の記述のうち、最も不適当なものはどれか。","o":["清掃作業の精度を向上させることは、品質評価の目的の一つである。","仕様書、作業基準表に限定せず建築物全体が快適環境になっているかに着眼して改善点を見出す。","廃棄物処理における実態分析は、衛生的かつ安全で効率的かに着眼して行う。","評価方法には、測定機器(光沢度計など)を使用する検査と、目視などによる官能検査とがある。","品質の評価は清掃作業者の立場に立って実施する。"],"a":4,"e":"品質の評価は、建物を使う利用者の立場に立って行う。清掃作業者の立場ではない。","l":"法令外","c":""},{"id":"2018-147","s":5,"q":"ほこりや汚れの除去に関する次の記述のうち、最も適当なものはどれか。","o":["おがくずを用いる方法は、ほこりを付着させる効果が小さい。","ほこりは長期間放置した方が除去しやすい。","粘度の低い不乾性の鉱油などを布に含ませ、ほこりを除去する方法をダストコントロール法という。","バキュームクリーニングでは、カーペットの織り目に入り込んだほこりや土砂は除去できない。","ダストクロス法は、油分による床面への弊害が多い。"],"a":2,"e":"粘度の低い不乾性の鉱油などを布に含ませてほこりを取る方法がダストコントロール法。1はおがくずはほこりをよく付着させる、2は放置すると取りにくくなる、4は真空掃除機で取れる、5は油分による弊害は少ない。","l":"法令外","c":""},{"id":"2018-148","s":5,"q":"建材の予防清掃に関する次の記述のうち、最も不適当なものはどれか。","o":["疎水性の建材には、油溶性物質が付着しやすい。","汚れは、平滑緻密な表面には付着しにくい。","耐水性のある建材は、清掃しやすいものが多い。","シール剤や床維持剤の塗布により、美観は向上するが、汚れの予防効果は得られない。","汚れが内部にしみ込みやすい建材は、汚れの除去に手間がかかる。"],"a":3,"e":"シール剤や床維持剤を塗ると、汚れが付きにくく落としやすくなるので、汚れの予防効果がある。","l":"法令外","c":""},{"id":"2018-149","s":5,"q":"ビルクリーニング用機械に関する次の記述のうち、最も適当なものはどれか。","o":["超高速バフ機の回転数は、毎分150〜300回転である。","自動床洗浄機は、洗剤供給式床みがき機と、吸水式真空掃除機とを結合したものである。","凹凸のある床面は、研磨粒子が付着したパッドを付けて洗浄する。","樹脂皮膜の剥離は、床用パッドの青又は赤が使われる。","床面洗浄用ロボットの連続作業時間は、1バッテリーで30〜60分ほどである。"],"a":1,"e":"自動床洗浄機は、洗剤を出してブラシで洗う床みがき機と、汚水を吸い取る吸水式真空掃除機を組み合わせた機械である。超高速バフ機は毎分1,000〜3,000回転で、剥離には黒や茶のパッドを使う。","l":"法令外","c":""},{"id":"2018-150","s":5,"q":"カーペット清掃用機械に関する次の記述のうち、最も不適当なものはどれか。","o":["真空掃除機は、電動ファンによって機械内部に空気の低圧域を作り、ホースを通じてほこりを吸引する構造である。","床移動型のドライ式真空掃除機は、床を回転ブラシで掃きながら、ごみやほこりを吸引する構造である。","アップライト型真空掃除機は、カーペットのほこりを取るのに適する構造である。","エクストラクタは、ノズルから洗浄液を噴射して、直ちに吸引する構造である。","スチーム洗浄機は、高温の水蒸気で汚れを分解するため、水分が少なく仕上がりも柔らかい。"],"a":1,"e":"回転ブラシで掃きながら吸い込むのは、カーペット向きのアップライト型真空掃除機の特徴。床移動型のドライ式真空掃除機は、吸引だけでごみやほこりを取る。","l":"法令外","c":""},{"id":"2018-151","s":5,"q":"清掃作業に使用する洗剤に関する次の記述のうち、最も適当なものはどれか。","o":["洗剤の助剤は、界面活性剤の表面張力を高めて洗浄力を向上させる。","アルカリ性の洗剤は、尿石や水垢等の除去に有効である。","アルカリ性の剥離剤は、清掃作業者の皮膚をおかす恐れがある。","樹脂床維持剤の皮膜手入れ用の表面洗剤は、よく泡立つように作られている。","洗剤は、高濃度で使用するほうがよい。"],"a":2,"e":"アルカリ性の剥離剤は皮膚をおかす恐れがあるので、保護手袋などを使う。助剤は洗浄力を助けるもの、尿石や水あかには酸性洗剤、表面洗剤は泡立ちを抑えてあり、洗剤は適正な濃度で使う。","l":"法令外","c":""},{"id":"2018-152","s":5,"q":"硬性床材の特徴に関する次の記述のうち、最も不適当なものはどれか。","o":["大理石は、耐酸性、耐アルカリ性に乏しい。","花崗岩は、耐熱性に乏しい。","コンクリートは、耐酸性に乏しい。","テラゾは、耐酸性に優れる。","セラミックタイルは、耐酸性、耐アルカリ性、耐摩耗性に優れる。"],"a":3,"e":"テラゾは大理石の砕石をセメントで固めた人造石なので、大理石と同じく酸に弱い。「耐酸性に優れる」は誤り。","l":"法令外","c":""},{"id":"2018-153","s":5,"q":"弾性床材の特徴と維持管理に関する次の記述のうち、最も不適当なものはどれか。","o":["床維持剤の黒ずみが生じてきたら、床維持剤の剥離作業をし、再生させる。","塩化ビニルシートは、床維持剤の密着不良が起きやすい。","日常清掃では、ダストモップなどを用いて、土砂やほこりを除去する。","スポットクリーニングでは、汚れが激しい箇所を部分的に洗浄し、床維持剤を塗布する。","塩化ビニルタイルは、アルカリ性洗剤に弱い。"],"a":4,"e":"塩化ビニルタイルは薬品に強く、アルカリ性洗剤にも強い。アルカリに弱いのはリノリウムなどである。","l":"法令外","c":""},{"id":"2018-154","s":5,"q":"清掃作業におけるドライメンテナンスに関する次の記述のうち、最も適当なものはどれか。","o":["ウェットメンテナンス法に比べ、作業の安全性に劣る。","ウェットメンテナンス法に比べ、使用する資機材が多い。","床材への熱影響に注意が必要である。","ドライバフ法は、研磨剤を含んだフロアパッドで磨き、光沢度を回復させる作業である。","ドライバフ法で用いる床みがき機は、回転数が低いほど、光沢回復が簡単にできる。"],"a":2,"e":"ドライメンテナンス法では、高速で回る床みがき機の摩擦熱で床材を傷めることがあるので、熱の影響に注意する。水を使わないので安全性は高く、資機材も少なく、回転数が高いほど光沢は戻しやすい。","l":"法令外","c":""},{"id":"2018-155","s":5,"q":"床以外の清掃作業に関する次の記述のうち、最も不適当なものはどれか。","o":["人の手による汚れは、化学繊維を使った製品(マイクロファイバークロスなど)を用いると除去しやすい。","階段の壁面は、他の場所より、ほこりの付着度合いが高い。","トイレの清掃用具は、便器に使用するものと、洗面器に使用するものとは区別する。","湯沸室に使用する資機材は、湯沸室専用として、他の場所と区別する。","ドア・エレベータスイッチ等は、冬期は夏期に比べ手垢が付きやすくなる。"],"a":4,"e":"手あかは汗や皮脂の多い夏の方が付きやすい。冬の方が付きやすいのではない。","l":"法令外","c":""},{"id":"2018-156","s":5,"q":"外装の清掃に関する次の記述のうち、最も不適当なものはどれか。","o":["金属製の外壁は、硬質ブラシでこすり洗いをする。","石材や陶磁器タイルの壁面は、徐々に汚れていくので、3〜5年に1回程度の頻度で洗浄を行う。","海岸地帯の金属製の外壁は、年に3〜4回程度の頻度で洗浄を行う。","臨海工業地帯の窓ガラスは、汚れが付きやすいので、月に1回程度の頻度で洗浄を行う。","自動窓拭き機は、洗剤又は水をガラス面に噴射して洗浄し、汚水をかき集め、真空吸引装置で回収する構造となっている。"],"a":0,"e":"金属製の外壁を硬いブラシでこすると傷が付く。中性洗剤や専用洗剤を使い、スポンジやウエスで拭き取る。","l":"法令外","c":""},{"id":"2018-157","s":5,"q":"廃棄物の処理及び清掃に関する法律に関する次の文章の(　　　)内に入る語句の組合せとして、最も適当なものはどれか。\n\n昭和45年の制定時に、従来の法律の衛生面から規定されていた汚物に加えて、( ア )の概念を追加して、廃棄物を定義し、産業廃棄物と一般廃棄物に分類するとともに、公衆衛生の向上に加え、( イ )を法の目的に追加した。","o":["ア:不要物、イ:都市の健全な発達","ア:不要物、イ:生活環境の保全","ア:固形状廃棄物、イ:都市の健全な発達","ア:液状廃棄物、イ:生活環境の保全","ア:液状廃棄物、イ:都市の健全な発達"],"a":1,"e":"廃棄物処理法では、廃棄物を「汚物又は不要物」と定義し、目的を「生活環境の保全及び公衆衛生の向上」としている(第1条・第2条)。","l":"廃棄物処理法 第1条・第2条第1項","c":""},{"id":"2018-158","s":5,"q":"3R(リデュース、リユース、リサイクル)を促進するための個別法に関する次の語句の組合せのうち、最も不適当なものはどれか。","o":["家電リサイクル法(特定家庭用機器再商品化法) ― 家庭用エアコン、テレビ(ブラウン管式、液晶式、プラズマ式)、冷蔵庫・冷凍庫、洗濯機・衣類乾燥機の4品目","容器包装リサイクル法(容器包装に係る分別収集及び再商品化の促進等に関する法律) ― 空き缶、プラスチック等容器包装廃棄物","食品リサイクル法(食品循環資源の再生利用等の促進に関する法律) ― 食品関連事業者(食品の製造・加工・販売業者等)","小型家電リサイクル法(使用済小型電子機器等の再資源化の促進に関する法律) ― 携帯電話、デジタルカメラ、ゲーム機器等28品目","建設リサイクル法(建設工事に係る資材の再資源化等に関する法律) ― 環境負荷の少ない物品の調達の推進"],"a":4,"e":"建設リサイクル法は、建設工事で出る資材の分別解体と再資源化を進める法律。環境負荷の少ない物品の調達を進めるのはグリーン購入法である。","l":"建設工事に係る資材の再資源化等に関する法律 第1条","c":""},{"id":"2018-159","s":5,"q":"建築物内の事業活動に伴って排出される廃棄物の処理などに関する次の記述のうち、最も不適当なものはどれか。","o":["プラスチック類のうち再生利用されないものを一般廃棄物の許可業者に委託して処理する。","生ごみのうち再生利用されないものを一般廃棄物の許可業者に委託して処理する。","古紙は専ら再生利用の目的となるもので資源回収業者に委託して処理する。","し尿を含まない雑排水槽からのビルピット汚泥を産業廃棄物の許可業者に委託して処理する。","グリース阻集器で阻集される油分を産業廃棄物の許可業者に委託して処理する。"],"a":0,"e":"事業活動に伴って出る廃プラスチック類は産業廃棄物なので、産業廃棄物の許可業者に委託する。一般廃棄物の許可業者に委託するのは誤り。","l":"廃棄物処理法 第2条第4項","c":""},{"id":"2018-160","s":5,"q":"産業廃棄物に関する次の記述のうち、最も不適当なものはどれか。","o":["建築物内に診療所がある場合、建築物の所有者は特別管理産業廃棄物管理責任者を置かなければならない。","爆発性、毒性、感染性その他の人の健康又は生活環境に被害を生ずるおそれのあるものは、特別管理産業廃棄物として規定されている。","排出事業者が自ら処理を行う場合、処理基準に従うことが必要である。","排出事業者が処理業者に委託して処理を行う場合、委託基準に従うことが必要である。","事業活動に伴って生じた廃棄物のうち、燃えがら、汚泥等20種類が産業廃棄物として定められている。"],"a":0,"e":"特別管理産業廃棄物管理責任者は、その廃棄物を出す事業者(この場合は診療所の開設者)が置く(第12条の2第8項)。建物の所有者ではない。","l":"廃棄物処理法 第12条の2第8項","c":""},{"id":"2018-161","s":5,"q":"一般廃棄物に関する次の記述のうち、最も不適当なものはどれか。","o":["市町村は、一般廃棄物処理計画に従い清掃事業として処理を行う。","ごみとし尿に分類され、ごみは家庭系ごみと事業系ごみに分類される。","ごみの分別とは、収集、運搬、リサイクル(再生利用)、中間処理、最終処分が適切に行われるよう、発生・排出元であらかじめ区分することである。","中間処理方法としては、破砕・圧縮が最も多い。","ごみの排出量を排出形態別でみると、平成28年度において、家庭系ごみが約70%を占める。"],"a":3,"e":"ごみの中間処理で最も多いのは焼却処理である。破砕・圧縮が最も多いのではない。","l":"法令外(環境省の統計)","c":""},{"id":"2018-162","s":5,"q":"事務所建築物から雑芥が1日当たり5m³排出されており、その質量は全廃棄物量の50%を占めていた。いま、全廃棄物量の質量を1日当たり2.0トンとすれば、雑芥の容積質量値(kg/m³)として正しいものは、次のうちどれか。","o":["10kg/m³","20kg/m³","100kg/m³","200kg/m³","800kg/m³"],"a":3,"e":"雑芥の質量は2.0トン×50%＝1,000kg。容積質量値＝1,000kg÷5m³＝200kg/m³。","l":"計算","c":""},{"id":"2018-163","s":5,"q":"建築物内廃棄物の中間処理に関する次の記述のうち、最も不適当なものはどれか。","o":["中間処理の目的は、廃棄物の減量化である。","建築物に導入されている設備は、比較的小規模なものが多い。","溶融固化装置は、ちゅう芥の処理に用いられる。","中間処理方法として、脱水がある。","プラスチックの中間処理方法として圧縮がある。"],"a":2,"e":"溶融固化装置は、発泡スチロールなどのプラスチックを熱で溶かして固め、体積を減らす装置である。厨芥(生ごみ)の処理には脱水機などを使う。","l":"法令外","c":""},{"id":"2018-164","s":5,"q":"建築物内廃棄物の保管場所に関する次の記述のうち、最も不適当なものはどれか。","o":["出入口には自動ドアを設ける。","床は傾きがないように水平にする。","ねずみ、昆虫等の誘引、侵入防止を図るため、防虫・防鼠構造とする。","壁面(腰壁)は、防水加工を施す。","分別、収集、保管が支障なく行えるよう、十分なスペースを確保する。"],"a":1,"e":"廃棄物の保管場所の床は、洗浄水などが流れるように排水溝に向けて勾配をつける。水平にするのは誤り。","l":"法令外","c":""},{"id":"2018-165","s":5,"q":"産業廃棄物管理票制度(マニフェスト制度)に関する次の記述のうち、最も不適当なものはどれか。","o":["電子マニフェストは、紙マニフェストに代えて、通信ネットワークを使用して、排出事業者がその処理を委託した廃棄物の流れを管理する仕組みである。","紙マニフェストの場合、排出事業者は、委託時に収集運搬業者からA票を入手し、原本を保存する。","紙マニフェストの場合、収集運搬業者は、作業が終了すると排出事業者にB2票を返却する。","紙マニフェストの場合、最終処分場での処分が完了すると、収集運搬業者にE票が返却される。","紙マニフェストの場合、排出事業者は、D票が委託から90日を経過しても返却されない場合、委託事業者に対して処分の状態を問い合わせる。"],"a":3,"e":"最終処分が終わったことを示すE票は、排出事業者に返送される。収集運搬業者に返却されるのではない。なおD票が交付から90日たっても戻らないときは、処理の状況を確認する(施行規則第8条の28)。","l":"廃棄物処理法施行規則 第8条の28","c":""},{"id":"2018-166","s":6,"q":"蚊に関する次の記述のうち、最も不適当なものはどれか。","o":["アカイエカは、羽化後、最初の産卵を無吸血で行うことができる。","コガタアカイエカの幼虫は、田んぼや湿地等の水域に発生する。","チカイエカは、北海道にも分布する。","ヒトスジシマカの幼虫の主な発生源として、道路や公園等に存在する雨水ますがある。","アカイエカとチカイエカの雌成虫は、外部形態で区別することは困難である。"],"a":0,"e":"羽化後の最初の産卵を吸血せずに行えるのは「チカイエカ」である。アカイエカは産卵に吸血が必要である。","l":"法令外","c":""},{"id":"2018-167","s":6,"q":"蚊の防除に関する次の記述のうち、最も不適当なものはどれか。","o":["昆虫成長制御剤(IGR)は、幼虫や蛹に対する速効的な致死効果が認められない。","浄化槽の殺虫剤処理後も成虫の発生数が減少しない場合は、薬剤抵抗性の発達を考慮する必要がある。","排水槽内に設置した粘着トラップで捕獲した蚊の数では、槽内の成虫密度を評価できない。","樹脂蒸散剤は、密閉性が保たれている空間では、1〜3カ月間の効果が期待できる。","乳剤に含まれる界面活性剤や有機溶剤は、浄化槽内の浄化微生物に影響を及ぼす可能性がある。"],"a":2,"e":"排水槽や浄化槽の中の成虫の多さは、粘着トラップで捕まえた数(1日1トラップあたりの捕獲数など)で評価できる。","l":"法令外","c":""},{"id":"2018-168","s":6,"q":"ゴキブリの生態に関する次の記述のうち、最も不適当なものはどれか。","o":["ゴキブリは、潜み場所として、暗く、暖かく、湿気が多く、狭く、餌や水場に近い所を好む。","ゴキブリの潜伏場所や歩く場所における排泄物による汚れのことを、ローチスポットという。","ゴキブリは、什器や壁等の縁や隅を好んで通る傾向が強い。","ゴキブリ指数とは、微量な薬剤のフラッシング効果により物陰から飛び出てくる数を指数化したものである。","ゴキブリは、幼虫、成虫ともに同じ場所で活動し、同じ食物を摂取する。"],"a":3,"e":"ゴキブリ指数は、粘着トラップの捕獲数を「1日1トラップあたり」にならした値である。薬剤で追い出した数ではない。","l":"法令外","c":""},{"id":"2018-169","s":6,"q":"ゴキブリの防除に関する次の記述のうち、最も不適当なものはどれか。","o":["残留処理に用いられる薬剤には、ダイアジノンやフェニトロチオン等の乳剤がある。","発生防止対策としては、食べ物の管理と環境の整備が重要である。","ULV処理では、ピレスロイド剤を有効成分とする専用の水性乳剤が用いられる。","毒餌処理に用いられる薬剤には、ホウ酸やヒドラメチルノン等を有効成分とした製剤がある。","空間処理は、ゴキブリがよく徘徊する通路、壁面等に薬剤を処理し、残渣に触れさせる方法である。"],"a":4,"e":"通路や壁面に薬剤をまいて、その残りにゴキブリを触れさせるのは「残留処理」である。空間処理は、煙霧やULVで空間に薬剤を漂わせる方法である。","l":"法令外","c":""},{"id":"2018-170","s":6,"q":"ダニに関する次の記述のうち、最も不適当なものはどれか。","o":["ヒゼンダニによる角化型疥癬は、感染性が非常に高いことが知られている。","イエダニは、スズメやムクドリ等の野鳥によって運び込まれる場合が多い。","コナダニ類の防除対策は、ツメダニ類の対策としても重要である。","カベアナタカラダニは建築物の外壁を多数歩き回り不快感を与えるが、ヒトを加害することはない。","マダニ類対策として、野外活動時における忌避剤の使用も有効である。"],"a":1,"e":"イエダニはネズミに寄生するダニで、ネズミと一緒に建物へ入ってくる。野鳥が運び込むのはトリサシダニである。","l":"法令外","c":""},{"id":"2018-171","s":6,"q":"害虫に関する次の記述のうち、最も不適当なものはどれか。","o":["コガタアカイエカの性フェロモンを用いた誘引トラップがある。","アルゼンチンアリは、砂糖、花の蜜、果物等を好む。","ヒラタキクイムシ類による被害は、針葉樹材を使用すれば発生しない。","クサギカメムシの越冬侵入に対しては、侵入場所となる窓枠などにシフェノトリンを処理すると侵入防止効果がある。","ノシメマダラメイガは、貯穀害虫である。"],"a":0,"e":"蚊の性フェロモンを使ったトラップは実用化されていない。蚊の調査には、炭酸ガス(ドライアイス)や光で誘う方法が使われる。","l":"法令外","c":""},{"id":"2018-172","s":6,"q":"殺虫剤やその剤型に関する次の記述のうち、最も不適当なものはどれか。","o":["有機リン剤を有効成分とするマイクロカプセル(MC)剤がある。","乳剤は、水で希釈すると白濁(乳濁化)する。","ピレスロイド剤によりノックダウンした虫は、蘇生する場合がある。","フィプロニルを有効成分とするゴキブリ用の食毒剤がある。","ジクロルボスは、残効性が高い殺虫剤である。"],"a":4,"e":"ジクロルボス(DDVP)は蒸気圧が高くすぐ揮発するので、速効性はあるが残効性は低い。","l":"法令外","c":""},{"id":"2018-173","s":6,"q":"ねずみの生態に関する次の記述のうち、最も不適当なものはどれか。","o":["ねずみ類は、高圧変電器を避けることはなく、停電の原因となることがある。","ドブネズミは、クマネズミに比べて運動能力に優れ、垂直な壁を登り屋内に侵入する。","ドブネズミは、屋外の植え込みの巣穴や下水道内部に生息している。","クマネズミは、ドブネズミより警戒心が強く、毒餌やトラップによる防除が難しい。","ハツカネズミは、好奇心が旺盛で、トラップにかかりやすい。"],"a":1,"e":"運動能力に優れ、垂直な壁や配管を登って高い階に入り込むのは「クマネズミ」である。ドブネズミは泳ぎが得意で、低い階や下水道に多い。","l":"法令外","c":""},{"id":"2018-174","s":6,"q":"ねずみの防除に関する次の記述のうち、最も不適当なものはどれか。","o":["殺鼠剤は、経口的な取り込みにより効果が発揮される。","侵入を防ぐために、通風口や換気口の金属格子の目の幅は1cm以下にする。","第1世代の抗凝血性殺鼠剤であるフマリンは、速効性である。","カプサイシンは、ケーブルなどのかじり防止の目的で使用される。","防除の基本は、餌を絶つこと、巣を作らせないこと、及び通路を遮断することである。"],"a":2,"e":"第1世代の抗凝血性殺鼠剤(フマリン、ワルファリンなど)は、何日も続けて食べさせて効く「遅効性」の薬剤である。","l":"法令外","c":""},{"id":"2018-175","s":6,"q":"殺鼠剤やその剤型に関する次の記述のうち、最も不適当なものはどれか。","o":["ジフェチアロールは、ワルファリンに対する抵抗性を獲得したネズミに対しても有効である。","クマテトラリルは、第2世代の抗凝血性殺鼠剤である。","シリロシドは、急性殺鼠剤である。","粉剤は、餌材料にまぶして毒餌を作製するのに使用することができる。","ブロマジオロン製剤は、建築物衛生法に基づく特定建築物内では使用できない。"],"a":1,"e":"クマテトラリルは「第1世代」の抗凝血性殺鼠剤である。第2世代はジフェチアロールやブロマジオロンなどで、1回食べるだけでも効く。","l":"法令外","c":""},{"id":"2018-176","s":6,"q":"疾病と衛生害虫との組合せとして、最も不適当なものはどれか。","o":["ライム病 ― マダニ類","日本脳炎 ― コガタアカイエカ","マラリア ― ハマダラカ類","デング熱 ― チカイエカ","アナフィラキシーショック ― スズメバチ類"],"a":3,"e":"デング熱を媒介するのは、ヒトスジシマカやネッタイシマカなどのヤブカ類である。チカイエカは媒介しない。","l":"法令外","c":""},{"id":"2018-177","s":6,"q":"殺虫・殺鼠剤の毒性や安全性に関する次の記述のうち、最も不適当なものはどれか。","o":["ヒトや動物に対するLD50の値が小さいほど、その薬剤の安全性は確保されやすい。","薬剤のヒトや動物に対する安全性は、毒性の強弱、摂取量、摂取期間等によって決まる。","害虫の種類が同じでも、幼虫と成虫により薬剤感受性が異なる場合がある。","殺鼠剤の有効成分の濃度は低く抑えられているので、ヒトとネズミの体重差から誤食による人体への影響は少ない。","衛生害虫用殺虫剤は医薬品、医療機器等の品質、有効性及び安全性の確保等に関する法律の規制に基づき、安全性、薬理、効力等の資料の審査により承認される。"],"a":0,"e":"LD50は半数の動物が死ぬ量なので、値が小さいほど少ない量で死ぬ、つまり毒性が強い。ヒトや動物へのLD50は大きいほど安全である。","l":"法令外","c":""},{"id":"2018-178","s":6,"q":"防虫・防鼠構造や防除に用いる機器に関する次の記述のうち、最も適当なものはどれか。","o":["室内灯の光源の色は、昆虫に対する誘引性とは無関係である。","超音波防鼠機は、同じ周波数の超音波を流し続けても、ネズミが慣れることはない。","食品を取扱う場所の上には電撃式殺虫機を設置するとよい。","噴射できる薬剤の粒径は、噴霧機、ミスト機、煙霧機の順に大きくなる。","通常20メッシュより細かい網目であれば、カ、コバエ等、多くの昆虫の侵入を防止できる。"],"a":4,"e":"20メッシュより細かい網なら、蚊やコバエなど多くの昆虫を防げる。ほかは、光の色で集まり方が変わる、ネズミは超音波に慣れる、電撃式は虫の破片が落ちるので食品の上は避ける、粒径はこの順に「小さく」なる、が正しい。","l":"法令外","c":""},{"id":"2018-179","s":6,"q":"建築物衛生法に基づく特定建築物内のねずみ等の防除に関する次の記述のうち、最も不適当なものはどれか。","o":["トラップによる捕獲調査を行った場合、1日1トラップ当たりの平均捕獲数を捕獲指数として算出しておく。","ベクターコントロールとは、感染症の媒介を断つための手段として行うねずみ等の防除である。","ねずみ等の防除を行う際は、必要に応じて薬剤を使用する。","ねずみ等に対する対策を行った場合、有害生物の密度調査などによって、その効果について客観性のある評価を行う。","防除は、発生予防対策より発生時対策に重点を置いて実施する。"],"a":4,"e":"建築物での防除は、IPM(総合的有害生物管理)の考え方により、発生してから駆除するよりも「発生予防」に重点を置く。","l":"建築物衛生法施行規則 第4条の5第2項","c":""},{"id":"2018-180","s":6,"q":"害虫や薬剤に関する次の記述のうち、最も不適当なものはどれか。","o":["殺虫剤抵抗性は、同一の殺虫剤が繰り返し使用されることによる淘汰によって発達する。","昆虫等に対する不快感の程度は、第三者による客観的な判断が困難である。","昆虫成長制御剤(IGR)による羽化阻害の効力は、KT50で評価される。","建築物内に発生する昆虫などが喘息のアレルゲンになることがある。","吸血害虫の中には、幼虫、雌・雄成虫ともに吸血する種類がある。"],"a":2,"e":"KT50は半数の虫が倒れる(ノックダウンする)までの時間で、速効性の指標である。IGRの羽化阻害の効力は、50%羽化阻害濃度(IC50)で評価する。","l":"法令外","c":""},{"id":"2019-1","s":0,"q":"世界保健機関(WHO)憲章の前文にある健康の定義について、次の文の( )に入る語句として、最も適当なものはどれか。\n「健康とは完全な肉体的、精神的及び社会的福祉の状態にあり、単に病気又は病弱の存在しないことではない。到達しうる最高基準の健康を享受することは、人種、宗教、政治的信念又は経済的もしくは( )条件の差別なしに万人の有する基本的権利の一つである。」","o":["地域的","文化的","社会的","精神的","身体的"],"a":2,"e":"WHO憲章の前文は「人種、宗教、政治的信念又は経済的もしくは社会的条件の差別なしに」としている。健康は、どんな立場の人にもある基本的な権利だという考え方である。","l":"法令外","c":""},{"id":"2019-2","s":0,"q":"建築物衛生法に基づく特定建築物の用途について、最も不適当なものはどれか。","o":["百貨店は、大規模小売店舗立地法に規定する大規模小売店舗をいう。","興行場は、興行場法に規定する興行場に限らない。","図書館は、図書館法に規定する図書館に限らない。","博物館は、博物館法に規定する博物館に限らない。","旅館は、旅館業法に規定する旅館業を営むための施設をいう。"],"a":1,"e":"特定建築物の用途としての興行場は、興行場法に規定する興行場をいう。一方、図書館や博物館は、図書館法・博物館法の施設に限らず、同じような使い方をする施設も含まれる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2019-3","s":0,"q":"建築物衛生法に基づく特定建築物の延べ面積について、最も不適当なものはどれか。","o":["地下街の地下道は、延べ面積に算入しない。","公共駐車場は、延べ面積に算入しない。","事務所内の事務所用倉庫は、延べ面積に算入しない。","共同住宅は、延べ面積に算入しない。","診療所は、延べ面積に算入しない。"],"a":2,"e":"事務所の中にある事務所用の倉庫は、特定用途(事務所)に付属する部分なので、延べ面積に入れる。地下街の地下道、公共駐車場、共同住宅、診療所は入れない。","l":"建築物衛生法 第2条、施行令 第1条","c":""},{"id":"2019-4","s":0,"q":"建築物衛生法について、誤っているものはどれか。","o":["特定建築物においては、建築物環境衛生管理基準に従った維持管理が義務付けられている。","特定建築物の所有者等は、建築物環境衛生管理技術者を選任しなければならない。","建築物環境衛生管理基準は、空気環境の調整、給水及び排水の管理、清掃、ねずみ・昆虫等の防除に関し、環境衛生上良好な状態を維持するのに必要な措置について定めている。","建築物環境衛生管理基準を定め、建築物環境衛生管理技術者にその遵守を義務付けている。","建築物環境衛生上の維持管理を行う事業者の資質の向上を図ることが重要であることから、これらの事業者について登録制度が設けられている。"],"a":3,"e":"管理基準を守る義務があるのは、特定建築物の維持管理について権原を持つ者(所有者・占有者など)である。管理技術者は、基準どおりに維持管理されるよう監督し、必要なら意見を述べる立場である。","l":"建築物衛生法 第4条、第6条","c":""},{"id":"2019-5","s":0,"q":"建築物衛生法に基づく特定建築物の用途として、最も不適当なものはどれか。","o":["ボーリング場","水族館","公民館","人文科学系研究所","スポーツジム"],"a":4,"e":"スポーツジムは、施行令の特定用途に当たらない(公式の正答)。ボーリング場は遊技場、水族館は博物館、公民館は集会場、人文科学系研究所は事務所に当たる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2019-6","s":0,"q":"次の建築物のうち、建築物衛生法に基づく特定建築物に該当するものはどれか。","o":["延べ面積が2,500m²の事務所を併せもつ、5,000m²の自然科学系研究施設","延べ面積が3,500m²の中学校と4,000m²の高等学校を併せもつ、7,500m²の中高一貫校","延べ面積が1,500m²の体育施設を併せもつ、6,500m²の専門学校","延べ面積が2,500m²の事務所を併せもつ、5,000m²の寺院","延べ面積が2,500m²の店舗と2,000m²の貸倉庫を併せもつ、4,500m²の複合建築物"],"a":2,"e":"専門学校は学校教育法第1条の学校ではないので、3,000m²以上で特定建築物になる。付属の体育施設も含めて6,500m²なので該当する。中高一貫校は1条の学校なので8,000m²必要で、ほかは特定用途の部分が3,000m²に届かない。","l":"建築物衛生法 第2条、施行令 第1条","c":""},{"id":"2019-7","s":0,"q":"建築物衛生法に基づく特定建築物の届出について、最も不適当なものはどれか。","o":["用途の変更により、特定建築物に該当しなくなったときは、その日から1か月以内に、その旨を届け出なければならない。","届出義務者は、所有者あるいは当該特定建築物の全部の管理について権原を有する者である。","現に使用されている建築物が、増築により新たに特定建築物に該当することになったときは、その日から1か月以内に届け出なければならない。","届出の様式は、建築物衛生法施行規則で定められている。","建築物衛生法施行規則に基づく届出事項に変更があったときは、その日から1か月以内に、その旨を届け出なければならない。"],"a":3,"e":"施行規則第1条は届出に書く事項を定めているが、届出の様式(書式)までは定めていない。届出は所有者等が、使用開始・該当・変更・非該当の日から1か月以内に行う。","l":"建築物衛生法 第5条、施行規則 第1条","c":""},{"id":"2019-8","s":0,"q":"建築物環境衛生管理基準に基づく空気環境の測定について、最も適当なものはどれか。","o":["新築の特定建築物では、最初の1年間は毎月測定しなければならない。","測定を行う場合は、1日2回以上測定することが必要である。","階数が多い場合は、各階ごとに測定しなくてもよい。","測定場所は、適当な居室を選択し、測定しやすい場所で行う。","ホルムアルデヒドの測定結果が基準を超えた場合は、空調・換気設備を調整するなど軽減措置を実施後、速やかに測定し、効果を確認しなければならない。"],"a":1,"e":"浮遊粉じん・一酸化炭素・二酸化炭素は1日の使用時間中の平均値で評価するため、始業後と終業前など1日2回以上測る。測定は2か月以内ごとに1回、各階ごとに、居室の中央部の床上75〜150cmで行う。","l":"建築物衛生法施行規則 第3条の2","c":""},{"id":"2019-9","s":0,"q":"建築物環境衛生管理技術者について、最も適当なものはどれか。","o":["特定建築物ごとに選任しなければならないので、同時に2以上の特定建築物の建築物環境衛生管理技術者となることは、いかなる場合も認められない。","建築物環境衛生管理技術者は、必要があると認めるときは、建築物維持管理権原者に意見を述べることができ、建築物維持管理権原者はこの意見に従わなければならない。","建築物環境衛生管理技術者が管理業務の指揮監督を怠り健康被害が発生した場合は、建築物環境衛生管理技術者に対して罰則の適用がある。","建築物環境衛生管理技術者の免状の記載事項に変更を生じたときは、厚生労働大臣に免状の書換え交付を申請しなければならない。","建築物環境衛生管理技術者の免状の再交付を受けた後、失った免状を発見したときは、5日以内に、失った免状を廃棄した旨を厚生労働大臣に報告する。"],"a":4,"e":"再交付の後に失った免状が見つかったら、5日以内に、その免状を廃棄したことを厚生労働大臣に報告する。兼任は支障がなければ認められ、権原者は意見を「尊重」する義務にとどまり、書換え交付は「申請できる」である。","l":"建築物衛生法 第6条、施行規則 第5条、第11条、第12条","c":"出題時の選択肢(5)は「5日以内にこれを厚生労働大臣に返還する」だったが、2026年1月ごろ施行の施行規則改正で「失った免状を廃棄した旨を報告する」に変わったため、今の条文に合わせて書き直した(正答は変わらない)。"},{"id":"2019-11","s":0,"q":"建築物衛生法に基づく事業の登録に必要な人的要件について、最も適当なものはどれか。","o":["建築物環境衛生管理技術者として特定建築物に選任されている者は、登録事業の監督者等と兼務することができる。","同一の者が2以上の営業所の登録事業の監督者等となることができる。","はじめに建築物環境衛生管理技術者の免状によって監督者となったものであっても、事業登録の更新により引き続き監督者となる場合は、6年ごとの再講習を受講する。","同一の者が同一営業所の2以上の登録事業の監督者等となることができる。","登録事業に従事するパート、アルバイトは従事者研修の対象外である。"],"a":2,"e":"免状で監督者になった人も、登録を更新して監督者を続けるには、6年ごとの再講習を受けなければならない。監督者等はほかの職務や他の営業所・他の事業と兼ねられず、パートやアルバイトも従事者研修の対象である。","l":"建築物衛生法 第12条の2、施行規則 第25条〜第30条","c":""},{"id":"2019-12","s":0,"q":"建築物衛生法に基づく事業の登録に必要な物的要件について、誤っているものはどれか。","o":["建築物空気調和用ダクト清掃業は、機械器具を適切に保管することのできる専用の保管庫が必要である。","建築物空気環境測定業は、機械器具を適切に保管することのできる専用の保管庫が必要とされていない。","建築物飲料水貯水槽清掃業は、機械器具を適切に保管することのできる専用の保管庫が必要である。","建築物ねずみ・昆虫等防除業は、機械器具及び薬剤を適切に保管することのできる専用の保管庫が必要である。","建築物環境衛生総合管理業は、機械器具を適切に保管することのできる専用の保管庫が必要とされていない。"],"a":0,"e":"専用の保管庫が必要なのは、貯水槽清掃業・排水管清掃業・ねずみ昆虫等防除業(薬剤も)である。ダクト清掃業の物的要件には、専用の保管庫は入っていない。","l":"建築物衛生法施行規則 第26条の3、第28条、第28条の3、第29条","c":""},{"id":"2019-13","s":0,"q":"建築物衛生法での都道府県知事の権限のうち、保健所を設置する市の市長と特別区の区長には与えられていないものはどれか。","o":["特定建築物の届出の受理","建築物事業登録営業所への立入検査","特定建築物所有者等に対する報告の徴収","特定建築物所有者等への改善命令","特定建築物に対する立入検査"],"a":1,"e":"事業の登録とその営業所への立入検査は、都道府県知事だけの権限である。特定建築物に関する届出の受理・報告の徴収・立入検査・改善命令は、保健所を設置する市の市長や特別区の区長も行う。","l":"建築物衛生法 第5条第1項、第12条の5","c":""},{"id":"2019-14","s":0,"q":"建築物衛生法に基づき、10万円以下の過料となるものはどれか。","o":["建築物環境衛生管理技術者を選任していない特定建築物の所有者","特定建築物の届出義務に違反した者","特定建築物の維持管理に関し環境衛生上必要な事項を記載した帳簿書類の備付け義務に違反した者","改善命令等に従わない者","正当な理由がないのに、厚生労働大臣の命令に違反して建築物環境衛生管理技術者免状を返納しなかった者"],"a":4,"e":"免状の返納命令に従わない者は、10万円以下の過料(行政上の罰)である。管理技術者の未選任、届出違反、帳簿書類の違反、改善命令違反は、30万円以下の罰金である。","l":"建築物衛生法 第16条、第18条","c":""},{"id":"2019-15","s":0,"q":"次は、ある特定建築物の飲料水の水質検査結果である。水道法第4条の水質基準を満たしていないものはどれか。","o":["一般細菌(1mLの検水で形成される集落数) ― 25個","濁度 ― 2度","pH値 ― 7.5","鉄及びその化合物 ― 3mg/L","有機物(全有機炭素(TOC)の量) ― 1mg/L"],"a":3,"e":"鉄及びその化合物の基準は0.3mg/L以下なので、3mg/Lは基準の10倍で不適合である。一般細菌は100個以下、濁度は2度以下、pHは5.8〜8.6、TOCは3mg/L以下で、ほかは基準内。","l":"水道法 第4条、水質基準に関する省令","c":""},{"id":"2019-16","s":0,"q":"下水道法について、最も不適当なものはどれか。","o":["下水道の整備を図り、もって都市の健全な発達及び公衆衛生の向上に寄与し、あわせて公共用水域の水質の保全に資することを目的とする。","厚生労働大臣は、緊急の必要があると認めるときは、公共下水道等の工事又は維持管理に関して必要な指示をすることができる。","終末処理場とは、下水を最終的に処理して河川等に放流するために、下水道の施設として設けられる処理施設及びこれを補完する施設をいう。","都道府県は、下水道の整備に関する総合的な基本計画を定めなければならない。","環境大臣は、緊急の必要があると認めるときは、終末処理場の維持管理に関して必要な指示をすることができる。"],"a":1,"e":"緊急時に公共下水道などの工事や維持管理について指示できるのは国土交通大臣で、終末処理場の維持管理については環境大臣である。厚生労働大臣は下水道法の所管ではない。","l":"下水道法 第1条、第2条、第2条の2、第37条","c":""},{"id":"2019-17","s":0,"q":"公衆浴場法について、最も不適当なものはどれか。","o":["営業者が講じなければならない入浴者の衛生及び風紀に必要な措置の基準については、厚生労働大臣が省令でこれを定める。","公衆浴場を経営しようとする者は、都道府県知事等の許可を受けなければならない。","都道府県知事等は、必要があると認めるときは、営業者その他の関係者から必要な報告を求め、又は当該職員に公衆浴場に立ち入り、検査をすることができる。","療養のために利用される公衆浴場で都道府県知事等の許可を受けた営業者は、伝染性の疾病にかかっている者と認められる者に対して、入浴を拒まなくともよい。","入浴者は、公衆浴場において、浴槽内を著しく不潔にし、その他公衆衛生に害を及ぼすおそれのある行為をしてはならない。"],"a":0,"e":"入浴者の衛生や風紀のための措置の基準は、都道府県が条例で定める(公衆浴場法第3条第2項)。厚生労働大臣の省令ではない。","l":"公衆浴場法 第2条、第3条、第4条、第5条、第6条","c":""},{"id":"2019-18","s":0,"q":"水質汚濁防止法第1条(目的)の次の条文の( )に入る語句の組合せとして、正しいものはどれか。\n「この法律は、工場及び事業場から公共用水域に排出される水の排出及び地下に浸透する水の浸透を規制するとともに、( ア )の実施を推進すること等によって、公共用水域及び地下水の水質の汚濁の防止を図り、もって( イ )とともに生活環境を保全し、並びに工場及び事業場から排出される汚水及び廃液に関して人の健康に係る被害が生じた場合における( ウ )について定めることにより、被害者の保護を図ることを目的とする。」","o":["ア 生活排水対策　イ 国民の健康を保護する　ウ 事業者の損害賠償の責任","ア 下水対策　イ 水質の基準を維持する　ウ 事業者の損害賠償の責任","ア 生活排水対策　イ 水質の基準を維持する　ウ 緊急時の措置","ア 下水対策　イ 国民の健康を保護する　ウ 緊急時の措置","ア 生活排水対策　イ 水質の基準を維持する　ウ 事業者の損害賠償の責任"],"a":0,"e":"条文どおり、ア「生活排水対策」、イ「国民の健康を保護する」、ウ「事業者の損害賠償の責任」が入る。水質汚濁防止法は、被害が出たときの事業者の無過失責任も定めている。","l":"水質汚濁防止法 第1条","c":""},{"id":"2019-19","s":0,"q":"事務所衛生基準規則で、労働者を常時就業させる室の環境について、最も不適当なものはどれか。","o":["空気調和設備を設けている場合は、室の気温が18℃以上28℃以下になるように努めなければならない。","窓その他の直接外気に向かって開放できる部分の面積が、常時床面積の20分の1以上となるようにするか、有効な換気設備を設けなければならない。","室の気温が10℃以下の場合は、暖房するなどの適当な温度調節の措置を講じなければならない。","気積は、設備の占める容積及び床面から3mを超える高さにある空間を除き、労働者1人について、8m³以上としなければならない。","室の作業面の照度は、付随的な事務作業の場合は150lx以上でなければならない。"],"a":3,"e":"気積は、設備の容積と床面から4mを超える空間を除いて、労働者1人あたり10m³以上としなければならない。3m・8m³ではない。","l":"事務所衛生基準規則 第2条〜第5条、第10条","c":"出題時の選択肢(1)は気温「17℃以上28℃以下」、選択肢(5)は「普通の作業の場合は150lx以上」だったが、2022年の事務所衛生基準規則の改正で気温の下限が18℃に、照度の区分が「一般的な事務作業300lx以上/付随的な事務作業150lx以上」に変わったため、今の基準に合わせて直した(正答は変わらない)。"},{"id":"2019-20","s":0,"q":"次の法律のうち、受動喫煙の防止を定めているものはどれか。","o":["健康増進法","有害物質を含有する家庭用品の規制に関する法律","悪臭防止法","環境基本法","美容師法"],"a":0,"e":"受動喫煙の防止は健康増進法で定められている。2018年の改正で、多くの人が利用する施設は原則屋内禁煙になった。","l":"健康増進法 第25条〜第42条","c":""},{"id":"2019-21","s":1,"q":"環境基本法で定める環境基準について、次の条文の( )に入る語句の組合せとして、正しいものはどれか。\n「政府は、大気の汚染、水質の汚濁、土壌の汚染及び( ア )に係る環境上の条件について、それぞれ、( イ )を保護し、及び( ウ )を保全する上で維持されることが望ましい基準を定めるものとする。」","o":["ア 騒音　イ 生態系　ウ 自然環境","ア 温暖化　イ 人の健康　ウ 国土","ア 騒音　イ 人の健康　ウ 生活環境","ア 海洋の汚染　イ 文化的な生活　ウ 生活環境","ア 海洋の汚染　イ 生態系　ウ 国土"],"a":2,"e":"環境基準は、大気・水質・土壌・騒音の4つについて、「人の健康を保護し、及び生活環境を保全する上で維持されることが望ましい基準」として定められる。","l":"環境基本法 第16条","c":""},{"id":"2019-22","s":1,"q":"環境衛生について、最も不適当なものはどれか。","o":["許容限界とは、生物が耐えきれなくなるストレス強度の限界のことである。","労働者の有害物質による健康障害を予防するために、許容濃度が日本産業衛生学会より勧告されている。","有害物による特定の反応においては、曝露量が増加すると陽性者の率は増加する。","集団の反応率と有害物への曝露量との関係を、量−影響関係という。","学校における環境衛生の基準は、学校保健安全法で定められている。"],"a":3,"e":"集団の中で反応が出た人の割合と曝露量との関係は「量−反応関係」という。「量−影響関係」は、一人ひとりに出る影響の大きさと曝露量との関係である。","l":"法令外","c":""},{"id":"2019-23","s":1,"q":"体温について、最も不適当なものはどれか。","o":["発汗反応は、行動性体温調節の一つの反応である。","平均皮膚温は、各部位の皮膚温をそれぞれの面積で重みづけした平均の値である。","核心温は、ホメオスタシスによって約37℃に保たれている。","体温調節は、自律性体温調節と行動性体温調節に分類される。","外気温(22〜25℃)では、手足より顔の皮膚温は高い。"],"a":0,"e":"発汗は、自分の意思とは関係なく起こる自律性体温調節の反応である。行動性体温調節は、服を着替える・冷暖房を使うなど、自分の行動で体温を調節することをいう。","l":"法令外","c":""},{"id":"2019-24","s":1,"q":"WBGT値について、最も不適当なものはどれか。","o":["熱中症予防のため、スポーツ時のガイドラインとして利用されている。","職場の暑熱基準として利用する場合、作業強度を考慮する必要がある。","作業者の熱への順化度に関わらず、作業強度に応じた基準値は同じ値である。","着用する衣服の種類に応じて補正する必要がある。","屋外で太陽照射がある場合、気温と自然湿球温度、黒球温度から求められる。"],"a":2,"e":"WBGTの基準値は、暑さに慣れている(順化している)人と慣れていない人で別の値が決められている。慣れていない人の方が低い基準値になる。","l":"法令外","c":""},{"id":"2019-25","s":1,"q":"ヒトの熱収支について、最も不適当なものはどれか。","o":["日本人(30歳代)の平均的基礎代謝量は、男子が女子よりも大きい。","日本人の基礎代謝は、冬が低く夏は高い。","着衣の保温性を表す量として、クロ値(clo)がある。","蒸発は、水分が皮膚より気化するときに潜熱で皮膚表面の熱を奪う現象である。","不感蒸泄により、皮膚表面から常に水分が蒸散している。"],"a":1,"e":"日本人の基礎代謝は、体の熱を多く作る必要がある冬に高く、夏に低い。","l":"法令外","c":""},{"id":"2019-26","s":1,"q":"高温障害の種類とその特徴の組合せとして、最も不適当なものはどれか。","o":["熱中症 ― 暑熱障害による症状の総称","熱失神 ― 血圧の上昇","熱けいれん ― 低ナトリウム血症","熱疲労 ― 脱水","熱射病 ― 中枢神経機能の異常"],"a":1,"e":"熱失神は、皮膚の血管が広がって血圧が下がり、脳への血流が減って起こる。血圧の「上昇」ではなく「低下」である。","l":"法令外","c":""},{"id":"2019-27","s":1,"q":"シックビル症候群について、最も不適当なものはどれか。","o":["そのビルに居住する人の20%以上が不快感に基づく症状を認める。","部屋の気密性が高いことは発症要因となる。","原因物質は同定されている。","学校でもみられる。","職場のストレスは、発症の危険因子となる。"],"a":2,"e":"シックビル症候群は、化学物質・換気不足・ストレスなど多くの要因が関係し、原因物質は特定(同定)されていない。","l":"法令外","c":""},{"id":"2019-28","s":1,"q":"気管支喘息について、最も不適当なものはどれか。","o":["有害な免疫反応により引き起こされる。","症状の発現には、体内の肥満細胞の働きが関係する。","アレルゲンの同定方法の一つに皮内テストがある。","原因としては、真菌が最も多い。","患者の素因は、発症・増悪因子の一つである。"],"a":3,"e":"気管支喘息の原因(アレルゲン)として最も多いのは、ダニやハウスダストである。真菌(カビ)も原因になるが、最多ではない。","l":"法令外","c":""},{"id":"2019-29","s":1,"q":"過敏性肺炎について、最も不適当なものはどれか。","o":["アレルギー性疾患である。","過敏性肺炎の一種である換気装置肺炎は、好熱性放線菌が原因となることが多い。","大部分の夏型過敏性肺炎は、真菌(トリコスポロン)により発生する。","予防には、飲料用貯水槽や空調用エアフィルタの清掃が重要である。","たばこ煙も発症の原因となる。"],"a":4,"e":"過敏性肺炎は、カビや細菌などの有機物の粉じんを繰り返し吸い込んで起こるアレルギー性の肺炎である。たばこの煙は原因とはされていない。","l":"法令外","c":""},{"id":"2019-30","s":1,"q":"室内にある汚染物質とその健康障害の組合せとして、最も不適当なものはどれか。","o":["細菌 ― 慢性閉塞性肺疾患","たばこ煙 ― 喉頭癌","ハウスダスト ― 慢性鼻炎","真菌 ― アスペルギルス症","ホルムアルデヒド ― シックハウス症候群"],"a":0,"e":"慢性閉塞性肺疾患(COPD)の主な原因は、長い間のたばこの煙の吸入である。細菌が原因の病気ではない。","l":"法令外","c":""},{"id":"2019-31","s":1,"q":"音について、最も不適当なものはどれか。","o":["マスキング量は、マスクする雑音などが存在するとき、マスクされる音の最小可聴域の音圧レベル上昇量で示される。","ヒトの聴器で聴き取ることのできる周波数帯の範囲は、約10オクターブである。","聴覚の刺激となる音には、鼓膜を通じた空気の振動による音と、骨を通じて伝わる音がある。","オージオメータを用いた聴力検査で測定されたマイナスの測定値は、聴力が基準よりも良いことを意味する。","ヒトの聴覚が最も敏感な周波数は、8,000Hz付近である。"],"a":4,"e":"ヒトの耳が最もよく聞こえる(敏感な)のは、3,000〜4,000Hz付近である。8,000Hzではない。","l":"法令外","c":""},{"id":"2019-32","s":1,"q":"光環境と視覚について、最も適当なものはどれか。","o":["網膜にある杆体細胞は、明るいときに働きやすい。","明るい場所から暗い場所への順応を暗順応といい、およそ2分程度で順応が完了する。","杆体細胞と錐体細胞を比較すると、感光度は錐体細胞の方が高い。","杆体細胞と錐体細胞を比較すると、数は錐体細胞の方が多い。","視力は、照度0.1lx付近(輝度では0.01cd/m²)で大きく変化する。"],"a":4,"e":"視力は0.1lx付近を境に大きく変わる(公式の正答)。杆体細胞は暗いときに働き、感光度も数も杆体細胞の方が上で、暗順応には40分以上かかる。","l":"法令外","c":""},{"id":"2019-35","s":1,"q":"紫外線について、最も不適当なものはどれか。","o":["波長によって、3領域に分類される。","慢性曝露で緑内障を発症する。","皮膚の老化を促進する。","ビタミンDを生成して、くる病を予防する。","赤外線と比較して皮膚透過性が低い。"],"a":1,"e":"紫外線を長く浴び続けて起こる目の病気は白内障である。緑内障は、眼圧などで視神経が傷む病気で、紫外線が原因ではない。","l":"法令外","c":""},{"id":"2019-36","s":1,"q":"放射線の健康影響のうち、晩発影響として最も不適当なものはどれか。","o":["白血病","胎児の障害","白内障","脱毛","甲状腺癌"],"a":3,"e":"脱毛は、大量に被ばくしてから数週間以内に現れる早期影響である。白血病・白内障・甲状腺癌は、年月がたってから出る晩発影響である。","l":"法令外","c":""},{"id":"2019-37","s":1,"q":"電場、磁場、電磁波について、最も不適当なものはどれか。","o":["赤外線は、電離作用を持っている。","電磁波は、波長の長短により性質が大きく異なる。","磁場の単位は、T(テスラ)又はG(ガウス)である。","家庭用電化製品、送電線等から発生する電磁場は変動磁場である。","冬場には、静電場が生じやすい。"],"a":0,"e":"赤外線は波長が長くエネルギーが小さいので、原子から電子をはじき出す電離作用はない。電離作用があるのはエックス線やγ線などである。","l":"法令外","c":""},{"id":"2019-38","s":1,"q":"ヒトと水について、最も不適当なものはどれか。","o":["一般成人における体内の水分量は、体重の約60%である。","体液のうち、細胞内液は、約2/3である。","成人の場合、1日1L以上の尿排泄が必要である。","一般に体重当たりの体内水分量は、女性より男性の方が多い。","水分の欠乏率が体重の2%になると、強い口渇を感じる。"],"a":2,"e":"体の老廃物を出すのに最低限必要な尿の量(不可避尿)は、1日0.4〜0.5L程度である。1L以上は必要ない。","l":"法令外","c":""},{"id":"2019-39","s":1,"q":"有機水銀について、最も不適当なものはどれか。","o":["生物濃縮が起こる。","水俣病はメチル水銀による。","小脳性失調を認める。","水質汚濁防止法に基づく排水基準の項目に含まれる。","慢性曝露で低分子蛋白尿を認める。"],"a":4,"e":"慢性曝露で低分子蛋白尿(腎臓の障害)が出るのは、カドミウムの特徴である。有機水銀では、手足のしびれや運動失調などの神経の症状が出る。","l":"法令外","c":""},{"id":"2019-40","s":1,"q":"環境基本法の水質汚濁に係る環境基準で、公共用水域から「検出されないこと」とされているものはどれか。","o":["カドミウム","PCB","ヒ素","ベンゼン","鉛"],"a":1,"e":"PCBは「検出されないこと」が基準である(ほかに全シアンやアルキル水銀も同じ)。カドミウム・ヒ素・ベンゼン・鉛は、数値の基準値が決められている。","l":"水質汚濁に係る環境基準について(環境庁告示)","c":""},{"id":"2019-41","s":1,"q":"感染症とその病原体の組合せとして、最も適当なものはどれか。","o":["マラリア ― 原虫","カンジダ症 ― ウイルス","A型肝炎 ― 細菌","クリプトスポリジウム症 ― 真菌","デング熱 ― 細菌"],"a":0,"e":"マラリアは原虫による。カンジダ症は真菌、A型肝炎とデング熱はウイルス、クリプトスポリジウム症は原虫による。","l":"法令外","c":""},{"id":"2019-42","s":1,"q":"次の感染症対策のうち、感染経路対策として、最も不適当なものはどれか。","o":["ネズミの駆除","手洗いの徹底","N95マスクの着用","水と空気の浄化","ワクチンの接種"],"a":4,"e":"ワクチンの接種は、人の免疫を高めて感染しにくくする「感受性対策」である。ほかは、病原体がうつる道すじを断つ感染経路対策である。","l":"法令外","c":""},{"id":"2019-43","s":1,"q":"感染症法で、建物の立入り制限が適用されることがある感染症はどれか。","o":["エボラ出血熱","コレラ","結核","デング熱","マラリア"],"a":0,"e":"建物への立入りの制限や禁止ができるのは、一類感染症の病原体に汚染された建物である。エボラ出血熱は一類感染症である。","l":"感染症法 第6条、第32条","c":""},{"id":"2019-44","s":1,"q":"消毒について、最も不適当なものはどれか。","o":["波長254nm付近の紫外線は、消毒作用がある。","消毒用エタノールは、芽胞や一部のウイルスに対して無効である。","100%エタノールの方が、70%エタノールより消毒に適している。","酸化エチレンは、ガス滅菌に用いられる。","ホルマリンは、全ての微生物に有効である。"],"a":2,"e":"エタノールは、水を少し含む70%前後の方が細菌の中に入りやすく、消毒効果が高い。100%ではすぐ蒸発するうえ効果も落ちる。","l":"法令外","c":""},{"id":"2019-45","s":1,"q":"6%次亜塩素酸ナトリウム溶液100mLを水30Lに加えたとき、次亜塩素酸ナトリウムの濃度に最も近いものはどれか。","o":["20mg/L","60mg/L","100mg/L","200mg/L","300mg/L"],"a":3,"e":"6%は60,000mg/Lなので、100mL(0.1L)には6,000mgが含まれる。6,000mg÷約30L=約200mg/Lになる。","l":"法令外","c":""},{"id":"2019-46","s":2,"q":"下の図は、外壁の断面図上に、冬期暖房時の壁内定常温度分布を示している。この図に関する次の記述のうち、最も適当なものはどれか。","o":["温度分布はAとなり、壁内結露の防止のためにイに防湿層を設けることは有効である。","温度分布はBとなり、壁内結露の防止のためにウに防湿層を設けることは有効である。","温度分布はCとなり、壁内結露の防止のためにイに防湿層を設けることは有効である。","温度分布はAとなり、壁内結露の防止のためにアに防湿層を設けることは有効である。","温度分布はCとなり、壁内結露の防止のためにウに防湿層を設けることは有効である。"],"a":4,"e":"断熱材は熱を通しにくいので、温度差の大部分は断熱材の中で生じる。木材の中では温度があまり変わらず、断熱材の中で大きく上がるCが正しい分布。防湿層は水蒸気分圧の高い室内側(ウ)に設けると、壁内結露の防止に有効である。","l":"法令外","c":"","g":["img/2019-46.png"]},{"id":"2019-47","s":2,"q":"放射に関する次の記述のうち、最も不適当なものはどれか。","o":["同一温度の物体間では、物体の放射率と吸収率は等しい。","白色プラスターの日射吸収率は、0.1程度である。","常温物体から射出される電磁波は、波長が10μm付近の赤外線が主体である。","温度が0°Cの固体表面も、熱放射している。","光ったアルミ箔の長波長放射率は、0.9程度である。"],"a":4,"e":"光ったアルミ箔は長波長(赤外線)をよく反射するので、長波長放射率は0.1以下と非常に小さい。0.9程度はコンクリートや木材など非金属の値である。","l":"法令外","c":""},{"id":"2019-48","s":2,"q":"面積8m²の外壁の熱貫流(熱通過)抵抗が2.0m²・K/Wであったとする。外気温度が−5°Cのときに室温20℃とすると、外壁を通過する熱量として、正しいものは次のうちどれか。","o":["60W","80W","100W","400W","800W"],"a":2,"e":"熱貫流率＝1÷熱貫流抵抗＝1÷2.0＝0.5W/(m²・K)。熱量＝0.5×8m²×(20－(－5))K＝100W。","l":"計算","c":""},{"id":"2019-49","s":2,"q":"熱移動に関する次の記述のうち、最も不適当なものはどれか。","o":["一般に、同一材料でも内部に水分を多く含むほど、熱伝導率は小さくなる。","一般に、密度が大きい材料ほど、熱伝導率は大きくなる。","一般に、同一材料でも熱伝導率は、温度によって異なる。","中空層の熱抵抗は、密閉の程度に関係する。","ガラス繊維などの断熱材の熱伝導率が小さいのは、繊維材によって内部の空気の流動が阻止されることによる。"],"a":0,"e":"材料が水分を含むと、水は空気より熱を伝えやすいので、熱伝導率は大きくなる。「小さくなる」は誤り。","l":"法令外","c":""},{"id":"2019-50","s":2,"q":"流体力学に関する次の記述のうち、最も不適当なものはどれか。","o":["円形ダクトの圧力損失は、ダクト長さに比例し、ダクト直径に反比例する。","動圧は、速度の2乗と流体の密度に比例する。","開口部の通過流量は、開口部の面積と流量係数に比例し、圧力差の平方根に比例する。","位置圧は、高さの2乗に比例する。","ダクトの形状変化に伴う圧力損失は、風速の2乗と形状抵抗係数に比例する。"],"a":3,"e":"位置圧(ρgh)は高さに比例する。高さの2乗に比例するのではない。","l":"法令外","c":""},{"id":"2019-51","s":2,"q":"下の図のように、風上側と風下側にそれぞれ一つの開口部を有する建築物における外部の自然風のみによる自然換気に関する次の記述のうち、最も不適当なものはどれか。","o":["換気量は、外部の自然風の風速に比例する。","換気量は、開口部①と②の風圧係数の差に比例する。","開口部①と②の両方の開口面積を2倍にすると、換気量は2倍になる。","風下側に位置する開口部②の風圧係数は、一般的に負の値となる。","流量係数は、開口部の形状に関係する。"],"a":1,"e":"風による換気量は、風速と開口部の大きさに比例し、風圧係数の差の「平方根」に比例する。差そのものに比例するのではない。","l":"法令外","c":"","g":["img/2019-51.png"]},{"id":"2019-52","s":2,"q":"下の図は、暖房時の各種吹出方式による室内気流を示したものである。暖房時に好ましい方式の室内気流の組合せとして、最も適当なものは次のうちどれか。","o":["AとC","BとD","AとD","BとC","CとD"],"a":1,"e":"暖かい空気は上にたまりやすい。暖房時は、床付近から上向きに吹き出すBや、天井から床まで届くように下向きに吹き出すDのように、暖気を下の方まで届ける方式が好ましい。","l":"法令外","c":"","g":["img/2019-52.png"]},{"id":"2019-53","s":2,"q":"平成14年に厚生労働省が公表した「分煙効果判定基準策定検討会報告書」による、分煙に関する次の文章の(ア)から(オ)の語句のうち、最も不適当なものはどれか。\n\n(ア：局所換気)により、たばこ煙中の粒子状及びガス状汚染物質の漏れ出しが隣室にないようにするため、非喫煙場所から喫煙場所方向に一定の空気の流れ(イ：0.1m/s以上)があることを判定の基準として提案している。また同時に、喫煙場所と非喫煙場所との境界においてデジタル粉じん計を用いて経時的に(ウ：浮遊粉じん濃度)の変化を測定し、漏れ状態を確認する。さらに、喫煙場所内の浮遊粉じん濃度は、(エ：0.15mg/m³以下)であること、一酸化炭素濃度が、(オ：10ppm以下)であることを確認する。","o":["(ア)","(イ)","(ウ)","(エ)","(オ)"],"a":1,"e":"報告書では、非喫煙場所から喫煙場所へ向かう気流を0.2m/s以上とすることが判定基準とされている。0.1m/sではない。","l":"法令外(平成14年 分煙効果判定基準策定検討会報告書)","c":""},{"id":"2019-54","s":2,"q":"揮発性有機化合物(VOCs)に関する次の記述のうち、最も不適当なものはどれか。","o":["VOCsとは、常温常圧で空気中に容易に揮発する有機化合物のことである。","室内の発生源として、洗剤、防臭剤、塗料、接着剤、ワックス等がある。","トルエンは、建築物衛生法により基準値が定められている。","VOCs、その物質の沸点を基準にVVOC、VOC、SVOCに分類される。","TVOC(総揮発性有機化合物)は、厚生労働省により暫定目標値が定められている。"],"a":2,"e":"建築物衛生法の空気環境の基準にある化学物質はホルムアルデヒドで、トルエンの基準はない(トルエンには厚生労働省の室内濃度指針値がある)。","l":"建築物衛生法施行令 第2条","c":""},{"id":"2019-55","s":2,"q":"ある室において、在室者数6人、在室者1人当たりのCO2発生量0.022m³/h、室内CO2許容値1,000ppm、外気CO2濃度400ppmのとき、必要換気量［m³/h］として最も近いものは次のうちどれか。ただし、室内は、定常状態で完全混合(瞬時一様拡散)とする。","o":["40m³/h","120m³/h","180m³/h","220m³/h","330m³/h"],"a":3,"e":"必要換気量＝CO2発生量÷(室内許容濃度－外気濃度)＝(6×0.022)÷(0.001－0.0004)＝0.132÷0.0006＝220m³/h。","l":"計算","c":""},{"id":"2019-56","s":2,"q":"室温20°Cの室内において、ホルムアルデヒドの質量濃度が0.08mg/m³であったとき、ホルムアルデヒドの容積比濃度として、最も近いものは次のうちどれか。\nただし、濃度換算には以下の式が用いられ、ホルムアルデヒドの分子量Mは30とする。\n\nCppm＝Cmg/m³ × 22.41/M × (273 ＋ t)/273\nCppm：容積比濃度［ppm］、M：分子量\nCmg/m³：質量濃度［mg/m³］、t：温度［°C］","o":["0.050ppm","0.065ppm","0.080ppm","0.100ppm","0.120ppm"],"a":1,"e":"0.08×22.41÷30×(273＋20)÷273＝0.08×0.747×1.073≒0.064ppmなので、最も近いのは0.065ppm。","l":"計算","c":""},{"id":"2019-57","s":2,"q":"アレルゲンと微生物に関する次の記述のうち、最も不適当なものはどれか。","o":["学校保健安全法の学校環境衛生基準には、ダニ又はダニアレルゲンの基準が含まれている。","ウイルスは、平常時の微生物汚染問題の主な原因であり、環境微生物として捉えられる。","クラドスポリウムは、アレルギー症状を引き起こす原因の一つである。","スギ花粉の除去にエアフィルタが有効である。","日本国民の約半分は、何らかのアレルギーに罹(り)患している。"],"a":1,"e":"ウイルスは生きた細胞の中でしか増えないため、建物の平常時の微生物汚染の主な原因は真菌(カビ)や細菌である。ウイルスを環境微生物として扱うのは誤り。","l":"法令外","c":""},{"id":"2019-58","s":2,"q":"エアロゾル粒子とその測定粒径との組合せとして、最も適当なものは次のうちどれか。","o":["雨滴 ― 100 μm","海岸砂 ― 10 μm","胞子 ― 1 μm","噴霧液滴 ― 0.1 μm","ウイルス ― 0.01 μm"],"a":4,"e":"ウイルスはおよそ0.01〜0.1μmで、組合せとして適当。雨滴は約1mm(1,000μm)、海岸砂は100μm以上、胞子は数μm〜数十μm、噴霧液滴は数十μm程度で、どれも桁がずれている。","l":"法令外","c":""},{"id":"2019-59","s":2,"q":"次の空調熱負荷のうち、室内負荷の構成要素に分類されないものはどれか。","o":["ガラス窓透過日射熱負荷","透湿熱負荷","外気負荷","間欠空調における蓄熱負荷","隙間風熱負荷"],"a":2,"e":"外気負荷は、取り入れた外気を室内の状態まで冷やしたり温めたりするための負荷で、空調機(装置)で処理する装置負荷に分類される。室内負荷ではない。","l":"法令外","c":""},{"id":"2019-60","s":2,"q":"空気Aと空気Bを2：1に混合した後の比エンタルピーと絶対湿度の組合せとして、最も適当なものは次のうちどれか。\n空気A:比エンタルピー 50kJ/kg(DA)、絶対湿度 0.010kg/kg(DA)\n空気B:比エンタルピー 68kJ/kg(DA)、絶対湿度 0.016kg/kg(DA)","o":["比エンタルピー 56kJ/kg(DA)、絶対湿度 0.012kg/kg(DA)","比エンタルピー 62kJ/kg(DA)、絶対湿度 0.012kg/kg(DA)","比エンタルピー 56kJ/kg(DA)、絶対湿度 0.014kg/kg(DA)","比エンタルピー 62kJ/kg(DA)、絶対湿度 0.014kg/kg(DA)","比エンタルピー 59kJ/kg(DA)、絶対湿度 0.013kg/kg(DA)"],"a":0,"e":"混合後の値は量の比で平均する。比エンタルピー＝(50×2＋68×1)÷3＝56、絶対湿度＝(0.010×2＋0.016×1)÷3＝0.012。","l":"計算","c":""},{"id":"2019-61","s":2,"q":"湿り空気の状態変化に関する次の記述のうち、最も不適当なものはどれか。","o":["湿り空気を加熱すると、相対湿度は低下する。","湿り空気を加熱すると、露点温度は低下する。","湿り空気を冷却すると、比エンタルピーは低下する。","湿り空気を冷却すると、比容積は小さくなる。","湿り空気を減湿すると、湿球温度は低下する。"],"a":1,"e":"加熱しても空気中の水蒸気の量(絶対湿度)は変わらないので、露点温度も変わらない。「低下する」は誤り。","l":"法令外","c":""},{"id":"2019-62","s":2,"q":"熱源方式に関する次の記述のうち、最も不適当なものはどれか。","o":["電動冷凍機＋ボイラ方式は、冷熱源として電動機駆動の冷凍機と、温熱源としてボイラを用いたものである。","吸着冷凍機は、比較的高温度の温水を加熱源としており、高い成績係数を得ることが可能である。","ヒートポンプ方式には、ガスエンジン駆動のヒートポンプがあり、エンジン排熱を暖房熱源に利用することが可能である。","吸収冷凍機＋蒸気ボイラ方式は、年間を通じてガス又は油が使用され、冷熱源は冷水、温熱源は蒸気である。","コージェネレーション方式では、高いエネルギー利用効率を得るために、燃焼排熱の有効活用が重要である。"],"a":1,"e":"吸着冷凍機は、50〜90℃程度の比較的低い温度の温水でも動かせるのが特徴だが、成績係数(効率)は低い。「高温度の温水」「高い成績係数」は誤り。","l":"法令外","c":""},{"id":"2019-63","s":2,"q":"空気調和方式に関する次の記述のうち、最も不適当なものはどれか。","o":["全空気方式では、熱負荷を処理するための熱媒として空気のみを用いるため、比較的大型の空気調和機が必要である。","外調機併用ターミナルエアハンドリングユニット方式は、ダクト併用ファンコイルユニット方式に比べ、高品位な空調空間が達成されやすい。","定風量単一ダクト方式では、室内空気質の維持に必要な新鮮外気量の確保が難しい。","デシカント空調方式は、潜熱・顕熱を分離して制御できる空調システムである。","分散設置空気熱源ヒートポンプ方式は、圧縮機のインバータによる比例制御が可能な機種が主流である。"],"a":2,"e":"定風量単一ダクト方式は、いつも一定の風量を送るので、必要な外気量を確保しやすい。外気量の確保が難しくなりやすいのは、風量を絞る変風量方式の方である。","l":"法令外","c":""},{"id":"2019-64","s":2,"q":"吸収冷凍機の構成機器として、最も不適当なものは次のうちどれか。","o":["凝縮器","蒸発器","吸収器","再生器","膨張弁"],"a":4,"e":"膨張弁は蒸気圧縮式冷凍機の部品。吸収冷凍機は、蒸発器・吸収器・再生器・凝縮器で構成される。","l":"法令外","c":""},{"id":"2019-65","s":2,"q":"蒸気圧縮式冷凍機における圧縮機の種類と特徴に関する次の記述のうち、最も不適当なものはどれか。","o":["往復動圧縮機は、シリンダ内のピストンを往復運動することで、冷媒ガスを圧縮する。","スクロール圧縮機は、渦巻き状の固定スクロールと渦巻き状の旋回スクロールの旋回により、冷媒を圧縮する。","スクリュー圧縮機を用いた冷凍機は、スクロール圧縮機を用いたものよりも冷凍容量の大きな範囲で使用される。","自然冷媒(アンモニア、CO2等)を使用する機種では、通常の冷媒を使用する場合よりも低い圧縮比で使用される。","遠心圧縮機を用いた冷凍機は、羽根車の高速回転が可能であり、大容量としてもコンパクトな機種とすることができる。"],"a":3,"e":"アンモニアやCO2などの自然冷媒を使う機種は、通常の冷媒より高い圧力・高い圧縮比で使われる。「低い圧縮比」は誤り。","l":"法令外","c":""},{"id":"2019-66","s":2,"q":"冷凍機に用いられる冷媒とオゾン破壊係数(ODP)との組合せとして、最も不適当なものは次のうちどれか。","o":["R11(CFC) ― ODP 1","R22(HCFC) ― ODP 0.055","R32(HFC) ― ODP 0.02","R717(NH3) ― ODP 0","R744(CO2) ― ODP 0"],"a":2,"e":"HFC冷媒は塩素を含まないので、オゾン破壊係数は0である。R32のODPを0.02とするのは誤り。","l":"法令外","c":""},{"id":"2019-67","s":2,"q":"空気調和機の構成要素の上流側からの設置順として、最も適当なものは次のうちどれか。","o":["加熱コイル ― 冷却コイル ― 加湿器","冷却コイル ― 加湿器 ― 加熱コイル","冷却コイル ― 加熱コイル ― 加湿器","加湿器 ― 冷却コイル ― 加熱コイル","加熱コイル ― 加湿器 ― 冷却コイル"],"a":2,"e":"空気は、まず冷却コイルで冷やして除湿し、次に加熱コイルで温め、最後に加湿器で湿度を加える順に通る。温めた空気の方が水分を吸収しやすいので、加湿器は加熱コイルの後に置く。","l":"法令外","c":""},{"id":"2019-68","s":2,"q":"全熱交換器に関する次の記述のうち、最も不適当なものはどれか。","o":["回転型は、静止型よりも目詰まりを起こしやすい。","回転型は、ロータの回転に伴って排気の一部が給気側に移行することがある。","外気負荷の軽減を目的として、空気中の顕熱・潜熱を同時に熱交換する装置である。","静止型の給排気を隔てる仕切り板は、伝熱性と透湿性をもつ材料である。","冬期・夏期のいずれも省エネルギー効果が期待できるが、中間期の運転には注意が必要である。"],"a":0,"e":"目詰まりを起こしやすいのは、細かい通路が固定されている静止型の方である。回転型は回転によって汚れがたまりにくい。","l":"法令外","c":""},{"id":"2019-69","s":2,"q":"加湿装置の方式に関する次の記述のうち、最も不適当なものはどれか。","o":["気化方式は、吹出し空気の温度が降下する。","気化方式は、結露する可能性が低い。","水噴霧方式は、給水中の不純物を放出しない。","水噴霧方式は、吹出し空気の温度が降下する。","蒸気方式は、吹出し空気の温度が降下しない。"],"a":2,"e":"水噴霧方式は水をそのまま霧にして飛ばすので、水に含まれる不純物(カルシウムなど)も室内に放出される。「放出しない」は誤り。","l":"法令外","c":""},{"id":"2019-70","s":2,"q":"ダクト及びその付属品に関する次の記述のうち、最も不適当なものはどれか。","o":["低圧ダクトの流速範囲は、15m/s以下である。","厨(ちゅう)房フードなどには、ステンレス鋼板が利用される。","グラスウールダクトには、ダクト系の騒音に対する消音効果が期待できる。","防火ダンパの羽根及びケーシングは、一般に1.5mm以上の鋼板で作成される。","厨房排気ダクト用防火ダンパの温度ヒューズ溶解温度は、280℃である。"],"a":4,"e":"厨房排気ダクトの防火ダンパの温度ヒューズは120℃で溶けるものを使う。280℃は排煙ダクト用の値である。","l":"法令外","c":""},{"id":"2019-71","s":2,"q":"送風機に関する次の記述のうち、最も不適当なものはどれか。","o":["斜流式送風機は、空気が羽根車の外周の一部から入り、反対側の外周の一部に通り抜ける。","遠心式送風機は、空気が羽根車の中を軸方向から入り、径方向に通り抜ける。","軸流送風機は、空気が羽根車の中を軸方向から入り、軸方向に通り抜ける。","送風機系の抵抗曲線は、風量に関する2次曲線で表される。","送風機の特性について、グラフ上の横軸に風量をとり、縦軸に各風量における圧力・効率・軸動力等をとって表したものを送風機の特性曲線という。"],"a":0,"e":"羽根車の外周の一部から入って反対側の外周から出るのは、横流送風機の説明。斜流送風機は、軸方向から入って斜め方向に出る、遠心式と軸流式の中間の形である。","l":"法令外","c":""},{"id":"2019-72","s":2,"q":"ダクトとその付属品に関する次の記述のうち、最も不適当なものはどれか。","o":["ピッツバーグはぜは、鋼板ダクトの組立てに用いられる。","鋼板製長方形ダクト同士を接合する継手には、アングルフランジ工法継手がある。","耐食性を必要とするダクトには、ステンレス鋼板が用いられる。","風量調整ダンパには、バタフライ型がある。","丸ダクトはスパイラルダクトに比べて、はぜにより高い強度が得られる。"],"a":4,"e":"強度が高いのは、らせん状のはぜ(継ぎ目)で巻いて作るスパイラルダクトの方である。","l":"法令外","c":""},{"id":"2019-73","s":2,"q":"空気浄化装置に関する次の記述のうち、最も不適当なものはどれか。","o":["静電式は、高圧電界により粉じんを荷電し、吸引吸着することによって捕集・除去するもので、電気集じん機が代表的な装置である。","ろ過式は、慣性、拡散、さえぎりなどの作用で粉じんをろ材繊維に捕集するものをいう。","HEPAフィルタやULPAフィルタは、圧力損失が大きい傾向にある。","ろ過式は各種フィルタがあるが、粒子捕集率の値の範囲は狭い。","空気浄化装置は、排気系統に設置される場合もある。"],"a":3,"e":"ろ過式フィルタには、粗じん用から HEPA・ULPA のような超高性能のものまであり、粒子捕集率の値の範囲は広い。","l":"法令外","c":""},{"id":"2019-74","s":2,"q":"空気調和設備の配管・ポンプに関する語句の組合せとして、最も不適当なものは次のうちどれか。","o":["伸縮継手 ― 振動防止対策","容積型ポンプ ― 歯車ポンプ","ポンプの特性曲線 ― 全揚程","蒸気トラップ ― 凝縮水の分離","キャビテーション ― 吐出量の低下、揚水不能"],"a":0,"e":"伸縮継手は、配管が温度で伸び縮みするのを吸収するための部品で、振動防止の部品ではない。振動防止には防振継手を使う。","l":"法令外","c":""},{"id":"2019-75","s":2,"q":"換気に関する次の記述のうち、最も不適当なものはどれか。","o":["局所換気は、汚染物質を発生源の近くで捕集するため捕集効率が高く、換気量も比較的少ない。","温度差による換気力は、室内外の空気の密度差に比例する。","住宅等の居室のシックハウス対策として機械換気設備を用いる場合の必要換気量は、換気回数で0.5回/h以上と規定されている。","第2種機械換気方式は、給気口及び排風機により構成される。","ハイブリッド換気は、自然換気に機械換気や空調設備を組み合わせたものである。"],"a":3,"e":"第2種機械換気は、送風機で給気し、排気は排気口から自然に出す方式。給気口と排風機の組合せは第3種機械換気である。","l":"法令外","c":""},{"id":"2019-76","s":2,"q":"個別方式空気調和設備で使用する換気設備に関する次の記述のうち、最も不適当なものはどれか。","o":["パッケージ型空調機は、通常は外気処理機能を持たないため、室内空気質確保のための対策が必要である。","中央方式の外調機の導入が困難な場合には、室単位もしくはゾーン単位の外気導入が一般的である。","暖房時に加湿不足になりやすいことから、加湿器を付加するなどの対策が取られることもある。","外気処理ユニットは、直膨コイルや全熱交換器等を組み込んだユニットである。","外気処理専用パッケージ型空調機は、給排気のバランスが取りにくい。"],"a":4,"e":"外気処理専用のパッケージ型空調機は、取り入れる外気量を決めて計画できる機器で、給排気のバランスがとりにくいわけではない(公式正答)。","l":"法令外","c":""},{"id":"2019-77","s":2,"q":"温熱環境要素の測定器に関する次の記述のうち、最も不適当なものはどれか。","o":["熱式風速計は、長時間使用していると指示値に誤差が生じることがあるので、定期的に較正する必要がある。","サーミスタ温度計は、電気抵抗の変化を利用するものである。","アスマン通風乾湿計の乾球温度は、一般に湿球温度より高い値を示す。","グローブ温度計は、気流変動の大きいところでの測定に適している。","相対湿度の測定には、毛髪などの伸縮を利用する方法がある。"],"a":3,"e":"グローブ温度計は熱をためてから安定するまでに時間がかかる(15〜20分程度)ため、気流が変わりやすい場所の測定には向かない。","l":"法令外","c":""},{"id":"2019-78","s":2,"q":"空気環境の測定に関する次の記述のうち、最も不適当なものはどれか。","o":["酸素の測定には、紫外線吸収法がある。","微生物の測定には、免疫クロマトグラフ法がある。","イオウ酸化物の測定には、溶液導電率法がある。","オゾンの測定には、半導体法がある。","花粉アレルゲンの測定には、エアロアレルゲン・イムノブロット法がある。"],"a":0,"e":"酸素の測定には、ガルバニ電池方式やポーラログラフ方式が使われる。紫外線吸収法はオゾンの測定法である。","l":"法令外","c":""},{"id":"2019-79","s":2,"q":"汚染物質とその単位の組合せとして、最も不適当なものは次のうちどれか。","o":["キシレン濃度 ― μg/m³","浮遊細菌濃度 ― CFU/m³","オゾン濃度 ― Sv","アスベスト濃度 ― 本/L","イオウ酸化物濃度 ― ppm"],"a":2,"e":"Sv(シーベルト)は放射線の人体への影響を表す単位。オゾン濃度はppmなどで表す。","l":"法令外","c":""},{"id":"2019-80","s":2,"q":"ホルムアルデヒド測定法として、最も不適当なものは次のうちどれか。","o":["DNPHカートリッジ捕集 − HPLC法","検知管法","定電位電解法","電気化学的燃料電池法","光散乱法"],"a":4,"e":"光散乱法は浮遊粉じんの測定法で、ホルムアルデヒドの測定には使わない。","l":"法令外","c":""},{"id":"2019-81","s":2,"q":"揮発性有機化合物(VOCs)定法に関する次の記述のうち、最も不適当なものはどれか。","o":["固相捕集・加熱脱着−GC/MS法は、空気中のVOCsを捕集した吸着剤を加熱脱着装置によりGC/MSへ導入する方法である。","固相捕集・溶媒抽出−GC/MS法は、空気中のVOCsを捕集した吸着剤を二硫化炭素で抽出した後、GC/MSへ導入する方法である。","TVOC(Total VOC)の測定には、パッシブ法を使用することができる。","トルエン、パラジクロロベンゼンは、検知管法により測定することができる。","半導体センサを用いたモニタ装置により、トルエン、キシレンを測定することができる。"],"a":2,"e":"TVOCは、ポンプで空気を吸って捕集するアクティブ法と加熱脱着GC/MSなどで測る。パッシブ法ではTVOCは測定できない。","l":"法令外","c":""},{"id":"2019-82","s":2,"q":"建築物環境衛生管理基準に基づく空気調和設備に関する衛生上必要な措置に関する次の記述のうち、最も不適当なものはどれか。","o":["冷却塔及び冷却水の水管は、6カ月以内ごとに1回、定期に清掃を行うことが求められる。","冷却塔及び冷却水は、使用開始時及び使用期間中の1カ月以内ごとに1回、定期に汚れの状況を点検することが求められる。","冷却塔に供給する水は、水道法第4条に規定する水質基準に適合していることが求められる。","加湿装置は、使用開始時及び使用を開始した後、1カ月以内ごとに1回、定期に汚れの状況を点検することが求められる。","空気調和設備内に設けられた排水受けは、使用開始時及び使用期間中の1ヵ月以内ごとに1回、定期に汚れの状況を点検することが求められる。"],"a":0,"e":"冷却塔・冷却水の水管・加湿装置の清掃は、1年以内ごとに1回行うと定められている(施行規則第3条の18)。6か月以内ごとではない。","l":"建築物衛生法施行規則 第3条の18","c":""},{"id":"2019-83","s":2,"q":"遮音に関する次の記述のうち、最も不適当なものはどれか。","o":["床衝撃音に対する遮音等級は、値が小さいほど遮音性能が優れている。","複層壁の場合、共鳴によって音が透過することがある。","軽量床衝撃音は、床仕上げ材を柔らかくすることで軽減できる。","複数の断面仕様の異なる部材で構成される壁の透過損失は、最も透過損失の大きい構成部材の値を用いる。","重量床衝撃音は、床躯(く)体構造の質量や曲げ剛性を増加させることで軽減できる。"],"a":3,"e":"いくつかの部材でできた壁は、透過損失の小さい(音を通しやすい)部分の影響を強く受ける。最も大きい値を用いるのは誤り。","l":"法令外","c":""},{"id":"2019-84","s":2,"q":"振動に関する次の記述のうち、最も不適当なものはどれか。","o":["空気調和機による振動は、定常的で変動が小さい。","風による建物の振動は、不規則である。","環境振動で対象とする周波数の範囲は、鉛直方向の場合、1〜80Hzである。","不規則かつ大幅に変動する振動のレベルは、時間率レベルで表示する。","防振溝は、溝が深いほど、また、溝が振動源に近いほど効果が大きい。"],"a":1,"e":"風で揺れる建物は、建物の固有振動数に近い周期で揺れるため、振動はおおむね規則的になる。「不規則」は誤り(公式正答)。","l":"法令外","c":""},{"id":"2019-85","s":2,"q":"面音源からの音圧レベルの伝搬特性に関する次の文章の(　　　)内に入る語句の組合せとして、最も適当なものはどれか。\n\n「下の図に示す寸法 a×b(a＜b)の長方形の面音源について、面音源中心から面に対して垂直方向への距離をdとした場合、音源付近 d ＜ ( a/π )では( ア )としての伝搬特性を示し、( a/π )＜ d ＜ ( b/π )では線音源に対応する減衰特性を、d ＞ ( b/π )の範囲では( イ )に対応する減衰特性を示す。よって、d ＞ ( b/π )の範囲で音源からの距離が2倍になると( ウ )dB減衰する。」","o":["ア:点音源、イ:面音源、ウ:3","ア:点音源、イ:面音源、ウ:6","ア:面音源、イ:点音源、ウ:3","ア:面音源、イ:点音源、ウ:6","ア:面音源、イ:点音源、ウ:10"],"a":3,"e":"面音源のすぐ近くでは面音源として距離で減衰しにくく、十分離れると点音源と同じように減衰する。点音源では距離が2倍になると約6dB下がる。","l":"法令外","c":"","g":["img/2019-85.png"]},{"id":"2019-86","s":2,"q":"測光量に関する次の文章の(　　　)内に入る語句の組合せとして、最も適当なものはどれか。\n\n「照度は( ア )当たりに入射する光束であり、単位は通常( イ )と表される。光度は( ウ )当たりから放出される光束であり、単位は通常( エ )と表される。」","o":["ア:単位面積、イ:lx、ウ:単位立体角、エ:cd/m²","ア:単位面積、イ:lx、ウ:単位立体角、エ:cd","ア:単位面積、イ:lm、ウ:単位立体角、エ:cd","ア:単位立体角、イ:cd、ウ:単位面積、エ:cd/m²","ア:単位立体角、イ:lm、ウ:単位面積、エ:cd"],"a":1,"e":"照度は単位面積あたりに入る光束で単位はlx(ルクス)。光度は単位立体角あたりに出る光束で単位はcd(カンデラ)。cd/m²は輝度の単位である。","l":"法令外","c":""},{"id":"2019-87","s":2,"q":"光・照明に関する次の記述のうち、最も不適当なものはどれか。","o":["太陽高度が等しければ、大気透過率が高いほど地表に到達する直射日光による水平面照度は大きくなる。","演色評価数は、100に近いほど基準光で照らした場合の色に近い色に再現できる。","室内表面の輝度分布が大きすぎると視覚的疲労感を生じる。","電球色の蛍光ランプと昼白色の蛍光ランプとでは、昼白色の方が相関色温度が高い。","同じ面積の窓から天空光を取り入れる場合、側窓と天窓とで取り入れられる光の量は等しい。"],"a":4,"e":"天窓は側窓より空の広い範囲が見えるので、同じ面積なら約3倍の光が入る。光の量は等しくない。","l":"法令外","c":""},{"id":"2019-88","s":2,"q":"地表における直射日光による法線面照度が80,000 lxのとき、直射日光による水平面照度として、最も近いものは次のうちどれか。ただし、このときの太陽高度は60度とする。","o":["35,000 lx","40,000 lx","55,000 lx","70,000 lx","80,000 lx"],"a":3,"e":"水平面照度＝法線面照度×sin(太陽高度)＝80,000×sin60°＝80,000×0.866≒69,000lxなので、最も近いのは70,000lx。","l":"計算","c":""},{"id":"2019-89","s":2,"q":"照明施設の保守に関する次の記述のうち、最も不適当なものはどれか。","o":["照明器具の保守率は、照明施設の管理状況によらず、光源、照明器具の性能のみで決まる。","LED照明器具の場合、周辺環境の清浄度が同じであれば、露出形と完全密閉形の設計光束維持率は同等である。","既設の蛍光ランプ用照明器具のランプを直管ランプで代替する場合、適切なランプと照明器具の組合せでないと、照明器具の焼損や火災を招くおそれがある。","光源の交換と清掃の時期を合理的に組み合わせることが、所要照度の維持にとって望ましい。","JIS8105−1によれば、照明器具の適正交換の目安は、累積点灯時間30,000時間としている。"],"a":0,"e":"保守率は、光源や器具の性能だけでなく、周囲の汚れ具合や清掃・ランプ交換の頻度など、管理の状況でも変わる。","l":"法令外","c":""},{"id":"2019-90","s":2,"q":"空気調和設備に関する次の記述のうち、最も適当なものはどれか。","o":["ふく流吹出口は、他の吹出口と比べて、均一度の高い温度分布が得やすい。","吸収冷凍機は、容積冷凍機や遠心冷凍機と比較して騒音・振動が大きい。","躯(く)体蓄熱方式を採用すると、一般に熱源機器容量は大きくなる。","放射冷暖房設備は、他の空調方式と併用せず設置するのが一般的である。","吸込み気流は、吸込み中心からの距離に反比例して減衰する。"],"a":0,"e":"ふく流吹出口(アネモ型など)は、周囲に放射状に広く吹き出すので、温度分布が均一になりやすい。2は逆(吸収冷凍機は静か)、3は熱源容量を小さくできる、5は距離の2乗に反比例する。","l":"法令外","c":""},{"id":"2019-91","s":3,"q":"都市の熱環境について、最も不適当なものはどれか。","o":["COP21において、温室効果ガス削減の枠組みとなるパリ協定が採択された。","CASBEE(建築環境総合性能評価システム)の評価対象は、エネルギー消費、資源循環、地域環境、室内環境の4分野である。","熱帯夜とは、夕方から翌朝までの最低気温が25℃以上の日をいう。","ストリートキャニオンは、風の弱い日にも熱や汚染物質の拡散能力が高い。","都市化により、都市の中心部の気温が郊外と比較して高くなる現象をヒートアイランド現象という。"],"a":3,"e":"ストリートキャニオンは、高い建物に挟まれた谷のような道路空間で、風が通りにくい。そのため熱や汚染物質がたまりやすく、拡散する力は低い。","l":"法令外","c":""},{"id":"2019-92","s":3,"q":"日射・日照について、最も不適当なものはどれか。","o":["太陽から放射される可視光線、紫外線、近赤外線のうち、紫外線の波長が最も短い。","遮熱性塗料や遮熱性舗装の特徴は、近赤外線の反射率が大きいことである。","天空日射とは、太陽光が大気中で散乱して、地上に降りそそいだものである。","夏至の晴天日において、南向き鉛直壁面の日積算日射受熱量は、札幌の方が那覇より多い。","日影曲線とは、冬至の日において、地面に垂直な単位長さの棒が水平面に落とす影を時間別に描いたものである。"],"a":4,"e":"日影曲線は、冬至の日に限らず、ある緯度の地点で、季節(日)ごとに垂直な棒の影の先端が描く線を時刻別に示した図である。","l":"法令外","c":""},{"id":"2019-93","s":3,"q":"日射・日照とその調整の方法について、最も不適当なものはどれか。","o":["樹木の緑葉の日射反射率は、コンクリートに比べて大きい。","ライトシェルフとは、部屋の奥まで光を導くよう直射日光を反射させる庇である。","オーニングとは、窓に取り付ける日除けの一種である。","照返しの熱量は、照返し面での日射反射量と、その面での熱放射量とに分けられる。","内付けブラインドの日射遮蔽効果は、外付けブラインドに比べて小さい。"],"a":0,"e":"樹木の緑葉は日射の多くを吸収して蒸散に使うので、日射反射率はコンクリートより小さい。","l":"法令外","c":""},{"id":"2019-94","s":3,"q":"建築士法で定義している設計図書に含まれないものはどれか。","o":["建具表","仕上表","配置図","面積表","現寸図"],"a":4,"e":"建築士法の設計図書は、工事に必要な図面(現寸図などは除く)と仕様書である。現寸図は、施工のために実物大で描く図なので含まれない。","l":"建築士法 第2条第6項","c":""},{"id":"2019-95","s":3,"q":"建築物の基礎構造と地盤について、最も不適当なものはどれか。","o":["異種の基礎構法の併用は、原則として禁止されている。","沖積層の地耐力は、第三紀層に比べて大きい。","液状化は、埋立地や砂質地盤などで生じやすい。","フーチングは、柱又は壁を支える鉄筋コンクリートの基礎の広がり部分をいう。","地盤の短期に生ずる力に対する許容応力度は、長期に生ずる力に対する許容応力度の2倍とする。"],"a":1,"e":"沖積層は新しくやわらかい地層なので、古く締め固まった第三紀層より地耐力が小さい。","l":"建築基準法施行令 第38条、第93条","c":""},{"id":"2019-96","s":3,"q":"建築物の荷重と構造力学について、最も不適当なものはどれか。","o":["床の構造計算をする場合の積載荷重は、地震力を計算する場合の積載荷重より大きく設定されている。","土圧や水圧は、常時荷重に分類されている。","反力は、建築物に荷重が作用した場合、作用荷重に対応して支点に生じる力である。","せん断力は、部材内の任意の面に作用して、面をずれさせるように作用する力である。","等分布荷重の作用する片持支持梁のせん断力は、梁中央で最も大きい。"],"a":4,"e":"等分布荷重がかかる片持ち梁のせん断力は、固定端(根元)で最も大きく、先端に向かって小さくなる。","l":"建築基準法施行令 第85条","c":""},{"id":"2019-97","s":3,"q":"建築材料の密度が、大きい順に並んでいるものはどれか。","o":["鋼材 > コンクリート > アルミニウム > 合板","鋼材 > アルミニウム > コンクリート > 合板","コンクリート > 鋼材 > アルミニウム > 合板","コンクリート > アルミニウム > 鋼材 > 合板","コンクリート > 鋼材 > 合板 > アルミニウム"],"a":1,"e":"密度はおよそ、鋼材7.85、アルミニウム2.7、コンクリート2.3、合板0.5〜0.6(g/cm³)なので、この順になる。","l":"法令外","c":""},{"id":"2019-98","s":3,"q":"建築材料の性質について、最も不適当なものはどれか。","o":["木材の気乾状態の含水率は、25〜30%である。","木材の引火点は、240〜270℃程度である。","高強度鋼は、軟鋼より伸びが小さい。","鋼材のヤング係数は、鋼材の種類にかかわらずほぼ一定である。","強化ガラスは、一般板ガラスに特殊な熱処理を施し、表面に圧縮応力を生じさせたものである。"],"a":0,"e":"気乾状態(空気中で乾いた状態)の木材の含水率は、15%前後である。25〜30%は繊維飽和点にあたる。","l":"法令外","c":""},{"id":"2019-99","s":3,"q":"ガスの供給と取扱いについて、最も適当なものはどれか。","o":["厨房がガス臭いので、ガスを排出するため直ちに換気扇を起動した。","都市ガス及びLPガスは、1,000倍に希釈しても臭いを感知できる付臭剤の添加が、法令で義務付けられている。","地震後、ガスのマイコンメータの復帰ボタンを押したら赤いランプが点滅したが、ガス機器に異常がなさそうなので使用開始した。","土中から建築物にガス管を引き込む際、耐震のため絶縁継手を設置することが必要である。","LPガス容器は、常時50℃以下の直射日光の当たらない場所に設置する。"],"a":1,"e":"都市ガスもLPガスも、空気中に1,000分の1混ざっただけで気づけるにおいを付けることが法令で決められている。換気扇のスイッチは火花で引火するおそれがあり、LPガス容器は40℃以下に保つ。","l":"ガス事業法施行規則、液化石油ガス保安規則","c":""},{"id":"2019-100","s":3,"q":"電気設備について、最も不適当なものはどれか。","o":["「非常用の照明装置」は、停電を伴った災害発生時に安全に避難するための設備で、消防法により設置場所・構造が定められている。","インバータ制御は、交流電動機の回転速度調整や出力トルク調整が容易で、効率の大幅改善が期待できる。","電動機は、起動時に定格を超える電流が流れ異常振動等を起こすことがあるため、スターデルタ起動方式により運転するのが望ましい。","契約電力50kW以上の建築物の場合、高圧(6.6kV)で受電し、自家用変電設備で低圧(200V・100V)に変圧して給電する。","地階を除く階数が、11階以上の階に、非常コンセント設備の設置が義務付けられている。"],"a":0,"e":"非常用の照明装置は、消防法ではなく建築基準法(施行令第126条の4・第126条の5)で設置場所や構造が決められている。","l":"建築基準法施行令 第126条の4、第126条の5、消防法施行令 第29条の2","c":""},{"id":"2019-101","s":3,"q":"建築物の防災対策などについて、最も不適当なものはどれか。","o":["高層ビルの回転式の扉は、内外気温差で生じる出入口での強風を減じる効果がある。","超高層ビルの足元にあるサンクンガーデンは、ビル風対策としても効果がある。","Jアラートは、緊急の気象関係情報、有事関係情報を国から住民等に伝達するシステムである。","エレベータには、地震時に直ちに避難階へ直行させる地震管制モードが備わっている。","集中豪雨時に浸水しやすい地下街、地下階への浸水対策として、止水板、土嚢が用いられる。"],"a":3,"e":"エレベータの地震時管制運転は、揺れを感じたら最寄りの階に止めて扉を開き、乗っている人を降ろす仕組みである。避難階へ直行させるのではない。","l":"法令外","c":""},{"id":"2019-102","s":3,"q":"建築物の消防用設備について、最も適当なものはどれか。","o":["煙感知器は、熱感知器に比べ火災の検知が早く、アトリウムや大型ドームのような大空間での火災感知に適している。","差動式熱感知器は、定められた温度を一定時間以上超え続けた場合に作動する。","小規模社会福祉施設では、上水道の給水管に連結したスプリンクラ設備の使用が認められている。","ハロゲン化物消火設備は、負触媒作用による優れた消火効果があり、コンピュータルーム、図書館など水損被害が懸念される用途の空間で普及している。","排煙設備は、消防法施行令に定めるところの消防の用に供する設備に含まれる。"],"a":2,"e":"小規模な社会福祉施設などでは、水道の給水管につないだ「特定施設水道連結型スプリンクラー設備」が認められている。大空間では煙が薄まるため煙感知器は向かず、差動式は温度の上がり方で作動し、排煙設備は消火活動上必要な施設である。","l":"消防法施行令 第7条、第12条","c":""},{"id":"2019-103","s":3,"q":"建築基準法について、誤っているものはどれか。","o":["建築物とは、土地に定着する工作物であることが前提である。","鉄道及び軌道の線路敷地内の運転保安に関する施設は、建築物から除かれる。","建築物の構造上重要でない間仕切壁の過半の模様替えは、大規模の模様替えである。","敷地とは、一の建築物又は用途上不可分の関係にある二以上の建築物のある一団の土地である。","集団規定による建築物の制限として、用途地域による建築物の用途制限がある。"],"a":2,"e":"大規模の模様替は、主要構造部の一種以上について行う過半の模様替である。構造上重要でない間仕切壁は主要構造部に入らないので、大規模の模様替にならない。","l":"建築基準法 第2条第1号・第5号・第15号、施行令 第1条第1号","c":""},{"id":"2019-104","s":3,"q":"建築基準法に定める建築設備に該当しないものはどれか。","o":["汚物処理の設備","煙突","共同アンテナ","昇降機","避雷針"],"a":2,"e":"建築設備は、電気・ガス・給水・排水・換気・暖房・冷房・消火・排煙・汚物処理の設備と、煙突・昇降機・避雷針である。共同アンテナは含まれない。","l":"建築基準法 第2条第3号","c":""},{"id":"2019-105","s":3,"q":"建築基準法について、誤っているものはどれか。","o":["劇場における客席からの出口の戸は、内開きとしてはならない。","床面積とは、建築物の各階又はその一部で、壁その他の区画の中心線で囲まれた部分の水平投影面積である。","耐火性能とは、通常の火災が終了するまでの間、建築物の倒壊・延焼を防止するために、建築物の部分に必要な性能のことをいう。","建築主事は、建築基準法の規定に違反した建築物に関する工事の請負人に対して、当該工事の施工の停止を命じることができる。","直通階段とは、建築物の避難階以外の階の居室から、避難階又は地上に直通する階段のことをいう。"],"a":3,"e":"違反建築物の工事の請負人などに工事の施工の停止を命じられるのは、特定行政庁(と建築監視員)である。建築主事は確認や検査を行う立場で、この命令の権限はない。","l":"建築基準法 第2条第7号、第9条、施行令 第2条第1項第3号、第118条","c":""},{"id":"2019-106","s":4,"q":"給水及び排水の管理に関する用語とその単位との組合せとして、最も不適当なものはどれか。","o":["給湯配管からの熱損失 ― W","ばっ気槽混合液浮遊物質濃度(MLSS) ― %","水の密度 ― kg/m³","溶存酸素濃度 ― mg/L","BOD負荷量 ― g/(人・日)"],"a":1,"e":"MLSSは、ばっ気槽の液1Lの中にある浮遊物質(主に活性汚泥)の量なので、単位は mg/L で表す。","l":"法令外","c":""},{"id":"2019-107","s":4,"q":"給水及び排水の管理に関する次の記述のうち、最も不適当なものはどれか。","o":["膨張管とは、給湯配管系統の安全装置の一つである。","ゲージ圧力とは、真空を基準とする圧力のことである。","富栄養化とは、栄養塩類を含んだ汚水の流入により、湖沼などの水質汚濁が進むことである。","金属の不動態化とは、酸化保護被膜の生成をいう。","バルキングとは、活性汚泥が沈降しにくくなる現象である。"],"a":1,"e":"ゲージ圧力は「大気圧」を基準(0)とした圧力である。真空を基準とするのは絶対圧力である。","l":"法令外","c":""},{"id":"2019-108","s":4,"q":"給水設備における水質劣化の原因に関する次の記述のうち、最も不適当なものはどれか。","o":["異臭味は、藻類や放線菌が産生する臭気物質によって生じる。","スケールは、水の硬度成分によって生じ、配管の詰まりの原因となる。","白濁現象は、脂肪酸と銅イオンが化合物を形成することによって生じる。","スライム障害は、細菌類や藻類の増殖によって生じ、消毒効果の低下の原因となる。","トリハロメタンは、水槽内の水温の上昇によって、その生成量が増加する傾向にある。"],"a":2,"e":"脂肪酸と銅イオンが化合物を作って起きるのは「青い水」である。白濁は、亜鉛めっき鋼管から溶け出した亜鉛や、水に溶けていた空気の気泡などで起きる。","l":"法令外","c":""},{"id":"2019-109","s":4,"q":"給水設備に関する次の記述のうち、最も不適当なものはどれか。","o":["簡易専用水道とは、水道事業の用に供する水道から受ける水のみを水源とするもので、水槽の有効容量の合計が10m³を超えるものをいう。","配水管から給水管に分岐する箇所での配水管の最小動水圧は、150kPaである。","開放型冷却塔の補給水は、冷却水循環量の2%程度を見込む。","一般水栓における必要水圧は、30kPaである。","水道法に基づく水質基準では、大腸菌は1mLの検水で形成される集落数が100以下である。"],"a":4,"e":"水質基準では、大腸菌は「検出されないこと」とされている。「1mLの検水で集落数100以下」は一般細菌の基準である。","l":"水質基準に関する省令(表)、水道法施行令 第2条、水道施設の技術的基準を定める省令 第7条","c":""},{"id":"2019-110","s":4,"q":"水道施設に関する次の記述のうち、最も不適当なものはどれか。","o":["送水施設は、浄水施設で処理された水を配水施設まで送る施設のことである。","取水施設の位置の選定に当たっては、水量及び水質に対する配慮が必要である。","清澄な地下水を水源とする場合、浄水処理は消毒のみで水道水として供給することがある。","配水池の必要容量は、計画1日最大給水量の8時間分を標準とする。","緩速ろ過法は、沈殿池で水中の土砂などを沈殿させた後に、緩速ろ過池で4〜5m/日の速度でろ過する方法である。"],"a":3,"e":"配水池は時間ごとの使用量の変化をならすための池で、必要容量は計画1日最大給水量の「12時間分」を標準とする。","l":"法令外","c":""},{"id":"2019-111","s":4,"q":"給水設備に関する次の記述のうち、最も不適当なものはどれか。","o":["ウォータハンマとは、給水管路において、弁を急激に閉止するときに弁の下流に生じる著しい圧力上昇が、圧力変動の波として管路に伝わる現象である。","逆サイホン作用とは、給水管内が負圧になったときに生ずる吸引作用で、汚れた水が吐水口を通じて給水管内に逆流することをいう。","メカニカル形接合とは、ステンレス鋼管などで採用されている接合方法で、ねじ込み、溶接、接着等によらない機械的な接合方法をいう。","さや管ヘッダ工法とは、集合住宅などで、ヘッダから各器具にそれぞれ単独に配管する工法である。","クリープ劣化とは、合成樹脂管などで発生する劣化で、応力が長時間継続してかかり、材料変形が時間とともに進んでいく状態をいう。"],"a":0,"e":"弁を急に閉めると、流れてきた水がせき止められて弁の「上流」側で圧力が急上昇する。これがウォータハンマである。","l":"法令外","c":""},{"id":"2019-112","s":4,"q":"給水設備の配管に関する次の記述のうち、最も不適当なものはどれか。","o":["給水管を上向き配管方式とする場合は、先上り配管とする。","給水配管の枝管の分岐は、下方に給水する場合には下取出しとする。","飲料水用配管は、他の配管系統と識別できるようにしなければならない。","銅管やステンレス鋼管は、異物の付着による孔食のおそれがあるので、管内清掃を十分に行う。","不等(不同)沈下の変位吸収のために、ショックアブソーバを配管に取り付ける。"],"a":4,"e":"地盤沈下などによる変位の吸収には、可とう継手(曲がったり伸び縮みしたりできる継手)を使う。ショックアブソーバは地震などの衝撃を抑える装置である。","l":"法令外","c":""},{"id":"2019-113","s":4,"q":"受水槽に関する次の記述のうち、最も不適当なものはどれか。","o":["水の使用量が極端に減少する期間がある建築物では、受水槽の水位を通常使用時と少量使用時で切り替える方法を取る。","流入管からの吐水による水面の波立ち防止策として、防波板を設置する。","受水槽を独立した室に設置する場合は、出入口に施錠するなどの措置を講ずる。","受水槽の上部には、他設備の機器や配管が設置されないようにする。","受水槽の流入口と流出口の位置は、滞留時間を短くするため近接させる。"],"a":4,"e":"流入口と流出口が近いと、入った水がすぐ出ていき、槽の中に水が淀む場所(死水)ができる。流入口と流出口は対角線上など、離れた位置に設ける。","l":"法令外","c":""},{"id":"2019-114","s":4,"q":"給水設備に関する次の記述のうち、最も不適当なものはどれか。","o":["受水槽の有効容量は、一般に1日最大使用水量の1/2程度である。","給水管と排水管が水平に並行して埋設される場合は、一般に両配管の水平間隔を300mm以内とする。","高層ホテルにおいてゾーニングする場合の圧力の上限値は、一般に0.3MPaである。","給水配管内の適正流速は、一般に0.9〜1.2m/sである。","高置水槽の有効容量は、一般に1日最大使用水量の1/10程度である。"],"a":1,"e":"給水管が汚染されないよう、給水管と排水管を並べて埋設するときは、水平間隔を500mm以上とし、給水管を排水管より上にする。","l":"法令外","c":""},{"id":"2019-115","s":4,"q":"給水設備の保守管理に関する次の記述のうち、最も不適当なものはどれか。","o":["貯水槽の付属装置である定水位弁や電極棒等の動作不良により、断水、溢(いっ)水事故を起こすことがある。","地震など、貯水槽の構造や水質に影響を与えるような事態が発生した場合には、速やかにその影響を点検する。","給水ポンプの吐出側の圧力が変動している場合は、ポンプ内あるいは吐出配管に詰まりがある。","高置水槽と受水槽の清掃は、原則として同じ日に行い、受水槽の清掃前に高置水槽の清掃を行う。","給水栓において規定値の残留塩素が保持できない場合は、塩素剤の注入装置を設置して、その適正な管理を行う。"],"a":3,"e":"清掃は、まず「受水槽」を行い、その後に高置水槽を行う。先に高置水槽を洗っても、汚れた受水槽の水が送られてきてしまうため。","l":"平成15年厚生労働省告示第119号 第2の一の1","c":""},{"id":"2019-116","s":4,"q":"次のポンプの点検項目のうち、点検頻度を一般に6カ月に1回程度としているものはどれか。","o":["吐出側の圧力","ポンプと電動機の芯狂い","電動機の絶縁抵抗","電流値","軸受温度"],"a":1,"e":"ポンプと電動機の芯狂い(軸のずれ)の点検は6か月に1回程度とされる。吐出側の圧力・電流値・軸受温度は毎日、絶縁抵抗は1か月に1回程度点検する。","l":"法令外","c":""},{"id":"2019-117","s":4,"q":"給水設備の保守管理に関する次の記述のうち、最も不適当なものはどれか。","o":["飲料用貯水槽の清掃は、1年以内ごとに1回、定期に行う。","飲料用貯水槽の清掃作業に従事する者は、6カ月に1回程度、健康診断を受ける。","飲料用貯水槽の点検は、6カ月に1回程度、定期に行う。","給水栓における残留塩素の測定は、7日以内ごとに1回、定期に行う。","第2種圧力容器に該当する圧力水槽は、1年以内ごとに1回、定期自主検査を行う。"],"a":2,"e":"飲料用貯水槽の点検は、汚染を早く見つけるため1か月に1回程度行う。6か月に1回では少なすぎる。","l":"建築物衛生法施行規則 第4条(選択肢1・4)、ボイラー及び圧力容器安全規則 第88条(選択肢5)","c":""},{"id":"2019-118","s":4,"q":"給湯設備に関する次の記述のうち、最も不適当なものはどれか。","o":["壁掛けシャワーの使用温度は、42℃程度である。","総合病院における使用湯量は、40〜80L/(床・日)程度である。","電気温水器の貯湯量は、60〜480L程度である。","強制循環式給湯系統の横管は、1/200以上の勾配で配管する。","貯湯槽の容量は、ピーク時の必要量の1〜2時間分を目安に加熱能力とのバランスから決定する。"],"a":1,"e":"総合病院は入浴や医療などで湯を多く使うため、使用湯量は100〜200L/(床・日)程度とされる。40〜80Lは少なすぎる。","l":"法令外","c":""},{"id":"2019-119","s":4,"q":"給湯設備に関する次の記述のうち、最も不適当なものはどれか。","o":["中央式給湯方式の循環ポンプは、省エネルギーのため連続運転とする。","貯湯槽の容量が小さいと、加熱装置の発停が多くなる。","エネルギーと水の節約を図るため、湯と水を別々の水栓から出さずに混合水栓を使用する。","部分負荷を考慮し、エネルギー利用効率の高い熱源機器を採用する。","加熱装置から逃し管を立ち上げる場合は、水を供給する高置水槽の水面よりも高く立ち上げる。"],"a":0,"e":"循環ポンプを連続運転すると電力の無駄になる。返湯管の温度が下がったときだけ動かすなど、温度で発停させるのが省エネになる。","l":"法令外","c":""},{"id":"2019-120","s":4,"q":"給湯設備に使用される加熱装置に関する次の記述のうち、最も不適当なものはどれか。","o":["ガスマルチ式給湯機は、小型のガス瞬間湯沸器を複数台連結してユニット化したものである。","ヒートポンプは、排熱を利用した給湯熱源機器として使用される。","間接加熱方式は、蒸気や高温の温水を熱源として、加熱コイルで給湯用の水を加熱するものである。","ボイラは、伝熱面積とゲージ圧力により、ボイラ、小型ボイラ、簡易ボイラに分類される。","給湯用貫流ボイラは、出湯温度が安定しているので、大規模のシャワー設備の給湯に適している。"],"a":4,"e":"貫流ボイラは中にためている水の量が少ないため、使う量が変わると出湯温度が変わりやすい。そのため、大規模なシャワー設備には向かない。","l":"法令外","c":""},{"id":"2019-121","s":4,"q":"給湯設備に使用される材料に関する次の記述のうち、最も不適当なものはどれか。","o":["ステンレス鋼管の線膨張係数は、架橋ポリエチレン管の線膨張係数より小さい。","金属材料の曲げ加工を行った場合には、応力腐食の原因になる。","樹脂管を温度の高い湯に使用すると、塩素による劣化が生じやすい。","返湯管に銅管を用いた場合は、他の配管材料を用いた場合と比較して、流速を速く設定できる。","ステンレス鋼管は、隙間腐食、もらい錆(さび)等による腐食が生じる可能性がある。"],"a":3,"e":"銅管は流れが速いと管の内面が削られて腐食する(潰食)おそれがあるので、返湯管に使うときは流速を遅めにする。","l":"法令外","c":""},{"id":"2019-122","s":4,"q":"給湯設備の保守管理に関する次の記述のうち、最も不適当なものはどれか。","o":["器具のワッシャには、細菌の繁殖を防止するために合成ゴムを使用する。","中央式給湯方式においては、加熱により残留塩素が消滅する場合があるので、その水質には留意する。","貯湯槽が複数ある場合は、停滞水の防止のため、使用しない貯湯槽の水は抜いておく。","貯湯槽に流電陽極式電気防食を施す場合は、外部電源が必要である。","給湯設備に防錆(せい)剤を使用する場合は、飲料水と同じ管理方法による。"],"a":3,"e":"流電陽極式は、鉄より溶けやすい金属(犠牲陽極)を取り付け、それが溶けることで防食するので、外部電源はいらない。外部電源が必要なのは外部電源式である。","l":"法令外","c":""},{"id":"2019-123","s":4,"q":"給湯設備の保守管理に関する次の記述のうち、最も不適当なものはどれか。","o":["給湯循環ポンプは、作動確認を兼ねて分解・清掃を実施する。","自動空気抜き弁は、弁からの水漏れがある場合には分解・清掃を実施する。","真空式温水発生機の定期検査は、労働安全衛生法の規定に基づいて行う。","逃し弁は、レバーハンドルを操作して作動を確認する。","配管系統の末端において、定期的に停滞水の排出を行い、温度測定を実施する。"],"a":2,"e":"真空式温水発生機は、中の圧力が大気圧より低いため労働安全衛生法のボイラーに当たらず、同法に基づく定期検査の対象ではない。","l":"法令外","c":""},{"id":"2019-124","s":4,"q":"雑用水設備に関する次の記述のうち、最も不適当なものはどれか。","o":["広域循環方式は、複数の建築物間で排水再利用設備を共同利用し、処理水を各建築物に送水して利用するものである。","雑用水は、災害時における非常用水の原水として利用することができる。","雨水利用設備における上水代替率とは、使用水量に対する雨水利用量の割合である。","散水、修景、清掃用水として利用する場合、雑用水受水槽は、6面点検ができるように設置することが望ましい。","上水管、雑用水管、給湯管等が並行して配管される場合、配管の配列を変えてはならない。"],"a":0,"e":"選択肢は「地区循環方式」の説明である。広域循環方式は、下水処理場などの処理水を広い地域の建物にまとめて送る方式である。","l":"法令外","c":""},{"id":"2019-125","s":4,"q":"雑用水として使用する場合の標準的な雨水処理施設における次のフローシートの( )内に入る単位装置の組合せとして、最も適当なものはどれか。\n集水 → スクリーン →(ア)→(イ)→ 雨水貯留槽 → 消毒装置 → 雑用水槽 → 給水","o":["ア:沈砂槽 イ:沈殿槽","ア:流量調整槽 イ:活性炭吸着装置","ア:活性炭吸着装置 イ:沈殿槽","ア:流量調整槽 イ:生物処理槽","ア:沈砂槽 イ:生物処理槽"],"a":0,"e":"雨水は汚れが少ないので、生物処理はしない。スクリーンでごみを除いた後、沈砂槽で砂を、沈殿槽で細かい汚れを沈めてから貯留する。","l":"法令外","c":""},{"id":"2019-126","s":4,"q":"建築物衛生法による雑用水の基準に関する次の記述のうち、誤っているものはどれか。","o":["散水、修景又は清掃の用に供する雑用水は、し尿を含む水を原水として用いない。","水洗便所の用に供する雑用水のpHの基準値は、散水、修景又は清掃の用に供する雑用水の場合と同じ値である。","外観の検査は、7日以内ごとに1回、定期に行う。","水洗便所の用に供する雑用水の水質基準項目として、濁度が規定されている。","大腸菌の検査は、2カ月以内ごとに1回、定期に行う。"],"a":3,"e":"濁度(2度以下)が基準にあるのは散水・修景・清掃用の雑用水だけで、水洗便所用には濁度の基準はない。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2019-127","s":4,"q":"下水道に関する次の記述のうち、最も不適当なものはどれか。","o":["下水道は、流域下水道、公共下水道、都市下水路に分けられる。","下水道施設は、排水管渠(きょ)、処理施設及びポンプ施設等から構成されている。","合流式とは、汚水と雨水を同一の管渠系統で排除する方式をいう。","下水の温度が基準値以上の場合には、除害施設を設置する必要がある。","流域下水道の事業主体は、原則として市町村である。"],"a":4,"e":"流域下水道は2つ以上の市町村にまたがる下水を処理するもので、原則として「都道府県」が設置・管理する。市町村が行うのは公共下水道である。","l":"下水道法 第2条・第3条・第25条の22","c":""},{"id":"2019-128","s":4,"q":"排水通気設備に関する次の記述のうち、最も不適当なものはどれか。","o":["管径50mmの排水横管の最小勾配は、1/50である。","厨(ちゅう)房排水用の排水管に設置する掃除口の口径は、排水管径と同径とする。","飲料用貯水槽の間接排水管の口径が65mmの場合、排水口空間は、最小125mmである。","排水横主管以降が満流となるおそれのある場合、伸頂通気方式を採用してはならない。","通気管の末端を、窓・換気口等の付近に設ける場合、その上端から600mm以上立ち上げて大気に開放する。"],"a":2,"e":"飲料用貯水槽の間接排水管の排水口空間は、管の太さに関係なく最小150mmとする。","l":"法令外","c":""},{"id":"2019-129","s":4,"q":"阻集器に関する次の記述のうち、最も不適当なものはどれか。","o":["阻集器を兼ねる排水トラップの深さは、下限値を50mmとし、上限値を定めない。","グリース阻集器は、器内への排水の流入部へバスケットを設けて、排水中に含まれる厨(ちゅう)芥(かい)を阻止・分離する。","排水トラップが組み込まれていない阻集器には、その入口側に排水トラップを設ける。","砂阻集器は、建築現場等から多量に排出される土砂・石粉・セメント等を阻止・分離・収集するために設ける。","開放式のオイル阻集器を屋内に設置する場合、屋内換気を十分に行う。"],"a":2,"e":"トラップが組み込まれていない阻集器には、「出口側」にトラップを設ける。入口側に付けると、阻集器にたまった汚れの臭いなどを防げない。","l":"法令外","c":""},{"id":"2019-130","s":4,"q":"排水通気設備に関する次の記述のうち、最も不適当なものはどれか。","o":["排水管への掃除口の設置間隔は、管径100mmを超える場合は、通常30m以内とする。","排水トラップの脚断面積比(流出脚断面積/流入脚断面積)が大きくなると、封水強度は大きくなる。","敷地排水管の直管が長い場合には、管内径の120倍を超えない範囲内に排水ますを設置する。","ドーム状のルーフドレンでは、ストレーナの開口面積は、接続する排水管径の2倍以上が必要である。","雑排水ポンプは、厨(ちゅう)房排水を含む雑排水を排除する。"],"a":4,"e":"雑排水ポンプは厨房排水を「除いた」雑排水に使う。油や固形物を含む厨房排水には、汚物ポンプなど詰まりにくいポンプを使う。","l":"法令外","c":""},{"id":"2019-131","s":4,"q":"排水通気配管方式に関する次の記述のうち、最も不適当なものはどれか。","o":["ループ通気管は、最上流の器具排水管が排水横枝管に接続する点のすぐ下流から立ち上げ、通気立て管に接続する。","結合通気管は、高層建築物でブランチ間隔10以上の排水立て管において、最上階から数えてブランチ間隔10以内ごとに設ける。","ループ通気方式において、大便器及びこれと類似の器具が8個以上接続される排水横枝管には、逃し通気管を設ける。","伸頂通気方式において、排水横主管の水平曲がりは、排水立て管の底部より3m以内に設けてはならない。","排水横管から通気管を取り出す場合、通気管は、排水管断面の水平中心線から30°以内の角度で取り出す。"],"a":4,"e":"通気管に排水が入り込まないよう、排水横管の断面の「垂直中心線」上部から45°以内の角度で取り出す。","l":"法令外","c":""},{"id":"2019-132","s":4,"q":"排水槽及び排水ポンプに関する次の記述のうち、最も不適当なものはどれか。","o":["排水槽内は、ブロワによってばっ気をすると負圧になるので給気を行う。","排水槽の底部の勾配は、吸込みピットに向かって1/15以上1/10以下とする。","排水槽内の排水ポンプは、吸込みピットの壁などから200mm以上離して設置する。","排水槽のマンホールは、排水水中ポンプ又はフート弁の直上に設置する。","即時排水型ビルピット設備は、排水槽の悪臭防止に有効である。"],"a":0,"e":"ブロワで空気を吹き込むと、槽内は空気が増えて「正圧」になる。そのため、通気管で外へ排気できるようにしておく。","l":"法令外","c":""},{"id":"2019-133","s":4,"q":"排水通気設備の保守管理に関する用語の組合せとして、最も不適当なものはどれか。","o":["敷地内排水管内の清掃 ― ロッド法","敷地外からの建築物内への雨水の浸入 ― 可動式の堤防装置","床下式の掃除口 ― 鋼製プラグ","排水槽の清掃 ― 空気呼吸器","厨(ちゅう)房排水槽の水位感知 ― フロートスイッチ"],"a":2,"e":"鋼製プラグはさびて固着し、外せなくなるおそれがある。床下式の掃除口には、さびにくい砲金製(銅合金)のプラグを使う。","l":"法令外","c":""},{"id":"2019-134","s":4,"q":"排水通気設備の保守管理に関する次の記述のうち、最も不適当なものはどれか。","o":["排水管内部の詰まり具合や腐食状況は、内視鏡や超音波厚さ計等により確認できる。","排水槽の清掃では、最初に酸素濃度が15%以上、硫化水素濃度が25ppm以下であることを確認してから作業を行う。","排水横管の清掃にワイヤ法を使用する場合、一般に長さ25m程度が限界とされている。","水中ポンプのメカニカルシール部のオイルは、6カ月〜1年に1回、交換する。","排水管の清掃に用いるウォータラム法は、閉塞した管内に水を送り、圧縮空気を一気に放出してその衝撃で閉塞物を除去する。"],"a":1,"e":"排水槽に入る前には、酸素濃度18%以上、硫化水素濃度10ppm以下であることを確かめる。15%や25ppmでは酸欠や中毒の危険がある。","l":"酸素欠乏症等防止規則 第2条・第5条","c":""},{"id":"2019-135","s":4,"q":"小便器に関する次の記述のうち、最も不適当なものはどれか。","o":["壁掛型は、駅やホテルの共用部などにおいて床清掃のしやすさから選定されている。","床置型は乾燥面が広いため、洗浄に注意しないと臭気が発散する。","手動式洗浄弁は、使用後、人為的な操作により洗浄でき、公衆用に適している。","洗浄方式は、一般に洗浄水栓方式、洗浄弁方式及び自動洗浄方式の三つに分けられる。","節水を目的として、個別感知洗浄方式や照明スイッチ等との連動による洗浄方式が用いられている。"],"a":2,"e":"手動式は使った人が流し忘れることがあるので、多くの人が使う公衆用には向かない。公衆用には自動洗浄方式が向いている。","l":"法令外","c":""},{"id":"2019-136","s":4,"q":"衛生器具設備に関する次の記述のうち、最も不適当なものはどれか。","o":["大便器洗浄弁の必要水圧は、70kPaである。","小便器の排水状態は、6カ月に1回、定期に点検する。","洗面器のトラップの接合部における緩みの有無は、2カ月に1回、定期に点検する。","大便器の洗浄タンク内の汚れ状態は、1年に1回、定期に点検する。","JIS A 5207では、節水Ⅱ形の大便器の洗浄水量は、6.5L以下としている。"],"a":3,"e":"大便器の洗浄タンクの中の汚れの状態は、6か月に1回、定期に点検する(2017年問135でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2019-137","s":4,"q":"厨(ちゅう)房排水除害施設に関する次の記述のうち、最も不適当なものはどれか。","o":["生物処理法は、浮上分離法に比べて発生汚泥量が多い傾向にある。","動植物油の除去が主な目的である。","浮上分離法としては、一般的に加圧浮上法が用いられる。","施設のコンクリート壁面などは、腐食対策が必要となる。","施設から発生する汚泥は、産業廃棄物として処理する。"],"a":0,"e":"生物処理法は、油などを微生物に分解させるので、薬品で固めて浮かせる浮上分離法より発生する汚泥の量が「少ない」。","l":"法令外","c":""},{"id":"2019-138","s":4,"q":"浄化槽法で規定されている事項として、誤っているものはどれか。","o":["浄化槽製造業の登録制度","浄化槽工事業の登録制度","浄化槽保守点検業の登録制度","浄化槽清掃業の許可制度","浄化槽設備士及び浄化槽管理士の国家資格"],"a":0,"e":"浄化槽法には、浄化槽の「型式の認定」の制度はあるが、製造業の登録制度はない。工事業の登録、清掃業の許可、浄化槽設備士・浄化槽管理士の資格は定められ、保守点検業の登録は同法にもとづき条例で定める。","l":"浄化槽法 第13条・第21条・第35条・第42条・第45条・第48条","c":""},{"id":"2019-139","s":4,"q":"下図のように、一次処理装置、二次処理装置からなる浄化槽において、一次処理装置のBOD除去率が30%、二次処理装置のBOD除去率が50%であった場合、浄化槽全体のBOD除去率として、最も適当な値はどれか。","o":["35%","40%","50%","65%","80%"],"a":3,"e":"流入BODを100とすると、一次処理で30%除かれて70、二次処理でその50%が除かれて35が残る。除去されたのは100−35=65なので、65%となる。","l":"法令外","c":"","g":["img/2019-139.png"]},{"id":"2019-140","s":4,"q":"消火設備に関する次の記述のうち、最も不適当なものはどれか。","o":["連結散水設備は、消火活動が困難な地下街に設置される。","閉鎖型予作動式スプリンクラ設備は、アトリウムなどの大空間に設置される。","屋内消火栓設備は、建築物の関係者や自衛消防隊が初期消火を目的として使用するものである。","粉末消火設備は、消火薬剤として炭酸水素ナトリウムなどの粉末を使用する。","泡消火設備は、駐車場や飛行機の格納庫等に設置される。"],"a":1,"e":"閉鎖型予作動式は、誤って放水すると困るコンピュータ室などに使う。天井の高いアトリウムなどの大空間には、放水型スプリンクラー設備が使われる。","l":"法令外","c":""},{"id":"2019-141","s":5,"q":"建築物における衛生的環境の維持管理について(平成20年1月25日健発第0125001号)に示された、建築物環境衛生維持管理要領に関する次の記述のうち、最も不適当なものはどれか。","o":["帳簿書類には、清掃、点検及び整備を実施した年月日、作業内容等を記載する。","清掃用機械及び器具は、清潔なものを用い、汚染度を考慮して区域ごとに使い分ける。","大掃除においては、1年以内ごとに1回、日常清掃の及びにくい箇所等の汚れ状況を点検し、必要に応じ除じん、洗浄を行う。","清掃用機械及び器具類、清掃用資材の保管庫は、6カ月以内ごとに1回、定期に点検する。","収集・運搬設備、貯留設備等の廃棄物処理設備は、6カ月以内ごとに1回、定期に点検する。"],"a":2,"e":"大掃除は6か月以内ごとに1回、定期に行うと定められている(施行規則第4条の5)。1年以内ごとではない。","l":"建築物衛生法施行規則 第4条の5、平成15年厚生労働省告示第119号 第5","c":""},{"id":"2019-142","s":5,"q":"建築物清掃の標準的な作業計画に関する次の記述のうち、最も適当なものはどれか。","o":["エレベータかご内部の除じんは、定期清掃として実施する。","廊下壁面のスイッチ回りの洗剤拭きは、日常清掃として実施する。","トイレ・洗面所の換気口の除じんは、定期清掃として実施する。","一般の人が立ち入らない管理用区域の清掃は、年2回程度実施する。","エスカレータパネル類の洗剤拭きは、日常清掃として実施する。"],"a":2,"e":"トイレ・洗面所の換気口の除じんは、毎日ではなく定期清掃で行う。エレベーターかご内の除じんは日常清掃、スイッチ回りやエスカレーターのパネル類の洗剤拭きは定期清掃で行うのが一般的である。","l":"法令外","c":""},{"id":"2019-143","s":5,"q":"建築物清掃の作業計画に関する次の記述のうち、最も不適当なものはどれか。","o":["記憶や経験を基にした個人的な管理手法のため、作業指示が円滑になる。","作業内容が明確化されているため、統一的な指導ができる。","計画的な作業管理により、記録の保存によって責任の所在が明確になる。","計画的に作業を実施できることから、限られた時間内に一定の成果が得られる。","日常清掃で除去する汚れと定期的に除去する汚れを区別することによって、作業効率と作業成果の向上が得られる。"],"a":0,"e":"作業計画は、記憶や経験に頼る個人的な管理をやめて、誰でも同じように作業できるように明文化するものである。「個人的な管理手法のため」は逆。","l":"法令外","c":""},{"id":"2019-144","s":5,"q":"建築物清掃作業の安全衛生に関する次の記述のうち、最も不適当なものはどれか。","o":["清掃作業に関わる転倒事故防止は、清掃作業従事者と第三者の安全確保のために必要である。","清掃作業に関わる事故の多くは、転倒や墜落・転落事故である。","ノロウィルス感染によると思われる嘔(おう)吐物があった場合は、その物をぬぐい取り、その部分を含む広い範囲をクレゾール石けん液で消毒する。","洗剤などは使用説明書に従って使用し、保護手袋などの保護具を適切に用いる。","吸殻処理は、清掃業務における防火対策として重要である。"],"a":2,"e":"ノロウイルスにはクレゾール石けん液(や逆性石けん・アルコール)は効きにくい。嘔吐物を拭き取った後は、次亜塩素酸ナトリウムで消毒する。","l":"法令外","c":""},{"id":"2019-145","s":5,"q":"建築物清掃の作業管理に関する次の記述のうち、最も不適当なものはどれか。","o":["作業計画に基づき、日常清掃と定期清掃の予定表を作成し、適正な人員配置を行う。","定期的に点検を行い、現場実態を把握しておく。","正しい作業方法を従事者に教育・指導し、作業能率と作業成果の向上、安全衛生に努める。","作業実態分析を行い、ムリ、ムダ、ムラがないようにし、作業方法を変えずに常に同じ作業を実施する。","建材、汚れ等に適した清掃機械・器具やケミカル類を選定する。"],"a":3,"e":"作業実態を分析してムリ・ムダ・ムラをなくし、必要に応じて作業方法を見直していくことが大切。「作業方法を変えずに常に同じ作業」は誤り。","l":"法令外","c":""},{"id":"2019-146","s":5,"q":"建築物清掃の点検評価に関する次の記述のうち、最も不適当なものはどれか。","o":["清掃作業の実施状況の点検については、四半期ごとに実施する。","清掃作業の評価は、利用者の立場に立って実施する。","評価範囲は、汚染度合いの高い箇所などに重点を絞る。","作業の改善は、作業仕様書や作業基準書に限定しないで行う。","清掃作業の点検評価は、主として測定機器(光沢度計など)を用いて行う。"],"a":4,"e":"清掃の点検評価は、主に目視などの官能検査で行う。光沢度計などの測定機器は補助的に使う。","l":"法令外","c":""},{"id":"2019-147","s":5,"q":"建材の予防清掃に関する次の記述のうち、最も不適当なものはどれか。","o":["ほこり以外の汚れ物質は、人間の活動に伴って付着することが多い。","高気密化している建築物では、窓や隙間がほこりの侵入路として重要視されている。","汚れは、凹凸が多くて粗い表面には付着しやすく、付着すると除去しにくい。","建材が親水性か疎水性かによって、付着する汚れの種類は異なる。","シール剤や床維持剤の塗布により、汚れの予防効果が得られる。"],"a":1,"e":"気密性の高い建物では、窓や隙間から入るほこりは少なく、ほこりの主な侵入路は人の出入りする出入口である。","l":"法令外","c":""},{"id":"2019-148","s":5,"q":"ビルクリーニング用機械・器具に関する次の記述のうち、最も不適当なものはどれか。","o":["床みがき機に用いるブラシは、直径50cm以上のものが多く使われている。","凹凸のある床面は、研磨粒子入りブラシを付けて洗浄する。","床みがき機に用いるブラシは、シダの茎、又はナイロン繊維を植えたものが一般的である。","自在ぼうきは、馬毛などを植えた薄いブラシであり、ほこりを舞い上げることが少ない。","超高速バフ機の回転数は、毎分1,000〜3,000回転である。"],"a":0,"e":"床みがき機のブラシは直径40cm前後(20〜50cm)のものが多く使われている。50cm以上が多いのではない。","l":"法令外","c":""},{"id":"2019-149","s":5,"q":"カーペット清掃用機械に関する次の記述のうち、最も不適当なものはどれか。","o":["ローラブラシ方式の洗浄機は、パイルに対する当たりが柔らかで、パイルを傷めることが少ない。","スチーム洗浄機は、カーペットのしみ取りにも使われる。","アップライト型真空掃除機は、カーペットのほこりを取るのに適している。","洗剤供給式床みがき機は、ウールのウィルトンカーペットの洗浄に適している。","エクストラクタは、水分に耐えるカーペットの洗浄に適している。"],"a":3,"e":"ウールのウィルトンカーペットは水や摩擦に弱く、洗剤供給式床みがき機(ロータリーブラシでこする方式)で洗うとパイルを傷めやすい。","l":"法令外","c":""},{"id":"2019-150","s":5,"q":"清掃作業に使用する洗剤に関する次の記述のうち、最も不適当なものはどれか。","o":["酸性洗剤は、小便器に付着した尿石や、鉄分を含んだ水垢(あか)等の除去に有効である。","アルカリ性洗剤は、幅広い用途に使用されるが、床材や作業方法に注意して使う必要がある。","研磨剤入り洗剤は、固着した汚れの除去に有効である。","洗剤は、最適な濃度に希釈して用いるのが効果的である。","表面洗剤には、界面活性剤や助剤が配合されているので、泡立ちやすいものが多い。"],"a":4,"e":"表面洗剤は、樹脂床維持剤の皮膜を傷めずに汚れを落とす洗剤で、泡立ちを抑えて作られている。「泡立ちやすい」は誤り。","l":"法令外","c":""},{"id":"2019-151","s":5,"q":"弾性床材の特徴と管理に関する次の記述のうち、最も適当なものはどれか。","o":["塩化ビニルシートは、床維持剤の密着不良が起きにくい。","塩化ビニル系床材は、耐薬品性や耐水性に富む。","リノリウムは、耐アルカリ性に富む。","床維持剤を塗布することで、土砂・ほこりの除去頻度を減らすことができる。","塩化ビニルタイルは、可塑剤を含まない。"],"a":1,"e":"塩化ビニル系床材は、薬品や水に強い。1は密着不良が起きやすい、3はリノリウムはアルカリに弱い、4は除じんの回数は減らせない、5は可塑剤を含む、がそれぞれ正しい。","l":"法令外","c":""},{"id":"2019-152","s":5,"q":"硬性床材の耐薬品性に関する次の記述のうち、最も適当なものはどれか。","o":["花崗(こう)岩は、耐アルカリ性に乏しい。","セラミックタイルは、耐酸性、耐アルカリ性に乏しい。","テラゾは、耐酸性に優れる。","コンクリートは、耐酸性に優れる。","大理石は、耐酸性、耐アルカリ性に乏しい。"],"a":4,"e":"大理石は酸にもアルカリにも弱い。花崗岩はアルカリに強く、セラミックタイルは酸・アルカリに強い。テラゾやコンクリートは酸に弱い。","l":"法令外","c":""},{"id":"2019-153","s":5,"q":"繊維床材の清掃方法に関する次の記述のうち、最も適当なものはどれか。","o":["玄関や共用部は汚れやすいので、その日のうちに真空掃除機で土砂を除去する。","パイル内部のほこりの除去には、カーペットスイーパを用いる。","アクリル素材は、親水性の汚れが取れにくい。","しみ取り作業は定期清掃時に行う。","スポットクリーニングは、パイル奥の汚れまで徹底的に除去する作業である。"],"a":0,"e":"玄関や共用部は土砂が持ち込まれやすいので、その日のうちに真空掃除機で取り除く。パイル内部のほこりは真空掃除機で取り、しみはすぐに取るのが基本である。","l":"法令外","c":""},{"id":"2019-154","s":5,"q":"清掃におけるドライメンテナンスに関する次の記述のうち、最も不適当なものはどれか。","o":["床材への熱影響に注意が必要である。","スプレークリーニング法の仕上げには、フロアポリッシュを塗布する。","ウェットメンテナンス法に比べ、滑りや転倒が多いので注意が必要である。。","床材への水の浸透による劣化を防ぐ。","ドライバフ法で用いる床みがき機は、回転数が高いほど、光沢度の回復が容易である。"],"a":2,"e":"ドライメンテナンス法は水をほとんど使わないので、ウェットメンテナンス法より床が濡れにくく、滑りや転倒は少ない。","l":"法令外","c":""},{"id":"2019-155","s":5,"q":"清掃におけるウェットメンテナンスに関する次の記述のうち、最も不適当なものはどれか。","o":["汚れが激しい箇所を洗剤で洗浄し、床維持剤を塗布する。","樹脂床維持剤の皮膜を除去するには、酸性の剥離剤で皮膜を溶解させる。","ドライメンテナンス法に比べ、部分補修がしにくい。","シールされた木質床は、水性フロアポリッシュを使用できるが、水の使用を最小限にして管理する必要がある。","ドライメンテナンス法に比べ、使用する資機材の種類が多い。"],"a":1,"e":"樹脂床維持剤の皮膜は、アルカリ性の剥離剤で溶かして取り除く。酸性ではない。","l":"法令外","c":""},{"id":"2019-156","s":5,"q":"床以外の清掃作業に関する次の記述のうち、最も適当なものはどれか。","o":["廊下の壁面は、階段の壁面と比較して、ほこりの付着量が多い。","ドア・エレベータスイッチは、冬期は夏期に比べ手垢(あか)が付きやすくなる。","エレベータの壁は、手垢で汚れやすいので表面に保護膜を塗布しておくとよい。","トイレの清掃は、衛生上の観点から利用者の使用を全面的に禁止して作業を行う。","照明器具は静電気でほこりがたまりやすく、照度低下があるため、毎日清掃する必要がある。"],"a":2,"e":"エレベーターの壁は手あかが付きやすいので、保護膜を塗っておくと汚れが落としやすくなる。1は階段の方がほこりが多い、2は夏の方が手あかが付きやすい、4は全面禁止せず一部ずつ作業する、5は毎日の清掃は不要。","l":"法令外","c":""},{"id":"2019-157","s":5,"q":"外装の清掃に関する次の記述のうち、最も不適当なものはどれか。","o":["石材や磁器タイルの壁面は、3〜5年に1回洗浄を行う。","自動窓拭き設備には、スチーム洗浄機が組み込まれている。","臨海工業地帯の金属製の外壁は、1年に4〜6回洗浄を行う。","アルミニウム板は、通常、表面に保護膜が施されているが、徐々に汚れが付着する。","金属製の外壁は、中性洗剤か専用洗剤を用いて、スポンジ又はウエスで拭き取る。"],"a":1,"e":"ゴンドラなどに付けた自動窓拭き設備は、洗剤や水を吹き付けてブラシで洗い、汚水を回収する仕組みで、スチーム洗浄機は組み込まれていない。","l":"法令外","c":""},{"id":"2019-158","s":5,"q":"循環型社会形成に関する次の記述のうち、最も不適当なものはどれか。","o":["生産において、マテリアルリサイクルを進める。","消費・使用において、リデュースを進める。","廃棄において、リユースを進める。","処理において、サーマルリサイクルを進める。","最終処分において、天然資源の投入を進める。"],"a":4,"e":"循環型社会では、天然資源の消費をできるだけ抑えることを目指す。最終処分の段階で天然資源の投入を進めるのは逆である。","l":"法令外","c":""},{"id":"2019-159","s":5,"q":"ごみの処理に関する次の記述のうち、最も不適当なものはどれか。","o":["一般廃棄物の埋立処分は、遮断型最終処分場に埋め立てなければならない。","焼却処理では、容積は5〜10％に減容化される。","ごみ燃料化施設は、選別・乾燥技術を用いている。","粗大ごみ処理施設は、破砕・選別技術を用いている。","分別とは、収集や運搬、リサイクルや中間処理、最終処分が適正に行われるように、発生・排出元であらかじめ区分することである。"],"a":0,"e":"一般廃棄物は管理型の最終処分場に埋め立てる。遮断型最終処分場は、有害物質を含む産業廃棄物を埋め立てるためのものである。","l":"廃棄物処理法施行令 第7条第14号(産業廃棄物の最終処分場の区分)","c":""},{"id":"2019-160","s":5,"q":"廃棄物の区分に関する次の記述のうち、最も不適当なものはどれか。","o":["事業系一般廃棄物とは、事業活動に伴い発生する廃棄物のうち、産業廃棄物に該当しないものである。","粗大ごみのうち、スプリングマットレスは、適正処理困難物に該当する。","一般廃棄物のびんは、容器包装リサイクル法の対象物に該当する。","事業活動に伴い発生する廃棄物のうち、ゴムくずは、安定型品目の産業廃棄物の一つに該当する。","事業活動に伴い発生する廃棄物のうち、廃プラスチック類は、業種指定のある産業廃棄物に該当する。"],"a":4,"e":"廃プラスチック類は、どの業種から出ても産業廃棄物になる(業種指定なし)。業種指定があるのは紙くず・木くず・繊維くずなどである。","l":"廃棄物処理法 第2条第4項、同法施行令 第2条","c":""},{"id":"2019-161","s":5,"q":"建築物内廃棄物の適正処理に関する次の記述のうち、最も不適当なものはどれか。","o":["清掃作業に伴って生じる廃液は、廃棄物の処理及び清掃に関する法律に加えて下水道法、水質汚濁防止法の規定を遵守し適正に処理する。","建築物から発生する事業系一般廃棄物は、古紙と生ごみがほとんどを占める。","蛍光管は、取扱いが規制されている。","グリース阻集器で阻集される油分は、一般廃棄物の廃油に該当する。","し尿を含まないビルピット汚泥は、産業廃棄物に該当する。"],"a":3,"e":"グリース阻集器で集めた油分は、事業活動に伴う廃油なので産業廃棄物に当たる。一般廃棄物ではない。","l":"廃棄物処理法 第2条第4項、同法施行令 第2条","c":""},{"id":"2019-162","s":5,"q":"産業廃棄物に関する次の記述のうち、最も不適当なものはどれか。","o":["適正な処理を確保するため、処理基準や委託基準が定められている。","特別管理産業廃棄物は、爆発性、毒性、感染性等、人の健康又は生活環境に被害を生ずるおそれのある産業廃棄物のことである。","事業活動に伴い発生する廃棄物であって、燃え殻、汚泥等20種類をいう。","収集・運搬業者は、事業者から受託した産業廃棄物を処分業者に引き渡す際に産業廃棄物管理票を交付する。","施設及び申請者の能力等が基準に適合する場合、都道府県知事は産業廃棄物処理業者として許可する。"],"a":3,"e":"産業廃棄物管理票(マニフェスト)は、産業廃棄物を引き渡すときに排出事業者が交付する。収集運搬業者が交付するのではない。","l":"廃棄物処理法 第12条の3","c":""},{"id":"2019-163","s":5,"q":"建築物内廃棄物に関する次の記述のうち、最も不適当なものはどれか。","o":["ごみの質を表すには、水分、灰分、可燃分の比率(％)で示す方法がある。","厨(ちゅう)芥(かい)とは、紙くずと雑芥を混合したものである。","廃棄物発生場所からコレクタ等で集め、廃棄物保管場所に運ぶまでのプロセスが、収集運搬の計画である。","吸殻の収集をするときは、金属製の蓋付き容器を使用する。","新築の建築物では、使用開始後一定期間が経過した時機に、廃棄物処理計画を見直す。"],"a":1,"e":"厨芥は台所などから出る生ごみのこと。紙くずと厨芥を混ぜたものは雑芥と呼ぶ。","l":"法令外","c":""},{"id":"2019-164","s":5,"q":"産業廃棄物の委託処理に関する次の記述のうち、最も不適当なものはどれか。","o":["排出事業者は、電子マニフェストでも、A票、B2票、D票、E票の保存が必要である。","収集運搬業者の選定に当たっては、排出場所と運搬先の両方の自治体の許可を取得していることを確認する。","処理業者との契約に当たっては、収集運搬業者と処分業者とそれぞれ契約を締結しなければならない。","処理業者の選定には、都道府県や環境省のホームページ等から選ぶ方法がある。","排出事業者は、廃棄物が最終処分まで適正に処理されたことを確認する義務がある。"],"a":0,"e":"電子マニフェストを使う場合は、情報処理センターに記録が残るので、紙の伝票(A票・B2票・D票・E票)を保存する必要はない。","l":"廃棄物処理法 第12条の5","c":""},{"id":"2019-165","s":5,"q":"建築物内廃棄物の貯留・搬出方式に関する次の記述のうち、最も不適当なものはどれか。","o":["コンパクタ・コンテナ方式は、容器方式より防災性に優れている。","真空収集方式は、容器方式より衛生的に優れている。","貯留・排出機方式は、真空収集方式より初期コストが少ない。","貯留・排出機方式は、コンパクタ・コンテナ方式より大規模建築物に適用される。","コンパクタ・コンテナ方式は、容器方式よりランニングコストが少ない。"],"a":3,"e":"貯留・排出機方式は中規模の建物に向いた方式で、大規模な建物には、コンパクタ・コンテナ方式などが使われる。","l":"法令外","c":""},{"id":"2019-166","s":6,"q":"蚊の生態に関する次の記述のうち、最も不適当なものはどれか。","o":["チカイエカは、九州から北海道まで分布する。","吸血せずに産卵する蚊が知られている。","ウシやウマなど、大型動物を好んで吸血する種類がある。","ヒトスジシマカは、雨水ますなどの小さな水域から発生する。","アカイエカは、主として昼間に吸血する。"],"a":4,"e":"アカイエカは主に「夜間」に吸血する。昼間に吸血するのはヒトスジシマカなどのヤブカ類である。","l":"法令外","c":""},{"id":"2019-167","s":6,"q":"蚊の防除に関する次の記述のうち、最も不適当なものはどれか。","o":["ULV処理は、成虫に対する速効性が認められる。","ライトトラップや粘着トラップで捕獲した成虫の数は、維持管理の状態を評価するために重要である。","クレゾールなどの殺菌剤を含む製剤は、浄化槽内の微生物に影響を及ぼすおそれがある。","殺虫剤による防除効果が得られない場合には、殺虫剤抵抗性の発達を考慮する必要がある。","樹脂蒸散剤は、密閉性が保たれていない空間であっても、殺成虫効果が期待できる。"],"a":4,"e":"樹脂蒸散剤は、樹脂から少しずつ蒸発した薬剤を空間にためて効かせるので、密閉性が保たれた空間でないと効果が出ない。","l":"法令外","c":""},{"id":"2019-168","s":6,"q":"ゴキブリの生態に関する次の記述のうち、最も適当なものはどれか。","o":["チャバネゴキブリは、卵鞘(しょう)を孵(ふ)化直前まで尾端に保持し続けている。","クロゴキブリは、昼行性で、夜間はほとんど活動しない。","トビイロゴキブリは、孵化後間もない幼虫が、単独で生活する傾向が強い。","ワモンゴキブリは、動物性の食品や汚物等を餌としない。","ヤマトゴキブリは、幼虫、蛹(さなぎ)を経て成虫となる。"],"a":0,"e":"チャバネゴキブリの雌は、卵の入った卵鞘をふ化の直前までお尻の先に付けたまま持ち歩く。ほかは、ゴキブリは夜行性・幼虫は集団で生活・雑食性・蛹の時期がない(不完全変態)、が正しい。","l":"法令外","c":""},{"id":"2019-169","s":6,"q":"ダニに関する次の記述のうち、最も適当なものはどれか。","o":["マダニ類には、ヒトの皮膚内に寄生する種類がある。","ダニの体は、頭部、胸部、胴体部に分けることができる。","ツメダニ類は、他のダニやチャタテムシ等を捕食することが知られている。","ワクモは、室内塵(じん)中の有機物を餌として発育する。","イエダニは、野鳥に寄生し、吸血する。"],"a":2,"e":"ツメダニ類は、ほかのダニやチャタテムシなどを捕まえて食べる。ヒトの皮膚内に寄生するのはヒゼンダニ、ダニの体は顎体部と胴体部に分かれる、ワクモは鳥から吸血する、イエダニはネズミに寄生する。","l":"法令外","c":""},{"id":"2019-170","s":6,"q":"害虫に関する次の記述のうち、最も不適当なものはどれか。","o":["ニセケバエ類は、鉢植の肥料に用いられる油粕(かす)などから発生する。","ネコノミは、イヌにも寄生する。","ツマアカスズメバチは、特定外来生物に指定されている。","シバンムシアリガタバチの成虫は、乾燥食品や建築材料を餌とする。","トコジラミは、夜間吸血性である。"],"a":3,"e":"シバンムシアリガタバチは、シバンムシ類の幼虫に寄生するハチで、乾燥食品や建材を食べるわけではない(人を刺すことがある)。乾燥食品などを食べるのはシバンムシのほうである。","l":"特定外来生物による生態系等に係る被害の防止に関する法律 第2条、同法施行令 第1条・別表第一(選択肢3)","c":""},{"id":"2019-171","s":6,"q":"下記の①から④の特徴をすべて有する殺虫剤は、次のうちどれか。\n① 抵抗性を獲得した害虫集団の存在が知られている。\n② 基礎的な効力は、IC50値により評価される。\n③ 昆虫などの節足動物以外の生物に対する影響が少ない。\n④ 成虫に対する致死効力はない。","o":["ピレスロイド剤","昆虫成長制御剤(IGR)","対称型有機リン剤","非対称型有機リン剤","カーバメート剤"],"a":1,"e":"IGRは脱皮や変態をじゃまする薬剤で、昆虫以外への影響が少なく、成虫は殺さない。効力は50%羽化阻害濃度(IC50)で評価し、抵抗性をもつ集団も知られている。","l":"法令外","c":""},{"id":"2019-172","s":6,"q":"殺虫剤やその有効成分に関する次の記述のうち、最も適当なものはどれか。","o":["メトフルトリンは、常温揮散でも効力を発揮する。","ULV処理には、専用の油剤を使用する。","ジフルベンズロンは、幼若ホルモン様化合物である。","乳剤は、煙霧処理に使用される。","KT50の値が小さいほど、致死効力が高い。"],"a":0,"e":"メトフルトリンは常温でも揮発して効くピレスロイドである。ULVには専用の水性乳剤を使う、ジフルベンズロンは表皮形成阻害剤、煙霧には油剤を使う、KT50が小さいのは速効性が高いことを示す。","l":"法令外","c":""},{"id":"2019-173","s":6,"q":"ネズミの生態に関する次の記述のうち、最も不適当なものはどれか。","o":["ねずみ類は、多くの場合移動する通路が一定で、体の汚れが通路となる壁や配管に付着する。","クマネズミは、動物質の餌を好む。","ドブネズミの尾は、体長より短い。","クマネズミは運動能力に優れ、ロープを伝わって船舶から上陸することができる。","ドブネズミは泳ぎが得意なので、水洗便所の排水管を通って侵入することがある。"],"a":1,"e":"クマネズミは穀物や種子など植物質の餌を好む。動物質の餌を好むのはドブネズミである。","l":"法令外","c":""},{"id":"2019-174","s":6,"q":"ねずみ用の薬剤に関する次の記述のうち、最も不適当なものはどれか。","o":["ブロマジオロン製剤は、動物用医薬部外品として承認されている。","ジフェチアロールは、第2世代の抗凝血性殺鼠(そ)剤である。","粉剤は、餌材料にまぶして、毒餌として利用することができる。","リン化亜鉛は、致死させるために、複数回摂取させる必要がある。","カプサイシンは、忌避剤で、かじり防止などの目的で使用される。"],"a":3,"e":"リン化亜鉛は急性殺鼠剤で、1回食べただけで効く。何回も食べさせる必要があるのは、第1世代の抗凝血性殺鼠剤である。","l":"法令外","c":""},{"id":"2019-175","s":6,"q":"ねずみ用の薬剤に関する次の記述のうち、最も不適当なものはどれか。","o":["殺鼠(そ)剤により死亡したネズミから、ハエなどが発生することがある。","配置された毒餌から、シバンムシ類などの食品害虫が発生することがある。","クマテトラリルは、第1世代の抗凝血性殺鼠剤である。","シクロヘキシミドには、処理区域からネズミを追い出す効果はない。","ドブネズミでは、抗凝血性殺鼠剤に対する抵抗性を獲得した集団は報告されていない。"],"a":4,"e":"ワルファリンなどの抗凝血性殺鼠剤が効かない抵抗性のドブネズミの集団は、すでに報告されている(クマネズミでも知られている)。","l":"法令外","c":""},{"id":"2019-176","s":6,"q":"衛生害虫と疾病に関する次の記述のうち、最も不適当なものはどれか。","o":["トコジラミが疾病媒介に直接関わっている事例は、知られていない。","ねずみ類は、レプトスピラ症の媒介動物である。","コガタアカイエカは、ジカウイルス感染症を媒介する。","アカイエカは、ウエストナイル熱を媒介する。","アシナガバチによる刺症は、アナフィラキシーショックの原因となる。"],"a":2,"e":"ジカウイルス感染症を媒介するのは、ネッタイシマカやヒトスジシマカなどのヤブカ類である。コガタアカイエカは日本脳炎を媒介する。","l":"法令外","c":""},{"id":"2019-177","s":6,"q":"殺虫剤・殺鼠(そ)剤に関する次の記述のうち、最も不適当なものはどれか。","o":["昆虫の変態等の生理的な変化に影響を与え、その他の生物に影響が小さい薬剤が防除に利用されている。","有効成分の毒性と安全性は、医薬品、医療機器等の品質、有効性及び安全性の確保等に関する法律によって定められた基準によりチェックされている。","毒薬に該当する衛生害虫用の殺虫剤はない。","ある殺虫剤の毒性がヒト又は動物と昆虫の間であまり変わらないことを、選択毒性が高いと表現する。","薬剤の安全性は、毒性の強弱や摂取量等によって決まる。"],"a":3,"e":"ヒトや動物と昆虫とで毒性があまり変わらないのは、選択毒性が「低い」状態である。昆虫には強く効き、ヒトには効きにくいことを選択毒性が高いという。","l":"法令外","c":""},{"id":"2019-178","s":6,"q":"建築物衛生法に基づく特定建築物内のねずみ等の防除に関する次の記述のうち、最も適当なものはどれか。","o":["環境的対策は、特定建築物維持管理権原者のもとで当該区域の管理者が日常的に行う。","食料取扱い区域などのねずみ等が発生しやすい場所では、6カ月以内ごとに発生状況調査を実施する。","調査は、目視調査や聞取り調査を重点的に行い、トラップ調査は実施しなくてよい。","IPM(総合的有害生物管理)における「警戒水準」とは、すぐに防除作業が必要な状況をいう。","IPMに基づくねずみ等の防除では、定期的・統一的な薬剤処理を行う。"],"a":0,"e":"整理整頓や清掃などの環境的対策は、権原者のもとで各区域の管理者が日常的に行う。ほかは、発生しやすい場所は2か月以内ごとに調査、トラップ調査も行う、すぐ防除が必要なのは「措置水準」、薬剤は必要なときに使う、が正しい。","l":"建築物衛生法施行規則 第4条の5第2項、平成15年厚生労働省告示第119号 第6","c":""},{"id":"2019-179","s":6,"q":"ねずみ・昆虫等及び鳥類の防除に関する次の記述のうち、最も不適当なものはどれか。","o":["ドバトの捕獲や卵の除去を行う際は、自治体等の長の許可が必要である。","ネズミと昆虫では、薬剤抵抗性の発達の原理が異なる。","ネッタイトコジラミは、近年、東京都内の宿泊施設でも散見されている。","防除は、発生時対策より発生予防対策に重点を置いて実施する。","吸血昆虫を対象にした人体用忌避剤として、イカリジンがある。"],"a":1,"e":"ネズミも昆虫も、同じ薬剤を使い続けると効きにくい個体が生き残って増えるという、同じしくみで抵抗性が発達する。","l":"鳥獣の保護及び管理並びに狩猟の適正化に関する法律 第8条・第9条(選択肢1)","c":""},{"id":"2019-180","s":6,"q":"ねずみの建物侵入防止のための防鼠(そ)構造に関する次の記述のうち、最も不適当なものはどれか。","o":["建物の土台である基礎は、地下60cm以上の深さまで入れる。","外壁には、ツタ等の植物を這(は)わせたり、樹木の枝を接触させない。","床の通風口や換気口には、目の大きさ2cm以下の金網格子を設置する。","1階の窓の下端と地表との距離は、90cm以上離す。","ドアの上部、側部、底部の隙間は、1cm以内とする。"],"a":2,"e":"ネズミは2cmのすき間なら通り抜けられるので、通風口や換気口の金網の目は1cm以下にする(2018年問174でも1cm以下が正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-1","s":0,"q":"日本国憲法第25条の次の文の(ア)〜(エ)に入る語句の組合せとして、正しいものはどれか。\n「すべて国民は、( ア )で文化的な最低限度の生活を営む権利を有する。② 国は、すべての( イ )について、社会福祉、( ウ )及び( エ )の向上及び増進に努めなければならない。」","o":["ア 健康　イ 国民　ウ 生活環境　エ 環境衛生","ア 健康　イ 生活部面　ウ 社会保障　エ 公衆衛生","ア 健全　イ 国民　ウ 生活環境　エ 公衆衛生","ア 健全　イ 国民　ウ 社会保障　エ 公衆衛生","ア 健全　イ 生活部面　ウ 社会保障　エ 環境衛生"],"a":1,"e":"憲法第25条は「健康で文化的な最低限度の生活」を保障し、国は「すべての生活部面について、社会福祉、社会保障及び公衆衛生の向上及び増進」に努めると定めている。","l":"日本国憲法 第25条","c":""},{"id":"2020-2","s":0,"q":"現在の衛生行政の組織について、最も適当なものはどれか。","o":["地方で建築基準法を執行する特定行政庁は、都道府県と、建築主事を置く市町村・特別区である。","学校保健行政の地方の事務は、私立学校も含めて、都道府県と市町村の教育委員会が責任を負っている。","労働衛生行政は、国は厚生労働省、地方は都道府県が分担して行っている。","下水道行政は国土交通省の所管だが、終末処理場の維持管理は厚生労働省の所管である。","保健所の数を設置する自治体別にみると、政令市が設置する保健所が最も多い。"],"a":0,"e":"特定行政庁は、建築主事を置く市町村・特別区の長と、それ以外の区域の都道府県知事である。私立学校は都道府県知事、労働衛生は都道府県労働局、終末処理場の維持管理は環境省が受け持つ。","l":"建築基準法 第2条第35号","c":""},{"id":"2020-3","s":0,"q":"次の建築物のうち、特定建築物に当たらないものはどれか。","o":["延べ面積7,000m²の幼稚園","延べ面積5,000m²の自動車学校","延べ面積10,000m²の特別支援学校","延べ面積6,000m²の予備校","延べ面積9,000m²の幼保連携型認定こども園"],"a":0,"e":"幼稚園は学校教育法第1条の学校なので、特定建築物になるのは延べ面積8,000m²以上の場合である。7,000m²では当たらない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2020-4","s":0,"q":"次の複合用途の建築物について、正しいものはどれか。なお、A〜D社はお互いに関係がない。\n【建物の内訳】A社の学習塾 900m²、B社の銀行 1,500m²、A社とB社の共用地下駐車場 500m²、B社の倉庫 100m²、C社のトランクルーム(貸倉庫) 300m²、D社の保育施設 700m²","o":["特定用途に使われる部分の延べ面積は4,000m²で、特定建築物に当たる。","特定用途に使われる部分の延べ面積は3,300m²で、特定建築物に当たる。","特定用途に使われる部分の延べ面積は3,000m²で、特定建築物に当たる。","特定用途に使われる部分の延べ面積は2,900m²で、特定建築物に当たらない。","特定用途に使われる部分の延べ面積は2,400m²で、特定建築物に当たらない。"],"a":2,"e":"学習塾900+銀行1,500+共用駐車場500+銀行の倉庫100=3,000m²。トランクルーム(貸倉庫)と保育施設は特定用途に含まれない。3,000m²以上なので特定建築物に当たる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2020-5","s":0,"q":"特定建築物の届出に書く事項として、建築物衛生法施行規則に定められていないものはどれか。","o":["特定建築物所有者等の氏名と住所","特定建築物維持管理権原者の氏名と住所","特定用途に使われる部分の延べ面積","建築物環境衛生管理技術者の氏名と住所","特定建築物の竣工年月日"],"a":4,"e":"届け出るのは「特定建築物が使用されるに至った年月日」であり、竣工年月日は届出事項にない。","l":"建築物衛生法施行規則 第1条","c":""},{"id":"2020-6","s":0,"q":"備えておく帳簿書類と、その保存期間の組合せとして、最も適当なものはどれか。","o":["維持管理の年間管理計画書 ― 1年間","空気環境測定の結果 ― 2年間","ねずみ等の防除の記録 ― 3年間","臨時に行った水質検査の結果 ― 5年間","空調ダクトの系統を示した図面 ― 5年間"],"a":3,"e":"測定・検査の結果など維持管理の状況を書いた帳簿書類は5年間保存する。臨時の水質検査の結果も同じ。図面には保存期間の定めがない。","l":"建築物衛生法施行規則 第20条","c":""},{"id":"2020-7","s":0,"q":"空気環境の測定方法について、最も不適当なものはどれか。","o":["二酸化炭素の含有率を、検知管方式の二酸化炭素測定器で測った。","温度を、0.5度目盛の温度計で測った。","気流を、0.2m/秒以上の気流を測れる風速計で測った。","相対湿度を、0.5度目盛の乾湿球湿度計で測った。","浮遊粉じんの量を、経済産業大臣の登録を受けた者が較正した機器で測った。"],"a":4,"e":"浮遊粉じんの測定機器を較正するのは、厚生労働大臣の登録を受けた者である。","l":"建築物衛生法施行規則 第3条の2","c":""},{"id":"2020-8","s":0,"q":"特定建築物の給排水設備の維持管理について、最も不適当なものはどれか。","o":["修景(水景)に使う雑用水について、残留塩素・濁度・臭気・外観は毎日、pH値と大腸菌は1か月に1回検査している。","施行規則第4条に定める16項目の飲料水の水質検査を、6か月ごとに行っている。","飲料水の残留塩素を、給水栓の末端で毎日測っている。","貯水槽と貯湯槽の清掃を、1年に1回、定期に行っている。","排水槽の清掃を、4か月ごとに行っている。"],"a":0,"e":"散水・修景・清掃用の雑用水は、pH値・臭気・外観・遊離残留塩素を7日以内ごとに1回検査しなければならず、pH値を1か月に1回では足りない(大腸菌・濁度は2か月以内ごとに1回)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2020-9","s":0,"q":"建築物環境衛生管理技術者免状について、誤っているものはどれか。","o":["厚生労働大臣は、免状をもつ人が建築物衛生法に違反したときは、免状の返納を命じることができる。","免状を破ったり、汚したり、なくしたりしたときは、厚生労働大臣に再交付を申請できる。","免状をもつ人が亡くなったときは、戸籍法の届出義務者が1年以内に、免状を廃棄したことを厚生労働大臣に報告する。","厚生労働大臣は、免状の返納を命じられ、その日から1年を過ぎていない人には、免状を交付しないことができる。","免状の記載事項が変わったときは、厚生労働大臣に書換え交付を申請できる。"],"a":2,"e":"正しくは、届出義務者は「1か月以内」に、免状を廃棄したことを厚生労働大臣に報告する。","l":"建築物衛生法 第7条、施行規則 第11条〜第13条","c":"出題時の選択肢(3)は「1年以内に免状を返還する」だったが、2026年1月ごろ施行の施行規則改正で「1か月以内に免状を廃棄した旨を報告する」に変わったため、期間の誤りはそのままに今の言い方に直した。選択肢(5)は「本籍地を変更した場合」を、条文どおり「記載事項が変わったとき」とした(正答は変わらない)。"},{"id":"2020-10","s":0,"q":"建築物清掃業の登録に必要な、従事者の研修について、最も不適当なものはどれか。","o":["アルバイトも研修を受ける必要がある。","従事者全員が、原則として1年に1回以上研修を受けられる体制が必要である。","カリキュラムの参考例が、厚生労働省の通知で示されている。","研修の実施主体について定められている。","従事者全員の研修は、一度に行わなければならない。"],"a":4,"e":"研修は従事者全員が受けられるものであればよく、全員を一度に集めて行う必要はない。","l":"建築物衛生法施行規則 第25条第3号","c":""},{"id":"2020-11","s":0,"q":"国や地方公共団体が使う特定建築物に適用される事項として、誤っているものはどれか。","o":["都道府県知事等による資料の提出の要求","特定建築物の届出","都道府県知事等による改善命令","建築物環境衛生管理基準を守ること","建築物環境衛生管理技術者の選任"],"a":2,"e":"国や地方公共団体の特定建築物には、改善命令の規定は適用されない。その代わりに、都道府県知事等は必要な措置をとるよう勧告できる。","l":"建築物衛生法 第13条","c":""},{"id":"2020-12","s":0,"q":"感染症法で、医師が診断した後に都道府県知事に「直ちに」届け出なければならない感染症として、誤っているものはどれか。","o":["ラッサ熱","百日咳","コレラ","急性灰白髄炎","デング熱"],"a":1,"e":"百日咳は五類感染症で、届出は7日以内でよい。ラッサ熱(一類)、急性灰白髄炎(二類)、コレラ(三類)、デング熱(四類)は直ちに届け出る。","l":"感染症法 第12条","c":""},{"id":"2020-13","s":0,"q":"地域保健法にもとづく保健所の事業として、最も適当なものはどれか。","o":["社会福祉に関する考え方の普及と向上","精神保健に関すること","介護認定に関すること","水道・下水道・廃棄物の処理・清掃その他の環境の保全に関すること","児童虐待の防止に関すること"],"a":1,"e":"精神保健に関する事項は、地域保健法で保健所の事業として定められている。環境については「環境の衛生」が保健所の事業である。","l":"地域保健法 第6条","c":""},{"id":"2020-14","s":0,"q":"学校保健安全法の学校環境衛生基準で、教室等の環境の検査項目に含まれないものはどれか。","o":["照度","換気","騒音レベル","振動レベル","温度"],"a":3,"e":"教室等の環境の検査項目には、換気・温度・照度・騒音レベルなどがあるが、振動レベルは含まれない。","l":"学校環境衛生基準(学校保健安全法 第6条)","c":""},{"id":"2020-15","s":0,"q":"旅館業法施行令の旅館・ホテル営業の施設の基準について、誤っているものはどれか。","o":["宿泊しようとする人と面接するのに適した玄関帳場などがあること。","適当な換気・採光・照明・防湿・排水の設備があること。","客室の数は5室以上であること。","寝台を置く客室の床面積は、9m²以上であること。","善良の風俗が害されるような文書・図面などを、施設に掲示したり備え付けたりしないこと。"],"a":2,"e":"旅館・ホテル営業の施設の基準には、客室の数の最低限の定めはない(平成30年の改正で廃止された)。","l":"旅館業法施行令 第1条","c":""},{"id":"2020-16","s":0,"q":"水質汚濁防止法について、誤っているものはどれか。","o":["特定施設のある事業場(特定事業場)から出る水を、排水基準以下の濃度で排水することを義務づけている。","公共用水域への排出とは、川・湖・海などへの排出のことで、下水道に出す場合は含まない。","都道府県は、条例で国の排水基準より厳しい基準を定めることができる。","規制の対象は工場・事業場から公共用水域に出る排水だけで、地下への水の浸透は含まない。","1日の平均排水量が50m³以上のホテルは、水質汚濁防止法の特定事業場である。"],"a":3,"e":"水質汚濁防止法は、公共用水域への排出に加えて、地下への水の浸透も規制している。","l":"水質汚濁防止法 第1条、第12条の3","c":""},{"id":"2020-17","s":0,"q":"悪臭防止法の特定悪臭物質に当たらないものはどれか。","o":["アンモニア","ホルムアルデヒド","硫化水素","トルエン","メチルメルカプタン"],"a":1,"e":"ホルムアルデヒドは特定悪臭物質(22物質)に含まれない。","l":"悪臭防止法施行令 第1条","c":""},{"id":"2020-18","s":0,"q":"労働安全衛生法の労働災害防止の定めについて、誤っているものはどれか。","o":["厚生労働大臣は、労働災害防止計画をつくらなければならない。","事業者は、規模に応じて総括安全衛生管理者を選任しなければならない。","事業者は、業種と規模に応じて安全委員会を設けなければならない。","都道府県知事は、重大な労働災害が起きた場合、事業者に特別安全衛生改善計画をつくるよう指示できる。","安全委員会の委員には、その事業場の労働者で、事業者が指名した人が含まれなければならない。"],"a":3,"e":"特別安全衛生改善計画の作成を指示するのは、都道府県知事ではなく厚生労働大臣である。","l":"労働安全衛生法 第78条","c":""},{"id":"2020-19","s":0,"q":"平成30年の健康増進法の改正についての次の文の(ア)〜(ウ)に入る語句の組合せとして、正しいものはどれか。\n「平成30年の健康増進法の改正では( ア )の( イ )の強化が行われ、原則として学校・病院・児童福祉施設での( ウ )の禁煙の徹底が図られている。」","o":["ア 能動喫煙　イ 削減　ウ 敷地内","ア 能動喫煙　イ 防止　ウ 屋内","ア 受動喫煙　イ 防止　ウ 屋内","ア 受動喫煙　イ 防止　ウ 敷地内","ア 受動喫煙　イ 削減　ウ 屋内"],"a":3,"e":"平成30年の改正で受動喫煙の防止が強化され、学校・病院・児童福祉施設などの第一種施設は原則「敷地内禁煙」となった。","l":"健康増進法 第29条","c":""},{"id":"2020-20","s":0,"q":"次の国際的な取り決めのうち、主に廃棄物対策に関するものはどれか。","o":["モントリオール議定書","ラムサール条約","ワシントン条約","パリ協定","バーゼル条約"],"a":4,"e":"バーゼル条約は、有害廃棄物の国境を越える移動と処分を規制する条約である。","l":"法令外","c":""},{"id":"2020-21","s":1,"q":"体の臓器系と、それに属する臓器・組織の組合せとして、最も不適当なものはどれか。","o":["造血器系 ― 脾臓","内分泌系 ― 下垂体","呼吸器系 ― 肺","神経系 ― 甲状腺","循環器系 ― 毛細血管"],"a":3,"e":"甲状腺はホルモンを出す内分泌系の器官である。","l":"法令外","c":""},{"id":"2020-22","s":1,"q":"体温調節について、次の文の(ア)〜(ウ)に入る語句の組合せとして、最も適当なものはどれか。\n「体は熱をつくる量(産熱)と逃がす量(放熱)のつり合いを保ち、体温を一定にしている。産熱は( ア )の増進などで制御される。放熱は( イ )、( ウ )、皮下組織による熱の遮断などで調節される。」","o":["ア 消化　イ 呼吸　ウ 神経興奮","ア 発汗　イ 筋収縮　ウ 神経興奮","ア 発汗　イ 呼吸　ウ 内分泌","ア 基礎代謝　イ 尿産生　ウ 血液循環","ア 基礎代謝　イ 呼吸　ウ 血液循環"],"a":4,"e":"産熱は基礎代謝の増進などで、放熱は呼吸・血液循環・皮下組織の熱遮断などで調節される。","l":"法令外","c":""},{"id":"2020-23","s":1,"q":"ふつうの室内で、体の各部位の温度を低い順に並べたものとして、最も適当なものはどれか。","o":["顔 < 直腸 < 足","顔 < 足 < 直腸","直腸 < 顔 < 足","足 < 直腸 < 顔","足 < 顔 < 直腸"],"a":4,"e":"手足の先は外気の影響を受けて最も低く、顔は手足より高い。体の内部の温度(核心温)を表す直腸温が最も高い。","l":"法令外","c":""},{"id":"2020-24","s":1,"q":"熱中症予防の指標となる暑さ指数(WBGT)について、次の文の(ア)(イ)に入る語句の組合せとして、正しいものはどれか。\n「WBGTは、屋内や屋外で日射がない場合、0.7TA+0.3TBで求める。ただし、TAは( ア )、TBは( イ )である。」","o":["ア 黒球温度　イ 湿球温度","ア 湿球温度　イ 乾球温度","ア 湿球温度　イ 黒球温度","ア 乾球温度　イ 黒球温度","ア 乾球温度　イ 湿球温度"],"a":2,"e":"日射がない場合のWBGTは、0.7×(自然)湿球温度+0.3×黒球温度で求める。","l":"法令外","c":""},{"id":"2020-25","s":1,"q":"温熱条件の快適さについて、最も不適当なものはどれか。","o":["温冷感は心理的な反応で、人の主観的な評価による指標である。","快適感は、核心温の状態に関係なく一定である。","一般に、平均皮膚温が33〜34℃のときに、暑くも寒くもない(温熱的中性)という申告が得られる。","温熱的快適感とは、熱環境に満足していると表せる心の状態をいう。","快適感の尺度は、外国でつくられたものを日本語に訳して使っているものが多く、言語による違いが生じる。"],"a":1,"e":"快適感は核心温の状態によって変わる。たとえば体温が高いときは冷たい刺激を、低いときは暖かい刺激を快く感じる。","l":"法令外","c":""},{"id":"2020-26","s":1,"q":"熱中症についての次の文で、下線(番号つき)の語句のうち最も不適当なものはどれか。\n「熱失神は、皮膚の血管が広がって血圧が下がり、(1)脳血流が減少して起こる。熱けいれんは、汗で(2)塩分が失われ、その後(3)水分だけを大量にとることで起こる。熱疲労は、細胞外液の浸透圧が上がって、細胞内の(4)水分増加が起こることで生じる。熱射病は、(5)体温調節中枢の障害が起こることで生じる。」","o":["脳血流が減少","塩分","水分","水分増加","体温調節中枢の障害"],"a":3,"e":"細胞外液の浸透圧が上がると、細胞内の水分は外へ引き出されるので、起こるのは細胞内の「水分増加」ではなく脱水(水分減少)である。","l":"法令外","c":""},{"id":"2020-27","s":1,"q":"湿度と加湿について、最も不適当なものはどれか。","o":["湿度が高いと、風邪などの呼吸器の病気にかかりやすくなる。","湿度が高いと、結露してカビやダニが発生する。","湿度が低いと、静電気が起きやすくなる。","湿度が低いと、ほこりが舞い上がりやすくなる。","水に混ざった真菌(カビ)が、加湿のときにエアロゾルとして放出されることがある。"],"a":0,"e":"風邪などの呼吸器の病気にかかりやすくなるのは、湿度が低いときである。","l":"法令外","c":""},{"id":"2020-28","s":1,"q":"酸素欠乏についての次の文の(ア)(イ)に入る数値の組合せとして、正しいものはどれか。\n「酸素欠乏症等防止規則では、空気中の酸素濃度が( ア )%未満の状態を酸素欠乏と定義している。また、空気中の酸素濃度が( イ )%以下になると、意識障害やけいれんが起こる。」","o":["ア 20　イ 18","ア 20　イ 16","ア 18　イ 16","ア 18　イ 10","ア 16　イ 10"],"a":3,"e":"酸欠則では酸素濃度18%未満を酸素欠乏と定義している。酸素濃度が10%以下になると、意識障害やけいれんが起こる。","l":"酸素欠乏症等防止規則 第2条","c":""},{"id":"2020-29","s":1,"q":"ヒトが不快感を覚えるとされる室内の二酸化炭素濃度として、最も適当なものはどれか。","o":["0.5%","1〜2%","3〜4%","6%","7〜10%"],"a":1,"e":"二酸化炭素濃度が1〜2%になると不快感が起こり、3〜4%で頭痛・めまい・血圧上昇、7〜10%で数分で意識不明となる。","l":"法令外","c":""},{"id":"2020-30","s":1,"q":"アスベストについて、最も不適当なものはどれか。","o":["自然界にある、繊維状の水和したケイ酸塩鉱物をまとめた呼び名である。","過去には断熱材として使われた。","吸いこむと、肺の線維化を起こす。","健康障害は、アスベスト製品をつくる工場の従業員だけに起こる。","悪性中皮腫の原因になる。"],"a":3,"e":"アスベストによる健康障害は、製造工場の従業員に限らず、解体工事の作業者や周辺の住民などにも起こっている。","l":"法令外","c":""},{"id":"2020-31","s":1,"q":"ホルムアルデヒドについて、最も不適当なものはどれか。","o":["常温では気体である。","酸化力が強い。","水やアルコールに溶けやすい。","たばこの煙の中にある。","粘膜への刺激が強い。"],"a":1,"e":"ホルムアルデヒドは酸化されやすい物質で、強い「還元力」をもつ。酸化力が強いのではない。","l":"法令外","c":""},{"id":"2020-32","s":1,"q":"室内の空気汚染と健康障害の組合せとして、最も不適当なものはどれか。","o":["レジオネラ属菌 ― 肺がん","二酸化窒素 ― 慢性気管支炎","オゾン ― 肺気腫","ホルムアルデヒド ― 喘息のような気管支炎","ハウスダスト ― アレルギー性疾患"],"a":0,"e":"レジオネラ属菌が起こすのは、レジオネラ肺炎などの感染症であり、肺がんではない。","l":"法令外","c":""},{"id":"2020-33","s":1,"q":"聴覚について、最も不適当なものはどれか。","o":["年をとると、低い周波数から聴力が落ちる。","超低周波空気振動とは、周波数が低くてヒトが聞きとれないものをいう。","音の感覚の3要素は、音の大きさ・高さ・音色である。","中耳は、鼓膜・耳小骨・鼓室・耳管などでできている。","最も敏感な周波数は、4,000Hz付近である。"],"a":0,"e":"加齢による聴力の低下は、高い周波数の音から始まる。","l":"法令外","c":""},{"id":"2020-34","s":1,"q":"振動について、最も不適当なものはどれか。","o":["全身振動を感じることには、内耳の前庭器官と三半規管が関係している。","振動は、皮膚・内臓・関節など全身にある運動神経の末端の受容器で感じとられる。","全身振動の大きさの感じ方は、振動が続く時間によって変わる。","振動レベルの単位は、dB(デシベル)である。","白ろう病は、手で持つ振動工具による指の血行障害である。"],"a":1,"e":"振動を感じとるのは、全身に分布する「知覚神経」の末端の受容器である。運動神経ではない。","l":"法令外","c":""},{"id":"2020-35","s":1,"q":"発光ダイオード(LED)の性質について、最も不適当なものはどれか。","o":["小さくて軽い。","熱に弱い。","光が広がりやすい(拡散しやすい)。","寿命が長い。","効率が高い。"],"a":2,"e":"LEDの光は指向性が強く、一定の方向に進みやすい。光が広がりやすい(拡散しやすい)という性質ではない。","l":"法令外","c":""},{"id":"2020-36","s":1,"q":"情報機器作業(VDT作業)と健康について、最も不適当なものはどれか。","o":["まぶしさ(グレア)を防ぐ照明器具を使う。","ディスプレイ画面の上の照度は、500lx以下にする。","キーボードの上の照度は、300lx以上にする。","デスクトップ型とノート型のパソコンでは、デスクトップ型のほうが疲れの訴えが多い。","目と画面、目と書類などの距離は、同じくらいにするのが望ましい。"],"a":3,"e":"ノート型パソコンは画面とキーボードが一体で姿勢の自由が少ないため、デスクトップ型より疲れの訴えが多い。","l":"法令外","c":""},{"id":"2020-37","s":1,"q":"赤外線による体への影響として、最も不適当なものはどれか。","o":["熱中症","皮膚の血流をよくする","電気性眼炎","ガラス工白内障","代謝をうながす"],"a":2,"e":"電気性眼炎は、溶接のアークなどから出る紫外線による目の炎症であり、赤外線の影響ではない。","l":"法令外","c":""},{"id":"2020-38","s":1,"q":"電離放射線について、最も適当なものはどれか。","o":["γ線は、鉛や鉄の板を通り抜ける。","放射線が体に与える影響の単位は、Bq(ベクレル)である。","放射線の健康影響のうち、がんへの影響には閾値がある。","胸のX線検査1回で受ける線量は、自然放射線から1年間に受ける線量の世界平均より多い。","放射線の影響を最も受けやすい細胞は、リンパ球である。"],"a":4,"e":"放射線の感受性が最も高い細胞はリンパ球である。体への影響の単位はSv(シーベルト)、がんは閾値のない確率的影響とされる。","l":"法令外","c":""},{"id":"2020-39","s":1,"q":"放射線障害を防ぐ対策の組合せとして、最も不適当なものはどれか。","o":["体内被曝の防護 ― 被曝時間を短くする","個人の被曝線量の管理 ― フィルムバッジを使う","体外被曝の防護 ― 遮蔽","環境管理 ― 環境モニタリング","個人の健康管理 ― 健康診断"],"a":0,"e":"被曝時間を短くすることは、体の外からの被曝(体外被曝)を防ぐ方法である。体内被曝は、放射性物質を体に取りこまないことで防ぐ。","l":"法令外","c":""},{"id":"2020-40","s":1,"q":"ヒトの水の出入りや不足について、最も不適当なものはどれか。","o":["成人のふだんの状態では、1日に失う水は2,500mLである。","成人のふだんの状態では、呼吸で失う水分量は、失う水全体の約1/6である。","水分の不足が体重の1%を超えると、のどの渇きが起こる。","水分の不足が体重の5%を超えると、筋肉のけいれんが起こる。","水分の不足が体重の20%を超えると、死亡する。"],"a":3,"e":"筋肉のけいれんが起こるのは、水分の不足が体重の10〜12%程度になったときである(2025年度問41の選択肢でも、10〜12%の欠乏で筋けいれんとされている)。","l":"法令外","c":""},{"id":"2020-41","s":1,"q":"飲み水の汚染事故の原因として、最も不適当なものはどれか。","o":["ノロウイルス","アニサキス","カンピロバクター・ジェジュニ","病原性大腸菌","赤痢アメーバ"],"a":1,"e":"アニサキスは、生の魚介類を食べることで感染する寄生虫で、飲み水の汚染事故の原因にはならない。","l":"法令外","c":""},{"id":"2020-42","s":1,"q":"水道法の水質基準にある物質と、それによる病気の組合せとして、最も不適当なものはどれか。","o":["ヒ素 ― ボーエン病","亜硝酸態窒素 ― メトヘモグロビン血症","四塩化炭素 ― 肝がん","ベンゼン ― 再生不良性貧血","フッ素 ― 舌がん"],"a":4,"e":"フッ素の過剰摂取で起こるのは、斑状歯(歯のフッ素症)や骨フッ素症であり、舌がんではない。","l":"法令外","c":""},{"id":"2020-43","s":1,"q":"感染症法の類型のうち、一類・二類・三類のすべてで行われる措置として、最も不適当なものはどれか。","o":["健康診断を受けるよう勧告すること","就業制限","死体の移動制限","入院の勧告","積極的疫学調査"],"a":3,"e":"入院の勧告は一類・二類感染症などが対象で、三類感染症では行われない。","l":"感染症法 第19条、第26条","c":""},{"id":"2020-44","s":1,"q":"クリプトスポリジウム症とその病原体について、最も不適当なものはどれか。","o":["感染したほ乳類のふん便が感染源となる。","大きさ4〜6μmの原虫である。","感染すると、2〜5日後に下痢や腹痛などの症状が出る。","特定の環境では、2〜6か月間感染力を保つ。","対策として、給水栓の末端の遊離残留塩素濃度を0.2mg/L以上に保つことが大切である。"],"a":4,"e":"クリプトスポリジウムは塩素に強く、通常の塩素消毒では不活化できない。対策としては、ろ過や紫外線処理などが用いられる。","l":"法令外","c":""},{"id":"2020-45","s":1,"q":"消毒薬について、最も不適当なものはどれか。","o":["クレゾールは、食器の消毒には向いていない。","逆性石けんは、緑膿菌や結核菌に対する殺菌力が弱い。","ホルマリンは、すべての微生物に有効である。","消毒用エタノールは、一部のウイルスには効かない。","次亜塩素酸ナトリウムは、芽胞にも有効である。"],"a":4,"e":"次亜塩素酸ナトリウムは、芽胞には効果が期待できない(2022年度問45でも「芽胞には効果がない」が正しい記述とされている)。","l":"法令外","c":""},{"id":"2020-46","s":2,"q":"用語と単位の組合せのうち、誤っているものはどれか。","o":["輝度 ― cd/m³","熱伝達抵抗 ― m²・K/W","音の強さ ― W/m²","吸音力 ― m²","比熱 ― kJ/(kg・K)"],"a":0,"e":"輝度は見かけの面積あたりの光度なので、単位はcd/m²(2023年度問46でも正しい組合せ)。m³ではない。","l":"法令外","c":""},{"id":"2020-47","s":2,"q":"冬の結露についての次のア〜ウの文の[(1)]〜[(5)]の語句のうち、最も不適当なものはどれか。\nア ふつう室内では、空気中の絶対湿度の場所によるばらつきは[(1)比較的小さい]。そのため、局所的に温度が低い場所があると、そこでの飽和水蒸気圧が[(2)低下し]、結果として結露が起きる。\nイ 窓の[(3)アルミサッシ]や断熱材が切れている場所などで[(4)熱橋]ができ、局所的に結露が起きやすくなる。\nウ 内部結露を防ぐ方法としては、断熱層の[(5)室外側]に防湿層を設ける方法が一般的である。","o":["比較的小さい","低下し","アルミサッシ","熱橋","室外側"],"a":4,"e":"防湿層は、水蒸気圧の高い室内側(断熱層の室内側)に設ける(2021年度問47・2024年度問49でも正しい記述)。","l":"法令外","c":""},{"id":"2020-48","s":2,"q":"熱移動の用語と、その値に影響する要因の組合せとして、最も不適当なものはどれか。","o":["放射熱伝達率 ― 材料の色","対流熱伝達率 ― 境界層の外の風速","中空層の熱抵抗 ― 熱の流れる方向","熱伝導率 ― 材料の密度","熱貫流抵抗 ― 固体壁の厚さ"],"a":0,"e":"放射熱伝達率にかかわる長波長放射率は、目に見える色ではほとんど変わらない(白色ペイントも長波長放射率は大きい。2022年度問48参照)。色が影響するのは日射吸収率である。","l":"法令外","c":""},{"id":"2020-49","s":2,"q":"流体について述べた次の文のうち、最も不適当なものはどれか。","o":["ダクト内の気流の静圧と動圧の和を全圧として扱う。","ダクト内の連続の式は、流体の密度・流速・断面積の積が一定になることを意味する。","開口部の流量係数は、ふつうの窓では1.2である。","摩擦抵抗係数は、ダクト内の粗さのほか、気流のレイノルズ数によって変わる。","管内の流れは、レイノルズ数が4,000程度以上で乱流になる。"],"a":2,"e":"ふつうの窓の流量係数は0.6〜0.7程度で、1より小さい(2021年度問50でも「約1.0」が誤りとされている)。","l":"法令外","c":""},{"id":"2020-50","s":2,"q":"自然換気について述べた次の文のうち、最も不適当なものはどれか。","o":["温度差による換気量は、給気口と排気口の高さの差の平方根に比例して増える。","温度差による換気量は、室内外の空気の密度差に比例して増える。","風力による換気量は、外の風速に比例して増える。","風力による換気量は、風圧係数の差の平方根に比例して増える。","開口部の風圧係数は、正と負の値をとる。"],"a":1,"e":"換気量は圧力差の平方根に比例するので、温度差による換気量は密度差の平方根に比例する(2024年度問52でも正しい記述)。","l":"法令外","c":""},{"id":"2020-51","s":2,"q":"空気の流れについて述べた次の文のうち、最も不適当なものはどれか。","o":["吸込気流でも、吹出気流と同じように、吸込みの影響が遠くまで及ぶ。","自由噴流の中心軸速度が一定の速度まで落ちる距離を到達距離という。","自由噴流は、吹出口の近くでは中心軸速度がそのまま保たれる。","自由噴流には、吹出口から離れたところで中心軸速度が距離に反比例して減る領域がある。","吸込気流には、吹出気流のような強い指向性はない。"],"a":0,"e":"吸込みの影響は吸込口の近くに限られ、吹出しのように遠くまでは及ばない(2025年度問53でも正しい記述)。","l":"法令外","c":""},{"id":"2020-52","s":2,"q":"換気について述べた次の文のうち、最も不適当なものはどれか。","o":["置換換気は、室温より少し低い空気を床近くから供給し、天井近くで排気する方式である。","気流の性状から見た換気方式は、混合方式と一方向方式の2つに大きく分けられる。","換気回数[回/h]とは、1時間に室内に取り入れる新鮮空気(外気)の量を室の容積で割ったものである。","燃焼器具の必要換気量は、開放型燃焼器具の場合、理論廃ガス量の40倍と定められている。","第2種機械換気は、ほかに汚染空気を出してはならない汚染室に使われる。"],"a":4,"e":"第2種換気(機械給気・自然排気)は室内が正圧になり、空気が周りへ押し出される。汚染空気を外に漏らしたくない室には、負圧になる第3種換気を使う。","l":"法令外","c":""},{"id":"2020-53","s":2,"q":"冬に室内が低湿度になる原因について述べた次の文のうち、最も不適当なものはどれか。","o":["暖房期でも、パソコンやサーバなどで室温が上がり、自動制御で冷房運転になって加湿が難しくなることがある。","加湿装置の能力が足りない。","スプレー式加湿器のノズルが詰まっている。","加湿器が空調機の加熱コイルの後ろに設置されている。","設計で想定した室温より高い室温で運用している。"],"a":3,"e":"加湿器を加熱コイルの下流に置くのは標準的な配置で(2025年度問69参照)、それ自体は低湿度の原因にならない。","l":"法令外","c":""},{"id":"2020-54","s":2,"q":"浮遊粉じんについての次の文の[(1)]〜[(5)]の語句のうち、最も不適当なものはどれか。\n「建築物衛生法の測定対象となる浮遊粉じん濃度は、[(1)相対沈降径]が[(2)10μm以下]の粒子を対象に、[(3)0.15mg/m³]以下と定められており、標準となる測定法はローボリウムエアサンプラによる[(4)質量濃度測定法]である。かつては空気環境の管理項目の中で不適率の高い項目だったが、大気汚染物質の減少、禁煙・分煙などの受動喫煙対策、エアフィルタの高性能化により、不適率は[(5)10%]程度になった。」","o":["相対沈降径","10μm以下","0.15mg/m³","質量濃度測定法","10%"],"a":4,"e":"この語句が誤り(現在の浮遊粉じんの不適率は10%よりずっと低い)。(1)〜(3)は施行令第2条・施行規則第3条の2のとおり。","l":"建築物衛生法施行令 第2条、施行規則 第3条の2","c":""},{"id":"2020-55","s":2,"q":"揮発性有機化合物(VOCs)と、室内でのおもな発生源の組合せとして、最も不適当なものはどれか。","o":["アセトアルデヒド ― コンクリート","ホルムアルデヒド ― 接着剤","エチルベンゼン ― 塗料","クロルピリホス ― 防蟻剤","フタル酸ジ-2-エチルヘキシル ― プラスチックの可塑剤"],"a":0,"e":"この組合せが誤り。コンクリートはアセトアルデヒドのおもな発生源ではない(アセトアルデヒドの発生源にはたばこなどがある。2021年度問55参照)。","l":"法令外","c":""},{"id":"2020-56","s":2,"q":"床面積40m²、天井高2.5mの居室に8人いて、換気によって室内の二酸化炭素濃度が900ppmに保たれていた。この部屋の換気量に最も近いものはどれか。ただし、室内は定常状態・完全混合、外気の二酸化炭素濃度は400ppm、1人あたりの二酸化炭素発生量は0.025m³/hとする。","o":["50m³/h","100m³/h","200m³/h","400m³/h","1,000m³/h"],"a":3,"e":"発生量は8×0.025＝0.2m³/h。換気量＝0.2÷(900－400)×10⁶＝0.2÷0.0005＝400m³/h。室の大きさは計算に使わない。","l":"計算","c":""},{"id":"2020-57","s":2,"q":"20℃の室内でホルムアルデヒドの容積比濃度が0.04ppmだった。空気1m³中のホルムアルデヒドの量に最も近いものはどれか。ただし、C(mg/m³)＝C(ppm)×M/22.41×273/(273＋t)(M:分子量、t:温度[℃])を使い、ホルムアルデヒドの分子式はHCHO、炭素・水素・酸素の原子量は12・1・16とする。","o":["0.15mg","0.1mg","0.08mg","0.05mg","0.025mg"],"a":3,"e":"分子量M＝1×2＋12＋16＝30。0.04×30÷22.41×273÷293＝0.04×1.339×0.932≒0.050mgなので0.05mg。","l":"計算","c":""},{"id":"2020-58","s":2,"q":"アレルゲンと微生物について述べた次の文のうち、最も不適当なものはどれか。","o":["ウイルスは、生きている細胞の中でしか増えられない。","クラドスポリウムは、一般の環境で育つカビである。","空調運転中の事務所の室内では、浮遊細菌より浮遊真菌の濃度の方が高いことが多い。","ダンプネスとは、過度の湿気が原因の問題が確認できる状態をいう。","ダニアレルゲンの大部分は、2μm以上の粒子である。"],"a":2,"e":"この記述が誤り。空調時の事務所では、人から出る浮遊細菌の方が浮遊真菌より濃度が高いことが多い(オフィス内の細菌のおもな発生源は在室者。2021年度問58参照)。","l":"法令外","c":""},{"id":"2020-59","s":2,"q":"浮遊粒子の動きにかかわる性質について述べた次の文のうち、最も不適当なものはどれか。","o":["抵抗係数は、ストークス域ではレイノルズ数に反比例する。","球形粒子の拡散係数は、粒径に比例する。","球形粒子が重力で落ちるときの終末沈降速度は、粒径の2乗に比例する。","電界中の電荷をもつ球形粒子の移動速度は、粒径に反比例する。","球形粒子が気体から受ける抵抗力は、粒子と流体の相対速度の2乗に比例する。"],"a":1,"e":"球形粒子の拡散係数は粒径に反比例する(2023年度問58でも正しい記述)。小さい粒子ほどよく拡散する。","l":"法令外","c":""},{"id":"2020-60","s":2,"q":"湿り空気線図(h-x線図)で相対湿度を求めるときに使う2つの項目の組合せとして、最も不適当なものはどれか。","o":["乾球温度と湿球温度","湿球温度と絶対湿度","比エンタルピーと乾球温度","露点温度と比エンタルピー","水蒸気分圧と露点温度"],"a":4,"e":"水蒸気分圧と露点温度は、どちらも絶対湿度だけで決まる値なので、2つそろっても状態点が決まらない(2024年度問59で正答)。","l":"法令外","c":""},{"id":"2020-61","s":2,"q":"暖房時における空気調和システムを図-Aに示す。図-Bは、図-Aのa〜eにおける空気の状態変化を湿り空気線図上に表したものである。図-Aのdに相当する図-B中の状態点はどれか。","o":["ア","イ","ウ","エ","オ"],"a":0,"e":"冬の外気a=オ(低温・乾燥)、室内e=ウ、その混合b=エ。加熱器で温めて(絶対湿度はそのまま)イ、加湿器で加湿した吹出空気d=ア。","l":"法令外","c":"","g":["img/2020-61.png"]},{"id":"2020-62","s":2,"q":"熱源方式について述べた次の文のうち、最も不適当なものはどれか。","o":["電動冷凍機＋ボイラ方式では、冷熱源は冷水、温熱源は温水または蒸気である。","電動機で動かすヒートポンプでは、おもに水熱源方式が採用されている。","吸収冷凍機＋蒸気ボイラ方式では、1年を通してガスまたは油を使う。","直焚吸収冷温水機方式では、冷水と温水を同時につくれる。","コージェネレーション方式は、発電と同時に排熱を空調や給湯などに使える。"],"a":1,"e":"電動ヒートポンプで広く使われているのは、外気を熱源とする空気熱源方式である(2025年度問65で正答)。","l":"法令外","c":""},{"id":"2020-63","s":2,"q":"地域冷暖房システムについて述べた次の文のうち、最も不適当なものはどれか。","o":["一定の地域内の建築物に、熱源プラントでつくった熱媒を供給する方式である。","欧米では熱(暖房)の供給が中心である。","大気汚染防止などの公害対策になる。","個々の建築物の機械室スペースが大きくなる。","熱源装置の大型化・集約化・集中管理によって、安全性や効率がよくなる。"],"a":3,"e":"熱源を地域のプラントにまとめるので、個々の建築物の機械室は小さくなり、使える床面積が増える(2024年度問64でも正しい記述)。","l":"法令外","c":""},{"id":"2020-64","s":2,"q":"乾球温度26.0℃・絶対湿度0.0105kg/kg(DA)の空気1,000kg/hと、乾球温度34.4℃・絶対湿度0.0194kg/kg(DA)の空気500kg/hを混ぜたときの、乾球温度と絶対湿度の組合せとして最も適当なものはどれか。","o":["28.8℃ ― 0.0135kg/kg(DA)","28.8℃ ― 0.0164kg/kg(DA)","30.2℃ ― 0.0150kg/kg(DA)","31.6℃ ― 0.0135kg/kg(DA)","31.6℃ ― 0.0164kg/kg(DA)"],"a":0,"e":"質量の割合による加重平均。温度＝(1,000×26.0＋500×34.4)÷1,500＝43,200÷1,500＝28.8℃。絶対湿度＝(1,000×0.0105＋500×0.0194)÷1,500＝20.2÷1,500≒0.0135kg/kg(DA)。","l":"計算","c":""},{"id":"2020-65","s":2,"q":"変風量単一ダクト方式について述べた次の文のうち、最も不適当なものはどれか。","o":["定風量単一ダクト方式に対して、省エネルギーと室温制御性の改善を目的とした方式である。","室への給気風量と室からの還気風量を変えるために、変風量装置を使う。","給気風量を変えるので、必要な新鮮外気量を確保する対策が必要である。","ふつう、給気温度は一定で運転する。","潜熱と顕熱を分けて制御できる空気調和システムである。"],"a":4,"e":"変風量単一ダクト方式は風量で温度を調整する方式で、潜熱と顕熱を分けて制御するものではない。潜熱・顕熱を分けて制御できるのはデシカント空調方式など(2022年度問65参照)。","l":"法令外","c":""},{"id":"2020-66","s":2,"q":"蓄熱槽を使う蓄熱システムについて述べた次の文のうち、最も不適当なものはどれか。","o":["負荷の大きな変動に対応できる。","熱源機器の容量が大きくなる。","開放式の水槽の場合、より大きなポンプ能力が必要になる。","熱源を定格で運転できる。","氷蓄熱では冷凍機の効率が下がる。"],"a":1,"e":"蓄熱システムを使うと、熱源装置の容量を減らせる(2025年度問67でも正しい記述)。","l":"法令外","c":""},{"id":"2020-67","s":2,"q":"下の図は蒸気熱源吸収冷凍機の冷凍サイクルを示したものである。図中のA、B、Cに対応する蒸気、冷水、冷却水の組合せとして、最も適当なものはどれか。","o":["蒸気 A/冷水 B/冷却水 C","蒸気 B/冷水 A/冷却水 C","蒸気 B/冷水 C/冷却水 A","蒸気 C/冷水 A/冷却水 B","蒸気 C/冷水 B/冷却水 A"],"a":4,"e":"再生器につながるCは溶液を加熱する蒸気。蒸発器につながるBは冷水。吸収器から凝縮器へ流れるAは冷却水。","l":"法令外","c":"","g":["img/2020-67.png"]},{"id":"2020-68","s":2,"q":"ボイラについて述べた次の文のうち、最も不適当なものはどれか。","o":["鋳鉄製ボイラは、スケールを防ぐため装置の系統を密閉系として設計・使用する。","貫流ボイラを扱うには、容量に関係なくボイラー技士の資格が必要である。","炉筒煙管式ボイラは、直径の大きな横型ドラムを本体とし、燃焼室と煙管群でできている。","真空式温水発生機は、缶体内を真空に保って水を沸騰させ、熱交換器に熱を伝える。","真空式温水発生機は、容量に関係なくボイラの取扱い資格がいらない。"],"a":1,"e":"貫流ボイラは容量によって扱いが分かれ、小さいものはボイラー技士の資格がなくても取り扱える(2025年度問66でも同じ内容が正答)。","l":"法令外","c":""},{"id":"2020-69","s":2,"q":"冷却塔について述べた次の文のうち、最も不適当なものはどれか。","o":["開放型冷却塔の水質管理として、強制的な循環水のブローと補給、薬品による水処理などが必要である。","密閉型冷却塔は、電算室やクリーンルームの系統によく採用される。","開放型冷却塔は通風抵抗が大きいので、密閉型冷却塔より大きな送風機動力が必要である。","開放型冷却塔と外気取入口との距離は10m以上とする。","開放型冷却塔の白煙防止対策として、冷却塔の壁に熱交換器を付けて外気を加熱する方法がある。"],"a":2,"e":"通風抵抗が大きく送風機動力が大きいのは密閉型の方である(2023年度問69・2025年度問70参照)。","l":"法令外","c":""},{"id":"2020-70","s":2,"q":"熱交換器について述べた次の文のうち、多管式熱交換器の説明にあたるものはどれか。","o":["構造によってU字管式・全固定式・遊動頭式に分けられる。","中に封入した作動媒体が蒸発と凝縮をくり返して熱を運ぶ。","熱交換器の中では、設置面積や重さが小さい。","伝熱板を増やしたり減らしたりして伝熱面積を変えられる。","一体成形されたブレージング型は、汚れやすい流体には向かない。"],"a":0,"e":"多管式(シェルアンドチューブ)熱交換器は、U字管式・全固定式・遊動頭式に分けられる(2024年度問68で正答)。(2)はヒートパイプ、(3)〜(5)はプレート式の説明。","l":"法令外","c":""},{"id":"2020-71","s":2,"q":"空気調和機について述べた次の文のうち、最も適当なものはどれか。","o":["パッケージ型空調機の圧縮機を動かす源は電力だけである。","ファンコイルユニットは冷媒を使う。","パッケージ型空調機は、個別に制御するのが難しい。","エアハンドリングユニットは、使う目的に合わせて構成機器を変えることはできない。","エアハンドリングユニットは、冷却・加熱のための熱源をもたない。"],"a":4,"e":"エアハンドリングユニットは熱源を内蔵せず、熱源設備から送られる冷温水などを使う(2021年度問71参照)。パッケージ型にはガスエンジン駆動もある。","l":"法令外","c":""},{"id":"2020-73","s":2,"q":"空気調和に使う送風機の特性と送風系についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「送風機の特性曲線は、横軸に[ア]をとり、縦軸に[イ]・効率・軸動力・騒音をとって表したものである。一方、送風系の抵抗曲線は、同じグラフ上で原点を通る[ウ]で表される。」","o":["ア 風量/イ 圧力/ウ 直線","ア 風量/イ 圧力/ウ 二次曲線","ア 圧力/イ 風量/ウ 直線","ア 圧力/イ 風量/ウ 二次曲線","ア 回転数/イ 圧力/ウ 直線"],"a":1,"e":"特性曲線は横軸に風量、縦軸に圧力などをとる。抵抗は風量の2乗に比例するので、抵抗曲線は原点を通る二次曲線になる(2024年度問72で正答)。","l":"法令外","c":""},{"id":"2020-74","s":2,"q":"ダクトと付属品について述べた次の文のうち、最も不適当なものはどれか。","o":["風量調整ダンパには、多翼型やスライド型などがある。","防火ダンパの温度ヒューズが溶ける温度は、一般換気用、厨房排気用、排煙用で違う。","長方形ダクトどうしの接続には、一般に差込み継手が使われる。","たわみ継手は、送風機など振動する機器とダクトをつなぐときに設ける。","定風量装置には、ダクト内の圧力によって機械的に自力で風量を調整する方式がある。"],"a":2,"e":"長方形ダクトどうしは一般にフランジ継手でつなぐ。差込み継手は丸ダクト(スパイラルダクト)の接続に使う(2024年度問71でも差込み継手の記述は正答になっていない)。","l":"法令外","c":""},{"id":"2020-75","s":2,"q":"吹出口について述べた次の文のうち、最も不適当なものはどれか。","o":["面状吹出口には、多孔パネル型や天井パネル型がある。","線状吹出口は、おもにペリメータ負荷の処理のため窓の近くに設置されることが多い。","ふく流吹出口は誘引効果が高く、ムラの少ない温度分布が得やすい。","軸流吹出口の吹出気流は、到達距離が短い。","軸流吹出口には、グリル型がある。"],"a":3,"e":"軸流吹出口は誘引比が小さく、到達距離が長い(2025年度問73でも正しい記述)。","l":"法令外","c":""},{"id":"2020-76","s":2,"q":"空気浄化装置について述べた次の文のうち、最も不適当なものはどれか。","o":["電気集じん器は、高電圧の電界で粉じんに電気を帯びさせて引き寄せ・付着させて取り除くもので、ろ過式に分類される。","ガス除去用エアフィルタは、使っても圧力損失がほとんど変わらない。","空気浄化装置を空気が通るときの抵抗を圧力損失といい、上流側と下流側の全圧の差[Pa]で表す。","ガス除去用エアフィルタには、シリカゲルや活性炭などを使った吸着剤フィルタがある。","HEPAフィルタやULPAフィルタは、ごく細かい粉じん粒子を高い性能でとらえられる。"],"a":0,"e":"電気集じん器は電気の力で粉じんを集める静電式で、ろ材でこし取るろ過式ではない。","l":"法令外","c":""},{"id":"2020-77","s":2,"q":"空気調和設備の配管の種類と使い道の組合せとして、最も不適当なものはどれか。","o":["圧力配管用炭素鋼鋼管 ― 蒸気","一般配管用ステンレス鋼鋼管 ― 冷却水","水道用硬質塩化ビニルライニング鋼管 ― 冷却水","架橋ポリエチレン管 ― 蒸気","配管用ステンレス鋼鋼管 ― 冷却水"],"a":3,"e":"架橋ポリエチレン管は樹脂管で、高温の蒸気には使えない。給水・給湯などに使う。","l":"法令外","c":""},{"id":"2020-78","s":2,"q":"温熱環境の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["サーミスタ温度計は、電気抵抗式温度計の一種である。","熱線風速計には、定電圧式と定温度式がある。","気流の測定法として、球体部の冷却力と気流の関係を利用する方法がある。","グローブ温度計の値は、平均放射温度(MRT)の2乗に比例する。","相対湿度の測定法として、乾球温度と湿球温度から水蒸気圧を求める方法がある。"],"a":3,"e":"この記述が誤り。グローブ温度と平均放射温度は、2乗に比例するような関係ではない。","l":"法令外","c":""},{"id":"2020-79","s":2,"q":"環境要素の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["微生物の間接的な測定法に、核酸増幅法がある。","酸素の測定法に、ガルバニ電池方式がある。","花粉の測定法に、培養法がある。","オゾンの測定法に、吸光光度法がある。","イオウ酸化物の測定法に、溶液導電率法がある。"],"a":2,"e":"培養法は、細菌やカビなど生きた微生物を増やして数える方法。花粉は培養せず、顕微鏡で数えるなどの方法で測る。","l":"法令外","c":""},{"id":"2020-80","s":2,"q":"測定対象と測定法の組合せとして、最も不適当なものはどれか。","o":["アスベスト ― 紫外線蛍光法","窒素酸化物 ― ザルツマン法","一酸化炭素 ― 定電位電解法","臭気 ― 官能試験法","ダニアレルゲン ― 酵素免疫測定法(ELISA法)"],"a":0,"e":"紫外線蛍光法はイオウ酸化物の測定法(2024年度問79でも正しい組合せ)。アスベストは繊維を顕微鏡で数えるなどの方法で測る。","l":"法令外","c":""},{"id":"2020-81","s":2,"q":"冷却塔と冷却水の維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["連続ブローなどで冷却水の濃縮を管理することは、スケール防止に役立つ。","冷却水系の化学的洗浄には、過酸化水素が使われる。","冷却塔と冷却水の水管は、1年以内ごとに1回清掃する。","冷却塔と冷却水は、使用開始後1か月以内ごとに1回、定期に汚れの状況を点検する。","スケール防止剤やレジオネラ属菌の殺菌剤などを含むパック剤は、薬注装置を使って連続的に注入して効果を出す。"],"a":4,"e":"この記述が誤り。パック剤は冷却塔に置いて薬剤を溶け出させるもので、薬注装置で注入するものではない。清掃の1年以内ごと、点検の1か月以内ごとは施行規則第3条の18のとおり。","l":"建築物衛生法施行規則 第3条の18","c":""},{"id":"2020-82","s":2,"q":"騒音・振動について述べた次の文のうち、最も不適当なものはどれか。","o":["周波数1Hz以下の乗り物などの揺れには、一般に鉛直方向より水平方向の方が敏感である。","鉛直方向の5Hzの振動は、環境振動で対象とする周波数の範囲に含まれる。","道路交通振動の規制は、昼間より夜間の方が厳しい。","ある騒音環境で、対象とする特定の音より周波数が低い音のことを暗騒音という。","広帯域騒音とは、広い周波数の成分を含む騒音のことである。"],"a":3,"e":"暗騒音とは、対象とする特定の音以外のすべての音のこと(2022年度問83でも正しい定義)。周波数の高い低いは関係ない。","l":"法令外","c":""},{"id":"2020-83","s":2,"q":"床衝撃音について述べた次の文のうち、最も不適当なものはどれか。","o":["軽量床衝撃音の対策として、床仕上げ材の弾性を高めることがある。","重量床衝撃音は、衝撃源そのものの衝撃力が高い周波数におもな成分を含む。","軽量床衝撃音の衝撃源は、重量床衝撃音の衝撃源より硬いことが多い。","重量床衝撃音の対策として、床躯体構造の曲げ剛性を高めることがある。","床衝撃音については、一般に学校よりホテルの方が高い遮音性能を求められる。"],"a":1,"e":"重量床衝撃音はおもに低い周波数の成分を含む(2024年度問84・2025年度問84でも正しい内容)。","l":"法令外","c":""},{"id":"2020-84","s":2,"q":"1台73dB(A)の騒音を出す機械を、測定点から同じ距離に6台置いて同時に動かしたときの騒音レベルに最も近いものはどれか。ただし log10 2＝0.3010、log10 3＝0.4771とする。","o":["76dB(A)","78dB(A)","81dB(A)","438dB(A)","568dB(A)"],"a":2,"e":"73＋10log10 6＝73＋10×(0.3010＋0.4771)＝73＋7.78≒81dB(A)。","l":"計算","c":""},{"id":"2020-85","s":2,"q":"音・振動環境について述べた次の文のうち、最も不適当なものはどれか。","o":["立っていても座っていても聞こえないが、寝ると骨伝導で固体伝搬音を感じることがある。","ポンプにつながった管路で出る騒音は、空気伝搬音である。","空気伝搬音を減らすには窓・壁・床などの遮音が必要だが、固体伝搬音には振動源の振動を減らすことや防振対策が重要である。","外部騒音が同じなら、コンサートホールやオペラハウスより録音スタジオの方が高い遮音性能を求められる。","床スラブが薄い機械室の隣の居室の振動対策としては、設備機器の防振支持が重要である。"],"a":1,"e":"ポンプや管路の振動が建物を伝わって出る音は、固体伝搬音である(2024年度問87でも同じ内容が正答)。","l":"法令外","c":""},{"id":"2020-86","s":2,"q":"光と照明について述べた次の文のうち、最も不適当なものはどれか。","o":["光の色は、色温度が高くなるにつれて赤っぽい色から青っぽい白色に変わる。","事務所の文書作成作業では、製図作業より高い維持照度が求められる。","光の色が同じでも、蛍光ランプとLEDでは分光分布が違う。","見る人から見た照明器具の発光部の立体角が大きいほど、不快グレアの程度を表すUGRの値は大きくなる。","基準の光で照らしたときの色をどれだけ忠実に再現できるかを判定する指標として、演色評価数を使う。"],"a":1,"e":"細かい作業をする製図の方が、文書作成より高い維持照度が求められる(2023年度問87でも正しい記述)。","l":"法令外","c":""},{"id":"2020-87","s":2,"q":"ランプと発光の種類の組合せとして、最も不適当なものはどれか。","o":["蛍光ランプ ― 低圧放電","エレクトロルミネセンス(EL) ― 電界発光","発光ダイオード(LED) ― 放電発光","白熱電球 ― 温度放射","水銀ランプ ― 高輝度放電"],"a":2,"e":"LEDは半導体による電界発光で、放電発光ではない(2025年度問88参照)。","l":"法令外","c":""},{"id":"2020-88","s":2,"q":"ある部屋の作業面に必要な照度が500lxである。ランプ1灯あたりの光束が2,000lmのとき、必要なランプの数に最も近いものはどれか。ただし作業面の面積は50m²、照明率は0.6、保守率は0.7とする。","o":["12灯","18灯","20灯","30灯","80灯"],"a":3,"e":"灯数＝照度×面積÷(1灯の光束×照明率×保守率)＝500×50÷(2,000×0.6×0.7)＝25,000÷840≒29.8≒30灯。","l":"計算","c":""},{"id":"2020-89","s":2,"q":"照明方式に関する次の用語のうち、建築化照明に分類されないものはどれか。","o":["フロアスタンド","システム天井照明","コーブ照明","コーニス照明","光天井照明"],"a":0,"e":"フロアスタンドは床に置く移動できる照明器具で、建築と一体にした建築化照明ではない。","l":"法令外","c":""},{"id":"2020-90","s":2,"q":"近年の建築物管理の変化の要因と、その対処方策の組合せとして、最も不適当なものはどれか。","o":["高齢者・要援護者の需要増 ― ユニバーサル化","危機管理・BCP ― 自家発電の導入","節電・省エネルギー化 ― 高効率機器の選択","集中豪雨 ― 排水・水防対策の強化","空調・換気のパーソナル化 ― 空間環境の均一化"],"a":4,"e":"パーソナル化は一人ひとりの好みに合わせて環境を変えることなので、対処方策は個別制御などになる。空間環境を均一にするのは逆である。","l":"法令外","c":""},{"id":"2020-91","s":3,"q":"太陽放射について、最も不適当なものはどれか。","o":["太陽の位置は、太陽の方位角と高度から求められる。","直達日射と天空日射は、短波長放射と呼ばれる。","UV-A・UV-B・UV-Cと呼ばれる紫外線のうち、波長が最も短いのはUV-Aである。","太陽定数とは、大気圏外で太陽に正面から向き合ったとき、単位面積あたりに入る放射エネルギーのことである。","紫外線(ドルノ線)には、体内でビタミンDをつくるはたらきがある。"],"a":2,"e":"紫外線の波長は、UV-A > UV-B > UV-Cの順に短くなり、最も短いのはUV-Cである。","l":"法令外","c":""},{"id":"2020-92","s":3,"q":"建築士法について、最も適当なものはどれか。","o":["決められた年数以上の構造設計の実務経験がある人には、構造設計一級建築士が与えられる。","木造建築士は、木造建築物なら延べ面積に関係なく新築の設計ができる。","一級建築士でなければ設計できない建築物が定められている。","建築設備士は、建築基準法の適合チェックが義務づけられた建築物に関わらなければならない。","工事監理とは、自分の責任で、工事を施工図と照らし合わせて確認することである。"],"a":2,"e":"建築士法では、規模や構造などに応じて一級建築士でなければ設計・工事監理ができない建築物が定められている。工事監理は「設計図書」と照合して確認すること。","l":"建築士法 第3条","c":""},{"id":"2020-93","s":3,"q":"建築物の基礎構造と地盤について、最も不適当なものはどれか。","o":["液状化現象は、埋立地や砂質の地盤などで起こりやすい。","砂質地盤の長期に生じる力に対する許容応力度は、粘土質地盤より小さい。","べた基礎は、地耐力が弱いところで使われることが多い。","地盤のうち、第三紀層は土丹層とも呼ばれる。","地業とは、基礎スラブより下に設ける割ぐり石や捨てコンクリートなどの部分をいう。"],"a":1,"e":"長期の許容応力度は、密実な砂質地盤が200kN/m²、粘土質地盤が20kN/m²で、砂質地盤のほうが大きい。","l":"建築基準法施行令 第93条","c":""},{"id":"2020-94","s":3,"q":"建築構造とその材料について、最も不適当なものはどれか。","o":["溶接の断面の形式には、突合せ溶接・すみ肉溶接・部分溶込み溶接などがある。","梁に使うH形鋼のフランジは、主にせん断力に抵抗する。","鉄骨構造はねばり強さ(じん性)に富み、地震に強い構造にしやすい。","ボルト接合には、高力ボルトが多く使われる。","合成梁は、鉄骨の梁とコンクリートの床板をスタッドボルトなどでしっかりつないだものである。"],"a":1,"e":"H形鋼のフランジ(上下の板)は主に曲げモーメントに抵抗し、せん断力には主にウェブ(中央の板)が抵抗する。","l":"法令外","c":""},{"id":"2020-95","s":3,"q":"建築物の荷重と構造力学について、最も不適当なものはどれか。","o":["等分布荷重がかかる単純梁のせん断力は、梁の中央で最も大きい。","積載荷重には、物品の重さが含まれる。","柱の構造計算に使う積載荷重は、地震力の計算に使う積載荷重より大きく決められている。","トラス構造の部材に生じる応力は、主に軸力である。","一般の区域の積雪荷重は、積雪量1cmごとに1m²あたり20N以上として計算する。"],"a":0,"e":"等分布荷重がかかる単純梁では、せん断力は両端(支点)で最も大きく、中央で0になる。中央で最大になるのは曲げモーメント。","l":"法令外","c":""},{"id":"2020-96","s":3,"q":"建築物とその構造について、最も不適当なものはどれか。","o":["鉄筋コンクリート造の店舗の法定耐用年数は、39年である。","既存不適格建築物とは、法の規定が適用された時点ですでにあった建物のうち、その後の改正規定に合っていない建物をいう。","免震構造には、アイソレータを使って地盤から建物を切り離す方法がある。","鉄筋コンクリート構造の鉄筋の腐食は、主にコンクリートのひび割れや中性化によって起こる。","構造設計に使う鋼材の許容応力度は、引張強さを基準にして計算する。"],"a":4,"e":"鋼材の許容応力度は、降伏点などをもとにした基準強度(F値)を基準にして計算する。","l":"建築基準法施行令 第90条","c":""},{"id":"2020-97","s":3,"q":"建築材料と部材の性質について、最も不適当なものはどれか。","o":["鉄鋼の線膨張係数は、コンクリートとほぼ等しい。","アルミニウムは、ほかの金属やコンクリートなどとふれると腐食する。","コンクリートをつくる砂と砂利の容積は、全体の約70%を占める。","トタンは、鋼板にすずめっきをしたものである。","網入り板ガラスは、フロート板ガラスに比べて、火災のときに破片が飛び散るのを防ぐ効果がある。"],"a":3,"e":"トタンは鋼板に亜鉛めっきをしたものである。すずめっきをしたものはブリキ。","l":"法令外","c":""},{"id":"2020-98","s":3,"q":"建築生産について、最も不適当なものはどれか。","o":["木工事は、仕上げ工事に分類される。","施工管理の業務には、関係する官庁などへの手続きも含まれる。","環境への負荷を減らすために、リユースやリサイクルなどが大切である。","工事のための電力や上下水道の設備の計画は、仮設計画に含まれる。","建築主は、建設工事の発注者である。"],"a":0,"e":"木工事は、建物の骨組をつくる躯体工事に分類される。","l":"法令外","c":""},{"id":"2020-99","s":3,"q":"建築設備について、最も適当なものはどれか。","o":["いつも遠隔で監視・管理されているエレベーターは、所有者による特定行政庁への定期検査の報告がいらない。","都市ガスの保守管理で、配管・ガス栓・ガス漏れ警報器の日常点検は、ガス設備の所有者または使用者が行う必要がある。","分散電源システムとは、商用電源が止まったときにも給電できる自家発電設備や蓄電池でつくるシステムのことである。","建物の不動産価値を評価するデューディリジェンスでは、建物の躯体・設備の現況が大切で、維持管理や稼働状況の記録はいらない。","ESCO事業のシェアード・セイビング方式とは、顧客が自分で投資して設備機器を入れ、ESCO事業者が削減効果を保証する方式である。"],"a":1,"e":"都市ガスの配管やガス栓、ガス漏れ警報器の日常の点検は、ガス設備の所有者・使用者が行う。顧客が自己投資する方式はギャランティード・セイビング方式である。","l":"法令外","c":""},{"id":"2020-100","s":3,"q":"建物の中の昇降設備について、最も不適当なものはどれか。","o":["非常用エレベーターは、緊急時には消防隊員の活動が優先される。","小荷物専用昇降機は、かごの床面積と天井の高さの上限が決められている。","動く歩道の定格速度は、勾配に応じて決められている。","乗用エレベーターには、火災のときに最寄りの階まで自動で運転する管制運転装置を備える必要がある。","エスカレーターには、その竪穴区画の防火シャッターが閉まるのに連動して止まる制動装置がついている。"],"a":3,"e":"火災時管制運転は、エレベーターを最寄りの階ではなく避難階まで運転して止めるものである。最寄りの階に止めるのは地震時管制運転。","l":"法令外","c":""},{"id":"2020-101","s":3,"q":"建物の防火について、最も不適当なものはどれか。","o":["避難安全検証法や耐火性能検証法は、建築基準法令に定められた性能規定である。","火災荷重とは、建物内の燃える物の量を木材に換算した、床面積あたりの重さのことである。","火の勢いは、窓などの開口の条件に関係なく、建物内の燃える物の量が多いほど激しくなる。","避難経路になる廊下や階段に煙が入らないよう、防煙・排煙の対策が必要である。","特定防火設備とは、シャッターや防火扉など、火災を閉じこめることができる設備のことである。"],"a":2,"e":"火の勢いは、燃える物の量だけでなく、窓などの開口から入る空気の量(開口条件)によっても大きく変わる。","l":"法令外","c":""},{"id":"2020-102","s":3,"q":"建物の避難計画や避難施設について、最も不適当なものはどれか。","o":["高層ビルなどにある特別避難階段とは、防煙・排煙の対策がとられた、安全性の高い直通階段のことである。","すべり台や避難ロープは、消防法で定める避難器具に含まれる。","非常用の照明装置の避難に有効な照度は、光源がLEDランプの場合、白熱電灯の倍の2lx以上にしなければならない。","高層ビルでは避難が終わるまでに時間がかかるため、誘導灯の点灯を続ける時間は60分と定められている。","高層ビルの避難計画では、効率よく避難できるよう、2つ以上の避難階段はなるべく近くに配置するのが望ましい。"],"a":4,"e":"2つ以上の避難階段は、1つが使えなくなってももう1つで避難できるよう、なるべく離して配置する(2方向避難)。","l":"法令外","c":""},{"id":"2020-103","s":3,"q":"防犯・防災の管理について、最も不適当なものはどれか。","o":["防犯用のネットワークカメラは、撮った高解像度の映像を送れるので、高画質なシステムをつくれる。","アクティブセンサとは、人などの熱を出すものを赤外線で検知し、それが動いたときに作動する防犯センサである。","夜間無人になる建物の機械警備では、異常が起きたとき25分以内に警備員がかけつけなければならない。","大規模な事業所では、防火管理者・自衛消防組織に加えて、大地震などに備えた防災管理者を置く必要がある。","入退室管理システムには、緊急避難のときに電気錠を一斉に開ける機能をもたせる必要がある。"],"a":1,"e":"人などが出す熱(赤外線)の変化を感じて作動するのはパッシブセンサである。アクティブセンサは、自ら赤外線を出し、その光がさえぎられたことで検知する。","l":"法令外","c":""},{"id":"2020-104","s":3,"q":"建築物に関係する法令について、最も不適当なものはどれか。","o":["消防法の特定防火対象物では、消防用設備等の設置・維持の規定が適用されるのは新しく建てる建物だけである。","高さ31mを超える高層建築物の管理者は、消防法の防火管理者を定め、消防計画をつくる。","バリアフリー法でいう建築物特定施設には、出入口・階段・便所がある。","建築主は、バリアフリー法の2,000m²以上の特別特定建築物を建てるときは、建築物移動等円滑化基準に適合させなければならない。","耐震改修促進法でいう耐震改修とは、地震への安全性を高めるために、増築・改築・修繕・模様替・一部の除却・敷地の整備をすることをいう。"],"a":0,"e":"特定防火対象物では、既存の建物にも現行の消防用設備等の基準が適用される(遡って適用される)。","l":"消防法 第17条の2の5","c":""},{"id":"2020-105","s":3,"q":"建築物の維持管理の略語と内容の組合せとして、最も不適当なものはどれか。","o":["BCP ― 事業継続計画","BEMS ― ビルエネルギー管理システム","POE ― 建物を使う人の視点からの性能評価","LCC ― 建物の一生に必要なすべての費用","CASBEE ― 発注者が求める品質を実現するための管理プロセス"],"a":4,"e":"CASBEEは建築環境総合性能評価システムで、建物の環境性能を評価する仕組みである。","l":"法令外","c":""},{"id":"2020-106","s":4,"q":"給水・排水の管理で使う用語と、その単位の組合せとして、最も不適当なものはどれか。","o":["総アルカリ度 ― mg/L","BOD容積負荷 ― g/(人・日)","色度 ― 度","水槽照度率 ― %","腐食速度 ― mm/年"],"a":1,"e":"BOD容積負荷の単位は kg/(m³・日) である(2022年問106で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2020-107","s":4,"q":"給水・排水の管理に関する用語の説明として、最も不適当なものはどれか。","o":["逃し通気管 ― 排水系統内の下水ガスの臭いを取り除くための管","FRP ― ガラス繊維で強化したプラスチック","スクリーン ― 原水の中のきょう雑物(混じったごみ)を取り除く装置","バルキング ― 活性汚泥が沈みにくくなる現象","バキュームブレーカ ― 管内が負圧になったときに空気を取り入れる装置"],"a":0,"e":"逃し通気管は臭気を除くための管ではない。排水立て管内の圧力変動をやわらげるなど、空気の流れを助けるための通気管である(2022年問129で、結合通気管を「圧力変動を緩和する逃し通気管」とした記述が正しいとされている)。","l":"法令外","c":""},{"id":"2020-108","s":4,"q":"水質基準に関する省令で定める基準として、誤っているものはどれか。","o":["一般細菌は、検水1mLでできる集落数が100以下であること。","総トリハロメタンは、0.1mg/L以下であること。","カルシウム・マグネシウム等(硬度)は、500mg/L以下であること。","鉛及びその化合物は、鉛の量として0.01mg/L以下であること。","塩化物イオンは、200mg/L以下であること。"],"a":2,"e":"硬度(カルシウム・マグネシウム等)の基準は300mg/L以下である(水質基準に関する省令)。500mg/L以下は蒸発残留物の基準。ほかの4つは現行の基準どおり。","l":"水質基準に関する省令(表)","c":""},{"id":"2020-109","s":4,"q":"水道水の塩素消毒に関する記述として、最も不適当なものはどれか。","o":["CT値は、塩素濃度を接触時間で割ったものである。","塩素消毒の効果は、にごりの成分(懸濁物質)があると下がる。","原虫のシスト(殻に包まれた状態)は、塩素消毒に強い。","塩素消毒は、多くの種類の微生物に効果が期待できる。","塩素消毒の反応の速さは、温度が高いほど速くなる。"],"a":0,"e":"CT値は、塩素濃度と接触時間をかけたものである(2022年問110で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-110","s":4,"q":"給水の管理に関する記述として、最も不適当なものはどれか。","o":["残留塩素濃度の定期検査は、濃度が最も低いと考えられる末端の給水栓で行う。","飲料水系統の給水管の赤水などへの恒久対策として、防錆剤を使う。","飲料水系統の配管の維持管理では、管の損傷・さび・腐食・水漏れがないかを定期に点検することが大切である。","給水設備が古くなると、水量や水圧が下がることがある。","水質検査で病原生物などが基準を超えていて、人の健康を害するおそれがある場合は、すぐに給水を止める。"],"a":1,"e":"防錆剤の使用は、赤水などの対策として配管の布設替えなどが行われるまでの応急対策とされている(告示第119号 第2の二の4)。恒久対策ではない。","l":"平成15年厚生労働省告示第119号 第2の二の4","c":""},{"id":"2020-111","s":4,"q":"給水用の止水弁の取付けに関する記述として、最も不適当なものはどれか。","o":["天井の中に止水弁を設ける場合は、その近くに点検口を設ける。","給水立て主管から各階へ分かれる管には、止水弁を設ける。","取り外しが必要な機器の前後に止水弁を設ける場合は、ねじ込み型にする。","止水弁には、系統の名前の札を付ける。","止水弁としては、仕切弁が多く使われる。"],"a":2,"e":"機器との接続配管は、交換のときに外しやすいフランジ接合などにする(2021年問114で正しい記述として出題)。ねじ込み型とした記述が誤り。","l":"法令外","c":""},{"id":"2020-112","s":4,"q":"給水設備に関する記述として、最も適当なものはどれか。","o":["総合病院の1日あたりの設計給水量は、150〜350L/床とする。","受水槽の有効容量は、一般に1日最大使用量の1/10とする。","高層ホテルの給水系統のゾーニングは、上限水圧が0.5MPaになるようにする。","直結増圧方式は、引込み管に増圧ポンプユニットを設けて水圧を高め、中層の建物にも使えるようにした方式である。","高置水槽方式は、ほかの給水方式に比べて水質汚染の可能性が低い方式である。"],"a":3,"e":"直結増圧方式は、引込み管に増圧ポンプユニットを設けて水圧を上げ、中層建築物にも使えるようにした方式である。なお高層ホテルの上限水圧は0.3MPa(2023年問112)。","l":"法令外","c":""},{"id":"2020-113","s":4,"q":"給水設備の配管材料と、その接合方法の組合せとして、最も不適当なものはどれか。","o":["水道用硬質塩化ビニルライニング鋼管 ― フランジ接合","銅管 ― 差込みろう接合","ステンレス鋼管 ― フランジ接合","ポリブテン管 ― 接着接合","硬質ポリ塩化ビニル管 ― 接着接合"],"a":3,"e":"ポリブテン管の接合方法には、メカニカル形接合や融着接合がある(2016年問114で正しい記述として出題)。接着接合ではない。","l":"法令外","c":""},{"id":"2020-114","s":4,"q":"給水設備の貯水槽の汚染防止に関する記述として、最も不適当なものはどれか。","o":["受水槽を屋外に置く場合は、防護フェンスで囲み、出入口にかぎをかける。","貯水槽の下と周りには60cm以上、上には100cm以上の点検スペースを確保する。","流入管は、吐水するときの波立ちを防ぐため、吐水部を水面の下に沈める。","容量の大きい貯水槽では、槽の中に迂回壁を設けて、水のよどみをおさえる。","有効容量が2m³以上の貯水槽には、水槽本体との取付部を水密にした通気管を設ける。"],"a":2,"e":"流入管は受水槽の中で水に沈めず、吐水口空間を確保する(2022年問114で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-115","s":4,"q":"給水設備に関する記述として、最も不適当なものはどれか。","o":["建物の揺れ、地盤の不同沈下、配管の振動などによるずれを吸収するため、配管に可とう継手を付ける。","高置水槽方式の揚水管は、水柱分離によるウォータハンマを防ぐため、屋上での横引きを長くする。","合成樹脂管のクリープ劣化とは、合成樹脂に熱応力が長時間かかり続けると、材料の変形が時間とともに進むことをいう。","吸排気弁は、給水管内の空気を出すことと、管内が負圧になったときの逆流を防ぐために設ける。","さや管ヘッダ工法とは、集合住宅の住戸内などで、ヘッダから各器具へそれぞれ単独に配管する工法である。"],"a":1,"e":"揚水管の屋上での横引きを長くするとした記述が誤り。水柱分離によるウォータハンマを防ぐには、屋上での横引きを長くしない。","l":"法令外","c":""},{"id":"2020-116","s":4,"q":"貯水槽の清掃に関する記述として、最も不適当なものはどれか。","o":["清掃のときは、マンホールのふたを開け、換気用のファンやダクトを置いて槽内を換気するなど、事故防止の対策をする。","受水槽と高置水槽の清掃は原則として同じ日に行い、受水槽の清掃後に高置水槽を清掃する。","清掃が終わったら、塩素剤を使って2回以上、貯水槽の中を消毒する。","消毒後の水洗いと水張りは、消毒が終わってから15分程度たってから行う。","清掃後の消毒には、有効塩素濃度50〜100mg/Lの次亜塩素酸ナトリウム溶液などの塩素剤を使う。"],"a":3,"e":"消毒後の水洗いと水張りは、少なくとも30分以上たってから行う(2021年問117・2023年問114で正しい記述として出題)。受水槽→高置水槽の順、2回以上の消毒は告示第119号 第2のとおり。","l":"平成15年厚生労働省告示第119号 第2(選択肢2・3)","c":""},{"id":"2020-117","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["ホテルの宿泊部分の設計給湯量は、50L/(人・日)程度である。","ガス瞬間湯沸器の能力は一般に号数で表し、1号は加熱能力1.74kWにあたる。","厨房の業務用皿洗い機のすすぎ温度は、80℃程度である。","中央式給湯設備の給湯栓の温度は、ピーク時でも55℃以上にする。","貯蔵式湯沸器は90℃以上の高温の湯が得られ、飲用に使われる。"],"a":0,"e":"ホテルの宿泊部分の設計給湯量は150〜250L/(人・日)程度である(2024年問120で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-118","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["循環式給湯設備で下向き配管方式とする場合、給湯横主管は1/200以上の下り勾配にする。","返湯管に銅管を使う場合は、潰食を考えて管内の流速を1.2m/s以下にする。","ライニング鋼管に単式の伸縮管継手を設ける間隔は、50m程度とする。","貯湯槽の容量は、ピーク時に必要な量の1〜2時間分を目安にする。","耐熱性硬質ポリ塩化ビニル管は、90℃以下で使う。"],"a":2,"e":"ライニング鋼管の単式伸縮管継手の設置間隔を50m程度とした記述が誤り(2025年問118でも同じ記述が誤りとして出題)。","l":"法令外","c":""},{"id":"2020-119","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["強制循環方式で湯を均等に循環させるため、リバースリターン方式にする。","密閉式膨張水槽を設ける場合は、逃し弁を設ける。","給湯循環ポンプの循環流量は、循環配管系などからの熱損失と、加熱装置での給湯温度と返湯温度の差から計算する。","加熱装置から逃し管(膨張管)を立ち上げる場合は、補給水槽の水面よりも高く立ち上げる。","給湯循環ポンプは、背圧に耐えられるものを選ぶ。"],"a":0,"e":"強制循環方式で、必ずしもリバースリターン方式にする必要はない。湯を均等に循環させるには、返湯管に定流量弁を設ける方法がある(2021年問123・2023年問119で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-120","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["樹脂管の許容使用圧力は、使う温度が高くなると下がる。","ステンレス鋼管はすき間腐食が起こるおそれがあるので、ていねいな施工が求められる。","耐熱性硬質塩化ビニルライニング鋼管の接続には、管端防食継手を使う。","返湯管のない単管式の給湯配管に銅管を使う場合は、給湯循環配管に使う場合より腐食が起こりやすい。","ステンレス鋼管と銅管の線膨張係数は、ほぼ等しい。"],"a":3,"e":"銅管は、循環配管を設けない一管式(単管式)の配管では腐食がほとんど起こらない(2024年問122で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-121","s":4,"q":"給湯設備の加熱装置に関する記述として、最も不適当なものはどれか。","o":["ガス瞬間湯沸器には、給湯のほかにセントラルヒーティング用の回路を組み込んだものがある。","給湯用の貫流ボイラは水管群でできていて、耐圧性に優れている。","無圧式温水発生機は、缶体の中を大気圧以下にし、熱媒を蒸発させて内部の熱交換器で熱交換し、湯を供給する。","加熱コイル付き貯湯槽は、蒸気などの熱源が得られる場合に使われる。","ガスマルチ式給湯機は、小型の瞬間湯沸器を何台もつないでユニットにしたものである。"],"a":2,"e":"缶体内を大気圧より低く保って水を沸騰させるのは真空式温水発生機の説明である(2024年問123で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-122","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["第二種圧力容器は、1年以内ごとに1回、定期自主検査を行う。","各種の弁は、1年に1回以上、分解清掃する。","中央式給湯方式の循環ポンプは、1年に1回以上、分解清掃する。","給湯配管は、1年に1回以上、管洗浄を行う。","シャワーヘッドは、1年に1回以上、定期的に点検する。"],"a":4,"e":"シャワーヘッドの定期点検は6か月に1回以上行う(2023年問121で正しい組合せとして出題)。第二種圧力容器の定期自主検査は1年以内ごとに1回(ボイラー及び圧力容器安全規則第88条)。","l":"ボイラー及び圧力容器安全規則 第88条(選択肢1)","c":""},{"id":"2020-123","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["器具のワッシャには、天然ゴム製のものを使う。","あまり使わない給湯栓は、定期的にたまった水を出し、給湯温度を測る。","貯湯槽は、定期的に底部にたまった水を出す。","SUS444製の貯湯槽には、電気防食を施してはならない。","給湯栓から出る湯が分離した気体で白くにごる場合は、自動空気抜き弁の空気の出口が詰まっている可能性がある。"],"a":0,"e":"器具のワッシャには、細菌が増えるのを防ぐため合成ゴム製のものを使う(2024年問124で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-124","s":4,"q":"雨水利用設備に関する記述として、最も不適当なものはどれか。","o":["雨水を集める場所は、原則として建物の屋根面とする。","雨水の処理では、生物処理法が使われる。","雨水利用率とは、雨水集水量に対する雨水利用量の割合である。","雨水の処理で、消毒装置は雨水貯留槽の下流側に設ける。","雨水貯留槽に流れ込む立て管には、豪雨で満水になったときの対策として、緊急停止弁などを設ける。"],"a":1,"e":"雨水の処理に生物処理法が使われるとした記述が誤り。","l":"法令外","c":""},{"id":"2020-125","s":4,"q":"雑用水の処理設備のうち、色度と臭気を取り除くのに最も適したものはどれか。","o":["沈砂槽","回転板接触槽","ばっ気槽","活性炭処理装置","ろ過装置"],"a":3,"e":"色度と臭気の除去には、活性炭処理装置が適している(2025年問126でも色度の除去に活性炭処理装置が適当とされている)。","l":"法令外","c":""},{"id":"2020-126","s":4,"q":"建築物衛生法施行規則で定める雑用水の水質基準の項目と基準の組合せとして、誤っているものはどれか。","o":["大腸菌 ― 検出されないこと","臭気 ― 異常でないこと","pH値 ― 5.8以上8.6以下であること","濁度 ― 2度以下であること","外観 ― 浮遊物質を含まないこと"],"a":4,"e":"外観の基準は「ほとんど無色透明であること」である(施行規則第4条の2)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2020-127","s":4,"q":"排水の水質に関する記述として、最も不適当なものはどれか。","o":["透視度はBODと関係があることが多く、汚水処理の進み具合を推定する指標に使われる。","CODは、主に水中の有機物が好気性微生物によって分解されるときに使われる酸素の量を表す。","MLSSはばっ気槽の混合液の浮遊物質のことで、活性汚泥の中の微生物の量の指標の一つである。","残留塩素は、水中にある遊離型と結合型の有効塩素をいい、消毒効果の指標に使われる。","リン化合物は、閉鎖性水域の富栄養化の原因物質の一つである。"],"a":1,"e":"好気性微生物による分解で使われる酸素量を表すのはBODである(2023年問126で正しい記述として出題)。CODの説明ではない。","l":"法令外","c":""},{"id":"2020-128","s":4,"q":"排水トラップに関する記述として、最も不適当なものはどれか。","o":["トラップにかかる圧力変動の周期と封水の固有振動の周期が近いと共振が起き、封水が大きく失われる。","脚断面積比とは、トラップの流出脚の断面積を流入脚の断面積で割った値をいう。","封水強度とは、トラップで蒸発が起きたときに封水を保つ能力をいう。","トラップのウェア(あふれ縁)に糸くずや髪の毛が引っかかると、毛細管現象で封水が減る。","自掃作用とは、排水の流れの勢いで、トラップの封水部にたまったり付いたりしそうなきょう雑物を押し流す作用をいう。"],"a":2,"e":"封水強度とは、排水管内に正圧や負圧が生じたときにトラップの封水を保つ能力をいう(2021年問129・2025年問133で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-129","s":4,"q":"排水通気設備に関する語句の組合せとして、最も不適当なものはどれか。","o":["各個通気方式 ― トラップの自己サイホン作用を防ぐ","排水口空間 ― 飲料水槽の汚染を防ぐ","即時排水型ビルピット ― 排水槽の悪臭を防ぐ","インバートます ― 固形物がたまるのを防ぐ","通気弁 ― 通気管内の正圧を防ぐ"],"a":4,"e":"通気弁を「通気管内の正圧防止」とした組合せが誤り。","l":"法令外","c":""},{"id":"2020-130","s":4,"q":"排水設備に関する記述として、最も不適当なものはどれか。","o":["排水ポンプは、吸込みピットの壁面から200mm以上離して設置する。","排水用耐火二層管は、繊維モルタルの外管と、硬質ポリ塩化ビニル管の内管を組み合わせたものである。","トラップが組み込まれていない阻集器には、出口側にトラップを設ける。","排水槽の底の勾配は、吸込みピットに向かって1/20とする。","通気管の大気開口部に付ける通気口の通気率(開口面積/管内断面積)は、100%以上必要である。"],"a":3,"e":"排水槽の底の勾配は、吸込みピットに向かって1/15以上1/10以下とする(2021年問131・2025年問130で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-131","s":4,"q":"排水通気配管に関する記述として、最も不適当なものはどれか。","o":["ループ通気方式は、最上流の器具排水管が排水横枝管につながる位置のすぐ下流から通気管を立ち上げ、通気立て管につなぐ方式である。","通気管の大気開口部を窓や換気口の近くに設ける場合は、その上端から600mm以上立ち上げる。","特殊継手排水システムは、排水横枝管につながる器具の数が多いビルに採用されている。","管径150mmの排水横管の最小勾配は、1/200である。","伸頂通気方式では、排水立て管と排水横主管の接続に大曲がりベンドなどを使う。"],"a":2,"e":"特殊継手排水システムは、排水横枝管につながる器具の数が比較的少ない集合住宅やホテルの客室系統に多く採用されている(2021年問128で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-132","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["排水管の掃除口の間隔は、管径が100mmを超える場合、通常30m以内とする。","雨水ますの流出管は、流入管より管底を20mm程度下げて設ける。","敷地排水管の直管が長い場合、排水ますは管内径の150倍程度の間隔で設ける。","飲料用貯水槽の間接排水管の排水口空間は、最小150mmとする。","自然流下式の排水横管の勾配は、管内の流速が0.6〜1.5m/sになるように設ける。"],"a":2,"e":"敷地排水管の直管が長い場合、排水ますは管内径の120倍を超えない範囲に設置する(2021年問132・2023年問130で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-133","s":4,"q":"排水設備の保守管理に関する用語の組合せとして、最も不適当なものはどれか。","o":["逆流防止弁 ― 排水の逆流を防ぐ","床下式の掃除口 ― 砲金製のプラグを使う","ウォーターラム法 ― 圧縮空気を放出して管内の詰まりを取り除く","排水槽の開口部への防虫網の設置 ― チカイエカの発生を防ぐ","汚水槽のフロートスイッチ ― 絶縁抵抗を定期的に測る"],"a":4,"e":"(5)の組合せが誤り。","l":"法令外","c":""},{"id":"2020-134","s":4,"q":"排水設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["排水槽の底の勾配面には、点検で歩きやすいように階段を設ける。","排水槽の清掃は、酸素濃度と硫化水素濃度を確かめてから行う。","排水槽の悪臭対策として、タイマによる強制排水を行うことが望ましい。","グリース阻集器のトラップの清掃は、2か月に1回程度行う。","水中用排水ポンプのメカニカルシール部のオイル交換は、3〜5年に1回程度行う。"],"a":4,"e":"水中ポンプのメカニカルシール部のオイル交換は、6か月〜1年に1回行う(2024年問134で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-135","s":4,"q":"排水通気設備の維持管理に関する記述として、最も不適当なものはどれか。","o":["小便器の排水管の中に付いた尿石は、アルカリ性洗剤で取り除く。","排水管内部の詰まり具合や腐食の状態は、内視鏡や超音波厚さ計で確かめられる。","ロッド法は、1〜1.8mのロッドをつなぎ、手で排水管に入れて清掃する方法である。","排水横管の清掃に使うスネークワイヤ法は、一般に長さ25m以内で使われる。","排水立て管の清掃に使う高圧洗浄法は、5〜30MPaの圧力の水を噴射して管内を洗う方法である。"],"a":0,"e":"尿石の除去には酸性洗浄剤を使う(2023年問133・2025年問134で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-136","s":4,"q":"衛生器具に関する記述として、最も不適当なものはどれか。","o":["衛生器具の材質は、表面がなめらかで、水や湿気を吸わず、衛生的であることが求められる。","給水器具には、給水栓・洗浄弁・ボールタップなどがある。","衛生器具の分類で、水受け容器の排水口と排水管をつなぐトラップは、付属品に分類される。","飲料水にふれる部分の材質は、人体に有害な成分が溶け出さないことが求められる。","洋風大便器の便座には、プラスチックや木材などが使われる。"],"a":2,"e":"トラップを付属品に分類するとした記述が誤り。","l":"法令外","c":""},{"id":"2020-137","s":4,"q":"衛生器具の故障の現象と、その原因の組合せとして、最も不適当なものはどれか。","o":["小便器の中が十分に洗われていない ― 水の出口の穴に異物が詰まっている","小便器の排水の流れが悪い ― 排水管の中にスケールが付いている","混合水栓で適温が得られない ― 水圧と湯圧の差が大きすぎる","大便器に少しずつ水が流れ続ける ― 洗浄弁のシートとシートパッキンの間に異物が付いている","サイホン式大便器のたまり水の面が正常より小さい ― タンク内の補助水管がオーバフロー管の中に差し込まれている"],"a":4,"e":"(5)の組合せが誤り。","l":"法令外","c":""},{"id":"2020-138","s":4,"q":"浄化槽法で定める浄化槽の定義について、次の文の【 】内の語句のうち、誤っているものはどれか。\n「【(1)便所】と連結して、し尿とこれに併せて【(2)雨水】を処理し、【(3)下水道法】に定める終末処理場をもつ公共下水道以外に放流するための設備又は施設であって、同法の公共下水道と【(4)流域下水道】、ならびに廃棄物処理法の計画に従って【(5)市町村】が設置したし尿処理施設以外のものをいう。」","o":["便所","雨水","下水道法","流域下水道","市町村"],"a":1,"e":"浄化槽がし尿と併せて処理するのは「雑排水」である。雑排水からは工場廃水や雨水などの特殊な排水は除かれている(浄化槽法第2条第1号)。","l":"浄化槽法 第2条第1号","c":""},{"id":"2020-139","s":4,"q":"浄化槽の装置と、その点検内容の組合せとして、最も不適当なものはどれか。","o":["沈殿分離槽 ― 溶存酸素濃度","汚泥貯留槽 ― スカムのたまり具合","流量調整槽 ― ポンプが作動する水位","接触ばっ気槽 ― 生物膜のでき具合","消毒槽 ― 沈殿物のたまり具合"],"a":0,"e":"溶存酸素濃度は、ばっ気槽の点検項目である(2021年問139で正しい項目として出題)。沈殿分離槽の点検内容としては不適当。","l":"法令外","c":""},{"id":"2020-140","s":4,"q":"消防用設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["防火設備定期検査制度により、特定行政庁が定める特定建築物の防火設備は、一級建築士・二級建築士または防火設備検査員が1年に1回作動状況などを確認する。","特定防火対象物では、法定定期点検の結果と不備の是正措置の報告を3年に1回行う。","消防用設備等に付いている動力消防ポンプは、6か月に1回作動点検を行う。","法定定期点検の内容は、作動点検・外観点検・機能点検・総合点検である。","消防法の消防用設備等について、一定規模以上の特定防火対象物は、消防設備士または消防設備点検資格者が点検する。"],"a":1,"e":"特定防火対象物の点検結果の報告は1年に1回である(消防法施行規則第31条の6第3項。3年に1回は非特定防火対象物)。","l":"消防法施行規則 第31条の6第3項","c":""},{"id":"2020-141","s":5,"q":"「建築物における衛生的環境の維持管理について」(平成20年1月25日 健発第0125001号)に示された建築物環境衛生維持管理要領について述べた次の文のうち、最も不適当なものはどれか。","o":["清掃用器具は、汚れの度合いを考えて区域ごとに使い分ける。","洗剤や床維持剤は、利用者や清掃従事者などの健康と環境に配慮したものを使う。","清掃用機械器具などの保管庫は、1年以内ごとに1回、定期に点検する。","収集・運搬設備や貯留設備などの廃棄物処理設備は、6か月以内ごとに1回、定期に点検する。","所有者等は、建築物内で出る廃棄物を分別できる環境を整える。"],"a":2,"e":"清掃用機械器具や資材の保管庫の点検は、6か月以内ごとに1回である(2024年度問141でも正しい記述として出題)。","l":"法令外(建築物環境衛生維持管理要領)","c":""},{"id":"2020-142","s":5,"q":"次の建築物清掃のうち、一般に日常清掃で行うものとして、最も不適当なものはどれか。","o":["玄関ホールのフロアマットの除じん","エスカレーターのランディングプレートの除じん","廊下の壁の除じん","駐車場の床の除じん","玄関ホールの金属部の除じん"],"a":2,"e":"廊下の壁の除じんは、毎日ではなく定期清掃で行う作業である。","l":"法令外","c":""},{"id":"2020-143","s":5,"q":"清掃作業での転倒事故の防止対策について述べた次の文のうち、最も不適当なものはどれか。","o":["出入口や曲がり角では、指差し呼称を行う。","走ったり、ポケットに手を入れたりしない。","滑りにくい作業靴や滑り止めカバーを使う。","使う機械や器具を散らかして置かない。","通路を確保するため、周りを整理整頓して作業する。"],"a":0,"e":"この記述が誤り(公式正答)。ほかの4つは、走らない・滑りにくい靴・整理整頓など、転倒防止の基本的な対策である。","l":"法令外","c":""},{"id":"2020-144","s":5,"q":"建築物清掃の点検評価について述べた次の文のうち、最も適当なものはどれか。","o":["評価は4か月に1回行う。","改善が必要と判断したときは、評価者が清掃責任者に指示する。","評価は清掃作業者の視点で行う。","点検は、おもに光沢度計などの測定機器で行う。","評価範囲は、汚れ方が平均的な箇所に重点を置く。"],"a":1,"e":"改善が必要なときは、評価者が改善内容を示して清掃責任者に指示する(2021年度問144でも正しい記述)。評価は利用者の立場で、おもに目視で行う。","l":"法令外","c":""},{"id":"2020-145","s":5,"q":"粒子状物質と粒子の大きさの組合せとして、最も適当なものはどれか。","o":["沈降性大気じん ― 0.1〜0.5μm","たばこ煙 ― 1〜10μm","花粉 ― 10〜100μm","掃除機の排気中の粒子 ― 50〜500μm","ダストクロス清掃による発じん ― 100〜1,000μm"],"a":2,"e":"花粉は10〜100μm程度と比較的大きい(2024年度問53でも花粉が最も大きいとされている)。たばこ煙はもっと小さい(2022年度問59参照)。","l":"法令外","c":""},{"id":"2020-146","s":5,"q":"建築物清掃での環境対策について述べた次の文のうち、最も不適当なものはどれか。","o":["パッドやブラシに使われている研磨剤の種類や量を考えて選ぶ。","作業時間を短くする。","酸性・アルカリ性の洗剤は中和してから流す。","洗剤を使うときの温度は、できるだけ高くする。","作業で出る洗剤容器などの廃棄物を減らす。"],"a":3,"e":"お湯を沸かすためのエネルギーを使うので、温度をできるだけ高くするのは環境対策に逆行する。","l":"法令外","c":""},{"id":"2020-147","s":5,"q":"ビルクリーニング用の機械・器具について述べた次の文のうち、最も適当なものはどれか。","o":["三つ手ちり取りは、移動するときにごみがこぼれないので、拾い掃き用として広く使われる。","自在ぼうきは、馬毛などを植えた薄いブラシで、ほこりを舞い上げることが少ない。","自動床洗浄機は、洗剤供給式床磨き機とドライ式真空掃除機を組み合わせたものである。","樹脂床維持剤の皮膜をはがすときは、床材を傷めないように赤または白の床用パッドを使う。","凹凸のある床には、研磨粒子が付いたパッドを使う。"],"a":1,"e":"自在ぼうきはほこりを舞い上げにくい(2024年度問148でも正しい記述)。ごみがこぼれないのは改良ちり取り、自動床洗浄機は吸水式真空掃除機と組み合わせたもの(2023年度問149)、凹凸の床はブラシを使う。","l":"法令外","c":""},{"id":"2020-148","s":5,"q":"カーペット清掃用の機械について述べた次の文のうち、最も不適当なものはどれか。","o":["アップライト型真空掃除機は、カーペットのほこりを取るのに向いた構造である。","真空掃除機は、電動ファンで機械の中に空気の低圧部をつくり、ホースからほこりを吸い込む構造である。","スチーム洗浄機は、高温の水蒸気で汚れを取るので、洗った後に残る水分が少なく、仕上がりも柔らかい。","洗剤供給式床磨き機は、化学繊維のタフテッドカーペットの洗浄に向いている。","エクストラクタは、機械の中でつくった泡で洗い、すぐに吸い取る構造である。"],"a":4,"e":"エクストラクタは、ノズルから洗浄液を吹き付けてすぐに吸い取る機械(2024年度問147でも正しい記述)。泡で洗うのはドライフォーム方式の洗浄機である。","l":"法令外","c":""},{"id":"2020-149","s":5,"q":"清掃作業で使う洗剤について述べた次の文のうち、最も適当なものはどれか。","o":["表面洗剤は、界面活性剤を配合して泡立ちやすくしてある。","洗剤に使う界面活性剤は、陰イオン系と非イオン系の2つに大きく分けられる。","界面活性剤は、液体の表面張力を高くする働きをもつ。","洗剤の効果を高める助剤(ビルダ)には、汚れの再付着を防ぐものがある。","洗剤は、使う濃度が低いほどよい。"],"a":3,"e":"ビルダには汚れの再付着を防ぐ働きをもつものがある(2022年度問149でも正しい組合せ)。表面洗剤は泡立ちが少なく、界面活性剤は表面張力を下げ、洗剤には最適な濃度がある(2023年度問150)。","l":"法令外","c":""},{"id":"2020-150","s":5,"q":"清掃作業と、使う洗剤の組合せとして、最も不適当なものはどれか。","o":["真ちゅう金物の洗浄 ― 研磨剤入り洗剤","厨房の床の洗浄 ― アルカリ性洗剤","樹脂床維持剤を塗った床の剥離洗浄 ― アルカリ性洗剤","大理石の床の洗浄 ― 中性洗剤","リノリウムの床の洗浄 ― アルカリ性洗剤"],"a":4,"e":"リノリウムはアルカリに弱いので、アルカリ性洗剤は使わない(2023年度問152・2024年度問150参照)。","l":"法令外","c":""},{"id":"2020-151","s":5,"q":"ビルクリーニング作業を行うときに把握しておくべき床材の特性として、最も不適当なものはどれか。","o":["耐洗剤性","防音性","吸水性","表面の粗さ","工法・仕上げ"],"a":1,"e":"清掃方法を選ぶには、洗剤への強さ、水の吸いやすさ、表面の粗さ、工法・仕上げなどが関係する。防音性は清掃の方法には直接かかわらない。","l":"法令外","c":""},{"id":"2020-152","s":5,"q":"床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["木質系床材は水分に弱い。","塩化ビニル系床材は、薬品や水に強い。","床維持剤を塗れば、ほこりを取る作業の回数を減らせる。","セラミックタイルは、酸にもアルカリにも強い。","コンクリートは、酸に弱い。"],"a":2,"e":"床維持剤を塗っても、土砂やほこりは毎日たまるので除じんの回数は減らせない(2025年度問150でも同じ内容が誤りとされている)。","l":"法令外","c":""},{"id":"2020-153","s":5,"q":"繊維床材の清掃について述べた次の文のうち、最も適当なものはどれか。","o":["事務所建築物の繊維床材の汚れは、約60%が油性のしみである。","スポットクリーニングは、除じんで取れない汚れがパイルの上部にあるうちに行う。","ポリプロピレン素材は、親水性の汚れが取れにくい。","カーペットのほつれは、年に1〜2回まとめてカットする。","アクリル素材は、親水性の汚れが取れにくい。"],"a":1,"e":"汚れがパイルの奥にしみ込む前に取るのが基本(2021年度問151でも正しい記述)。事務所の繊維床材のしみは約60%が親水性で(2022年度問151)、ポリプロピレンは親水性の汚れがしみになりにくい(2024年度問151)。","l":"法令外","c":""},{"id":"2020-154","s":5,"q":"床維持剤のドライメンテナンス法について述べた次の文のうち、最も不適当なものはどれか。","o":["部分補修がしやすい。","前に進む作業が中心となり、作業の安全性が高い。","汚水がほとんど出ないので、環境汚染が少ない。","作業の工程数が少ない。","ドライバフ法の床磨き機は、床の土砂やほこりを取るのに使う。"],"a":4,"e":"ドライバフ法は、高速の床磨き機で皮膜を磨いて光沢を戻す方法(2022年度問150参照)。土砂やほこりはダストモップなどで取る。","l":"法令外","c":""},{"id":"2020-155","s":5,"q":"清掃について述べた次の文のうち、最も不適当なものはどれか。","o":["エレベーターホールの繊維床のスポットクリーニングは、6か月に1〜2回行う。","照明器具の定期清掃は、6か月に1回行う。","エレベーターの内壁、手すり、ドアなどは、毎日の水拭きや洗剤拭きが大切である。","トイレは、清掃作業で全面使用禁止にならないようにする。","階段の壁は、ほかの場所よりほこりが付きやすい。"],"a":0,"e":"スポットクリーニングは汚れがパイルの奥に入る前に行うもので(2021年度問151)、6か月に1〜2回では間隔が長すぎる。","l":"法令外","c":""},{"id":"2020-156","s":5,"q":"日本の廃棄物処理政策の移り変わりについて述べた次の文のうち、最も不適当なものはどれか。","o":["1950年代に、汚物を衛生的に処理し生活環境を清潔にすることを目的に、清掃法が制定された。","1970年代の廃棄物処理法の制定で、「汚物」に加えて新たに「不要物」の考え方が取り入れられた。","1980年代に、最終処分場の確保が難しいことなどに対応するため、廃棄物処理施設の整備が進められた。","1990年代に、「廃棄物」を「一般廃棄物」と「産業廃棄物」に分け、適正処理が図られた。","2000年代に、廃棄物などの発生抑制(リデュース)とともに、再使用(リユース)と再生利用(リサイクル)が図られた。"],"a":3,"e":"一般廃棄物と産業廃棄物の区分は、1970年の廃棄物処理法の制定時に設けられた(2024年度問165・2021年度問157でも同じ内容)。","l":"廃棄物処理法 第2条","c":""},{"id":"2020-157","s":5,"q":"ごみの焼却処理について述べた次の文のうち、最も不適当なものはどれか。","o":["800℃以上の高温で焼却すると、ごみに含まれる悪臭物質は熱で分解される。","焼却処理で、ごみの容積は5〜10%に減る。","焼却処理で、ごみの重さは約15%に減る。","約70%のごみ焼却施設で、余熱を使った発電が行われている。","ごみの焼却処理は、ごみの総処理量の約80%を占める。"],"a":3,"e":"この記述が誤り(余熱で発電している焼却施設の割合は約70%もない)。焼却で容積が5〜10%になることは2023年度問158でも正しい記述。","l":"法令外(環境省の統計)","c":""},{"id":"2020-159","s":5,"q":"廃棄物処理法について述べた次の文のうち、最も不適当なものはどれか。","o":["都道府県知事は、多量の一般廃棄物を出す建物の占有者に、減量に関する計画の作成などを指示できる。","排出事業者が産業廃棄物の処理を委託するときは、移動や処理の状況を自ら把握するため、マニフェストの使用が義務付けられている。","一般廃棄物の収集・運搬・処分などが適正に行われるよう、処理基準が定められている。","都道府県知事は、産業廃棄物処理業の許可申請があると、基準に合っているかを審査して許可する。","排出事業者が産業廃棄物の処理を委託するときは、委託基準に従わなければならない。"],"a":0,"e":"多量の一般廃棄物を出す建物の占有者に減量計画の作成などを指示できるのは、市町村長である(廃棄物処理法第6条の2第5項)。","l":"廃棄物処理法 第6条の2第5項","c":""},{"id":"2020-160","s":5,"q":"廃棄物処理法の一般廃棄物と産業廃棄物について述べた次の文のうち、最も不適当なものはどれか。","o":["医療機関などから出る感染のおそれのある産業廃棄物は、特別管理産業廃棄物にあたる。","飲食店から出た木くずは、産業廃棄物にあたる。","特別管理一般廃棄物には、都市ごみ焼却施設から出るばいじんや、医療機関などから出る血液の付いたガーゼ・脱脂綿がある。","事業活動で出る廃棄物は、事業系一般廃棄物と産業廃棄物に大きく分けられる。","紙くずのうち、紙製造業など特定の業種から出たものは、産業廃棄物にあたる。"],"a":1,"e":"木くずが産業廃棄物になるのは建設業など特定の業種から出た場合だけ(2021年度問160でも正しい記述)。飲食店の木くずは事業系一般廃棄物である。","l":"廃棄物処理法施行令 第2条","c":""},{"id":"2020-161","s":5,"q":"事務所建築物から厨芥が1日あたり0.25m³出ていて、その質量は全廃棄物の質量の5%を占める。全廃棄物の質量が1日あたり2.4tのとき、厨芥の単位容積質量値として正しいものはどれか。","o":["30kg/m³","120kg/m³","300kg/m³","480kg/m³","600kg/m³"],"a":3,"e":"厨芥の質量は2,400kg×0.05＝120kg。単位容積質量値＝120kg÷0.25m³＝480kg/m³。","l":"計算","c":""},{"id":"2020-162","s":5,"q":"建築物内廃棄物について述べた次の文のうち、最も適当なものはどれか。","o":["家庭から出る廃棄物より、事務所建築物から出る廃棄物の方が単位容積質量値は大きい。","厨芥とは、紙くずと雑芥を混ぜたものである。","感染性廃棄物は、長い期間保管することを考えて保管場所を決める。","建築物内に診療所がある場合は、建築物の所有者が特別管理産業廃棄物管理責任者を置かなければならない。","紙くず類の収集には、一般にキャンバス製のコレクタが使われる。"],"a":4,"e":"紙くず類は一般にキャンバス製のコレクタで集める。厨芥は生ごみで(2025年度問161)、特別管理産業廃棄物管理責任者は診療所(事業者)が置く(廃棄物処理法第12条の2第8項)。","l":"廃棄物処理法 第12条の2第8項","c":""},{"id":"2020-163","s":5,"q":"建築物内廃棄物にかかわる人たちの基本的な役割について述べた次の文のうち、最も不適当なものはどれか。","o":["国・地方公共団体は、廃棄物に関する教育・啓発を行う。","ビルメンテナンス事業者は、建築物内廃棄物の管理責任者を選ぶ。","建築物内廃棄物処理事業者は、廃棄物の容積を小さくするよう努める。","建築物維持管理権原者は、建築物内廃棄物の処理に必要な容器、集積場所、保管場所などを適切に用意する。","ビルメンテナンス事業者は、建築物内廃棄物の収集・運搬・処理・保管を行う。"],"a":1,"e":"この記述が誤り。廃棄物の管理責任者を選ぶのはビルメンテナンス事業者の役割ではない(2024年度問162でも同じ内容が誤りとされている)。","l":"法令外","c":""},{"id":"2020-164","s":5,"q":"建築物内廃棄物の貯留・搬出方式について述べた次の文のうち、最も不適当なものはどれか。","o":["容器方式は、コンパクタ・コンテナ方式より貯留・搬出の作業性にすぐれる。","真空輸送方式は、輸送管で空気によって運ぶ方式である。","コンパクタ・コンテナ方式は、大規模な建築物に向いている。","貯留・排出機方式は、真空収集方式より初期費用がかからない。","コンパクタ・コンテナ方式は、容器方式よりランニングコストが少ない。"],"a":0,"e":"容器方式は人手による作業が多く、コンパクタ・コンテナ方式より作業性は劣る(2021年度問162でも同じ内容が誤りとされている)。","l":"法令外","c":""},{"id":"2020-165","s":5,"q":"建築物内廃棄物の中間処理について述べた次の文のうち、最も適当なものはどれか。","o":["破砕機は、プラスチック類の粉砕に使う。","シュレッダは、新聞紙の切断に使う。","冷蔵庫は、厨芥類の保管に使う。","梱包機は、缶類の圧縮に使う。","圧縮装置は、段ボールの保管場所を確保するために使う。"],"a":2,"e":"生ごみ(厨芥)は腐敗や悪臭を防ぐため冷蔵庫で保管する。プラスチック類は圧縮(2025年度問162)、段ボールは梱包機(2022年度問163)を使い、新聞は切断しない。","l":"法令外","c":""},{"id":"2020-166","s":6,"q":"蚊の防除に関する記述として、最も不適当なものはどれか。","o":["昆虫成長制御剤(IGR)は、成虫を殺す効果がない。","浄化槽で殺虫剤を処理した後も成虫の数が減らない場合は、より濃い薬剤を何回も処理する。","浄化槽に殺虫剤を処理する場合は、クレゾールなどの殺菌剤を含む製剤は使わない。","防除を効果的に行うには、吸血被害の聞き取り調査や成虫の発生状況の調査を行う。","排水槽や汚水槽の通気管は、外から成虫が入ってくる経路になる。"],"a":1,"e":"効果が出ないときに、より高い濃度の薬剤を何回も処理するとした記述が誤り。","l":"法令外","c":""},{"id":"2020-167","s":6,"q":"ゴキブリの防除に関する記述として、最も不適当なものはどれか。","o":["チャバネゴキブリでは、毒餌を食べようとしない喫食抵抗性をもつ個体が知られている。","ULV処理は、室内の空間に薬剤を充満させて処理する方法である。","残留処理は、薬剤を口から取り込ませることをねらった処理方法である。","防除の前に、ゴキブリの生息密度を調べることは重要である。","ピレスロイド剤は、ゴキブリにフラッシング効果(隠れ場所から追い出す効果)を示す。"],"a":2,"e":"残留処理を、薬剤を口から取り込ませる処理とした記述が誤り。","l":"法令外","c":""},{"id":"2020-168","s":6,"q":"ダニに関する記述として、最も不適当なものはどれか。","o":["ダニの頭部には、温度や炭酸ガスを感じるための触角がある。","マダニは、血を吸う相手の動物が近づくのを、植物の葉の先で待ちかまえている。","トリサシダニやスズメサシダニの被害は、野鳥が巣立つ時期に集中する。","ヒトの皮膚の中に寄生するダニが知られている。","コナヒョウヒダニが増える温度・湿度の条件は、ヒトが快適に暮らせる条件とほぼ同じである。"],"a":0,"e":"ダニの頭部に触角があるとした記述が誤り。マダニ類で温度や炭酸ガスを感じる器官は第1脚の先端部分にある(2022年問170で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-169","s":6,"q":"ハエ類に関する記述として、最も不適当なものはどれか。","o":["イエバエの主な発生源は、畜舎やごみ処理場である。","クロバエは、夏によく見られる小型のハエである。","ショウジョウバエやチョウバエなどには、光に集まる性質(走光性)をもつ種類が多い。","国内のハエ症では、食べ物といっしょに幼虫を飲み込んで腹痛などを起こす消化器ハエ症が最も多い。","ノミバエの主な発生源は、腐った動物質である。"],"a":1,"e":"クロバエ類は、気温の低い時期に発生する大型のハエである(2016年問171で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-170","s":6,"q":"衛生害虫に関する記述として、最も不適当なものはどれか。","o":["カツオブシムシ類の幼虫は、乾燥食品や毛織物などを食べて害を与える。","シバンムシアリガタバチの幼虫は、シバンムシの体に寄生する。","コナチャタテ類は、ドライフラワーなどから発生する。","トコジラミは、シラミの仲間の吸血昆虫である。","ノミはシラミと違い、飢えに耐えることができる。"],"a":3,"e":"トコジラミをシラミの仲間とした記述が誤り。","l":"法令外","c":""},{"id":"2020-171","s":6,"q":"殺虫剤の有効成分と、その防除対象の害虫の組合せとして、最も不適当なものはどれか。","o":["フィプロニル ― チャバネゴキブリの幼虫・成虫","フェノトリン ― アカイエカの幼虫","プロペタンホス ― トコジラミの幼虫・成虫","ジクロルボス ― チカイエカの成虫","ピリプロキシフェン ― イエバエの幼虫"],"a":1,"e":"(2)の組合せが誤り。","l":"法令外","c":""},{"id":"2020-172","s":6,"q":"薬剤とその効き目に関する記述として、最も適当なものはどれか。","o":["イカリジンは、ゴキブリ類を殺す効力が高い。","ジクロルボスを有効成分とする樹脂蒸散剤がある。","LD50の値は、50%が死ぬ濃度を表している。","有機リン剤でノックダウンした個体は、生き返る傾向が強い。","昆虫成長制御剤(IGR)への抵抗性を身につけた衛生害虫は、知られていない。"],"a":1,"e":"ジクロルボスを有効成分とする樹脂蒸散剤がある(2023年問173でも正しい組合せとして出題)。なおイカリジンは吸血害虫用の忌避剤である。","l":"法令外","c":""},{"id":"2020-173","s":6,"q":"ネズミの防除に関する記述として、最も不適当なものはどれか。","o":["ネズミの毒餌をつくる場合、クマネズミには植物質のものを材料にする。","殺鼠剤で防除した場合、死体からハエ類が発生することがあるので、死んだネズミをなるべく回収する。","ネズミが入ってこないよう、通風口や換気口に付ける金属格子の目の幅は1cm以下にする。","ラットサインとは、ネズミが活動したあとに残るふん尿や足跡などのしるしのことである。","ドブネズミは警戒心が強く、毒餌やトラップでの防除が難しい。"],"a":4,"e":"警戒心が強く防除が難しいのはクマネズミで、クマネズミはドブネズミより警戒心が強い(2025年問175で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-174","s":6,"q":"ネズミ用の薬剤とその効き目に関する記述として、最も不適当なものはどれか。","o":["皮膚から取り込ませて効かせることを目的とした殺鼠剤はない。","殺鼠剤で駆除したとき、イエダニによる吸血被害が目立つようになることがある。","ネズミの薬剤抵抗性は、免疫を獲得することで発達する。","ケーブルなどのかじり防止に使える忌避剤がある。","抗凝血性殺鼠剤が死に至らせる効果は、ゆっくり現れる。"],"a":2,"e":"ネズミの殺鼠剤抵抗性は免疫の獲得によるものではなく、昆虫の殺虫剤抵抗性と同様の原理で発達する(2023年問176で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-175","s":6,"q":"衛生害虫とその健康被害に関する記述として、最も不適当なものはどれか。","o":["アカイエカは、デング熱を媒介する蚊である。","ネコノミは宿主の範囲が広く、ネコ以外の動物からも吸血する。","イエバエは、腸管出血性大腸菌を運ぶものとして注目されている。","ホテル・旅館・簡易宿泊所などで、トコジラミによる吸血被害が報告されている。","マダニ類は、重症熱性血小板減少症候群(SFTS)の病原体を媒介する。"],"a":0,"e":"デング熱を媒介するのはヒトスジシマカである(2017年問178で正しい記述として出題)。","l":"法令外","c":""},{"id":"2020-176","s":6,"q":"殺虫剤・殺鼠剤に関する記述として、最も不適当なものはどれか。","o":["昆虫の体内の加水分解酵素などが、殺虫剤の解毒にかかわっている。","殺鼠剤の安全性は、毒性の内容や強さ、食べた量、食べた期間で決まる。","殺鼠剤の多くは選択毒性が低く、ヒトにも毒性を示す。","殺鼠剤には、劇薬や毒薬にあたる製剤がある。","薬剤を実験動物に与えて求めたLD50の値は、殺虫剤の急性毒性の評価基準になる。"],"a":3,"e":"殺鼠剤に劇薬・毒薬にあたる製剤があるとした記述が誤り。","l":"法令外","c":""},{"id":"2020-177","s":6,"q":"防虫・防鼠の構造や、防除に使う機器に関する記述として、最も適当なものはどれか。","o":["ふつう16メッシュの網目なら、蚊やコバエなど多くの昆虫の侵入を防げる。","光源がナトリウム灯の場合は、白熱灯より昆虫を引き寄せやすいことが知られている。","ミスト機は、100〜400μm程度の粒の薬剤を、ゴキブリなどの生息場所にまくときに使う。","食品を扱う場所やその周りでは、毒餌や圧殺式トラップは、かぎのかかる毒餌箱に入れて置く。","噴霧機は、殺虫剤などに熱を加えず、送風装置とノズル先の衝突板で20〜100μm程度の粒を出す機器である。"],"a":3,"e":"食品を扱う場所やその周辺では、毒餌や圧殺式トラップは施錠できる毒餌箱に入れて設置する。なお多くの昆虫の侵入を防ぐには20メッシュより細かい網目が必要とされる(2023年問179)。","l":"法令外","c":""},{"id":"2020-178","s":6,"q":"殺虫剤の処理や保管に関する記述として、最も不適当なものはどれか。","o":["乳剤や油剤などには、消防法の第四類危険物のうち、第一石油類にあたるものが多い。","有機溶剤系の薬剤を扱うときは、有機溶剤に強いゴム手袋を使う。","建築物環境衛生管理基準に従って衛生害虫を防除する場合は、医薬品または医薬部外品を使わなければならない。","殺虫剤の処理で、煙感知器が作動することがある。","殺虫剤を散布するときは、散布の前後それぞれ3日間、その区域の入口に殺虫剤の種類や散布方法などを掲示して知らせる。"],"a":0,"e":"乳剤や油剤の多くが第一石油類にあたるとした記述が誤り。なお(3)は建築物衛生法施行規則第4条の5第2項第2号の定めどおり。","l":"建築物衛生法施行規則 第4条の5第2項第2号(選択肢3)","c":""},{"id":"2020-179","s":6,"q":"ねずみ・昆虫等の防除に関する記述として、最も不適当なものはどれか。","o":["ペストコントロールには、ベクターコントロールとニューサンスコントロールの2つの側面がある。","防除は、発生時の対策より発生予防の対策に重点を置いて行う。","IPM(総合的有害生物管理)で決める維持管理水準値は、建物ごと・場所ごとに決めることができる。","対策を行ったら、対象生物の密度調査などで、その効果を客観的に評価する。","IPMの「措置水準」とは、放っておくと今後問題になる可能性がある状況をいう。"],"a":4,"e":"措置水準の説明として誤り。","l":"法令外","c":""},{"id":"2020-180","s":6,"q":"害虫や薬剤に関する記述として、最も不適当なものはどれか。","o":["害虫の薬剤抵抗性の発達をおさえるため、作用のしくみが異なる薬剤のローテーション処理を行う。","有機塩素系の殺虫成分を含む製剤が、ハエ類の駆除に使われている。","炭酸ガス製剤は、有機溶剤に溶かした有効成分を液化炭酸ガスとまぜた製剤である。","昆虫などへの不快感の程度は、第三者が客観的に判断するのは難しい。","メイガ類の幼虫は、小麦粉でつくったお菓子に害を与えることがある。"],"a":2,"e":"液化炭酸ガス製剤には、有機溶媒や水は使われていない(2021年問177で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-1","s":0,"q":"現在の行政組織について、正しいものはどれか。","o":["消防法は、内閣府が所管している。","学校保健安全法は、総務省が所管している。","下水道法は、国土交通省と環境省が所管している。","浄化槽法は、厚生労働省が所管している。","保健所には、労働基準監督官が置かれている。"],"a":2,"e":"下水道法は国土交通省と環境省の所管である。消防法は総務省、学校保健安全法は文部科学省、浄化槽法は環境省と国土交通省の所管で、労働基準監督官は労働基準監督署に置かれる。","l":"法令外(各省設置法)","c":""},{"id":"2021-2","s":0,"q":"世界保健機関(WHO)憲章の前文にある健康の定義について、次の文の(ア)(イ)に入る語句の組合せとして、最も適当なものはどれか。\n「健康とは、肉体的、( ア )及び社会的に完全に良好な状態であり、単に病気や病弱でないことではない。到達できる最高水準の健康を享受することは、( イ )、宗教、政治的信念、経済的又は社会的条件による差別なしに、すべての人がもつ基本的権利の一つである。」","o":["ア 経済的　イ 人種","ア 文化的　イ 性別","ア 文化的　イ 人種","ア 精神的　イ 性別","ア 精神的　イ 人種"],"a":4,"e":"WHO憲章は、健康を「肉体的、精神的及び社会的に完全に良好な状態」とし、「人種、宗教、政治的信念、経済的又は社会的条件」による差別なく享受できる権利としている。","l":"法令外(WHO憲章 前文)","c":""},{"id":"2021-3","s":0,"q":"建築物衛生法について、誤っているものはどれか。","o":["建築物衛生法は、建物の設備・構造の面と維持管理の面の両方から規制を行っている。","事業の登録の事務は、都道府県知事が行う。","特定建築物でなくても、多くの人が使う建物は、建築物環境衛生管理基準に従って維持管理するよう努めなければならない。","特定建築物の維持管理権原者は、建築物環境衛生管理基準に従って維持管理をしなければならない。","特定建築物の所有者等には、所有者のほか、その建物全部の管理について権原をもつ者も含まれる。"],"a":0,"e":"建築物衛生法は、建物の維持管理の面から規制する法律である。設備・構造の面は建築基準法などが規制している。","l":"建築物衛生法 第1条、第4条","c":""},{"id":"2021-4","s":0,"q":"特定建築物で、特定用途に使われる部分として延べ面積に入れるものはどれか。","o":["地下街の地下道","建物の地下に電気事業者が設けた変電所","建物の中にある鉄道のプラットホーム","地下街の店舗に付属する倉庫","建物の地下にある、管理する主体が違う公共駐車場"],"a":3,"e":"店舗に付属する倉庫は、特定用途に付属する部分として延べ面積に入れる。地下道、変電所、鉄道のプラットホーム、管理主体の違う公共駐車場は入れない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2021-5","s":0,"q":"特定建築物の届出などについて、最も適当なものはどれか。","o":["今使っている建物が用途の変更で新たに特定建築物に当たる場合は、1か月前までに届け出なければならない。","届出をしなかったり、うその届出をしたりすると、30万円以下の罰金が科されることがある。","建物を取り壊す場合は、前もって、特定建築物に当たらなくなることを届け出なければならない。","届け出る事項は、政令で決められている。","届出の様式は、厚生労働省の通知で示されている。"],"a":1,"e":"届出をしない、またはうその届出をした者は30万円以下の罰金に処せられる。届出は当たることになった日・当たらなくなった日から1か月以内に行い、届出事項は厚生労働省令(施行規則)で定められている。","l":"建築物衛生法 第5条、第16条","c":""},{"id":"2021-6","s":0,"q":"建築物衛生法で備えておく帳簿書類と、その保存期間の組合せとして、最も適当なものはどれか。","o":["飲料水貯水槽の修繕の記録 ― 2年間","維持管理に関する設備の配置図 ― 5年間","新しくした空調設備の整備記録 ― 3年間","臨時に行った空気環境測定の結果 ― 3年間","排水管清掃の実施記録 ― 5年間"],"a":4,"e":"維持管理の状況(測定・検査の結果、設備の点検・整備の状況など)を書いた帳簿書類は5年間保存する。設備の配置図などの図面には保存期間の定めがない。","l":"建築物衛生法施行規則 第20条","c":""},{"id":"2021-7","s":0,"q":"建築物環境衛生管理基準の空気環境の調整について、正しいものはどれか。","o":["機械換気設備を設けている場合は、ホルムアルデヒドの量の基準は適用されない。","居室の温度を外気の温度より低くする場合は、その差をひどく大きくしない。","空気調和設備等を設けた一般の事務所には建築物衛生法と事務所衛生基準規則が適用され、居室の二酸化炭素の含有率の基準値も同じである。","外気の一酸化炭素の含有率が高く、基準値(6ppm以下)を保てない場合は、基準値を50ppm以下とすることができる。","浮遊粉じんの量の基準値は、相対沈降径がおおむね20μm以下の粒子を対象としている。"],"a":1,"e":"施行令で「居室における温度を外気の温度より低くする場合は、その差を著しくしないこと」と定められている。機械換気設備でもホルムアルデヒドの基準は適用され、浮遊粉じんの対象はおおむね10μm以下の粒子。","l":"建築物衛生法施行令 第2条第1号","c":"出題時の選択肢(4)は「基準値の10ppm以下」だったが、2022年4月の施行令改正で一酸化炭素の基準が6ppm以下になり、外気が汚れている場合の特例もなくなったため、基準値を6ppmに直した(誤りの選択肢のままで、正答は変わらない)。"},{"id":"2021-8","s":0,"q":"建築物環境衛生管理技術者について、最も適当なものはどれか。","o":["特定建築物の維持管理が環境衛生上適正に行われるよう監督する。","選任された特定建築物に常駐しなければならない。","特定建築物所有者等と雇用関係がなければならない。","特定建築物維持管理権原者に、設備の改善を命じることができる。","環境衛生上必要な事項を書いた帳簿書類を備えておかなければならない。"],"a":0,"e":"管理技術者は、特定建築物の維持管理が環境衛生上適正に行われるよう監督するために選任される。権原者には「命令」ではなく「意見を述べる」ことができる。","l":"建築物衛生法 第6条","c":""},{"id":"2021-9","s":0,"q":"建築物環境衛生管理基準にもとづく飲料水の衛生上の措置について、最も不適当なものはどれか。","o":["水道水を直結給水で特定建築物に飲料水として供給する場合は、定期の水質検査を行う必要はない。","水道水を建物内の貯水槽にためて供給する場合、貯水槽から先の飲料水の管理責任者は、その建物の維持管理権原者である。","供給する水が健康を害するおそれがあると分かったときは、すぐに給水を止め、その水を使うと危険であることを関係者に知らせる。","飲むためだけでなく、炊事用など生活に使う水も、水道法の水質基準に合った水を供給しなければならない。","水道水以外の井戸水などを使う場合、水道水と同じ水質が確保されていれば、給水栓で残留塩素を保つ必要はない。"],"a":4,"e":"井戸水などを使う場合も、給水栓で遊離残留塩素を0.1mg/L(100万分の0.1)以上に保たなければならない。","l":"建築物衛生法施行規則 第4条第1項第1号","c":""},{"id":"2021-10","s":0,"q":"建築物環境衛生管理基準にもとづく空気環境の測定方法について、誤っているものはどれか。","o":["特定建築物のふだんの使用時間中に行う。","測定する位置は、居室の中央部の床上75cm以上150cm以下である。","浮遊粉じんの量、一酸化炭素の含有率、二酸化炭素の含有率は、1日の使用時間中の平均値とする。","新築の特定建築物では、使い始めてから3年間、毎年6月1日から9月30日までの間にホルムアルデヒドを測定する。","測定は、2か月以内ごとに1回、定期に行う。"],"a":3,"e":"ホルムアルデヒドの測定は、新築・大規模修繕などの後、使い始めた日以後最初の6月1日〜9月30日の間に1回行う。3年間毎年ではない。","l":"建築物衛生法施行規則 第3条の2","c":""},{"id":"2021-11","s":0,"q":"事業の登録について、最も不適当なものはどれか。","o":["事業登録制度は、建物の環境衛生上の維持管理を行う事業者の質を高めるために設けられた。","登録を受けていない者が、登録業者やそれに似た表示をすることは禁止されている。","本社で登録をすれば、支社の営業所でも登録業者であると表示できる。","都道府県は、条例で独自に登録基準を定めることはできない。","平成14年4月に建築物空気調和用ダクト清掃業と建築物排水管清掃業が加わり、現在は8業種である。"],"a":2,"e":"登録は営業所ごとに受けるもので、本社が登録していても、登録を受けていない支社の営業所では登録業者の表示はできない。","l":"建築物衛生法 第12条の2、第12条の3","c":""},{"id":"2021-12","s":0,"q":"事業の登録の登録基準について、誤っているものはどれか。","o":["必要な機械器具について定められている。","監督者等の人的基準について定められている。","事故が起きたときの補償の対応について定められている。","作業の方法について定められている。","必要な設備について定められている。"],"a":2,"e":"登録基準は、機械器具などの物的要件、監督者などの人的要件、作業の方法などのその他の要件からなり、事故の補償対応は定められていない。","l":"建築物衛生法 第12条の2第2項、施行規則(各登録基準)","c":""},{"id":"2021-13","s":0,"q":"特定建築物の立入検査について、最も不適当なものはどれか。","o":["特定建築物でなくても、多くの人が使う建物には立入検査を行うことができる。","都道府県知事は、必要があると認めるときは、特定建築物に立入検査を行うことができる。","特定建築物の立入検査を行う職員を、環境衛生監視員という。","立入検査の権限は、保健所を設置する市の市長と特別区の区長にも与えられている。","特定建築物の立入検査は、犯罪捜査のために行ってはならない。"],"a":0,"e":"立入検査ができるのは特定建築物に対してである。特定建築物でない建物には、保健所が相談・指導を行う。","l":"建築物衛生法 第3条、第11条","c":""},{"id":"2021-14","s":0,"q":"建築物衛生法で、罰則が適用されないものはどれか。","o":["特定建築物に建築物環境衛生管理技術者を選任しない者","都道府県知事の改善命令に従わない者","維持管理の帳簿書類にうその記載をした者","建築物環境衛生管理基準を守らない者","都道府県知事の立入検査を拒んだ者"],"a":3,"e":"管理基準を守らないこと自体には罰則はない。ただし、改善命令などに従わないと罰則の対象になる。","l":"建築物衛生法 第16条","c":""},{"id":"2021-15","s":0,"q":"地域保健法について、最も不適当なものはどれか。","o":["保健所長には、原則として医師を充てる。","特別区には、保健所が設置されている。","都道府県が設置する保健所は、市町村の求めに応じて技術的な助言を行うことができる。","全国の保健所のうち、政令市が設置する保健所が最も多い。","地域保健対策の推進に関する基本的な指針には、対人保健のほか、建築物衛生に関わる事項も含まれる。"],"a":3,"e":"設置主体別にみると、都道府県が設置する保健所が最も多い。","l":"法令外(保健所の設置状況)","c":""},{"id":"2021-16","s":0,"q":"下水道法第1条の目的について、次の文の(ア)(イ)に入る語句の組合せとして、正しいものはどれか。\n「この法律は、流域別下水道整備総合計画の策定に関する事項と、公共下水道・流域下水道・都市下水路の設置その他の管理の基準などを定めて下水道の整備を図り、都市の健全な発達及び( ア )に寄与し、あわせて公共用水域の( イ )に資することを目的とする。」","o":["ア 健康で文化的な生活の確保　イ 水質の保全","ア 生活環境の改善　イ 環境の保全","ア 生活環境の改善　イ 水質の保全","ア 公衆衛生の向上　イ 環境の保全","ア 公衆衛生の向上　イ 水質の保全"],"a":4,"e":"下水道法の目的は、都市の健全な発達及び公衆衛生の向上に寄与し、あわせて公共用水域の水質の保全に資することである。","l":"下水道法 第1条","c":""},{"id":"2021-17","s":0,"q":"興行場法について、最も不適当なものはどれか。","o":["興行場とは、映画・演劇・スポーツ・演芸・見せ物を、公衆に見せたり聞かせたりする施設をいう。","興行場の営業を行うには、興行場法にもとづく許可が必要である。","興行場の維持管理は、都道府県の条例で定める換気・照明・防湿・清潔などの衛生基準に従わなければならない。","興行場は、国が定める構造設備の基準に従わなければならない。","特定建築物に当たる興行場は、建築物衛生法と興行場法のそれぞれの衛生上の基準を守らなければならない。"],"a":3,"e":"興行場の構造設備の基準は、国ではなく都道府県などの条例で定められる。","l":"興行場法 第2条、第3条","c":""},{"id":"2021-18","s":0,"q":"大気汚染防止法第1条の目的として、誤っているものはどれか。","o":["排出ガスに含まれるダイオキシン類の量について許容限度を定める。","揮発性有機化合物の排出などを規制する。","有害大気汚染物質対策の実施を進める。","自動車排出ガスの許容限度を定める。","水銀等の排出を規制する。"],"a":0,"e":"ダイオキシン類の排出規制は、大気汚染防止法ではなくダイオキシン類対策特別措置法で定められている。","l":"大気汚染防止法 第1条","c":""},{"id":"2021-19","s":0,"q":"環境基本法で、環境基準が定められていないものはどれか。","o":["大気の汚染","振動","土壌の汚染","騒音","水質の汚濁"],"a":1,"e":"環境基準が定められているのは、大気の汚染・水質の汚濁・土壌の汚染・騒音の4つで、振動には環境基準がない。","l":"環境基本法 第16条","c":""},{"id":"2021-20","s":0,"q":"労働安全衛生法に定められている内容として、最も不適当なものはどれか。","o":["国による労働災害防止計画の策定","一定の事業場での安全衛生委員会の設置","都道府県知事によるボイラーの製造許可","一定の事業者による産業医の選任","事業者による快適な作業環境の維持管理"],"a":2,"e":"ボイラーなど特定機械等の製造許可を出すのは、都道府県知事ではなく都道府県労働局長である。","l":"労働安全衛生法 第37条","c":""},{"id":"2021-21","s":1,"q":"生体の恒常性(ホメオスタシス)などについて、最も不適当なものはどれか。","o":["外の環境が変わっても、体の内部の環境を一定に保つ仕組みを恒常性という。","恒常性は、主に神経系・内分泌系・免疫系のはたらきで保たれている。","外からの刺激は受容器で受け取られて中枢に伝わり、効果器に興奮が伝わって反応が起こる。","体に刺激が加わると体内に変化が起こり、適応しようとする反応が非特異的に起こる。","年をとると取りこむエネルギー量は減るが、エネルギーを予備力としてたくわえる能力は増える。"],"a":4,"e":"年をとると、エネルギーを予備力としてたくわえる能力(予備力)も低下する。","l":"法令外","c":""},{"id":"2021-22","s":1,"q":"健康に影響する環境要因のうち、「物理的要因」として最も不適当なものはどれか。","o":["オゾン","湿度","気圧","温度","音"],"a":0,"e":"オゾンは物質なので、化学的要因に分類される。","l":"法令外","c":""},{"id":"2021-23","s":1,"q":"温熱環境の指数について、最も不適当なものはどれか。","o":["黒球温度は、熱放射と対流に関わる温度を測るのに使われる。","湿球黒球温度(WBGT)は、屋内外の暑い作業での暑熱ストレスを評価するのに使われる。","有効温度は、湿度100%・無風の部屋の気温に置きかえて表す、体感にもとづく指数である。","標準新有効温度は、気温・湿度・風速・熱放射・着衣量・代謝量の6つの要素を含んだ指標である。","不快指数は、気温に関係なく使える指標である。"],"a":4,"e":"不快指数は気温と湿度から求める夏の蒸し暑さの指標で、気温が低いときには使えない。","l":"法令外","c":""},{"id":"2021-24","s":1,"q":"体温調節について、最も不適当なものはどれか。","o":["寒い環境では、暖かい環境と比べて、体の内部と体の表面との温度差が小さくなる。","平均皮膚温を求めるHardy-DuBoisの7点法で、皮膚温の重みが一番大きいのは腹である。","冷房や扇風機を使うことは、行動性体温調節である。","熱を逃がすこと(熱放散)は、対流・放射・伝導・蒸発の物理的な過程からなる。","核心温は、体の表面の温度に比べて、外気温の影響を受けにくい。"],"a":0,"e":"寒い環境では皮膚の血管が縮んで体表面の温度が下がるため、体の内部と表面との温度差は大きくなる。","l":"法令外","c":""},{"id":"2021-25","s":1,"q":"温熱環境と体の熱のつり合いについて、最も不適当なものはどれか。","o":["対流による熱放散は、流体の流れにともなう熱エネルギーの移動である。","蒸発による熱放散は、水分が皮膚から気化するときに、皮膚表面から潜熱をうばう現象である。","暑い環境では、体の熱をつくる量は下がる。","人体側の温熱環境の要素は、代謝量と着衣量である。","伝導による熱放散は、体と直接ふれている物との間の熱エネルギーの移動である。"],"a":2,"e":"暑い環境では、発汗や血液循環の増加などで代謝が上がり、熱をつくる量はむしろ増える。","l":"法令外","c":""},{"id":"2021-26","s":1,"q":"熱中症について、最も不適当なものはどれか。","o":["熱けいれんは、大量に汗をかいたとき、水分だけを大量にとることで起こる。","熱疲労では、大量の汗で体内の水分と塩分が足りなくなり、臓器のはたらきが落ちる。","熱失神は最も重い熱中症で、体温が異常に上がる。","皮膚の病気やひどい日焼けのときは汗をかくはたらきが落ちるので、注意が必要である。","熱射病の治療では、冷やしすぎに注意する必要がある。"],"a":2,"e":"最も重い熱中症は熱射病で、体温が異常に上がる。熱失神は、皮膚の血管が広がって血圧が下がることによる一時的な意識の消失である。","l":"法令外","c":""},{"id":"2021-27","s":1,"q":"ヒトの発がんの原因について、最も不適当なものはどれか。","o":["発がんの要因として、食事が3分の1を占める。","感染症が、がんの原因になることがある。","ラドンにさらされると、肺がんのリスクが上がる。","DNAに最初に傷をつけ、変異を起こさせる物質をプロモータという。","ホルムアルデヒドには発がん性が認められる。"],"a":3,"e":"最初にDNAに傷をつける物質はイニシエータである。プロモータは、傷のついた細胞の増殖を促す物質。","l":"法令外","c":""},{"id":"2021-28","s":1,"q":"アスベストについて、最も不適当なものはどれか。","o":["人工的に合成された化学物質である。","胸膜中皮腫の潜伏期間の多くは、20〜50年である。","吸いこむと、肺の線維化を起こす。","肺がんについて、アスベストへの曝露と喫煙の相乗作用が示されている。","中皮腫や肺がんになる危険度は、アスベストに累積でさらされた量が多いほど高くなる。"],"a":0,"e":"アスベストは、自然界にある繊維状のケイ酸塩鉱物で、合成された化学物質ではない。","l":"法令外","c":""},{"id":"2021-29","s":1,"q":"アレルギーについて、最も不適当なものはどれか。","o":["湿度が低いことは、アトピー性皮膚炎を悪化させる要因である。","アレルゲンを特定することは、予防や治療のうえで大切である。","ヒスタミンは、アレルゲンの一種である。","アレルギー反応とは、体に有害な免疫反応をいう。","過敏性肺炎の一種である加湿器肺を防ぐには、加湿器の微生物汚染を防ぐことが大切である。"],"a":2,"e":"ヒスタミンは、アレルギー反応が起きたときに体の細胞から出る化学伝達物質で、アレルゲン(原因物質)ではない。","l":"法令外","c":""},{"id":"2021-30","s":1,"q":"シックビル症候群でみられる症状などについて、最も不適当なものはどれか。","o":["目やのどの刺激、くしゃみなどの症状は、加湿すると減る。","そのビルを使うすべての人に症状がみられる。","外気の供給が足りないことは、発症の危険因子である。","胸の圧迫感、息切れ、せきなどの症状が出ることがある。","アトピー体質は、発症の危険因子である。"],"a":1,"e":"シックビル症候群の症状は、そのビルを使う人の一部にみられるもので、すべての人に出るわけではない。","l":"法令外","c":""},{"id":"2021-31","s":1,"q":"受動喫煙について、最も適当なものはどれか。","o":["医療機関の受動喫煙防止対策は、地域保健法で定められている。","喫煙専用室には、20歳未満の人は立ち入れないという掲示が必要である。","副流煙とは、たばこを吸う人が吐き出す煙のことである。","たばこの煙のニコチンやタールは、副流煙より主流煙に多く含まれる。","受動喫煙によって、子どもの呼吸器の病気のリスクは増えない。"],"a":1,"e":"健康増進法により、喫煙専用室などには20歳未満の者が立ち入れない旨を掲示しなければならない。受動喫煙防止は健康増進法の規定で、副流煙はたばこの先から出る煙、有害物質は副流煙に多い。","l":"健康増進法 第33条","c":""},{"id":"2021-32","s":1,"q":"音について、最も不適当なものはどれか。","o":["聴力レベルがプラスの値であることは、基準より聴力が良いことを意味する。","音を感じとる器官である耳は、外耳・中耳・内耳に分けられる。","耳に届く音には、頭の骨を伝わる音も含まれる。","音の大きさを評価する尺度に、聴覚の周波数特性で補正したA特性音圧レベルがある。","職場の定期健康診断では、聴力のスクリーニングとして1,000Hzと4,000Hzの聴力レベルを測る。"],"a":0,"e":"聴力レベルがプラスの値であるほど、小さい音が聞こえにくい(聴力が悪い)ことを意味する。","l":"法令外","c":""},{"id":"2021-33","s":1,"q":"騒音について、最も不適当なものはどれか。","o":["騒音性難聴は、4,000Hz付近の聴力低下から始まる。","老人性難聴の初期には、会話の音域である2,000Hzの周波数から聴力が落ちる。","環境騒音によって自律神経が刺激され、血圧の上昇などがみられる。","長い間85dB以上の騒音にさらされると、永久的な聴力低下になる危険性が高くなる。","住民の騒音の苦情の大半は、聞きとりの妨げと心理的影響である。"],"a":1,"e":"老人性(加齢性)難聴は、高い周波数の音から聞こえにくくなるのが特徴で、会話音域から始まるのではない。","l":"法令外","c":""},{"id":"2021-34","s":1,"q":"振動について、最も不適当なものはどれか。","o":["振動レベルの単位はデシベル(dB)である。","局所振動による健康障害は、冬に多くみられる。","局所振動による障害に、レイノー現象と呼ばれる指の末梢神経の障害がある。","フォークリフトの運転で垂直方向の振動にさらされると、胃下垂などが起こる。","全身振動は、垂直方向の振動と水平方向の振動に分けて評価する。"],"a":2,"e":"レイノー現象は、指の血管が縮んで血行が悪くなる「末梢循環障害」であり、末梢神経障害ではない。","l":"法令外","c":""},{"id":"2021-35","s":1,"q":"光の知覚について、最も不適当なものはどれか。","o":["目が見る対象の細かい部分を見分ける能力を、視力という。","見る対象を正確に認識することを明視といい、その条件は、大きさ・対比・時間・明るさである。","視細胞は角膜にある。","暗順応にかかる時間は、明順応より長い。","錐体細胞には赤・青・緑の光にそれぞれ反応する3種類があり、その反応の組合せで色を感じる。"],"a":2,"e":"視細胞(錐体・杆体)は、目の奥の網膜にある。","l":"法令外","c":""},{"id":"2021-36","s":1,"q":"情報機器作業について、最も不適当なものはどれか。","o":["作業者の健康調査で、最も多い自覚症状は目の症状である。","ディスプレイのまぶしさ(グレア)を防ぐには、直接照明を使う。","書類の上とキーボードの上の照度は、300lx以上が勧められる。","ディスプレイ画面の上の照度は、500lx以下が勧められる。","ディスプレイ画面・書類・キーボードの明るさと周りの明るさとの差は、なるべく小さくする。"],"a":1,"e":"グレアを防ぐには、間接照明などを使って光源が直接画面に映りこまないようにする。","l":"法令外(情報機器作業における労働衛生管理のためのガイドライン)","c":""},{"id":"2021-37","s":1,"q":"電磁波について、最も不適当なものはどれか。","o":["レーザー光線には、可視光のレーザーのほか、赤外線や紫外線のレーザーがある。","溶接作業で起こる電気性眼炎は、紫外線による。","赤外線は、白内障の原因になる。","マイクロ波の主な用途の一つに、家庭用の電子レンジがある。","可視光線の波長は、赤外線より長い。"],"a":4,"e":"可視光線の波長は赤外線より短い(赤外線のほうが長い)。","l":"法令外","c":""},{"id":"2021-38","s":1,"q":"電離放射線の健康影響のうち、「確定的影響」でありかつ「晩発影響」であるものとして、最も適当なものはどれか。","o":["不妊","染色体異常","白血病","白内障","甲状腺がん"],"a":3,"e":"白内障は、しきい線量を超えると起こる確定的影響で、被ばくから時間がたって現れる晩発影響でもある。白血病や甲状腺がんは確率的影響、不妊は早期に現れる影響。","l":"法令外","c":""},{"id":"2021-39","s":1,"q":"ヒトと水について、最も適当なものはどれか。","o":["ふだんの状態で、水が最も多く出ていくのは尿で、その次は皮膚からの蒸散である。","成人の体内の水分量は、体重の約80%である。","水分の不足が体重の5%以上になると、のどの渇きを感じる。","ヒトが生理的に必要とする水分量は、成人で1日あたり約3Lである。","体の中では、細胞内液より細胞外液のほうが多い。"],"a":0,"e":"体から出ていく水分は尿が最も多く、次が皮膚からの蒸散(不感蒸泄)である。成人の水分量は体重の約60%、のどの渇きは約1%の不足で起こり、細胞内液のほうが多い。","l":"法令外","c":""},{"id":"2021-40","s":1,"q":"水質汚濁に係る環境基準の項目について、最も適当なものはどれか。","o":["ヒ素は、短時間に大量にさらされると皮膚の色素沈着を起こす。","亜鉛は、水俣病の原因になる。","カドミウムは、水質汚濁の環境基準で「検出されないこと」となっている。","アルキル水銀は、生物学的濃縮を起こす。","ベンゼンには、ヒトに対する発がん性は認められない。"],"a":3,"e":"アルキル水銀(有機水銀)は生物濃縮を起こし、水俣病の原因となった。カドミウムには数値の基準があり、ベンゼンには発がん性が認められている。","l":"法令外","c":""},{"id":"2021-41","s":1,"q":"感染症法の感染症の類型について、最も不適当なものはどれか。","o":["一類感染症では、交通が制限されることがある。","二類感染症では、建物への立入りは制限されない。","三類感染症では、就業が制限される職種がある。","四類感染症では、積極的疫学調査は行われない。","五類感染症には、ジアルジア症が含まれる。"],"a":3,"e":"積極的疫学調査は、一類〜五類感染症などすべての類型で行うことができ、四類感染症も対象である。","l":"感染症法 第15条","c":""},{"id":"2021-42","s":1,"q":"次の感染症のうち、主に空気を介して感染するものはどれか。","o":["デング熱","B型肝炎","ペスト","日本脳炎","麻しん"],"a":4,"e":"麻しん(はしか)は、空気感染(飛沫核感染)で広がる。デング熱と日本脳炎は蚊、B型肝炎は血液、ペストはノミなどを介して感染する。","l":"法令外","c":""},{"id":"2021-43","s":1,"q":"クリプトスポリジウム症について、最も適当なものはどれか。","o":["病原体は細菌である。","ヒトやほ乳類の消化管の中で増える。","水道水の塩素消毒で死滅する。","水道におけるクリプトスポリジウム等対策指針では、レベル1が最もリスクが高い。","下痢の症状は1〜2日で治まる。"],"a":1,"e":"クリプトスポリジウムは原虫で、ヒトやほ乳類の消化管の中で増殖する。塩素に強く、通常の塩素消毒では死なない。","l":"法令外","c":""},{"id":"2021-44","s":1,"q":"5%溶液として売られている次亜塩素酸ナトリウムを水で薄めて、100mg/Lの溶液を10Lつくるとき、必要な5%溶液の量に最も近いものはどれか。","o":["0.2mL","4mL","20mL","40mL","200mL"],"a":2,"e":"必要な有効成分は100mg/L×10L=1,000mg=1g。5%溶液なので 1g÷0.05=20g(約20mL)。","l":"法令外(計算)","c":""},{"id":"2021-45","s":1,"q":"滅菌(すべての微生物を死滅・除去すること)に使われるものとして、最も不適当なものはどれか。","o":["γ線","ろ過","エチレンオキサイドガス","高圧蒸気","紫外線"],"a":4,"e":"紫外線は表面の殺菌・消毒には使われるが、物の内部まで届かないため、滅菌の方法としては使われない。","l":"法令外","c":""},{"id":"2021-46","s":2,"q":"下に示す湿り空気線図に関する次の記述のうち、最も不適当なものはどれか。","o":["乾球温度14℃、相対湿度80%の空気を加熱コイルで25℃に温めると相対湿度は約40%となる。","乾球温度10℃、相対湿度80%の空気は、乾球温度22℃、相対湿度30%の空気より絶対湿度が高い。","乾球温度22℃、相対湿度60%の空気が表面温度15℃の窓ガラスに触れると結露する。","乾球温度19℃の空気が含むことのできる最大の水蒸気量は、0.010kg/kg(DA)より大きい。","露点温度10℃の空気は、乾球温度29℃において約30%の相対湿度となる。"],"a":2,"e":"22℃・60%の空気の露点温度は約14℃。窓ガラスが15℃なら露点より高いので結露しない。","l":"法令外","c":"","g":["img/2021-46.png"]},{"id":"2021-47","s":2,"q":"結露についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「暖房時に壁の内部や表面の結露を防ぐには、壁の中で水蒸気圧の[ア]側に、[イ]の低い[ウ]を設けることが有効である。」","o":["ア 高い/イ 熱伝導率/ウ 断熱材","ア 高い/イ 湿気伝導率/ウ 防湿層","ア 低い/イ 湿気伝導率/ウ 防湿層","ア 低い/イ 熱伝導抵抗/ウ 断熱材","ア 低い/イ 湿気伝導率/ウ 断熱材"],"a":1,"e":"冬は室内側の水蒸気圧が高いので、その側(断熱層の室内側)に湿気を通しにくい防湿層を設けて、水蒸気が壁の中に入らないようにする(2023年度・2024年度の問題でも同じ内容が正しい記述)。","l":"法令外","c":""},{"id":"2021-48","s":2,"q":"下の図は、建築材料表面(白色プラスター、アスファルト、新しい亜鉛鉄板、光ったアルミ箔)の長波長放射率と日射吸収率の関係を示している。A〜Dの組合せとして、最も適当なものはどれか。","o":["A 白色プラスター/B アスファルト/C 光ったアルミ箔/D 新しい亜鉛鉄板","A 光ったアルミ箔/B 新しい亜鉛鉄板/C 白色プラスター/D アスファルト","A 白色プラスター/B アスファルト/C 新しい亜鉛鉄板/D 光ったアルミ箔","A アスファルト/B 白色プラスター/C 新しい亜鉛鉄板/D 光ったアルミ箔","A 新しい亜鉛鉄板/B 光ったアルミ箔/C 白色プラスター/D アスファルト"],"a":0,"e":"白色プラスターは日射をあまり吸収せず長波長はよく放射する(A)。アスファルトはどちらも大きい(B)。光ったアルミ箔はどちらも小さい(C)。新しい亜鉛鉄板は日射吸収率が中くらいで放射率は小さい(D)。","l":"法令外","c":"","g":["img/2021-48.png"]},{"id":"2021-49","s":2,"q":"下の図は、厚さの異なるA、B、C部材で構成された建築物外壁における定常状態の内部温度分布を示している。この図に関する次の記述のうち、最も不適当なものはどれか。","o":["A、B、C部材のなかで、最も熱伝導率が大きい部材はB部材である。","熱伝達率は、屋外側の方が室内側より大きい。","B部材が主体構造体であるとすれば、この図は内断熱構造を示している。","壁表面近傍で空気温度が急激に変化する部分を境界層という。","A、B、C部材のなかで、部材を流れる単位面積当たりの熱流量が最も大きいのはA部材である。"],"a":4,"e":"定常状態では、熱は途中でたまらずに壁を通り抜けるので、A・B・Cどの部材でも単位面積当たりの熱流量は同じ。A部材だけが大きくなることはない。","l":"法令外","c":"","g":["img/2021-49.png"]},{"id":"2021-50","s":2,"q":"空気の流れについて述べた次の文のうち、最も不適当なものはどれか。","o":["冷房で天井面に沿って吹き出した噴流は、速度が小さいと途中ではがれて下に降りることがある。","コールドドラフトは、冷たい壁の近くなどで起きる冷たい下降気流である。","自由噴流の第3域では、中心軸の速度は吹出口からの距離に反比例して小さくなる。","吹出しの影響は遠くまで及ぶが、吸込みの影響は吸込口の近くに限られる。","ふつうの窓の流量係数は約1.0である。"],"a":4,"e":"ふつうの窓の流量係数は0.6〜0.7程度で、1.0より小さい。","l":"法令外","c":""},{"id":"2021-51","s":2,"q":"流体力学について述べた次の文のうち、最も不適当なものはどれか。","o":["直線ダクトの圧力損失は、長さに比例する。","直線ダクトの圧力損失は、風速に比例する。","直線の円形ダクトの圧力損失は、直径に反比例する。","ダクトの形が変わることによる圧力損失は、形状抵抗係数に比例する。","開口部を通る風量は、開口部前後の圧力差の平方根に比例する。"],"a":1,"e":"ダクトの圧力損失は風速の2乗に比例する(2023年度問51などでも「風速の2乗に比例」が正しい記述)。","l":"法令外","c":""},{"id":"2021-52","s":2,"q":"換気について述べた次の文のうち、最も不適当なものはどれか。","o":["単位時間に室内で入れ替わる新鮮空気(外気)の量を換気量という。","空気交換効率とは、室内の空気がどれだけ効率よく新鮮空気と入れ替わるかを示す尺度である。","1時間に窓を開ける回数を換気回数という。","外気が給気口から室内の任意の点に届くまでの平均時間を、局所平均空気齢という。","ある汚染物質の室内濃度を基準値に保つために必要な換気量を、必要換気量という。"],"a":2,"e":"換気回数は、1時間の換気量を室の容積で割ったもの(2024年度問56でも正しい記述として出題)。窓を開ける回数ではない。","l":"法令外","c":""},{"id":"2021-53","s":2,"q":"ある居室に16人いるとき、室内の二酸化炭素濃度を建築物環境衛生管理基準値以下に保つために最低限必要な換気量として正しいものはどれか。ただし、室内は定常状態・完全混合、外気の二酸化炭素濃度は400ppm、1人あたりの二酸化炭素発生量は0.018m³/hとする。","o":["320m³/h","400m³/h","480m³/h","600m³/h","720m³/h"],"a":2,"e":"二酸化炭素の基準値は1,000ppm以下(施行令第2条)。発生量は16×0.018＝0.288m³/h。必要換気量＝0.288÷(1,000－400)×10⁶＝0.288÷0.0006＝480m³/h。","l":"計算(基準値は建築物衛生法施行令 第2条)","c":""},{"id":"2021-54","s":2,"q":"室内のホルムアルデヒドの発生源として、最も不適当なものはどれか。","o":["ユリア樹脂系接着剤","パーティクルボード","家具","コンクリート","喫煙"],"a":3,"e":"ホルムアルデヒドは、それを原料とする接着剤や、接着剤を使った合板・パーティクルボード・家具、たばこの煙などから出る。コンクリートはおもな発生源ではない。","l":"法令外","c":""},{"id":"2021-55","s":2,"q":"室内汚染物質と発生源の組合せとして、最も不適当なものはどれか。","o":["アセトアルデヒド ― 加熱式たばこ","窒素酸化物 ― 開放型燃焼器具","オゾン ― レーザープリンタ","ラドン ― 石材","フェノブカルブ ― 接着剤"],"a":4,"e":"この組合せが誤り。フェノブカルブは殺虫剤・防蟻剤などに使われる成分で、接着剤から出るものではない。","l":"法令外","c":""},{"id":"2021-56","s":2,"q":"換気について述べた次の文のうち、最も不適当なものはどれか。","o":["換気の目的の一つは、汚染物質を室内から取り除くことである。","ハイブリッド換気は、自然換気と機械換気を組み合わせる換気方式である。","第1種換気は、機械給気と機械排気による換気である。","局所換気は、汚染物質が出る場所を部分的に換気する方法である。","第3種換気は、機械給気と自然排気口による換気である。"],"a":4,"e":"第3種換気は、自然給気口と機械排気による換気。機械給気と自然排気の組合せは第2種換気である(2022年度問54参照)。","l":"法令外","c":""},{"id":"2021-57","s":2,"q":"浮遊粒子の動きにかかわる次のア〜エの性質のうち、粒径が大きくなるほど値が大きくなるものの組合せとして最も適当なものはどれか。\nア 終末沈降速度\nイ 拡散係数\nウ 気流と平行な垂直面への沈着速度\nエ 粒子が気体から受ける抵抗力","o":["アとイ","アとウ","アとエ","イとエ","ウとエ"],"a":2,"e":"大きい粒子ほど速く沈み、気体から受ける抵抗力も大きくなる。拡散係数と、拡散による垂直面への沈着速度は、粒径が大きいほど小さくなる(2025年度問58参照)。","l":"法令外","c":""},{"id":"2021-58","s":2,"q":"アレルゲンと微生物などについて述べた次の文のうち、最も不適当なものはどれか。","o":["ウイルスは建材の表面で増えることがある。","アスペルギルスは、一般の環境にすむカビである。","オフィスビル内の細菌のおもな発生源は、在室者である。","酵母は真菌に分類される。","カビアレルゲンの大部分は、数μm以上の粒子である。"],"a":0,"e":"ウイルスは生きた細胞の中でしか増えられないので、建材の表面で増えることはない(2024年度問54参照)。","l":"法令外","c":""},{"id":"2021-59","s":2,"q":"パッケージ型空調機について述べた次の文のうち、最も適当なものはどれか。","o":["中央方式の空気調和設備と同じように、熱源設備が必要である。","圧縮機はすべて電力で動かしている。","ふつうは外気処理の機能を備えている。","ビル用マルチパッケージは、ON-OFF制御で圧縮機の容量を制御するのが主流である。","水熱源ヒートポンプ方式のパッケージ型空調機は、圧縮機を備えているので騒音に注意が必要である。"],"a":4,"e":"水熱源ヒートポンプ方式のパッケージ型空調機は室内側に圧縮機をもつので、騒音に注意が必要(2022年度問63でも正しい記述)。ガスエンジン駆動もあり、外気処理機能はふつうなく、インバータ制御が主流である。","l":"法令外","c":""},{"id":"2021-60","s":2,"q":"空気調和設備について述べた次の文のうち、最も不適当なものはどれか。","o":["HEMSと呼ばれる総合的なビル管理システムの導入が進んでいる。","空気調和機には、広い意味ではファンコイルユニットも含まれる。","熱搬送設備は、配管系設備とダクト系設備に大きく分けられる。","冷凍機、ボイラ、ヒートポンプ、チリングユニットは熱源機器にあたる。","自動制御設備の中央監視装置は、省エネルギーや室内環境の確保のために設備機器を監視・制御する設備である。"],"a":0,"e":"ビルのエネルギー管理システムはBEMS(ビルディング・エネルギー・マネジメント・システム)。HEMSは住宅(ホーム)向けのシステムである。","l":"法令外","c":""},{"id":"2021-61","s":2,"q":"躯体蓄熱システムについての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「躯体蓄熱システムでは蓄熱槽や熱源機器の容量を減らせるが、氷蓄熱に比べて熱損失が[ア]、蓄熱投入熱量比が[イ]。また、放熱時の熱量の制御は[ウ]である。」","o":["ア 大きく/イ 大きい/ウ 容易","ア 小さく/イ 大きい/ウ 容易","ア 大きく/イ 小さい/ウ 容易","ア 小さく/イ 大きい/ウ 困難","ア 大きく/イ 小さい/ウ 困難"],"a":4,"e":"躯体蓄熱は建物の構造体に熱を蓄えるので、氷蓄熱より熱損失が大きく(2025年度問67でも正しい記述)、蓄熱投入熱量比は小さい。構造体から自然に放熱されるため、放熱量の制御は難しい。","l":"法令外","c":""},{"id":"2021-62","s":2,"q":"湿り空気線図上での空調の操作について述べた次の文のうち、最も不適当なものはどれか。","o":["暖房時に水噴霧加湿を使う場合、温水コイル出口の温度は設計給気温度より高くする必要がある。","冷房時の室内熱負荷の顕熱比SHF＝0.8の場合、空調機からの吹出し空気の絶対湿度は室内空気より低くする必要がある。","温水コイルを通った空気は単純加熱となり、通る前後で絶対湿度は変わらない。","還気と外気を混ぜた状態は、湿り空気線図上で両者の状態点を結んだ直線上にある。","冷水コイルで冷却除湿すると、コイル出口の空気の相対湿度は100%になる。"],"a":4,"e":"コイルに触れずに通り抜ける空気(バイパス空気)があるため、コイル出口の相対湿度は100%にはならない(2023年度問63でも正しい記述)。","l":"法令外","c":""},{"id":"2021-63","s":2,"q":"冷水コイルによる空気の冷却についての次の文の[ア]・[イ]に入るものの組合せとして、最も適当なものはどれか。\n「湿り空気線図上で、冷水コイル入口の空気の状態点をA、出口の空気の状態点をBとし、乾球温度がAと等しく絶対湿度がBと等しい状態点をCとする。A・B・Cの比エンタルピーをhA・hB・hC、コイルを通る空気の質量流量をG[kg/h]とすると、冷水コイルで除去する熱量のうち潜熱分は[ア]、顕熱分は[イ]で表される。」","o":["ア G(hA－hB)/イ G(hA－hC)","ア G(hA－hC)/イ G(hA－hB)","ア G(hA－hC)/イ G(hC－hB)","ア G(hC－hB)/イ G(hA－hB)","ア G(hC－hB)/イ G(hA－hC)"],"a":2,"e":"A→Cは温度が同じで絶対湿度だけが減る変化なので潜熱分はG(hA－hC)。C→Bは絶対湿度が同じで温度だけが下がる変化なので顕熱分はG(hC－hB)。","l":"法令外","c":""},{"id":"2021-64","s":2,"q":"空気調和方式について述べた次の文のうち、最も不適当なものはどれか。","o":["定風量単一ダクト方式は、給気量を一定にし、給気温度を変えて熱負荷の変化に対応する方式である。","変風量単一ダクト方式は、定風量単一ダクト方式より空気質の確保に有利である。","ダクト併用ファンコイルユニット方式は、単一ダクト方式とファンコイルユニットを組み合わせて個別制御しやすくしたシステムである。","放射冷暖房では、冷房時の表面結露や空気質の確保に配慮が必要である。","マルチゾーン空調方式は、負荷の変わり方が違う複数のゾーンの温湿度調整を1台の空調機で行う方式である。"],"a":1,"e":"変風量方式は負荷が小さいと給気量を絞るため外気の取入れ量も減り(2025年度問63参照)、空気質の確保にはむしろ不利になる。","l":"法令外","c":""},{"id":"2021-65","s":2,"q":"冷凍機について述べた次の文のうち、最も不適当なものはどれか。","o":["スクロール圧縮機は、渦巻き状の固定スクロールと旋回スクロールの旋回によって冷媒を圧縮する。","スクリュー圧縮機を使った冷凍機は、スクロール圧縮機を使ったものより冷凍容量が大きい。","吸収冷凍機は都市ガスを使うので、特別な運転資格が必要である。","遠心圧縮機は、容積式圧縮機より吸い込んで圧縮できるガスの量が大きい。","シリカゲルやゼオライトなどの固体吸着剤を使う吸着冷凍機は、高い成績係数が得られない。"],"a":2,"e":"吸収冷凍機は機内が真空で高圧ガスを使わないため、特別な運転資格はいらない(2023年度問64でも正しい記述)。","l":"法令外","c":""},{"id":"2021-66","s":2,"q":"空気調和設備の熱源方式について述べた次の文のうち、最も不適当なものはどれか。","o":["地域冷暖房システムは、個別の熱源システムに比べ、一般に環境負荷が増える。","蓄熱システムは、電力負荷の平準化や熱源装置の容量削減に効果がある。","電動冷凍機とボイラを組み合わせる方式では、夏に電力消費量がピークになる。","直焚吸収冷温水機は、1台で冷水だけ・温水だけでなく、両方を同時につくることもできる。","電力需要を中心に運転するコージェネレーション方式では、空調などの熱需要に追いつけない場合がある。"],"a":0,"e":"地域冷暖房は熱源をまとめて効率よく運転できるので、個別熱源より大気汚染などの環境負荷は小さくなる(2024年度問64でも正しい記述)。","l":"法令外","c":""},{"id":"2021-67","s":2,"q":"図は、蒸気圧縮冷凍サイクルにおける冷媒の標準的な状態変化をモリエル線図上に表したものである。圧縮機の出口直後に相当する図中の状態点として、最も適当なものはどれか。","o":["ア","イ","ウ","エ","オ"],"a":0,"e":"蒸発器を出たガス(オ)を圧縮機で圧縮すると、圧力と比エンタルピーがともに上がりアになる。ア→イ→ウが凝縮器、ウ→エが膨張弁、エ→オが蒸発器。","l":"法令外","c":"","g":["img/2021-67.png"]},{"id":"2021-68","s":2,"q":"熱源方式について述べた次の文のうち、最も不適当なものはどれか。","o":["ヒートポンプ方式は、1台で温熱源と冷熱源を兼ねられる。","蓄熱システムの顕熱を利用する蓄熱体として、氷や無機水和塩類が使われる。","ヒートポンプ方式は、地下水や工場排熱などの未利用エネルギーも活用できる。","太陽熱を使った空調熱源システムは、エネルギーを安定して供給するのが難しい。","吸収冷凍機＋蒸気ボイラ方式は、空調以外に高圧蒸気を使う用途の建物でよく使われる。"],"a":1,"e":"氷や無機水和塩類は、凍ったり溶けたりするときの熱を使う潜熱利用の蓄熱材である(2025年度問67でも正しい記述)。顕熱利用は水や躯体など。","l":"法令外","c":""},{"id":"2021-69","s":2,"q":"冷却塔について述べた次の文のうち、最も不適当なものはどれか。","o":["開放型冷却塔は、密閉型より小型である。","開放型冷却塔の冷却水は、レジオネラ属菌の繁殖に注意が必要である。","開放型冷却塔は、密閉型冷却塔より送風機の動力が大きい。","密閉型冷却塔は、電算室やクリーンルームの系統の冷却塔として使われる。","密閉型冷却塔は散布水系統の保有水量が少ないので、保有水中の不純物濃度が高くなる。"],"a":2,"e":"送風機の動力が大きいのは通風抵抗の大きい密閉型の方である(2025年度問70でも「開放型は送風機動力が小さい」が正しい記述)。","l":"法令外","c":""},{"id":"2021-70","s":2,"q":"加湿装置の種類と加湿方式の組合せとして、最も不適当なものはどれか。","o":["滴下式 ― 気化方式","電極式 ― 蒸気方式","パン型 ― 蒸気方式","遠心式 ― 水噴霧方式","超音波式 ― 気化方式"],"a":4,"e":"超音波式は超音波で水を細かい霧にして飛ばすので、水噴霧方式にあたる(2024年度問70でも正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2021-71","s":2,"q":"空気調和機を構成する機器について述べた次の文のうち、最も不適当なものはどれか。","o":["システム型エアハンドリングユニットは、全熱交換器、制御機器、還気送風機などの必要な機器を一体にした空調機である。","エアハンドリングユニットは、冷却・加熱のための熱源を内蔵した空調機である。","ファンコイルユニットは、送風機、熱交換器、エアフィルタとケーシングでできている。","パッケージ型空調機は、蒸発器、圧縮機、凝縮器、膨張弁などでできている。","ヒートポンプ型のパッケージ型空調機は、熱をくみ取る源によって水熱源と空気熱源に分けられる。"],"a":1,"e":"エアハンドリングユニットは熱源を内蔵せず、熱源設備から送られる冷水・温水・蒸気などを使って空気をつくる(2023年度問70でも正しい記述)。","l":"法令外","c":""},{"id":"2021-72","s":2,"q":"防火ダンパについての次の文の[ア]〜[ウ]に入る値の組合せとして、最も適当なものはどれか。\n「温度ヒューズ型の溶ける温度は、一般換気用が[ア]、厨房排気用が[イ]、排煙用が[ウ]である。」","o":["ア 60℃/イ 120℃/ウ 280℃","ア 60℃/イ 130℃/ウ 270℃","ア 72℃/イ 120℃/ウ 270℃","ア 72℃/イ 120℃/ウ 280℃","ア 72℃/イ 130℃/ウ 270℃"],"a":3,"e":"温度ヒューズの溶ける温度は、一般換気用72℃、厨房排気用120℃、排煙用280℃(公式正答による)。2024年度問71で「厨房用280℃」が誤りとされたのもこのため。","l":"法令外","c":""},{"id":"2021-73","s":2,"q":"送風機について述べた次の文のうち、最も不適当なものはどれか。","o":["軸流送風機では、空気が羽根車に軸方向から入り、軸方向へ抜ける。","シロッコファンは遠心式に分類される。","ダンパの開き具合を変えると、送風系の抵抗曲線が変わる。","送風系の抵抗を大きくして風量を減らすと、空気の脈動で振動や騒音が出て、不安定な運転になることがある。","横軸に風量、縦軸に送風機静圧をとった送風機特性曲線は、原点を通る二次曲線になる。"],"a":4,"e":"原点を通る二次曲線になるのは送風系の抵抗曲線(2024年度問72参照)。送風機の特性曲線は、風量が増えると圧力が下がる右下がりの曲線である。","l":"法令外","c":""},{"id":"2021-74","s":2,"q":"ダクトと付属品について述べた次の文のうち、最も不適当なものはどれか。","o":["フレキシブル継手は、ダクトと吹出口をつなぐときに位置を合わせるために使う。","防火ダンパの羽根とケーシングは、一般に厚さ1.5mm以上の鋼板でつくる。","グリル型吹出口は誘引効果が高いので、ムラの少ない温度分布が得やすい。","低圧の亜鉛鉄板製長方形ダクトには、一般に厚さ0.5〜1.2mmのものが使われる。","グラスウールダクトには消音効果が期待できる。"],"a":2,"e":"グリル型吹出口は軸流吹出口に分類され(2023年度問74)、誘引効果は小さい。誘引効果が高く温度分布が均一になりやすいのはふく流吹出口(アネモスタット型など)。","l":"法令外","c":""},{"id":"2021-75","s":2,"q":"空気浄化装置について述べた次の文のうち、最も不適当なものはどれか。","o":["自動巻取型エアフィルタのろ材の更新には、タイマによる方法や圧力損失を検知する方法が使われる。","ろ過式粒子用エアフィルタは、さえぎり、慣性、拡散、静電気などの作用で粉じんをろ材の繊維にとらえる。","空気中の有害ガスを取り除くガス除去用エアフィルタとして、イオン交換繊維を使ったものがある。","一般にHEPAフィルタの圧力損失は、一般空調用フィルタより小さい。","粒子用エアフィルタの性能は、圧力損失、粉じん捕集率、粉じん保持容量で表す。"],"a":3,"e":"HEPAフィルタはろ材が非常に細かく目が詰んでいるため、一般空調用フィルタより圧力損失が大きい。","l":"法令外","c":""},{"id":"2021-76","s":2,"q":"空気調和設備のポンプ・配管について述べた次の文のうち、最も不適当なものはどれか。","o":["ポンプの損失水頭は、管内流速の2乗に比例する。","片吸込み渦巻きポンプは、ターボ型ポンプに分類される。","歯車ポンプは、油の輸送など粘度の高い液体の輸送によく使われる。","ポンプの急停止による水撃作用を防ぐ方法として、緩閉式逆止め弁を使う方法がある。","キャビテーションとは、流量と圧力の周期的な変動が続き、運転が安定しない現象である。"],"a":4,"e":"流量と圧力が周期的に変動して運転が不安定になる現象はサージング。キャビテーションは、圧力が下がった部分で液体が蒸発して気泡ができる現象である(2024年度問74参照)。","l":"法令外","c":""},{"id":"2021-77","s":2,"q":"換気設備について述べた次の文のうち、最も不適当なものはどれか。","o":["水分の回収が不要な場合の熱回収には、空気対空気の顕熱交換器を使う。","空気対空気の全熱交換器だけでは空調システムとして十分な温度・湿度処理ができないので、二次空調機が必要になる。","外気処理ユニットとは、冷媒直膨コイル、全熱交換器、加湿器、フィルタなどを組み込んだユニットである。","ヒートポンプデシカント調湿型外気処理装置では、暖房時に効果的な相対湿度の維持管理が期待できる。","厨房、倉庫、各種機械室などでは、換気設備を単独で設けることが多い。"],"a":3,"e":"この記述が誤り。","l":"法令外","c":""},{"id":"2021-78","s":2,"q":"光散乱式の粉じん計で室内の浮遊粉じんの相対濃度を測ったところ、3分間で90カウントだった。この粉じん計のバックグランド値は10分間で60カウント、標準粒子に対する感度は1分間1カウントあたり0.001mg/m³、室内の浮遊粉じんに対する較正係数は1.3である。室内の浮遊粉じんの量に最も近いものはどれか。","o":["0.01mg/m³","0.03mg/m³","0.04mg/m³","0.07mg/m³","0.20mg/m³"],"a":1,"e":"1分あたりに直すと、測定値90÷3＝30cpm、バックグランド60÷10＝6cpm。濃度＝(30－6)×0.001×1.3＝0.0312≒0.03mg/m³。","l":"計算","c":""},{"id":"2021-79","s":2,"q":"汚染物質と、その濃度または強さを表す単位の組合せとして、最も不適当なものはどれか。","o":["アスベスト ― CFU/m³","放射能 ― Bq","オゾン ― μg/m³","二酸化イオウ ― ppm","トルエン ― μg/m³"],"a":0,"e":"CFU(コロニー形成単位)は微生物の数の単位。アスベストの濃度は繊維の本数(本/Lなど)で表す(2023年度問79参照)。","l":"法令外","c":""},{"id":"2021-80","s":2,"q":"温熱環境の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["熱式風速計は、白金線などから気流に奪われる熱量が風速に関係することを利用している。","サーミスタ温度計は、2種類の金属の膨張率の違いを利用している。","自記毛髪湿度計は、振動の多い場所での使用を避ける。","アスマン通風乾湿計は、まわりの気流や熱放射の影響を防ぐ構造になっている。","電気抵抗式湿度計は、感湿部の電気抵抗が吸湿・脱湿で変わることを利用している。"],"a":1,"e":"サーミスタ温度計は、温度で電気抵抗が変わることを利用する電気抵抗式温度計(2024年度問77)。2種類の金属の膨張率の差を使うのはバイメタル式温度計である。","l":"法令外","c":""},{"id":"2021-81","s":2,"q":"ホルムアルデヒドの測定法について述べた次の文のうち、最も不適当なものはどれか。","o":["簡易測定法には、検知管法や定電位電解法がある。","DNPHカートリッジは、オゾンによって正の妨害を受ける。","DNPHカートリッジは、冷蔵で保存する必要がある。","パッシブ法では、試料の採取に8時間程度かかる。","パッシブサンプリング法ではポンプを使わない。"],"a":1,"e":"オゾンはカートリッジ内の試薬や捕集したホルムアルデヒドを分解するため、測定値が低く出る負の妨害を与える。","l":"法令外","c":""},{"id":"2021-82","s":2,"q":"揮発性有機化合物(VOCs)の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["VOCsの採取方法には、アクティブサンプリング法とパッシブサンプリング法がある。","固相捕集・加熱脱着-GC/MS法では、前処理装置で脱着操作を行う。","固相捕集・溶媒抽出-GC/MS法は、加熱脱着法より測定感度が低い。","TVOC(Total VOC)を測る装置は、方式によらず、どのVOCに対しても同じ感度である。","TVOCは、GC/MSでヘキサンからヘキサデカンまでの範囲で検出したVOCsの合計である。"],"a":3,"e":"TVOCの測定装置は、方式やVOCの種類によって感度が違う。そのため標準ガスによる校正が欠かせない(2025年度問77参照)。","l":"法令外","c":""},{"id":"2021-83","s":2,"q":"空気調和設備の維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["加湿装置は、使用開始時と使用期間中の1年以内ごとに1回、定期に汚れの状況を点検し、必要に応じて清掃などを行う。","空調システムを通じて起きる微生物汚染の問題として、レジオネラ症がある。","空気調和設備のダクト内部は、使用年数がたつにつれて清掃を考える必要がある。","冷却塔に供給する水は、水道法の水質基準に適合させる必要がある。","冷却水管を含む冷却塔の清掃は、1年以内ごとに1回、定期に行う。"],"a":0,"e":"加湿装置の汚れの点検は、使用開始時と使用開始後1か月以内ごとに1回(施行規則第3条の18第3号)。清掃の1年以内ごと1回、供給水の水質基準も同条のとおり。","l":"建築物衛生法施行規則 第3条の18","c":""},{"id":"2021-84","s":2,"q":"音について述べた次の文のうち、最も不適当なものはどれか。","o":["人が聞き取れる範囲は、音圧レベルでおよそ0〜130dBである。","対象音と暗騒音のレベル差が15dBより大きい場合は、暗騒音の影響を取り除く必要がある。","空気中の音速は、気温が上がるほど速くなる。","低い周波数の騒音に対する人の感度は低い。","時間で変動する騒音は、等価騒音レベルで評価する。"],"a":1,"e":"対象音が暗騒音より10dB以上大きければ、暗騒音の影響は無視できる(2024年度問83でも正しい記述)。15dBも差があれば補正はいらない。","l":"法令外","c":""},{"id":"2021-85","s":2,"q":"音の用語と説明の組合せとして、最も不適当なものはどれか。","o":["広帯域騒音 ― 広い周波数の成分を含む騒音","吸音率 ― 入ってきた音のエネルギーに対する、吸収されたエネルギーの割合","純音 ― 1つの周波数だけでできた音波","拡散音場 ― 空間に音のエネルギーが一様に分布し、音があらゆる方向に伝わっている状態","パワーレベル ― 音源の音響出力をデシベルで表したもの"],"a":1,"e":"吸音率は、入ってきた音のエネルギーのうち反射されなかった(吸収と透過を合わせた)エネルギーの割合である。吸収分だけの割合ではない。","l":"法令外","c":""},{"id":"2021-86","s":2,"q":"音についての次の文の[ア]〜[エ]に入る数値の組合せとして、最も適当なものはどれか。\n「点音源では、音源からの距離が2倍になると約[ア]dB、10倍になると約[イ]dB音圧レベルが下がる。線音源では、距離が2倍になると約[ウ]dB、10倍になると約[エ]dB下がる。」","o":["ア 3/イ 15/ウ 6/エ 30","ア 3/イ 10/ウ 6/エ 20","ア 6/イ 20/ウ 3/エ 10","ア 6/イ 20/ウ 3/エ 15","ア 6/イ 30/ウ 3/エ 15"],"a":2,"e":"点音源は距離の2乗で弱まるので20log10(距離比):2倍で約6dB、10倍で20dB。線音源は距離に比例して弱まるので10log10(距離比):2倍で約3dB(2024年度問85参照)、10倍で10dB。","l":"計算","c":""},{"id":"2021-87","s":2,"q":"遮音と振動について述べた次の文のうち、最も不適当なものはどれか。","o":["道路交通による振動は不規則に起き、変動が大きい。","隔壁をはさむ2室間の遮音性能は、受音室の吸音力が大きいほど高くなる。","カーペットや畳などを敷いても、重量床衝撃音はほとんど減らせない。","床衝撃音の遮音等級Lr値は、値が大きいほど遮音性能が高い。","コインシデンス効果によって、壁の透過損失は小さくなる。"],"a":3,"e":"Lr値は値が小さいほど遮音性能が高い(2025年度問83で正答、2024年度問84でも正しい記述)。","l":"法令外","c":""},{"id":"2021-88","s":2,"q":"昼光照明と窓について述べた次の文のうち、最も不適当なものはどれか。","o":["大気透過率が同じなら、太陽高度が高いほど直射日光による地上の水平面照度は大きくなる。","曇天の空は、白熱電球より色温度が高い。","設計用全天空照度は、快晴より薄曇りの方が高い。","直接昼光率は、直射日光による照度の影響を受ける。","面積が同じなら、側窓より天窓の方が多くの昼光を取り入れられる。"],"a":3,"e":"昼光率は天空光(空の明るさ)だけをもとに計算する指標で、直射日光は含めない。そのため直射日光の影響は受けない。","l":"法令外","c":""},{"id":"2021-89","s":2,"q":"測光量についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「光度は、単位立体角あたりに放出される[ア]である。光度の単位は、通常[イ]と表される。さらに、光度を見る方向から見た見かけの面積で割った値が[ウ]である。」","o":["ア 光束/イ cd/ウ 輝度","ア 光束/イ cd/ウ 光束発散度","ア 照度/イ lm/ウ 光束発散度","ア 照度/イ lm/ウ 輝度","ア 照度/イ cd/ウ 輝度"],"a":0,"e":"光度は単位立体角あたりの光束で、単位はcd(カンデラ)。光度を見かけの面積で割ったものが輝度(2022年度問88でも正しい定義)。","l":"法令外","c":""},{"id":"2021-90","s":2,"q":"点光源の真下3.0mの水平面照度が450lxのとき、点光源の真下1.0mの水平面照度に最も近いものはどれか。","o":["450lx","900lx","1,350lx","4,050lx","4,500lx"],"a":3,"e":"照度は距離の2乗に反比例する。距離が1/3になると照度は9倍なので、450×9＝4,050lx。","l":"計算","c":""},{"id":"2021-91","s":3,"q":"建築物と日射について、最も不適当なものはどれか。","o":["夏に建物が受ける日射の熱を減らすには、東西の壁や窓はなるべく小さくするほうが有利である。","直射日光は天気で大きく変わるので、昼光を照明に利用する場合は天空光だけを利用する。","室内側につけるブラインドの日射を遮る効果は、50%程度しか期待できない。","夏至の日に南の壁が1日に受ける日射量は、緯度の低い那覇のほうが東京より大きい。","ライトシェルフとは、直射日光を反射させて部屋の奥まで光を届ける庇のことである。"],"a":3,"e":"夏至の那覇は太陽が非常に高い位置を通るため、南向きの壁にはほとんど日が当たらず、1日の日射量は東京より小さい。","l":"法令外","c":""},{"id":"2021-92","s":3,"q":"建築士法で定義している設計図書に含まれないものはどれか。","o":["仕様書","平面図","断面図","施工図","設備図"],"a":3,"e":"建築士法の設計図書は、工事用の図面(現寸図などを除く)と仕様書である。施工図は、施工者が工事のために作る図面で、設計図書には含まれない。","l":"建築士法 第2条第6項","c":""},{"id":"2021-93","s":3,"q":"鉄筋コンクリート構造とその材料について、最も不適当なものはどれか。","o":["モルタルは、砂・セメント・水を練り混ぜたものである。","梁のあばら筋は、一般に135°以上に曲げて主筋に定着させる。","柱の帯筋は、主にせん断力に対して配筋される。","柱の小径は、構造耐力上主要な支点間の距離の1/15以上とする。","直接土に接する床では、鉄筋に対するコンクリートのかぶり厚さを3cm以上としなければならない。"],"a":4,"e":"直接土に接する壁・柱・床・梁などのかぶり厚さは、4cm以上としなければならない。","l":"建築基準法施行令 第79条","c":""},{"id":"2021-94","s":3,"q":"鉄骨構造とその材料について、最も不適当なものはどれか。","o":["降伏比の大きい鋼材は、ねばり強さ(靭性)に優れる。","建築構造用鋼材は、降伏点または耐力の上限と下限が決められている。","鋼材の強さは温度が上がると下がり、1,000℃ではほとんど0になる。","軟鋼の炭素量は、0.12〜0.30%である。","高力ボルト接合で締め付けたときの余長は、ねじ山3つ以上とする。"],"a":0,"e":"降伏比(降伏強さ÷引張強さ)が大きい鋼材は、降伏してから破断するまでの余裕が小さく、ねばり強さに劣る。","l":"法令外","c":""},{"id":"2021-95","s":3,"q":"建築物の荷重と構造力学について、最も不適当なものはどれか。","o":["地震力を計算する場合、住宅の居室の積載荷重は、事務室より小さく決められている。","曲げモーメントは、部材のある点で部材を曲げようとする応力である。","片持ち梁の先端に集中荷重がかかる場合、梁のせん断力は固定端で最も大きい。","ラーメン構造の部材に生じる応力には、曲げモーメント・せん断力・軸方向力がある。","建物にかかる土圧は、常時荷重に分類される。"],"a":2,"e":"先端に集中荷重がかかる片持ち梁では、せん断力は梁の全長で一定である。固定端で最も大きくなるのは曲げモーメント。","l":"法令外","c":""},{"id":"2021-97","s":3,"q":"建築材料と部材の性質について、最も不適当なものはどれか。","o":["スランプ試験のスランプ値が大きいほど、コンクリートの流動性が高いと評価できる。","CLTは、ひき板を繊維の方向が直交するように重ねた板材である。","AE剤は、モルタルやコンクリートの中に細かい空気の泡を均一に分布させるために使う。","鋼材の引張試験で、破断したときのひずみ度を伸びという。","木材の強さは、幹の半径方向(放射軸)、年輪の接線方向、繊維方向(幹)の順に大きくなる。"],"a":4,"e":"木材は繊維方向が最も強く、繊維に直角な方向では、年輪の接線方向が半径方向より弱い。順番は接線方向<半径方向<繊維方向。","l":"法令外","c":""},{"id":"2021-98","s":3,"q":"建築生産について、最も不適当なものはどれか。","o":["工事監理は、一般に設計者が建築主の依頼を受けて代わりに行う。","一般競争入札は、工事の内容や入札の条件などを公示して行う。","金属工事は、躯体工事に分類される。","建設業法では、発注者の書面による承諾がない限り、一括下請負は禁止されている。","設備工事は、建築工事とは別に契約されることが多い。"],"a":2,"e":"金属工事は、仕上げ工事に分類される。躯体工事は、鉄筋・型枠・コンクリート・鉄骨工事など建物の骨組をつくる工事である。","l":"法令外","c":""},{"id":"2021-99","s":3,"q":"電気と電気設備について、最も不適当なものはどれか。","o":["同じ定格の電力・同じ電流値なら、交流のピーク電圧は直流より高い。","設備に電力を送るケーブルの許容電流は、配線用遮断器の定格電流より小さくする。","モーターの起動時に大きな電流が流れて異常が起こらないよう、スターデルタ起動方式が使われる。","電力は、電圧と電流の積に比例する。","地域マイクログリッドとは、自然エネルギーの発電を組み合わせて、地域の電力需要をまかなうシステムである。"],"a":1,"e":"ケーブルの許容電流は、配線用遮断器の定格電流より大きくする。小さいと、遮断器が働く前にケーブルが過熱するおそれがある。","l":"法令外","c":""},{"id":"2021-100","s":3,"q":"駐車場法で定める駐車場・駐車施設に当たらないものはどれか。","o":["路上駐車場","附置義務駐車施設","専用駐車場","都市計画駐車場","届出駐車場"],"a":2,"e":"駐車場法には、路上駐車場・路外駐車場(都市計画駐車場・届出駐車場など)・附置義務駐車施設の定めがあるが、「専用駐車場」という区分はない。","l":"駐車場法 第2条、第20条","c":""},{"id":"2021-101","s":3,"q":"都市ガスとLPガスについて、最も不適当なものはどれか。","o":["都市ガスの低位発熱量とは、水蒸気の潜熱を含む場合の発熱量のことである。","LPガスは常温・常圧では気体だが、圧力をかけたり冷やしたりして液体にして貯蔵・運搬される。","都市ガスの大半は、天然ガスを主な原料にしている。","都市ガスもLPガスも、ほとんどにおいがないため、付臭剤が加えられている。","ガスの比重は、13Aの都市ガスは空気より軽く、LPガスは空気より重い。"],"a":0,"e":"水蒸気の潜熱を含む発熱量は高位発熱量である。低位発熱量は、潜熱を含まない発熱量をいう。","l":"法令外","c":""},{"id":"2021-102","s":3,"q":"火災のときの排煙対策について、最も不適当なものはどれか。","o":["自然排煙方式では、排煙窓のほかに、その部屋の下のほうに給気の通り道を確保することが望ましい。","排煙設備の給気機の外気取入口は、新鮮な空気を取り入れるため屋上に設けるのが望ましい。","機械排煙方式では、火災の部屋が負圧になり廊下への煙もれを防げるが、避難扉が開け閉めしにくくなるおそれがある。","加圧防煙は、階段室に煙が入るのを防ぐため、階段室の付室や廊下によく使われる。","第2種排煙の煙を出す量は、排煙窓の位置での内外の圧力差と排煙窓の有効面積で決まる。"],"a":1,"e":"屋上は排煙口から出た煙が流れてきやすく、煙を吸い込むおそれがあるため、給気用の外気取入口の位置として望ましくない。","l":"法令外","c":""},{"id":"2021-103","s":3,"q":"建築基準法とその施行令の用語について、誤っているものはどれか。","o":["延べ床面積とは、地階や屋階(屋根裏部屋)を含む各階の床面積の合計である。","直通階段とは、避難階以外の階の居室から、避難階または地上に直接通じる階段のことをいう。","延焼のおそれのある部分とは、燃えやすい材料が使われている建物の外壁の部分である。","耐火性能とは、通常の火災が終わるまでの間、建物の倒壊・延焼を防ぐために必要な性能のことである。","居室とは、住む・働くなどの目的で続けて使う部屋のことで、廊下や階段は当たらない。"],"a":2,"e":"延焼のおそれのある部分は、隣地境界線や道路中心線などから一定の距離内にある部分のことで、材料の燃えやすさとは関係ない。","l":"建築基準法 第2条第6号","c":""},{"id":"2021-104","s":3,"q":"建築基準法の用語について、誤っているものはどれか。","o":["建築とは、建築物を新築・増築・改築・移転することである。","移転とは、既存の建物を別の敷地へ移動することである。","増築とは、既存の建物の床面積を増やすことである。","改築とは、既存の建物の全部または一部を取り除いて、構造・規模・用途が大きく変わらない建物をつくることである。","新築とは、建物がない土地の部分に建物をつくることである。"],"a":1,"e":"建築基準法の移転は、同じ敷地の中で建物の位置を変えることである。","l":"建築基準法 第2条第13号","c":""},{"id":"2021-105","s":3,"q":"空調技術について、最も不適当なものはどれか。","o":["事務所建築のパーソナル空調では、冷房用に天井・床・デスクなどからの吹出しが使われている。","ナイトパージとは、夜間の外気を取り入れて、空調機の冷房負荷を減らすものである。","自然換気を組み合わせたハイブリッド空調とは、穏やかな気候のときの外気を積極的に室内に入れて冷房に利用するものである。","タスク・アンビエント空調とは、タスク域(人が作業する場所)の温熱条件をゆるめることで省エネルギーを図るものである。","細霧空調とは、細かい霧が蒸発するときの潜熱で周りの空気の温度が下がる現象を利用した空調である。"],"a":3,"e":"タスク・アンビエント空調は、作業する場所(タスク域)はしっかり空調し、周りの空間(アンビエント域)の条件をゆるめて省エネルギーを図るものである。","l":"法令外","c":""},{"id":"2021-106","s":4,"q":"給水・排水の管理で使う用語と、その単位の組合せとして、最も不適当なものはどれか。","o":["水の比熱 ― kJ/(kg・℃)","腐食速度 ― mm/年","塩化物イオン ― mg/L","揚水ポンプの揚程 ― m","水槽照度率 ― lm/m²"],"a":4,"e":"水槽照度率は、水槽の外の照度に対する水槽の中の照度の割合である(2024年問108で正しい組合せとして出題)。割合なので、lm/m²(照度の単位)ではない。","l":"法令外","c":""},{"id":"2021-107","s":4,"q":"給水・排水の管理に関する用語の組合せとして、最も不適当なものはどれか。","o":["スライム障害 ― バイオフィルムができること","異臭味 ― 藻類や放線菌がつくる物質","スカム ― 排水槽の中に浮かんでいる物質","スケール障害 ― トリハロメタンができること","赤水 ― 鉄さびが溶け出すこと"],"a":3,"e":"スケールは炭酸カルシウムや炭酸マグネシウムなどの析出物である(2017年問107・2023年問107で正しい組合せとして出題)。トリハロメタンの生成とは関係がない。","l":"法令外","c":""},{"id":"2021-108","s":4,"q":"水道法に関する記述として、最も不適当なものはどれか。","o":["水道とは、導管などの工作物によって、人が飲むのに適した水を供給する施設全体をいう。","水道事業とは、一般の需要に応じて水道で水を供給する事業で、計画上の給水人口が101人以上のものをいう。","上水道事業とは、計画給水人口が4,001人以上の水道事業をいう。","専用水道には、寄宿舎などの自家用水道で、100人を超える人に居住に必要な水を供給するものが含まれる。","簡易専用水道とは、水道事業の水道から受ける水だけを水源とし、水槽の有効容量の合計が10m³を超えるものをいう。"],"a":2,"e":"簡易水道事業は給水人口5,000人以下の水道事業なので(水道法第3条第3項)、上水道事業は一般に計画給水人口5,001人以上のものをいう(2025年問110で正しい記述として出題)。","l":"水道法 第3条","c":""},{"id":"2021-109","s":4,"q":"水道施設などに関する記述として、最も不適当なものはどれか。","o":["市や特別区にある専用水道と簡易専用水道は、その市長や特別区長が指導監督する。","地表水は、伏流水と比べて、水量や水質の変化が大きい。","深層地下水は地表からの汚染を受けにくく水質は安定しているが、管の腐食を起こすことがある。","導水施設とは、浄水施設できれいにした水を配水施設まで送る施設のことである。","水道法の給水装置とは、需要者に水を届けるため、水道事業者が設けた配水管から分かれた給水管と、これに直結する給水用具をいう。"],"a":3,"e":"浄水施設から配水施設まで浄水を送るのは送水施設である(2023年問108で正しい記述として出題)。導水施設の説明ではない。なお(1)は水道法第48条の2、(5)は同法第3条第9項のとおり。","l":"水道法 第3条第9項・第48条の2(選択肢1・5)","c":""},{"id":"2021-110","s":4,"q":"水道水の塩素消毒に関する記述として、最も不適当なものはどれか。","o":["塩素消毒の効果は、にごりの成分(懸濁物質)があると下がる。","塩素消毒の反応の速さは、温度が高いほど速くなる。","水道水の中の窒素化合物と反応すると、塩素消毒の効果が高まる。","塩素消毒の効果は、アルカリ側で急に下がる。","塩素消毒は、多くの種類の微生物に効く。"],"a":2,"e":"窒素化合物と反応すると、消毒効果は下がる(2024年問109で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-111","s":4,"q":"給水設備の汚染に関する記述として、最も不適当なものはどれか。","o":["逆サイホン作用とは、給水管内にできた負圧で、水受け容器にいったん出た水が給水管内に逆流することである。","クロスコネクションとは、飲料水の系統とほかの配管系統を、配管などで直接つなぐことである。","洗面器の吐水口空間とは、給水栓の吐水口と洗面器のあふれ縁との垂直距離である。","大便器の洗浄弁の下流側には、一般に圧力式バキュームブレーカを設ける。","逆サイホン作用を防ぐ対策の基本は、吐水口空間を設けることである。"],"a":3,"e":"大便器洗浄弁には、大気圧式バキュームブレーカを設ける(2017年問114・2024年問111で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-112","s":4,"q":"給水設備に関する記述として、最も不適当なものはどれか。","o":["小学校の1日あたりの設計給水量は、70〜100L/人である。","受水槽の有効容量は、一般に1日使用水量の1/2程度である。","一般の水栓に最低限必要な水圧は、30kPaである。","給水配管の管径は、管内の流速が2.0m/s以下になるように選ぶ。","高層ホテルの上限給水圧力は、0.7MPaである。"],"a":4,"e":"高層ホテルのゾーニングにおける給水の上限水圧は0.3MPaである(2023年問112で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-113","s":4,"q":"給水設備で起こる現象と、その原因の組合せとして、最も不適当なものはどれか。","o":["ウォータハンマ ― シングルレバー水栓で急に閉めること","貯水槽の水面の波立ち ― 迂回壁を設けること","クリープ劣化 ― 長い時間続けてかかる応力","青水 ― 銅イオンが溶け出すこと","孔食 ― ステンレス鋼管の中に付いた異物"],"a":1,"e":"迂回壁は、大容量の貯水槽で水のよどみ(滞留水)を防ぐために設けるものである(2022年問111・2024年問111で正しい記述として出題)。水面の波立ちの原因ではない。","l":"法令外","c":""},{"id":"2021-114","s":4,"q":"給水設備の配管に関する記述として、最も不適当なものはどれか。","o":["給水管と排水管を並べて埋める場合は、給水管を排水管より上に埋める。","止水弁は、主管からの分岐、各系統の起点、機器との接続部などに設ける。","ポンプに弁や配管を付けるときは、その重さが直接ポンプにかからないように支える。","建物の揺れや配管の振動などによるずれを吸収するため、貯水槽と配管の接続には伸縮継手を使う。","機器との接続配管は、機器を交換するときに外しやすいよう、フランジ接合などにする。"],"a":3,"e":"建物の揺れ・地盤の不同沈下・配管の振動などによるずれの吸収には、可とう継手を使う(2024年問116で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-115","s":4,"q":"給水設備の配管に関する語句の組合せとして、最も不適当なものはどれか。","o":["合成樹脂ライニング鋼管(ねじ接合) ― 管端防食継手","ステンレス鋼管(溶接接合) ― TIG溶接","架橋ポリエチレン管 ― 接着接合","ポリブテン管 ― メカニカル形接合","銅管 ― 差込みろう接合"],"a":2,"e":"架橋ポリエチレン管は、接着接合ではなくメカニカル形接合などでつなぐ(2023年問113で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2021-116","s":4,"q":"給水設備の維持管理に関する記述として、最も不適当なものはどれか。","o":["防錆剤を使っている場合は、3か月以内ごとに1回、防錆剤の濃度を検査する。","受水槽と高置水槽の清掃は原則として同じ日に行い、受水槽の清掃後に高置水槽を清掃する。","飲料用貯水槽の清掃業務をする人は、6か月に1回程度、健康診断を受ける。","飲料用貯水槽の点検は定期に行い、必要に応じて補修などをする。","受水槽の水位制御の作動点検は、槽内のボールタップを手で動かして行う。"],"a":0,"e":"防錆剤の濃度の検査は、ふだんは2か月以内ごとに1回行う(2022年問117で正しい記述として出題)。なお受水槽→高置水槽の順に清掃することは告示第119号 第2のとおり。","l":"平成15年厚生労働省告示第119号 第2(選択肢2)","c":""},{"id":"2021-117","s":4,"q":"建築物衛生法にもとづく貯水槽の清掃に関する記述として、誤っているものはどれか。","o":["清掃後の消毒には、有効塩素濃度50〜100mg/Lの次亜塩素酸ナトリウム溶液などの塩素剤を使う。","清掃が終わったら、2回以上貯水槽の中を消毒する。","消毒後の水洗いと水張りは、少なくとも30分以上たってから行う。","清掃後の水質検査で、遊離残留塩素濃度の基準値は0.1mg/L以上である。","清掃後の水質検査で、濁度の基準値は2度以下である。"],"a":3,"e":"清掃後の水張り時の検査で、遊離残留塩素の基準は0.2mg/L(百万分の0.2)以上である(告示第119号 第2の一の1(四))。濁度2度以下、2回以上の消毒も同じ告示のとおり。","l":"平成15年厚生労働省告示第119号 第2の一の1","c":""},{"id":"2021-118","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["壁掛けシャワーの使用温度は、42℃程度である。","自然冷媒ヒートポンプ給湯機で湯を沸かせる最高温度は、60℃である。","総合病院で使う湯の量は、100〜200L/(床・日)程度である。","架橋ポリエチレン管の使用温度は、95℃以下とする。","ガス瞬間湯沸器の能力表示の1号は、約1.74kWの加熱能力である。"],"a":1,"e":"自然冷媒ヒートポンプ給湯機の最高沸き上げ温度を60℃とした記述が誤り。","l":"法令外","c":""},{"id":"2021-119","s":4,"q":"給湯設備で扱う水の性質に関する記述として、最も不適当なものはどれか。","o":["4℃以上の水は、温度が上がると密度が小さくなる。","配管内の水に溶ける気体の量(溶解度)は、水温が上がると増える。","給湯設備で扱う範囲の水は、ほとんど圧縮されない(非圧縮性)。","水に溶けている空気は、配管内の圧力が高いと分離しにくい。","水温が高いほど、金属が腐食する速度は速くなる。"],"a":1,"e":"水中の気体の溶解度は、水温が上がると減少する(2016年問117・2024年問118で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-120","s":4,"q":"給湯設備に使う材料に関する記述として、最も不適当なものはどれか。","o":["金属材料を曲げ加工すると、応力腐食が起こることがある。","耐熱性硬質ポリ塩化ビニル管の最高使用許容圧力は、使う温度が高くなると下がる。","樹脂管を温度の高い湯に使うと、塩素による劣化が起こりやすい。","ステンレス鋼管は、酸化被膜で母材が不動態化することで腐食に強くなる。","ポリブテン管の線膨張係数は、銅管より小さい。"],"a":4,"e":"ポリブテン管の線膨張係数は、銅管より小さくはない(樹脂管のほうが大きい)。","l":"法令外","c":""},{"id":"2021-121","s":4,"q":"循環配管の長さが100mの給湯設備で、循環流量を10L/minとした。循環配管からの1mあたりの熱損失として、最も近いものはどれか。\nただし、加熱装置での給湯温度と返湯温度の差は5℃とし、次の式を使う。\nQ = 0.0143 × H_L ÷ Δt\n(Q:循環流量[L/min]、H_L:循環配管からの熱損失[W]、Δt:給湯温度と返湯温度の差[℃])","o":["0.5W/m","7.0W/m","35W/m","140W/m","3,500W/m"],"a":2,"e":"式を変形すると H_L = Q × Δt ÷ 0.0143 = 10 × 5 ÷ 0.0143 ≒ 3,500W。これを配管の長さ100mで割ると、約35W/mとなる。","l":"法令外","c":""},{"id":"2021-122","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["貫流ボイラは、煙道をもっている。","貯蔵式湯沸器は、減圧弁をもっている。","真空式温水発生機は、減圧蒸気室をもっている。","太陽熱利用温水器には、集熱器と貯湯槽が一体になったものがある。","潜熱回収型給湯器は、排気ガスの潜熱を回収し、給水の予熱に使う。"],"a":1,"e":"貯蔵式湯沸器は貯める部分が大気に開放されている(2022年問119で正しい組合せとして出題)ので、減圧弁をもつとした記述が誤り。","l":"法令外","c":""},{"id":"2021-123","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["給湯水からレジオネラ属菌が見つかった場合の対策として、高濃度の塩素で系統内を消毒する方法がある。","無圧式温水発生機の定期検査は、労働安全衛生法で定められている。","給湯設備には、給水設備に準じた保守管理が必要である。","給湯水を均等に循環させるため、返湯管に定流量弁を設ける。","ベローズ形の伸縮管継手は、ベローズの疲労破壊によって水漏れすることがある。"],"a":1,"e":"無圧式温水発生機の定期検査が労働安全衛生法で定められている、とした記述が誤り。","l":"法令外","c":""},{"id":"2021-124","s":4,"q":"雑用水に関する記述として、最も不適当なものはどれか。","o":["地区循環方式は、いくつかの建物で排水再利用設備を共同で使うものである。","雑用水の原水には、1年を通して安定して確保できる排水を優先して使う。","雑用水は、洗面器や手洗器などにつながない。","雑用水受水槽には、腐食に強く長持ちする材質のものを使う。","し尿を含む原水からつくった雑用水を散水や水景に使う場合は、決められた水質基準に合っていればよい。"],"a":4,"e":"散水・修景・清掃に使う雑用水は、し尿を含む水を原水として使ってはならない(建築物衛生法施行規則第4条の2第1項第3号イ)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2021-125","s":4,"q":"建築物衛生法にもとづく雑用水の水質検査で、7日以内ごとに1回、定期に行う項目にあてはまらないものはどれか。","o":["pH","臭気","外観","濁度","遊離残留塩素"],"a":3,"e":"濁度の検査は2か月以内ごとに1回である。pH値・臭気・外観と遊離残留塩素は7日以内ごとに1回行う(施行規則第4条の2)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2021-126","s":4,"q":"雨水利用設備の装置と、その点検項目の組合せとして、最も不適当なものはどれか。","o":["スクリーン ― ばっ気の状況","降雨水集水装置 ― 屋根面の汚れ","雨水貯留槽 ― 沈殿物があるか","ストレーナ ― 網が破れていないか","ろ過装置 ― ろ層の詰まり具合"],"a":0,"e":"スクリーンの点検項目を「ばっ気の状況」とした組合せが誤り。","l":"法令外","c":""},{"id":"2021-127","s":4,"q":"排水の水質に関する記述として、最も不適当なものはどれか。","o":["pH値は汚水の処理の過程で変わるので、処理の進み具合を推定するのに使われる。","BOD/COD比が高い排水には、生物処理法より物理化学処理法が向いている。","窒素化合物は、閉鎖性水域の富栄養化の原因物質の一つである。","総アルカリ度は、硝化・脱窒反応の指標として使われる。","ヘキサン抽出物質は、比較的揮発しにくい油脂類などである。"],"a":1,"e":"BOD/COD比が高い排水は生物で分解しやすい有機物が多いので、物理化学処理法より生物処理法が向いている。","l":"法令外","c":""},{"id":"2021-128","s":4,"q":"排水通気配管に関する記述として、最も不適当なものはどれか。","o":["通気管の末端を窓や換気口などの近くに設ける場合は、その上端から600mm以上立ち上げて大気に開放する。","特殊継手排水システムは、排水横枝管につながる器具が比較的少ない集合住宅やホテルの客室系統に多く採用されている。","間接排水管の管径が30mmの場合、排水口空間は最小50mmである。","結合通気管は、高層建物でブランチ間隔10以上の排水立て管に、最上階から数えてブランチ間隔10以内ごとに設ける。","ループ通気管は、最上流の器具排水管が排水横枝管につながる位置のすぐ下流から立ち上げ、通気立て管につなぐ。"],"a":2,"e":"管径30mmの間接排水管の排水口空間を最小50mmとした記述が誤り。","l":"法令外","c":""},{"id":"2021-129","s":4,"q":"排水トラップと阻集器に関する記述として、最も不適当なものはどれか。","o":["ドラムトラップは、サイホントラップに分類される。","トラップの封水強度とは、排水管内に正圧や負圧が生じたときに封水を保つ能力をいう。","砂阻集器に設ける泥だめの深さは、150mm以上とする。","開放式のオイル阻集器を屋内に置く場合は、換気を十分に行う。","繊維くず阻集器には、網の目が13mm程度のバスケットストレーナを設ける。"],"a":0,"e":"ドラムトラップは非サイホントラップに分類される(2016年問128・2023年問127で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2021-130","s":4,"q":"排水配管に関する記述として、最も不適当なものはどれか。","o":["間接排水管の長さが1,500mmを超える場合は、悪臭を防ぐため、機器・装置の近くにトラップを設ける。","管径65mmの排水横管の最小勾配は、1/50である。","雨水排水ますの流出管は、流入管より管底を10mm程度下げて設ける。","排水立て管のオフセット部の上下600mm以内には、排水横枝管を設けてはならない。","伸頂通気方式の排水横主管の水平曲がりは、排水立て管の底部から3m以内に設けてはならない。"],"a":2,"e":"雨水ますの流出管は、流入管より管底を20mm以上(20mm程度)下げて設ける(2023年問130・2025年問129で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-131","s":4,"q":"排水槽と排水ポンプに関する記述として、最も不適当なものはどれか。","o":["排水槽の底の勾配は、吸込みピットに向かって1/15以上1/10以下とする。","排水槽の中をブロワでばっ気すると正圧になるので、排気を行う。","排水槽のマンホールは、水中ポンプやフート弁の真上に設ける。","排水ポンプは、吸込みピットの壁面から100mm程度離して設置する。","厨房用の排水槽には、汚物ポンプを使う。"],"a":3,"e":"排水ポンプは、吸込みピットの壁面から200mm以上離して設置する(2016年問130・2023年問131で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-132","s":4,"q":"排水管の掃除口と排水ますに関する記述として、最も不適当なものはどれか。","o":["排水管の管径が75mmの場合、掃除口の間隔は25m程度とする。","敷地排水管の直管が長い場合、排水ますは管内径の120倍を超えない範囲に設ける。","排水管の管径が125mmの場合、掃除口の口径は100mmとする。","掃除口は、建物内の排水横主管と敷地排水管がつながる場所の近くに設ける。","排水ますの大きさは、配管を埋める深さ、つながる配管の大きさと本数、点検のしやすさなどを考えて決める。"],"a":0,"e":"管径100mm以下の排水管の掃除口の間隔は15m以内とする(2023年問128・2025年問131で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-133","s":4,"q":"排水槽と排水ポンプの保守管理に関する記述として、最も不適当なものはどれか。","o":["排水槽の悪臭対策として、1〜2時間を超えて排水をためないよう、タイマ制御で強制排水する。","排水槽の清掃は、酸素濃度を確かめた後、硫化水素濃度が10ppm以下であることを測って確かめてから行う。","排水ポンプは3か月に1回絶縁抵抗を測り、1MΩ以上あることを確かめる。","排水槽の清掃を6か月以内ごとに1回行うことは、建築物環境衛生管理基準で決められている。","排水ポンプのメカニカルシールは、1〜2年に1回程度交換する。"],"a":2,"e":"排水ポンプの絶縁抵抗の測定は1か月に1回行う(2023年問134で正しい記述として出題)。なお(4)は施行規則第4条の3のとおり。","l":"建築物衛生法施行規則 第4条の3(選択肢4)","c":""},{"id":"2021-134","s":4,"q":"排水設備とグリース阻集器の保守管理に関する記述として、最も不適当なものはどれか。","o":["通気管は、1年に1回程度、定期的に系統ごとに異常がないか点検・確認する。","グリース阻集器のグリースは、7〜10日に1回の間隔で取り除く。","ロッド法による排水管の清掃では、最大30mの長さまでつないだロッドが使われる。","スネークワイヤ法を排水立て管の清掃に使う場合、長さ20m程度が限界である。","高圧洗浄による排水管の清掃では、0.5〜3MPaの圧力の水を噴射して洗う。"],"a":4,"e":"高圧洗浄による排水管の清掃では、5〜30MPaの圧力の水を噴射する(2023年問134・2024年問135で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-135","s":4,"q":"大便器に関する記述として、最も不適当なものはどれか。","o":["大便器の給水方式には、タンク式・洗浄弁式・専用洗浄弁式がある。","大便器の洗浄水量は、JIS A 5207で、Ⅰ形が8.5L以下と区分されている。","大便器洗浄弁がつながる給水管の管径は、13mmとする。","大便器の取り付け状態は、6か月に1回、定期に点検する。","大便器の節水型洗浄弁は、ハンドルを押し続けても、標準の量しか水が出ない機能をもつ。"],"a":2,"e":"大便器洗浄弁がつながる給水管の管径を13mmとした記述が誤り。","l":"法令外","c":""},{"id":"2021-136","s":4,"q":"衛生器具などの清掃に関する記述として、最も不適当なものはどれか。","o":["陶器製の衛生器具に熱湯を直接かけると、割れることがある。","プラスチック製の衛生器具は、水やぬるま湯にひたして固くしぼったやわらかい布でふく。","ステンレス製の衛生器具の油汚れは、中性洗剤を付けたスポンジなどで洗い、洗剤分を完全に洗い流す。","ほうろう鉄器製の衛生器具に付いた水あかや鉄さびなどの汚れは、金属たわしでこすり取る。","洗面所の鏡に付いた水分を放っておくと白い汚れが付きやすいので、乾いた布でこまめにふき取る。"],"a":3,"e":"ほうろう鉄器製の衛生器具を金属たわしでこする、とした記述が誤り。","l":"法令外","c":""},{"id":"2021-137","s":4,"q":"浄化槽の高度処理で、取り除く物質と、その除去法の組合せとして、最も不適当なものはどれか。","o":["浮遊性の有機物 ― 急速ろ過法","リン化合物 ― 活性炭吸着法","溶解性の有機物 ― 接触ばっ気法","窒素化合物 ― 生物学的硝化脱窒法","アンモニア ― イオン交換法"],"a":1,"e":"リン化合物の除去法を活性炭吸着法とした組合せが誤り。","l":"法令外","c":""},{"id":"2021-138","s":4,"q":"浄化槽法で定める浄化槽管理者に関する記述として、誤っているものはどれか。","o":["最初の保守点検は、浄化槽を使い始めた直後に行う。","指定検査機関が行う法定検査を受ける。","保守点検と清掃を行い、その記録を保存する。","保守点検と清掃は、法令で定められた技術上の基準に従って行う。","保守点検は、登録を受けた浄化槽保守点検業者に委託することができる。"],"a":0,"e":"最初の保守点検は、浄化槽の使用開始の直前に行う(環境省関係浄化槽法施行規則第5条第1項)。","l":"環境省関係浄化槽法施行規則 第5条第1項","c":""},{"id":"2021-139","s":4,"q":"浄化槽のばっ気槽の点検項目として、最も不適当なものはどれか。","o":["ばっ気槽混合液浮遊物質濃度(MLSS)","溶存酸素濃度","空気供給量","30分間汚泥沈殿率","透視度"],"a":4,"e":"ばっ気槽の点検項目として透視度をあげた点が誤り。MLSSはばっ気槽混合液の浮遊物質で、活性汚泥の量の指標である(2020年問127で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-140","s":4,"q":"特殊設備に関する記述として、最も不適当なものはどれか。","o":["プールの循環ろ過の取水口には、吸い込み事故を防ぐための安全対策をする。","厨房機器の材質は、水を吸わず、耐水性と耐食性があるものにする。","水景施設へ上水系統から補給する水は、必ず吐水口空間を設けて間接的に給水する。","水景施設の維持管理では、貯水部や流水部の底や側壁にたまった・付いた汚泥などの除去も必要である。","オーバーフロー方式の浴槽循環ろ過設備では、循環水を浴槽の水面より高い位置から浴槽に入れる。"],"a":4,"e":"浴槽の循環水は、浴槽の底部に近い部分から供給する(2024年問138で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-141","s":5,"q":"建築物清掃で一般に行う日常清掃として、最も不適当なものはどれか。","o":["ドアノブなど金属類の除じん","エスカレーターのランディングプレートの除じん","駐車場の除じん","玄関ホールのフロアマットの除じん","事務室の窓台の除じん"],"a":4,"e":"窓台の除じんは定期清掃で行う作業である(2025年度問143で正答)。","l":"法令外","c":""},{"id":"2021-142","s":5,"q":"建築物清掃管理仕様書についての次の文の[  ]に入る語句として、最も適当なものはどれか。\n「建築物清掃管理仕様書は、基本管理方針、作業範囲、作業環境、作業時間帯などを書いた総括的なものと、作業内容を図表などで詳しく表した[  ]からなる。」","o":["清掃作業基準表","清掃品質管理表","清掃作業計画表","清掃作業予定表","清掃点検評価表"],"a":0,"e":"清掃管理仕様書は、総括的な仕様書と、作業内容を詳しく図表で示した清掃作業基準表でできている(2024年度問145でも仕様書と作業基準表が並べて扱われている)。","l":"法令外","c":""},{"id":"2021-143","s":5,"q":"建築物清掃業の登録基準についての次の文の[  ]に入る語句として、正しいものはどれか。\n「作業計画と作業手順書の内容、それにもとづく清掃作業の実施状況について、[  ]以内ごとに1回、定期に点検し、必要に応じて適切な措置を講ずること。」","o":["3か月","4か月","6か月","1年","2年"],"a":0,"e":"清掃作業の登録基準を定めた告示(平成14年厚生労働省告示第117号 第8号)で、作業計画・作業手順書と実施状況の点検は3か月以内ごとに1回とされている。","l":"平成14年厚生労働省告示第117号 第8号(建築物衛生法施行規則 第25条第5号にもとづく基準)","c":""},{"id":"2021-144","s":5,"q":"建築物清掃の品質評価について述べた次の文のうち、最も不適当なものはどれか。","o":["きれいさの評価は、おもに光沢度計などの測定機器で行う。","改善内容や具体的な対策を示して、清掃責任者に指示する。","点検は、インスペクション実施計画に沿って行う。","同じ仕様でもできばえに大きな差が出るので、品質評価が重要である。","評価は、利用者の立場に立って行う。"],"a":0,"e":"きれいさの評価は、おもに目視などによる官能検査で行い、測定機器は補助的に使う。","l":"法令外","c":""},{"id":"2021-145","s":5,"q":"ほこりや汚れの除去について述べた次の文のうち、最も適当なものはどれか。","o":["アクリル板のほこりは、ただ載っているだけの状態である。","湿ったタオルでしみの部分を軽くこすり、タオルに汚れが付けば水溶性のしみである。","ほこりは、長い間放置しても取りやすさは変わらない。","ダストコントロール法では、水溶性の汚れも取れる。","ダストクロス法は、油分による床への悪影響が多い。"],"a":1,"e":"湿ったタオルに汚れが移れば、水に溶けるしみと判断できる。ほこりは放置すると取りにくくなり(2025年度問147)、ダストクロス法は油分の害が少ない(2023年度問147)。","l":"法令外","c":""},{"id":"2021-146","s":5,"q":"カーペット清掃用の機械について述べた次の文のうち、最も不適当なものはどれか。","o":["ドライフォーム方式の洗浄機は、洗剤液を泡にして縦回転ブラシで洗う。","カーペットスイーパは、パイルの内部のほこりを取る。","スチーム洗浄機は、カーペットのしみ取りに使われる。","真空掃除機は、電動ファンで機械の中に空気の低圧部をつくり、ほこりを吸い込む構造である。","エクストラクタは、カーペットのシャンプークリーニング後のすすぎ洗いに使われる。"],"a":1,"e":"カーペットスイーパは、パイルの表面にある粗いごみを取る道具である(2023年度問148・2024年度問151でも正しい記述)。","l":"法令外","c":""},{"id":"2021-147","s":5,"q":"床維持剤について述べた次の文のうち、最も適当なものはどれか。","o":["剥離剤は、酸の作用で樹脂床維持剤の皮膜を溶かす。","フロアポリッシュは、物理的・化学的な方法でも簡単には除去できない。","剥離剤を使った後は、すすぎ拭きを十分にしてから樹脂床維持剤を塗り直す。","フロアオイルは、おもに表面加工した木質系床材の保護に使う。","床維持剤には、乳化性フロアポリッシュが多く使われている。"],"a":2,"e":"剥離剤が残ると新しい床維持剤がよく付かないので、十分にすすぎ拭きしてから塗り直す。剥離剤はアルカリ性(2023年度問151)で、簡単に除去できないのはフロアシーラ(2024年度問149)。","l":"法令外","c":""},{"id":"2021-148","s":5,"q":"弾性床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["床維持剤が黒ずんできたら、剥離作業をして塗り直す。","塩化ビニルシートは、床維持剤の密着性がよい。","日常清掃では、ダストモップで土砂やほこりを取る。","塩化ビニルタイルは、可塑剤を含む。","ゴム系床材は、剥離剤で変色やひび割れなどが起きることがある。"],"a":1,"e":"塩化ビニルシートは含まれる可塑剤の影響で、床維持剤が密着しにくい(2024年度問150・2022年度問150でも正しい記述)。","l":"法令外","c":""},{"id":"2021-149","s":5,"q":"床材の耐性について述べた次の文のうち、最も適当なものはどれか。","o":["木質系床材は、水に強い。","テラゾは、酸に強い。","リノリウムは、アルカリに強い。","セラミックタイルは、すり減りにくい。","コンクリートは、酸に強い。"],"a":3,"e":"セラミックタイルは耐摩耗性にすぐれる(2024年度問152で「すり減りやすい」が誤りとされている)。木質は水に弱く、テラゾ・コンクリートは酸に、リノリウムはアルカリに弱い。","l":"法令外","c":""},{"id":"2021-150","s":5,"q":"床維持剤のドライメンテナンス法について述べた次の文のうち、最も適当なものはどれか。","o":["ウェットメンテナンス法より部分補修がしにくい。","ドライバフ法で使う床磨き機は、回転数が高いとフロアポリッシュの皮膜を傷めるので低速で使う。","ドライバフ法は、つや出し作用のあるスプレー液をかけながらパッドで磨き、光沢を戻す。","スプレークリーニング法では、毎分1,000回転以上の超高速床磨き機を使う。","ウェットメンテナンス法より作業の安全性が高い。"],"a":4,"e":"ドライメンテナンス法は水をあまり使わず前に進む作業が中心なので安全性が高い(2025年度問153でも正しい記述)。部分補修はしやすく、ドライバフ法は高速で磨き、スプレー液をかけるのはスプレーバフ法である。","l":"法令外","c":""},{"id":"2021-151","s":5,"q":"繊維床材の特徴と清掃について述べた次の文のうち、最も不適当なものはどれか。","o":["事務所建築物の繊維床材のしみの多くは親水性である。","アクリル素材は、耐久性にすぐれている。","スポットクリーニングは、汚れがパイルの上部にあるうちに行う。","ナイロン素材は、耐久性にすぐれている。","しみ取り作業は、日常清掃で行う。"],"a":1,"e":"この記述が誤り。アクリル素材は耐久性が高いとはいえない(耐久性にすぐれるのはナイロンなど)。","l":"法令外","c":""},{"id":"2021-152","s":5,"q":"床以外の清掃作業について述べた次の文のうち、最も不適当なものはどれか。","o":["トイレは、清掃作業で全面使用禁止にならないよう工程を工夫する必要がある。","湯沸室で使う資機材は湯沸室専用とし、ほかの場所と区別する配慮が必要である。","玄関ホールの清掃品質は、視線の向きや高さを変えて確かめる。","階段の壁は、廊下の壁よりほこりが付きにくい。","玄関ホールは季節や天候の影響を受けるので、清掃品質が変わりやすい。"],"a":3,"e":"階段では人の動きで空気が上下に動くため、壁はほかの場所よりほこりが付きやすい(2025年度問154でも正しい記述)。","l":"法令外","c":""},{"id":"2021-153","s":5,"q":"外装のガラスクリーニングについて述べた次の文のうち、最も不適当なものはどれか。","o":["自動窓拭き設備は、洗剤や水をガラスに吹き付けてブラシで洗い、真空吸引装置で回収する。","ロープ高所作業を行う場合は、ライフラインの設置が義務付けられている。","美観を保つため、1〜2か月に1回の頻度で洗うのが望ましい。","スクイジー法は、細かい研磨剤をガラスに塗ってスクイジーでかき取る方法である。","作業前に傷の有無、大きさ、数などを調べ、業務の発注者に報告する。"],"a":3,"e":"スクイジー法は、水や専用洗剤を塗ってスクイジーでかき取る方法で、研磨剤は使わない(2024年度問155でも正しい記述)。ライフラインの義務は労働安全衛生規則第539条の2。","l":"労働安全衛生規則 第539条の2","c":""},{"id":"2021-154","s":5,"q":"建築物の清掃・消毒について述べた次の文のうち、最も不適当なものはどれか。","o":["感染症が出たときの消毒に備え、衛生管理の担当者は、消毒剤の種類や使い方、対象物などの理解を深めておく必要がある。","清掃でほこり、汚れ、廃棄物、汚物などを取り除くことは、消毒の前処理として重要である。","清掃の衛生管理の基本はゾーニング管理である。","ふだんから作業者に衛生管理の訓練を行う。","逆性石けんは、ノロウイルスに対して消毒効果が高い。"],"a":4,"e":"逆性石けん(第四級アンモニウム塩)はノロウイルスにはほとんど効かない(2025年度問156で正答)。","l":"法令外","c":""},{"id":"2021-155","s":5,"q":"廃棄物の中間処理施設と、そのおもな効果の組合せとして、最も不適当なものはどれか。","o":["焼却施設 ― 減量化","焼却残渣溶融施設 ― 安定化","ごみ燃料化施設 ― 安定化","粗大ごみ処理施設 ― 減容化","高速堆肥化施設 ― 資源化"],"a":2,"e":"ごみ燃料化施設は、ごみを燃料にして再利用するための施設なので、おもな効果は資源化である。","l":"法令外","c":""},{"id":"2021-156","s":5,"q":"ごみの処理の過程について述べた次の文のうち、最も不適当なものはどれか。","o":["分別は、出るところであらかじめ区分することで、リサイクルを進めるうえで重要である。","保管は、次の処理に移るまで一時的に保管することで、衛生害虫の発生防止などに注意する。","収集・運搬では、飛び散りや悪臭の防止などに注意する。","再生(リサイクル)は、おもにごみを製品の原料など役に立つものとして資源化することである。","最終処分には、焼却してごみを減らすことが含まれる。"],"a":4,"e":"焼却してごみを減らすのは中間処理である(2021年度問155・2022年度問155参照)。最終処分は埋立てなどを指す。","l":"法令外","c":""},{"id":"2021-157","s":5,"q":"廃棄物処理法についての次の文の[ア]・[イ]に入る語句の組合せとして、最も適当なものはどれか。\n「1970年に制定された廃棄物処理法では、[ア]から定めていた汚物に加えて新たに不要物の考え方を取り入れて廃棄物を定義し、産業廃棄物と一般廃棄物に分けるとともに、[イ]が新たに法の目的に加えられた。」","o":["ア 環境面/イ 生活環境の保全","ア 衛生面/イ 適正処理","ア 衛生面/イ 排出の抑制","ア 衛生面/イ 生活環境の保全","ア 環境面/イ 排出の抑制"],"a":3,"e":"それまでの法律は衛生面から汚物を定めていた。廃棄物処理法は目的に「生活環境の保全」を加えた(現行の第1条にも「生活環境の保全及び公衆衛生の向上」とある。2024年度問165参照)。","l":"廃棄物処理法 第1条","c":""},{"id":"2021-158","s":5,"q":"廃棄物処理法について述べた次の文のうち、最も不適当なものはどれか。","o":["排出事業者が産業廃棄物の処理を委託するとき、その移動や処理の状況を自ら把握するために、特別管理産業廃棄物の制度が設けられている。","都道府県知事は、産業廃棄物処理業の許可申請があると、施設と申請者の能力が基準に合っているかを審査して許可する。","市町村は、自らつくった一般廃棄物処理計画に従って処理を行う。","一般廃棄物の処理業者は、専ら再生利用の目的となる一般廃棄物を扱う者を除き、市町村長の許可を受けなければならない。","市町村が一般廃棄物の収集・運搬・処分などを業者に委託するときは、委託基準に従わなければならない。"],"a":0,"e":"委託した産業廃棄物の移動や処理の状況を把握するための制度は、産業廃棄物管理票(マニフェスト)制度である(第12条の3)。特別管理産業廃棄物は有害な性状をもつ廃棄物の区分である。","l":"廃棄物処理法 第12条の3","c":""},{"id":"2021-159","s":5,"q":"廃棄物処理法の一般廃棄物の処理に関する次の条文の[ア]〜[ウ]に入る語句の組合せとして、正しいものはどれか。\n「[ア]は、その区域内において事業活動に伴い多量の一般廃棄物を生ずる土地又は建物の[イ]に対し、当該一般廃棄物の[ウ]に関する計画の作成、当該一般廃棄物を運搬すべき場所及びその運搬の方法その他必要な事項を指示することができる。」","o":["ア 都道府県知事/イ 占有者/ウ 減量","ア 都道府県知事/イ 所有者/ウ 適正処理","ア 市町村長/イ 占有者/ウ 減量","ア 市町村長/イ 所有者/ウ 適正処理","ア 市町村長/イ 所有者/ウ 減量"],"a":2,"e":"条文は「市町村長は、…多量の一般廃棄物を生ずる土地又は建物の占有者に対し、当該一般廃棄物の減量に関する計画の作成…を指示することができる」(第6条の2第5項)。","l":"廃棄物処理法 第6条の2第5項","c":""},{"id":"2021-160","s":5,"q":"廃棄物の区分について述べた次の文のうち、最も不適当なものはどれか。","o":["事業活動で出た廃棄物のうち、燃え殻や汚泥など20種類が産業廃棄物と定められている。","木くずのうち、建設業など特定の業種から出たものは産業廃棄物にあたる。","事業活動で出る油分のうち、グリース阻集器で集めたものは産業廃棄物にあたる。","事業系一般廃棄物とは、事業活動で出る廃棄物のうち産業廃棄物にあたらないものである。","事業活動で出る廃棄物のうち、ばいじん類は安定型品目の産業廃棄物にあたる。"],"a":4,"e":"安定型産業廃棄物は、廃プラスチック類・ゴムくず・金属くず・ガラスくず等・がれき類に限られ、ばいじんは含まれない(廃棄物処理法施行令第6条第1項第3号イ)。","l":"廃棄物処理法施行令 第6条第1項第3号イ","c":""},{"id":"2021-161","s":5,"q":"建築物内の廃棄物などについて述べた次の文のうち、最も不適当なものはどれか。","o":["し尿を含まないビルピットの汚泥は、産業廃棄物である。","事業活動で出たプラスチック類は、産業廃棄物である。","水銀を使った蛍光管は、捨てるときの取扱いが規制されている。","再利用する古紙は、登録された資源回収業者などが扱う。","特定建築物の清掃作業で出る廃液の排水基準値は、建築物衛生法で定められている。"],"a":4,"e":"この記述が誤り。建築物衛生法とその施行令・施行規則には、清掃廃液の排水基準値の定めはない(排水の基準は下水道法などの分野)。","l":"建築物衛生法施行規則(該当規定なし)","c":""},{"id":"2021-162","s":5,"q":"建築物内廃棄物の貯留・搬出方式について述べた次の文のうち、最も不適当なものはどれか。","o":["真空収集方式は、広い大規模開発地域に導入されている。","容器方式は、コンパクタ・コンテナ方式より作業性にすぐれる。","貯留・排出機方式は、廃棄物を圧縮・貯留し、パッカー車に自動で積み替えて運び出す。","コンパクタ・コンテナ方式は、圧縮機で圧縮・貯留し、コンテナごとトラックで運び出す。","容器方式は、ほかの方式より広い設置スペースが必要である。"],"a":1,"e":"容器方式は容器の移動や積込みを人手で行うため、機械で処理するコンパクタ・コンテナ方式より作業性は劣る(2022年度問164でもコンパクタ・コンテナ方式の作業性がすぐれるとされている)。","l":"法令外","c":""},{"id":"2021-163","s":5,"q":"建築物内廃棄物の中間処理について述べた次の文のうち、最も不適当なものはどれか。","o":["雑誌の処理方法として、切断がある。","厨芥類の処理方法として、脱水がある。","生ごみの処理方法として、乾燥がある。","OA紙の処理方法として、梱包がある。","缶類の処理方法として、圧縮がある。"],"a":0,"e":"この記述が誤り。雑誌はそのまま資源として回収されるので、切断はしない。","l":"法令外","c":""},{"id":"2021-164","s":5,"q":"建築物内の廃棄物保管場所に必要な面積として、正しいものはどれか。ただし、作業場の面積や粗大ごみ・再利用物の管理面積は考えない。\n延べ床面積:10,000m²、廃棄物発生量:0.04kg/(m²・日)、保管容器:1個に10kg、保管容器1個は0.25m²を占める、保管日数:2日、保管容器は平積みとする。","o":["10m²","20m²","80m²","200m²","500m²"],"a":1,"e":"2日分の量は10,000×0.04×2＝800kg。容器は800÷10＝80個。面積は80×0.25＝20m²。","l":"計算","c":""},{"id":"2021-165","s":5,"q":"リサイクルに関する法律と、その対象品目の組合せとして、最も不適当なものはどれか。","o":["容器包装リサイクル法 ― ペットボトル","食品リサイクル法 ― 食品残渣","建設リサイクル法 ― 木材","家電リサイクル法 ― 食器洗い乾燥機","小型家電リサイクル法 ― 携帯電話"],"a":3,"e":"家電リサイクル法の対象はエアコン、テレビ、冷蔵庫・冷凍庫、洗濯機・衣類乾燥機の4品目で(特定家庭用機器再商品化法施行令第1条)、食器洗い乾燥機は含まれない。","l":"特定家庭用機器再商品化法施行令 第1条","c":""},{"id":"2021-166","s":6,"q":"蚊の防除に関する記述として、最も不適当なものはどれか。","o":["昆虫成長制御剤(IGR)は、幼虫・蛹・成虫のすべての段階で効果がある。","ULV処理は、短い期間の効果しか期待できない。","浄化槽の中の防除効果は、柄杓ですくい取った幼虫の数で判定する。","浄化槽の中の防除効果は、粘着トラップでとれた成虫の数で判定する。","樹脂蒸散剤は、密閉性が保たれている浄化槽などで効果を発揮する。"],"a":0,"e":"IGRは成虫を殺す効果がない(2016年問167で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-167","s":6,"q":"蚊の主な発生源や生態に関する記述として、最も不適当なものはどれか。","o":["コガタアカイエカは、水田や湿地などの水域で発生する。","ヒトスジシマカは、小さな人工容器や雨水ますで発生する。","アカイエカは、地下の浄化槽や湧水槽で発生する。","チカイエカは、最初の産卵を吸血しないで行うことができる。","アカイエカは、夜間に吸血する性質がある。"],"a":2,"e":"アカイエカは、有機物の多い排水溝や雨水ますで発生する(2022年問167で正しい記述として出題)。地下の浄化槽や湧水槽で発生するのはチカイエカである。","l":"法令外","c":""},{"id":"2021-168","s":6,"q":"ゴキブリの生態に関する記述として、最も不適当なものはどれか。","o":["ゴキブリが活動する場所にできる排泄物の汚れを、ローチスポットという。","日本にいるゴキブリの多くの種類は、屋外で暮らしている。","ゴキブリには決まった潜み場所があり、昼間はほとんどそこに隠れている。","日本にいるゴキブリには、卵から成虫まで1年以上かかる種類がいる。","ゴキブリの食べ物の好みは、成長の段階によって変わる。"],"a":4,"e":"ゴキブリの食性は、発育段階によって変わらない。","l":"法令外","c":""},{"id":"2021-169","s":6,"q":"ゴキブリの防除に関する記述として、最も不適当なものはどれか。","o":["薬剤は、生息場所を中心に、ある程度広い範囲に処理するのが望ましい。","防除作業の後には、効果判定の調査をすることが重要である。","毒餌処理に使う薬剤には、ディートやイカリジンを有効成分とする製剤がある。","よく歩き回る通路などに、残効性の高い有機リン剤やピレスロイド剤を処理する。","ペルメトリンを有効成分とする水性乳剤をULV機で散布すると、追い出し効果が期待できる。"],"a":2,"e":"ディートやイカリジンは吸血害虫用の忌避剤の成分であり(2023年問173で「イカリジン ― 吸血害虫用忌避剤」が正しい組合せとして出題)、毒餌の成分ではない。","l":"法令外","c":""},{"id":"2021-170","s":6,"q":"ダニに関する記述として、最も不適当なものはどれか。","o":["ツメダニの被害対策には、ヒョウヒダニ類やチャタテムシ類の防除が重要である。","家のまわりのマダニ類の対策では、ペットの衛生管理が重要である。","ヒゼンダニは皮膚の中に入り込み、吸血する。","コナダニ類の対策は、畳の表面の掃除機がけと、風通しをよくして乾かすことが基本である。","スズメサシダニが見つかった場合は、野鳥の巣が家の天井や壁にある可能性が高い。"],"a":2,"e":"ヒゼンダニはヒトの皮膚の下に内部寄生するダニで(2022年問170・2024年問169で正しい記述として出題)、吸血するとした点が誤り。","l":"法令外","c":""},{"id":"2021-171","s":6,"q":"殺虫剤に関する記述として、最も適当なものはどれか。","o":["有機リン剤を液化炭酸ガスに溶かし、ボンベに入れた製剤がある。","ピレスロイド剤でノックダウンした昆虫は、生き返らずに死ぬことが多い。","油剤は、有効成分をケロシンに溶かし、乳化剤を加えた製剤である。","プロペタンホスは、カーバメート系の殺虫剤である。","トランスフルトリンは、常温で揮散する性質をもつ薬剤である。"],"a":4,"e":"トランスフルトリンは常温揮散性の薬剤で、常温揮散製剤に使われる(2023年問173で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2021-172","s":6,"q":"殺虫剤の有効成分とその効き目に関する記述として、最も不適当なものはどれか。","o":["ピレスロイド剤には、蚊などを寄せつけない忌避効果がある。","殺虫剤への抵抗性は、どんな有効成分でも身につけられてしまう可能性がある。","除虫菊に含まれる殺虫成分と、合成されたそれに似た物質をまとめて、ピレスロイドと呼ぶ。","幼若ホルモン様化合物は、幼虫が脱皮するときに表皮ができるのを妨げる。","LD50の値が小さいほど、殺虫力が強い薬剤といえる。"],"a":3,"e":"幼若ホルモン様化合物について、脱皮時の表皮形成を阻害するとした記述が誤り。","l":"法令外","c":""},{"id":"2021-173","s":6,"q":"クマネズミに関する記述として、最も不適当なものはどれか。","o":["警戒心が強く、粘着トラップでの防除が難しい。","都心のビルの中では、最も多い種類(優占種)になっている。","運動能力が高く、電線やロープを渡ることができる。","ドブネズミと比べて、何でも食べる雑食の傾向が強い。","尾は体長より長く、耳は大きくて折り返すと目をおおう。"],"a":3,"e":"クマネズミは、ドブネズミと比べて穀類などの植物性の餌を好む傾向が強い(2022年問175で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-174","s":6,"q":"建物の中のネズミの防除に関する記述として、最も不適当なものはどれか。","o":["ジフェチアロール以外の抗凝血性殺鼠剤は、続けて食べさせる必要がある。","外からの侵入を防ぐため、通風口や換気口の金属格子の目の幅は1cm以下にする。","カプサイシンのスプレーやパテは、ケーブルなどのかじり防止や、かじられた穴の修理に使われる。","防除は、餌を絶つこと、巣をつくらせないこと、通り道をふさぐことが基本である。","殺鼠剤には、口から取り込ませるもの以外に、皮膚から取り込ませて効く薬剤がある。"],"a":4,"e":"皮膚から取り込ませて効く殺鼠剤はない(2020年問174で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-175","s":6,"q":"衛生害虫と健康被害に関する記述として、最も不適当なものはどれか。","o":["イエバエは、消化器の感染症の病原体を運ぶことが知られている。","小さなダニや昆虫の死骸のかけらは、喘息の原因の一つである。","ハチ毒には、アミン類のほかに、アレルギー反応を起こす酵素類が含まれている。","ヒアリが各地の港湾地区で見つかっており、皮膚炎の被害が心配されている。","トコジラミは、高齢の入院患者が多い病院での吸血被害が問題になっている。"],"a":4,"e":"トコジラミの吸血被害が問題になっているのは、ホテル・旅館・簡易宿泊所などの宿泊施設である(2020年問175で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-176","s":6,"q":"衛生害虫などが媒介する感染症と、その媒介者の組合せとして、最も不適当なものはどれか。","o":["チクングニア熱 ― ヒトスジシマカ","日本紅斑熱 ― コロモジラミ","ウエストナイル熱 ― アカイエカ","レプトスピラ症 ― ネズミ","マラリア ― ハマダラカ"],"a":1,"e":"日本紅斑熱を媒介するのはマダニ類である(2024年問177で正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-177","s":6,"q":"防除に使う機器と薬剤に関する記述として、最も不適当なものはどれか。","o":["すき間や割れ目などの細かい部分に粉剤を処理する場合は、電動散粉機を使う。","噴霧器のノズルから出る薬液の噴射パターンの一つに、扇型がある。","ミスト機は、汚水槽の蚊やチョウバエの防除に使われる。","液化炭酸ガス製剤には、有機溶媒や水は使われていない。","粘着式殺虫機は、昆虫の死骸がまわりに落ちることが少ない。"],"a":0,"e":"すき間や割れ目などの細かい部分の処理に電動散粉機を使うとした記述が誤り。","l":"法令外","c":""},{"id":"2021-178","s":6,"q":"建築物衛生法にもとづくねずみ・昆虫等の防除について、次の文の【ア】〜【エ】に入る語句の組合せとして、最も適当なものはどれか。\n「ねずみ等の防除は、IPM(総合的有害生物管理)の考え方にもとづいて行わなければならない。この防除では、【ア】や【イ】、防除法の選定、【ウ】などが重視され、防除法を選ぶときは【エ】や侵入防止対策を優先して検討する必要がある。」","o":["ア:使用薬剤の選定 ― イ:防除目標の設定 ― ウ:利用者の感覚的評価 ― エ:発生時対策","ア:生息密度調査 ― イ:防除目標の設定 ― ウ:生息指数による評価 ― エ:発生時対策","ア:使用薬剤の選定 ― イ:化学的対策 ― ウ:使用薬剤の種類 ― エ:発生時対策","ア:生息密度調査 ― イ:防除目標の設定 ― ウ:生息指数による評価 ― エ:発生予防対策","ア:発生時対策 ― イ:化学的対策 ― ウ:利用者の感覚的評価 ― エ:発生予防対策"],"a":3,"e":"IPMでは、生息密度調査、防除目標の設定、生息指数による評価が重視され、防除法では発生予防対策と侵入防止対策を優先する(2022年問180でも「発生予防対策は対策の基本」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2021-179","s":6,"q":"ねずみ・昆虫等の防除に関する記述として、最も適当なものはどれか。","o":["ネズミや害虫には、薬剤処理とトラップによる対策を優先して行う。","IPMの警戒水準とは、すぐに防除作業が必要な状況をいう。","生息密度調査の結果が許容水準にあたる場合は、原則として6か月以内に1回、発生が多い場所では2か月以内に1回の定期調査を続ける。","チャバネゴキブリがいる厨房の5か所に3日間置いた粘着トラップで、成虫30匹・幼虫120匹がとれた場合、ゴキブリ指数は30である。","ゴキブリ防除用として、医薬品や医薬部外品として承認された殺虫剤の代わりに使える農薬がある。"],"a":2,"e":"許容水準なら定期調査を続ける。調査の頻度は施行規則第4条の5(6か月以内ごと)と告示第119号 第6(発生しやすい場所は2か月以内ごと)に定められている。なお(4)のゴキブリ指数は150÷5÷3=10である。","l":"建築物衛生法施行規則 第4条の5、平成15年厚生労働省告示第119号 第6","c":""},{"id":"2021-180","s":6,"q":"衛生害虫の防除などに関する記述として、最も不適当なものはどれか。","o":["作用のしくみが異なる殺虫剤を順番に使うローテーション処理で、殺虫剤抵抗性の発達をおさえられる。","ニューサンスコントロールとは、感染症を媒介する衛生動物の防除をさす。","吸血昆虫の中には、幼虫も成虫も、雌も雄も吸血する種類がいる。","昆虫などへの不快感は、主観的なものである。","昆虫成長制御剤(IGR)で処理しても、成虫の数がすぐに減ることはない。"],"a":1,"e":"感染症を媒介する動物の防除はベクターコントロールで、ニューサンスコントロールとは別の側面である(2020年問179で「ペストコントロールにはベクターコントロールとニューサンスコントロールの2つの側面がある」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-1","s":0,"q":"次の法律のうち、厚生労働省が所管していないものはどれか。","o":["生活衛生関係営業の運営の適正化及び振興に関する法律","労働安全衛生法","有害物質を含有する家庭用品の規制に関する法律","廃棄物の処理及び清掃に関する法律","旅館業法"],"a":3,"e":"廃棄物の処理及び清掃に関する法律(廃棄物処理法)は環境省の所管である。","l":"法令外(各省設置法)","c":"出題時の選択肢(5)は「水道法」だったが、2024年4月に水道行政が国土交通省・環境省へ移り、水道法も「厚生労働省が所管していない」法律になって正解が2つになるため、厚生労働省所管の「旅館業法」に差し替えた。"},{"id":"2022-2","s":0,"q":"特定建築物について、誤っているものはどれか。","o":["特定建築物の衛生上の維持管理を監督する行政機関は、都道府県知事、保健所を設置する市の市長、特別区の区長である。","建築物環境衛生管理基準を定め、維持管理権原者にそれを守ることを義務づけている。","保健所は、多くの人が使う建物について、正しい知識を広めるとともに、相談・指導を行う。","特定建築物の所有者等は、建築物環境衛生管理技術者を選任しなければならない。","登録業者の業務の改善・向上のため、事業ごとに、都道府県を単位とした団体を知事が指定する制度がある。"],"a":4,"e":"登録業者の団体を指定するのは厚生労働大臣で、事業ごとに全国的に業務を行う団体(指定団体)を指定する。","l":"建築物衛生法 第12条の6","c":""},{"id":"2022-3","s":0,"q":"特定建築物の用途に当たるものはどれか。","o":["寺院","病院","自然科学系研究所","水族館","スポーツジム"],"a":3,"e":"水族館は博物館に類するものとして特定用途に含まれる。寺院、病院、自然科学系研究所は含まれない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2022-4","s":0,"q":"建築物衛生法令の主な制度改正について、誤っているものはどれか。なお、書かれている年は正しいものとして考える。","o":["昭和50年に特定建築物の範囲が広げられ、学校教育法第1条の学校を除いて、延べ面積3,000m²以上となった。","昭和53年に、維持管理を監督する行政機関が、都道府県知事から保健所を設置する市の市長にまで広げられた。","昭和55年に、建築物の衛生管理業務を営む者の質を高めるため、一定の人的・物的基準を要件とする、都道府県知事による事業者の登録制度が設けられた。","平成13年に、登録事業のうち既存の1業種の業務内容が追加されて名称が変わり、新しく2業種が加わった。","平成14年に、雑用水の維持管理基準を加えるなど、建築物環境衛生管理基準の見直しが行われた。"],"a":1,"e":"この記述が誤り(監督する行政機関の範囲の改正内容が事実と異なる)。","l":"建築物衛生法(改正の経緯)","c":""},{"id":"2022-5","s":0,"q":"次の建物で、特定用途に使われる部分の延べ面積は( ア )m²となり、この建物は特定建築物に( イ )。(ア)(イ)の組合せとして正しいものはどれか。なお、A〜E社はお互いに関係がない。\n【建物の内訳】A社の銀行の店舗と事務所 1,700m²、銀行の地下駐車場 300m²、B社の学習塾 700m²とそれに付属する自習室 100m²、C社の保育施設 600m²、D社の老人デイサービスセンター 500m²、E社の美容室 400m²","o":["ア 4,300　イ 当たる","ア 3,700　イ 当たる","ア 3,200　イ 当たる","ア 2,900　イ 当たらない","ア 2,500　イ 当たらない"],"a":2,"e":"銀行の店舗・事務所1,700+銀行の駐車場300+学習塾700+自習室100+美容室400=3,200m²。保育施設とデイサービスセンターは特定用途に含まれない。3,000m²以上なので特定建築物に当たる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2022-6","s":0,"q":"特定建築物の届出事項として、最も不適当なものはどれか。","o":["建物の全部が使われ始めた年月日","特定建築物の用途と、特定用途に使われる部分の延べ面積","建築物環境衛生管理技術者の氏名・住所・免状番号","特定建築物の所有者等の氏名と住所","特定建築物の構造設備の概要"],"a":0,"e":"届け出るのは「特定建築物が使用されるに至った年月日」であり、「建物の全部が使われ始めた年月日」ではない。","l":"建築物衛生法施行規則 第1条","c":""},{"id":"2022-7","s":0,"q":"建築物環境衛生管理基準にもとづく空気環境の測定について、誤っているものはどれか。","o":["2か月以内ごとに1回の定期測定が、1年を通して基準値以下なら、冷房期・暖房期とその中間期の年4回に回数を減らせる。","温度・相対湿度・気流は、使用時間中いつも基準に合っているかどうかで判定する。","浮遊粉じん・一酸化炭素・二酸化炭素は1日の使用時間中の平均値で判定するが、実務上は、使用時間中の適切な2時点の測定の平均値で判定してよい。","測定は、床上75cm以上150cm以下の位置で行う。","各階ごとに1か所以上、居室の中央部で行う。"],"a":0,"e":"空気環境の測定は、2か月以内ごとに1回、定期に行わなければならず、結果が良くても回数を減らす規定はない。","l":"建築物衛生法施行規則 第3条の2","c":""},{"id":"2022-8","s":0,"q":"建築物環境衛生管理基準の雑用水の衛生上の措置について、正しいものはどれか。","o":["雑用水の給水栓での遊離残留塩素の規定は、飲料水の給水栓での規定と異なる。","雑用水を水洗便所に使う場合は、し尿を含む水を原水に使ってはならず、pH値・臭気・外観・大腸菌が基準に合っていること。","雑用水を散水・修景・清掃に使う場合は、し尿を含む水を原水に使ってはならず、pH値・臭気・外観・大腸菌・濁度が基準に合っていること。","遊離残留塩素・pH値・臭気・外観は14日以内ごとに1回、大腸菌・濁度は3か月以内ごとに1回、定期に検査する。","供給する雑用水が健康を害するおそれがあると分かったときは、すぐに危険であることを関係者に知らせ、その後で供給を止める。"],"a":2,"e":"散水・修景・清掃用の雑用水は、し尿を含む水を原水に使えず、pH値・臭気・外観・大腸菌・濁度の基準がある。水洗便所用は、し尿を含む水の制限がなく、濁度の基準もない。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2022-9","s":0,"q":"建築物環境衛生管理基準にもとづく給排水設備の衛生上の措置について、最も不適当なものはどれか。","o":["飲用の循環式給湯設備の貯湯槽の清掃は、1年以内ごとに1回、定期に行う。","グリース阻集器の掃除は、6か月以内ごとに1回、定期に行う。","雑用水槽の清掃は、槽の容量・材質や雑用水の水源の種類などに応じた方法で、定期に行う。","高置水槽や圧力水槽などを清掃した後で、受水槽を清掃する。","排水槽の清掃で出た汚泥などの廃棄物は、関係法令にもとづいて適切に処理する。"],"a":3,"e":"清掃は水の流れの上流から行うため、受水槽を先に清掃し、その後に高置水槽や圧力水槽を清掃する。","l":"空気調和設備等の維持管理及び清掃等に係る技術上の基準(平成15年厚生労働省告示第119号)","c":""},{"id":"2022-10","s":0,"q":"建築物環境衛生管理技術者について、最も不適当なものはどれか。","o":["特定建築物所有者等が管理技術者を選任しなかった場合は、30万円以下の罰金に処せられる。","特定建築物に選任されている管理技術者は、業務に支障がない範囲で、登録事業の監督者等になることができる。","免状の返納を命じられ、その日から1年を過ぎていない人には、免状を交付しないことがある。","管理技術者の職務は、特定建築物で環境衛生上の維持管理業務が適正に行われるよう、全体的に監督することである。","免状の記載事項が変わったときは、厚生労働大臣に書換え交付を申請できる。"],"a":1,"e":"特定建築物に選任されている管理技術者は、登録事業の監督者等を兼ねることはできない。","l":"建築物衛生法施行規則(事業の登録基準)、関係通知","c":""},{"id":"2022-11","s":0,"q":"建築物環境衛生総合管理業の登録に必要な監督者等に当たらないものはどれか。","o":["統括管理者","清掃作業監督者","貯水槽清掃作業監督者","空調給排水管理監督者","空気環境測定実施者"],"a":2,"e":"貯水槽清掃作業監督者は、建築物飲料水貯水槽清掃業の登録に必要な監督者である。総合管理業には必要ない。","l":"建築物衛生法施行規則(建築物環境衛生総合管理業の登録基準)","c":""},{"id":"2022-12","s":0,"q":"事業の登録を受けた登録業者が次の事項を変えた場合、届出がいらないものはどれか。","o":["営業所の名称","清掃作業監督者","主な機械器具その他の設備","機械器具その他の設備の維持管理の方法","従事者の研修の方法"],"a":4,"e":"従事者の研修の方法は、変更の届出が必要な事項に含まれていない。","l":"建築物衛生法施行規則(登録事項の変更の届出)","c":""},{"id":"2022-13","s":0,"q":"都道府県知事による立入検査について、最も適当なものはどれか。","o":["特定建築物の中の住居には、住んでいる人の承諾なしに立ち入ることができる。","立入検査は、日時を前もって知らせなければならない。","立入検査は、必ず2人以上で行う。","立入検査を行う職員は、身分を示す証明書を持っていなければならない。","管理基準に違反していれば、すべてすぐに改善命令などの行政処分が行われる。"],"a":3,"e":"立入検査を行う職員(環境衛生監視員)は身分を示す証明書を携帯し、求められたら示さなければならない。住居に立ち入るには居住者の承諾が必要。","l":"建築物衛生法 第11条","c":""},{"id":"2022-14","s":0,"q":"学校保健安全法で定める学校薬剤師の職務として、最も不適当なものはどれか。","o":["学校安全計画の立案に関わること","学校保健計画の立案に関わること","学校の環境衛生の維持・改善について、必要な指導・助言をすること","環境衛生検査に従事すること","病気の予防処置に従事すること"],"a":4,"e":"病気の予防処置に従事するのは学校医の職務である。","l":"学校保健安全法施行規則 第22条、第24条","c":""},{"id":"2022-15","s":0,"q":"地域保健法について、誤っているものはどれか。","o":["地域保健法は、保健所法を改正してつくられた。","保健所は、都道府県、指定都市、中核市その他の政令で定める市、特別区が設置する。","都道府県知事は、保健所の受け持ち区域を決めるとき、前もって厚生労働大臣の承認を得なければならない。","厚生労働大臣は、地域保健対策の推進に関する基本的な指針を定めなければならない。","市町村は、市町村保健センターを設置できる。"],"a":2,"e":"保健所の所管区域を決めるのに、厚生労働大臣の承認は必要ない。","l":"地域保健法 第5条","c":""},{"id":"2022-16","s":0,"q":"下水道法について、最も不適当なものはどれか。","o":["公共下水道に流しこむための排水設備は、その公共下水道を管理する者が設置する。","公共下水道の構造は、政令と地方公共団体の条例で定める技術上の基準に合っていなければならない。","公共下水道の設置・改築・修繕・維持などの管理は、原則として市町村が行う。","下水とは、生活や事業(耕作の事業を除く)によって出る廃水、または雨水をいう。","公共下水道管理者は、公共下水道を設置するとき、前もって事業計画を定めなければならない。"],"a":0,"e":"公共下水道へ流しこむための排水設備は、その土地の所有者などが設置する。","l":"下水道法 第10条","c":""},{"id":"2022-17","s":0,"q":"旅館業法第4条の次の文の(ア)〜(ウ)に入る語句の組合せとして、正しいものはどれか。\n「営業者は、旅館業の施設について、( ア )、採光、( イ )、防湿及び清潔その他( ウ )の衛生に必要な措置を講じなければならない。」","o":["ア 換気　イ 照明　ウ 客室","ア 換気　イ 照明　ウ 宿泊者","ア 換気　イ 防音　ウ 客室","ア 空気調和　イ 照明　ウ 宿泊者","ア 空気調和　イ 防音　ウ 客室"],"a":1,"e":"旅館業法第4条は「換気、採光、照明、防湿及び清潔その他宿泊者の衛生に必要な措置」を講じるよう定めている。","l":"旅館業法 第4条","c":""},{"id":"2022-18","s":0,"q":"環境基本法の大気の汚染に係る環境基準に定められていない物質はどれか。","o":["微小粒子状物質","光化学オキシダント","二酸化窒素","ベンゼン","ホルムアルデヒド"],"a":4,"e":"ホルムアルデヒドは大気の環境基準に定められていない。ベンゼンは有害大気汚染物質として環境基準が定められている。","l":"大気の汚染に係る環境基準(環境基本法 第16条)","c":""},{"id":"2022-19","s":0,"q":"事務所衛生基準規則で、労働者をいつも働かせる事務室の環境管理について、最も不適当なものはどれか。","o":["気積は、設備の容積と床面から4mを超える空間を除いて、1人あたり10m³以上にしなければならない。","一酸化炭素の含有率は100万分の50以下、二酸化炭素の含有率は100万分の5,000以下にしなければならない。","冷房する場合は、室温を外気温よりひどく低くしてはならない。","中央管理方式の空調設備がある建物では、作業環境測定を2か月以内ごとに1回、定期に行わなければならない。","事務室の作業環境測定は、作業環境測定士が行わなければならない。"],"a":4,"e":"事務室の作業環境測定は、作業環境測定士でなければ行えないという決まりはない。","l":"事務所衛生基準規則 第2条〜第7条","c":""},{"id":"2022-20","s":0,"q":"平成30年改正の健康増進法で、受動喫煙防止の対象となる施設の区分について、誤っているものはどれか。","o":["公立の小学校や中学校は、第一種施設である。","行政機関が事務を行うために使う庁舎は、第二種施設である。","旅館業法の許可を受けたホテルや旅館は、第二種施設である。","一般の事務所は、第二種施設である。","医療法の病院は、第一種施設である。"],"a":1,"e":"国や地方公共団体の行政機関の庁舎は、学校や病院と同じ第一種施設である。","l":"健康増進法 第28条第5号","c":""},{"id":"2022-21","s":1,"q":"健康に影響する環境要因のうち、「化学的要因」として最も不適当なものはどれか。","o":["酸素","粉じん","オゾン","し尿","放射線"],"a":4,"e":"放射線は物理的要因に分類される。","l":"法令外","c":""},{"id":"2022-22","s":1,"q":"細胞・組織・臓器・臓器系と、そのはたらきの組合せとして、最も不適当なものはどれか。","o":["自律神経 ― 消化・呼吸・循環などのはたらきを調整する。","腎臓 ― 血液の老廃物などをろ過して尿をつくる。","消化器系 ― 栄養や水を取り入れ吸収し、再合成と排泄を行う。","赤血球 ― 細菌などから体を守るはたらきをもつ。","内分泌系 ― 成長・発達・代謝をコントロールする。"],"a":3,"e":"赤血球のはたらきは酸素を運ぶことである。細菌などから体を守るのは白血球のはたらき。","l":"法令外","c":""},{"id":"2022-23","s":1,"q":"労働衛生について、最も不適当なものはどれか。","o":["有害物の負荷量と、個体レベルでの障害などの程度との関係を、量-反応関係という。","最大許容濃度とは、作業中のどの時間でも曝露濃度がこの値以下なら、ほとんどすべての労働者に健康上の悪い影響が見られないと判断される濃度である。","許容濃度とは、1日8時間・週40時間程度、激しくない労働で有害物質にさらされても、ほとんどすべての労働者に健康上の悪い影響が見られないと判断される濃度である。","許容限界とは、生物が耐えられなくなるストレスの強さの限界のことである。","一般の事務所の環境の基準は、労働安全衛生法にもとづく事務所衛生基準規則で定められている。"],"a":0,"e":"負荷量と個体の障害の程度の関係は「量-影響関係」という。量-反応関係は、負荷量と集団の中で反応が出た人の割合との関係。","l":"法令外","c":""},{"id":"2022-24","s":1,"q":"温熱環境の指数について、最も不適当なものはどれか。","o":["予測平均温冷感申告(PMV)は、気温・湿度・風速・平均放射温度・エネルギー代謝量・着衣量の6つの要素で評価する。","不快指数は、気温と湿球温度、または気温と相対湿度から計算する。","黒球(グローブ)温度は、銅でできた黒い球の中心の温度を測ったものである。","有効温度は、気温・湿度・風速・熱放射の4つの要素の影響を含んだ温熱環境の指標である。","湿球黒球温度(WBGT)は、暑さ指数として熱中症予防に使われている。"],"a":3,"e":"有効温度は、気温・湿度・風速の3つの要素で表す指標で、熱放射は含まない。熱放射を加えたものは修正有効温度である。","l":"法令外","c":""},{"id":"2022-25","s":1,"q":"エネルギー代謝について、最も不適当なものはどれか。","o":["基礎代謝とは、朝起きてすぐの空腹時に、あお向けに寝た姿勢でのエネルギー代謝のことである。","睡眠時の代謝量は、基礎代謝量より高い。","安静時の代謝量は、基礎代謝量よりおよそ20%高い。","体の熱は、主に食べた物の代謝による化学的エネルギーから生まれる。","体温は、熱をつくる量と逃がす量のバランスで一定に保たれている。"],"a":1,"e":"睡眠時の代謝量は、基礎代謝量より低い。","l":"法令外","c":""},{"id":"2022-26","s":1,"q":"寒冷障害(ヒトの低温障害)について、最も不適当なものはどれか。","o":["5℃以下の水に急に浸かると、5〜15分で命にかかわる低体温症になる。","気温が13〜16℃程度でも、天候によっては低体温症になることがある。","乳幼児や高齢者は寒さに適応する力が弱く、低体温症のリスクが高い。","低体温症の診断は、わきの下の体温を測って行う。","凍傷による障害は、組織が凍ることと、まわりの血管の収縮・血栓による血流の妨げで起こる。"],"a":3,"e":"低体温症の診断は、体の中心の温度(深部体温)を反映する直腸温などで行う。","l":"法令外","c":""},{"id":"2022-27","s":1,"q":"建物の中の湿度について、最も不適当なものはどれか。","o":["湿度が低いと、ほこりが舞い上がりやすくなる。","湿度が低いと、インフルエンザウイルスが生き残りやすくなる。","加湿器を清潔に保つことは、室内の環境衛生のために大切である。","湿度が高いと、体感温度が上がる。","湿度が高いと、壁の塗装がはがれやすくなる。"],"a":4,"e":"この記述が誤り。湿度が高いことで起こりやすいのは、結露やカビ・ダニの発生などである。","l":"法令外","c":""},{"id":"2022-28","s":1,"q":"空気環境について、最も不適当なものはどれか。","o":["良い室内空気環境を保つには、一般に1人あたり30m³/h以上の換気量が必要とされる。","ふつうの室内環境では、窒素による体への健康影響はない。","空気中の酸素濃度が16%程度になると、意識障害やけいれんが起こる。","二酸化炭素濃度は、室内空気の汚れや換気の総合的な指標として使われる。","窒素は、大気の約78%を占める。"],"a":2,"e":"酸素濃度16%程度では、呼吸・脈拍の増加や頭痛などが出始める段階である。意識障害やけいれんは、さらに低い濃度で起こる。","l":"法令外","c":""},{"id":"2022-29","s":1,"q":"浮遊粉じんについての次の文の(ア)(イ)に入る数値の組合せとして、最も適当なものはどれか。\n「粒径( ア )μm以下の粉じんは長い時間浮かんでいて、ヒトの気道に取りこまれる。特に肺に沈着して体に有害な影響を与えるのは、ふつう( イ )μm程度以下の大きさである。」","o":["ア 50　イ 10","ア 40　イ 10","ア 20　イ 5","ア 10　イ 5","ア 10　イ 1"],"a":4,"e":"粒径10μm以下の粉じんは長く浮遊して気道に入り、特に1μm程度以下のものが肺に沈着しやすい。建築物衛生法の浮遊粉じんの測定対象も粒径おおむね10μm以下である。","l":"法令外","c":""},{"id":"2022-30","s":1,"q":"アスベスト(石綿)について、最も不適当なものはどれか。","o":["自然界にある、繊維状の水和したケイ酸塩鉱物をまとめた呼び名である。","健康障害は、アスベスト製品をつくる工場の従業員だけに限られない。","肺がんについて、喫煙との相乗作用が疫学的に示されている。","労働安全衛生法、大気汚染防止法、建築基準法などで規制されている。","現在は試験研究用を除いて使用禁止であり、今ある建物には残っていない。"],"a":4,"e":"使用は禁止されたが、禁止前に建てられた建物には今もアスベストを使った建材が残っている。","l":"法令外","c":""},{"id":"2022-31","s":1,"q":"二酸化炭素について、最も不適当なものはどれか。","o":["大気中の濃度は、一般に0.04〜0.05%である。","学校保健安全法の学校環境衛生基準では、教室の二酸化炭素濃度は0.5%以下と定められている。","安静にしている人の吐く息には、4%程度含まれている。","室内の濃度が3〜4%になると、頭痛・めまい・血圧上昇が起こる。","室内の濃度が7〜10%になると、数分で意識不明になる。"],"a":1,"e":"学校環境衛生基準では、教室の二酸化炭素濃度は1,500ppm(0.15%)以下とされている。","l":"学校環境衛生基準","c":""},{"id":"2022-32","s":1,"q":"空気汚染と健康障害の組合せとして、最も不適当なものはどれか。","o":["オゾン ― 気道の粘膜への刺激","レジオネラ属菌 ― 急性肺炎","真菌 ― アレルギー性疾患","たばこの煙 ― 慢性閉塞性肺疾患(COPD)","二酸化硫黄 ― 過敏性肺炎"],"a":4,"e":"過敏性肺炎は、カビなどの有機物の粉じんを吸い込んで起こる病気であり、二酸化硫黄の健康障害としては不適当。","l":"法令外","c":""},{"id":"2022-33","s":1,"q":"音について、最も不適当なものはどれか。","o":["外耳は、耳介・外耳道・鼓膜からなる。","音の伝わり方には、気導と骨導がある。","サウンドアメニティーとは、心地よい音環境のことである。","聴力は、オージオメータの基準音圧レベルを基準にして測る。","蝸牛は内耳にあり、その中には有毛細胞をもつコルチ器がある。"],"a":0,"e":"外耳は耳介と外耳道からなり、鼓膜は中耳に含まれる。","l":"法令外","c":""},{"id":"2022-34","s":1,"q":"騒音について、最も不適当なものはどれか。","o":["騒音レベル85dB以上の騒音に長い間さらされると、聴力に障害が起こる。","騒音によって副腎ホルモンの分泌が増えるなど、内分泌系への影響が起こる。","文章了解度は、聞きとりの妨げについて、話の内容がどれだけ分かるかを評価する指標である。","騒音のある業務で働く人の4,000Hzの聴力レベルが20dBなら、騒音性難聴とされる。","一般環境騒音の環境基準は、地域の類型ごとに、道路に面しない地区と面する地区に分けて決められている。"],"a":3,"e":"聴力レベル20dB程度は正常の範囲で、これだけで騒音性難聴とはされない。","l":"法令外","c":""},{"id":"2022-35","s":1,"q":"振動について、最も適当なものはどれか。","o":["地震の震度は、気象庁の職員の体感で測っている。","レイノー現象は、気温が高く代謝が上がる夏に起こりやすい。","全身振動によって、胃腸のはたらきが抑えられる。","振動は、皮膚・内臓・関節など全身にある運動神経の末端の受容器で感じとられる。","地面の振動が伝わるとき、建物内の床の振動レベルは、減衰によって屋外の地面より低くなる。"],"a":2,"e":"全身振動により、胃腸のはたらきの抑制などが見られる。震度は震度計で測り、レイノー現象は寒いときに起こりやすい。","l":"法令外","c":""},{"id":"2022-36","s":1,"q":"目の構造と光の知覚、光環境について、最も不適当なものはどれか。","o":["照度が0.1lxより下がると、視力は大きく下がる。","錐体には赤・青・黄の光にそれぞれ反応する3種類があり、その組合せで色を感じる。","視細胞が感じた光の刺激は、視神経を通って脳に伝わり、知覚される。","グレアとは、視野の中に輝度が高すぎる点などがあることで起こる不快感や見にくさである。","目の水晶体は、カメラでいうとレンズの役割をする。"],"a":1,"e":"錐体は、赤・緑・青の光にそれぞれ反応する3種類がある。黄ではなく緑である。","l":"法令外","c":""},{"id":"2022-37","s":1,"q":"情報機器作業について、最も不適当なものはどれか。","o":["情報機器には、タブレット端末も含まれる。","照明や採光は、なるべく明るさの差が大きくならないようにする。","ディスプレイは、画面の上の端が目の高さより少し上になる高さにするのが望ましい。","情報機器作業とは、パソコンなどの情報機器を使ってデータ入力や文章・画像などの作成を行う作業である。","情報機器作業者の健康診断では、目の症状、筋骨格系の症状、ストレスに関する症状を調べる。"],"a":2,"e":"ディスプレイは、画面の上の端が目の高さとほぼ同じか、少し下になる高さにするのが望ましい。","l":"法令外(情報機器作業における労働衛生管理のためのガイドライン)","c":""},{"id":"2022-38","s":1,"q":"電場・磁場・電磁波について、最も不適当なものはどれか。","o":["電磁波には、電波・光・X線・γ線が含まれる。","目で確かめられる電磁波は、可視光線だけである。","地球の磁場のような静磁場にさらされることによる健康影響は知られていない。","静電気は、放電によってガソリンや有機溶剤に火をつけたり爆発させたりする。","電磁波の周波数が高くなると、波長は長くなる。"],"a":4,"e":"電磁波は、周波数が高くなるほど波長は短くなる。","l":"法令外","c":""},{"id":"2022-39","s":1,"q":"赤外線と紫外線の健康影響について、最も不適当なものはどれか。","o":["赤外線は熱中症の原因になる。","赤外線は、ビタミンDがつくられるのを助ける。","紫外線を浴びることで、角膜炎が起こる。","紫外線のうちUV-Cは、オゾン層に吸収される。","紫外線のUV-Bはエネルギーが強く、肌の表面の細胞を傷つけたり炎症を起こしたりして、皮膚がんのリスクを高める。"],"a":1,"e":"体内でビタミンDがつくられるのを助けるのは紫外線である。","l":"法令外","c":""},{"id":"2022-40","s":1,"q":"健康な体重75kgの一般成人の体内の水分量として、最も適当なものはどれか。","o":["20kg未満","20kg以上30kg未満","30kg以上40kg未満","40kg以上50kg未満","50kg以上60kg未満"],"a":3,"e":"成人の体内水分量は体重の約60%なので、75kg×0.6=約45kgとなる。","l":"法令外","c":""},{"id":"2022-41","s":1,"q":"自然界に出されると、生物濃縮によってヒトの健康に影響する物質はどれか。","o":["四塩化炭素","シアン化合物","鉛","有機水銀","六価クロム"],"a":3,"e":"有機水銀(メチル水銀)は魚介類などに生物濃縮され、それを食べたヒトに水俣病などの健康被害を起こした。","l":"法令外","c":""},{"id":"2022-42","s":1,"q":"のどの渇きが起こるときの体内の水分の不足の割合として、最も適当なものはどれか。","o":["1%程度","4%程度","6%程度","8%程度","10%以上"],"a":0,"e":"体重の1%程度の水分が不足すると、のどの渇きを感じる。","l":"法令外","c":""},{"id":"2022-43","s":1,"q":"感染症法の類型のうち、一類・二類・三類のすべてで行われる措置として、最も不適当なものはどれか。","o":["積極的疫学調査","死体の移動制限","症状のない病原体保有者への入院勧告","汚染された場所の消毒","就業制限"],"a":2,"e":"入院勧告は一類・二類感染症の患者などが対象で、三類感染症では行われない。無症状病原体保有者への入院勧告は一類感染症だけである。","l":"感染症法 第19条、第26条","c":""},{"id":"2022-44","s":1,"q":"主にヒトからヒトへの感染で広がる感染症はどれか。","o":["マイコプラズマ肺炎","デング熱","発疹チフス","レプトスピラ症","ジカウイルス感染症"],"a":0,"e":"マイコプラズマ肺炎は、せきなどの飛沫でヒトからヒトへうつる。デング熱とジカウイルス感染症は蚊、発疹チフスはシラミ、レプトスピラ症はネズミなどの動物を介して感染する。","l":"法令外","c":""},{"id":"2022-45","s":1,"q":"次亜塩素酸ナトリウムによる消毒について、最も適当なものはどれか。","o":["一般に、手指の消毒に最もよく使われる。","ふつう5%の濃度で使う。","芽胞には効果がない。","室内では噴霧して使う。","有機物が多くても効き目は落ちない。"],"a":2,"e":"次亜塩素酸ナトリウムは芽胞には効果が期待できない。手指には使わず、有機物が多いと効果が落ちる。","l":"法令外","c":""},{"id":"2022-46","s":2,"q":"熱の移動について述べた次の文のうち、最も不適当なものはどれか。","o":["中空層の熱抵抗は、ある厚さ(2〜5cm)までは厚くなるほど大きくなるが、それ以上ではほぼ一定になる。","固体の中の熱流は、その場所の温度勾配に熱伝導率をかけて求める。","密度の大きい材料ほど、一般に熱伝導率は小さい。","同じ材料でも、一般に熱伝導率は温度によって違う。","同じ材料でも、一般に湿気を多く含むほど熱伝導率は大きくなる。"],"a":2,"e":"一般に密度の大きい材料ほど熱伝導率は大きい(2023年度問49でも正しい記述として出題)。コンクリートは断熱材より熱を通しやすい。","l":"法令外","c":""},{"id":"2022-47","s":2,"q":"湿り空気と湿度について述べた次の文のうち、最も不適当なものはどれか。","o":["温度を変えずに絶対湿度を増やすと、比エンタルピーは増える。","露点温度にある湿り空気では、乾球温度と湿球温度は等しい。","絶対湿度が上がると、水蒸気分圧は上がる。","絶対湿度が上がると、露点温度は下がる。","絶対湿度を変えずに温度を下げると、相対湿度は上がる。"],"a":3,"e":"水蒸気が多いほど高い温度で結露し始めるので、絶対湿度が上がると露点温度も上がる。","l":"法令外","c":""},{"id":"2022-48","s":2,"q":"熱放射について述べた次の文のうち、最も不適当なものはどれか。","o":["白色ペイントは、光ったアルミ箔より長波長放射率が小さい。","物体の表面から出る単位面積あたりの放射熱流は、絶対温度の4乗に比例する。","同じ温度の物体どうしでは、長波長放射について放射率と吸収率は等しい。","一般的なアスファルトの長波長放射率は約0.9である。","常温の物体が出す電磁波は、波長10μm付近の赤外線が中心である。"],"a":0,"e":"白色ペイントは長波長放射率が大きく(0.9程度)、光ったアルミ箔は小さい。白色は日射をよく反射するが、長波長放射率は大きい点に注意。","l":"法令外","c":""},{"id":"2022-49","s":2,"q":"1辺3mの正方形の壁材で立方体の部屋をつくり、日射の当たらない条件で、床が地面から浮いた状態で固定した。床と天井を含む壁材の熱貫流抵抗は0.4m²・K/W、すき間換気は無視できる。外気温度10℃のもとで室内を1,620Wで加熱したとき、十分に時間がたった後の室内空気温度として最も適当なものはどれか。","o":["12℃","22℃","28℃","32℃","40℃"],"a":1,"e":"床も浮いているので6面すべてから熱が逃げる。面積は3×3×6＝54m²、熱貫流率は1÷0.4＝2.5W/(m²・K)。1,620＝2.5×54×温度差より温度差＝12℃。室温＝10＋12＝22℃。","l":"計算","c":""},{"id":"2022-50","s":2,"q":"自然換気の換気力について述べた次の文のうち、最も不適当なものはどれか。","o":["温度差による換気力は、開口部の高さの差に比例して大きくなる。","温度差による換気力は、室内外の空気の密度差に比例して大きくなる。","風力による換気力は、外の風速の2乗に比例して大きくなる。","風力による換気力は、開口部の風圧係数の2乗に比例して大きくなる。","風力による換気力は、風向きが変わると変わる。"],"a":3,"e":"風力による換気力(風圧)は風圧係数に比例する(2025年度問51でも「風圧係数に比例」が正しい記述)。2乗に比例するのは風速の方である。","l":"法令外","c":""},{"id":"2022-51","s":2,"q":"空気の流れについて述べた次の文のうち、最も不適当なものはどれか。","o":["円形ダクトの圧力損失は、ダクトの直径に反比例する。","ダクトの形が変わることによる圧力損失は、風速の2乗に比例する。","合流や分岐のないダクトを流れる気流の速さは、断面積に比例する。","開口部を通る風量は、開口部前後の圧力差の平方根に比例する。","レイノルズ数は、慣性力と粘性力の比を表す無次元数である。"],"a":2,"e":"連続の式により、流量が一定なら流速×断面積が一定なので、流速は断面積に反比例する(細いところほど速い)。","l":"法令外","c":""},{"id":"2022-52","s":2,"q":"摩擦のないダクトの流れで、ベルヌーイの定理は (1/2)ρa²＋b＋ρgc＝一定 と表される。ρは密度、gは重力加速度である。a・b・c(ア〜ウ)にあたる語句の組合せとして、正しいものはどれか。","o":["ア(a) 速度/イ(b) 静圧/ウ(c) 高さ","ア(a) 速度/イ(b) 動圧/ウ(c) 高さ","ア(a) 高さ/イ(b) 静圧/ウ(c) 速度","ア(a) 静圧/イ(b) 高さ/ウ(c) 速度","ア(a) 動圧/イ(b) 高さ/ウ(c) 速度"],"a":0,"e":"第1項(1/2)ρa²は動圧なのでaは速度、第2項bは静圧、第3項ρgcは位置圧なのでcは高さ。","l":"法令外","c":""},{"id":"2022-53","s":2,"q":"建築物環境衛生管理基準とそれに関連して述べた次の文のうち、最も不適当なものはどれか。","o":["建築物衛生法の気流の管理基準値は0.5m/s以下である。","空気環境の管理項目の中で、気流は不適率が高い項目の一つである。","極端に気流が少ない状態は好ましくなく、ある程度の気流は確保すべきである。","冷房期の節電対策などで居室に扇風機を置くと、局所的に気流の基準値を超えることがある。","気流を改善する方法に、間仕切りの設置や吹出口の風量バランスの調整がある。"],"a":1,"e":"この記述が誤り。気流は不適率の高い項目ではない。気流の基準値0.5m/s以下は施行令第2条のとおり。","l":"建築物衛生法施行令 第2条第1号","c":""},{"id":"2022-54","s":2,"q":"換気について述べた次の文のうち、最も不適当なものはどれか。","o":["混合方式は、室内に送る清浄な空気と室内の空気を十分に混ぜて薄める方式である。","一方向方式は、清浄な空気をピストンのように一方向に流し、排気口へ押し出す方式である。","第2種換気は、自然給気口と機械排気による換気である。","局所換気は、汚染物質が出る場所を部分的に換気する方法である。","機械換気は、自然換気より適切な換気を計画しやすい。"],"a":2,"e":"第2種換気は、機械で給気し自然排気口から排気する方式。自然給気と機械排気の組合せは第3種換気である。","l":"法令外","c":""},{"id":"2022-55","s":2,"q":"室内の空気汚染物質について述べた次の文のうち、最も不適当なものはどれか。","o":["一酸化炭素の建築物内の発生源は、燃焼器具、たばこなどである。","二酸化炭素の建築物内の発生源は、人の活動(呼吸)、燃焼器具などである。","浮遊粉じんの建築物内の発生源は、人の活動などである。","ホルムアルデヒドの建築物内の発生源は、これを原料とした接着剤や、複合フローリング、合板などである。","オゾンの建築物内の発生源は、洗剤やクリーナなどである。"],"a":4,"e":"室内のオゾンのおもな発生源は、コピー機やレーザープリンタなどの高電圧を使う機器である(2025年度問55で正答)。","l":"法令外","c":""},{"id":"2022-56","s":2,"q":"空気汚染物質の特徴を示した次のア〜エのうち、ホルムアルデヒドの特徴にあたるものの組合せとして最も適当なものはどれか。\nア 常温で無色の、刺激臭のある気体である。\nイ 人に対して発がん性がある。\nウ 一酸化窒素と結びつき、二酸化窒素と酸素をつくる。\nエ 水に溶けない。","o":["アとイ","アとウ","アとエ","イとウ","イとエ"],"a":0,"e":"ホルムアルデヒドは無色で刺激臭のある気体で、発がん性がある。水によく溶ける(水溶液がホルマリン)ので、エは誤り。ウはオゾンの性質。","l":"法令外","c":""},{"id":"2022-57","s":2,"q":"エアロゾル粒子の相当径のうち、幾何相当径に分類されるものはどれか。","o":["空気力学径","ストークス径","円等価径","光散乱径","電気移動度径"],"a":2,"e":"円等価径は、粒子の投影面積と同じ面積の円の直径で、形から決める幾何相当径。ほかは沈降や光散乱、電気移動などの物理的なふるまいから決める物理相当径である。","l":"法令外","c":""},{"id":"2022-58","s":2,"q":"アレルゲンと微生物について述べた次の文のうち、最も不適当なものはどれか。","o":["オフィスビル内のアレルゲンの大部分は細菌類である。","空気調和機の中は、微生物が増えやすい環境になる。","アルテルナリアは、一般の環境で育つカビである。","ダンプネスとは、過度の湿気が原因でカビ臭さや微生物汚染などの問題が確認できる状態をいう。","大部分のダニアレルゲンの粒径は数μm以上である。"],"a":0,"e":"この記述が誤り。室内のアレルゲンとしてはダニやカビなどが中心で、細菌類が大部分を占めるのではない。","l":"法令外","c":""},{"id":"2022-59","s":2,"q":"エアロゾル粒子の一般的な粒径として、最も小さいものはどれか。","o":["噴霧液滴","硫酸ミスト","セメントダスト","フライアッシュ","たばこ煙"],"a":4,"e":"たばこ煙の粒子は0.01〜1μm程度と非常に小さい。噴霧液滴やセメントダスト、フライアッシュはそれより大きい。","l":"法令外","c":""},{"id":"2022-60","s":2,"q":"ダクト併用ファンコイルユニット方式について述べた次の文のうち、最も不適当なものはどれか。","o":["ファンコイルユニットを単一ダクト方式と組み合わせ、個別に制御しやすくしたシステムである。","ファンコイルユニットは、熱負荷が大きくなりやすいペリメータゾーンに置かれることが多い。","単一ダクト方式より、空調機や主ダクトを小さくできる。","ペリメータゾーンとインテリアゾーンの熱負荷の性質の違いに対応できる。","新鮮外気の確保は、ファンコイルユニットで行う。"],"a":4,"e":"ファンコイルユニットは室内の空気を循環させるだけで外気を取り入れる機能はない。新鮮外気は空調機からダクトで送る。","l":"法令外","c":""},{"id":"2022-61","s":2,"q":"建築物の熱負荷とその種類の組合せとして、最も適当なものはどれか。","o":["壁からの通過熱負荷 ― 顕熱負荷","人体による室内発熱負荷 ― 顕熱負荷","ガラス窓を通る日射熱負荷 ― 顕熱負荷と潜熱負荷","外気負荷 ― 顕熱負荷","照明による室内発熱負荷 ― 顕熱負荷と潜熱負荷"],"a":0,"e":"壁を通って伝わる熱は温度だけを変えるので顕熱負荷。人体と外気は顕熱と潜熱の両方、窓の日射と照明は顕熱だけである(2024年度問61・2025年度問60参照)。","l":"法令外","c":""},{"id":"2022-62","s":2,"q":"下に示す湿り空気線図上のア〜オは、加湿・除湿操作による状態変化を表している。各状態変化と加湿・除湿操作との組合せとして、最も不適当なものはどれか。","o":["ア ― 蒸気加湿","イ ― 気化式加湿","ウ ― 空気冷却器による冷却除湿","エ ― 液体吸収剤による化学的除湿","オ ― シリカゲルなどの固体吸着剤による除湿"],"a":0,"e":"蒸気加湿では絶対湿度が上がり、乾球温度はほとんど変わらないか少し上がる(ほぼ真上へ動く)。アは乾球温度が下がる向きに動いているので、蒸気加湿の変化ではない。イは湿球温度の線に沿って動く気化式加湿で正しい。","l":"法令外","c":"","g":["img/2022-62.png"]},{"id":"2022-63","s":2,"q":"個別方式の空気調和設備について述べた次の文のうち、最も不適当なものはどれか。","o":["水熱源ヒートポンプ方式のパッケージ型空調機は、圧縮機を内蔵しているので騒音源として注意が必要である。","分散設置型空気熱源ヒートポンプ方式には、電動ヒートポンプ(EHP)のほか、ガスエンジン駆動のヒートポンプ(GHP)がある。","ビル用マルチパッケージとは、1台の室外機に複数の室内機をつなぐタイプである。","ビル用マルチパッケージには、同じ室外機の系統でも室内機ごとに冷暖房を選べる冷暖房同時型がある。","空気熱源ヒートポンプは、冷房時にデフロスト運転(除霜運転)による効率低下が起きることがある。"],"a":4,"e":"室外機に霜が付いてデフロスト運転が必要になるのは、外気から熱をくみ取る暖房時である。冷房時ではない。","l":"法令外","c":""},{"id":"2022-64","s":2,"q":"乾球温度0℃・比エンタルピー4kJ/kg(DA)の外気と、乾球温度22℃・比エンタルピー39kJ/kg(DA)の室内空気を2:3の割合で混ぜた後の、乾球温度と比エンタルピーの組合せとして最も適当なものはどれか。","o":["8.8℃ ― 18kJ/kg(DA)","13.2℃ ― 25kJ/kg(DA)","8.8℃ ― 21kJ/kg(DA)","18.3℃ ― 21kJ/kg(DA)","13.2℃ ― 18kJ/kg(DA)"],"a":1,"e":"混合後の値は量の割合による加重平均。温度＝(2×0＋3×22)÷5＝13.2℃、比エンタルピー＝(2×4＋3×39)÷5＝125÷5＝25kJ/kg(DA)。","l":"計算","c":""},{"id":"2022-65","s":2,"q":"デシカント空調方式について述べた次の文のうち、最も不適当なものはどれか。","o":["除湿量は、再生空気の相対湿度の影響を大きく受ける。","放射冷暖房システムの結露対策としても使われる。","除湿のとき、デシカントロータを通る前後で外気の乾球温度は下がる。","2ロータ方式では、再生熱交換器は排気側に設置される。","潜熱と顕熱を分けて制御できる空調システムである。"],"a":2,"e":"デシカント(乾燥剤)が水蒸気を吸着すると吸着熱が出るため、ロータを通った外気の乾球温度は上がる。","l":"法令外","c":""},{"id":"2022-66","s":2,"q":"蒸気圧縮冷凍サイクルについて述べた次の文のうち、最も不適当なものはどれか。","o":["凝縮器で冷媒が液体になる。","圧縮機で冷媒の比エンタルピーが増える。","膨張弁で冷媒の圧力が下がる。","蒸発器で冷媒が気体になる。","冷凍サイクルでは、凝縮器→圧縮機→膨張弁→蒸発器の順に冷媒がめぐる。"],"a":4,"e":"冷媒がめぐる順番は、圧縮機→凝縮器→膨張弁→蒸発器である(2024年度問67でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-67","s":2,"q":"冷凍機の冷媒について述べた次の文のうち、最も不適当なものはどれか。","o":["CFC(クロロフルオロカーボン)は、オゾン層破壊の問題から全面的に製造禁止となった。","HCFC(ハイドロクロロフルオロカーボン)はオゾン破壊係数(ODP)は小さいが、全廃に向けて生産量が段階的に減らされている。","HFC(ハイドロフルオロカーボン)は、オゾン破壊係数(ODP)が1である。","HFC(ハイドロフルオロカーボン)は温室効果ガスに指定され、使用量の制限が課されている。","自然冷媒のアンモニアは、地球温暖化係数(GWP)が1より小さい。"],"a":2,"e":"HFCは塩素を含まないので、オゾン破壊係数は0である(2023年度問66参照)。ODPが1なのはCFC(R11)。","l":"法令外","c":""},{"id":"2022-68","s":2,"q":"空気調和設備の熱源方式の特徴について述べた次の文のうち、最も不適当なものはどれか。","o":["コージェネレーション方式は、電力需要を中心に運転すると、最も高いエネルギー利用効率が得られる。","ガスエンジンヒートポンプ方式は、エンジンの排熱を活用できるので、寒冷地の暖房熱源に向いている。","蓄熱システムは、電力負荷の平準化や熱源装置の容量削減に効果がある。","水熱源方式のヒートポンプは、地下水や下水熱などの未利用エネルギーの活用に向いている。","地域冷暖房システムには、地域で熱源をまとめ、集中して管理できるメリットがある。"],"a":0,"e":"コージェネレーションは発電時の排熱を使い切ることで効率が上がるので、熱需要に合わせて運転するときに効率が最も高くなる。電力需要中心の運転では排熱が余りやすい。","l":"法令外","c":""},{"id":"2022-69","s":2,"q":"密閉型冷却塔についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「密閉型冷却塔は、水と空気が[ア]熱交換となるため、通風抵抗と送風機動力が[イ]する。また、散布水系統の保有水量は開放型冷却塔と比べて[ウ]。」","o":["ア 間接/イ 増加/ウ 多い","ア 間接/イ 減少/ウ 少ない","ア 直接/イ 減少/ウ 多い","ア 直接/イ 増加/ウ 少ない","ア 間接/イ 増加/ウ 少ない"],"a":4,"e":"密閉型は冷却水をコイルの中に通して間接的に冷やすので、通風抵抗と送風機動力が大きくなる。散布水系統の保有水量は少ない(2025年度問70でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-70","s":2,"q":"空気調和機と、それを構成する機器の組合せとして、最も不適当なものはどれか。","o":["エアハンドリングユニット ― 加湿器","ファンコイルユニット ― 凝縮器","パッケージ型空調機 ― 圧縮機","エアハンドリングユニット ― エアフィルタ","ファンコイルユニット ― 熱交換器"],"a":1,"e":"ファンコイルユニットは送風機・熱交換器(コイル)・エアフィルタなどでできており、冷凍サイクルの凝縮器はもたない(2023年度問70参照)。","l":"法令外","c":""},{"id":"2022-71","s":2,"q":"空気調和設備の熱交換器について述べた次の文のうち、最も不適当なものはどれか。","o":["回転型全熱交換器は、仕切り板の熱を伝える性質と湿気を通す性質によって、給気と排気の間で全熱交換を行う。","空気-空気熱交換器は、おもに外気負荷を減らすために使う。","代表的な空気冷却用の熱交換器に、プレートフィン型冷却コイルがある。","ヒートパイプは、構造や原理が単純で、熱を運ぶ能力の高い熱交換器である。","プレート式水-水熱交換器は、コンパクトで簡単に分解して洗えるのが特徴である。"],"a":0,"e":"仕切り板で全熱交換を行うのは静止型(2025年度問71参照)。回転型は、吸湿性のあるロータが回転して給気側と排気側を行き来することで熱と湿気を移す。","l":"法令外","c":""},{"id":"2022-72","s":2,"q":"加湿装置について述べた次の文のうち、最も不適当なものはどれか。","o":["滴下式では、吹出し空気の温度が下がる。","蒸気式では、吹出し空気の温度が下がらない。","超音波式では、給水中の不純物が放出される。","透湿膜式では、給水中の不純物は放出されない。","電極式は、純水で加湿する。"],"a":4,"e":"電極式は水に電流を流して発熱させる方式で、電気を通す不純物を含む水道水などを使う。電気を通しにくい純水では使えない。","l":"法令外","c":""},{"id":"2022-73","s":2,"q":"吹出口について述べた次の文のうち、最も適当なものはどれか。","o":["ふく流吹出口は、ほかの吹出口より誘引効果が高く、温度差や風量が大きくても居住域にコールドドラフトが起きにくい。","軸流吹出口の気流は、広がる角度が大きく、到達距離が短い。","線状吹出口は、おもにインテリアゾーンの熱負荷を処理するために設置されることが多い。","面状吹出口には、放射冷暖房の効果が期待できない。","線状吹出口は、吹出しの向きを調整できない。"],"a":0,"e":"ふく流吹出口は周囲の空気をよく誘引して混ぜるため、コールドドラフトが起きにくい。軸流吹出口は到達距離が長く、線状吹出口はペリメータ用、面状吹出口には放射効果がある(2025年度問73参照)。","l":"法令外","c":""},{"id":"2022-74","s":2,"q":"送風機の運転点についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「送風機の特性曲線は、横軸に[ア]、縦軸に[イ]をとって表す。送風系の抵抗曲線は、同じグラフ上で原点を通る二次曲線として表され、2つの曲線の交点が運転点になる。送風系の[ウ]を操作すると抵抗曲線が変わり、運転点が移る。」","o":["ア 圧力/イ 回転数/ウ インバータ","ア 風量/イ 圧力/ウ インバータ","ア 圧力/イ 風量/ウ インバータ","ア 風量/イ 圧力/ウ ダンパ","ア 圧力/イ 風量/ウ ダンパ"],"a":3,"e":"特性曲線は横軸に風量、縦軸に圧力をとる。ダンパの開き具合を変えるとダクト系の抵抗が変わり、抵抗曲線そのものが変わる。インバータは送風機の回転数を変えるので、変わるのは送風機の特性曲線の方である。","l":"法令外","c":""},{"id":"2022-75","s":2,"q":"空気浄化装置について述べた次の文のうち、最も不適当なものはどれか。","o":["自動巻取型エアフィルタは、ろ材の更新を自動で行える構造である。","ULPAフィルタは、定格風量で粒径0.3μmの粒子をとらえる率で規定されている。","ろ過式フィルタの捕集原理には、さえぎりによる付着、慣性衝突、拡散による付着がある。","ガス除去用エアフィルタのガス除去容量は、除去率が初期値の85%に下がるまでにとらえたガスの質量で表す。","パネル型エアフィルタは、外気用やプレフィルタとして使われる。"],"a":1,"e":"粒径0.3μmの粒子の捕集率で規定されるのはHEPAフィルタ。ULPAフィルタはさらに小さい0.15μmの粒子で規定される。","l":"法令外","c":""},{"id":"2022-76","s":2,"q":"空気調和設備の配管の種類と、使う温度または圧力の組合せとして、最も不適当なものはどれか。","o":["冷却水配管 ― 20〜40℃","高温水配管 ― 80〜90℃","冷水配管 ― 5〜10℃","低圧蒸気配管 ― 0.01〜0.05MPa","高圧蒸気配管 ― 0.1〜1MPa"],"a":1,"e":"80〜90℃程度は温水の範囲。高温水は100℃を超える温度(120℃以上など)の水を指す。","l":"法令外","c":""},{"id":"2022-77","s":2,"q":"空気調和設備の配管とポンプに関する語句の組合せとして、最も不適当なものはどれか。","o":["伸縮継手 ― 温度変化による配管応力の吸収","キャビテーション ― 吐出し量の低下","サージング ― 有効吸込みヘッド(NPSH)","配管系の抵抗曲線 ― 全揚程","水撃作用 ― 衝撃音の発生"],"a":2,"e":"有効吸込みヘッド(NPSH)は、キャビテーションが起きないかを確かめるための指標である。サージングは揚程曲線が右上がりの部分で運転すると起きる圧力・流量の脈動。","l":"法令外","c":""},{"id":"2022-78","s":2,"q":"汚染物質と、その濃度または強さを表す単位の組合せとして、最も不適当なものはどれか。","o":["二酸化窒素 ― ppb","ダニアレルゲン ― ng/m³","浮遊真菌 ― CFU/m³","臭気 ― cpm","エチルベンゼン ― μg/m³"],"a":3,"e":"cpm(1分あたりのカウント数)は、粉じん計などの計数の単位。臭気の強さは臭気指数や臭気濃度などで表す。","l":"法令外","c":""},{"id":"2022-79","s":2,"q":"浮遊粉じんの測定についての次の文の[(1)]〜[(5)]の語句のうち、最も不適当なものはどれか。\n「建築物衛生法の測定対象となる浮遊粉じん濃度は、粉じんの[(1)]を考えずに、[(2)]がおおむね[(3)]を対象として、[(4)]以下と定められている。標準となる測定法は[(5)]である。」","o":["化学的組成","幾何相当径","10μm以下の粒子状物質","0.15mg/m³","重量法(質量濃度測定法)"],"a":1,"e":"対象は「相対沈降径」がおおむね10μm以下の浮遊粉じん(施行規則第3条の2)。基準値0.15mg/m³は施行令第2条のとおり。","l":"建築物衛生法施行令 第2条、施行規則 第3条の2","c":""},{"id":"2022-80","s":2,"q":"環境要素と測定に使うものの組合せとして、最も不適当なものはどれか。","o":["温度 ― 熱電対","臭気 ― オルファクトメータ法","熱放射 ― シンチレーションカウンタ","酸素 ― ガルバニ電池","気流 ― サーミスタ"],"a":2,"e":"シンチレーションカウンタは放射線(ラドンなど)の測定器(2024年度問78参照)。熱放射はグローブ温度計などで測る。","l":"法令外","c":""},{"id":"2022-81","s":2,"q":"空気調和・換気設備の維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["異常の兆候はそれ自体を測るのが難しいので、振動などの値から推定する。","予防保全とは、故障が起きたときに、ほかの部分への影響を防ぐため、その部分をすぐに修復する方法である。","熱源設備は重要機器として、点検レベルを高く設定する。","点検業務は、法定点検業務と、設備の機能を保つために行う任意点検業務に分けられる。","空気調和・換気設備をリニューアルするまでの使用期間は、20〜30年となる場合が多い。"],"a":1,"e":"予防保全は、故障が起きる前に計画的に点検・修理・交換して故障を防ぐ方法。故障してから直すのは事後保全である(2025年度問81参照)。","l":"法令外","c":""},{"id":"2022-82","s":2,"q":"空気調和・換気設備の維持管理上の問題と、考えられる原因の組合せとして、最も不適当なものはどれか。","o":["冷却水系統のスケール発生 ― 冷却水の過剰な濃縮","全熱交換器の効率低下 ― 熱交換エレメントの目詰まり","冬の暖房時の室内相対湿度の低下 ― 高い室内温度設定","夏の冷房時の室内温度の上昇 ― 外気量の低下","室内空気質の低下 ― ダクト内部の汚れ"],"a":3,"e":"夏の外気は暑いので、外気量が減ると冷房の負担はむしろ軽くなる。室温が上がる原因として考えられるのは外気量の増えすぎなどである。","l":"法令外","c":""},{"id":"2022-83","s":2,"q":"音と振動の用語と定義の組合せとして、最も不適当なものはどれか。","o":["暗騒音 ― ある騒音環境で、対象とする特定の音以外の音の総称","吸音 ― 壁などで音をさえぎり、通り抜ける音のエネルギーを小さくすること","騒音レベル ― 人の聴覚の周波数特性で補正した、騒音の大きさの尺度","音の強さ ― 音の進む方向に垂直な単位面積を、単位時間に通り抜ける音のエネルギー","時間率レベル ― あるレベル以上の振動にさらされる時間が、観測時間に占める割合"],"a":1,"e":"壁などで音をさえぎり、通り抜ける音のエネルギーを小さくすることは「遮音」の定義(2025年度問83参照)。吸音は、音を吸収して反射を減らすことである。","l":"法令外","c":""},{"id":"2022-84","s":2,"q":"振動と遮音について述べた次の文のうち、最も不適当なものはどれか。","o":["固体伝搬音の問題には振動がかかわっている。","振動が正弦波のとき、振動加速度の実効値は、加速度の最大振幅の1/√2で求められる。","コインシデンス効果が起きると、壁の透過損失は小さくなる。","建物の中で感じる道路交通による振動は、不規則で変動も大きい。","空気調和設備による振動は、間欠的で周期性のない形で起きる。"],"a":4,"e":"空気調和設備の送風機やポンプなどは連続して回転しているので、その振動は連続的・周期的に起きる。","l":"法令外","c":""},{"id":"2022-85","s":2,"q":"音圧レベル80dBの音源室と、面積10m²・音響透過損失20dBの隔壁で仕切られた受音室(等価吸音面積20m²)の平均音圧レベルに最も近いものはどれか。\nただし L1－L2＝TL＋10log10(A2/Sw)(L1・L2:音源室・受音室の平均音圧レベル[dB]、A2:受音室の等価吸音面積[m²]、Sw:隔壁の面積[m²]、TL:音響透過損失[dB])。log10 2＝0.3010、log10 3＝0.4771とする。","o":["50dB","54dB","57dB","60dB","63dB"],"a":2,"e":"80－L2＝20＋10log10(20/10)＝20＋3.01＝23.01。L2＝80－23.01≒57dB。","l":"計算","c":""},{"id":"2022-86","s":2,"q":"床衝撃音についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「軽量床衝撃音は、[ア]ときに発生し、[イ]におもな成分を含む。対策としては[ウ]が効果的である。」","o":["ア 人が床の上で飛び跳ねたりした/イ 高周波数域/ウ 柔らかい床仕上げ材","ア 人が床の上で飛び跳ねたりした/イ 低周波数域/ウ 柔らかい床仕上げ材","ア 食器を落とした/イ 高周波数域/ウ 床躯体構造の質量を増やすこと","ア 食器を落とした/イ 高周波数域/ウ 柔らかい床仕上げ材","ア 食器を落とした/イ 低周波数域/ウ 床躯体構造の質量を増やすこと"],"a":3,"e":"軽量床衝撃音は食器を落とすなど軽く硬いものの衝撃で起き、高い周波数が中心。柔らかい床仕上げ材が効果的である(2024年度問84参照)。","l":"法令外","c":""},{"id":"2022-87","s":2,"q":"音・振動環境の保守管理について述べた次の文のうち、最も不適当なものはどれか。","o":["複数の材料を貼り合わせた内装の振動は、部位による振動モードの影響で、測る場所によって違うことがある。","騒音・振動を測るときは、暗騒音・暗振動が大きい時間帯に行うのが望ましい。","年数による遮音性能の低下をつかむため、建設時に壁・床・建具などの遮音性能を測っておくのが望ましい。","機械室に隣接する居室の床スラブが薄かったので、固体伝搬音が伝わらないよう空調機を防振支持した。","遮音性能の高い扉でも、毎日の開け閉めで遮音性能が下がることがある。"],"a":1,"e":"暗騒音・暗振動が大きいと対象の音や振動が正しく測れないので、それらが小さい時間帯に測る(2025年度問86でも「大きい時間帯を避ける」が正しい記述)。","l":"法令外","c":""},{"id":"2022-88","s":2,"q":"光と照明の用語と定義の組合せとして、最も不適当なものはどれか。","o":["照度 ― 単位立体角あたりに入ってくる光束","輝度 ― 見る方向から見た、見かけの面積あたりの光度","演色性 ― 基準の光で照らしたときの色を、どれだけ忠実に再現するかを判定する指標","保守率 ― ある期間使った後の作業面の平均照度と、初期の平均照度の比","色温度 ― 黒体(完全放射体)を熱したときの絶対温度と光の色の関係をもとに、数値で表した光の色"],"a":0,"e":"照度は、単位面積あたりに入ってくる光束(lx＝lm/m²)。単位立体角あたりの光束は光度(cd)である。","l":"法令外","c":""},{"id":"2022-89","s":2,"q":"光と照明について述べた次の文のうち、最も不適当なものはどれか。","o":["光が当たった物体の境界面が滑らかな場合、光は正反射して光沢となる。","建築化照明とは、照明器具を建築物の一部として天井や壁などに組み込んだ照明方式である。","間接昼光率は、室内の反射率の影響を受ける。","点光源からの光による照度は、光源からの距離に反比例する。","見る人から見た照明器具の発光部の立体角が大きいほど、不快グレアの程度を表すUGRの値は大きくなる。"],"a":3,"e":"点光源による照度は、距離の2乗に反比例する(逆二乗の法則。2024年度問89の計算参照)。","l":"法令外","c":""},{"id":"2022-90","s":2,"q":"地表で直射日光による法線面照度が100,000lxのとき、直射日光による水平面照度に最も近いものはどれか。ただし太陽高度は60度とする。","o":["35,000lx","43,000lx","50,000lx","65,000lx","87,000lx"],"a":4,"e":"水平面照度＝法線面照度×sin(太陽高度)＝100,000×sin60°＝100,000×0.866≒87,000lx。","l":"計算","c":""},{"id":"2022-91","s":3,"q":"建築物と環境に関する用語の組合せとして、最も関係が少ないものはどれか。","o":["フレキシビリティ ― 間仕切りの変更","サスティナブル・ディベロップメント ― 持続可能な開発","屋上緑化 ― 市街地風","メタン ― 温室効果ガス","コージェネレーション ― 排熱の有効利用"],"a":2,"e":"屋上緑化は、ヒートアイランド現象の緩和や断熱などに関係する用語で、市街地風(ビル風)とは関係が少ない。","l":"法令外","c":""},{"id":"2022-92","s":3,"q":"建築物と都市環境について、最も不適当なものはどれか。","o":["高層建築物の周りでは、局地的に強い風が起こることがある。","一般的なアスファルト舗装の面は、土の面より熱容量が大きく、日射の熱をためこみやすい。","地盤沈下は、環境基本法で公害と定義される典型7公害の一つである。","都市化によって都市の中心部の気温が郊外より高くなる現象を、ダウンドラフトという。","無計画な開発などで市街地が広がることを、スプロール現象という。"],"a":3,"e":"都市の中心部の気温が郊外より高くなる現象はヒートアイランド現象である。ダウンドラフトは、高層ビルにぶつかった風が下に吹き降りる現象。","l":"法令外","c":""},{"id":"2022-93","s":3,"q":"建築物の設計図書(意匠図面)について、最も不適当なものはどれか。","o":["配置図は、建物と敷地の関係を示す図で、外構の計画もあわせて示すことがある。","平面図は、部屋の配置を平面的に示す図で、家具や棚なども書きこむことがある。","立面図は、建物の外観を示すものである。","展開図は、建物の中の雰囲気や空間の構成を立体的に示すものである。","詳細図は、出入口・窓・階段・便所など主な部分の平面や断面などの納まりを示すものである。"],"a":3,"e":"展開図は、部屋の中から見た各壁面を、展開して立面のように示した図である。雰囲気や空間を立体的に示すのは透視図(パース)。","l":"法令外","c":""},{"id":"2022-94","s":3,"q":"建築物の荷重と構造力学について、最も不適当なものはどれか。","o":["基礎の構造計算に使う積載荷重は、床の構造計算に使う積載荷重より大きく決められている。","家具や物品などの重さは、積載荷重に含まれる。","片持ち梁のスパンの中央に集中荷重がかかる場合、先端には曲げモーメントは生じない。","トラス構造の部材に生じる応力は、主に軸方向力である。","水平荷重には、風圧力や地震力などがある。"],"a":0,"e":"積載荷重は、床の構造計算用が最も大きく、大ばり・柱・基礎の構造計算用はそれより小さく決められている(すべての床が同時に満載になることは少ないため)。","l":"建築基準法施行令 第85条","c":""},{"id":"2022-95","s":3,"q":"建築物とその構造について、最も不適当なものはどれか。","o":["木造住宅の法定耐用年数は、22年である。","剛性率は、骨組の上下方向(立面的)のバランスを表す指標である。","制振構造は、建物を長持ちさせ、耐久性を高めることに役立つ。","耐震改修には、地震への安全性を高めるための模様替も含まれる。","層間変形角は、各階の高さを、その層の層間変位で割った値である。"],"a":4,"e":"層間変形角は、層間変位を各階の高さで割った値である(割る数と割られる数が逆)。","l":"法令外","c":""},{"id":"2022-96","s":3,"q":"鉄骨構造とその材料について、最も不適当なものはどれか。","o":["鋼材の降伏比とは、降伏強さに対する引張強さの割合をいう。","柱脚と基礎は、支える条件によって、ピン・半固定・固定などを選んで設計する。","スタッドボルトは、鉄骨の梁とコンクリートのスラブをしっかりつなぐために使う。","鉄骨構造の解体は、一般の鉄筋コンクリート構造より簡単である。","高力ボルトの締付け長さとは、つなぎ合わせる鋼板の板厚の合計をいう。"],"a":0,"e":"降伏比は、引張強さに対する降伏強さの割合(降伏強さ÷引張強さ)である。","l":"法令外","c":""},{"id":"2022-97","s":3,"q":"仕上げ材料について、最も不適当なものはどれか。","o":["合成高分子材料は、合成樹脂・合成ゴム・合成繊維に大きく分けられる。","断熱材のグラスウールは、熱伝導率の高い空気の性質を利用している。","しっくいは、消石灰にのり・すさ・水を加えて練った左官材料である。","アスファルトルーフィングは、合成繊維などの原板にアスファルトをしみこませ、覆った材料である。","せっこうボードは、火に強いが、水分や湿気に弱い。"],"a":1,"e":"グラスウールは、熱伝導率の低い(熱を伝えにくい)空気を繊維の間に閉じこめて断熱している。","l":"法令外","c":""},{"id":"2022-98","s":3,"q":"建築生産について、最も不適当なものはどれか。","o":["プレハブ工法は、工場でつくった部材を現場に運んで組み立てる工法である。","建築基準法の設計図書には、設計図と仕様書が含まれる。","軸組式構法は、木材や鋼材などの軸材で柱や梁などを組み、そこに面材を取り付けたものをいう。","施工管理は、設計図書のとおりに工事が行われているかを設計者が確かめることで、建築士法に定義されている。","型枠工事は、躯体工事に含まれる。"],"a":3,"e":"設計図書と照らして工事を確かめ、建築士法に定義されているのは「工事監理」である。施工管理は、施工者が工程・品質・安全などを管理すること。","l":"建築士法 第2条第8項","c":""},{"id":"2022-99","s":3,"q":"エレベーター設備について、最も不適当なものはどれか。","o":["小荷物専用昇降機は、荷物運搬専用の小規模なリフトの総称である。","ロープ式エレベーターは用途が広く、中高層・超高層の建物で多く使われている。","非常用エレベーターの設置義務は、消防法で定められている。","新築の建物では、機械室のないエレベーターが広まっている。","エレベーターの安全装置には、制動装置がある。"],"a":2,"e":"非常用エレベーター(非常用の昇降機)の設置義務は、建築基準法で定められている(高さ31mを超える建築物)。","l":"建築基準法 第34条第2項","c":""},{"id":"2022-100","s":3,"q":"空気調和設備の用語と図示記号の組合せとして、最も不適当なものはどれか。下の図の記号は、上から順に(1)〜(5)の選択肢に対応している。","o":["VAVユニット ― (1)の記号","排気ガラリ ― (2)の記号","風量調節ダンパ ― (3)の記号(VD)","還気ダクト ― (4)の記号(RA)","吸込口 ― (5)の記号"],"a":1,"e":"この組合せが不適当(公式の正答)。(2)の斜線を引いた長方形の記号を排気ガラリとする組合せは誤りとされている。VDは風量調節ダンパ、RAは還気ダクト(リターンエア)を表す。","l":"法令外","c":"","g":["img/2022-100.png"]},{"id":"2022-101","s":3,"q":"消火設備と設置場所の組合せとして、最も不適当なものはどれか。","o":["不活性ガス消火設備 ― 事務室","連結散水設備 ― 地下街","泡消火設備 ― 地下駐車場","水道連結型スプリンクラー設備 ― 小規模社会福祉施設","ハロゲン化物消火設備 ― 通信機器室"],"a":0,"e":"不活性ガス消火設備は酸素濃度を下げて消火するため、人がいつもいる事務室には適さない。通信機器室や電気室など、水で消火できない場所に使う。","l":"法令外","c":""},{"id":"2022-102","s":3,"q":"地震対策について、最も不適当なものはどれか。","o":["ガス用マイコンメータは、地震のときに自動でガスを止めるガスメータである。","気象庁震度階級は、地震の揺れの強さを示す指標である。","大規模な事業所では、地震被害を減らすため、防火管理者の選任が義務づけられている。","感震ブレーカは、地震のときに自動で電気を止めるブレーカである。","Jアラートは、緊急の気象関係情報や有事関係情報を、国から住民などへ伝えるシステムである。"],"a":2,"e":"大規模な事業所で地震などの被害を減らすために選任が義務づけられているのは、防災管理者である。","l":"消防法 第36条","c":""},{"id":"2022-103","s":3,"q":"建築基準法の建築物の高さ制限として、定められていないものはどれか。","o":["道路からの高さ制限","隣地境界からの高さ制限","北側からの高さ制限","日影による中高層建築物の高さ制限","相対高さ制限"],"a":4,"e":"建築基準法には、道路斜線・隣地斜線・北側斜線制限や日影規制はあるが、「相対高さ制限」という規定はない。","l":"建築基準法 第56条、第56条の2","c":""},{"id":"2022-105","s":3,"q":"建築物の管理について、最も不適当なものはどれか。","o":["エネルギー管理で、日報・月報などで使用状況を「見える化」することは、PDCAサイクルを回すために必要な機能である。","ファシリティマネジメントとは、企業・団体などが活動のために施設とその環境を総合的に企画・管理・活用する経営活動のことである。","設備のライフサイクルとは、JISの生産管理用語で「設備の製作、運用、保全」と定義されている。","COP(成績係数)は、入力したエネルギーに対して出てきた熱量の割合で、1を超えることがある。","インターロックとは、誤操作や確認不足による間違った手順の操作を防ぐ機能のことである。"],"a":2,"e":"JISでは、設備のライフサイクルを、計画・設計・製作・運用・保全をへて廃棄・再利用までを含むすべての段階としており、「製作・運用・保全」だけではない。","l":"法令外(JIS Z 8141)","c":""},{"id":"2022-106","s":4,"q":"給水・排水の管理で使う用語と、その単位の組合せとして、最も不適当なものはどれか。","o":["水の比体積 ― kg/m³","給湯器の加熱能力 ― kW","BOD容積負荷 ― kg/(m³・日)","腐食速度 ― mm/年","病院の単位給水量 ― L/(床・日)"],"a":0,"e":"比体積は密度(kg/m³)の逆数で、単位質量あたりの体積なので、単位は m³/kg になる。kg/m³は密度の単位(2024年問106で「水の密度 ― kg/m³」が正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2022-108","s":4,"q":"給水・排水の管理に関する用語と説明の組合せとして、最も不適当なものはどれか。","o":["メカニカル形接合 ― ねじ込み・溶接・接着などによらない、機械的に配管をつなぐ方法","スライム障害 ― 貯水槽や配管の中で細菌類が増え、バイオフィルムができて水質が悪くなる現象","逆サイホン作用 ― 排水管内の正圧によって、器具側に封水が吹き出す現象","ウォータハンマ ― 弁などを急に閉めると大きな圧力上昇が起こり、それが圧力波として管路を伝わる現象","クリープ劣化 ― 合成樹脂に力が長時間かかり続けると、材料の変形が時間とともに進む状態"],"a":2,"e":"逆サイホン作用とは、給水管内に生じた負圧で、水受け容器にいったん出た水が給水管内に逆流することである(2025年問116で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-109","s":4,"q":"水道法の水質基準に関する省令で定める基準として、誤っているものはどれか。","o":["大腸菌は、検出されないこと。","銅及びその化合物は、銅の量として1.0mg/L以下であること。","総トリハロメタンは、0.5mg/L以下であること。","ホルムアルデヒドは、0.08mg/L以下であること。","pH値は、5.8以上8.6以下であること。"],"a":2,"e":"総トリハロメタンの基準は0.1mg/L以下である(水質基準に関する省令)。ほかの4つは現行の基準どおり。","l":"水質基準に関する省令(表)","c":""},{"id":"2022-110","s":4,"q":"水道水の塩素消毒に関する記述として、最も不適当なものはどれか。","o":["CT値とは、塩素濃度と接触時間をかけたものである。","反応の速さは、温度が高いほど速くなる。","消毒効果がどれだけ落ちるかは、にごりの成分の種類・大きさ・濃度や、微生物の種類などで変わる。","刺激臭があるので、異臭味が生じる。","アルカリ側(pHが高い側)で消毒効果が高まる。"],"a":4,"e":"塩素消毒はアルカリ側で効果が急に下がる(2024年問109で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-111","s":4,"q":"給水設備の汚染に関する記述として、最も不適当なものはどれか。","o":["飲料水用の貯水槽は、6面から点検できるように設置する。","貯水槽の水抜き管は、槽のいちばん低い部分から取り出す。","給水配管から消火設備の配管系統へ給水するときは、吐水口空間を確保した消火用水槽を設ける。","大気圧式バキュームブレーカは、常に圧力がかかる配管部分に設ける。","容量の大きい貯水槽では、槽の中に迂回壁を設けて、水がよどむのを防ぐ。"],"a":3,"e":"大気圧式バキュームブレーカは、常に圧力がかかる配管部分には設けない。","l":"法令外","c":""},{"id":"2022-112","s":4,"q":"給水方式に関する記述として、最も不適当なものはどれか。","o":["高置水槽方式では、受水槽の水位によって揚水ポンプが起動・停止する。","直結増圧方式の吸排気弁は、給水管内の空気を出すことと、管内が負圧になったときの逆流を防ぐために設ける。","ポンプ直送方式で使われるインバータ制御は、周波数を変えてポンプの回転数を変えている。","給水方式は、水道直結方式と受水槽方式に大きく分けられる。","直結直圧方式では、配水管の圧力で、各給水箇所へ直接給水する。"],"a":0,"e":"高置水槽方式の揚水ポンプは、高置水槽の水位によって起動・停止させる(2024年問114で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-113","s":4,"q":"給水設備の貯水槽に関する記述として、最も不適当なものはどれか。","o":["FRP製の高置水槽は、槽内の照度が100lx以上になると、光合成で藻類が増えやすい。","木製の貯水槽は断熱性に優れているので、結露対策がいらない。","ステンレス鋼板製の貯水槽は、気相部(水面より上)よりも液相部(水の中)の腐食対策が必要である。","FRP製の貯水槽は機械的強度が低いので、耐震補強が必要である。","鋼板製の貯水槽には、一体成型した槽にエポキシ樹脂を焼き付けてコーティングしたものがある。"],"a":2,"e":"ステンレス鋼板製の貯水槽で腐食対策が必要なのは気相部である(2025年問111で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-114","s":4,"q":"受水槽の構造に関する記述として、最も不適当なものはどれか。","o":["流入管は、受水槽の中で水に沈めず、吐水口空間を確保する。","オーバフロー管に付ける防虫網の有効開口面積は、オーバフロー管の断面積以上にする。","水抜き管は、オーバフロー管につながず、単独の配管にする。","オーバフローした水を受ける排水管の管径は、オーバフロー管より大きくする。","水抜き管の管の先には、防虫網を付ける。"],"a":4,"e":"(5)の記述が誤り。","l":"法令外","c":""},{"id":"2022-115","s":4,"q":"給水設備で使う弁の説明として、最も不適当なものはどれか。","o":["仕切弁 ― 弁体が管路を垂直に仕切るようにして開け閉めする構造","バタフライ弁 ― 円板状の弁体を回して管路を開け閉めする構造","減圧弁 ― ダイヤフラムと調節ばねのつり合いで弁体の開き具合を調整する仕組み","定水位弁 ― 副弁の開閉に合わせて弁体を開閉し、水槽の水位を保つ仕組み","玉形弁 ― 穴の開いた弁体を回して開け閉めする構造"],"a":4,"e":"玉形弁は、弁体と弁座のすき間を変えて流量を調節するものである(2017年問77で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-116","s":4,"q":"給水設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["貯水槽の清掃で出た汚泥などの廃棄物は、廃棄物処理法や下水道法などの決まりに従って適切に処理する。","防錆剤の注入と管理の業務は、建築物衛生法の建築物飲料水水質検査業の登録を受けた者が行わなければならない。","管更生工法で管の内側に合成樹脂ライニングをする場合は、技術評価・審査証明を受けた工法を選ぶのがよい。","残留塩素は、一般にDPDを発色試薬とする方法で測る。","配管は、損傷・さび・腐食・水漏れがないか点検し、必要に応じて補修する。"],"a":1,"e":"防錆剤の注入・管理を飲料水水質検査業の登録業者が行わなければならない、という決まりはない(2016年問115・2024年問117でも誤りとして出題)。なお(1)は告示第119号 第2の一の1(五)の定めどおり。","l":"平成15年厚生労働省告示第119号 第2(選択肢1)","c":""},{"id":"2022-117","s":4,"q":"給水設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["飲料用貯水槽の点検は、1か月に1回程度、定期に行う。","第二種圧力容器にあたる圧力水槽は、2年以内ごとに1回、定期自主検査を行う。","飲料用貯水槽の清掃作業をする人は、おおむね6か月ごとに健康診断を受ける必要がある。","防錆剤を使う場合は、ふだんは2か月以内ごとに1回、防錆剤の濃度を検査する。","給水栓での残留塩素の測定は、7日以内ごとに1回、定期に行う。"],"a":1,"e":"第二種圧力容器の定期自主検査は1年以内ごとに1回である(ボイラー及び圧力容器安全規則第88条)。給水栓の残留塩素の検査が7日以内ごとに1回であることは施行規則第4条第1項第7号に定めがある。","l":"ボイラー及び圧力容器安全規則 第88条、建築物衛生法施行規則 第4条第1項第7号(選択肢5)","c":""},{"id":"2022-118","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["貯湯槽の容量は、ピーク時に必要な量の1〜2時間分を目安にする。","集合住宅の設計用給湯量は、100L/(戸・日)程度である。","壁掛けシャワーの使用温度は、42℃程度である。","中央式給湯設備の給湯栓の温度は、ピーク時でも55℃以上にする。","ステンレス鋼管に単式の伸縮継手を使う場合、設置間隔は20m程度である。"],"a":1,"e":"集合住宅の設計用給湯量を100L/(戸・日)程度とした記述が誤り。","l":"法令外","c":""},{"id":"2022-119","s":4,"q":"給湯設備の加熱装置と、その説明の組合せとして、最も不適当なものはどれか。","o":["ガスマルチ式給湯機 ― 小型のガス瞬間湯沸器を何台もつないだもので、主に業務用に使われる。","汽水混合装置 ― タンクの中に入れ、蒸気を直接水に吹き込んで温水をつくる装置。","貯蔵式湯沸器 ― 貯める部分が大気に開放されていて、本体の給湯栓から飲用に向く高温の湯が出る。","ヒートポンプ給湯機 ― 一体型の集熱器と貯湯槽でできていて、その間で水を自然に循環させて温める。","給湯用貫流ボイラ ― 温水を取り出す小型ボイラで、水管群でできていて耐圧性に優れる。"],"a":3,"e":"集熱器と貯湯槽が一体になったものは太陽熱利用温水器の説明である(2021年問122で「太陽熱利用温水器には集熱器と貯湯槽が一体のものがある」が正しい記述として出題)。ヒートポンプ給湯機の説明ではない。","l":"法令外","c":""},{"id":"2022-120","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["配管内の湯に溶けている空気を抜くため、圧力の低い場所に自動空気抜き弁を設ける。","加熱装置に逃し管を設ける場合は、水を供給する高置水槽の水面よりも高く立ち上げる。","密閉式膨張水槽を設ける場合は、逃し弁の設定圧力を、膨張水槽にかかる給水圧力よりも低くする。","逃し管には、弁を設けてはならない。","循環ポンプの揚程は、循環回路で最も長くなる配管系統の摩擦損失から決める。"],"a":2,"e":"逃し弁の設定圧力を給水圧力より低くするとした記述が誤り。給水圧力より低いと、ふだんから逃し弁が開いてしまう。","l":"法令外","c":""},{"id":"2022-121","s":4,"q":"給湯設備の省エネルギーに関する記述として、最も不適当なものはどれか。","o":["中央式給湯設備の循環ポンプは、省エネルギーのため、返湯管の温度が下がったときに運転する。","器具ごとに定流量弁を付ける。","適切な給湯設備の制御方式を選ぶ。","混合水栓を使わず、湯と水は別々の水栓にする。","配管経路を短くしたり配管を断熱したりして、熱が逃げにくい配管にする。"],"a":3,"e":"エネルギーと水を節約するには、湯と水を別々の水栓から出さず、混合水栓を使う(2023年問117・2025年問119で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-122","s":4,"q":"給湯設備に使う材料に関する記述として、最も不適当なものはどれか。","o":["ステンレス鋼管のすき間腐食は、不動態化によって起こる。","金属材料を曲げ加工すると、応力腐食の原因になる。","銅管は、管内の流速が速いと潰食が起こる。","耐熱性硬質ポリ塩化ビニルライニング鋼管には、管端防食継手を使う。","樹脂管は、使う温度が高くなると、使ってよい圧力(許容使用圧力)が低くなる。"],"a":0,"e":"ステンレス鋼管が腐食に強いのは、酸化被膜による不動態化のためである(2024年問113で正しい記述として出題)。すき間腐食の原因を不動態化とするのは誤り。","l":"法令外","c":""},{"id":"2022-123","s":4,"q":"給湯設備の配管に関する記述として、最も不適当なものはどれか。","o":["業務用厨房のように連続して湯を使う給湯枝管には、返湯管を設けない。","ベローズ形の伸縮管継手は、スリーブ形と比べて伸縮を吸収できる量が大きい。","湯を均等に循環させるため、返湯の量を調節する必要がある。","給湯管の管径は、ピーク時の湯の流量をもとに決める。","逃し弁には、加熱で膨らんだ湯を逃がすための排水管を設ける。"],"a":1,"e":"伸縮を吸収できる量は、スリーブ形のほうがベローズ形より大きい(2016年問119で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-124","s":4,"q":"雑用水設備に関する記述として、最も不適当なものはどれか。","o":["広域循環方式は、公共下水処理場の処理水を排水再利用設備で処理し、一般に大規模な地区へ送って使うものである。","排水再利用水や雨水などを原水とする雑用水受水槽には、上水を補給する装置を設ける。","工事完成時に雑用水に色を付けて通水試験を行い、上水系の器具から色の付いた水が出ないことを確かめる。","配管にスライムが発生したときは、雑用水の残留塩素濃度を高めて洗浄する。","雨水利用設備の雨水利用率とは、使用水量に対する雨水利用量の割合である。"],"a":4,"e":"雨水利用率とは、雨水集水量に対する雨水利用量の割合である(2020年問124で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-125","s":4,"q":"排水再利用施設の次の処理の流れで、【ア】【イ】【ウ】に入る装置の組合せとして、最も適当なものはどれか。\n集水 → スクリーン → 【ア】 → 【イ】 → 沈殿槽 → 【ウ】 → 消毒槽 → 排水処理水槽 → 配水","o":["ア:沈砂槽 ― イ:流量調整槽 ― ウ:生物処理槽","ア:流量調整槽 ― イ:生物処理槽 ― ウ:ろ過装置","ア:ろ過装置 ― イ:生物処理槽 ― ウ:流量調整槽","ア:流量調整槽 ― イ:沈砂槽 ― ウ:ろ過装置","ア:沈砂槽 ― イ:ろ過装置 ― ウ:生物処理槽"],"a":1,"e":"排水再利用施設の標準的な流れは、スクリーン → 流量調整槽 → 生物処理槽 → 沈殿槽 → ろ過装置 → 消毒槽 → 排水処理水槽である。","l":"法令外","c":""},{"id":"2022-126","s":4,"q":"排水再利用設備に使われる膜分離活性汚泥処理装置に関する記述として、最も不適当なものはどれか。","o":["分離膜には、主に精密ろ過膜(MF)が使われる。","膜モジュールを生物処理槽の中にひたす、槽内浸漬型が一般的である。","膜分離活性汚泥処理装置の後ろに沈殿槽を設ける。","処理水には消毒が必要である。","透過する水の量が減らないよう、定期的に膜を洗浄する。"],"a":2,"e":"膜分離活性汚泥処理装置では、膜で汚泥と水を分けるため、後段に沈殿槽を設けるとした記述が誤り。","l":"法令外","c":""},{"id":"2022-127","s":4,"q":"排水通気設備の機器と配管に関する記述として、最も不適当なものはどれか。","o":["雑排水ポンプは、厨房排水以外の雑排水を出すのに使う。","排水用硬質塩化ビニルライニング鋼管の接続には、可とう継手を使う。","防水床用の排水トラップには、水抜き孔が付いている。","排水用耐火二層管は、繊維モルタルの外管と、架橋ポリエチレン管の内管を組み合わせたものである。","トラップが組み込まれていない阻集器には、出口側に排水トラップを設ける。"],"a":3,"e":"排水用耐火二層管の内管は、硬質ポリ塩化ビニル管である(2020年問130で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-128","s":4,"q":"排水通気配管に関する記述として、最も不適当なものはどれか。","o":["排水横枝管から通気管を取り出すときは、排水横枝管の断面の真上の中心から45°以内の方向に取り出す。","器具排水管から各個通気管を取り出すときは、トラップのウェアから管径の2倍以上離れた位置から取り出す。","排水横枝管からループ通気管を取り出すときは、最も下流の器具排水管がつながる位置のすぐ上流から取り出す。","排水立て管から通気立て管を取り出すときは、最も低い排水横枝管より低い位置から取り出す。","通気管の末端を窓や換気口の近くで大気に開放するときは、窓・換気口の上端から600mm以上立ち上げて開口する。"],"a":2,"e":"ループ通気管は、最上流の器具排水管が排水横枝管につながる位置のすぐ下流から立ち上げる(2023年問129で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-129","s":4,"q":"排水通気設備に関する用語と説明の組合せとして、最も不適当なものはどれか。","o":["オフセット ― 排水立て管の経路を水平にずらすため、エルボやベンド継手でつくる移行部分","ブランチ間隔 ― 排水立て管につながる各階の排水横枝管(または排水横主管)の間の垂直距離が2.5mを超える区間","排水口開放 ― 間接排水管を、一般の排水系統に直結した水受け容器や排水器具のあふれ縁より低い位置で開放すること","結合通気管 ― 排水立て管内の圧力変動をやわらげるため、排水立て管から分かれて立ち上げ、通気立て管につなぐ逃し通気管","インバートます ― 底に150mm程度の泥だまりがあり、土砂をためて下水道に流れ出るのを防ぐ排水ます"],"a":4,"e":"インバートますは、底部に溝(インバート)のある排水ますで、汚水や雑排水に使う(2025年問131で正しい記述として出題)。150mm程度の泥だめを設けるのは雨水ますである(2023年問130)。","l":"法令外","c":""},{"id":"2022-130","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["管径75mmの排水横管の最小勾配は、1/100である。","排水ポンプは、排水槽の吸込みピットの壁面から200mm以上離して設置する。","排水槽の底の勾配は、吸込みピットに向かって1/15以上1/10以下とする。","排水立て管のオフセット部の上下600mm以内には、排水横枝管を設けてはならない。","厨房用の口径100mmの排水管に設ける掃除口の口径は、75mmとする。"],"a":4,"e":"厨房用の口径100mmの排水管に設ける掃除口の口径は100mmとする(2024年問129で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-131","s":4,"q":"排水トラップと間接排水に関する記述として、最も不適当なものはどれか。","o":["間接排水管の長さが1,500mmを超える場合は、悪臭を防ぐため、機器・装置の近くにトラップを設ける。","飲料用水槽で、管径100mmの間接排水管に設ける排水口空間は、最小150mmとする。","洗濯機の間接排水管の先は、排水口空間を確保するか、排水口開放とする。","排水トラップの脚断面積比(流出脚の断面積/流入脚の断面積)が小さくなると、封水強度は大きくなる。","めったに使わない衛生器具のトラップには、封水が蒸発して破れないよう、トラップ補給水装置を付ける。"],"a":3,"e":"脚断面積比が大きくなると封水強度は大きくなる(2023年問128で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-132","s":4,"q":"敷地内の排水設備に関する記述として、最も不適当なものはどれか。","o":["排水の直管が長い場合、排水ますは管内径の120倍を超えない範囲に設ける。","合流式排水方式は、汚水・雑排水・雨水を同じ系統で排水する。","雨水ますの流入管と流出管の管底の差は、20mm程度とする。","雨水浸透施設は、透水性舗装・浸透ます・浸透地下トレンチなどでできている。","排水ますの大きさは、配管を埋める深さ、つながる配管の管径と本数などを考えて決める。"],"a":1,"e":"(2)の記述が誤り。","l":"法令外","c":""},{"id":"2022-133","s":4,"q":"排水設備の清掃・診断に関する記述として、最も不適当なものはどれか。","o":["排水立て管の清掃に使う高圧洗浄法は、5〜30MPaの高圧の水を噴射して管内を洗う方法である。","排水管に付いた有機性の汚れは、酸性洗浄剤で取り除く。","排水管内部の腐食の状態は、超音波厚さ計やX線を使う方法などで確かめる。","ウォータラム法は、圧縮空気を一気に放出し、その衝撃で詰まりを取り除く方法である。","ワイヤを通す方法は、一般に長さ25mまでの排水横管の清掃に使う。"],"a":1,"e":"排水管の有機性の付着物は、アルカリ性洗浄剤で取り除く(2024年問135で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-134","s":4,"q":"排水設備に関する記述として、最も不適当なものはどれか。","o":["汚水槽の清掃は、酸素濃度が18%以上、かつ硫化水素濃度が10ppm以下であることを確かめてから作業する。","逆流防止弁は、排水通気管からの臭気の逆流を防ぐために設ける。","飲食店などのグリース阻集器で出る油分の廃棄物は、産業廃棄物として処理する。","排水槽の中で汚物などの腐敗が進んで悪臭が出る場合は、排水ポンプのタイマ制御で1〜2時間ごとに強制的に排水する。","排水管に付ける床下式の掃除口のふたには、砲金製のプラグを使う。"],"a":1,"e":"逆流防止弁は、下水本管からの排水の逆流を防ぐために設ける(2017年問133で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-135","s":4,"q":"衛生器具設備に関する記述として、最も不適当なものはどれか。","o":["衛生器具は危ない突起のない形のものを選び、使う人の安全に配慮する。","節水機器を入れる場合は、排水管の中で汚物などを運ぶ性能にも配慮する。","洗面器の取り付け状態は、2か月に1回、定期に点検する。","水受け容器には、便器・洗面器類・流し類のほかに、トラップも含まれる。","小便器の排水状態は、6か月に1回、定期に点検する。"],"a":3,"e":"トラップは水受け容器には含まれない。","l":"法令外","c":""},{"id":"2022-136","s":4,"q":"大便器まわりの故障の現象と、その原因の組合せとして、最も不適当なものはどれか。","o":["便器と床の間がぬれる ― フランジ部のシール材の取り付けが悪い","洗浄力が弱く、汚物が流れない ― タンク内の止水位が高くなっている","洗浄弁のハンドル部から水が漏れる ― ハンドル部のパッキンや押し棒がすり減ってゆるんでいる","水の出る時間が長い ― 洗浄弁のピストンバルブのストレーナが詰まりかけている","洗出し便器で封水の位置が低い ― つながる汚水管の勾配がおかしく、サイホン現象が起きている"],"a":1,"e":"洗浄力が弱い原因を「タンク内の止水位が高い」とした組合せが誤り。","l":"法令外","c":""},{"id":"2022-137","s":4,"q":"浄化槽で採用されている処理法のうち、生物膜法に分類されないものはどれか。","o":["長時間ばっ気法","回転板接触法","接触ばっ気法","散水ろ床法","担体流動法"],"a":0,"e":"長時間ばっ気法は生物膜法に分類されない。回転板接触法・接触ばっ気法・散水ろ床法・担体流動法は生物膜法である。","l":"法令外","c":""},{"id":"2022-138","s":4,"q":"水分98.0%の汚泥15.0m³を、水分97.0%まで濃縮したときの汚泥の容積として、最も適当なものはどれか。","o":["3.0m³","5.0m³","7.5m³","10.0m³","12.5m³"],"a":3,"e":"固形分の量は変わらない。固形分は15.0×(100−98)/100=0.3m³分で、濃縮後は固形分が3%になるので、0.3÷0.03=10.0m³となる。","l":"法令外","c":""},{"id":"2022-139","s":4,"q":"特殊設備に関する記述として、最も不適当なものはどれか。","o":["厨房機器は、食品にふれる部分が衛生的で、洗浄・殺菌しやすい構造にする。","入浴設備の打たせ湯には、循環している浴槽の水を使わない。","水景施設へ上水系統から補給する水は、必ず吐水口空間を設けて間接的に給水する。","プールの循環ろ過にオーバフロー方式を使う場合は、オーバフローに床の洗浄水が入らない構造にする。","入浴設備で浴槽の循環水を消毒する場合は、塩素系薬剤の投入口を、ろ過器から出た直後に設ける。"],"a":4,"e":"塩素系薬剤の投入口を「ろ過器から出た直後」に設けるとした記述が誤り。","l":"法令外","c":""},{"id":"2022-140","s":4,"q":"消防用設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["一定規模以上の特定防火対象物は、消防設備士または消防設備点検資格者が点検する。","一定規模以上の建物の定期点検の結果は、特定防火対象物は1年に1回、非特定防火対象物は3年に1回報告する。","消防用設備等に付いている自家発電設備は、1年に1回機器点検を行う。","外観点検は、損傷がないかなど外観から判断できることを、設備の種類に応じて点検基準に従って確認する。","防火管理者は日常点検として消防用設備の異常信号などを確認し、異常があればすぐに修理して機能を回復させる。"],"a":2,"e":"自家発電設備の機器点検は6か月に1回である(2025年問140で正しい記述として出題)。報告の頻度(特定1年・非特定3年)は消防法施行規則第31条の6第3項のとおり。","l":"消防法施行規則 第31条の6第3項(選択肢2)","c":""},{"id":"2022-141","s":5,"q":"「建築物における衛生的環境の維持管理について」(平成20年1月25日 健発第0125001号)に示された建築物環境衛生維持管理要領について述べた次の文のうち、最も不適当なものはどれか。","o":["建築物の清掃は、用途、使用状況、劣化状況、建築資材などを考えた年間作業計画と作業手順書をつくり、それにもとづいて行う。","天井など日常の清掃が届きにくい箇所や照明器具、給排気口は、6か月以内ごとに1回、定期に汚れを点検し、必要に応じて除じん・洗浄を行う。","廃棄物の収集・運搬設備、貯留設備などの廃棄物処理設備は、1年以内ごとに1回、定期に点検し、必要に応じて補修・消毒などを行う。","清掃用機械などは、6か月以内ごとに1回、定期に点検し、必要に応じて整備・取替えなどを行う。","帳簿書類には、清掃・点検・整備を行った年月日、作業内容、実施者名などを記載する。"],"a":2,"e":"廃棄物処理設備の点検は6か月以内ごとに1回である(2024年度問141でも正しい記述として出題)。日常清掃しない箇所の6か月以内ごとの点検は告示第119号第5の一の3のとおり。","l":"平成15年厚生労働省告示第119号 第5(維持管理要領)","c":""},{"id":"2022-142","s":5,"q":"清掃作業管理での作業の流れと、現場責任者の業務の組合せとして、最も不適当なものはどれか。","o":["予定された作業 ― 作業予定表の作成","従事者への作業の指示・指導 ― 管理仕様書の作成","資機材の準備 ― 作業手順書・作業ごとの使用資機材一覧表の作成","作業の実施 ― 指示・指導","作業の終了(手直し) ― 点検確認(手直しの指示・指導)"],"a":1,"e":"この組合せが誤り。管理仕様書は委託の内容を定める書類で、従事者への指示・指導の段階で現場責任者がつくるものではない。","l":"法令外","c":""},{"id":"2022-143","s":5,"q":"清掃品質の評価について述べた次の文のうち、最も不適当なものはどれか。","o":["品質評価は、自らセルフインスペクションを行い、求められる品質との差を確かめることである。","組織品質は、事業所管理品質と作業品質でできている。","評価者は、業務によく通じていることが望ましい。","評価方法には、光沢度計などの測定機器を使う検査と、目視などによる官能検査がある。","作業の改善点は、仕様書や作業基準表に限らず、建物全体の衛生性に目を向けて見つける必要がある。"],"a":1,"e":"組織品質は、事業所管理品質と現場管理品質で構成される(2025年度問145・2024年度問145でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-144","s":5,"q":"清掃品質の評価者がインスペクションで行うことについて述べた次の文のうち、最も不適当なものはどれか。","o":["準備では、評価する範囲を具体的に決め、インスペクションの実施計画を立てる。","評価では、品質のよしあしだけでなく、どの程度の改善が必要かを分析・判断する。","改善では、改善の内容や具体的な対策を示して、清掃従事者に直接指示をする。","再点検で改善されていない場合は、その理由を明らかにして事後処理をする。","再点検の結果をもとに、改善について再評価する。"],"a":2,"e":"この記述が誤り。評価者は改善内容を示して現場の責任者に指示し、清掃従事者への指示は現場の責任者を通じて行う。","l":"法令外","c":""},{"id":"2022-145","s":5,"q":"ほこりや汚れの除去について述べた次の文のうち、最も適当なものはどれか。","o":["水に溶けるかさ高の固着物なら、物理的な力を加えなくても水洗いで取れる。","アルミニウム建材は、アルカリに弱い。","おがくずに水を含ませて掃き取る方法は、ほこりを付着させる効果が小さい。","バキュームクリーニングでは、カーペットの織り目に入ったほこりや土砂は取れない。","ダストコントロール作業法を使えば、ほこり以外の汚れも取れる。"],"a":1,"e":"アルミニウムはアルカリに弱く、アルカリ性洗剤で変色・腐食する。おがくず法は付着効果が大きく、バキュームクリーニングは織り目のほこりを取るのに使う(2025年度問147参照)。","l":"法令外","c":""},{"id":"2022-146","s":5,"q":"清掃の対象となる床材について述べた次の文のうち、最も不適当なものはどれか。","o":["水をはじく(疎水性の)床には、油に溶ける物質が付きやすい。","汚れは平らで緻密な表面には付きにくく取りやすいが、凹凸が多く粗い表面には付きやすく取りにくい。","汚れがしみ込みやすい吸水性の床材や、汚れでさびやカビなどの変質が起きやすいものは、後の処理が難しい。","カーペットに洗剤分を残すと、汚れの予防効果が得られる。","汚れを取るには水を使うことが多いので、水に強い材質のものは清掃しやすいことが多い。"],"a":3,"e":"洗剤分が残るとそこに汚れが付きやすくなる。告示でも、カーペット類に洗剤を使ったときは洗剤分が残らないようにすることとされている(告示第119号第5の一の2)。","l":"平成15年厚生労働省告示第119号 第5","c":""},{"id":"2022-147","s":5,"q":"ビルクリーニング用の器具について述べた次の文のうち、最も不適当なものはどれか。","o":["床磨き機に使うブラシは、シダの茎やナイロン繊維を植えたものが一般的である。","自在ぼうきは、馬毛などを植えた薄いブラシに長い柄を付けた構造である。","三つ手ちり取りは、本体を下に置くとふたが開き、移動するときにごみがこぼれない構造である。","床維持剤を塗るフラット型モップは、房が短いので壁や幅木を汚しにくい。","床磨き機に使うブラシは、凹凸のある床の洗浄に使う。"],"a":2,"e":"移動するときにごみがこぼれない構造なのは改良ちり取り(文化ちり取り)である(2025年度問148参照)。","l":"法令外","c":""},{"id":"2022-148","s":5,"q":"清掃作業に使う洗剤について述べた次の文のうち、最も適当なものはどれか。","o":["樹脂床維持剤の皮膜の手入れに使う表面洗剤は、泡立ちやすくつくられている。","洗剤に使う界面活性剤は、陰イオン系と陽イオン系の2つに大きく分けられる。","アルカリ性の強い洗剤は、トイレの尿石を取るのに有効である。","アルカリ性の強い洗剤は、清掃作業者の皮膚を傷めて危険である。","アルカリ性の強い洗剤は、リノリウムに付いた油汚れを取るのに使う。"],"a":3,"e":"強いアルカリ性の洗剤は皮膚を傷めるので、手袋などで保護する。表面洗剤は泡立ちが少なく(2025年度問149)、尿石には酸性洗剤を使い、リノリウムはアルカリに弱い。","l":"法令外","c":""},{"id":"2022-149","s":5,"q":"洗剤・床維持剤と関係する語句の組合せとして、最も不適当なものはどれか。","o":["フロアフィニッシュ ― 床材の保護","フロアポリッシュ ― 床油","シール剤 ― ポリウレタン","ビルダ ― 汚れの再付着防止","リン酸塩 ― 富栄養化"],"a":1,"e":"床油にあたるのはフロアオイル(2024年度問149参照)。フロアポリッシュは塗って乾くと皮膜をつくる床維持剤である。","l":"法令外","c":""},{"id":"2022-150","s":5,"q":"弾性床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["塩化ビニル系床材には、床維持剤を塗らなくてよい製品も売られている。","塩化ビニル系の床は、薬品や水に強い。","塩化ビニルシートには、床維持剤が密着しにくいものがある。","ウェットメンテナンス法は、ドライメンテナンス法より作業の標準化・システム化がしやすい。","ドライバフ法は、床磨き機の回転数が高いほど光沢を回復しやすい。"],"a":3,"e":"作業の標準化・システム化がしやすいのはドライメンテナンス法の方である。ドライバフ法は高速回転ほど効果が上がる(2025年度問153参照)。","l":"法令外","c":""},{"id":"2022-151","s":5,"q":"繊維床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["事務所建築物の繊維床材のしみは、約60%が親水性である。","ウール素材は含水率が約15%なので、洗った後に乾きにくい。","スチーム洗浄機は、エクストラクタより、洗浄後にカーペットに残る水分が多い。","繊維床材は、パイルにすき間があるので土砂やほこりがたまりやすい。","ナイロンに付いた親水性の汚れは、ポリエステルより取りにくい。"],"a":2,"e":"スチーム洗浄機は高温の蒸気で洗うので使う水が少なく、エクストラクタより洗浄後に残る水分は少ない。","l":"法令外","c":""},{"id":"2022-152","s":5,"q":"硬性床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["硬性床材は一般に多孔質で細かい凹凸があるので、洗浄後の汚水や洗剤分をできるだけ取り除く。","テラゾには酸性洗剤を使わない。","セラミックタイルには、アルカリ性洗剤を使わない。","花崗岩には、アルカリ性洗剤を使う。","目地のセメントモルタルは、酸性洗剤で傷みやすい。"],"a":2,"e":"この記述が誤り。セラミックタイルは薬品に強く、アルカリ性洗剤を使ってよい。","l":"法令外","c":""},{"id":"2022-153","s":5,"q":"木質系床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["水分で膨らんだり縮んだりをくり返し、割れやすき間ができやすい。","アルカリ性洗剤を使うと、床材が変色しやすい。","ナラやケヤキなどの広葉樹は、木質が硬い。","ポリウレタン樹脂でシールされた体育館の床材は、水拭きによる日常清掃で管理する。","シールされていない床材は、油性の保護剤で管理する。"],"a":3,"e":"体育館の床板がはがれてけがをする事故を防ぐため、日常清掃での水拭きをやめるよう文部科学省から通知が出されている(2023年度問154でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-154","s":5,"q":"外装の清掃について述べた次の文のうち、最も不適当なものはどれか。","o":["ゴンドラによる清掃作業では、労働安全衛生法にもとづくゴンドラ安全規則を必ず守らなければならない。","自動窓拭き設備による窓ガラス清掃は、人の作業より仕上がりがよい。","ロープ高所作業では、労働安全衛生規則により作業計画の策定などが義務付けられている。","金属材の清掃は、汚れが軽く固まらないうちに行う。","石や磁器タイルの壁は汚れが目立ちにくいが、数年に1回は洗う。"],"a":1,"e":"この記述が誤り。自動窓拭き設備は天候に左右されにくく計画的に作業できる(2023年度問156)が、仕上がりは人の作業に及ばない。","l":"法令外","c":""},{"id":"2022-155","s":5,"q":"ごみの処理の段階と関係する語句の組合せとして、最も不適当なものはどれか。","o":["排出抑制 ― 収集袋の有料化","収集・運搬 ― 余熱利用","再生 ― 集団回収","中間処理 ― 破砕・圧縮","最終処分 ― 残余容量"],"a":1,"e":"余熱利用は焼却施設の熱を発電や温水に使うことで、中間処理(焼却)の段階にあたる。収集・運搬の段階ではない。","l":"法令外","c":""},{"id":"2022-156","s":5,"q":"平成25年以降の廃棄物の排出の傾向について述べた次の文のうち、最も不適当なものはどれか。","o":["ごみの総排出量のうち、事業系ごみの割合は約30%である。","ごみの総資源化(再生)量は、ごみの総排出量の約20%である。","し尿と浄化槽汚泥の年間処理計画量のうち、約90%がし尿処理施設で処理されている。","産業廃棄物の総排出量を種類別に見ると、がれき類が約40%で最も多い。","産業廃棄物の総排出量のうち、約50%が再生利用されている。"],"a":3,"e":"産業廃棄物を種類別に見ると、最も多いのは汚泥である(2025年度問157でも正しい記述として出題)。","l":"法令外(環境省の統計)","c":""},{"id":"2022-157","s":5,"q":"「建築物における衛生的環境の維持管理について」(平成20年1月25日 健発第0125001号)の建築物環境衛生維持管理要領に示された次の文の[ア]〜[ウ]に入る語句の組合せとして、正しいものはどれか。\n「建築物内で発生する廃棄物の分別、収集、運搬及び貯留について、安全で衛生的かつ[ア]な方法により、速やかに処理すること。[イ]は、分別ができるような環境を整備し、[ウ]へ分別を促すこと。」","o":["ア 効率的/イ 所有者等/ウ 利用者","ア 効率的/イ 占有者等/ウ 事業者","ア 効率的/イ 占有者等/ウ 利用者","ア 計画的/イ 占有者等/ウ 事業者","ア 計画的/イ 所有者等/ウ 利用者"],"a":0,"e":"「安全で衛生的かつ効率的な方法」で、「所有者等は分別できる環境を整え、利用者へ分別を促す」(2023年度問141・2024年度問141でも同じ趣旨が正しい記述)。","l":"法令外(建築物環境衛生維持管理要領)","c":""},{"id":"2022-158","s":5,"q":"廃棄物処理法について述べた次の文のうち、最も不適当なものはどれか。","o":["事業系一般廃棄物の排出事業者が処理を委託するときは、市町村長の許可を受けた処理業者に委託しなければならない。","事業系一般廃棄物の排出事業者が、委託した廃棄物の移動や処理の状況を自ら把握するため、廃棄物処理法にもとづく一般廃棄物管理票制度が設けられている。","事業系一般廃棄物の排出事業者が、市町村の施設へ自分で運び込むなど自ら処理するときは、処理基準に従わなければならない。","特別管理廃棄物とは、爆発性、毒性、感染性など、人の健康や生活環境に被害を与えるおそれのある性状をもつ廃棄物である。","産業廃棄物の処理を業とする者は、専ら再生利用の目的となる産業廃棄物の場合などを除き、都道府県知事の許可を受けなければならない。"],"a":1,"e":"廃棄物処理法の管理票(マニフェスト)制度は産業廃棄物についての制度で(第12条の3)、一般廃棄物の管理票制度はない。","l":"廃棄物処理法 第12条の3","c":""},{"id":"2022-159","s":5,"q":"建築物内廃棄物の発生量の原単位についての次の文の[(1)]〜[(5)]のうち、最も不適当なものはどれか。\n「発生量の把握に使う一般的な原単位は[(1)]である。発生量が多い場合は[(2)]、または重量の代わりに容量で示す[(3)]を使う。人の利用者数で発生量が左右される図書館では[(4)]を使う。廃棄物の質を表す単位は『単位容積質量値』で[(5)]を使う。」","o":["kg/(m²・年)","kg/(m²・日)","L/(m²・日)","kg/(人・年)","m³/kg"],"a":4,"e":"単位容積質量値は、一定の容積あたりの質量なので、kg/m³(またはkg/L)で表す(2024年度問161でも0.4kg/Lとして計算)。m³/kgは逆である。","l":"法令外","c":""},{"id":"2022-160","s":5,"q":"建築物内廃棄物にかかわる人たちの基本的な役割について述べた次の文のうち、最も不適当なものはどれか。","o":["ビルの入居者は、廃棄物処理のルールを徹底させるため責任者を選ぶ。","ビルの入居者は、廃棄物を減らしたり容積を小さくしたりするよう努める。","廃棄物処理業者は、分別できる廃棄物をはっきりさせる。","ビルメンテナンス事業者は、建築物内廃棄物の処理に必要な容器、集積場所、保管場所などを適切に用意する。","ビルメンテナンス事業者は、必要な場合に建築物内廃棄物の事後分別を行う。"],"a":3,"e":"この記述が誤り。容器や集積場所、保管場所などの設備を用意するのは、ビルメンテナンス事業者の基本的な役割ではない。","l":"法令外","c":""},{"id":"2022-161","s":5,"q":"ごみ2m³あたりの質量を300kgとするとき、60Lのごみ容器に入るごみの量として正しいものはどれか。","o":["6kg","9kg","12kg","18kg","36kg"],"a":1,"e":"2m³＝2,000Lなので、1Lあたり300÷2,000＝0.15kg。60L×0.15kg/L＝9kg。","l":"計算","c":""},{"id":"2022-162","s":5,"q":"産業廃棄物管理票制度(マニフェスト制度)について述べた次の文のうち、最も不適当なものはどれか。","o":["電子マニフェストは、紙マニフェストと違ってA票、B2票、D票、E票の保存が不要である。","処理業者を選ぶ方法の一つに、都道府県などのホームページから選ぶ方法がある。","排出事業者は、廃棄物が最終処分まで適正に処分されたことを確認する義務がある。","紙マニフェストでは、収集運搬業者は運搬を終えると排出事業者にB2票を返送する。","紙マニフェストでは、最終処分場での処分が終わると、収集運搬業者にE票が返送される。"],"a":4,"e":"E票は最終処分が終わったことを知らせる伝票で、排出事業者に返送される(2024年度問164参照)。収集運搬業者に返送されるのではない。","l":"廃棄物処理法 第12条の3","c":""},{"id":"2022-163","s":5,"q":"建築物内廃棄物の中間処理について述べた次の文のうち、最も不適当なものはどれか。","o":["厨芥類を処理する生ごみ処理機には、減量のための乾燥機や、リサイクルのための堆肥化装置がある。","缶類の処理として、スチール缶とアルミ缶を自動で分けて圧縮し、ブロック状にする方式がある。","廃棄紙類の処理には、保管スペースを確保するため圧縮・梱包機が使われる。","発泡スチロールの処理に使う溶融固化装置は、薬液を加えて溶かし固める方式である。","段ボールの処理には梱包機が使われる。"],"a":3,"e":"溶融固化装置は、熱を加えて溶かし固める方式である(2025年度問162でも正しい記述として出題)。薬液ではない。","l":"法令外","c":""},{"id":"2022-164","s":5,"q":"建築物内廃棄物の貯留・排出方式について述べた次の文のうち、最も不適当なものはどれか。","o":["真空収集方式は、容器方式より必要な人数が少ない。","コンパクタ・コンテナ方式は、貯留・排出機方式より作業性にすぐれる。","容器方式は、ほかの方式より設置スペースが少なくてすむ点ですぐれる。","コンパクタ・コンテナ方式は、ほかの方式よりランニングコストにすぐれる。","容器方式は、ほかの方式より初期費用にすぐれる。"],"a":2,"e":"容器方式はごみを容器に入れたまま貯めるので、圧縮する方式などより広い設置スペースが必要になる。","l":"法令外","c":""},{"id":"2022-165","s":5,"q":"リサイクルを進めるための個別の法律と、その内容の組合せとして、最も不適当なものはどれか。","o":["容器包装リサイクル法 ― 市町村による容器包装の分別収集","家電リサイクル法 ― 市町村による消費者からの廃家電の引取り","食品リサイクル法 ― 食品の製造・加工・販売業者による食品廃棄物の再生利用","自動車リサイクル法 ― 製造事業者によるシュレッダーダストなどの再資源化","建設リサイクル法 ― 工事の受注者による分別解体などの実施"],"a":1,"e":"家電リサイクル法で消費者から廃家電を引き取るのは小売業者である(2025年度問158でも小売業者に引き取ってもらう記述が正しいとされている)。","l":"特定家庭用機器再商品化法","c":""},{"id":"2022-166","s":6,"q":"蚊の防除に関する記述として、最も不適当なものはどれか。","o":["ULV処理は、一般に成虫に対してすぐに効く力(速効性)が低い。","チカイエカの対策として、浄化槽の通気管に防虫網を付ける。","浄化槽の中の防除効果は、柄杓ですくい取った幼虫の数で判定できる。","ライトトラップや粘着トラップでとれた蚊の数は、維持管理水準を判断するのに役立つ。","クレゾールなどを含む殺虫製剤は、浄化槽の中の微生物に影響を与える。"],"a":0,"e":"ULV処理は成虫に対する速効性が高い処理法であり、「低い」とした記述が誤り。","l":"法令外","c":""},{"id":"2022-167","s":6,"q":"蚊の生態に関する記述として、最も不適当なものはどれか。","o":["コガタアカイエカは、水田や湿地など大きな水域で発生する。","温帯にいるヒトスジシマカは、卵の姿で冬を越す。","アカイエカは、有機物の多い排水溝や雨水ますで発生する。","チカイエカは、最初の産卵を吸血しないで行うことができる。","アカイエカとチカイエカは、雌成虫の外見で簡単に見分けられる。"],"a":4,"e":"アカイエカとチカイエカは、雌成虫の外部形態で区別することができない(2017年問166でも「外部形態で区別できる」が誤りとして出題)。","l":"法令外","c":""},{"id":"2022-168","s":6,"q":"ゴキブリの生態に関する記述として、最も不適当なものはどれか。","o":["ワモンゴキブリは、卵鞘を唾液などでくぼみやすき間にはり付ける。","ゴキブリ類は、成虫と幼虫のすむ場所が同じである。","ふ化したばかりのゴキブリの幼虫は、0.5mmのすき間にも潜り込める。","チャバネゴキブリは、休眠する性質をもたない。","ゴキブリ類が集団をつくるのは、気門から出る集合フェロモンによって促される。"],"a":4,"e":"集合フェロモンが気門から分泌されるとした記述が誤り(2025年問169でも同じ内容は正しい記述とされていない)。","l":"法令外","c":""},{"id":"2022-169","s":6,"q":"ゴキブリの防除に関する記述として、最も不適当なものはどれか。","o":["空間処理とは、ゴキブリの気門から成分を取り込ませ、主に呼吸毒として働かせる処理方法である。","乳剤とマイクロカプセル剤の残効性を同じ条件で比べると、乳剤のほうが長い。","チャバネゴキブリでは、殺虫剤抵抗性と喫食抵抗性の両方が報告されている。","残留処理では、散布する面の素材によって散布量を調整する必要がある。","ゴキブリ指数とは、調査期間中の1日・1トラップあたりの捕獲数をいう。"],"a":1,"e":"残効性は、乳剤よりマイクロカプセル剤のほうが長い。","l":"法令外","c":""},{"id":"2022-170","s":6,"q":"ダニに関する記述として、最も不適当なものはどれか。","o":["マダニ類は、第1脚の先に温度や炭酸ガスを感じる器官がある。","マダニ類は、幼虫・若虫・成虫のすべての段階で吸血する。","タカラダニ類は、ほかのダニやチャタテムシなどを捕まえて食べる。","ヒゼンダニは、ヒトの皮膚の下に寄生する。","イエダニは、家にすむネズミ類に寄生する。"],"a":2,"e":"タカラダニ類を捕食性とした記述が誤り。ほかの小さな生き物を捕食するのはツメダニ類である(2024年問169で「ミナミツメダニは捕食性」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-171","s":6,"q":"害虫に関する記述として、最も不適当なものはどれか。","o":["ヒメマルカツオブシムシの成虫は、乾燥食品や羊毛製品などを食べて害を与える。","シバンムシ類の幼虫は、乾燥した麺類や菓子類に害を与える。","ヒラタキクイムシ類の幼虫は、穀物に害を与えることもある。","一部のメイガ類は、貯蔵した穀物の害虫である。","イガは、繊維や衣類の害虫である。"],"a":0,"e":"ヒメマルカツオブシムシで乾燥食品や羊毛製品を食害するのは成虫ではない。","l":"法令外","c":""},{"id":"2022-172","s":6,"q":"害虫に関する記述として、最も不適当なものはどれか。","o":["コナチャタテ類の防除では、餌になるカビの発生をおさえることが必要である。","ヒメマルカツオブシムシは、フェロモンで誘引される。","マルカメムシの防除では、食草になるクズなどを取り除くことが効果的である。","チョウバエ類の幼虫には、一般に蚊より殺虫剤がよく効く。","イエバエでは、薬剤抵抗性をもつ集団が報告されている。"],"a":3,"e":"チョウバエ類の幼虫に対する殺虫剤の効力は、一般に蚊より高いとはいえない。","l":"法令外","c":""},{"id":"2022-173","s":6,"q":"次の害虫の防除を目的とする殺虫剤のうち、医薬品医療機器等法による承認が必要なものはどれか。","o":["アリ類","シロアリ類","スズメバチ類","トコジラミ類","ドクガ類"],"a":3,"e":"トコジラミ用の殺虫製剤は、医薬品医療機器等法にもとづく医薬品・医薬部外品としての承認が必要である(2024年問173で正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-174","s":6,"q":"殺虫剤の効き目や剤形に関する記述として、最も不適当なものはどれか。","o":["殺虫剤がすぐに効くかどうか(速効性)は、KT値から判断できる。","ピレスロイド剤は、ゴキブリなどにフラッシング効果(隠れ場所から追い出す効果)を示す。","フィプロニルは、ゴキブリ用食毒剤の有効成分である。","プロペタンホスには、マイクロカプセル(MC)剤がある。","有機リン剤を有効成分とする、ULV処理専用の乳剤がある。"],"a":4,"e":"ULV処理専用の水性乳剤は、ピレスロイド剤のフェノトリンを有効成分とするものである(2024年問172で正しい組合せとして出題)。有機リン剤のULV専用乳剤とした記述が誤り。","l":"法令外","c":""},{"id":"2022-175","s":6,"q":"ネズミに関する記述として、最も不適当なものはどれか。","o":["ネズミのふんから、食中毒の原因になる病原体が見つかることがある。","ハツカネズミは、クマネズミと比べてトラップにかかりにくく、殺鼠剤に弱い。","クマネズミは、ドブネズミと比べて穀類などの植物性の餌を好む傾向が強い。","クマネズミは、垂直な壁を登ったり、電線を伝ったりして室内に入ってくる。","ネズミの通り道はほぼ決まっているので、体の汚れが通り道の壁やパイプシャフトのまわりに付く。"],"a":1,"e":"ハツカネズミは家住性ネズミの中で警戒心が最も弱い(2023年問174で正しい記述として出題)ので、クマネズミよりトラップにかかりにくいとした点が誤り。","l":"法令外","c":""},{"id":"2022-176","s":6,"q":"殺鼠剤に関する記述として、最も適当なものはどれか。","o":["粉剤は、ネズミの好みに合わせた毒餌をつくるのに使える。","ネズミ類が殺鼠剤に抵抗性を発達させるしくみは、昆虫とはちがう。","殺鼠剤を食べて死んだネズミから、ハエなどが発生することはない。","殺鼠剤の有効成分は選択毒性が高く、体重あたりのヒトへの毒性はネズミより低い。","ワルファリンは、1回食べるだけでネズミを失血死させる。"],"a":0,"e":"粉剤は餌の材料にまぶして、ネズミの好みに合わせた毒餌をつくるのに使える(2025年問176でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2022-177","s":6,"q":"次の①〜④のすべてにあてはまる殺鼠剤の有効成分はどれか。\n①1回食べるだけでも効果がある。\n②第2世代の抗凝血性殺鼠剤である。\n③ワルファリンに抵抗性をもつネズミの対策用に開発された。\n④建築物衛生法の特定建築物の中で使うことが認められている。","o":["リン化亜鉛","ブロマジオロン","クマテトラリル","ジフェチアロール","シリロシド"],"a":3,"e":"ジフェチアロールは第2世代の抗凝血性殺鼠剤で(2025年問176)、特定建築物内で使える(2023年問175)。ブロマジオロンは特定建築物内では使えず、クマテトラリルは第1世代である。","l":"法令外","c":""},{"id":"2022-178","s":6,"q":"防虫・防鼠の構造と、防除に使う機器に関する記述として、最も適当なものはどれか。","o":["ライトトラップは、長い波長の誘引ランプに集まった昆虫を捕まえる器具である。","ネズミが入ってこないよう、建物の外壁に木の枝がふれないようにする。","噴射できる薬剤の粒の大きさは、ミスト機・ULV機・噴霧器のうちULV機が最も大きい。","昆虫が室内に入るのを防ぐための網戸は、10メッシュ程度にする。","ULV機は、高濃度の薬剤を大量にまく散布機である。"],"a":1,"e":"ネズミは木の枝を伝って建物に入るので、外壁に木の枝がふれないようにする。","l":"法令外","c":""},{"id":"2022-179","s":6,"q":"建築物衛生法の特定建築物で行うねずみ・昆虫等の防除に関する記述として、最も不適当なものはどれか。","o":["トラップ調査で複数の種類の害虫がとれた場合、それぞれの種類の生息密度が「許容水準」でも「警戒水準」にあると判断する。","ねずみ・昆虫等への不快感も、健康被害の一つである。","調査では、発生状況や被害状況の聞き取り調査を重点的に行う。","防除には、ベクターコントロールとニューサンスコントロールという2つの異なる側面がある。","建築物の維持管理マニュアルのIPM実施モデルの水準値は、現場の使い方などに応じて個別の水準値を決めることもできる。"],"a":2,"e":"聞き取り調査を重点的に行うとした記述が誤り(2016年問179・2024年問179でも、聞き取り中心の調査は誤りとして出題)。","l":"法令外","c":""},{"id":"2022-180","s":6,"q":"ねずみ・昆虫等や鳥類の防除と殺虫剤に関する記述として、最も不適当なものはどれか。","o":["蚊の幼虫に対する基礎的な殺虫力は、LD50の値で判断できる。","カラスの巣を卵ごと取り除く場合は、自治体の長などの許可が必要になる。","「発生予防対策」は、ねずみ・昆虫等の対策の基本である。","水性乳剤は、水でうすめても白くにごらない。","IGRは、成虫を殺す効力がない。"],"a":0,"e":"蚊の幼虫の基礎的な殺虫力をLD50で判断するとした記述が誤り。なお鳥類の卵の採取等には都道府県知事などの許可が必要(鳥獣保護管理法第8条・第9条)。","l":"鳥獣の保護及び管理並びに狩猟の適正化に関する法律 第8条・第9条(選択肢2)","c":""},{"id":"2023-1","s":0,"q":"日本国憲法第25条の次の文の(ア)〜(エ)に入る語句の組合せとして、正しいものはどれか。\n「すべて国民は、健康で( ア )な最低限度の生活を営む権利を有する。② 国は、すべての( イ )について、( ウ )、社会保障及び( エ )の向上及び増進に努めなければならない。」","o":["ア 文化的　イ 生活部面　ウ 社会福祉　エ 公衆衛生","ア 社会的　イ 国民　ウ 環境衛生　エ 生活環境","ア 文化的　イ 国民　ウ 環境衛生　エ 生活環境","ア 社会的　イ 国民　ウ 社会福祉　エ 公衆衛生","ア 文化的　イ 生活部面　ウ 環境衛生　エ 公衆衛生"],"a":0,"e":"憲法第25条は「健康で文化的な最低限度の生活」を保障し、国は「すべての生活部面について、社会福祉、社会保障及び公衆衛生の向上及び増進」に努めると定めている。","l":"日本国憲法 第25条","c":""},{"id":"2023-2","s":0,"q":"法律と、その法律を受け持つ行政組織の組合せとして、誤っているものはどれか。","o":["地域保健法 ― 厚生労働省","廃棄物の処理及び清掃に関する法律 ― 環境省","学校保健安全法 ― 文部科学省","土壌汚染対策法 ― 国土交通省","健康増進法 ― 厚生労働省"],"a":3,"e":"土壌汚染対策法を所管しているのは環境省である。","l":"法令外(各省設置法)","c":""},{"id":"2023-3","s":0,"q":"特定建築物の用途について、最も不適当なものはどれか。","o":["興行場とは、興行場法にもとづく興行場をいう。","旅館とは、旅館業法の許可を受けた施設に限られる。","学校とは、学校教育法にもとづく学校に限られる。","博物館は、博物館法にもとづく博物館に限らない。","図書館は、図書館法にもとづく図書館に限らない。"],"a":2,"e":"特定用途の「学校」は、学校教育法第1条の学校に限らず、各種学校や研修所なども含まれる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2023-4","s":0,"q":"特定建築物の用途として、最も不適当なものはどれか。","o":["結婚式場","理容所","認可保育園","公民館","社交ダンスホール"],"a":2,"e":"認可保育園などの児童福祉施設は、特定用途に含まれない。結婚式場・公民館は集会場、社交ダンスホールは遊技場、理容所は店舗に当たる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2023-5","s":0,"q":"特定建築物の届出などについて、最も不適当なものはどれか。","o":["特定建築物が使われ始めたときは、その日から1か月以内に届け出る。","届け出る事項は、建築物衛生法施行規則で決められている。","届出をするのは、特定建築物の所有者等である。","届出事項が変わる場合は、変わる1か月前までに届け出る。","届出をしなかったり、うその届出をしたりすると、30万円以下の罰金が科されることがある。"],"a":3,"e":"届出事項が変わったときは、前もってではなく、変わった日から1か月以内に届け出る。","l":"建築物衛生法 第5条第3項","c":""},{"id":"2023-6","s":0,"q":"建築物衛生法で備えておく帳簿書類とその保存について、最も不適当なものはどれか。","o":["特定建築物の所有者等は、環境衛生上必要な事項を書いた帳簿書類を備えておかなければならない。","平面図や断面図は、その建物が取り壊されるまで保存しなければならない。","行った空気環境の測定結果は、5年間保存しなければならない。","行った遊離残留塩素の検査の記録は、5年間保存しなければならない。","受水槽を新しくしたときの給水の系統図は、5年間保存しなければならない。"],"a":4,"e":"5年間の保存期間が決められているのは、測定・検査の結果などの帳簿書類である。平面図・断面図や設備の系統図には期間の定めがなく、建物がある限り保存しておくものである。","l":"建築物衛生法施行規則 第20条","c":""},{"id":"2023-7","s":0,"q":"建築物環境衛生管理基準にもとづく空気環境の測定について、誤っているものはどれか。","o":["ホルムアルデヒド以外の測定は、2か月以内ごとに1回、定期に行う。","ホルムアルデヒドの測定結果が基準値を超えたときは、空調・換気設備の調整などで減らす対策をした後、すぐに測定する。","浮遊粉じんの量、一酸化炭素の含有率、二酸化炭素の含有率は、1日の使用時間中の平均値とする。","ふだんの使用時間中に、各階ごとに、居室の中央部で測定する。","大規模修繕を行ったときは、完了後に使い始めた日以後、最初に来る6月1日から9月30日までの間に1回、ホルムアルデヒドを測定する。"],"a":1,"e":"この記述が誤り。法令で定められたホルムアルデヒドの測定は、新築・増築・大規模の修繕・大規模の模様替の後、最初の6月1日〜9月30日の期間中に1回である。","l":"建築物衛生法施行規則 第3条の2","c":""},{"id":"2023-8","s":0,"q":"建築物環境衛生管理基準にもとづく飲料水の衛生上の措置について、誤っているものはどれか。","o":["飲料水として供給する水には、飲むためだけでなく、炊事用や手洗い用など、生活に使う水も含まれる。","水道水以外の地下水などを原水にする場合も、水道水と同じ水質を確保し、塩素消毒などを行う必要がある。","貯湯槽の清掃は、1年以内ごとに1回、定期に行う。","使い始めた後の飲料水の水質検査は、原水が水道水の場合と地下水の場合とで、項目も頻度も同じである。","遊離残留塩素の検査を、7日以内ごとに1回、定期に行う。"],"a":3,"e":"地下水などを原水にする場合は、水道水の場合の検査に加えて、有機化学物質などの項目を3年以内ごとに1回検査する必要があり、項目と頻度は同じではない。","l":"建築物衛生法施行規則 第4条第1項第3号・第4号","c":""},{"id":"2023-9","s":0,"q":"建築物環境衛生管理基準にもとづく雑用水の衛生上の措置について、誤っているものはどれか。","o":["雑用水槽の清掃は、槽の容量・材質や雑用水の水源の種類などに応じた方法で、定期に行う。","給水栓の水の遊離残留塩素を、100万分の0.1(0.1mg/L)以上に保つ。","遊離残留塩素の検査を、7日以内ごとに1回、定期に行う。","pH値、臭気、外観の検査を、7日以内ごとに1回、定期に行う。","一般細菌の検査を、2か月以内ごとに1回、定期に行う。"],"a":4,"e":"雑用水で2か月以内ごとに1回検査するのは大腸菌(散水・修景・清掃用は濁度も)であり、一般細菌は雑用水の検査項目ではない。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2023-10","s":0,"q":"建築物環境衛生管理技術者免状について、誤っているものはどれか。","o":["免状の再交付を受けた後になくした免状を見つけたときは、5日以内に、その免状を廃棄したことを厚生労働大臣に報告する。","免状をもつ人が亡くなったときは、戸籍法の届出義務者が1か月以内に、免状を廃棄したことを厚生労働大臣に報告する。","免状を破ったり、汚したり、なくしたりしたときは、厚生労働大臣に再交付を申請できる。","厚生労働大臣は、免状の返納を命じられ、その日から2年を過ぎていない人には、免状を交付しないことができる。","免状の記載事項が変わったときは、厚生労働大臣に書換え交付を申請できる。"],"a":3,"e":"正しくは、返納を命じられた日から「1年」を過ぎていない人には、免状を交付しないことができる。","l":"建築物衛生法 第7条第2項、施行規則 第12条第5項・第13条","c":"出題時の選択肢(1)(2)は免状を厚生労働大臣に「返還する」だったが、2026年1月ごろ施行の施行規則改正で「免状を廃棄した旨を報告する」に変わったため、今の条文に合わせて書き直した(正答は変わらない)。"},{"id":"2023-11","s":0,"q":"建築物環境衛生管理技術者の免状をもっていても、事業の登録の人的基準として認められないものはどれか。","o":["建築物環境衛生総合管理業の空気環境測定実施者","建築物排水管清掃業の排水管清掃作業監督者","建築物飲料水貯水槽清掃業の貯水槽清掃作業監督者","建築物空気調和用ダクト清掃業のダクト清掃作業監督者","建築物飲料水水質検査業の水質検査実施者"],"a":4,"e":"飲料水水質検査業の水質検査実施者は、薬剤師や、大学等で化学などの課程を修めた人などに限られ、管理技術者の免状だけでは認められない。","l":"建築物衛生法施行規則(建築物飲料水水質検査業の登録基準)","c":""},{"id":"2023-12","s":0,"q":"事業の登録について、最も不適当なものはどれか。","o":["建物の環境衛生の維持管理業務を行うには、登録を受けなければならない。","登録を受けるには、物的要件・人的要件・その他の要件が一定の基準を満たしていなければならない。","登録の有効期間は6年で、6年を超えて登録業者だと表示したい場合は、新たに登録を受けなければならない。","登録を受けていない者が、登録業者やそれに似た表示をすることは禁止されている。","建築物の衛生管理業務を営む者の質を高めることを目的に、建築物衛生法の施行後に導入された制度である。"],"a":0,"e":"事業の登録は任意の制度で、登録を受けなくても維持管理業務を行うことはできる。登録を受けていない者は「登録業者」と表示できないだけである。","l":"建築物衛生法 第12条の2、第12条の3","c":""},{"id":"2023-13","s":0,"q":"特定建築物などへの立入検査について、最も不適当なものはどれか。","o":["都道府県知事等の立入検査を拒んだ人は、30万円以下の罰金に処せられる。","都道府県知事等に報告を求められて応じなかった人は、30万円以下の罰金に処せられる。","都道府県知事等は、必要に応じて、犯罪捜査のために立入検査を行うことができる。","保健所は、特定建築物でなくても、多くの人が使う建物には環境衛生上必要な指導ができる。","都道府県知事等は、管理基準に従った維持管理がされておらず、環境衛生上とても不適当な事態があるときは、改善命令や使用停止などの処分ができる。"],"a":2,"e":"立入検査の権限は、犯罪捜査のために認められたものと解釈してはならないと定められている。","l":"建築物衛生法 第11条第2項(第7条の15第3項の準用)","c":""},{"id":"2023-14","s":0,"q":"国や地方公共団体が使う特定建築物について、誤っているものはどれか。","o":["特定建築物の届出をしなければならない。","建築物環境衛生管理基準を守らなければならない。","建築物環境衛生管理技術者を選任しなければならない。","都道府県知事等は、立入検査を行うことができる。","都道府県知事等は、改善命令などの代わりに勧告を行うことができる。"],"a":3,"e":"国や地方公共団体の特定建築物には、立入検査の規定は適用されない。都道府県知事等は、説明や資料の提出を求めることができる。","l":"建築物衛生法 第13条","c":""},{"id":"2023-15","s":0,"q":"感染症法について、誤っているものはどれか。","o":["感染症の発生を予防し、広がるのを防いで、公衆衛生の向上と増進を図ることを目的としている。","国と地方公共団体は、感染症の患者などの人権を尊重しなければならない。","厚生労働大臣は、基本指針に沿って予防計画を定めなければならない。","国民は、感染症について正しい知識をもち、予防に必要な注意を払うよう努めなければならない。","感染症とは、一類〜五類感染症、新型インフルエンザ等感染症、指定感染症、新感染症をいう。"],"a":2,"e":"予防計画を定めるのは都道府県である。厚生労働大臣が定めるのは基本指針。","l":"感染症法 第9条、第10条","c":""},{"id":"2023-16","s":0,"q":"平成30年12月の水道法改正について、最も不適当なものはどれか。","o":["人口減少による水需要の減少、水道施設の老朽化、深刻な人材不足などの課題に対応し、水道の基盤を強くするために改正された。","水道事業者どうしの広域的な連携や統合を進めることで、上水道事業者の数を具体的にいくつ減らすかの目標を設定した。","国は、広域連携の推進を含む、水道の基盤を強化するための基本方針を定めることとした。","地方公共団体が国の許可を受けて、水道施設の運営権を民間事業者に設定できる仕組みを導入した。","指定給水装置工事事業者の指定に、更新制を導入した。"],"a":1,"e":"この改正では広域連携の推進が盛り込まれたが、事業者数をいくつ減らすかという具体的な削減目標は設定されていない。","l":"水道法(平成30年法律第92号による改正)","c":"選択肢(4)の許可権者は、出題当時「厚生労働大臣」だったが、2024年4月から水道行政が国土交通省に移ったため「国の許可」と書き換えた(正答は変わらない)。"},{"id":"2023-17","s":0,"q":"公衆浴場法について、最も不適当なものはどれか。","o":["公衆浴場とは、温湯・潮湯・温泉などを使って、公衆を入浴させる施設をいう。","浴場業とは、都道府県知事等の許可を受けて、業として公衆浴場を経営することをいう。","営業者は、浴槽の中をひどく不潔にする入浴者に対して、その行為をやめさせなければならない。","公衆浴場の営業許可は、厚生労働大臣が規則で定める構造設備の基準・適正配置の基準に従っていなければならない。","公衆浴場の運営は、都道府県等の条例で定める換気・採光・照明・保温・清潔などの衛生・風紀の基準に従っていなければならない。"],"a":3,"e":"この記述が誤り。公衆浴場の設置の場所や構造設備の基準は、厚生労働大臣の規則ではなく、都道府県等が条例などで定める。","l":"公衆浴場法 第2条、第3条","c":""},{"id":"2023-18","s":0,"q":"環境省が公表している令和元年度以降の大気汚染の常時監視結果で、大気環境基準の達成率が最も低いものはどれか。","o":["光化学オキシダント","浮遊粒子状物質","一酸化炭素","二酸化窒素","微小粒子状物質"],"a":0,"e":"光化学オキシダントの環境基準の達成率は、ほぼ0%と極めて低い状態が続いている。ほかの物質はほぼ100%に近い。","l":"法令外(環境省 大気汚染状況の常時監視結果)","c":""},{"id":"2023-19","s":0,"q":"法令とその規制の対象の組合せとして、誤っているものはどれか。","o":["下水道法 ― 一定規模以上の飲食店の厨房の排水に含まれるノルマルヘキサン抽出物質の量","水質汚濁防止法 ― 一定規模以上の合併処理浄化槽の排水の生物化学的酸素要求量(BOD)","大気汚染防止法 ― 一定規模以上のボイラーの排ガスに含まれる硫黄酸化物","温泉法 ― 一定規模以上の温泉施設の排水の水素イオン濃度(pH)","ダイオキシン類対策特別措置法 ― 一定規模以上の廃棄物焼却炉の排ガスに含まれるダイオキシン類の量"],"a":3,"e":"温泉施設(旅館業の温泉施設など)の排水のpHを規制するのは水質汚濁防止法であり、温泉法は温泉の保護や利用の適正化を定める法律である。","l":"温泉法 第1条、水質汚濁防止法","c":""},{"id":"2023-21","s":1,"q":"環境基準と閾値について、最も不適当なものはどれか。","o":["環境基準には、人の健康を守るうえで望ましい基準と、生活環境を守るうえで望ましい基準がある。","閾値とは、反応が起こる最小の刺激量のことで、医学的に有害かどうかを判断する根拠となる量である。","環境基準には常に適切な科学的判断を加え、必要な改定をしなければならない。","閾値の考え方を示すHatchの図では、縦軸が化学的因子の量である。","環境基準は、動物実験や疫学調査などから得られた有害な濃度をもとに、安全の余裕を考えて決められている。"],"a":3,"e":"Hatchの図では、横軸が因子の量(負荷量)、縦軸が生体の影響(反応)を表す。","l":"法令外","c":""},{"id":"2023-22","s":1,"q":"環境衛生について、最も不適当なものはどれか。","o":["許容濃度は、一般環境の基準として使ってはならない。","日本産業衛生学会は、労働者の有害物質による健康障害を防ぐため、許容濃度を公表している。","許容濃度以下なら、ほとんどすべての労働者に健康上の悪い影響は見られないと判断される。","有害物の曝露量と、集団の中で反応が出た人の割合との関係を、量-影響関係という。","学校の環境衛生の基準は、学校保健安全法で定められている。"],"a":3,"e":"曝露量と集団の反応率の関係は「量-反応関係」という。量-影響関係は、曝露量と個体に出る影響の程度との関係である。","l":"法令外","c":""},{"id":"2023-23","s":1,"q":"体の臓器系とその障害・病気の組合せとして、最も不適当なものはどれか。","o":["造血器系 ― 再生不良性貧血","消化器系 ― 肝硬変","呼吸器系 ― 肺気腫","神経系 ― 甲状腺機能低下症","循環器系 ― 動脈硬化症"],"a":3,"e":"甲状腺機能低下症は、ホルモンを出す内分泌系の病気であり、神経系の病気ではない。","l":"法令外","c":""},{"id":"2023-24","s":1,"q":"体温調節での熱をつくること(熱産生)と熱を逃がすこと(熱放散)について、最も不適当なものはどれか。","o":["基礎代謝とは、眠っているときのエネルギー代謝のことをいう。","暑い環境では汗をかいたり血流量が増えたりして、代謝量が上がる。","熱をつくる量は体の活動によって変わり、作業量が増えると増える。","日本人の基礎代謝は、冬より夏のほうが低い。","寒い環境では、震えによって熱をつくる量が増える。"],"a":0,"e":"基礎代謝は、目が覚めている状態で、安静にして横になっているときの生命維持に必要な最小限のエネルギー代謝である。睡眠時の代謝はこれより低い。","l":"法令外","c":""},{"id":"2023-25","s":1,"q":"高齢者と温度環境について、最も不適当なものはどれか。","o":["一般に、若い人より暖かい温度を好むとされる。","寒さを感じとる感受性は、若い人より高い傾向にある。","冬の深部体温は、若い人より低い傾向にある。","放射熱がない場合、高齢者の8割が満足する気温の範囲は、青年より狭い。","寒い環境にさらされたときの血圧の変動が、若い人より大きい。"],"a":1,"e":"高齢者は寒さを感じとる感受性が低下しているため、寒さに気づきにくい。","l":"法令外","c":""},{"id":"2023-26","s":1,"q":"ヒトの温熱的な快適さに影響する因子として、最も不適当なものはどれか。","o":["室内の気流","室内の相対湿度","室内の二酸化炭素濃度","着衣量","季節"],"a":2,"e":"二酸化炭素濃度は空気の汚れの指標であり、暑い・寒いといった温熱的な快適さを決める因子ではない。","l":"法令外","c":""},{"id":"2023-27","s":1,"q":"ヒトのがんについて、最も不適当なものはどれか。","o":["ヒトのがんの3分の2以上は、食事や喫煙などの生活習慣が原因とされる。","がんは日本の死因の第1位で、高齢化にともなって死亡者数が増え続けている。","プロモータは、最初にDNAに傷をつけて変異を起こさせる物質である。","ウイルスががんの原因になることがある。","ホルムアルデヒドには発がん性が認められる。"],"a":2,"e":"最初にDNAに傷をつけるのはイニシエータである。プロモータは、傷のついた細胞の増殖を促す物質。","l":"法令外","c":""},{"id":"2023-28","s":1,"q":"アレルギーについて、最も不適当なものはどれか。","o":["アレルギーは、ヒトにとって有害な免疫反応である。","アレルギー反応が出るのには、体内の肥満細胞のはたらきが関係するものがある。","湿度が低いことは、気管支喘息を悪化させる要因である。","予防には、ダニやカビが増えないよう換気や清掃をすることが大切である。","建築物衛生法で、ダニまたはダニアレルゲンの基準が定められている。"],"a":4,"e":"ダニまたはダニアレルゲンの基準が定められているのは学校保健安全法(学校環境衛生基準)であり、建築物衛生法には定めがない。","l":"建築物衛生法施行令 第2条、学校環境衛生基準","c":""},{"id":"2023-29","s":1,"q":"建物の室内空気と環境について、最も不適当なものはどれか。","o":["ふつうの室内環境では、窒素による体への健康影響はない。","一般的な室内空気の酸素濃度は、約21%である。","良い室内空気環境を保つには、1人あたり10m³/h以上の換気量が必要である。","建築物衛生法では、粒径(相対沈降径)がおおむね10μm以下の粉じんを測定の対象にしている。","花粉は、エアロゾル粒子として室内にあることがある。"],"a":2,"e":"二酸化炭素濃度を1,000ppm以下に保つための必要換気量は、1人あたり約30m³/hとされ、10m³/hでは足りない。","l":"法令外","c":""},{"id":"2023-30","s":1,"q":"建築物衛生法のホルムアルデヒドの量の基準値として、正しいものはどれか。","o":["0.08mg/m³以下","0.1mg/m³以下","0.15mg/m³以下","0.5mg/m³以下","1mg/m³以下"],"a":1,"e":"建築物環境衛生管理基準では、ホルムアルデヒドの量は空気1m³につき0.1mg以下とされている。","l":"建築物衛生法施行令 第2条第1号イ","c":""},{"id":"2023-31","s":1,"q":"オゾンについて、最も不適当なものはどれか。","o":["水に溶けにくい。","紫外線による光化学反応でできる。","日本産業衛生学会は、作業環境でのオゾンの許容濃度を示している。","吸い込むと肺の奥まで届き、肺気腫を起こすことがある。","においがない(無臭である)。"],"a":4,"e":"オゾンには特有の生ぐさいにおい(刺激臭)がある。","l":"法令外","c":""},{"id":"2023-32","s":1,"q":"健康増進法について、最も不適当なものはどれか。","o":["特定施設の管理権原者は、法で決められた禁煙エリアに、灰皿などの喫煙用の器具・設備を使える状態で置いてはならない。","特定施設の管理権原者は、禁煙エリアでたばこを吸っている人に、喫煙をやめるか禁煙エリアから出るよう求めるよう努めなければならない。","病院や学校は、たばこの煙が流れ出ないための技術的基準を満たしていても、屋内に喫煙場所を設けることはできない。","受動喫煙を防ぐため、罰則の規定が設けられている。","加熱式たばこは、規制の対象にならない。"],"a":4,"e":"加熱式たばこも健康増進法の規制の対象である。","l":"健康増進法 第28条","c":""},{"id":"2023-33","s":1,"q":"音について、最も不適当なものはどれか。","o":["音は最終的に聴神経を通って大脳に伝わり、音として認識される。","同じ音でも、聞く人によって心地よい音にも騒音にもなる。","ヒトが聞きとれる音の周波数の範囲は、およそ20Hz〜20kHzといわれる。","音の伝わり方の「気導」とは、空気の振動による音が鼓膜を通して伝わることである。","騒音職場などの定期健康診断の聴力検査では、ふるい分け(スクリーニング)として500Hzと2,000Hzの聴力レベルを測る。"],"a":4,"e":"定期健康診断の聴力検査のスクリーニングでは、1,000Hzと4,000Hzの聴力を測る。","l":"労働安全衛生規則 第44条(騒音障害防止のためのガイドライン)","c":""},{"id":"2023-34","s":1,"q":"騒音とその影響について、最も不適当なものはどれか。","o":["騒音性難聴と加齢性難聴は、医学的に別のものである。","長い間騒音にさらされると、だんだん会話の音域の聴力も落ちていく。","騒音性難聴は、中耳での音の伝わりが障害されて起こる。","環境騒音の基準は、住民の心理的な影響や聞きとりの妨げ、睡眠の妨げなどを参考に決められる。","会話の声のレベルから騒音のレベルを引いた値が20dB以上あれば、十分に聞きとれる。"],"a":2,"e":"騒音性難聴は、内耳の有毛細胞が傷つくことで起こる感音性の難聴である。","l":"法令外","c":""},{"id":"2023-35","s":1,"q":"振動について、最も適当なものはどれか。","o":["振動レベルの単位はHzで表す。","振動は、全身に分布する交感神経の末端の受容器で感じとられる。","全身振動は、水平方向の振動だけで評価する。","長距離バスやフォークリフトの運転などで、局所振動障害が起こる。","振動が原因の白ろう病では、指が境目のはっきりした青白い状態になる。"],"a":4,"e":"白ろう病(振動障害)では、指の血行が悪くなり、境目のはっきりした蒼白化(レイノー現象)が起こる。振動レベルの単位はdB、乗り物の振動は全身振動。","l":"法令外","c":""},{"id":"2023-36","s":1,"q":"目の構造と、光の知覚・明るさについて、最も不適当なものはどれか。","o":["目の網膜にある視細胞が光を感じとる。","網膜は目の前の方、水晶体より前にある。","黒い輪の切れ目を見て視力を測る方法がある。","室内の適切な照明の量は、使い道によって違う。","物の色は、光が物に当たって反射した光の分光分布によって見える。"],"a":1,"e":"網膜は目の奥(後ろ側)にあり、水晶体を通った光が網膜の上に像を結ぶ。","l":"法令外","c":""},{"id":"2023-37","s":1,"q":"情報機器作業について、最も不適当なものはどれか。","o":["一連続の作業時間は、90分を超えないようにする。","まぶしさ(グレア)を防ぐ照明器具を使う。","最も多い自覚症状は、目のピント調節機能の低下や疲れ、痛み、充血などである。","高齢者は目の調節力が落ちているので、作業に必要な照度に配慮が必要である。","ディスプレイを使う場合、書類の上とキーボードの上の照度は300lx以上にする。"],"a":0,"e":"ガイドラインでは、一連続の作業時間が1時間を超えないようにし、次の作業までに10〜15分の作業休止時間を設けるとされている。","l":"法令外(情報機器作業における労働衛生管理のためのガイドライン)","c":""},{"id":"2023-38","s":1,"q":"電場・磁場・電磁波について、最も不適当なものはどれか。","o":["電磁波は、真空中でも空気中でも光の速さで伝わる。","エネルギーの高いX線やγ線には、電離作用がある。","電場と磁場の振動が伝わっていく波をまとめて電磁波という。","光を波長の長い順に並べると、紫外線が一番長く、次が可視光線で、赤外線が一番短い。","静電場は、電撃や皮膚がチリチリする不快感を起こすことがある。"],"a":3,"e":"波長の長い順は、赤外線 → 可視光線 → 紫外線で、紫外線が一番短い。","l":"法令外","c":""},{"id":"2023-39","s":1,"q":"紫外線について、最も不適当なものはどれか。","o":["紫外線には殺菌作用がある。","紫外線は皮膚の表面近くで吸収される。","紫外線のリスクとして、悪性黒色腫が起こることがある。","紫外線を浴びる作業の一つに、アーク溶接がある。","紫外線を浴びることで起こる白内障は、ガラス工白内障として昔から知られている。"],"a":4,"e":"ガラス工白内障は、赤外線を長年浴び続けることで起こる白内障である。","l":"法令外","c":""},{"id":"2023-40","s":1,"q":"電離放射線について、最も不適当なものはどれか。","o":["放射線の影響を最も受けやすい細胞は、消化管の上皮細胞である。","α線は紙1枚でさえぎることができる。","体に与える影響の単位はシーベルト(Sv)である。","放射線による悪性腫瘍の発生は、確率的影響に分類される。","妊娠の可能性がある女性の骨盤への照射は、月経が始まってから10日以内に行う。"],"a":0,"e":"放射線の影響(感受性)が最も高い細胞はリンパ球である。","l":"法令外","c":""},{"id":"2023-41","s":1,"q":"ヒトと水について、最も不適当なものはどれか。","o":["一般の成人の体内の水分量は、体重の約60%である。","体の水分(体液)のうち、細胞内液は約2/3である。","成人は、不可避尿として1日に最低1L以上の尿を出す必要がある。","一般に、体重あたりの体内の水分量は、女性より男性のほうが多い。","水分の不足が体重の約2%になると、強い渇きを感じる。"],"a":2,"e":"老廃物を出すために最低限必要な不可避尿の量は、1日あたり約0.4〜0.5Lとされ、1L以上ではない。","l":"法令外","c":""},{"id":"2023-42","s":1,"q":"水を介して広がる感染症(水系感染症)の特徴について、最も不適当なものはどれか。","o":["梅雨から夏に集中して起こる。","最初の患者が出てから数日で爆発的に増える。","職業と関係することは少ない。","給水の範囲と一致して起こり、その境目がはっきりしている。","一般に潜伏期間が長い。"],"a":0,"e":"水系感染症は、季節に関係なく発生する。","l":"法令外","c":""},{"id":"2023-43","s":1,"q":"次の感染症のうち、ウイルスによって起こるものはどれか。","o":["発しんチフス","カンジダ症","マラリア","日本脳炎","レプトスピラ症"],"a":3,"e":"日本脳炎はウイルスによる感染症である。発しんチフスはリケッチア、カンジダ症は真菌、マラリアは原虫、レプトスピラ症は細菌(スピロヘータ)による。","l":"法令外","c":""},{"id":"2023-44","s":1,"q":"感染症法で、全数の届出(全数把握)が必要とされる感染症はどれか。","o":["ヘルパンギーナ","A型肝炎","季節性インフルエンザ","手足口病","マイコプラズマ肺炎"],"a":1,"e":"A型肝炎は四類感染症で、診断したすべての医師に届出が義務づけられる全数把握の対象。ほかは五類感染症の定点把握の対象である。","l":"感染症法 第6条、第12条","c":""},{"id":"2023-45","s":1,"q":"5%の次亜塩素酸ナトリウム溶液を水で薄めて、200mg/Lの溶液を10Lつくるとき、必要な5%溶液の量に最も近いものはどれか。","o":["0.4mL","2mL","4mL","20mL","40mL"],"a":4,"e":"必要な有効成分は200mg/L×10L=2,000mg=2g。5%溶液なので 2g÷0.05=40g(約40mL)。","l":"法令外(計算)","c":""},{"id":"2023-46","s":2,"q":"用語と単位の組合せのうち、誤っているものはどれか。","o":["絶対湿度 ― kg/kg(DA)","熱貫流抵抗 ― m²・K/W","輝度 ― cd/m²","音響透過損失 ― dB","比熱 ― kJ/kg(DA)"],"a":4,"e":"比熱は1kgの物質を1K上げるのに必要な熱量なので、単位はkJ/(kg・K)。kJ/kg(DA)は比エンタルピーの単位である。","l":"法令外","c":""},{"id":"2023-47","s":2,"q":"A部材(室内側)とB部材(屋外側)でできた外壁がある。A部材は厚さ14cm・熱伝導率1.4W/(m・K)、B部材は厚さ5cm・熱伝導率0.2W/(m・K)、室内側の熱伝達率は10W/(m²・K)、屋外側の熱伝達率は20W/(m²・K)である。室内と屋外の温度差が20℃のとき、この外壁の単位面積あたりの熱流量として正しいものはどれか。","o":["0.7W/m²","1.4W/m²","10W/m²","40W/m²","56W/m²"],"a":3,"e":"熱貫流抵抗＝1/10＋0.14/1.4＋0.05/0.2＋1/20＝0.1＋0.1＋0.25＋0.05＝0.5m²・K/W。熱流量＝温度差÷熱貫流抵抗＝20÷0.5＝40W/m²。","l":"計算","c":""},{"id":"2023-48","s":2,"q":"湿り空気について述べた次の文のうち、最も不適当なものはどれか。","o":["絶対湿度が一定のまま温度が上がると、相対湿度は下がる。","相対湿度が同じなら、温度が高い方が比エンタルピーは大きい。","乾球温度が同じなら、絶対湿度が高い方が水蒸気圧は高い。","露点温度の湿り空気では、乾球温度と湿球温度は等しい。","比エンタルピーが同じなら、温度が高い方が絶対湿度は高い。"],"a":4,"e":"比エンタルピーは温度の分(顕熱)と水蒸気の分(潜熱)の合計なので、比エンタルピーが同じなら温度が高い方が絶対湿度は低くなる。","l":"法令外","c":""},{"id":"2023-49","s":2,"q":"熱の移動について述べた次の文のうち、最も不適当なものはどれか。","o":["一般に、同じ材料でも水分を多く含むほど熱伝導率は大きくなる。","固体の中を流れる熱流は、その場所の温度勾配に熱伝導抵抗をかけて求める。","一般に、密度の大きい材料ほど熱伝導率は大きい。","中空層の熱抵抗は、ある厚さまでは厚くなるほど大きくなるが、それ以上ではほぼ一定になる。","ガラス繊維などの断熱材の熱伝導率が小さいのは、繊維が内部の空気の流れを妨げるためである。"],"a":1,"e":"熱流は温度勾配に熱伝導率をかけて求める(フーリエの法則)。熱伝導抵抗をかけるのではない。","l":"法令外","c":""},{"id":"2023-50","s":2,"q":"熱放射について述べた次の文のうち、最も不適当なものはどれか。","o":["同じ温度の物体どうしの放射では、物体の放射率と吸収率は等しい。","物体表面の日射吸収率は、放射率と必ずしも等しくならない。","簡略化した放射熱伝達の式では、放射熱伝達率を使う。","常温の物体が出す電磁波は、波長10μm付近の赤外線が中心である。","温度0℃の固体表面は、放射率に関係なく熱放射をしていない。"],"a":4,"e":"絶対温度が0K(－273℃)より高い物体はすべて熱放射をしている。0℃は273Kなので熱放射をしている。","l":"法令外","c":""},{"id":"2023-51","s":2,"q":"流体力学について述べた次の文のうち、最も不適当なものはどれか。","o":["連続の式(質量保存の法則)は、ダクトの中の流体の温度・断面積・流速の積が一定になることを意味する。","無秩序な乱れによって流体のかたまりが混ざり合う流れを乱流という。","ベルヌーイの定理は、流れの力学的エネルギーが保存されるという仮定から導かれる。","レイノルズ数が小さい流れは、粘性の影響が強い流れになる。","ダクトの形が変わることによる圧力損失は、形状抵抗係数と風速の2乗に比例する。"],"a":0,"e":"連続の式は、密度×断面積×流速が一定になること(流れる質量が保存されること)を表す。温度ではない。","l":"法令外","c":""},{"id":"2023-52","s":2,"q":"風上側と風下側に1つずつ開口部がある建築物で、外の自然風だけで換気する場合について述べた次の文のうち、最も不適当なものはどれか。","o":["外の風速が2倍になると、換気量は2倍になる。","換気量は、2つの開口部の風圧係数の差の平方根に比例する。","2つの開口部の面積をどちらも2倍にすると、換気量は4倍になる。","風下側の開口部の風圧係数は、一般に負の値になる。","各開口部の流量係数は、開口部の形に関係する。"],"a":2,"e":"換気量は開口面積に比例するので、両方の開口面積を2倍にすると換気量は2倍になる。4倍にはならない。","l":"法令外","c":""},{"id":"2023-53","s":2,"q":"室内の気流について述べた次の文のうち、最も不適当なものはどれか。","o":["混合換気は、室温より少し低い空調空気を床近くから低速で供給し、天井近くで排気する方式である。","コールドドラフトは、冷たい壁の近くなどで自然対流による下降流が原因で起きることがある。","壁の上部から水平に吹き出す空調方式では、暖房時に居住域に空気のよどみができ、上下の温度差が大きくなりやすい。","天井中央付近から下向きに吹き出す空調方式では、冷房時に冷気が床近くに広がり、室の上部によどみができやすい。","ドラフトとは不快な局部的な気流のことで、風速、気流変動の大きさ、空気温度の影響を受ける。"],"a":0,"e":"床近くから低温の空気を低速で供給し天井近くで排気するのは置換換気の説明(2025年度問53でも置換換気の説明として正しい記述)。混合換気は吹き出した空気を室内全体に混ぜる方式。","l":"法令外","c":""},{"id":"2023-54","s":2,"q":"窓などの開口部で通風するとき、通過風量Qは Q＝ア×√(2÷イ×ウ) と表せる。ア〜ウに入る用語の組合せとして正しいものはどれか。","o":["ア 相当開口面積/イ 空気の密度/ウ 開口部前後の圧力差","ア 開口部前後の圧力差/イ 相当開口面積/ウ 空気の密度","ア 相当開口面積/イ 開口部前後の圧力差/ウ 空気の密度","ア 開口部前後の圧力差/イ 空気の密度/ウ 相当開口面積","ア 空気の密度/イ 相当開口面積/ウ 開口部前後の圧力差"],"a":0,"e":"通過風量は Q＝αA√(2ΔP/ρ)。相当開口面積αAに、圧力差ΔPを密度ρで割って2倍した値の平方根をかける。","l":"法令外","c":""},{"id":"2023-55","s":2,"q":"喫煙室で1時間に15本のたばこが吸われている。室内の一酸化炭素濃度を建築物環境衛生管理基準の6ppm以下に保つために最低限必要な換気量に最も近いものはどれか。ただし、室内は定常状態・完全混合、外気の一酸化炭素濃度は0ppm、たばこ1本あたりの一酸化炭素発生量は0.0004m³/hとする。","o":["40m³/h","66m³/h","600m³/h","1,000m³/h","4,000m³/h"],"a":3,"e":"発生量は15×0.0004＝0.006m³/h。必要換気量＝発生量÷(室内濃度－外気濃度)＝0.006÷(6×10⁻⁶－0)＝1,000m³/h。6ppmは現行の施行令第2条の基準値。","l":"計算(基準値は建築物衛生法施行令 第2条)","c":""},{"id":"2023-56","s":2,"q":"換気と必要換気量について述べた次の文のうち、最も不適当なものはどれか。","o":["必要換気量は、人体への影響、燃焼器具の影響、熱や水蒸気の発生の影響などから決める。","必要換気量は、人体から出る二酸化炭素を基準に求めることが多い。","理論廃ガス量とは、燃料が不完全燃焼したときの廃ガス量のことである。","機械換気は、送風機や排風機などの機械の力で室内の空気を入れ替える。","ハイブリッド換気は、自然換気の省エネルギー性と機械換気の安定性の長所を両方いかした換気方法である。"],"a":2,"e":"理論廃ガス量は、燃料が完全燃焼したときに出る廃ガスの量である。","l":"法令外","c":""},{"id":"2023-57","s":2,"q":"空気の清浄化と換気について述べた次の文のうち、最も不適当なものはどれか。","o":["単位時間に室内に取り入れる外気量を室の容積で割ったものを、空気交換効率という。","換気の目的の一つに、室内の空気と新鮮な空気の入れ替えがある。","単位時間に室内に取り入れる外気量を、(外気による)換気量という。","室内の粉じんは、空調機のエアフィルタで取り除くことができる。","室内のガス状汚染物質はケミカルエアフィルタで除去できるが、基本的には換気が重要である。"],"a":0,"e":"外気量を室の容積で割ったものは換気回数である(2024年度問56でも「換気回数は換気量を室容積で除したもの」が正しい記述)。","l":"法令外","c":""},{"id":"2023-58","s":2,"q":"浮遊粒子の動きにかかわる性質について述べた次の文のうち、最も不適当なものはどれか。","o":["抵抗係数は、ストークス域ではレイノルズ数に反比例する。","電荷をもつ粒子の電気移動度は、粒子の移動速度と電界強度の積である。","球形粒子の拡散係数は、粒径に反比例する。","沈着速度は、単位時間あたりの沈着量を空気中の濃度で割った値である。","球形粒子が重力で落ちるときの終末沈降速度は、粒径の2乗に比例する。"],"a":1,"e":"電気移動度は、粒子の移動速度を電界強度で割った値(単位の電界あたりの移動速度)である。積ではない。","l":"法令外","c":""},{"id":"2023-59","s":2,"q":"個別方式の空気調和設備について述べた次の文のうち、最も不適当なものはどれか。","o":["ビル用マルチパッケージには、同じ室外機の系統でも室内機ごとに冷暖房を選べる冷暖房同時型がある。","圧縮機を動かす力には、電力によるものとガスエンジンによるものがある。","特殊なものを除き、ふつうは外気処理の機能をもたない。","分散設置空気熱源ヒートポンプ方式では、圧縮機のON-OFF制御が主流である。","分散設置水熱源ヒートポンプ方式では、冷房と暖房が混在するときに熱回収運転ができる。"],"a":3,"e":"現在はインバータで圧縮機の回転数を変えて容量を細かく制御する方式が主流である(2024年度問62でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-60","s":2,"q":"定風量単一ダクト方式を図-Aに、冷房最大負荷時の状態変化を図-Bに示す。図-Aの各点に対する図-Bの状態点との組合せとして、最も適当なものはどれか。","o":["a ― ア","b ― ウ","c ― エ","d ― イ","e ― オ"],"a":3,"e":"外気a=オ、室内からの還気e=ウ、その混合b=エ。冷却コイルで冷やして除湿した点c=ア。送風機を通ると少し温まるので、室内へ送る点d=イ。","l":"法令外","c":"","g":["img/2023-60a.png","img/2023-60b.png"]},{"id":"2023-61","s":2,"q":"空気調和方式と、その設備の構成要素の組合せとして、最も不適当なものはどれか。","o":["定風量単一ダクト方式 ― 混合ユニット","変風量単一ダクト方式 ― VAVユニット","ダクト併用ファンコイルユニット方式 ― 還気ダクト","分散設置空気熱源ヒートポンプ方式 ― 室外機","外調機併用ターミナルエアハンドリングユニット方式 ― VAVユニット"],"a":0,"e":"混合ユニットは、冷風と温風の2本のダクトを混ぜる二重ダクト方式で使う機器。定風量単一ダクト方式では使わない。","l":"法令外","c":""},{"id":"2023-62","s":2,"q":"湿り空気の用語について述べた次の文のうち、最も不適当なものはどれか。","o":["顕熱比とは、顕熱の変化量の、全熱の変化量に対する比である。","露点温度とは、湿り空気を冷やしたときに飽和状態になる温度である。","絶対湿度とは、湿り空気中の水蒸気量の、湿り空気全体の質量に対する比である。","相対湿度とは、ある湿り空気の水蒸気分圧の、同じ温度の飽和水蒸気分圧に対する比を百分率で表したものである。","熱水分比とは、比エンタルピーの変化量の、絶対湿度の変化量に対する比である。"],"a":2,"e":"絶対湿度は、水蒸気の質量を乾き空気の質量で割ったもの(単位kg/kg(DA))。湿り空気全体の質量で割るのではない。","l":"法令外","c":""},{"id":"2023-63","s":2,"q":"湿り空気線図上での空調の操作について述べた次の文のうち、最も不適当なものはどれか。","o":["温水コイルを通った空気は単純加熱となり、通る前後で絶対湿度は変わらない。","冷房時の室内熱負荷の顕熱比(SHF)が0.8なら、空調機からの吹出し空気の絶対湿度は室内空気より低くなる。","暖房時に水噴霧加湿を使う場合、給気温度は加湿前の温水コイル出口の温度と等しくなる。","還気と外気を混ぜた状態は、湿り空気線図上で両者の状態点を結んだ直線上にある。","冷水コイルで冷却除湿すると、バイパスする空気があるため、コイル出口の空気の相対湿度は100%にならない。"],"a":2,"e":"水噴霧で加湿すると、水が蒸発するときに熱を奪うので空気の温度は下がる(2025年度問72でも「水噴霧方式は吹出し温度が降下する」が正しい記述)。","l":"法令外","c":""},{"id":"2023-64","s":2,"q":"同じ出力の蒸気圧縮冷凍機と比べたときの、吸収冷凍機の特徴として最も不適当なものはどれか。","o":["機内は真空なので、圧力による破裂のおそれがない。","回転する部分が少なく、騒音や振動が小さい。","特別な運転資格がいらない。","消費電力量が少ない。","排熱の回収・利用に向かない。"],"a":4,"e":"吸収冷凍機は熱(蒸気や温水)で動くので、コージェネレーションなどの排熱を利用しやすい。","l":"法令外","c":""},{"id":"2023-65","s":2,"q":"ボイラについて述べた次の文のうち、最も不適当なものはどれか。","o":["鋳鉄製ボイラは、高温・高圧の蒸気をつくるのに向いている。","炉筒煙管ボイラは、直径の大きな横型ドラムを本体とし、燃焼室と煙管群でできている。","貫流ボイラは、水管壁で囲まれた燃焼室と、水管群による対流伝熱面でできている。","真空式温水発生機は、容量に関係なくボイラの取扱い資格がいらない。","真空式温水発生機は、缶体内を真空に保って水を沸騰させ、熱交換器に熱を伝える。"],"a":0,"e":"鋳鉄製ボイラはもろく、高温・高圧・大容量には向かない(2025年度問66でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-66","s":2,"q":"冷凍機の冷媒とオゾン破壊係数(ODP)の組合せとして、最も不適当なものはどれか。","o":["R11(CFC) ― 1","R32(HFC) ― 0.055","R123(HCFC) ― 0.02","R717(NH3) ― 0","R744(CO2) ― 0"],"a":1,"e":"HFCは塩素を含まないのでオゾン層を壊さず、R32のオゾン破壊係数は0である。","l":"法令外","c":""},{"id":"2023-67","s":2,"q":"熱源方式について述べた次の文のうち、最も不適当なものはどれか。","o":["地域冷暖房システムは、地域内の建築物や施設(需要家)どうしが熱をやりとりして、効率よく熱需要に応える方式である。","ヒートポンプ方式には、1台で冷水か温水、または必要に応じて冷水と温水を同時につくるものがある。","吸収冷凍機＋蒸気ボイラ方式は、空調以外に給湯・洗浄・消毒などで高圧蒸気を使う病院、ホテル、工場などでよく採用される。","コージェネレーション方式は、エンジンなどで発電し、その排熱も回収して使う方式である。","蓄熱システムは、熱源設備でつくった冷熱・温熱を計画的に蓄え、必要なときに必要な量を取り出して使うシステムである。"],"a":0,"e":"地域冷暖房は、地域の熱源プラントでまとめてつくった冷水・温水・蒸気などを、導管で各建築物に供給する方式である。需要家どうしが熱を融通し合う方式ではない。","l":"法令外","c":""},{"id":"2023-68","s":2,"q":"全熱交換器について述べた次の文のうち、最も不適当なものはどれか。","o":["外気負荷を減らすため、空気の顕熱と潜熱を同時に交換する装置である。","回転型では、ロータの回転にともなって排気の一部が給気側に移ることがある。","静止型は、回転型より目詰まりを起こしにくい。","静止型の給気と排気を仕切る板は、熱を伝え湿気を通す材料でできている。","冬も夏も省エネルギー効果が期待できるが、中間期の運転には注意が必要である。"],"a":2,"e":"この記述が誤り。静止型は細かい流路の仕切り板に汚れがたまりやすく、回転型より目詰まりしにくいとはいえない。","l":"法令外","c":""},{"id":"2023-69","s":2,"q":"冷却塔について述べた次の文のうち、最も不適当なものはどれか。","o":["開放型冷却塔は通風抵抗が大きいため、密閉型冷却塔より大きな送風機動力が必要である。","密閉型冷却塔は、電算室やクリーンルームの系統によく使われる。","開放型冷却塔では冷却水の、密閉型冷却塔では散布水の水質管理が重要である。","冷却能力が同じなら、密閉型冷却塔は開放型冷却塔より一般に大型である。","空調用の冷却塔は、おもに冷凍機の凝縮熱を大気に捨てるためにある。"],"a":0,"e":"密閉型はコイルがあるため通風抵抗が大きく、送風機動力も大きい。開放型の方が送風機動力は小さい(2025年度問70でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-70","s":2,"q":"空気調和機について述べた次の文のうち、最も不適当なものはどれか。","o":["エアハンドリングユニットは、熱源設備から送られる冷水・温水・蒸気などで空調空気をつくり、ダクトで各ゾーン・各室に送る。","ターミナルエアハンドリングユニットは、全熱交換器、制御機器、還気送風機などの必要な機器を一体にした空調機である。","ファンコイルユニットは、送風機、熱交換器、エアフィルタとケーシングでできた室内設置用の小型空調機である。","パッケージ型空調機は、圧縮機、膨張弁、蒸発器、凝縮器などでできている。","ヒートポンプ型のパッケージ型空調機は、熱をくみ取る源によって水熱源と空気熱源に分けられる。"],"a":1,"e":"この記述が誤り。ターミナルエアハンドリングユニットは、ゾーンごとに置く小型のエアハンドリングユニットで、全熱交換器や還気送風機を一体にした空調機ではない。","l":"法令外","c":""},{"id":"2023-71","s":2,"q":"空気調和設備の加湿装置と除湿装置について述べた次の文のうち、最も不適当なものはどれか。","o":["冷却除湿機は、空気を露点温度以下に冷やして水蒸気を凝縮させて取り除く。","吸収式除湿機は、塩化リチウムなどの吸収剤を使う湿式の除湿装置である。","蒸気式加湿器では、水に含まれる微生物が放出されて空気質が悪くなることがある。","吸着式除湿機は、シリカゲルなどの固体吸着剤に水蒸気を吸着させて除湿する。","気化式加湿器では、温度が下がる。"],"a":2,"e":"蒸気式加湿器は水を沸騰させた蒸気を使うので、微生物を放出するおそれはない。微生物の放出が問題になるのは水噴霧式などである。","l":"法令外","c":""},{"id":"2023-72","s":2,"q":"送風機について述べた次の文のうち、最も不適当なものはどれか。","o":["送風機は吐出し圧力の大きさによってファンとブロワに分けられ、空調用の送風機はファンにあたる。","遠心式送風機では、空気が軸方向から入り、軸に対して斜めに通り抜ける。","送風系の抵抗曲線は、ダクトの形やダンパの開き具合が変わると変化する。","軸流式送風機では、空気が羽根車に軸方向から入り、軸方向に通り抜ける。","横流式送風機では、空気が羽根車の外周の一部から入り、反対側の外周の一部へ通り抜ける。"],"a":1,"e":"遠心式送風機は、軸方向から入った空気を羽根車の回転で半径方向(外周方向)に送り出す。軸に対して斜めに通り抜けるのは斜流式である。","l":"法令外","c":""},{"id":"2023-73","s":2,"q":"ダクトと付属品について述べた次の文のうち、最も不適当なものはどれか。","o":["低圧ダクトの流速の範囲は15m/s以下である。","フレキシブル継手は、ダクトと吹出口や消音ボックスなどをつなぐとき、位置を合わせるために使う。","可変風量ユニットの動作形式には、絞り式とバイパス式がある。","風量調整ダンパは、モータダンパでも、ダンパそのものの構造は手動ダンパと同じである。","丸ダクトは、スパイラルダクトに比べ、はぜによって高い強度が得られる。"],"a":4,"e":"らせん状のはぜで補強されているスパイラルダクトの方が強度が高い。丸ダクトの方が強いのではない。","l":"法令外","c":""},{"id":"2023-74","s":2,"q":"吹出口について述べた次の文のうち、最も不適当なものはどれか。","o":["アネモスタット型吹出口は、誘引効果が高く、ムラの少ない温度分布が得られる。","ノズル型吹出口は、広がる角度が大きく到達距離が短い。","ライン型吹出口は、ペリメータ負荷の処理のため窓際に設置されることが多い。","天井パネル型吹出口は、面状吹出口に分類される。","グリル型吹出口は、軸流吹出口に分類される。"],"a":1,"e":"ノズル型は軸流吹出口の一種で、広がる角度が小さく到達距離が長い(2025年度問73でも「軸流吹出口は到達距離が長い」が正しい記述)。","l":"法令外","c":""},{"id":"2023-75","s":2,"q":"空気調和設備のポンプ・配管・付属品について述べた次の文のうち、最も不適当なものはどれか。","o":["バタフライ弁は、軸を回すと弁体が開閉する構造である。","軸流ポンプは遠心ポンプに比べ、全揚程は小さいが吐出し量が多い。","伸縮継手は、温度変化による配管の軸方向の伸び縮みを吸収するためのものである。","玉形弁は、流量の調整に使われる。","蒸気トラップは、機器や配管内で発生した高い蒸気圧力をすばやく外に逃がすための安全装置である。"],"a":4,"e":"蒸気トラップは、蒸気を通さずに凝縮水(ドレン)だけを排出する装置。圧力を逃がす安全装置は安全弁である。","l":"法令外","c":""},{"id":"2023-76","s":2,"q":"パッケージ型空調機方式で使う外気処理ユニットについて述べた次の文のうち、最も不適当なものはどれか。","o":["ビル用マルチパッケージと同じ冷媒配管の系統に接続できる。","取り入れた外気を加熱・冷却できる。","取り入れた外気は、加湿されたあとで直膨コイルを通る。","全熱交換器を組み込んだユニットである。","給気と排気の風量のバランスに注意が必要である。"],"a":2,"e":"外気はまず直膨コイルで冷却・加熱され、そのあとで加湿される。コイルの下流に加湿器を置くのが標準の順番(2025年度問69参照)。","l":"法令外","c":""},{"id":"2023-77","s":2,"q":"浮遊粉じんの測定法と測定器について述べた次の文のうち、最も不適当なものはどれか。","o":["浮遊粉じんを浮かんだまま測る方法に、吸光光度法がある。","浮遊粉じんを捕集して測る方法に、フィルタ振動法がある。","デジタル粉じん計は、粉じんが散乱させた光の波長から相対濃度を測る。","建築物環境衛生管理基準にもとづきローボリウムエアサンプラ法を使うときは、分粒装置を付ける必要がある。","デジタル粉じん計は、経年劣化などがあるので、定期的に較正する必要がある。"],"a":2,"e":"デジタル粉じん計は、散乱光の強さ(量)から相対濃度を測る。光の波長ではない。","l":"法令外","c":""},{"id":"2023-78","s":2,"q":"環境要素の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["グローブ温度は、室内の気流速度が小さくなるほど平均放射温度に近づく傾向がある。","超音波風速計は、超音波の強さと気流の関係を利用している。","電気抵抗式湿度計は、感湿部の電気抵抗が吸湿や脱湿で変わることを利用している。","バイメタル式温度計は、2種類の金属の膨張率の違いを利用している。","アスマン通風乾湿計の乾球温度は、一般に湿球温度より高い値を示す。"],"a":1,"e":"超音波風速計は、超音波が伝わる時間が気流によって変わることを利用している。超音波の強さではない。","l":"法令外","c":""},{"id":"2023-79","s":2,"q":"汚染物質と、その濃度または強さを表す単位の組合せとして、最も不適当なものはどれか。","o":["アセトアルデヒド ― μg/m³","オゾン ― cfu/m³","粉じん ― mg/m³","硫黄酸化物 ― ppm","アスベスト ― 本/L"],"a":1,"e":"cfu(コロニー形成単位)は細菌などの微生物の数を表す単位。オゾンの濃度はppmなどで表す。","l":"法令外","c":""},{"id":"2023-80","s":2,"q":"室内空気環境の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["一酸化炭素の測定法に、定電位電解法がある。","二酸化炭素の測定法に、非分散型紫外線吸収法がある。","窒素酸化物の測定法に、吸光光度法がある。","イオウ酸化物の測定法に、紫外線蛍光法がある。","オゾンの測定法に、紫外線吸収法がある。"],"a":1,"e":"二酸化炭素は赤外線を吸収する性質を利用した非分散型赤外線吸収法で測る。紫外線ではない。","l":"法令外","c":""},{"id":"2023-81","s":2,"q":"ホルムアルデヒドの簡易測定法として、最も不適当なものはどれか。","o":["検知管法","光電光度法","燃料電池法","化学発光法","β線吸収法"],"a":4,"e":"β線吸収法は浮遊粉じんの測定法である(2025年度問80でも正しい記述として出題)。ホルムアルデヒドの測定には使わない。","l":"法令外","c":""},{"id":"2023-82","s":2,"q":"空気調和設備の維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["冷却水系のレジオネラ属菌の増殖を抑えるには、化学的洗浄と殺菌剤の添加を組み合わせるのが望ましい。","空気調和設備の空気を送る系統では、使用年数がたつにつれてダクト内部の清掃を考える必要がある。","建築物環境衛生管理基準では、冷却塔の清掃は1年以内ごとに1回、定期に行う。","建築物環境衛生管理基準では、加湿装置は使用開始時と使用期間中の1か月以内ごとに1回、定期に汚れを点検し、必要に応じて清掃などを行う。","建築物環境衛生管理基準では、空気調和設備内の排水受けは6か月以内ごとに1回、定期に汚れと詰まりを点検し、必要に応じて清掃などを行う。"],"a":4,"e":"排水受けの点検は、使用開始時と使用開始後1か月以内ごとに1回(施行規則第3条の18第4号)。冷却塔の清掃1年以内ごと、加湿装置の点検1か月以内ごとも同条のとおり。","l":"建築物衛生法施行規則 第3条の18","c":""},{"id":"2023-83","s":2,"q":"音について述べた次の文のうち、最も不適当なものはどれか。","o":["音圧レベルは、人が聞き取れる最小の音圧を基準として定めた尺度である。","騒音レベルは、人の聴覚の周波数による感じ方の違いを考えた騒音の大きさの尺度である。","時間で変動する騒音は、等価騒音レベルで評価する。","空気調和機から出た音が隔壁のすき間などを通り抜けてくる音は、固体伝搬音である。","遮音とは、壁などで音をさえぎり、通り抜ける音のエネルギーを小さくすることである。"],"a":3,"e":"すき間などを空気中を伝わって通り抜けてくる音は空気伝搬音である(2024年度問87でも同じ内容が正答)。","l":"法令外","c":""},{"id":"2023-84","s":2,"q":"騒音と振動について述べた次の文のうち、最も不適当なものはどれか。","o":["不規則で大きく変動する振動の表し方として、時間率レベルが示されている。","回折減衰の効果を利用した振動対策として、防振溝がある。","道路交通振動の規制は、昼間より夜間の方が厳しい。","低い周波数の騒音に対する人の感度は低い。","低い周波数の全身振動より、高い周波数の全身振動の方が感じやすい。"],"a":4,"e":"人は全身振動では低い周波数の方を感じやすい。高い周波数の方が感じやすいのではない。","l":"法令外","c":""},{"id":"2023-85","s":2,"q":"騒音レベル80dBと86dBの騒音を合成したときの騒音レベルに最も近いものはどれか。ただし log10 2＝0.3010、log10 3＝0.4771、log10 5＝0.6990とする。","o":["83dB","86dB","87dB","89dB","166dB"],"a":2,"e":"L＝10log10(10^8.0＋10^8.6)。10^0.6≒4(log10 4＝0.602)なので、10^8＋4×10^8＝5×10^8。L＝10×(8＋0.699)≒87dB。","l":"計算","c":""},{"id":"2023-86","s":2,"q":"騒音・振動問題の対策について述べた次の文のうち、最も不適当なものはどれか。","o":["新築の建物で使い始めた直後、騒音・振動が設計目標値を満たしているのに出るクレームは、保守管理責任の範囲ではない。","外の騒音が同じなら、コンサートホールやオペラハウスの方が録音スタジオより高い遮音性能が求められる。","空気伝搬音を減らすには、窓・壁・床などで遮音する必要がある。","送風機の音や振動が年数とともに問題になっていないか確かめるため、ベルトのゆるみなどを定期的に点検する。","寝室の騒音では、骨伝導で感じる固体伝搬音も評価する必要がある。"],"a":1,"e":"わずかな雑音も録音されてしまう録音スタジオの方が、コンサートホールなどより高い遮音性能が求められる。","l":"法令外","c":""},{"id":"2023-87","s":2,"q":"光と照明について述べた次の文のうち、最も不適当なものはどれか。","o":["照明器具の不快グレアの程度を表すUGRは、値が大きいほどまぶしさの程度が大きい。","設計用全天空照度は、快晴より薄曇りの方が高い。","色温度が高くなると、光の色は青→白→黄→赤と変わる。","演色評価数が100に近い光源ほど、基準の光で照らしたときに近い色を再現できる。","事務所の製図作業では、文書作成作業より高い維持照度が求められる。"],"a":2,"e":"色温度が低いと赤っぽく、高くなるにつれて赤→黄→白→青と変わる。順番が逆である。","l":"法令外","c":""},{"id":"2023-88","s":2,"q":"ある部屋の作業面に必要な照度が750lxである。ランプ1本あたりの光束が3,000lmのとき、必要なランプの数に最も近いものはどれか。ただし床面積は100m²、照明率は0.6、保守率は0.75とする。","o":["15灯","25灯","34灯","42灯","56灯"],"a":4,"e":"光束法:灯数＝照度×床面積÷(1灯の光束×照明率×保守率)＝750×100÷(3,000×0.6×0.75)＝75,000÷1,350≒55.6≒56灯。","l":"計算","c":""},{"id":"2023-89","s":2,"q":"照明に関する次の用語のうち、建築化照明に分類されないものはどれか。","o":["システム天井照明","コードペンダント","ルーバー照明","コーニス照明","コーブ照明"],"a":1,"e":"建築化照明は天井や壁などの建築と一体にした照明。コードペンダントはコードで天井から吊り下げる照明器具で、建築化照明ではない。","l":"法令外","c":""},{"id":"2023-90","s":2,"q":"空気調和設備のコミッショニングに関連する用語として、あてはまらないものはどれか。","o":["BEMS","性能検証","BCP","運用最適化","FPT"],"a":2,"e":"コミッショニングは設備の性能を検証し運用を最適にする取組み。BCPは災害時などの事業継続計画で、コミッショニングの用語ではない。","l":"法令外","c":""},{"id":"2023-91","s":3,"q":"CASBEE(建築環境総合性能評価システム)の評価対象の分野に含まれていないものはどれか。","o":["エネルギー消費","火災安全","資源循環","地域環境","室内環境"],"a":1,"e":"CASBEEの評価分野は、エネルギー消費・資源循環・地域環境・室内環境の4つで、火災安全は含まれない。","l":"法令外","c":""},{"id":"2023-92","s":3,"q":"建築物と都市環境について、最も不適当なものはどれか。","o":["両側を高い建物で連続して囲まれ、半分閉じた空間のようになった道路空間を、ストリートキャニオンという。","熱容量が大きい材料は、日射の熱をためこみやすい。","内水氾濫による都市型洪水は、環境基本法で定義される公害の一つである。","都市化によって、都市の中心部の気温が郊外より高くなる現象をヒートアイランド現象という。","無計画な開発などで市街地が広がっていくことを、スプロール現象という。"],"a":2,"e":"環境基本法の公害は、大気汚染・水質汚濁・土壌汚染・騒音・振動・地盤沈下・悪臭の7つで、都市型洪水は含まれない。","l":"環境基本法 第2条第3項","c":""},{"id":"2023-93","s":3,"q":"鉄筋コンクリート構造とその材料について、最も不適当なものはどれか。","o":["セメントペーストは、砂・セメント・水を練り混ぜたものである。","梁に設ける設備配管用の穴の径は、一般に梁せいの1/3以下とする。","コンクリートと鉄筋の線膨張係数は、ほぼ等しい。","柱の帯筋比は、0.2%以上とする。","中性化している部分の、コンクリート表面からの距離を中性化深さという。"],"a":0,"e":"セメントペーストは水とセメントを練り混ぜたもの。砂を加えたものはモルタルである。","l":"法令外","c":""},{"id":"2023-94","s":3,"q":"鉄骨構造とその材料について、最も不適当なものはどれか。","o":["梁には、形鋼や鋼板を組み立てた材などが使われる。","鋼材の強さは温度が上がると下がり、1,000℃でほとんど0になる。","鉄骨構造はさびに弱いので、さび止めの処理が必要である。","骨組の耐火被覆の厚さは、必要な耐火時間に応じて決める。","鋼材の炭素量が増えると、一般に溶接しやすくなる。"],"a":4,"e":"鋼材は炭素量が増えると硬く強くなるが、溶接性は悪くなる。","l":"法令外","c":""},{"id":"2023-95","s":3,"q":"建築物の荷重と構造力学について、最も不適当なものはどれか。","o":["教室の床の構造計算に使う積載荷重は、一般に事務室より大きく決められている。","地震力は、地震で建物が揺れることで生じる慣性力である。","片持ち梁に分布荷重がかかる場合、その先端にはせん断力は生じない。","支点には、固定端・回転端(ピン)・移動端(ローラー)の3種類がある。","風圧力は、時間とともに変わる動的な荷重である。"],"a":0,"e":"床の構造計算用の積載荷重は、教室が2,300N/m²、事務室が2,900N/m²で、教室のほうが小さい。","l":"建築基準法施行令 第85条","c":""},{"id":"2023-96","s":3,"q":"建築材料と部材の性質について、最も不適当なものはどれか。","o":["コンクリートの混和材には、フライアッシュ・高炉スラグ・シリカヒュームなどがある。","単板積層材(LVL)は、主に柱や梁に使われる。","一般に、コンクリートのひび割れ幅が0.1〜0.2mm以上になると、鉄筋の腐食がひどくなる。","鋼材は、どの方向にも同じ性質をもつ等方性材料である。","木材の含水率は、水分を含んだ状態の木材の質量を、絶乾質量で割った割合をいう。"],"a":4,"e":"木材の含水率は、木材に含まれる「水分の質量」を絶乾質量で割った割合である。","l":"法令外","c":""},{"id":"2023-97","s":3,"q":"建築物の電気設備について、最も不適当なものはどれか。","o":["実効値100Vの交流電圧は、ピーク時の電圧が約140Vである。","受変電設備の変圧器の容量は、建物内の電気設備の負荷をすべて足した値以上にするのが一般的である。","電線の配電距離が長くなると、電圧が下がる。","磁束密度は、電流の強さとコイルの巻き数の積に比例する。","建物の設備機械の動力には、三相誘導電動機が多く使われている。"],"a":1,"e":"すべての機器が同時に最大で使われることはないため、変圧器の容量は負荷の合計に需要率などをかけて決め、一般に合計値より小さくなる。","l":"法令外","c":""},{"id":"2023-98","s":3,"q":"建築設備について、最も不適当なものはどれか。","o":["LPガスの容器は一般に鋼板製が多く、高圧ガス保安法による検査合格の刻印があるものなどでなければ使えない。","エスカレーターの公称輸送能力は、定格速度と踏段の幅で決まる。","受変電設備とは、電力会社から送られた高圧の電気を受けて、決められた電圧に下げ、建物内で安全に使えるようにする設備である。","非常用エレベーターを複数設ける場合は、まとまった位置に設けるのがよい。","エレベーターの安全装置は、建築基準法で定められている。"],"a":3,"e":"非常用エレベーターを2基以上設ける場合は、避難上・消火上有効な間隔をあけて配置する。","l":"建築基準法施行令 第129条の13の3","c":""},{"id":"2023-99","s":3,"q":"建築設備について、最も不適当なものはどれか。","o":["自動火災報知設備は、主に感知器・受信機・非常ベルなどでできている。","避雷設備は、高さ18mを超える建物に設けることが義務づけられている。","建築基準法により、高さ31mを超える建物(政令で定めるものを除く)には、非常用の昇降機を設けなければならない。","勾配が30度を超え35度以下のエスカレーターの定格速度は、30m/分以下とされている。","非常用照明装置は、停電をともなう災害のときに、利用者を安全に避難させるための設備である。"],"a":1,"e":"避雷設備の設置が義務づけられているのは、高さ20mを超える建築物である。","l":"建築基準法 第33条","c":""},{"id":"2023-100","s":3,"q":"火災の性質(火災性状)について、最も不適当なものはどれか。","o":["フラッシュオーバーは、火元から部屋全体へ一気に燃え広がる現象である。","火災のとき階段などの竪穴区画に煙が入ると、煙突効果で上の階へ急速に煙が広がるおそれがある。","減光係数は、煙の有毒性を数値で評価するための指標である。","火災のとき室内の上の方にできる高温の煙の層は、火の勢いを強める要因の一つである。","プルームは、火元の上にできる、燃焼をともなわない熱い気流のことである。"],"a":2,"e":"減光係数は、煙によって光がどれだけ弱まるか(煙の濃さ・見通し)を表す指標であり、有毒性の指標ではない。","l":"法令外","c":""},{"id":"2023-101","s":3,"q":"地震とその防災対策について、最も不適当なものはどれか。","o":["耐震診断は、建築物の耐震改修の促進に関する法律に定められている。","Jアラートは、緊急の気象関係の情報や有事の情報を、国から住民などに伝えるシステムである。","マグニチュードが1大きくなると、エネルギーは約30倍になる。","気象庁震度階級は地震の揺れの強さを示す指標で、7つの階級に分けられている。","耐震診断が義務づけられている「要安全確認計画記載建築物」には、都道府県や市町村が指定する緊急輸送道路などの避難路沿いの建物が含まれる。"],"a":3,"e":"気象庁震度階級は、震度0・1・2・3・4・5弱・5強・6弱・6強・7の10階級である。","l":"法令外","c":""},{"id":"2023-102","s":3,"q":"消火設備について、最も適当なものはどれか。","o":["地球環境の問題から、現在はトリフルオロメタン(HFC-23)などがハロンの代わりの消火剤として使われている。","連結散水設備は、一般の人が操作しやすい消火設備である。","連結送水管設備では、高置水槽がある場合、建物の高さが70mを超えてもブースターポンプはいらない。","屋内消火栓設備には1号消火栓と2号消火栓があり、工場や倉庫には2号消火栓を設ける。","消火器の消火能力を表す能力単位は、家庭用消火器の能力を「1」とした相対値で決められる。"],"a":0,"e":"オゾン層を壊すハロンの代わりに、HFC-23などの代替消火剤が使われている。連結散水設備・連結送水管は消防隊が使う設備で、工場・倉庫には1号消火栓を設ける。","l":"法令外","c":""},{"id":"2023-103","s":3,"q":"法令で定められた建物の防火・防災の管理体制について、最も不適当なものはどれか。","o":["管理権原者が複数いる防火対象物では、共同防火管理の体制をつくる必要がある。","一定規模の建物では、事業所や建物の単位で資格をもつ防火管理者を選び、消防計画をつくる必要がある。","指定数量以上の危険物がある防火対象物では、防火管理者として危険物取扱者を選ばなければならない。","建築基準法令で定める特定建築物は、建築物調査・防火設備検査・建築設備検査の定期報告の対象になる。","大規模な事業所では、防火管理者・自衛消防組織に加えて、大地震などに備えた防災管理者を置く必要がある。"],"a":2,"e":"この記述が誤り。防火管理者を危険物取扱者から選ぶ義務はない(危険物の保安は、危険物保安監督者などの別の仕組みで管理する)。","l":"消防法 第8条","c":""},{"id":"2023-104","s":3,"q":"建築基準法の用語について、最も不適当なものはどれか。","o":["床面積とは、建物の各階またはその一部で、壁などの区画の屋外側(外壁の外側)の線で囲まれた部分の水平投影面積のことである。","容積率(延べ面積/敷地面積)の制限では、一定の割合までの自動車車庫・駐車場などの面積を延べ面積から差し引ける。","居室とは、人がある程度長い時間使い続ける部屋で、階段・廊下・洗面所など一時的に使うものは含まない。","主要構造部には、建物の基礎や土台は含まれない。","耐火性能とは、通常の火災が終わるまでの間、その火災による建物の倒壊や延焼を防ぐために、建物の部分に必要な性能をいう。"],"a":0,"e":"床面積は、壁その他の区画の「中心線」で囲まれた部分の水平投影面積で求める。","l":"建築基準法施行令 第2条第1項第3号","c":""},{"id":"2023-105","s":3,"q":"建築物の維持管理に関する略語と内容の組合せとして、最も不適当なものはどれか。","o":["PFI ― 民間主導の公共サービス事業","BIM ― ビルエネルギー管理システム","POE ― 建物を使う人の視点からの性能評価","LCCM ― 建物の一生に必要なすべての費用の管理","ESCO ― 省エネルギー診断からシステム設計、効果の検証までを提供する、エネルギーの総合サービス事業"],"a":1,"e":"BIMは、コンピュータ上に建物の3次元モデルをつくり、設計から維持管理まで情報を活用する手法(ビルディング・インフォメーション・モデリング)である。ビルエネルギー管理システムはBEMS。","l":"法令外","c":""},{"id":"2023-106","s":4,"q":"給水・排水の管理に関する用語と説明の組合せとして、最も不適当なものはどれか。","o":["バルキング ― 排水槽の底に沈んだ固形物や油脂などが集まったもの","自己サイホン作用 ― 器具排水管の中を排水が満流で流れるとき、サイホンの原理でトラップの封水が引かれ、残る封水が少なくなる現象","クロスコネクション ― 上水(飲料水)の系統とほかの配管系統を、配管や装置で直接つなぐこと","オフセット ― 排水立て管の経路を平行にずらすため、エルボやベンド継手でつくる移行部分","ポンプのインバータ制御 ― 周波数を変えてモータの回転数を変え、送水量を調整する方法"],"a":0,"e":"バルキングは、活性汚泥が沈降しにくくなる現象である(2020年問107で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2023-107","s":4,"q":"給水・排水の管理に関する用語の組合せとして、最も不適当なものはどれか。","o":["トリハロメタン ― 有機物と消毒用の塩素が反応してできる物質","バイオフィルム ― 微生物がつくるぬるぬるした物質","白濁水 ― 銅イオンが溶け出すこと","水質汚濁 ― 富栄養化","スケール ― 炭酸カルシウムや炭酸マグネシウムなどの析出物"],"a":2,"e":"白濁水は、亜鉛めっき鋼管の亜鉛の腐食生成物が水に混ざって白くにごるものである(2024年問110で正しい記述として出題)。銅イオンの浸出で起こるのは青水。","l":"法令外","c":""},{"id":"2023-108","s":4,"q":"水道施設に関する記述として、最も不適当なものはどれか。","o":["取水施設の場所を選ぶときは、水量と水質に気を配る必要がある。","浄水処理は、一般に沈殿・ろ過・消毒の3段階からなる。","緩速ろ過法は、沈殿池で土砂などを沈めたあと、緩速ろ過池で4〜5m/日の速度でろ過する方法である。","送水施設は、浄水施設から配水施設まできれいにした水を送るための施設である。","配水池に必要な容量は、計画1日最大給水量の8時間分を標準とする。"],"a":4,"e":"配水池の必要容量を「計画1日最大給水量の8時間分」とした記述が誤り。","l":"法令外","c":""},{"id":"2023-109","s":4,"q":"給水設備に関する記述として、最も不適当なものはどれか。","o":["配水管から給水管が分かれる箇所では、配水管の最小動水圧として150kPa以上を確保する。","水道法の水質基準で、一般細菌の基準値は、検水1mLでできる集落数が100以下である。","水道法の水質基準で、総トリハロメタンの基準値は0.1mg/L以下である。","水道法の水質基準で、鉛及びその化合物の基準値は0.05mg/L以下である。","一般の水栓に必要な水圧は、30kPaである。"],"a":3,"e":"鉛及びその化合物の基準値は、鉛の量として0.01mg/L以下である(水質基準に関する省令)。一般細菌(100以下)と総トリハロメタン(0.1mg/L以下)は現行の基準どおり。","l":"水質基準に関する省令(表)","c":""},{"id":"2023-110","s":4,"q":"給水設備で使う貯水槽に関する記述として、最も不適当なものはどれか。","o":["鋼板製の貯水槽は、さび止めの被膜がどれだけ傷んでいるかを定期的に点検する必要がある。","FRP製の貯水槽は、腐食に強い。","FRP製の貯水槽は、耐震などの機械的な強度が高い。","ステンレス鋼板製の貯水槽は、表面がきれいで汚れも付きにくい。","木製の貯水槽は、断熱性に優れている。"],"a":2,"e":"FRP製貯水槽は機械的強度が低く、耐震補強が必要である(2025年問111で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-111","s":4,"q":"給水設備に関する記述として、最も不適当なものはどれか。","o":["飲料用の貯水槽の上には、原則として飲料水の配管以外の機器や配管を設けてはならない。","ウォータハンマ防止器は、防止器が壊れないよう、急に閉まる弁などから十分に離れた場所に設ける。","貯水槽の流入管は、ボールタップや電極棒による水位の制御に支障がないよう、波立ちを防ぐ対策をする。","厨房の給水配管は、防水層をつらぬかないようにする。","水の使用量が極端に減る期間がある建物の貯水槽では、少ない量をためるための水位制御電極もつけ、使用量に合わせて水位設定を切り替えて使う。"],"a":1,"e":"ウォータハンマ防止器は、ウォータハンマが起こる場所の近くに設ける(2016年問111・2024年問113で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-112","s":4,"q":"給水設備に関する記述として、最も不適当なものはどれか。","o":["高層ホテルのゾーニングでの給水の上限水圧は、0.3MPaである。","小便器洗浄弁に必要な水圧は、70kPaである。","節水器具を使う事務所の1日あたりの設計給水量は、70〜100L/人である。","給水配管の管径は、管内の流速が2.0m/s以下になるように選ぶ。","高置水槽の有効容量は、一般に1日最大使用水量の1/10である。"],"a":2,"e":"節水器具を使う事務所の1日あたり設計給水量は40〜60L/人である(2024年問112・2025年問115で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-113","s":4,"q":"給水設備に使う配管と、その接合方法の組合せとして、最も不適当なものはどれか。","o":["合成樹脂ライニング鋼管 ― ねじ接合(管端防食継手の場合)","銅管 ― 差込みろう接合","ステンレス鋼管 ― メカニカル形接合","硬質ポリ塩化ビニル管 ― 融着接合","架橋ポリエチレン管 ― メカニカル形接合"],"a":3,"e":"硬質ポリ塩化ビニル管は接着接合でつなぐ(2025年問112で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2023-114","s":4,"q":"飲料用貯水槽の清掃に関する記述として、最も不適当なものはどれか。","o":["清掃のときは、必要に応じてガード付きの作業灯を付け、槽内で安全に作業できる明るさを確保する。","高置水槽と受水槽の清掃は原則として同じ日に行い、受水槽を清掃したあとに高置水槽を清掃する。","清掃が終わったら、2回以上貯水槽の中を消毒する。","消毒後の水洗いと水張りは、消毒が終わってから少なくとも30分以上たってから行う。","清掃後の水質検査で、濁度の基準値は5度以下である。"],"a":4,"e":"清掃後の水張り時の検査で、濁度の基準は2度以下である(色度が5度以下)。受水槽→高置水槽の順、2回以上の消毒も告示どおり(平成15年厚生労働省告示第119号 第2)。","l":"平成15年厚生労働省告示第119号 第2の一の1","c":""},{"id":"2023-115","s":4,"q":"給水設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["貯水槽の定水位弁や電極棒などの付属装置が正しく動かないと、断水や溢水(あふれ)事故が起こることがある。","給水ポンプの軸受部がグランドパッキンの場合は、水滴が落ちていないことを確認する。","管更生工法の一つに、合成樹脂ライニングによる工法がある。","給水ポンプの電流値がふらついている場合は、異物をかみ込んでいるなどの可能性がある。","受水槽の水位制御の作動点検は、槽内のボールタップを手で動かして行う。"],"a":1,"e":"グランドパッキンの場合に「水滴が落ちていないこと」を確認するとした記述が誤り。","l":"法令外","c":""},{"id":"2023-116","s":4,"q":"給湯設備に使う配管に関する記述として、最も不適当なものはどれか。","o":["循環式給湯設備で下向き配管方式とする場合、給湯横主管は下り勾配にする。","耐熱性硬質ポリ塩化ビニル管の線膨張係数は、ポリブテン管より大きい。","自然循環方式は、配管の形が複雑な中央式給湯設備には向かない。","返湯管の管径は給湯循環ポンプの循環量から決めるが、一般には給湯管の半分程度である。","局所給湯方式で、加熱装置から給湯する場所までが短い場合は、単管式で配管する。"],"a":1,"e":"耐熱性硬質ポリ塩化ビニル管の線膨張係数がポリブテン管より大きい、とした記述が誤り。","l":"法令外","c":""},{"id":"2023-117","s":4,"q":"給湯設備の省エネルギーに関する記述として、最も不適当なものはどれか。","o":["部分負荷を考えて、エネルギー効率の高い熱源機器を選ぶ。","エネルギーと水を節約するため、湯と水を別々の水栓から出さずに混合水栓を使う。","配管の経路を短くする。","中央式給湯方式の循環ポンプは連続運転せず、給湯管(往き管)の温度が下がったときに動かす。","排水から熱を回収する場合は、熱交換器の腐食などで湯が汚れないよう、間接熱交換方式にする。"],"a":3,"e":"循環ポンプは、返湯管の温度が下がったときに作動させる(2016年問120で正しい記述として出題)。往き管の温度ではない。","l":"法令外","c":""},{"id":"2023-118","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["スリーブ形伸縮管継手の伸縮を吸収できる量は、最大200mm程度である。","中央式給湯設備の末端の給湯温度は、使用のピーク時でも55℃以上にする。","事務所用途の建物の1日あたりの設計給湯量は、30L/人程度である。","耐熱性硬質塩化ビニルライニング鋼管の使用温度は、85℃以下とする。","ガス瞬間湯沸器の能力表示の1号とは、流量1L/minの水の温度を25℃上げる能力である。"],"a":2,"e":"事務所の1日あたりの設計給湯量を30L/人程度とした記述が誤り。","l":"法令外","c":""},{"id":"2023-119","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["密閉式膨張水槽を設ける場合は、逃し弁も設ける。","加熱装置から逃し管を立ち上げる場合は、水を供給する高置水槽の水面よりも高く立ち上げる。","湯を均等に循環させるため、返湯管に定流量弁を設ける。","SUS444製の貯湯槽には、腐食を防ぐために電気防食を施す。","配管内の空気や水が抜けやすいように、凹凸のある配管にはしない。"],"a":3,"e":"SUS444製の貯湯槽には電気防食を施してはならない(2020年問123で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-120","s":4,"q":"給湯設備の循環ポンプに関する記述として、最も不適当なものはどれか。","o":["ポンプは、背圧に耐えられるものを選ぶ。","ポンプの循環流量は、加熱装置での給湯温度と返湯温度の差に比例する。","ポンプの揚程は、循環管路で最も大きくなる管路の摩擦抵抗・局部抵抗による圧力損失から決める。","ポンプには、液体にふれる部分をステンレス鋼製にしたものが多く使われている。","ポンプで脈動による騒音や振動が起きた場合の対応として、ポンプの吐出し側にサイレンサなどを付ける。"],"a":1,"e":"循環流量は、給湯温度と返湯温度の差に反比例する(2017年問118で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-121","s":4,"q":"給湯設備の保守管理の内容と、その実施頻度の組合せとして、最も不適当なものはどれか。","o":["第一種圧力容器の定期自主検査 ― 6か月以内ごとに1回","第二種圧力容器の定期自主検査 ― 1年以内ごとに1回","小型圧力容器の定期自主検査 ― 1年以内ごとに1回","シャワーヘッドの定期点検 ― 6か月に1回以上","給湯配管類の管洗浄 ― 1年に1回以上"],"a":0,"e":"第一種圧力容器の定期自主検査は1か月以内ごとに1回行う(ボイラー及び圧力容器安全規則第67条)。第二種圧力容器(第88条)と小型圧力容器(第94条)は1年以内ごとに1回。","l":"ボイラー及び圧力容器安全規則 第67条・第88条・第94条","c":""},{"id":"2023-122","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["中央式給湯方式では、加熱によって残留塩素がなくなることがあるので、水質に注意する。","開放式の貯湯槽では、外から汚れが入る経路になりやすいマンホールの気密性や、オーバフロー管の防虫網がきちんとしているかなどを点検する。","給湯水の流量を調節するには、仕切弁を使う。","あまり使わない給湯栓は、定期的にたまった水を出し、給湯温度を測る。","給湯循環ポンプは、作動の確認をかねて定期的に分解・清掃する。"],"a":2,"e":"流量の調節には仕切弁ではなく玉形弁が向いている(2023年問75で「玉形弁は流量調整用として用いられる」が正しい記述、2016年問114で「仕切弁は玉形弁より流量調整に適している」が誤りとして出題)。","l":"法令外","c":""},{"id":"2023-123","s":4,"q":"雑用水設備に関する記述として、最も不適当なものはどれか。","o":["雑用水とは、人が飲むことやそれに準じる用途以外に使われる水をまとめた呼び名である。","散水・修景・清掃に使う雑用水には、し尿を含む水を原水として使わない。","広域循環方式は、個別循環方式に比べて下水道への排水量が少なくなる。","雑用水受水槽に上水を補給するときは、吐水口空間を設けて給水する。","雑用水は、災害時の非常用水の原水として使うことができる。"],"a":2,"e":"広域循環方式は下水処理場の処理水を再利用するもので、個別循環方式より下水道への排水量が減るわけではない(2016年問124でも「広域循環方式で下水道への負荷が軽減される」は誤りとして出題)。なお(2)は施行規則第4条の2の定めどおり。","l":"建築物衛生法施行規則 第4条の2(選択肢2)","c":""},{"id":"2023-124","s":4,"q":"排水再利用設備の維持管理に関する記述として、最も不適当なものはどれか。","o":["スクリーンでは、汚物がたまらないようにその都度取り除く。","流量調整槽では、ポンプが正常に動き、決められた流量を保つよう調整する。","活性炭処理装置では、水を通す速度を適正に保つ。","ろ過装置では、ろ材の洗浄がきちんと行われているかを点検する。","消毒槽では、フロックのでき具合が最もよい状態かを確認する。"],"a":4,"e":"消毒槽で「フロックの形成状態」を確認するとした記述が誤り。","l":"法令外","c":""},{"id":"2023-125","s":4,"q":"建築物衛生法施行規則で定める雑用水の水質基準の項目と基準のうち、誤っているものはどれか。","o":["臭気 ― 異常でないこと","pH値 ― 5.8以上8.6以下であること","大腸菌 ― 検出されないこと","塩化物イオン ― 200mg/L以下であること","濁度 ― 2度以下であること"],"a":3,"e":"雑用水の基準項目は、pH値・臭気・外観・大腸菌・濁度(散水・修景・清掃用)で、塩化物イオンは入っていない(施行規則第4条の2)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2023-126","s":4,"q":"排水の水質に関する記述として、最も不適当なものはどれか。","o":["全窒素は、アンモニア性窒素・亜硝酸性窒素・硝酸性窒素の合計である。","浮遊物質(SS)は、試料を孔径1μmのガラスファイバろ紙でこし、乾かしたろ紙の上に残ったものの重さで表す。","溶存酸素(DO)は、水に溶けている分子状の酸素である。","生物化学的酸素要求量(BOD)は、主に水中の有機物が好気性微生物に分解されるときに使われる酸素の量を表す。","流れ込むリン化合物は、生活排水・畜産排水・工場排水などに由来する。"],"a":0,"e":"全窒素は、有機性窒素も含めた、有機性窒素・アンモニア性窒素・亜硝酸性窒素・硝酸性窒素の総和である(2025年問127で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-127","s":4,"q":"排水トラップと阻集器に関する語句の組合せとして、最も不適当なものはどれか。","o":["ドラムトラップ ― 非サイホントラップに分類","雨水トラップ ― ルーフドレンからの悪臭を防ぐ","オイル阻集器 ― ガソリンや油類が流れ出るのを止め、分けて集める","わんトラップ ― サイホントラップに分類","砂阻集器 ― 土砂・石粉・セメントなどが流れ出るのを止め、分けて集める"],"a":3,"e":"わんトラップはサイホントラップではなく、非サイホントラップに分類される(2016年問128でも「わんトラップ ― サイホントラップ」は誤りの組合せとして出題)。","l":"法令外","c":""},{"id":"2023-128","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["排水管の掃除口の間隔は、管径100mm以下の場合15m以内とする。","排水トラップの脚断面積比(流出脚の断面積/流入脚の断面積)が大きくなると、封水強度は大きくなる。","飲料用水槽で、管径75mmの間接排水管に設ける排水口空間は、最小150mmとする。","ドーム状のルーフドレンのストレーナ部分の開口面積は、つながる排水管の断面積の2倍程度必要である。","管径125mmの排水横管の最小勾配は、1/200である。"],"a":4,"e":"管径125mmの排水横管の最小勾配は1/150である(2024年問129で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-129","s":4,"q":"排水通気配管に関する記述として、最も不適当なものはどれか。","o":["排水横管から通気管を取り出すときは、排水管の断面の垂直中心線の上部から45°以内の角度で取り出す。","ループ通気管は、いちばん上流の器具排水管が排水横枝管につながる位置のすぐ下流から立ち上げ、通気立て管につなぐ。","結合通気管は、通気立て管と排水横枝管の間に設ける通気管で、排水立て管内の圧力をやわらげる。","通気立て管の下部は、排水立て管につながる最も低い排水横枝管より低い位置で、排水立て管から取り出す。","排水立て管と排水横主管の接続部には、大曲がりベンドなどを使う。"],"a":2,"e":"結合通気管は、排水立て管から分かれて立ち上げ、通気立て管につなぐ管で、排水立て管内の圧力変動をやわらげる(2022年問129で正しい記述として出題)。排水横枝管との間に設ける管ではない。","l":"法令外","c":""},{"id":"2023-130","s":4,"q":"排水管の掃除口と排水ますに関する記述として、最も不適当なものはどれか。","o":["雨水ますの底には150mm程度の泥だめを設け、土砂などが下水道へ流れ出るのを防ぐ。","排水管の管径が125mmの場合、掃除口の口径は75mmとする。","雨水ますの流出管は、流入管より管底を20mm程度下げて設ける。","敷地排水管の直管が長い場合、排水ますは管内径の120倍を超えない範囲に設ける。","排水管が45°を超える角度で向きを変える箇所には、掃除口を設ける。"],"a":1,"e":"排水管の管径が125mmの場合、掃除口の口径は100mmとする(2021年問132で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-131","s":4,"q":"排水槽と排水ポンプに関する記述として、最も不適当なものはどれか。","o":["排水用の水中ポンプは、吸込みピットの壁面から200mm以上離して設置する。","排水槽のマンホールは、水中ポンプやフート弁の真上に設ける。","即時排水型ビルピット設備は、排水槽の悪臭防止に効果がある。","排水槽の底の勾配は、吸込みピットに向かって1/15以上1/10以下とする。","汚物ポンプの最小口径は、40mmとする。"],"a":4,"e":"汚物ポンプの最小口径を40mmとした記述が誤り。","l":"法令外","c":""},{"id":"2023-132","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["自然流下式の排水横管の勾配は、管内の流速が0.6〜1.5m/sになるように設ける。","排水立て管のオフセット部の上下600mm以内には、排水横枝管を設けてはならない。","排水槽のマンホールの大きさは、直径60cm以上の円が内接できるものとする。","トラップが組み込まれていない阻集器には、その入口側にトラップを設ける。","伸頂通気方式の排水横主管の水平曲がりは、排水立て管の底部から3m以内に設けてはならない。"],"a":3,"e":"トラップが組み込まれていない阻集器には、出口側にトラップを設ける(2025年問132で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-133","s":4,"q":"排水設備の清掃と診断に関する記述として、最も不適当なものはどれか。","o":["スネークワイヤ法は、排水管の中のグリースなどの固い付着物を取り除くのに使う方法である。","酸性洗浄剤は、小便器の配管の尿石を取り除くのに使う。","ウォータラム法は、洗浄ノズルから高圧の水を噴き出し、その勢いで排水管の中を洗う方法である。","ロッド法は、1〜1.8mのロッドをつなぎ、手で排水管に入れて清掃する方法である。","排水管内部の腐食の診断には、内視鏡のほか超音波厚さ計などが使われる。"],"a":2,"e":"ウォータラム法は、圧縮空気を一気に放出し、その衝撃で詰まりを取り除く方法である(2016年問134・2022年問133で正しい記述として出題)。高圧の水を噴射するのは高圧洗浄法。","l":"法令外","c":""},{"id":"2023-134","s":4,"q":"排水設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["排水用水中ポンプのメカニカルシールは、1〜2年に1回程度交換する。","グリース阻集器では、2か月に1回程度、槽内の底や壁などに付いたグリースや沈殿物を取り除く。","排水槽の清掃は、6か月以内ごとに1回行う。","高圧洗浄による排水管の清掃では、5〜30MPaの圧力の水を噴射して洗う。","排水ポンプは1か月に1回絶縁抵抗を測り、1MΩ以上あることを確かめる。"],"a":1,"e":"グリース阻集器の槽内の底や壁面に付いたグリースの清掃は、1か月に1回程度行う(2025年問135で正しい組合せとして出題)。なお排水設備の清掃を6か月以内ごとに1回行うことは施行規則第4条の3に定めがある。","l":"建築物衛生法施行規則 第4条の3(選択肢3)","c":""},{"id":"2023-135","s":4,"q":"衛生器具設備に関する記述として、最も不適当なものはどれか。","o":["大便器洗浄弁に必要な水圧は、50kPaである。","温水洗浄便座への給水には、上水を使う。","衛生器具は、給水器具・水受け容器・排水器具・付属品の4つに分けられる。","洗面器の取り付け状態は、2か月に1回、定期に点検する。","大便器の洗浄水量は、JIS A 5207で、Ⅰ形が8.5L以下と区分されている。"],"a":0,"e":"大便器洗浄弁に必要な水圧は70kPaである(2024年問112・2025年問136で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-136","s":4,"q":"小便器に関する記述として、最も不適当なものはどれか。","o":["壁掛型は、駅やホテルの共用部などで、床を掃除しやすいことから選ばれている。","床置型は洗浄する面が広いので、きちんと洗浄しないと臭いが出る。","小便器のリップの高さとは、床面からあふれ縁までの垂直距離をいう。","自動感知洗浄弁には、便器と分かれた型と、便器と一体になった型がある。","使用頻度の高い公衆便所用の小便器の排水トラップは、小便器と一体のものが向いている。"],"a":4,"e":"使用頻度の高い公衆便所用小便器のトラップを「小便器一体のものが適している」とした記述が誤り(2017年問135でも同じ記述が誤りとして出題)。","l":"法令外","c":""},{"id":"2023-137","s":4,"q":"環境省関係浄化槽法施行規則第1条の2(放流水の水質の技術上の基準)で定めるBODの値として、正しいものはどれか。","o":["20mg/L以下","30mg/L以下","60mg/L以下","90mg/L以下","120mg/L以下"],"a":0,"e":"浄化槽からの放流水のBODは20mg/L以下で、BOD除去率は90%以上と定められている(環境省関係浄化槽法施行規則第1条の2)。","l":"環境省関係浄化槽法施行規則 第1条の2","c":""},{"id":"2023-138","s":4,"q":"浄化槽の単位装置である接触ばっ気槽の点検項目として、最も不適当なものはどれか。","o":["水温","pH","ばっ気部分の泡立ち","MLSS濃度","生物膜の付き具合"],"a":3,"e":"MLSSはばっ気槽の混合液の浮遊物質で、活性汚泥の量の指標である(2020年問127)。接触ばっ気槽では生物膜の状況を点検する(2020年問139で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2023-139","s":4,"q":"特殊設備に関する記述として、最も不適当なものはどれか。","o":["入浴設備の打たせ湯には、循環している浴槽の水を使う。","HACCP方式は、原材料の受入れから最終製品の出荷までの各段階のリスク分析にもとづき、重要管理点を決めて連続的に監視する、安全確保のための衛生管理手法である。","プール水の消毒設備では、塩素剤に加えてオゾン消毒や紫外線消毒を併用する例がある。","文部科学省は学校給食施設に、厨房の床をドライシステム(ドライフロア)にするよう求めている。","水景設備は、水がもつ親水機能や環境調整機能で空間を演出するものである。"],"a":0,"e":"打たせ湯には、循環している浴槽水を使わない(2022年問139で正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-140","s":4,"q":"消火設備に関する記述として、最も不適当なものはどれか。","o":["消火器は、火災を見つけた初期の段階で消火するためのものである。","泡消火設備は、消火薬剤の負触媒作用を主とした消火方法である。","不活性ガス消火設備は、不活性ガスを放出して酸素濃度を下げることを主とした消火方法である。","閉鎖型スプリンクラー設備は、火災が起きるとヘッドが熱を感じて散水し、初期消火する。","屋外消火栓には、消火栓弁・ホース・ノズルを内蔵した屋外消火栓箱型、地下ピット格納型、地上スタンド型がある。"],"a":1,"e":"負触媒作用を主とするのはハロゲン化物消火設備である(2024年問140で正しい組合せとして出題)。泡消火設備の説明としては誤り。","l":"法令外","c":""},{"id":"2023-141","s":5,"q":"「建築物における衛生的環境の維持管理について」(平成20年1月25日 健発第0125001号)に示された建築物環境衛生維持管理要領について述べた次の文のうち、最も不適当なものはどれか。","o":["清掃は、建築物の用途、使用状況、劣化状況、建築資材などを考えた年間作業計画と作業手順書をつくり、それにもとづいて行うこと。","清掃に使う洗剤や床維持剤は、利用者や清掃従事者などの健康と環境に配慮し、建築資材に合ったものを使い、適切に使用・管理すること。","建築物内で出る廃棄物の分別・収集・運搬・貯留は、安全で衛生的かつ効率的な方法で速やかに処理すること。","清掃用資機材の保管庫の中は整頓されて清潔で、ねずみや昆虫などがすみついたり出入りしたりしていないこと。","建築物衛生法施行規則第20条の帳簿書類には、清掃・点検・整備の予定表、作業内容、実施者の名簿などを記載すること。"],"a":4,"e":"この記述が誤り(要領に示された内容と異なる)。","l":"法令外(建築物環境衛生維持管理要領)","c":""},{"id":"2023-142","s":5,"q":"建築物衛生法施行規則に定める建築物清掃業の登録基準の内容として、最も不適当なものはどれか。","o":["清掃用機械器具として、真空掃除機と噴霧器をもっていること。","清掃作業に従事するすべての人が、規則に定める研修を修了していること。","清掃作業従事者の研修の内容は、清掃用機械器具・資材の使い方、清掃作業の安全・衛生に関するものであること。","清掃作業の監督を行う人は、厚生労働大臣の登録を受けた者が行う清掃作業監督者講習または再講習を修了して6年を経過していないこと。","清掃作業と清掃用機械器具などの維持管理の方法が、厚生労働大臣が別に定める基準に合っていること。"],"a":0,"e":"登録基準で必要な機械器具は、真空掃除機と床みがき機である(施行規則第25条第1号)。噴霧器ではない。監督者の講習修了後6年以内は同条第2号のとおり。","l":"建築物衛生法施行規則 第25条","c":""},{"id":"2023-143","s":5,"q":"建築物清掃の作業計画について述べた次の文のうち、最も不適当なものはどれか。","o":["廊下の壁のスポット洗浄は、一般に定期清掃で行う。","廊下の壁のスイッチまわりの洗剤拭きは、一般に定期清掃で行う。","エレベーターかご内の除じんは、一般に定期清掃で行う。","階段の手すり拭きは、一般に日常清掃で行う。","トイレ・洗面所の換気口の除じんは、一般に定期清掃で行う。"],"a":2,"e":"エレベーターかご内は利用が多く汚れやすいので、除じんは毎日の日常清掃で行う。","l":"法令外","c":""},{"id":"2023-144","s":5,"q":"建築物清掃の作業計画をつくる利点について述べた次の文のうち、最も不適当なものはどれか。","o":["日常清掃で取る汚れと定期的に取る汚れを分けて計画すると、作業の効率と成果が上がる。","現場の状況に合わせて作業者が計画を変えて作業すると、限られた時間で一定の成果が得られる。","作業内容がはっきりするので、統一した指導ができる。","作業者と作業内容を計画的に管理し記録を残すことで、責任の所在がはっきりする。","実施内容をデータとしてためて作業を改善すると、効率化につながる。"],"a":1,"e":"作業者がその場で計画を変えてしまうと、計画にもとづく管理ができなくなる。計画どおりに作業することが作業計画の利点である。","l":"法令外","c":""},{"id":"2023-145","s":5,"q":"建築物清掃の資機材保管庫について述べた次の文のうち、最も不適当なものはどれか。","o":["照明設備や空気調和設備などを設け、衛生面にも配慮して手洗い場なども設ける。","清掃作業を効率よく進めるには、建築物の規模に合った専用の資機材保管庫が必要である。","エレベーターなどに近く、資機材を運びやすい場所に設ける。","保管しやすいように、建築物の規模や形に関係なく、資機材保管庫は1か所にまとめる。","床や壁は水を通さない材料にする。"],"a":3,"e":"大きな建築物では資機材の移動に時間がかかるので、規模や形に応じて保管庫を分散して設ける。1か所にまとめるのではない。","l":"法令外","c":""},{"id":"2023-146","s":5,"q":"建築物清掃の品質評価について述べた次の文のうち、最も不適当なものはどれか。","o":["品質評価は、利用者の立場に立って行う。","清掃の実施結果を点検し、利用者が求める品質と実際の品質の差を修正する。","仕様書にもとづき、適正な作業計画に沿って業務がきちんと行われているかを点検する。","清掃の品質は、組織品質と作業品質でできている。","品質評価項目のうち資機材管理は、組織品質の中の事業所管理品質に含まれる。"],"a":4,"e":"資機材管理は現場で行う管理なので、事業所管理品質ではなく現場管理品質に含まれる。","l":"法令外","c":""},{"id":"2023-147","s":5,"q":"ほこりや汚れの除去について述べた次の文のうち、最も不適当なものはどれか。","o":["綿布やモップに含ませる水分は、ほこりの付着を高める程度で十分で、多すぎるとかえって害になる。","おがくずを使う方法は、ほこりを付着させる効果が大きい。","ダストコントロール法は、粘度の低い乾性の鉱油などを布に含ませてほこりを取る方法である。","ダストクロス法は、油分による床への悪影響が少ない。","バキュームクリーニングは、カーペットの織り目に入ったほこりや土砂などを取るのに使う。"],"a":2,"e":"ダストコントロール法で布に含ませるのは、乾かない性質の不乾性の鉱油である。乾性の油ではない。","l":"法令外","c":""},{"id":"2023-148","s":5,"q":"カーペットの清掃用機械について述べた次の文のうち、最も不適当なものはどれか。","o":["カーペットスイーパは、パイルの表面の粗いごみを取るのに向いている。","洗剤供給式床磨き機は、ウィルトンカーペットの洗浄に向いている。","スチーム洗浄機は、カーペットのしみ取りにも使われる。","アップライト型真空掃除機は、回転ブラシで床を掃きながら、ごみやほこりを吸い込む構造である。","エクストラクタは、ノズルから洗浄液を吹き付けてすぐに吸い取る構造である。"],"a":1,"e":"ウィルトンカーペットはぬれると縮みやすいため(2025年度問151で正答)、洗剤をたっぷり使う洗剤供給式床磨き機での洗浄には向かない。","l":"法令外","c":""},{"id":"2023-149","s":5,"q":"ビルクリーニング用の機械・器具について述べた次の文のうち、最も適当なものはどれか。","o":["超高速バフ機の回転数は、毎分150〜300回転である。","自動床洗浄機は、洗剤供給式床磨き機と吸水式真空掃除機を組み合わせた構造である。","三つ手ちり取りは、移動するときにごみがこぼれない構造である。","凹凸のある床は、研磨粒子の付いたパッドを床磨き機に付けて洗う。","床磨き機に使うブラシは、直径60cm以上のものが多く使われる。"],"a":1,"e":"自動床洗浄機は、洗剤を出しながらブラシで洗い、その汚水をすぐ吸い取る機械である。凹凸のある床はパッドではなくブラシを使う(2025年度問148参照)。","l":"法令外","c":""},{"id":"2023-150","s":5,"q":"清掃作業で使う洗剤について述べた次の文のうち、最も不適当なものはどれか。","o":["助剤(ビルダ)の働きとして、界面活性剤の表面張力を高めて洗浄力を上げることがある。","水道水で薄めて使う洗剤には、水中のカルシウムやマグネシウムを封じる作用のある助剤が入っている。","洗剤を水道水で薄めるときには、最適な濃度がある。","界面活性剤には、汚れを対象物から引き離す働きがある。","洗剤には酸性やアルカリ性があり、水素イオン濃度指数(pH)で確かめられる。"],"a":0,"e":"この記述が誤り。助剤は界面活性剤の働きを助けて洗浄力を高めるものだが、表面張力を高めるのではない(表面張力が下がるほど汚れにしみ込みやすくなる)。","l":"法令外","c":""},{"id":"2023-151","s":5,"q":"洗剤・床維持剤と、その説明の組合せとして、最も不適当なものはどれか。","o":["フロアシーラ ― 物理的・化学的な方法でも簡単には除去できない","フロアポリッシュ ― ろう状物質","酸性洗剤 ― 油汚れ","表面洗剤 ― 中性またはアルカリ性","剥離剤 ― アルカリ性"],"a":2,"e":"油汚れにはアルカリ性洗剤を使う。酸性洗剤は尿石や水あかなどの無機質の汚れに使う(2025年度問149でも同じ内容が正答)。","l":"法令外","c":""},{"id":"2023-152","s":5,"q":"弾性床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["ゴム系床材は、剥離剤で変色やひび割れなどが起きることがある。","床維持剤を塗ると、汚れが付きにくく、取りやすくなる。","塩化ビニル系床材は、タイルもシートも可塑剤を含む。","リノリウム床材のフロアポリッシュは、アルカリ性の剥離剤で取り除く。","日常清掃では、ダストモップで土砂やほこりを取る。"],"a":3,"e":"リノリウムはアルカリに弱く、アルカリ性の剥離剤で変色などが起きるので注意が必要である(2024年度問150でも同趣旨の記述が正しいとされている)。","l":"法令外","c":""},{"id":"2023-153","s":5,"q":"繊維床の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["ポリプロピレン素材は、復元力が弱い。","ウール素材に付いた汚れはしみになりやすいので、できるだけ早く対応する。","カーペットのほつれは、施工したての時期にカットすればよい。","カーペット全体の調和を保つため、どの場所も同じ頻度で真空掃除機をかける。","パイルの奥の汚れを取るために、シャンプークリーニングを行う。"],"a":3,"e":"出入口付近や通路など、場所によって汚れ方が違うので、汚れやすい場所ほど回数を増やすなど頻度を変える。","l":"法令外","c":""},{"id":"2023-154","s":5,"q":"木質床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["木質床材は、無垢の単層フローリングと、合板を台板にした複合フローリングに分けられる。","体育館の床板がはがれてけがをする事故を防ぐため、日常清掃での水拭きをやめるよう文部科学省から通知が出された。","体育館のシール加工には、ポリウレタン樹脂が多く使われている。","シールされていない杉材は多孔質なので、油性の保護剤でシールする。","一般に、針葉樹の床材は広葉樹の床材より木質が硬い。"],"a":4,"e":"一般に針葉樹の床材は広葉樹より木質が軟らかい(2024年度問153でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-155","s":5,"q":"硬性床材の特徴について述べた次の文のうち、最も適当なものはどれか。","o":["大理石は、アルカリに強い。","テラゾは、酸に強い。","セラミックタイルは、吸水性が低い。","花崗岩は、熱に強い。","コンクリートは、酸に強い。"],"a":2,"e":"セラミックタイルは吸水性が低い(2025年度問152でも正しい記述)。大理石はアルカリ・酸に弱く、テラゾやコンクリートは酸に弱く、花崗岩は熱に弱い(2024年度問152参照)。","l":"法令外","c":""},{"id":"2023-156","s":5,"q":"外装の清掃について述べた次の文のうち、最も不適当なものはどれか。","o":["自動窓拭き機は、人が作業するより天候に左右されにくく、計画的に作業しやすい。","石材や陶磁器タイルの壁は、数年に1回の頻度で洗う。","ロープ高所作業を行う場合、ライフラインの設置は努力義務である。","金属材の洗浄は、汚れが比較的軽く固まらないうちに、中性洗剤や専用洗剤を使ってスポンジやウエスで拭き取る。","窓ガラスは、水やガラス専用洗剤で洗い、スクイジーでかき取る。"],"a":2,"e":"ロープ高所作業では、メインロープとは別にライフラインを設けなければならない(労働安全衛生規則第539条の2)。努力義務ではなく義務である。","l":"労働安全衛生規則 第539条の2","c":""},{"id":"2023-157","s":5,"q":"平成27年度の廃棄物の排出・処理の状況について述べた次の文のうち、最も不適当なものはどれか。","o":["ごみの中間処理量は約4,000万トンで、そのうち約85%が直接焼却されている。","ごみの総排出量は約4,400万トンで、そのうち70%が事業系ごみ、30%が家庭系ごみである。","ごみの総資源化量は約900万トンで、この中には住民団体による集団回収量が含まれている。","産業廃棄物の排出量を業種別に見ると、電気・ガス・熱供給・水道業からの排出量が最も多い。","産業廃棄物の総排出量は約4億トンで、その約53%が再生利用されている。"],"a":1,"e":"家庭系と事業系の割合が逆で、家庭系ごみが約70%、事業系ごみが約30%である(令和4年度の統計を扱った2025年度問157でも家庭系約70%が正しい記述)。統計の数字は年度で変わる。","l":"法令外(環境省の統計)","c":""},{"id":"2023-158","s":5,"q":"ごみの処理について述べた次の文のうち、最も不適当なものはどれか。","o":["一般廃棄物の埋立処分は、安定型最終処分場で行われる。","焼却処理では、容積は5〜10%に減らされる。","ごみ燃料化施設は、選別・乾燥の技術を使っている。","粗大ごみ処理施設は、破砕・選別の技術を使っている。","中間処理の目的には、無害化、資源化、減量化、減容化、安定化がある。"],"a":0,"e":"安定型最終処分場は、廃プラスチック類など腐らない「安定型産業廃棄物」を埋め立てる処分場である(廃棄物処理法施行令第6条)。一般廃棄物は一般廃棄物の最終処分場で埋め立てる。","l":"廃棄物処理法施行令 第6条第1項第3号","c":""},{"id":"2023-159","s":5,"q":"循環型社会形成推進基本法についての次の文の[ア]・[イ]に入る語句の組合せとして、正しいものはどれか。\n「同法第2条で『循環型社会』とは、製品等が廃棄物等になることが抑えられ、製品等が循環資源になった場合は適正に循環的な利用が進められ、循環的な利用が行われない循環資源は適正な処分が確保され、もって[ア]の消費を抑え、[イ]ができる限り減らされる社会をいう。」","o":["ア 循環資源/イ 経済への負担","ア 環境資源/イ 健康への被害","ア 循環資源/イ 環境への負荷","ア 天然資源/イ 健康への被害","ア 天然資源/イ 環境への負荷"],"a":4,"e":"条文は「もって天然資源の消費を抑制し、環境への負荷ができる限り低減される社会」(循環型社会形成推進基本法第2条第1項)。","l":"循環型社会形成推進基本法 第2条第1項","c":""},{"id":"2023-160","s":5,"q":"廃棄物処理法第1条(目的)に定められている項目として、あてはまらないものはどれか。","o":["生活環境の保全","廃棄物の排出抑制","廃棄物の適正処理","公衆衛生の向上","地球環境の保全"],"a":4,"e":"第1条は「廃棄物の排出を抑制し、廃棄物の適正な分別、保管、収集、運搬、再生、処分等の処理をし、生活環境を清潔にすることにより、生活環境の保全及び公衆衛生の向上を図る」と定めており、地球環境の保全は含まれない。","l":"廃棄物処理法 第1条","c":""},{"id":"2023-161","s":5,"q":"廃棄物処理法での産業廃棄物について述べた次の文のうち、最も不適当なものはどれか。","o":["建築物内の医療機関から感染のおそれのある産業廃棄物が出る場合は、その建築物の所有者が特別管理産業廃棄物管理責任者を置かなければならない。","爆発性、毒性、感染性など、人の健康や生活環境に被害を与えるおそれのある性状をもつものとして政令で定める産業廃棄物を、特別管理産業廃棄物としている。","産業廃棄物の処理は、排出事業者が自らの責任で、自分で行うか許可業者に委託して行う。","産業廃棄物を輸出するには環境大臣の確認が必要である。","事業活動で出た廃棄物のうち、燃え殻、汚泥、廃油など20種類が産業廃棄物と定められている。"],"a":0,"e":"特別管理産業廃棄物管理責任者は、その廃棄物を出す事業場を設置している事業者(この場合は医療機関)が事業場ごとに置く(廃棄物処理法第12条の2第8項)。建築物の所有者ではない。","l":"廃棄物処理法 第12条の2第8項","c":""},{"id":"2023-162","s":5,"q":"廃棄物処理法にもとづく廃棄物の区分について述べた次の文のうち、最も不適当なものはどれか。","o":["事務所の建築物から捨てられたスチール机は、産業廃棄物である。","スーパーマーケットから出た紙くずは、一般廃棄物である。","事務所の建築物から捨てられた木製の机は、一般廃棄物である。","店舗から捨てられた発泡スチロールは、一般廃棄物である。","レストランから出た廃てんぷら油は、産業廃棄物である。"],"a":3,"e":"事業活動で出た発泡スチロールは廃プラスチック類にあたり、業種に関係なく産業廃棄物である。","l":"廃棄物処理法 第2条第4項","c":""},{"id":"2023-163","s":5,"q":"産業廃棄物管理票制度(マニフェスト制度)について述べた次の文のうち、最も不適当なものはどれか。","o":["紙マニフェストでは、運搬が終わると中間処理業者からB2票が排出事業者に返送される。","紙マニフェストでは、排出事業者はA票を控えとして保存する。","収集運搬業者を選ぶときは、排出場所と運搬先の両方の自治体の許可をもっているか確かめる。","返送されたマニフェストの伝票は5年間保存する。","電子マニフェストでは、A票、B2票、E票の保存は不要である。"],"a":0,"e":"B2票は、運搬を終えた収集運搬業者から返送される伝票である。中間処理業者から返送されるのはD票(2024年度問164参照)。伝票の5年保存は施行規則第8条の26のとおり。","l":"廃棄物処理法施行規則 第8条の26","c":""},{"id":"2023-164","s":5,"q":"建築物内の清掃作業に必要な人員として、正しいものはどれか。\n・作業場所は専用区域の「役員室及び会議室」と「事務室」で、1日の作業回数はどちらも1回。\n・作業面積を標準作業量で割った値が1時間あたりの必要作業人員で、1回の作業時間は2.5時間。\n・標準作業量には、準備、移動、清掃・ごみ収集、後始末が含まれる。\n役員室及び会議室(タイルカーペット):作業面積380m²、標準作業量95m²/(人・h)\n事務室(タイルカーペット):作業面積5,200m²、標準作業量200m²/(人・h)","o":["5人","8人","10人","12人","15人"],"a":3,"e":"1時間あたりの必要人員は 380÷95＋5,200÷200＝4＋26＝30人・時。作業時間2.5時間で割ると 30÷2.5＝12人。","l":"計算","c":""},{"id":"2023-165","s":5,"q":"個別リサイクル法と、その対象物の組合せとして、最も不適当なものはどれか。","o":["容器包装リサイクル法 ― 空き缶","食品リサイクル法 ― 食品残渣","家電リサイクル法 ― 電子レンジ","小型家電リサイクル法 ― デジタルカメラ","建設リサイクル法 ― 木材"],"a":2,"e":"家電リサイクル法の対象はエアコン、テレビ、冷蔵庫・冷凍庫、洗濯機・衣類乾燥機の4品目(特定家庭用機器再商品化法施行令第1条)で、電子レンジは含まれない。","l":"特定家庭用機器再商品化法施行令 第1条","c":""},{"id":"2023-166","s":6,"q":"蚊の生態に関する記述として、最も適当なものはどれか。","o":["日本のヒトスジシマカは、冬は成虫の姿で越冬する。","アカイエカは、主に建物内の浄化槽・汚水槽・湧水槽などで発生する。","ヒトスジシマカは、ヒト以外にもさまざまな動物から吸血する。","コガタアカイエカは小さな水域で発生し、空き缶や古タイヤなどによく発生する。","同じ期間でのアカイエカとヒトスジシマカの移動距離は、ほぼ同じである。"],"a":2,"e":"ヒトスジシマカは、ヒト以外にも多くの動物を吸血源にしている(2025年問166でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2023-167","s":6,"q":"ゴキブリに関する記述として、最も適当なものはどれか。","o":["ゴキブリは、集団よりも1匹で暮らすほうが早く成長する。","8か所に5日間置いた粘着トラップでとれたゴキブリの合計が200匹のとき、ゴキブリ指数は25である。","ゴキブリは食べ物の好みがはっきりしていて、決まったものしか食べない。","ゴキブリは、危険がせまると警戒フェロモンを出す。","屋内にすむゴキブリでも、東北地方や関東地方の屋外で冬を越せる種類が知られている。"],"a":4,"e":"屋内にすむゴキブリでも、東北・関東の屋外で越冬できる種類がいる。なお(2)のゴキブリ指数は200÷8÷5=5であり、25ではない。","l":"法令外","c":""},{"id":"2023-168","s":6,"q":"チャバネゴキブリに関する記述として、最も不適当なものはどれか。","o":["雌成虫は、卵鞘をふ化の直前まで腹の先に付けている。","雌成虫が一生のうちに産卵する回数は、約5回である。","ほかの屋内にすむゴキブリと比べて、野外で暮らす性質が強い。","幼虫も成虫も、同じ場所で活動する。","幼虫から成虫になり、蛹の時期がない。"],"a":2,"e":"チャバネゴキブリは、ほかの屋内性ゴキブリと比べて野外で生活する性質が強いわけではない。","l":"法令外","c":""},{"id":"2023-169","s":6,"q":"次の文にあてはまるダニとして、最も適当なものはどれか。\n「梅雨どきなど高温多湿のとき、畳や保存食品から大発生することがある。ヒトを刺したり血を吸ったりはせず、アレルゲンとしての重要性も比較的低いが、大量に出ると不快感や恐怖感を与える。」","o":["フトツメダニ","カベアナタカラダニ","ワクモ","ケナガコナダニ","コナヒョウヒダニ"],"a":3,"e":"高温多湿のときに畳や保存食品から大発生するのはケナガコナダニである。","l":"法令外","c":""},{"id":"2023-170","s":6,"q":"ハエ類に関する記述として、最も不適当なものはどれか。","o":["ヒメイエバエは、主に鶏舎での発生が問題になる。","ニクバエ類は、卵ではなく幼虫を産む卵胎生のハエである。","イエバエは、各地でピレスロイド剤への抵抗性を身につけている。","ノミバエ類などのコバエには、光に集まる性質(走光性)をもつ種類が多い。","建物内で発生するチョウバエ類は、ヒトから吸血することがある。"],"a":4,"e":"チョウバエ類はヒトから吸血しない。","l":"法令外","c":""},{"id":"2023-171","s":6,"q":"害虫とその防除に関する記述として、最も不適当なものはどれか。","o":["イエヒメアリの防除には、食毒剤が効果的である。","トコジラミでは、ピレスロイド剤への抵抗性をもつ集団が報告されている。","ツマアカスズメバチは、特定外来生物に指定されている。","ユスリカ類が建物に入ってくるのをおさえるため、電撃殺虫機を窓や出入口の近くに置く。","ヤケヒョウヒダニは、自由生活性のダニである。"],"a":3,"e":"電撃殺虫機を窓や出入口の近くに置くとした記述が誤り。","l":"法令外","c":""},{"id":"2023-172","s":6,"q":"殺虫剤に関する記述として、最も不適当なものはどれか。","o":["ブロフラニリドは、これまでの各種薬剤に抵抗性をもつゴキブリの集団にも効果がある。","プロペタンホスには、マイクロカプセル剤がある。","ピレスロイド剤は、有機リン剤に比べて魚への毒性が高いものが多い。","昆虫成長制御剤(IGR)の50%羽化阻害濃度は、IC50の値で表す。","有機リン剤では、薬の量や濃度を増やしたときの致死率の上がり方が、ピレスロイド剤よりゆるやかである。"],"a":4,"e":"(5)の記述が誤り。","l":"法令外","c":""},{"id":"2023-173","s":6,"q":"薬剤と、その薬剤を有効成分とする製剤の組合せとして、最も不適当なものはどれか。","o":["イミプロトリン ― ゴキブリ用の食毒剤","イカリジン ― 吸血害虫用の忌避剤","フェノトリン ― 炭酸ガス製剤","ジクロルボス ― 樹脂蒸散剤","トランスフルトリン ― 常温揮散製剤"],"a":0,"e":"イミプロトリンをゴキブリ用食毒剤とした組合せが誤り。","l":"法令外","c":""},{"id":"2023-174","s":6,"q":"ネズミの生態や防除に関する記述として、最も適当なものはどれか。","o":["建物内のIPMによるネズミ防除は、餌を絶つこと、殺鼠剤を適切に使うこと、通り道をふさぐことの3つを基本に進める。","建築物の維持管理マニュアルでは、生きたネズミが確認されないことをもって「許容水準にあたる」としている。","ネズミが動いたあとに残すしるしのうち、ふん・尿・毛・足跡・かじり跡をラブサインという。","家にすむネズミの警戒心は、クマネズミが最も強く、次がドブネズミで、ハツカネズミが最も弱い。","生け捕りかごなどのトラップでドブネズミを駆除する場合は、鳥獣保護管理法の規制を受ける。"],"a":3,"e":"家住性ネズミの警戒心は、クマネズミが最も強く、ハツカネズミが最も弱い(2025年問175でもクマネズミはドブネズミより警戒心が強いとされている)。","l":"法令外","c":""},{"id":"2023-175","s":6,"q":"殺鼠剤と、それに関連する事項の組合せとして、最も不適当なものはどれか。","o":["ブロマジオロン ― 建築物衛生法の特定建築物の中では使えない","シリロシド ― 第2世代の抗凝血性殺鼠剤","リン化亜鉛 ― 1回食べると死ぬ","クマテトラリル ― 第1世代の抗凝血性殺鼠剤","ジフェチアロール ― 建築物衛生法の特定建築物の中で使える"],"a":1,"e":"シリロシドはユリ科植物の球根からとれる成分(2024年問175で正しい記述として出題)で、第2世代の抗凝血性殺鼠剤ではない。","l":"法令外","c":""},{"id":"2023-176","s":6,"q":"殺鼠剤に関する記述として、最も不適当なものはどれか。","o":["粉剤を鼠穴の中に散粉する処理は、殺鼠剤を皮膚から取り込ませることをねらった方法である。","第1世代の抗凝血性殺鼠剤は、少しずつ毎日食べさせるように置く。","クマネズミは、ドブネズミに比べて抗凝血性殺鼠剤が効きにくい。","ネズミの殺鼠剤抵抗性は、昆虫の殺虫剤抵抗性と同じしくみで発達する。","有効成分と餌をパラフィンにまぜて固め、水にぬれる場所でも使える製剤がある。"],"a":0,"e":"皮膚から取り込ませて効く殺鼠剤はない(2020年問174で正しい記述として出題)。散粉処理も、皮膚から取り込ませることをねらった方法ではない。","l":"法令外","c":""},{"id":"2023-177","s":6,"q":"媒介動物と感染症に関する記述として、最も不適当なものはどれか。","o":["国内では、アカイエカやヒトスジシマカを含む何種類かの蚊がウエストナイルウイルスを媒介する可能性がある。","重症熱性血小板減少症候群(SFTS)の原因ウイルスが媒介されるのは、主に建物の中である。","マダニ類は、リケッチアやウイルスを媒介する。","イエバエは、腸管出血性大腸菌感染症を広めることにかかわっている。","動物由来感染症の対策では、ペットの外部寄生虫などへの対応も重要である。"],"a":1,"e":"SFTSのウイルスはマダニ類が媒介する(2020年問175で正しい記述として出題)。主に建物の中で媒介されるのではない。","l":"法令外","c":""},{"id":"2023-178","s":6,"q":"ねずみ・昆虫等の防除の安全管理に関する記述として、最も適当なものはどれか。","o":["N95マスクは、薬剤を空間に散布するときや狭い場所で、気化したガスを吸い込まないために着ける。","薬剤をまくときは、どんな薬剤を使っているか分かるように、薬剤を人目につく場所に置いておく。","2m以上の高所作業では墜落防止用の器具は不要だが、必ず補助者を付けなければならない。","殺虫剤散布の3日前までに内容を知らせ、散布の前後3日間、その区域の入口に掲示する。","建築物衛生法の特定建築物で行う防除では、医薬部外品として承認された薬剤は使えない。"],"a":3,"e":"殺虫剤を散布するときは、3日前までに内容を知らせ、散布前後3日間、区域の入口に掲示する。なお特定建築物での防除には医薬品または医薬部外品を使う(施行規則第4条の5第2項第2号)ので(5)は誤り。高さ2m以上の作業では墜落防止の措置が必要(労働安全衛生規則第518条)で(3)も誤り。","l":"建築物衛生法施行規則 第4条の5第2項第2号、労働安全衛生規則 第518条(選択肢3・5)","c":""},{"id":"2023-179","s":6,"q":"建築物とねずみ・害虫に関する記述として、最も不適当なものはどれか。","o":["防虫・防鼠の構造は、建物を新しく建てるときの構造設計の段階で取り入れておく必要がある。","ふつうは20メッシュより細かい網目なら、多くの昆虫の侵入を防げる。","環境的な対策は、特定建築物維持管理権原者のもとで、その区域の管理者が日ごろから行う必要がある。","特定建築物では、生息密度がどの維持管理水準にあたっていても、1年以内に1回は防除作業を行うことになっている。","室内で換気扇を使うと、窓や扉のすき間から入ってくる害虫が増える。"],"a":3,"e":"法令で決まっているのは、6か月以内ごとに1回の統一的な調査と、その結果にもとづく必要な措置である(施行規則第4条の5第2項第1号)。生息密度が許容水準にあたる場合は定期的な調査を続ける(2021年問179)ので、一律に1年以内に1回防除作業を行う決まりはない。","l":"建築物衛生法施行規則 第4条の5第2項第1号","c":""},{"id":"2023-180","s":6,"q":"害虫や薬剤に関する記述として、最も不適当なものはどれか。","o":["喫食抵抗性は、毒餌の基剤を食べるのを嫌がることで発達する。","ペストコントロールのペストとは、ネズミや害虫などの有害な生き物をさす。","定期的で回数の多い薬剤処理は、チャバネゴキブリやチカイエカなどの薬剤抵抗性が急に発達する原因になる。","選択毒性とは、体重あたりで比べたとき、ある化合物の毒性が生き物の種類によって違うことをいう。","人獣共通感染症とは、ヒトから動物ではなく、動物からヒトにだけ病原体がうつる感染症をいう。"],"a":4,"e":"人獣共通感染症は、動物からヒトへだけでなく、ヒトと動物の間でうつる感染症である。","l":"法令外","c":""},{"id":"2024-1","s":0,"q":"世界保健機関(WHO)憲章の前文にある健康の定義について、次の文の(ア)〜(ウ)に入る語句の組合せとして、最も適当なものはどれか。\n「健康とは、肉体的、精神的及び( ア )に完全に良好な状態であり、単に病気や病弱でないことではない。到達できる最高水準の健康を享受することは、人種、( イ )、政治的信念、( ウ )又は社会的条件による差別なしに、すべての人がもつ基本的権利の一つである。」","o":["ア 社会的　イ 性別　ウ 経済的","ア 地域的　イ 宗教　ウ 文化的","ア 社会的　イ 宗教　ウ 経済的","ア 地域的　イ 性別　ウ 文化的","ア 社会的　イ 性別　ウ 文化的"],"a":2,"e":"WHO憲章では、健康を「肉体的、精神的及び社会的に完全に良好な状態」とし、「人種、宗教、政治的信念、経済的又は社会的条件」による差別なく享受できる基本的権利としている。","l":"法令外(WHO憲章 前文)","c":""},{"id":"2024-2","s":0,"q":"現在の行政組織についてのア〜オの記述のうち、正しいものの組合せはどれか。\nア 労働衛生行政は、国では厚生労働省、地方では都道府県が受け持っている。\nイ 学校保健安全法は、総務省が所管している。\nウ 浄化槽法を所管しているのは、国土交通省と環境省である。\nエ 建築基準法でいう特定行政庁とは、国土交通省のことである。\nオ 保健所の数を設置する自治体別にみると、都道府県が設置する保健所が最も多い。","o":["アとイ","アとウ","イとエ","ウとオ","エとオ"],"a":3,"e":"ウとオが正しい。労働衛生行政の地方機関は都道府県ではなく都道府県労働局・労働基準監督署、学校保健安全法は文部科学省の所管、特定行政庁は建築主事等を置く市町村長・都道府県知事である。","l":"法令外(各省設置法)、建築基準法 第2条第35号","c":""},{"id":"2024-3","s":0,"q":"特定建築物の延べ面積について、最も適当なものはどれか。","o":["地下街の地下道は、延べ面積に入れる。","建物の地階にある公共駐車場は、延べ面積に入れる。","特定建築物の延べ面積の定義は、建築基準法の延べ面積の定義と同じである。","建物の地階にある電力会社の地下式変電所は、延べ面積に入れる。","店舗の地階にある、その店舗に付属する倉庫は、延べ面積に入れる。"],"a":4,"e":"特定用途に付属する倉庫などは、特定用途の部分として延べ面積に入れる。地下街の地下道、公共駐車場、変電所のような特定用途と関係のない施設は入れない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2024-4","s":0,"q":"特定建築物の用途に当たるものはどれか。","o":["特別養護老人ホーム","寄宿舎","病院","ボーリング場","教会"],"a":3,"e":"ボーリング場は遊技場に当たるため、特定用途に含まれる。福祉施設、寄宿舎、病院、宗教施設は特定用途に含まれない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2024-5","s":0,"q":"次の建築物のうち、特定建築物に当たらないものはどれか。なお、すべて1棟の建物とする。","o":["延べ面積2,000m²の事務所と、2,500m²の社員研修所の複合施設","延べ面積8,500m²の中等教育学校","延べ面積5,000m²の予備校","延べ面積2,500m²の事務所と、1,000m²の事務所付属の倉庫の複合施設","延べ面積1,000m²の店舗と、1,500m²の事務所と、その事務所が管理する2,500m²の自然科学系の研究施設の複合施設"],"a":4,"e":"自然科学系の研究施設は特定用途に含まれないため、店舗1,000+事務所1,500=2,500m²となり、3,000m²に届かない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2024-6","s":0,"q":"特定建築物の届出について、最も適当なものはどれか。","o":["うその届出をすると、期間を決めてその建物の使用停止の処分を受けることがある。","届出には、建築確認済証の写しをつけなければならない。","新たに特定建築物に当たることになったときは、その日から3か月以内に届け出なければならない。","届出の義務があるのは、所有者、またはその特定建築物全部の管理について権原をもつ者である。","特定建築物に当たらなくなったときは、その日から6か月以内に届け出なければならない。"],"a":3,"e":"届出をするのは特定建築物所有者等(所有者、または建物全部の管理について権原をもつ者)。届出の期限はいずれも1か月以内で、うその届出の罰則は30万円以下の罰金。","l":"建築物衛生法 第5条、第16条","c":""},{"id":"2024-7","s":0,"q":"建築物環境衛生管理基準にもとづく空気環境の測定について、正しいものはどれか。","o":["測定する位置は、居室の中央部の床上50cm以上175cm以下である。","気流の測定には、0.5m/秒以上の気流を測れる風速計を使う。","階数が多い場合は、各階ごとに測定しなくてもよい。","ホルムアルデヒドの測定は、毎年6月1日から9月30日までの間に行う。","二酸化炭素の含有率は、1日の使用時間中の平均値とする。"],"a":4,"e":"二酸化炭素や浮遊粉じん、一酸化炭素は、1日の使用時間中の平均値で評価する。測定位置は床上75cm以上150cm以下、風速計は0.2m/秒以上を測れるもの、ホルムアルデヒドは新築・大規模修繕等の後、最初に来る6月1日〜9月30日の間に1回測る。","l":"建築物衛生法施行規則 第3条の2","c":""},{"id":"2024-8","s":0,"q":"建築物環境衛生管理基準にもとづく飲料水の衛生上の措置について、最も不適当なものはどれか。","o":["6か月以内ごとの定期水質検査の項目のうち、鉛、亜鉛、鉄、銅とそれらの化合物、蒸発残留物は、検査結果が基準に合っていれば、次回の検査で省略できる。","貯水槽の清掃は、1年以内ごとに1回、定期に行う。","遊離残留塩素の検査は、給水栓の末端で7日以内ごとに1回、定期に行う。","総トリハロメタンなどの消毒副生成物の検査は、毎年6月1日から9月30日の間に行う。","水道水以外の地下水などを原水に使う場合は、3年以内ごとに1回、水質基準のすべての項目の検査を行う。"],"a":4,"e":"地下水などを使う場合、水質基準の全項目の検査は「給水を始める前」に行う。3年以内ごとに1回行うのは、四塩化炭素やトリクロロエチレンなど一部の有機化学物質の項目である。","l":"建築物衛生法施行規則 第4条第1項第4号","c":"原文の「すべての項目(51項目)」は、2026年4月の水質基準改正で52項目になったため、項目数を書かずに「すべての項目」とした(正答は変わらない)。"},{"id":"2024-9","s":0,"q":"建築物環境衛生管理基準について、誤っているものはどれか。","o":["防除する動物は、ねずみ、昆虫など、人の健康を損なうおそれのある動物である。","掃除は、日常の掃除のほか、大掃除を6か月以内ごとに1回、定期にまとめて行う。","特定建築物維持管理権原者は、排水設備の掃除を1年以内ごとに1回、定期に行わなければならない。","特定建築物維持管理権原者は、厚生労働大臣が定める技術上の基準に従い、排水設備の補修・掃除などの維持管理に努めなければならない。","冷却塔、冷却水の水管、加湿装置の清掃を、それぞれ1年以内ごとに1回、定期に行う。"],"a":2,"e":"正しくは、排水に関する設備の掃除は「6か月以内ごとに1回」、定期に行う。","l":"建築物衛生法施行規則 第4条の3","c":""},{"id":"2024-10","s":0,"q":"建築物環境衛生管理技術者の職務として、最も不適当なものはどれか。","o":["環境衛生上必要な事項を記載した帳簿書類を備えつけること","建築物環境衛生管理基準をもとにした管理業務計画を立てること","管理業務計画にもとづく具体的な管理業務を指揮・監督すること","空気環境の測定結果や水質検査の結果などを評価すること","環境衛生の維持管理に必要な各種の調査を行うこと"],"a":0,"e":"帳簿書類を備えつける義務があるのは、特定建築物所有者等である。","l":"建築物衛生法 第10条","c":""},{"id":"2024-11","s":0,"q":"水洗便所に飲料水以外の水(雑用水)を使っている場合の水質検査の項目として、最も不適当なものはどれか。","o":["pH値","臭気","外観","大腸菌","濁度"],"a":4,"e":"水洗便所用の雑用水の検査項目は、pH値・臭気・外観・大腸菌(と遊離残留塩素)。濁度は、散水・修景・清掃に使う雑用水だけの検査項目である。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2024-12","s":0,"q":"事業の登録に必要な物的要件のうち、機械器具以外の設備を必要としない登録事業はどれか。","o":["建築物清掃業","建築物飲料水水質検査業","建築物飲料水貯水槽清掃業","建築物排水管清掃業","建築物ねずみ昆虫等防除業"],"a":0,"e":"建築物清掃業の物的要件は、真空掃除機と床みがき機の機械器具だけである。ほかの業種は、検査施設や機械器具の保管庫、薬剤の保管庫などの設備も必要。","l":"建築物衛生法施行規則 第25条ほか","c":""},{"id":"2024-13","s":0,"q":"特定建築物への立入検査について、最も適当なものはどれか。","o":["特定建築物でなくても、多くの人が使う建物なら立入検査ができる。","立入検査は1人で行ってはならない。","立入検査は、日時を前もって知らせなければならない。","特定建築物の中にある住居に立ち入るときは、そこに住む人の承諾を得なければならない。","立入検査を行う職員を、環境衛生指導員という。"],"a":3,"e":"特定建築物の中の住居に立ち入る場合は、居住者の承諾が必要である。立入検査を行う職員は環境衛生監視員という。","l":"建築物衛生法 第11条","c":""},{"id":"2024-14","s":0,"q":"地域保健法にもとづく保健所の事業として、最も不適当なものはどれか。","o":["人口動態統計など、地域保健に関する統計","地域保健に関する考え方の普及と向上","公共医療事業の向上と増進","労働者の安全と衛生","医事と薬事"],"a":3,"e":"労働者の安全と衛生は、労働基準監督署などが受け持つ労働行政の分野であり、保健所の事業には含まれない。","l":"地域保健法 第6条","c":""},{"id":"2024-15","s":0,"q":"学校保健安全法の学校環境衛生基準のうち、教室等の揮発性有機化合物の検査項目に含まれていない物質はどれか。","o":["ホルムアルデヒド","アセトアルデヒド","トルエン","キシレン","パラジクロロベンゼン"],"a":1,"e":"教室等の揮発性有機化合物の検査項目は、ホルムアルデヒド、トルエン、キシレン、パラジクロロベンゼン、エチルベンゼン、スチレンで、アセトアルデヒドは含まれない。","l":"学校環境衛生基準(学校保健安全法 第6条)","c":""},{"id":"2024-16","s":0,"q":"下水道法について、最も不適当なものはどれか。","o":["下水道を整備し、都市の健全な発達と公衆衛生の向上に役立て、あわせて公共用水域の水質を守ることを目的とする。","国土交通大臣は、緊急の必要があるときは、公共下水道などの工事や維持管理について必要な指示ができる。","終末処理場とは、下水を最終的に処理して川などに流すために、下水道の施設として設けられる処理施設と、それを補う施設をいう。","都道府県は、下水道の整備に関する総合的な基本計画を定めなければならない。","厚生労働大臣は、緊急の必要があるときは、終末処理場の維持管理について必要な指示ができる。"],"a":4,"e":"終末処理場の維持管理について緊急時に指示ができるのは、厚生労働大臣ではなく環境大臣である。","l":"下水道法 第37条第3項","c":""},{"id":"2024-17","s":0,"q":"大気汚染防止法第1条の目的として、誤っているものはどれか。","o":["揮発性有機化合物や粉じんの排出などを規制する。","自動車排出ガスの許容限度を定める。","水銀等の排出を規制する。","排出ガス中のダイオキシン類について、特定施設の種類・構造に応じた排出基準を定める。","人の健康被害が生じたときの事業者の損害賠償の責任について定める。"],"a":3,"e":"ダイオキシン類の排出基準は、大気汚染防止法ではなく、ダイオキシン類対策特別措置法で定められている。","l":"大気汚染防止法 第1条","c":""},{"id":"2024-18","s":0,"q":"事務所衛生基準規則第2条の次の文の(ア)〜(ウ)に入る語句と数値の組合せとして、正しいものはどれか。\n「事業者は、労働者をいつも働かせる部屋の( ア )を、設備が占める容積と床面から( イ )mを超える高さの空間を除いて、労働者1人あたり( ウ )m³以上としなければならない。」","o":["ア 容積　イ 3　ウ 8","ア 気積　イ 3　ウ 10","ア 気積　イ 4　ウ 10","ア 容積　イ 4　ウ 12","ア 気積　イ 5　ウ 12"],"a":2,"e":"事務所衛生基準規則では、室の気積を、設備の容積と床面から4mを超える空間を除いて、労働者1人あたり10m³以上とする。","l":"事務所衛生基準規則 第2条","c":""},{"id":"2024-19","s":0,"q":"健康増進法の受動喫煙防止対策で、施設とその対応の組合せとして、最も不適当なものはどれか。","o":["学校 ― 敷地内禁煙","病院 ― 敷地内禁煙","行政機関の庁舎 ― 原則屋内禁煙","事務所 ― 原則屋内禁煙","ホテル・旅館 ― 原則屋内禁煙"],"a":2,"e":"行政機関の庁舎は、学校や病院と同じ第一種施設にあたり、「敷地内禁煙」である(屋外に特定屋外喫煙場所を設けることは可能)。","l":"健康増進法 第28条、第29条","c":""},{"id":"2024-20","s":0,"q":"建築物衛生法と関係する法律について、最も不適当なものはどれか。","o":["建築物衛生法は、給水の水質基準などについて、水道法の基準の一部を使っている(準用している)。","地域保健法で設置された保健所は、建築物の環境衛生に関する相談や指導などを行う。","特定建築物の建築確認のときは、特定行政庁・建築主事等・指定確認検査機関は、建築基準法の許可や確認について保健所長の同意を得なければならない。","事務所だけに使われる特定建築物の環境衛生管理は、利用者のほとんどが労働者なので、労働安全衛生法と建築物衛生法の両方の規制を受ける。","学校保健安全法でいう学校は、建築物衛生法の特定用途に当たる。"],"a":2,"e":"建築確認で同意が必要なのは消防長等である。特定建築物の場合、保健所長には「同意」ではなく「通知」を行い、保健所長は意見を述べることができる。","l":"建築基準法 第93条","c":""},{"id":"2024-21","s":1,"q":"健康に影響する環境要因のうち、「物理的要因」として最も不適当なものはどれか。","o":["振動","気圧","音","放射線","硫黄酸化物"],"a":4,"e":"硫黄酸化物は物質なので、化学的要因に分類される。","l":"法令外","c":""},{"id":"2024-22","s":1,"q":"環境基本法の環境基準についての条文で、(ア)〜(ウ)に入る語句の組合せとして、最も適当なものはどれか。\n「政府は、大気の汚染、水質の汚濁、土壌の汚染及び( ア )に関する環境上の条件について、それぞれ、( イ )を保護し、及び( ウ )を保全するうえで維持されることが望ましい基準を定める。」","o":["ア 騒音　イ 生態系　ウ 自然環境","ア 騒音　イ 人の健康　ウ 生活環境","ア 温暖化　イ 人の健康　ウ 国土","ア 海洋の汚染　イ 文化的な生活　ウ 生活環境","ア 海洋の汚染　イ 生態系　ウ 国土"],"a":1,"e":"環境基準は、大気・水質・土壌・騒音について、人の健康を保護し、生活環境を保全するうえで望ましい基準として定められる。","l":"環境基本法 第16条","c":""},{"id":"2024-23","s":1,"q":"環境衛生について、最も不適当なものはどれか。","o":["許容限界とは、生物が耐えられなくなるストレスの強さの限界のことである。","許容濃度を守れば、ほとんどすべての労働者に健康上の悪い影響は見られないとされる。","有害物による、がんなどを除く特定の反応では、曝露量が増えると反応が出る人(陽性者)は直線的に増える。","有害物の負荷量と、個体レベルでの障害などの程度との関係を、量-影響関係という。","学校の環境衛生の基準は、学校保健安全法で定められている。"],"a":2,"e":"がんなどを除く特定の反応では、曝露量と陽性者の割合の関係(量-反応関係)は直線ではなく、一般にS字形の曲線になる。","l":"法令外","c":""},{"id":"2024-24","s":1,"q":"体温調節について、次の文の(ア)(イ)に入る語句の組合せとして、最も適当なものはどれか。\n「体は熱をつくる量(産熱)と逃がす量(放熱)のつり合いを保ち、体温を一定にしている。産熱は( ア )などで制御され、放熱は発汗や( イ )などで調節されている。」","o":["ア 筋弛緩　イ 血液循環","ア 基礎代謝の増進　イ 尿産生","ア 筋弛緩　イ 交感神経の興奮","ア 基礎代謝の増進　イ 血液循環","ア ふるえ　イ 尿産生"],"a":3,"e":"産熱は基礎代謝の増進やふるえなどで、放熱は発汗や皮膚の血液循環(血管の拡張・収縮)などで調節される。","l":"法令外","c":""},{"id":"2024-25","s":1,"q":"WBGT(湿球黒球温度)について、最も不適当なものはどれか。","o":["熱中症予防のため、スポーツをするときの指針として使われている。","職場の暑さの基準として使う場合は、作業の強さを考える必要がある。","日常生活の熱中症予防の注意事項では、WBGTが31℃以上のとき、高齢者は安静にしていても熱中症の危険が大きいとされる。","職場の暑さの基準として使う場合は、着ている服の種類に応じて補正する必要がある。","屋外で日が当たっている場合は、自然湿球温度と黒球温度から求める。"],"a":4,"e":"屋外で日射がある場合は、自然湿球温度・黒球温度に加えて乾球温度(気温)も使って求める。","l":"法令外","c":""},{"id":"2024-26","s":1,"q":"熱中症について、最も不適当なものはどれか。","o":["熱けいれんは、高ナトリウム血症による筋肉のけいれんである。","熱射病は、体温が上がることによる中枢神経のはたらきの異常である。","熱失神(熱虚脱)は、皮膚の血管が広がって血圧が下がることによる、一時的な意識の消失である。","皮膚の病気やひどい日焼けのときは汗をかくはたらきが落ちるので、注意が必要である。","熱射病の治療では、冷やしすぎに注意する必要がある。"],"a":0,"e":"熱けいれんは、大量の汗で塩分が失われたのに水だけを補給したことによる、低ナトリウム血症での筋肉のけいれんである。","l":"法令外","c":""},{"id":"2024-27","s":1,"q":"低温による障害について、最も不適当なものはどれか。","o":["しもやけ(凍瘡)は、低温によって体の一部が凍ってしまったものである。","5℃以下の水に急に浸かると、5〜15分で命にかかわる低体温症になる可能性がある。","天候によっては、気温13〜16℃程度でも低体温症になることがある。","低体温症が進むと、震えは止まる。","低体温症の診断は、直腸温を測って行う。"],"a":0,"e":"体の一部が凍ってしまうのは凍傷である。しもやけ(凍瘡)は、凍らない程度の寒さで血行が悪くなって起こる炎症。","l":"法令外","c":""},{"id":"2024-28","s":1,"q":"健康な人に呼吸や脈拍の増加、めまいが起こる酸素濃度として、最も適当なものはどれか。","o":["20〜18%","17〜16%","11〜10%","7〜6%","4%以下"],"a":1,"e":"酸素濃度が16%前後になると、呼吸・脈拍の増加、頭痛、めまいなどの症状が出始める。","l":"法令外","c":""},{"id":"2024-29","s":1,"q":"アレルギーについて、最も不適当なものはどれか。","o":["湿度が低いことは、気管支喘息やアトピー性皮膚炎を悪化させる要因になる。","気管支喘息の原因は、ダニやハウスダストが多い。","気管支喘息の原因となるアレルゲンとして、ヒスタミンが重要である。","建築物衛生の面から、換気や清掃などの対策が大切である。","学校保健安全法で、ダニまたはダニアレルゲンの基準が定められている。"],"a":2,"e":"ヒスタミンは、アレルギー反応が起きたときに体の細胞から出る化学伝達物質であり、原因物質であるアレルゲンではない。","l":"法令外","c":""},{"id":"2024-30","s":1,"q":"室内の空気汚染物質による健康影響が一因となる病気の組合せア〜エについて、正しいものはどれか。\nア オゾン ― 肺気腫\nイ ラドン ― 肺がん\nウ 真菌 ― 過敏性肺炎\nエ トルエン ― シックハウス症候群","o":["アとイとウ","アとウとエ","アとイとエ","イとウとエ","すべて正しい"],"a":4,"e":"ア〜エはすべて、室内の空気汚染物質とそれが一因となる病気の正しい組合せである。","l":"法令外","c":""},{"id":"2024-31","s":1,"q":"アスベスト(石綿)が原因となる病気として、正しいものの組合せはどれか。\nア じん肺　イ 過敏性肺炎　ウ 慢性閉塞性肺疾患　エ 肺がん　オ 悪性中皮腫","o":["アとイとエ","アとウとエ","アとエとオ","イとウとオ","イとエとオ"],"a":2,"e":"アスベストは、じん肺の一種である石綿肺、肺がん、悪性中皮腫の原因になる。","l":"法令外","c":""},{"id":"2024-32","s":1,"q":"加熱式たばこについて、最も不適当なものはどれか。","o":["健康増進法の規制の対象になる。","吸っているときの室内のニコチン濃度は、紙巻たばこと同じくらいである。","主流煙には発がん性物質が含まれる。","加熱式たばこを使う人も、健康保険による禁煙治療の対象になる。","主流煙に紙巻たばこと同じくらいのニコチンを含む製品がある。"],"a":1,"e":"この記述が誤り。加熱式たばこを吸っているときの室内のニコチン濃度は、紙巻たばこと同等とはいえない(主流煙のニコチン量とは区別して考える)。","l":"法令外","c":""},{"id":"2024-33","s":1,"q":"ホルムアルデヒドについて、最も不適当なものはどれか。","o":["消毒剤として使われる。","建築基準法で、ホルムアルデヒドを含む建材の使用が制限されている。","防腐剤として使われる。","水やアルコールに溶けやすい。","燃えない(不燃性である)。"],"a":4,"e":"ホルムアルデヒドは燃えやすい(可燃性の)物質である。","l":"法令外","c":""},{"id":"2024-34","s":1,"q":"音について、最も不適当なものはどれか。","o":["耳に届く音には、鼓膜を通した空気の振動による音と、頭の骨などを通して伝わる音がある。","周波数とは、音波の波長のことである。","音は内耳の有毛細胞から聴神経を通って大脳に伝わり、音として認識される。","人の耳が最も敏感な周波数は、4,000Hz付近である。","話し声の主な周波数の範囲は、100〜4,000Hzである。"],"a":1,"e":"周波数は1秒間の振動の回数(単位Hz)であり、波長(1回の振動で音が進む長さ)とは別のものである。","l":"法令外","c":""},{"id":"2024-35","s":1,"q":"騒音とその影響について、最も不適当なものはどれか。","o":["騒音の測定で使うA特性は、人の耳の感度に近い特性を組み込んだものである。","事務室の騒音レベルは、一般に50〜60dBである。","騒音性難聴の初期の特徴は、4,000Hz付近の音が聞こえにくくなることである。","騒音による永久的な聴力障害がほとんど起こらないのは、1日の等価騒音レベルが85dB以下のときである。","血圧の上昇は、騒音による健康影響の一つとして知られている。"],"a":3,"e":"この記述が誤り。永久的な聴力障害がほとんど起こらないとされる1日の等価騒音レベルは、85dBより低い値とされる。","l":"法令外","c":""},{"id":"2024-36","s":1,"q":"振動について、最も不適当なものはどれか。","o":["局所振動では、振動数が大きければ大きいほど健康影響が大きい。","局所振動により、レイノー現象と呼ばれる指の血行障害が起こる。","フォークリフトの運転による全身振動で、胃下垂が起こる。","局所振動による神経障害が進むと筋肉がやせ、指を伸ばしにくくなる。","道路交通などの振動は地面を伝わり、建物の中で全身振動として感じられる。"],"a":0,"e":"この記述が誤り。局所振動の健康影響は、振動数が大きいほど単純に大きくなるわけではない。","l":"法令外","c":""},{"id":"2024-37","s":1,"q":"光環境と視覚について、最も不適当なものはどれか。","o":["明順応は、暗順応より順応にかかる時間が短い。","物の色は、光が物に当たって吸収された光の分光分布によって感じとられる。","視細胞の錐体には、赤・青・緑の光にそれぞれ反応する3種類がある。","目が見る対象の細かい部分を見分ける能力を、視力という。","グレアとは、視野の中に輝度が高すぎる点や面があることで起こる不快感や見にくさのことである。"],"a":1,"e":"物の色は、物に当たって吸収されずに反射(または透過)した光の分光分布によって感じとられる。","l":"法令外","c":""},{"id":"2024-38","s":1,"q":"電場・磁場・電磁波について、最も不適当なものはどれか。","o":["電磁波を波長の長い順に並べると、電波が一番長く、次が電離放射線で、光が一番短い。","電離作用とは、原子や分子が電子を放出することである。","電磁波のうち、目で存在を確かめられるのは可視光線だけである。","電流が流れるところには、電流に応じて必ず電磁場が発生する。","家庭の中の電波の発生源として、電子レンジがある。"],"a":0,"e":"波長の長い順は、電波 → 光(赤外線・可視光線・紫外線) → 電離放射線(X線・γ線)であり、電離放射線のほうが光より短い。","l":"法令外","c":""},{"id":"2024-39","s":1,"q":"電離放射線について、最も不適当なものはどれか。","o":["β線やα線は、粒子線である。","X線をさえぎるには、鉛の板などを使う。","細胞のうち、放射線の影響を最も受けやすいのはリンパ球である。","放射線の健康影響のうち、発がんは確定的影響に分類される。","胎児は、放射線の被ばくに対して影響を受けやすい。"],"a":3,"e":"発がんは、しきい線量がなく確率的に起こるとされる「確率的影響」に分類される。","l":"法令外","c":""},{"id":"2024-40","s":1,"q":"環境基本法の水質汚濁に係る環境基準で、公共用水域から「検出されないこと」とされているものはどれか。","o":["カドミウム","六価クロム","PCB","ジクロロメタン","ベンゼン"],"a":2,"e":"PCB(ポリ塩化ビフェニル)は、人の健康の保護に関する環境基準で「検出されないこと」とされている。ほかは数値の基準値が定められている。","l":"水質汚濁に係る環境基準(環境基本法 第16条にもとづく告示)","c":""},{"id":"2024-41","s":1,"q":"ヒトと水について、最も不適当なものはどれか。","o":["尿や汗などで出ていった水分は、飲み物、食べ物の中の水分、体内でできる代謝水で補われる。","体重の1%以上の水分が不足すると、のどの渇きが出る。","ヒトは、食べ物がなくても飲み水があれば数十日生きられる。","成人では、体重の約2/3が水分である。","体の中では、細胞内液より細胞外液のほうが多い。"],"a":4,"e":"体の水分は細胞内液のほうが多い(体重の約40%)。細胞外液は体重の約20%である。","l":"法令外","c":""},{"id":"2024-42","s":1,"q":"レジオネラ症について、最も不適当なものはどれか。","o":["病原体は、自然界の土や淡水の中などにすんでいる。","エアロゾル(細かい水しぶき)が飛び散ることで感染する。","閉じた空間では感染のリスクが高い。","ヒトからヒトへ感染する。","喫煙者や慢性の呼吸器の病気がある人などは発症しやすい。"],"a":3,"e":"レジオネラ症は、菌を含むエアロゾルを吸い込んで感染するもので、ヒトからヒトへはうつらない。","l":"法令外","c":""},{"id":"2024-43","s":1,"q":"再興感染症(いったん減ったが再び増えてきた感染症)に分類されるものはどれか。","o":["AIDS(後天性免疫不全症候群)","クリプトスポリジウム症","デング熱","SARS(重症急性呼吸器症候群)","エボラ出血熱"],"a":2,"e":"デング熱は再興感染症に分類される。AIDS、クリプトスポリジウム症、SARS、エボラ出血熱は、新しく見つかった新興感染症である。","l":"法令外","c":""},{"id":"2024-44","s":1,"q":"クリプトスポリジウム症について、最も不適当なものはどれか。","o":["病原体は原虫である。","人と動物の両方にうつる人獣共通感染症である。","川などの地表水を水道の原水にしている場合は、汚染のリスクが高い。","発症までの潜伏期間は3〜10日である。","水道でクリプトスポリジウムを不活化するには、一般にオゾンが使われる。"],"a":4,"e":"この記述が誤り。水道でのクリプトスポリジウム対策としては、一般にろ過による除去や紫外線処理が用いられる。","l":"法令外(水道におけるクリプトスポリジウム等対策指針)","c":""},{"id":"2024-45","s":1,"q":"薬液による消毒について、最も適当なものはどれか。","o":["消毒用エタノールは、濃度100%が最も効果が高い。","消毒用エタノールは、芽胞にも効果が期待できる。","逆性石けんは、緑膿菌や結核菌に有効である。","ホルマリンは、すべての微生物に有効である。","0.01%の次亜塩素酸ナトリウム水溶液は、一般に手指の消毒に使われる。"],"a":3,"e":"ホルマリンは芽胞を含むすべての微生物に有効である。エタノールは70〜80%程度が最も効果が高く、芽胞には効かない。","l":"法令外","c":""},{"id":"2024-46","s":2,"q":"用語と単位の組合せのうち、誤っているものはどれか。","o":["比エンタルピー ― kJ/kg(DA)","熱伝導率 ― W/(m・K)","光度 ― cd","音圧 ― W/m²","密度 ― kg/m³"],"a":3,"e":"音圧は圧力なので単位はPa。W/m²は音の強さ(音響インテンシティ)の単位である。","l":"法令外","c":""},{"id":"2024-47","s":2,"q":"1辺3mの正方形の壁材で、天井を含む立方体の部屋をつくり、日射の当たらない条件で床を地面に固定した。すき間換気は無視でき、床は完全に断熱されていて床からの熱貫流はない。外気温度－4℃のもとで室内を1,350Wの発熱で暖め、十分に時間がたった後の室温が20℃になった。壁の熱貫流率として最も適当なものはどれか。","o":["1.05W/(m²・K)","1.25W/(m²・K)","1.50W/(m²・K)","1.60W/(m²・K)","2.10W/(m²・K)"],"a":1,"e":"熱が逃げる面は壁4面＋天井1面＝5面で、面積は3×3×5＝45m²。発熱量＝熱貫流率×面積×温度差より、1,350＝K×45×(20－(－4))＝K×1,080。K＝1.25W/(m²・K)。","l":"計算","c":""},{"id":"2024-48","s":2,"q":"下の図は、厚さの異なるA、B、C部材で構成された建築物外壁における定常状態の内部温度分布を示している。この図に関する次の記述のうち、最も不適当なものはどれか。","o":["A、B、C部材のなかで、最も熱伝導率が小さい部材はB部材である。","熱伝達率は、屋外側の方が室内側より大きい。","B部材が主体構造体であるとすれば、この図は外断熱構造を示している。","A、B、Cの各部材を流れる単位面積当たりの熱流量に差異はない。","壁表面近傍で空気温度が急激に変化する部分を境界層という。"],"a":0,"e":"熱流量はどの部材も同じなので、温度が急に変わる(傾きが急な)部材ほど熱伝導率が小さい。いちばん傾きが急なのはA部材なので、熱伝導率が最も小さいのはA部材(断熱材)。","l":"法令外","c":"","g":["img/2024-48.png"]},{"id":"2024-49","s":2,"q":"冬の結露について述べた次の文のうち、最も不適当なものはどれか。","o":["戸建て住宅では、外気に面した壁の出隅部分の室内側で表面結露が起きやすい。","室内で家具などを外壁にくっつけて置くと、家具の裏側の結露を防ぐのに効果がある。","断熱が部分的に途切れて熱橋になった部分は結露しやすい。","換気の悪い暖房していない部屋では、暖房室で出た水蒸気が流れ込み、温度の低い窓面で結露が起きやすい。","壁の内部結露を防ぐには、外壁の断熱層の室内側に防湿層を設けるのが有効である。"],"a":1,"e":"家具を外壁に密着させると、裏側の空気が動かず壁の表面温度が下がるため、かえって結露しやすくなる。","l":"法令外","c":""},{"id":"2024-50","s":2,"q":"熱放射について述べた次の文のうち、最も不適当なものはどれか。","o":["常温の物体が出す電磁波は、波長10μm付近の赤外線が中心である。","アスファルトは、新しい亜鉛鉄板より長波長放射率が大きい。","放射熱伝達の式を簡単にするときは、放射熱伝達率を使う。","アスファルトは、光ったアルミ箔より日射吸収率が大きい。","物体の表面から出る単位面積あたりの放射熱流は、絶対温度の2乗に比例する。"],"a":4,"e":"ステファン・ボルツマンの法則により、放射熱流は絶対温度の4乗に比例する。","l":"法令外","c":""},{"id":"2024-51","s":2,"q":"流体の基礎についての次の文の[ア]〜[ウ]に入る語句の組合せとして、正しいものはどれか。\n「流管の2つの断面A・Bの間で流れの力学的エネルギーが保存されると考えると、(1/2)ρUA²＋PA＋ρghA＝(1/2)ρUB²＋PB＋ρghB が成り立つ。これをベルヌーイの定理といい、各辺の第1項を[ア]、第2項を[イ]、第3項を位置圧という。実際の流れでは[ウ]が生じるので、左辺と右辺に差が出る。」(ρ:密度、U:速度、P:圧力、g:重力加速度、h:高さ)","o":["ア 動圧/イ 絶対圧/ウ 圧力損失","ア 動圧/イ 静圧/ウ 圧力損失","ア 動圧/イ 静圧/ウ 圧力水頭","ア 静圧/イ 動圧/ウ 圧力損失","ア 静圧/イ 絶対圧/ウ 圧力水頭"],"a":1,"e":"速度による項(1/2)ρU²が動圧、圧力Pが静圧。実際の流れでは摩擦などで圧力損失が生じるため、両辺は等しくならない。","l":"法令外","c":""},{"id":"2024-52","s":2,"q":"自然換気の換気量について述べた次の文のうち、最も不適当なものはどれか。","o":["温度差による換気量は、給気口と排気口の高さの差の平方根に比例する。","温度差による換気量は、室内と屋外の空気の密度差の平方根に比例する。","風力による換気量は、風圧係数の差に比例する。","風力による換気量は、外部の風速に比例する。","開口部の風圧係数は、外の風の向きによって変わる。"],"a":2,"e":"換気量は開口部の前後の圧力差の平方根に比例するので、風力による換気量は風圧係数の差の平方根に比例する(風速には比例)。","l":"法令外","c":""},{"id":"2024-53","s":2,"q":"エアロゾル粒子の一般的な粒径が、大きい順に正しく並んでいるものはどれか。","o":["花粉 ＞ バクテリア ＞ ウイルス","ウイルス ＞ バクテリア ＞ 花粉","ウイルス ＞ 花粉 ＞ たばこ煙","たばこ煙 ＞ ウイルス ＞ バクテリア","バクテリア ＞ 花粉 ＞ たばこ煙"],"a":0,"e":"花粉は数十μm、バクテリア(細菌)は1μm前後、ウイルスはそれよりずっと小さいので、花粉＞バクテリア＞ウイルスの順になる。","l":"法令外","c":""},{"id":"2024-54","s":2,"q":"微生物とアレルゲンについて述べた次の文のうち、最も不適当なものはどれか。","o":["黄色ブドウ球菌は細菌に分類される。","浮遊しているダニアレルゲン粒子の除去にはエアフィルタが有効である。","ウイルスは結露水の中で増えやすい。","アスペルギルスはカビアレルゲンの一つに挙げられる。","ダンプネスとは、過度の湿気が原因でカビ臭さや微生物汚染などの問題が確認できる状態をいう。"],"a":2,"e":"ウイルスは生きた細胞の中でしか増えられないので、結露水の中で増えることはない。","l":"法令外","c":""},{"id":"2024-55","s":2,"q":"放射線は非電離放射線と電離放射線に分けられる。非電離放射線に分類されるものはどれか。","o":["α線","γ線","エックス線","赤外線","中性子線"],"a":3,"e":"赤外線は物質を電離させるほどのエネルギーをもたない非電離放射線。α線・γ線・エックス線・中性子線は電離放射線である。","l":"法令外","c":""},{"id":"2024-56","s":2,"q":"換気について述べた次の文のうち、最も不適当なものはどれか。","o":["1人あたりの必要換気量は、呼吸による酸素の消費量を基準に求めることが多い。","換気回数は、換気量を室の容積で割ったものである。","局所換気は、部屋全体ではなく、汚染物質が出る場所を部分的に換気する方法である。","機械換気は、送風機や排風機などの機械の力で室内の空気を入れ替える方法である。","自然換気を起こす力は、建物の外の風や建物内外の温度差である。"],"a":0,"e":"1人あたりの必要換気量は、一般に二酸化炭素濃度(1,000ppm)を基準にして求める。酸素の消費量ではない。","l":"法令外","c":""},{"id":"2024-57","s":2,"q":"室内の二酸化炭素について述べた次の文のうち、最も不適当なものはどれか。","o":["建築物衛生法の二酸化炭素の管理基準値は、換気量の目安として定められた値である。","東京都の立入検査結果を見ると、建築物衛生法の施行当時、二酸化炭素濃度の不適率は10〜20%台だった。","二酸化炭素の発生源は、人の活動(呼吸)や燃焼器具である。","二酸化炭素濃度の上昇には、設計時の想定より在室者が多い過密な使い方が関係する。","二酸化炭素濃度を下げる対策として、空調機のエアフィルタが挙げられる。"],"a":4,"e":"エアフィルタは粉じんを取る装置で、気体の二酸化炭素は除去できない。濃度を下げるには換気量を増やす。","l":"法令外","c":""},{"id":"2024-58","s":2,"q":"揮発性有機化合物と用途の組合せとして、最も不適当なものはどれか。","o":["ホルムアルデヒド ― ユリア系接着剤","トルエン ― 塗料の溶剤","パラジクロロベンゼン ― プラスチックの可塑剤","スチレン ― 発泡スチロール","クロルピリホス ― 防蟻剤"],"a":2,"e":"パラジクロロベンゼンは防虫剤に使われる物質(2025年度問56でも「防虫剤」の組合せが正しいとされている)。可塑剤ではない。","l":"法令外","c":""},{"id":"2024-59","s":2,"q":"湿り空気線図(h-x線図)で相対湿度を求めるときに使う2つの項目の組合せとして、最も不適当なものはどれか。","o":["乾球温度と湿球温度","水蒸気分圧と露点温度","露点温度と比エンタルピー","比エンタルピーと乾球温度","湿球温度と絶対湿度"],"a":1,"e":"水蒸気分圧と露点温度は、どちらも絶対湿度だけで決まる値なので、2つそろっても状態点が1つに決まらず、相対湿度は求められない。","l":"法令外","c":""},{"id":"2024-60","s":2,"q":"建築物の空気調和設計での熱負荷の大小関係として、最も適当なものはどれか。","o":["装置負荷 ＜ 熱源負荷 ＜ 室内負荷","室内負荷 ＜ 装置負荷 ＜ 熱源負荷","熱源負荷 ＜ 装置負荷 ＜ 室内負荷","室内負荷 ＜ 熱源負荷 ＜ 装置負荷","装置負荷 ＜ 室内負荷 ＜ 熱源負荷"],"a":1,"e":"装置負荷は室内負荷に外気負荷などを加えたもの、熱源負荷は装置負荷に配管などの負荷を加えたものなので、室内負荷＜装置負荷＜熱源負荷となる。","l":"法令外","c":""},{"id":"2024-61","s":2,"q":"次の空調熱負荷のうち、潜熱負荷を含むものとして最も適当なものはどれか。","o":["照明からの発熱負荷","ガラス窓からの通過熱負荷","外気負荷","ダクト通過熱負荷","送風機による負荷"],"a":2,"e":"外気には水蒸気が含まれるので、外気負荷には顕熱と潜熱の両方がある。ほかの4つは顕熱負荷だけである。","l":"法令外","c":""},{"id":"2024-62","s":2,"q":"個別方式の空気調和設備について述べた次の文のうち、最も不適当なものはどれか。","o":["水熱源ヒートポンプ方式のパッケージ型空調機には、冷房時の冷却水と暖房時の温水を別々の配管で送る。","パッケージ型空気調和機の圧縮機を動かす源には、電動機のほかガスエンジンもある。","個別方式の代表的な空気調和機は、パッケージ型空気調和機である。","ヒートポンプは、熱をくみ取る源(ヒートソース)によって水熱源と空気熱源に分けられる。","ビル用マルチパッケージは、インバータで圧縮機の容量を制御する機種が主流である。"],"a":0,"e":"水熱源ヒートポンプ方式では、冷房・暖房とも同じ熱源水の配管を各ユニットに回して使う。冷却水と温水を別配管で送るのではない。","l":"法令外","c":""},{"id":"2024-63","s":2,"q":"湿り空気線図上の状態の変化について述べた次の文のうち、最も不適当なものはどれか。","o":["湿り空気を加熱すると、相対湿度は下がる。","湿り空気を減湿すると、水蒸気分圧は下がる。","湿り空気を冷却すると、比容積は小さくなる。","湿り空気を加湿すると、露点温度は下がる。","湿り空気を冷却すると、比エンタルピーは下がる。"],"a":3,"e":"加湿すると絶対湿度が増えるので、露点温度は上がる。","l":"法令外","c":""},{"id":"2024-64","s":2,"q":"地域冷暖房システムについて述べた次の文のうち、最も不適当なものはどれか。","o":["個別の熱源システムに比べ、大気汚染などの環境負荷が小さくなる。","不特定多数の需要家に熱を送る熱源プラントは、規模の大小に関係なく熱供給事業法の対象になる。","各建築物の煙突や冷却塔がいらなくなり、都市の景観がよくなる。","熱源装置を大型化・集約化することで、効率のよい運用ができる。","個々の建築物の有効に使える床面積が広がり、収益性が増す。"],"a":1,"e":"熱供給事業法の対象は、加熱能力の合計が1時間あたり21ギガジュール以上の設備に限られる(熱供給事業法施行令第2条)。規模に関係なく対象になるわけではない。","l":"熱供給事業法 第2条、熱供給事業法施行令 第2条","c":""},{"id":"2024-65","s":2,"q":"下の図は、蒸気熱源吸収冷凍機の冷凍サイクルを示したものである。図中のA、B、Cに対応する蒸気、冷水、冷却水の組合せとして、最も適当なものはどれか。","o":["蒸気 A/冷水 C/冷却水 B","蒸気 B/冷水 A/冷却水 C","蒸気 B/冷水 C/冷却水 A","蒸気 C/冷水 A/冷却水 B","蒸気 C/冷水 B/冷却水 A"],"a":2,"e":"再生器につながるBは溶液を加熱する蒸気。蒸発器につながるCは冷水。吸収器から凝縮器へ流れるAは冷却水。","l":"法令外","c":"","g":["img/2024-65.png"]},{"id":"2024-66","s":2,"q":"冷凍機について述べた次の文のうち、最も不適当なものはどれか。","o":["二重効用吸収冷凍機は、蒸発のプロセスを増やして、単効用型吸収冷凍機より成績係数を高めたものである。","スクリュー圧縮機を使った冷凍機は、スクロール圧縮機を使ったものより、冷凍容量の大きい範囲で使われる。","遠心圧縮機は、容積式圧縮機に比べ、吸い込んで圧縮できるガスの量を大きくとれる。","往復動圧縮機は、シリンダ内のピストンが往復して冷媒ガスを圧縮する。","遠心圧縮機を使った冷凍機は、羽根車を高速で回せるので、大容量でもコンパクトにできる。"],"a":0,"e":"二重効用吸収冷凍機は、高温と低温の2つの再生器をもち、再生(吸収液から冷媒を追い出す)の段階を2段にして熱を有効に使うもの。蒸発の段階を増やしたものではない。","l":"法令外","c":""},{"id":"2024-67","s":2,"q":"蒸気圧縮冷凍サイクルについて述べた次の文のうち、最も不適当なものはどれか。","o":["圧縮機では、冷媒の比エンタルピーが上がる。","凝縮器では、周りに熱を捨てて冷媒が液体になる。","蒸発器では、周りから熱を奪って冷媒が気体になる。","膨張弁では、冷媒が気体になり圧力が上がる。","冷凍サイクルでは、圧縮機→凝縮器→膨張弁→蒸発器の順に冷媒がめぐる。"],"a":3,"e":"膨張弁では冷媒の圧力が下がり、温度も下がる。圧力が上がるのは圧縮機である。","l":"法令外","c":""},{"id":"2024-68","s":2,"q":"熱交換器について述べた次の文のうち、多管式熱交換器の説明にあたるものはどれか。","o":["熱交換器の中では、設置面積や重さが小さい。","中に封入した作動媒体が蒸発と凝縮をくり返して熱を運ぶ。","構造によってU字管式・全固定式・遊動頭式に分けられる。","伝熱板を増やしたり減らしたりして伝熱面積を変えられる。","一体成形されたブレージング型は、汚れやすい流体には向かない。"],"a":2,"e":"多管式(シェルアンドチューブ)熱交換器は、管の固定のしかたでU字管式・全固定式・遊動頭式に分けられる。(2)はヒートパイプ、(1)(4)(5)はプレート式の説明。","l":"法令外","c":""},{"id":"2024-69","s":2,"q":"標準的なエアハンドリングユニットを構成する機器として、最も不適当なものはどれか。","o":["圧縮機","熱交換器","加湿器","送風機","エアフィルタ"],"a":0,"e":"エアハンドリングユニットは、熱源から冷温水などを受けて空気を処理する装置で、圧縮機はもたない。圧縮機は冷凍機やパッケージ型空調機の部品である。","l":"法令外","c":""},{"id":"2024-70","s":2,"q":"加湿装置の基本構造と加湿方式の組合せとして、最も不適当なものはどれか。","o":["滴下式 ― 気化方式","遠心式 ― 気化方式","超音波式 ― 水噴霧方式","電極式 ― 蒸気方式","パン型 ― 蒸気方式"],"a":1,"e":"遠心式は、回転する円板で水を飛ばして細かい霧にする方式なので、水噴霧方式にあたる。","l":"法令外","c":""},{"id":"2024-71","s":2,"q":"ダクトと付属品について述べた次の文のうち、最も適当なものはどれか。","o":["長方形ダクトどうしの接続には、一般に差込み継手が使われる。","厨房のフードには、ステンレス鋼板が使われる。","厨房排気ダクト用の防火ダンパの温度ヒューズが溶ける温度は280℃である。","丸ダクトは、スパイラルダクトより、はぜによって高い強度が得られる。","防火ダンパは、煙感知器と連動してダクトを閉じる。"],"a":1,"e":"厨房フードは油や湿気にさらされるため、さびにくいステンレス鋼板が使われる。","l":"法令外","c":""},{"id":"2024-72","s":2,"q":"空気調和設備の送風機の特性と送風系についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「送風機の特性曲線は、グラフの横軸に[ア]、縦軸に[イ]をとって表す。送風系の[ウ]曲線は、同じグラフ上で原点を通る二次曲線として表す。2つの曲線の交点が運転点である。」","o":["ア 圧力/イ 風量/ウ 抵抗","ア 動力/イ 圧力/ウ 性能","ア 動力/イ 風量/ウ 圧力","ア 風量/イ 動力/ウ 性能","ア 風量/イ 圧力/ウ 抵抗"],"a":4,"e":"送風機の特性曲線は横軸に風量、縦軸に圧力をとる。ダクト系の抵抗は風量の2乗に比例するので、抵抗曲線は原点を通る二次曲線になる。","l":"法令外","c":""},{"id":"2024-73","s":2,"q":"空気浄化装置について述べた次の文のうち、最も不適当なものはどれか。","o":["空気浄化装置が取り除く対象の汚染物質は、粉じんと有害ガスである。","パネル型エアフィルタは、外気用や、高性能フィルタの前段のプレフィルタとして使われる。","電気集じん器は、高電圧の電界で粉じんに電気を帯びさせ、引き寄せて付着させて取り除く。","自動巻取り型エアフィルタのろ材には、合成繊維の不織布などが使われる。","HEPAフィルタは、有害ガスを化学吸着でとらえる専用のフィルタである。"],"a":4,"e":"HEPAフィルタは、ごく小さな粒子(粉じん)を高い効率でとらえる高性能のフィルタで、ガスを除去するものではない。","l":"法令外","c":""},{"id":"2024-74","s":2,"q":"空気調和設備のポンプについて述べた次の文のうち、最も不適当なものはどれか。","o":["ダイヤフラムポンプは、薬液の注入などに使われることが多い。","ターボ型ポンプは、連続して送水でき、脈動が少ない。","渦巻きポンプは、油の輸送など粘度の高い液体の輸送によく使われる。","ポンプの急停止による水撃作用を防ぐ方法として、緩閉式逆止め弁を使う方法がある。","流体の一部で圧力が下がり、局所的に蒸発して気泡ができる現象をキャビテーションという。"],"a":2,"e":"この記述が誤り。渦巻きポンプは水などの輸送に広く使われるポンプで、粘度の高い油の輸送向きではない。","l":"法令外","c":""},{"id":"2024-75","s":2,"q":"空気調和設備の配管の種類と使い道の組合せとして、最も不適当なものはどれか。","o":["圧力配管用炭素鋼鋼管 ― 高温水","一般配管用ステンレス鋼鋼管 ― 冷却水","水道用硬質塩化ビニルライニング鋼管 ― 冷却水","配管用炭素鋼鋼管(白管) ― 冷温水","耐熱性硬質ポリ塩化ビニル管 ― 蒸気"],"a":4,"e":"耐熱性硬質ポリ塩化ビニル管は給湯などに使うが、高温の蒸気には耐えられないので蒸気配管には使わない。","l":"法令外","c":""},{"id":"2024-76","s":2,"q":"換気設備について述べた次の文のうち、最も不適当なものはどれか。","o":["全熱交換器は、取り入れる外気と排気の間で熱交換し、外気負荷を減らして省エネルギーを図る装置である。","外気処理空調機は、居室に必要な外気の温湿度調整や空気浄化などを専門に行う装置である。","建築基準法施行令では、住宅等の居室のシックハウス対策で機械換気設備を使う場合、必要な換気量を換気回数0.3回/h以上と定めている。","便所や浴室では、換気設備を単独で設けることが多い。","建築物衛生法の空気環境の管理基準(空気調和設備を設けている特定建築物)では、一酸化炭素の含有率は6ppm以下とされている。"],"a":2,"e":"住宅等の居室の換気回数は0.5回/h以上(建築基準法施行令第20条の8)。0.3回/hは住宅等以外の居室の値。一酸化炭素6ppm以下は現行の施行令第2条どおり。","l":"建築基準法施行令 第20条の8、建築物衛生法施行令 第2条","c":""},{"id":"2024-77","s":2,"q":"環境の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["サーミスタ温度計は、電気抵抗式温度計の一種である。","相対湿度の測定には、毛髪などの伸び縮みを利用する方法がある。","アスマン通風乾湿計は、まわりの気流や熱放射の影響を防ぐ構造になっている。","ピトー管による風速の測定には、ストークスの定理を使う。","換気量の測定には、トレーサガスの濃度が減っていく様子を利用する方法がある。"],"a":3,"e":"ピトー管は全圧と静圧の差(動圧)から風速を求めるもので、ベルヌーイの定理を使う(2025年度問78でも「風速の測定にベルヌーイの定理を利用する」が正しい記述)。","l":"法令外","c":""},{"id":"2024-78","s":2,"q":"室内空気環境の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["微生物の測定には、ATP(アデノシン三リン酸)法がある。","ダニアレルゲンの測定には、酵素免疫測定法がある。","オゾンの測定には、検知管法がある。","ラドンガスの測定には、シンチレーションカウンタを使う方法がある。","アスベストの測定には、紫外線吸収スペクトル分析法がある。"],"a":4,"e":"この記述が誤り。アスベストは繊維を顕微鏡で数えるなどの方法で測定し、紫外線吸収スペクトル分析法は使わない。","l":"法令外","c":""},{"id":"2024-79","s":2,"q":"測定対象と測定法の組合せとして、最も不適当なものはどれか。","o":["酸素 ― ポーラログラフ方式","窒素酸化物 ― 溶液導電率法","一酸化炭素 ― ガスクロマトグラフ法","イオウ酸化物 ― 紫外線蛍光法","臭気 ― 3点比較式臭袋法"],"a":1,"e":"溶液導電率法は硫黄酸化物の測定法(2025年度問80でも正しい記述として出題)。窒素酸化物には化学発光法などを使う。","l":"法令外","c":""},{"id":"2024-80","s":2,"q":"ホルムアルデヒドの測定法の組合せとして、最も不適当なものはどれか。","o":["アクティブ法 ― DNPHカートリッジ捕集-HPLC法","アクティブ法 ― 検知管法","アクティブ法 ― 燃料電池法","パッシブ法 ― DNPH含浸チューブ-HPLC法","パッシブ法 ― 定電位電解法"],"a":4,"e":"この組合せが誤り。定電位電解法はポンプで空気を吸い込んで測るアクティブ法の測定器である。","l":"法令外","c":""},{"id":"2024-81","s":2,"q":"空気調和・換気設備の維持管理上の問題と、考えられる原因の組合せとして、最も不適当なものはどれか。","o":["全熱交換器からの外気量不足 ― 熱交換エレメントの目詰まり","冷却塔でのレジオネラ属菌の増殖 ― 冷却水の過剰な濃縮","室内空気質の低下 ― ダクト内部の汚れ","冬の暖房時の室内相対湿度の低下 ― 取り入れる外気量が少なすぎる","夏の冷房時の室内温度の上昇 ― ダンパの開きが足りず送風量が少なすぎる"],"a":3,"e":"冬の外気は乾燥しているので、湿度が下がる原因は外気の取入れ量が多すぎることである。少なすぎることではない。","l":"法令外","c":""},{"id":"2024-82","s":2,"q":"冷却塔と冷却水の維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["冷却水の強制ブローは、冷却水の濃縮を防ぐのに役立つ。","冷却水への薬剤処理は、適正な濃度を保つため、冷却塔への補給水量に比例した量の薬剤を注入して行う。","冷却塔と冷却水は、使用開始時と使用開始後1か月以内ごとに1回、定期に汚れの状況を点検する。","角形(クロスフロー)冷却塔は、丸形(カウンターフロー)冷却塔より冷却水が空中に飛び散りやすいので、より厳しく管理する必要がある。","冷却水系統のレジオネラ属菌の増殖を抑えるため、化学的洗浄と殺菌剤の添加を組み合わせる。"],"a":3,"e":"この記述が誤り。冷却塔の汚れの点検を使用開始時と1か月以内ごとに1回行うのは施行規則第3条の18のとおり。","l":"建築物衛生法施行規則 第3条の18","c":""},{"id":"2024-83","s":2,"q":"音と振動について述べた次の文のうち、最も不適当なものはどれか。","o":["振動が正弦波のとき、振動加速度の実効値は、加速度の最大振幅の1/2で求められる。","遮音とは、壁などで音をさえぎり、通り抜ける音のエネルギーを小さくすることである。","測りたい音が暗騒音より10dB以上大きければ、測定値はその音の値と判断できる。","コインシデンス効果が起きると、壁の透過損失は小さくなる。","人体への振動を扱うときは、振幅と同時に振動の方向をはっきりさせる必要がある。"],"a":0,"e":"正弦波の実効値は、最大振幅の1/√2(約0.707倍)である。1/2ではない。","l":"法令外","c":""},{"id":"2024-84","s":2,"q":"床衝撃音について述べた次の文のうち、最も不適当なものはどれか。","o":["軽量床衝撃音の対策には、床仕上げ材を柔らかくするのが効果的である。","重量床衝撃音は、おもに低周波数域の成分を含む。","床衝撃音の遮音等級Lr値は、値が小さいほど遮音性能が高い。","床衝撃音については、一般に学校よりホテルの方が高い遮音性能を求められる。","重量床衝撃音の対策は、床躯体構造の質量を減らすことが基本である。"],"a":4,"e":"重量床衝撃音は床の躯体を重く(質量を大きく)して抑えるのが基本(2025年度問84でも同じ内容が正答)。質量を減らすのは逆効果。","l":"法令外","c":""},{"id":"2024-85","s":2,"q":"面音源から出る音の伝わり方についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「寸法a×b(a＜b)の長方形の面音源で、面の中心から面に垂直な方向への距離をdとする。音源に近いd＜a/πでは[ア]としての伝わり方を示し、a/π＜d＜b/πでは線音源にあたる減衰を、d＞b/πでは[イ]にあたる減衰を示す。a/π＜d＜b/πの範囲では、音源からの距離が2倍になると[ウ]dB減衰する。」","o":["ア 点音源/イ 面音源/ウ 3","ア 点音源/イ 面音源/ウ 6","ア 面音源/イ 点音源/ウ 3","ア 面音源/イ 点音源/ウ 6","ア 面音源/イ 点音源/ウ 10"],"a":2,"e":"音源のごく近くでは面音源としてほとんど減衰せず、遠くでは点音源とみなせる。中間の線音源の範囲では、距離が2倍で10log2≒3dB減衰する。","l":"法令外","c":""},{"id":"2024-86","s":2,"q":"ある測定点で75dBの騒音レベルを出す機械を、6台同時に動かしたときの騒音レベルに最も近いものはどれか。ただし log10 2＝0.3010、log10 3＝0.4771とする。","o":["78dB","80dB","83dB","84dB","85dB"],"a":2,"e":"同じ音がn台なら75＋10log10 n。10log10 6＝10×(0.3010＋0.4771)＝7.78なので、75＋7.78＝82.78≒83dB。","l":"計算","c":""},{"id":"2024-87","s":2,"q":"空調機械室から出る騒音の伝わり方について、次のア〜ウの種類の組合せとして最も適当なものはどれか。\nア ダクトや管路の振動が原因の音\nイ 隔壁やすき間を通り抜けてくる、空調機から出た音\nウ ダクトの中を伝わって給排気口から出てくる音","o":["ア 固体伝搬音/イ 固体伝搬音/ウ 空気伝搬音","ア 固体伝搬音/イ 空気伝搬音/ウ 空気伝搬音","ア 固体伝搬音/イ 空気伝搬音/ウ 固体伝搬音","ア 空気伝搬音/イ 固体伝搬音/ウ 固体伝搬音","ア 空気伝搬音/イ 固体伝搬音/ウ 空気伝搬音"],"a":1,"e":"振動が構造体を伝わって出る音(ア)は固体伝搬音。空気中を伝わってくる音(イ・ウ)は空気伝搬音である。","l":"法令外","c":""},{"id":"2024-88","s":2,"q":"昼光照明と窓について述べた次の文のうち、最も不適当なものはどれか。","o":["直射日光による水平面照度は、地表での直射日光による法線面照度にcos h(h:太陽高度)をかけたものである。","間接昼光率は、室内の反射率の影響を受ける。","昼光率は、窓ガラスの透過率の影響を受ける。","面積が同じなら、側窓より天窓の方が多くの昼光を取り入れられる。","グローバル照度は、直射日光による照度と天空光による照度の合計である。"],"a":0,"e":"水平面照度＝法線面照度×sin h である(2025年度問89の計算もこの式で正答になる)。cos hではない。","l":"法令外","c":""},{"id":"2024-89","s":2,"q":"点光源の真下3.0mの水平面照度が600lxのとき、点光源の真下1.5mの水平面照度に最も近いものはどれか。","o":["300lx","600lx","1,200lx","2,400lx","3,600lx"],"a":3,"e":"照度は距離の2乗に反比例する。距離が1/2になると照度は4倍なので、600×4＝2,400lx。","l":"計算","c":""},{"id":"2024-90","s":2,"q":"照明器具の光源の交換方式などについての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「点灯しなくなった光源をそのつど交換する方式を[ア]といい、日本国内の事務所で最も多い方式である。一方、あらかじめ決めた交換時期になったら全数を交換する方式を[イ]という。光源の交換と[ウ]の時期をうまく組み合わせると、人件費の節約や美観の保持などに役立つ。」","o":["ア 個別的集団交換方式/イ 集団交換方式/ウ 清掃","ア 個別的集団交換方式/イ 集団的個別交換方式/ウ 配線交換","ア 個別交換方式/イ 集団交換方式/ウ 配線交換","ア 個別交換方式/イ 集団交換方式/ウ 清掃","ア 個別交換方式/イ 集団的個別交換方式/ウ 清掃"],"a":3,"e":"切れたものをそのつど替えるのが個別交換方式、時期を決めて全部替えるのが集団交換方式。交換と器具の清掃を同時に行うと効率がよい。","l":"法令外","c":""},{"id":"2024-91","s":3,"q":"日射・日照について、最も不適当なものはどれか。","o":["太陽から出る可視光線・紫外線・近赤外線のうち、紫外線の波長が最も長い。","遮熱性塗料や遮熱性舗装の特徴は、近赤外線をよく反射することである。","天空日射とは、太陽の光が大気中で散乱して地上に降り注いだものである。","アルベドとは、ある面に入った日射量に対して、その面が反射した日射量の割合をいう。","太陽定数とは、大気圏外で太陽に正面から向き合ったとき、単位面積あたりに入る放射エネルギーのことである。"],"a":0,"e":"波長は、紫外線 < 可視光線 < 近赤外線の順に長くなる。紫外線の波長が最も短い。","l":"法令外","c":""},{"id":"2024-92","s":3,"q":"建築物の基礎構造と地盤について、最も不適当なものはどれか。","o":["沖積層は、一般に大きな地耐力をもつ。","標準貫入試験は、地盤の強さや変形などの情報を得るために行う。","液状化は、海岸や埋立地などで起こりやすい。","圧密とは、粘土質の地盤に圧力がかかって水分が少しずつ抜け、地盤が縮むことをいう。","地業とは、基礎スラブより下に設ける割ぐり石や捨てコンクリートなどの部分をいう。"],"a":0,"e":"沖積層は比較的新しい軟らかい地層で、一般に地耐力は小さい。地耐力が大きいのは古い洪積層である。","l":"法令外","c":""},{"id":"2024-93","s":3,"q":"鉄筋コンクリート構造とその材料について、最も不適当なものはどれか。","o":["直接土に接する壁では、鉄筋に対するコンクリートのかぶり厚さを4cm以上にしなければならない。","工場でつくったプレキャストの鉄筋コンクリート部材を使うと、工期を短くできる。","鉄筋コンクリート用棒鋼の「SD」の記号は、丸鋼を表す。","梁のあばら筋は、せん断力に抵抗する。","柱の帯筋の径は、6mm以上とする。"],"a":2,"e":"SDは表面に凹凸のある異形棒鋼を表す記号で、丸鋼はSRである。","l":"建築基準法施行令 第77条、第79条(JIS G 3112)","c":""},{"id":"2024-94","s":3,"q":"鉄骨構造とその材料について、最も不適当なものはどれか。","o":["鋼材の強さは温度が上がると下がり、1,000℃ではほとんど0になる。","鉄骨構造の床には、デッキプレートなどが使われる。","鉄骨構造に使う鋼材には、形鋼、平鋼、鋼板などがある。","鋼材は、炭素量が増えるとねばり強さ(靭性)が増す。","鉄骨構造は、部材のつなぎ方によって、ラーメン構造・トラス構造などに大きく分けられる。"],"a":3,"e":"鋼材は炭素量が増えると強度や硬さは増すが、ねばり強さ(靭性)や伸びは低下する。","l":"法令外","c":""},{"id":"2024-95","s":3,"q":"建築材料とその性質について、最も不適当なものはどれか。","o":["アルミニウムの密度は、鋼の約1/3である。","セメントペーストは、水とセメントを練り混ぜたものである。","コンクリートは、鉄筋より熱を伝えにくい(熱伝導率が低い)。","単板積層材(LVL)は、薄い板を繊維の方向をそろえて重ねた軸材である。","伐ったばかりの木(生木)の含水率は、30%程度である。"],"a":4,"e":"含水率30%程度は木材の繊維飽和点の目安で、生木の含水率はそれより高い。","l":"法令外","c":""},{"id":"2024-96","s":3,"q":"仕上げ材料について、最も不適当なものはどれか。","o":["ポリ塩化ビニルは合成樹脂の一つで、床や内壁の仕上げ材などに使われる。","陶磁器質の材料は、一般に焼く温度が高いものほど水を吸いやすい。","左官材料を使う湿式工法の工期は、一般に乾式工法より長い。","ブロンズは、銅とすずの合金である。","グラスウール断熱材の中に湿気が入ると、断熱性が大きく下がる。"],"a":1,"e":"陶磁器質の材料は、焼く温度が高いほど緻密になり、吸水率は低くなる(磁器は吸水率が低く、陶器は高い)。","l":"法令外","c":""},{"id":"2024-97","s":3,"q":"ガス設備について、最も不適当なものはどれか。","o":["都市ガス(13A)がもれると、天井付近にたまりやすい。","マイコンメータには、地震などのときにガスを止める保安機能がある。","ガスが原因の中毒事故の大半は、ガス機器の不完全燃焼によるものである。","都市ガス事業者は、特定地下街のガス配管の漏えい検査を4年に1回以上行うことが法令で定められている。","燃料ガスを燃やすのに必要な空気量を理論空気量といい、ガス消費量1kWあたり約0.8〜0.9m³/hが必要である。"],"a":3,"e":"この記述が誤り。特定地下街などのガス配管の漏えい検査は、4年に1回よりも短い間隔で行うことが定められている。","l":"ガス事業法施行規則","c":""},{"id":"2024-98","s":3,"q":"建築物の運用と建築設備に関する用語の組合せとして、最も不適当なものはどれか。","o":["インバータ制御 ― 省エネルギー","LAN ― 情報・通信網","風力発電 ― 分散電源システム","ページング ― 構内放送設備","デューディリジェンス ― 防災対策"],"a":4,"e":"デューディリジェンスは、不動産取引などの際に、対象の価値やリスクを詳しく調べることであり、防災対策の用語ではない。","l":"法令外","c":""},{"id":"2024-99","s":3,"q":"輸送設備について、最も不適当なものはどれか。","o":["ロープ式エレベーターは、巻上機の速度を幅広く制御できる。","建物で使われるエレベーターの多くは、JIS規格にそったものである。","エレベーターの「火災時管制運転装置」とは、火災のときにエレベーターを一番近い階まで自動で運転するものである。","エスカレーターの安全装置は、利用者側の安全対策と機械側の異常対策に分けられる。","小荷物専用昇降機のかごの天井高さは、1.2m以下と定められている。"],"a":2,"e":"火災時管制運転は、火災のときにエレベーターを避難階まで運転して停止させるものである。最寄り階に止めるのは地震時管制運転。","l":"法令外","c":""},{"id":"2024-100","s":3,"q":"地震災害と防災対策について、最も不適当なものはどれか。","o":["地震の揺れの強さを示す指標として、日本では国際的なメルカリ震度階が使われている。","地震の規模を表すマグニチュードは、1大きくなるとエネルギーが約30倍になる。","同じ強さの構造物なら、地上より地震の揺れが増幅しにくい地下のほうが、構造的に安全性が高い。","緊急地震速報(警報)は、一定以上の規模の地震が起きたとき、気象庁から強い揺れが予想される地域に出される。","地震被害を減らすため、大規模な事業所には防災管理者を選ぶことが義務づけられている。"],"a":0,"e":"日本では、気象庁が定めた気象庁震度階級(震度0〜7の10階級)が使われている。","l":"法令外","c":""},{"id":"2024-101","s":3,"q":"建物の防火対策について、最も不適当なものはどれか。","o":["特定防火設備とは、鉄製の防火扉など、火災を閉じこめる性能をもつ防火設備である。","防炎製品とは、カーテン・暗幕・じゅうたんなどに薬剤処理をして燃えにくくしたもので、消防法令で定められている。","建築基準法令の非常用照明装置の、避難に有効な照度は、光源が白熱電灯の場合とLEDランプの場合で異なる。","第二種排煙は、給気ファンで排煙する部屋に正圧をかける排煙で、押出し排煙とも呼ばれる。","非常用進入口は、非常時に消防隊が入るための入口で、3階以上の階の窓などに赤い逆三角形の反射塗料で表示される。"],"a":1,"e":"消防法令で防炎性能が義務づけられているのは「防炎物品」(カーテン・じゅうたんなど)である。「防炎製品」は、法令の義務ではない任意の認定品(寝具など)を指す。","l":"消防法 第8条の3","c":""},{"id":"2024-102","s":3,"q":"防災・防犯の語句の組合せとして、最も不適当なものはどれか。","o":["無線ICタグ ― 入退室の認証装置","ストリートキャニオン ― ビル風の発生","サンクンガーデン ― 水害対策","パッシブセンサ ― 防犯対策","ライフライン ― 生活を支えるための諸施設"],"a":2,"e":"サンクンガーデンは、地面より低く掘り下げた庭(広場)で、雨水が流れこみやすく、水害対策ではなくむしろ浸水に注意が必要な場所である。","l":"法令外","c":""},{"id":"2024-103","s":3,"q":"建築基準法の用語について、最も不適当なものはどれか。","o":["居室とは、住む・働く・作業するなどの目的で続けて使う部屋で、階段や倉庫は含まない。","主要構造部とは、建物の構造上重要な壁・柱・梁・床・屋根・階段をいい、基礎や土台は含まない。","延焼のおそれのある部分とは、隣地境界線などから一定の距離内にある外壁・軒裏・開口部などのことで、材料や構造の燃えやすさとは関係ない。","耐火性能とは、通常の火災が終わるまでの間、建物の倒壊や延焼を防ぐために壁・柱・床などに必要な性能である。","建築物とは土地に定着する工作物で、鉄道の線路敷地内の運転保安に関する施設も含まれる。"],"a":4,"e":"鉄道や軌道の線路敷地内にある運転保安に関する施設などは、建築基準法の「建築物」から除かれている。","l":"建築基準法 第2条第1号","c":""},{"id":"2024-104","s":3,"q":"建築基準法の建築行為の用語について、最も不適当なものはどれか。","o":["模様替とは、既存の建物の部分を、おおむね同じ形・寸法・材料で改修する工事である。","既存の建物の床面積を増やすことは、増築に当たる。","既存の建物の全部または一部を取り壊し、前と構造・規模・用途が大きく変わらないものを建てることは、改築に当たる。","大規模の修繕とは、建物の主要構造部の1種以上について行う過半の修繕のことである。","同じ敷地の中で建物の位置を変えることは、移転に当たる。"],"a":0,"e":"おおむね同じ形・寸法・材料で行う改修は「修繕」である。模様替は、おおむね同じ位置で、異なる材料や仕様に替えて行う改修をいう。","l":"建築基準法 第2条第14号・第15号","c":""},{"id":"2024-105","s":3,"q":"建築物の管理について、最も不適当なものはどれか。","o":["リテラシーとは、情報やデータを管理し、活用する能力のことである。","BELSとは、中央監視・エネルギー管理・ビル管理などを含んだ包括的なシステムのことである。","冷暖房設備のCOP(成績係数)は、入力したエネルギーに対して出てきた熱量の割合を表す。","非常用発電機で電気を送る防災負荷とは、消火設備や排煙設備などに必要な電力のことである。","ステークホルダとは、企業・組織の利害関係者のことである。"],"a":1,"e":"BELSは建築物省エネルギー性能表示制度のこと。中央監視やエネルギー管理などを含む包括的なシステムはBEMS(ビルエネルギー管理システム)である。","l":"法令外","c":""},{"id":"2024-106","s":4,"q":"給水・排水の管理で使う用語と、その単位の組合せとして、最も不適当なものはどれか。","o":["給湯配管からの熱損失 ― W","腐食速度 ― mm/年","水の比熱 ― J/℃","水の密度 ― kg/m³","濁度 ― 度"],"a":2,"e":"比熱は質量あたりの量なので、単位は kJ/(kg・℃) などになる(2025年問121でも「15℃の水の比熱は4.186kJ/(kg・℃)」が正しい記述として出題)。J/℃は熱容量の単位。","l":"法令外","c":""},{"id":"2024-107","s":4,"q":"給水・排水に関する用語と説明の組合せとして、最も不適当なものはどれか。","o":["メカニカル形接合 ― ねじ込みや接着などで配管をつなぐ方法","毛細管現象 ― トラップのウェアに引っかかった糸くずや髪の毛によって、封水が少しずつ減る現象","着色障害 ― 主に給水配管材料の腐食でできた物質が水に溶けて起こる現象","生物膜法 ― 微生物が主な構成要素になっている膜を使って汚水を処理する方法","DPD法 ― 水道水の残留塩素を、発色試薬で簡単に測る方法"],"a":0,"e":"メカニカル形接合は、ねじ込み・溶接・接着などによらない機械的な接合方法である(2022年問108で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2024-108","s":4,"q":"給水・排水の管理に関する用語の組合せとして、最も不適当なものはどれか。","o":["水槽照度率 ― 水槽の外の照度に対する、水槽の中の照度の割合","スカム ― 排水槽の中に浮かんでいる物質","金属の不動態化 ― 酸化被膜ができること","給湯循環ポンプの背圧 ― ポンプの吐出し側にかかる圧力","異臭味 ― 藻類や放線菌がつくり出すもの"],"a":3,"e":"(4)の組合せが誤り。","l":"法令外","c":""},{"id":"2024-109","s":4,"q":"塩素消毒の特徴に関する記述として、最も不適当なものはどれか。","o":["大量の水でも扱いやすく、決まった量を注入しやすい。","窒素化合物と反応すると、消毒の効果が下がる。","塩素剤が残っているかの確認や、濃度の測定が簡単にできる。","有害な有機塩素化合物を減らす。","アルカリ側(pHが高い側)では消毒の効果が急に下がる。"],"a":3,"e":"塩素消毒は有害な有機塩素化合物を減らすのではなく、生成する原因になる。トリハロメタンは有機物と消毒用の塩素が反応してできる物質である(2017年問107・2023年問107で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2024-110","s":4,"q":"給水設備で水質が悪くなる原因に関する記述として、最も不適当なものはどれか。","o":["スケールは水の硬度成分によってでき、配管が詰まる原因になる。","赤水は、亜鉛めっき鋼管の給水配管で亜鉛層の防食効果がなくなり、下地の鉄が腐食することで起こる。","スライム障害は細菌類や藻類が増えることで起こり、消毒効果が下がる原因になる。","白濁水は、亜鉛めっき鋼管の亜鉛の腐食生成物が水に混ざって白くにごることで起こる。","トリハロメタンは、水槽の中の水温が下がると、できる量が増える傾向がある。"],"a":4,"e":"トリハロメタンは、水温が下がるのではなく、水温が上がるとできる量が増える傾向がある。","l":"法令外","c":""},{"id":"2024-111","s":4,"q":"給水設備の汚染に関する記述として、最も不適当なものはどれか。","o":["クロスコネクションとは、飲料水の系統とほかの配管系統を、配管などで直接つなぐことである。","容量の大きい貯水槽では、槽の中に迂回壁を設けて、水がよどむ場所ができるのをおさえる。","大便器の洗浄弁には、大気圧式バキュームブレーカを設ける。","上水の配管から消火系統へ水を補給するときは、消火用水槽を設けて行う。","洗面器の吐水口空間とは、水栓の吐水口の端から、水受け容器のオーバフロー口までの垂直距離である。"],"a":4,"e":"洗面器の吐水口空間は、給水栓の吐水口と洗面器のあふれ縁との垂直距離である(2025年問116で正しい記述として出題)。オーバフロー口までではない。","l":"法令外","c":""},{"id":"2024-112","s":4,"q":"給水設備に関する語句と数値の組合せとして、最も不適当なものはどれか。","o":["事務所ビルでゾーニングをした場合の給水の上限水圧 ― 0.5MPa","高等学校の1日あたりの設計給水量 ― 200〜250L/人","節水器具を使う事務所ビルの1日あたりの設計給水量 ― 40〜60L/人","給水配管の適正な流速 ― 0.9〜1.2m/s","大便器洗浄弁に必要な水圧 ― 70kPa"],"a":1,"e":"高等学校の1日あたりの設計給水量を200〜250L/人とした組合せが誤り。","l":"法令外","c":""},{"id":"2024-113","s":4,"q":"給水配管に関する記述として、最も不適当なものはどれか。","o":["硬質ポリ塩化ビニル管は、一般に融着接合でつなぐ。","飲料水の配管は、ほかの配管系統と見分けがつくようにする。","ウォータハンマ防止器は、ウォータハンマが起こる場所の近くに設ける。","銅管では、銅イオンが水に溶け出して青水が出ることがある。","ステンレス鋼管は、酸化被膜によって腐食に強い。"],"a":0,"e":"硬質ポリ塩化ビニル管は、一般に接着接合でつなぐ(2025年問112で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2024-114","s":4,"q":"給水設備の機器に関する記述として、最も不適当なものはどれか。","o":["木製の貯水槽は断熱性に優れているので、結露対策がいらない。","FRP製の貯水槽には、藻類が増えないように光を通しにくくした製品がある。","ポンプ直送方式の加圧ポンプには、水量と圧力の関係から末端の圧力が一定になるよう制御する推定末端圧力一定制御方式がある。","渦巻きポンプは、羽根車を高速で回して水に向心力を与え、吐き出す。","受水槽から高置水槽へ水を送る揚水ポンプは、高置水槽の水位によって起動・停止させる。"],"a":3,"e":"渦巻きポンプについて「水に向心力を与えて吐き出す」とした点が誤り(2017年問112でも同じ記述が誤りとして出題)。","l":"法令外","c":""},{"id":"2024-115","s":4,"q":"建築物の給水方式に関する記述として、最も不適当なものはどれか。","o":["直結直圧方式は、配水管の圧力の関係で、水を送れる高さに限りがある。","直結増圧方式は、引込み管の管径に制限がある。","高置水槽方式は、安定した水圧と水量が得られる。","直結増圧方式には、増圧ポンプを直列に複数つなぐ直列多段型がある。","ポンプ直送方式は、受水槽がいらない方式である。"],"a":4,"e":"ポンプ直送方式は受水槽を必要とする方式で、受水槽の水をポンプで直接送る。","l":"法令外","c":""},{"id":"2024-116","s":4,"q":"給水設備に関する記述として、最も不適当なものはどれか。","o":["可とう継手は、建物の揺れ、地盤の不同沈下、配管の振動などによるずれを吸収するために取り付ける。","ウォータハンマとは、給水管で弁を急に閉めたとき、弁の下流側に起こる大きな圧力上昇が、圧力の波として管に伝わる現象である。","合成樹脂管のクリープ劣化とは、合成樹脂に熱応力が長時間かかり続けると、材料の変形が時間とともに進むことをいう。","吸排気弁は、給水管内の空気を出すことと、管内が負圧になったときの逆流を防ぐために設ける。","さや管ヘッダ工法とは、集合住宅の住戸内などで、ヘッダから各器具へ1本ずつさや管を使って配管する工法である。"],"a":1,"e":"ウォータハンマで著しい圧力上昇が起こるのは、弁の下流側ではなく上流側である。","l":"法令外","c":""},{"id":"2024-117","s":4,"q":"給水設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["貯水槽の付属装置である定水位弁や電極棒が正しく動かないと、断水や溢水(あふれ)事故が起こることがある。","ポンプ直送方式では、ポンプが止まったときや性能が落ちたときなどに、上の階の給水管内が負圧になりやすい。","防錆剤の注入と管理の業務は、建築物衛生法の建築物飲料水水質検査業の登録を受けた者が行わなければならない。","管更生工法で管の内側に合成樹脂ライニングをする場合は、技術評価・審査証明を受けた工法を選ぶのがよい。","給水栓で決められた値の残留塩素を保てない場合は、塩素剤の注入装置を設けて適切に管理する。"],"a":2,"e":"防錆剤の注入・管理を飲料水水質検査業の登録業者が行わなければならない、という決まりはない(2016年問115・2022年問116でも同じ記述が誤りとして出題)。","l":"法令外","c":""},{"id":"2024-118","s":4,"q":"給湯に関する記述として、最も不適当なものはどれか。","o":["給湯設備で扱う範囲の水は、ほとんど圧縮されない(非圧縮性)。","配管内の水に溶ける気体の量(溶解度)は、水温が上がると減る。","水に溶けている空気は、配管内の圧力が低いと分離しにくい。","湯をポンプでくみ上げるとき、吸い上げられる高さは温度が高いほど低くなる。","給湯設備の金属材料は、水温が高いほど腐食の速度が速くなる。"],"a":2,"e":"水に溶けている空気は、配管内の圧力が高いと分離しにくく、圧力が低いと分離しやすい(2016年問117・2021年問119・2025年問121で「圧力が高いと分離されにくい」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-119","s":4,"q":"給湯に関する記述として、最も不適当なものはどれか。","o":["銅管に単式の伸縮管継手を使う場合、設置の間隔は30m程度である。","中央式給湯設備の末端の給湯温度は、使用のピーク時でも55℃以上にする。","壁掛けシャワーの使用温度は、42℃程度である。","ガス瞬間湯沸器の能力は一般に号数で表し、1号は加熱能力1.74kWにあたる。","加熱装置での給湯温度と返湯温度の差は、一般に5℃程度にする。"],"a":0,"e":"銅管の単式伸縮管継手の設置間隔を30m程度とした記述が誤り。","l":"法令外","c":""},{"id":"2024-120","s":4,"q":"給湯に関する記述として、最も不適当なものはどれか。","o":["ポリブテン管の使用温度は、JISで90℃以下とされている。","貯湯槽の容量は、ピーク時に必要な量の1〜2時間分を目安に、加熱能力とのバランスで決める。","厨房の業務用皿洗い機のすすぎ温度は、80℃程度である。","ホテルの宿泊部分の設計給湯量は、150〜250L/(人・日)程度である。","複式のベローズ形伸縮管継手の最大伸縮量は、35mm程度である。"],"a":4,"e":"複式のベローズ形伸縮管継手の最大伸縮量を35mm程度とした記述が誤り。","l":"法令外","c":""},{"id":"2024-121","s":4,"q":"給湯設備の加熱装置に関する記述として、最も不適当なものはどれか。","o":["ガス瞬間湯沸器には、給湯のほかに風呂の追い焚き機能をもつものがある。","加熱コイル付き貯湯槽は、蒸気などの熱媒が得られる場合に使われる。","ガスマルチ式給湯機は、小型のガス瞬間湯沸器を何台もつないでユニットにしたものである。","電気温水器は、加熱装置と貯湯槽をもっている給湯器である。","給湯用の貫流ボイラは、出てくる湯の温度が安定していて、大規模なシャワー設備の給湯に向いている。"],"a":4,"e":"給湯用貫流ボイラについて「出湯温度が安定し、大規模シャワー設備に向く」とした記述が誤り。","l":"法令外","c":""},{"id":"2024-122","s":4,"q":"給湯設備の配管に関する記述として、最も不適当なものはどれか。","o":["横管が凹形の配管になる場合は、水を抜くための止水弁を設ける。","ポンプの揚程は、循環管路で最も長くなる管路の摩擦抵抗と局部抵抗による圧力損失から決める。","架橋ポリエチレン管の線膨張係数は、ステンレス鋼管より小さい。","銅管は、循環配管を設けない一管式配管では、腐食がほとんど起こらない。","樹脂管を温度の高い湯に使うと、塩素による劣化が起こりやすい。"],"a":2,"e":"架橋ポリエチレン管の線膨張係数は、ステンレス鋼管より大きい(2017年問120で「ステンレス鋼管の線膨張係数は架橋ポリエチレン管より小さい」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-123","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["真空式温水発生機は、缶体の中を大気圧より低く保ちながら水を沸騰させる。","耐熱性硬質ポリ塩化ビニルライニング鋼管には、管端防食継手を使う。","ヒートポンプは、排熱を利用した給湯の熱源機器としても使われる。","給湯を止められない施設では、貯湯槽を複数台に分ける必要がある。","熱交換器で排水から熱を回収する場合は、熱効率を上げるために直接熱交換を行う。"],"a":4,"e":"排水から熱を回収する場合は、熱交換器の腐食などによる湯の汚染を防ぐため、間接熱交換方式にする(2023年問117で正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-124","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["器具のワッシャには、細菌が増えるのを防ぐために合成ゴム製のものを使う。","貯湯槽に流電陽極式の電気防食がしてある場合は、犠牲陽極の腐食の状態を調べる。","各配管に給湯水を均等に循環させるため、給湯往管(行きの管)に付いている弁の開き具合を調整する。","貯湯槽は、定期的に底部にたまった水を排出する。","給湯配管は、給水系統の配管の洗浄方法に準じて洗浄することが望ましい。"],"a":2,"e":"給湯水を均等に循環させるための調整は、返湯管側で行う(2021年問123・2023年問119で「返湯管に定流量弁を設ける」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-125","s":4,"q":"雑用水設備に関する記述として、最も不適当なものはどれか。","o":["雑用水の供給設備は、雑用水受水槽・ポンプ・配管類・末端の器具などでできている。","し尿を含む原水からつくった雑用水は、散水用の水に使える。","雑用水受水槽の内面は、合成樹脂防水モルタルなどで防水処理をする。","雑用水の配管は、上水管と違う色で塗る。","排水を再処理した雑用水では、スライムが発生しやすい。"],"a":1,"e":"散水・修景・清掃に使う雑用水には、し尿を含む水を原水として使ってはならない(建築物衛生法施行規則第4条の2第1項第3号イ)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2024-126","s":4,"q":"雨水を雑用水として使う標準的な雨水処理施設で、次の処理の流れの【ア】【イ】に入る装置の組合せとして、最も適当なものはどれか。\n集水 → スクリーン → 【ア】 → 【イ】 → 雨水貯留槽 → 消毒装置 → 雑用水槽 → 給水","o":["ア:沈砂槽 ― イ:活性炭吸着装置","ア:流量調整槽 ― イ:活性炭吸着装置","ア:沈砂槽 ― イ:沈殿槽","ア:生物処理槽 ― イ:沈殿槽","ア:流量調整槽 ― イ:生物処理槽"],"a":2,"e":"標準的な雨水処理では、スクリーンの後に沈砂槽、沈殿槽を通してから雨水貯留槽にためる。","l":"法令外","c":""},{"id":"2024-127","s":4,"q":"建築物衛生法施行規則にもとづく雑用水の水質検査で、2か月以内ごとに1回、定期に行う項目として、正しいものはどれか。","o":["外観","臭気","pH","大腸菌","残留塩素"],"a":3,"e":"2か月以内ごとに1回検査するのは大腸菌(散水・修景・清掃用ではさらに濁度)。pH値・臭気・外観と遊離残留塩素は7日以内ごとに1回である(施行規則第4条の2)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2024-128","s":4,"q":"下水道に関する記述として、最も不適当なものはどれか。","o":["合流式とは、生活排水と工場排水を同じ管渠で流す方式をいう。","下水道は、流域下水道・公共下水道・都市下水路に分けられる。","下水道の施設は、排水管渠・処理施設・ポンプ施設などでできている。","公共下水道の事業を行うのは、原則として市町村である。","排水の水質のBODが基準値以上の場合は、除害施設を設ける必要がある。"],"a":0,"e":"合流式を「生活排水と工場排水を同じ管渠で流す方式」とした記述が誤り。合流式は汚水と雨水をいっしょに流す方式で、下水道法施行令でも、合流式の排水施設には雨水の影響が大きいときに下水の一部を放流する「雨水吐」が設けられることが定められている。","l":"下水道法施行令 第5条の4","c":""},{"id":"2024-129","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["厨房用の口径100mmの排水管に設ける掃除口の口径は、100mmとする。","管径125mmの排水横管の最小勾配は、1/150とする。","ドーム状のルーフドレンのストレーナ部分の開口面積は、つながる排水管の断面積の2倍程度必要である。","器具排水管から各個通気管を取り出すときは、トラップのウェアから管径の2倍以上離れた位置で取り出す。","飲料用貯水槽の間接排水管の口径が65mmのとき、排水口空間は最小125mmとする。"],"a":4,"e":"飲料用貯水槽の間接排水管の排水口空間は最小150mmである(2016年問130で「口径65mmの場合は最小150mm」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-130","s":4,"q":"排水槽と排水ポンプに関する記述として、最も不適当なものはどれか。","o":["排水槽の底の勾配は、吸込みピットに向かって1/15とする。","排水槽の中をブロワでばっ気すると正圧になるので、排気を行う。","厨房用の排水槽から排水を出すには、汚水ポンプを使う。","排水用の水中ポンプは、吸込みピットの壁面から200mm以上離して設置する。","排水槽のマンホールは、水中ポンプやフート弁の真上に設ける。"],"a":2,"e":"厨房用の排水槽から排水を除くには、汚物ポンプを使う(2025年問132で正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-131","s":4,"q":"排水通気配管に関する記述として、最も不適当なものはどれか。","o":["結合通気管は、高層建築物でブランチ間隔10以上の排水立て管に、最上階から数えてブランチ間隔10以内ごとに設ける。","通気管の末端を窓や換気口の近くで大気に開放する場合、窓・換気口の上端から600mm以上立ち上げて開口する。","通気立て管の下部は、排水立て管につながる最も低い排水横枝管より高い位置で、排水立て管から取り出す。","伸頂通気方式では、排水立て管と排水横主管の接続に大曲がりベンドなどを使う。","通気立て管の上部は、最も高い位置の衛生器具のあふれ縁から150mm以上高い位置で伸頂通気管につなぐ。"],"a":2,"e":"通気立て管の下部は、最低位の排水横枝管より低い位置で排水立て管から取り出す(2017年問127・2023年問129で正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-132","s":4,"q":"排水通気設備に関する語句の組合せとして、最も不適当なものはどれか。","o":["特殊継手排水システム ― ホテルの客室系統に使う","通気弁 ― 寒冷地の集合住宅に使う","排水鋼管用可とう継手 ― 排水用硬質塩化ビニルライニング鋼管の接続","プールのオーバフロー排水 ― 排水口開放として排水する","即時排水型ビルピット設備 ― 排水槽の悪臭防止に効果がある"],"a":3,"e":"(4)の組合せが誤り。","l":"法令外","c":""},{"id":"2024-133","s":4,"q":"排水ますと掃除口に関する記述として、最も不適当なものはどれか。","o":["排水横管の掃除口の間隔は、管径が100mmを超える場合、通常30m以内とする。","敷地排水管の直管が長い場合、排水ますは管内径の120倍を超えない範囲に設ける。","雨水ますの流出管は、流入管より管底を20mm程度下げて設ける。","排水立て管の掃除口は、3〜5階おきくらいの間隔で設ける。","雨水ますの底には、100mm程度の泥だめを設ける。"],"a":4,"e":"雨水ますの底部には150mm以上の泥だめを設ける(2025年問129で正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-134","s":4,"q":"排水設備の維持管理に関する記述として、最も不適当なものはどれか。","o":["排水用の水中ポンプは、6か月〜1年に1回、メカニカルシール部のオイルを交換する。","排水槽の悪臭対策として、排水をためておく時間が5〜6時間程度になるよう、タイマ制御で強制排水する。","グリース阻集器に付いているトラップの清掃は、2か月に1回程度行う。","排水槽の清掃は、酸素濃度を確かめた後、硫化水素濃度が10ppm以下であることを測って確かめてから行う。","通気管は、1年に1回程度、定期的に系統ごとに異常がないか点検・確認する。"],"a":1,"e":"悪臭防止のためのタイマ制御による強制排水は、1〜2時間を超えて排水をためないように行う(2021年問133で正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-135","s":4,"q":"排水管の清掃・維持管理に関する記述として、最も不適当なものはどれか。","o":["スネークワイヤ法を排水立て管の清掃に使う場合、長さ30m程度が限界である。","排水管に付いた有機性の汚れは、アルカリ性洗浄剤で取り除く。","高圧洗浄による排水管の清掃では、5〜30MPaの圧力の水を噴射して洗う。","ロッド法では、1〜1.8mのロッドをつないで、手で排水管に入れて清掃する。","排水管内部の腐食の診断には、内視鏡のほか、X線などの非破壊検査機器が使われる。"],"a":0,"e":"スネークワイヤ法を排水立て管に使う場合の限界は、長さ20m程度である(2021年問134で正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-136","s":4,"q":"衛生器具設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["プラスチック製の衛生器具は、水やぬるま湯にひたして固くしぼったやわらかい布でふく。","小便器の排水の状態は、6か月に1回、定期に点検する。","ステンレスに付いた油汚れは、うすめた中性洗剤を付けたスポンジなどで洗い、洗剤分を完全に洗い流す。","大便器の洗浄タンクの中の汚れの状態は、6か月に1回、定期に点検する。","洗面器のトラップの接合部にゆるみがないかは、1年に1回、定期に点検する。"],"a":4,"e":"洗面器のトラップ接合部のゆるみの点検を1年に1回とした記述が誤り。","l":"法令外","c":""},{"id":"2024-137","s":4,"q":"浄化槽法第1条(目的)に書かれている事項として、誤っているものはどれか。","o":["浄化槽の設置・保守点検・清掃・製造について規制すること","浄化槽製造業の登録制度を整備すること","浄化槽清掃業の許可制度を整備すること","浄化槽設備士と浄化槽管理士の資格を定めること","浄化槽によって、し尿と雑排水を適正に処理すること"],"a":1,"e":"第1条で登録制度を整備するとされているのは「浄化槽工事業者」であり、浄化槽製造業ではない(浄化槽法第1条)。","l":"浄化槽法 第1条","c":""},{"id":"2024-138","s":4,"q":"特殊設備に関する記述として、最も不適当なものはどれか。","o":["入浴設備に気泡発生装置などエアロゾルを出す設備を付ける場合は、空気の取入口から土ぼこりが入らない構造にする。","プール水の消毒設備では、塩素剤に加えて、オゾン消毒や紫外線消毒を併用する例がある。","子どもが水遊びをする親水施設の水には、衛生を保つため、使い方によってはプールなみの浄化装置が必要になる。","食品製造の管理システムであるHACCP方式は、できあがった最終製品を対象に安全確認の検査をする手法である。","入浴設備の循環水は、浴槽の底に近い部分から供給する。"],"a":3,"e":"HACCPは、原材料の受入れから最終製品の出荷までの各段階のリスクを分析し、重要管理点を決めて連続的に監視する衛生管理手法である(2017年問140・2023年問139で正しい記述として出題)。最終製品だけを検査する手法ではない。","l":"法令外","c":""},{"id":"2024-139","s":4,"q":"防火設備と消防用設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["防火設備定期検査制度により、建築基準法施行令と特定行政庁が定めた条件にあてはまる建築物の防火設備は、一級建築士・二級建築士または防火設備検査員が1年に1回作動状況などを確認する。","消防用設備等に付いている動力消防ポンプは、1年に1回機器点検を行う。","防火管理者は日常点検として消防用設備の異常信号などを確認し、異常があればすぐに修理して機能を回復させる。","特定防火対象物では、法定定期点検の結果と不備の是正措置の報告を1年に1回行う。","機器点検のうち外観点検とは、消防用設備等の機器が適正に配置されているかなど、主に外観から判断できることを点検基準に従って確認することである。"],"a":1,"e":"動力消防ポンプの点検は6か月に1回行う(2020年問140で「6か月に1回作動点検を行う」が正しい記述として出題)。なお特定防火対象物の報告が1年に1回であることは消防法施行規則第31条の6第3項に定めがある。","l":"消防法施行規則 第31条の6第3項(選択肢4)","c":""},{"id":"2024-140","s":4,"q":"消火設備に関する組合せとして、最も不適当なものはどれか。","o":["閉鎖型スプリンクラー設備 ― 自動で散水して消火する","ハロゲン化物消火設備 ― 負触媒作用で消火する","消火器 ― 火災を見つけた初期の段階で消火する","屋内消火栓設備 ― 公設消防隊だけが使って消火する","泡消火設備 ― 油火災の消火"],"a":3,"e":"屋内消火栓設備は、公設消防隊専用の設備ではない(2016年問140でも「公設消防隊が使用する消防隊専用栓」は誤りとして出題)。","l":"法令外","c":""},{"id":"2024-141","s":5,"q":"「建築物における衛生的環境の維持管理について」(平成20年1月25日 健発第0125001号)に示された建築物環境衛生維持管理要領について述べた次の文のうち、最も不適当なものはどれか。","o":["清掃用の機械・器具は清潔なものを使い、汚れの度合いを考えて区域ごとに使い分けるなど、適切に使用・管理すること。","天井など日常の清掃が届きにくい箇所や、照明器具、給排気口は、1年以内ごとに1回、定期に汚れの状況を点検し、必要に応じて除じん・洗浄を行うこと。","収集・運搬設備や貯留設備などの廃棄物処理設備は、6か月以内ごとに1回点検し、必要に応じて補修や消毒などを行うこと。","清掃用の機械・器具と清掃用資材の保管庫は、6か月以内ごとに1回点検し、必要に応じて整備や取替えなどを行うこと。","建築物内で出る廃棄物について、所有者等は分別できる環境を整え、利用者に分別を促すこと。"],"a":1,"e":"日常的に清掃を行わない箇所の汚れの点検は、6か月以内ごとに1回である(告示第119号 第5の一の3)。1年以内ではない。","l":"平成15年厚生労働省告示第119号 第5","c":""},{"id":"2024-142","s":5,"q":"建築物清掃管理仕様書に一般に書かれる項目として、最も不適当なものはどれか。","o":["建築物清掃の目的や内容","使用する資機材","清掃作業に従事する人数","業務計画と報告","規律の維持"],"a":2,"e":"この選択肢が誤り。清掃作業従事者の人数は、清掃管理仕様書に一般に書く項目ではない。","l":"法令外","c":""},{"id":"2024-143","s":5,"q":"建築物清掃の作業計画について述べた次の文のうち、最も適当なものはどれか。","o":["廊下の壁のスポット洗浄は、一般に定期清掃で行う。","エレベーターかご内の除じんは、一般に定期清掃で行う。","階段の手すり拭きは、一般に定期清掃で行う。","トイレ・洗面所の換気口の除じんは、一般に日常清掃で行う。","洗面台の洗浄は、一般に定期清掃で行う。"],"a":0,"e":"廊下の壁のスポット洗浄は定期清掃で行う。エレベーターかご内の除じん、手すり拭き、洗面台の洗浄は毎日行う日常清掃、換気口の除じんは定期清掃にあたる。","l":"法令外","c":""},{"id":"2024-144","s":5,"q":"清掃の作業手順書についての次の文の[  ]に入る語句として、最も適当なものはどれか。\n「作業手順書とは、一つひとつの作業のマニュアルである。作業名、行う作業項目、作業手順、[  ]、注意事項、作業終了後の品質状態などを書いたもので、従事者の教育指導に使う。」","o":["作業計画の作成方法","作業実施記録の書き方","作業スケジュールの管理方法","組織管理体制","使用する資機材と数量"],"a":4,"e":"作業手順書には、その作業で使う資機材の種類と数量を書く(2025年度問142でも「使用清掃資機材の種類と数量」が作業手順書の項目とされている)。","l":"法令外","c":""},{"id":"2024-145","s":5,"q":"建築物清掃管理の評価について述べた次の文のうち、最も不適当なものはどれか。","o":["品質評価の目的の一つは、求められる品質と実際の品質の差を修正することである。","組織品質は、事業所管理品質と現場管理品質の2つでできている。","長期的な維持管理の観点から、作業の評価は日常的なチェックだけでは足りない。","管理者が評価を行う場合は、四半期ごとに1回行うよう計画する。","作業の改善点は、仕様書や作業基準表の内容に限ったうえで決める。"],"a":4,"e":"改善点は、仕様書や作業基準表の範囲に限らず、利用者の要望や現場の状況なども含めて広く検討する。","l":"法令外","c":""},{"id":"2024-146","s":5,"q":"予防清掃について述べた次の文のうち、最も不適当なものはどれか。","o":["細かいごみやたばこの灰などをなるべく散らかさないよう、適当な容器を用意する。","衣服や内装材・家具は、なるべくすり減りにくいものを使う。","土ほこりを放っておくと、床材や床維持剤が削られ、さらに多くのほこりが出る。","ほこりが多く出る場所は、除じん作業の回数を適切に調整する。","気密性の高い建築物では、窓やすき間がほこりの侵入路として重要である。"],"a":4,"e":"気密性の高い建築物では窓やすき間からの侵入は少なく、おもな侵入路は人の出入りする出入口(靴底など)である。","l":"法令外","c":""},{"id":"2024-147","s":5,"q":"ビルクリーニング用機械の構造について述べた次の文のうち、最も不適当なものはどれか。","o":["真空掃除機は、電動ファンで機械の中に空気の低圧部をつくり、ホースなどからほこりと空気を吸い込む。","アップライト型真空掃除機は、繊維床より弾性床のほこりを取るのに向いた構造である。","床移動型のウェット式真空掃除機は、モータ部をぬらさずに泥水や洗浄汚水を吸い取れる。","手動スイーパは、床を押して進むと回転ブラシがごみを掃き取り、本体の中に巻き込む。","エクストラクタは、ノズルから洗浄液を吹き付けてすぐに吸い取る。"],"a":1,"e":"アップライト型真空掃除機は、回転ブラシでパイルをかき起こしながら吸い込む構造で、カーペットなどの繊維床に向く。","l":"法令外","c":""},{"id":"2024-148","s":5,"q":"ビルクリーニング用器具について述べた次の文のうち、最も不適当なものはどれか。","o":["凹凸のある床は、研磨粒子の付いたパッドを床磨き機に付けて洗う。","不織布タイプのダストモップは、繊維のすき間にほこりを取り込むので、使い捨てが一般的である。","自在ぼうきは馬毛などを植えた薄いブラシで、ほこりを舞い上げることが少ない。","改良ちり取り(文化ちり取り)は、移動するときにごみがこぼれないので、拾い掃きに向いている。","床維持剤を塗るフラット型モップは、房が短いので壁や幅木を汚しにくい。"],"a":0,"e":"パッドは平らな面にしか当たらないので、凹凸のある床はブラシを床磨き機に付けて洗う(2025年度問148でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-149","s":5,"q":"清掃分野での床維持剤の説明として、最も不適当なものはどれか。","o":["フロアオイル ― 鉱油が主成分で、木質系床材の保護と美観の向上に使う","フロアポリッシュ ― 塗って乾くと皮膜をつくり、物理的・化学的な方法で簡単に除去できる製品群","フロアシーラ ― 塗って乾くと皮膜をつくり、物理的・化学的な方法でも簡単には除去できない製品群","水性フロアポリッシュ(ポリマータイプ) ― 不揮発性成分として、合成樹脂などのポリマが主原料","水性フロアポリッシュ(ワックスタイプ) ― 一般に樹脂ワックスと呼ばれ、フロアポリッシュの主流"],"a":4,"e":"樹脂ワックスと呼ばれて主流になっているのは、合成樹脂を主原料とするポリマータイプの方である。ワックスタイプではない。","l":"法令外","c":""},{"id":"2024-150","s":5,"q":"弾性床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["リノリウム系床材は、剥離剤で変色やひび割れなどが起きることがある。","床維持剤の皮膜に黒ずみが出たら、剥離作業をして塗り直す。","塩化ビニルシートは、含まれる可塑剤の影響で床維持剤が密着しにくい。","塩化ビニル系床材には、床維持剤を塗らなくてよい製品も売られている。","塩化ビニル系床材は、モルタルで下地に張り付けている。"],"a":4,"e":"この記述が誤り。塩化ビニル系床材は、モルタルではなく接着剤で下地に張り付けるのが一般的である。","l":"法令外","c":""},{"id":"2024-151","s":5,"q":"繊維床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["ポリプロピレン素材は、復元力は弱いが、親水性の汚れがしみになりにくい。","ウール素材は、耐久性は高いが、親水性の汚れがしみになりやすい。","しみ取り作業は、定期清掃で行う。","繊維床材は、パイルのすき間に土砂やほこりがたまりやすい。","パイルの表面の粗いごみを取るには、カーペットスイーパを使う。"],"a":2,"e":"しみは時間がたつと取れにくくなるので、見つけしだい日常清掃で取るのが基本である。","l":"法令外","c":""},{"id":"2024-152","s":5,"q":"硬性床材の特徴について述べた次の文のうち、最も不適当なものはどれか。","o":["大理石は、アルカリに弱い。","テラゾは、酸に弱い。","セラミックタイルは、すり減りやすい。","花崗岩は、熱に弱い。","目地のモルタルは、酸に弱い。"],"a":2,"e":"セラミックタイルは硬く、耐摩耗性にすぐれる床材である。","l":"法令外","c":""},{"id":"2024-153","s":5,"q":"木質床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["無垢の単層フローリングと複合フローリングでは、表面の仕上げ方が違う。","アルカリ洗剤は木質床材を変色させやすいので、十分注意する。","体育館の木質床材は、ポリウレタン樹脂などでシール加工されている。","シール加工された木質床材は、弾性床材と同じように多量の水で洗う。","一般に、針葉樹の床材は広葉樹の床材より木質が軟らかい。"],"a":3,"e":"木は水を吸うと膨らんだり反ったりするので、シール加工されていても多量の水を使う洗浄は避ける。","l":"法令外","c":""},{"id":"2024-154","s":5,"q":"床以外の清掃作業について述べた次の文のうち、最も不適当なものはどれか。","o":["天井・壁など高い所のおもな汚れは細かい粉じんや炭素粒子などで、床の次に重要な清掃対象である。","玄関ホールは多くの人がいろいろな角度から見る場所なので、視線の向きや高さを変えて汚れを確かめる。","トイレは、清掃作業で全面使用禁止にならないよう工程を工夫する。","ドアやエレベーターの押しボタンなどは、冬は夏より手あかが付きやすい。","人の手による汚れは、化学繊維を使った製品で取りやすい。"],"a":3,"e":"手あかは汗や皮脂による汚れなので、汗をかきやすい夏の方が付きやすい。","l":"法令外","c":""},{"id":"2024-155","s":5,"q":"外装の清掃について述べた次の文のうち、最も不適当なものはどれか。","o":["窓ガラスは平らで緻密なため汚れで変質しにくいので、1年に1回程度洗えばよい。","窓ガラスのスクイジー法は、ウォッシャで水や専用洗剤を塗り、端から窓用スクイジーでかき取る方法である。","ロープ高所作業を行うときは、労働安全衛生規則により特別教育の実施などが義務付けられている。","田園地帯など汚れの少ない地域の金属材は、1年に1回程度洗う。","石材やコンクリートは汚れが目立ちにくいが、立地に応じて3〜5年に1回程度は洗う。"],"a":0,"e":"窓ガラスは汚れが目立つため、1〜2か月に1回程度洗う(2025年度問155でも正しい記述として出題)。ロープ高所作業の特別教育は労働安全衛生規則第36条第40号で義務。","l":"労働安全衛生規則 第36条第40号","c":""},{"id":"2024-156","s":5,"q":"循環型社会をつくることについて述べた次の文のうち、最も不適当なものはどれか。","o":["生産の段階で、積極的にマテリアルリサイクルを行う。","生産の段階で、積極的にリユースを行う。","消費・使用の段階で、積極的にリデュースを行う。","焼却処理の段階で、積極的にサーマルリサイクルを行う。","最終処分の段階で、積極的に天然資源を投入する。"],"a":4,"e":"循環型社会は、天然資源の消費をできるだけ抑えることを目指す社会なので、天然資源を積極的に投入するのは逆である。","l":"法令外","c":""},{"id":"2024-157","s":5,"q":"次の産業廃棄物のうち、安定型最終処分場に埋め立てられないものはどれか。","o":["廃プラスチック類","がれき類","木くず","ゴムくず","金属くず"],"a":2,"e":"安定型産業廃棄物は、廃プラスチック類・ゴムくず・金属くず・ガラスくず等・がれき類に限られる(廃棄物処理法施行令第6条第1項第3号イ)。木くずは腐るので含まれない。","l":"廃棄物処理法施行令 第6条第1項第3号イ","c":""},{"id":"2024-158","s":5,"q":"廃棄物処理法での一般廃棄物の定義として、正しいものはどれか。","o":["家庭からだけ出る廃棄物","放射性廃棄物以外の廃棄物","固形状または液状の廃棄物","産業廃棄物以外の廃棄物","事業活動にともなって出る廃棄物"],"a":3,"e":"廃棄物処理法第2条第2項で、一般廃棄物は「産業廃棄物以外の廃棄物」と定義されている。","l":"廃棄物処理法 第2条第2項","c":""},{"id":"2024-159","s":5,"q":"廃棄物処理法でいう「専ら再生利用の目的となる廃棄物」にあたらないものはどれか。","o":["ペットボトル","古紙","くず鉄","あきびん類","古繊維"],"a":0,"e":"専ら再生利用の目的となる廃棄物(専ら物)は、古紙・くず鉄(古銅などを含む)・あきびん類・古繊維の4品目で、ペットボトルは含まれない。","l":"廃棄物処理法 第7条第1項・第14条第1項(ただし書)","c":""},{"id":"2024-160","s":5,"q":"建築物内の事業活動で出る廃棄物の処理について述べた次の文のうち、最も不適当なものはどれか。","o":["生ごみのうち再生利用しないものを、一般廃棄物の許可業者に委託して処理する。","プラスチック類のうち再生利用しないものを、一般廃棄物の許可業者に委託して処理する。","古紙を再生利用するため、資源回収業者に委託して処理する。","グリース阻集器で集めた油分を、産業廃棄物の許可業者に委託して処理する。","し尿を含まない雑排水槽のビルピット汚泥を、産業廃棄物の許可業者に委託して処理する。"],"a":1,"e":"事業活動で出たプラスチック類は産業廃棄物(廃プラスチック類)なので、産業廃棄物の許可業者に委託しなければならない。","l":"廃棄物処理法 第2条第4項・第12条","c":""},{"id":"2024-161","s":5,"q":"次の条件の事務所建築物について、廃棄物発生量の計算として最も不適当なものはどれか。\n・事務所部分の床面積の合計:10,000m²\n・廃棄物発生量原単位:0.04kg/(m²・日)または0.1L/(m²・日)\n・1か月の稼働日:20日\n・廃棄物の再利用率(リサイクル率):60%\n・廃棄物のうち生ごみの割合:20%","o":["再利用を考えないときの1日の廃棄物発生量は400kgである。","再利用を考えないときの1か月の廃棄物発生量は8,000kgである。","この建築物のごみの単位容積質量値は0.4kg/Lである。","再利用を考えたときの1日の廃棄物発生量は240kgである。","再利用を考えないときの1日の生ごみ発生量は80kgである。"],"a":3,"e":"1日の発生量は10,000×0.04＝400kg。再利用率60%を除くと400×(1－0.6)＝160kgで、240kgではない。ほかは400×20日＝8,000kg、0.04÷0.1＝0.4kg/L、400×0.2＝80kgで正しい。","l":"計算","c":""},{"id":"2024-162","s":5,"q":"建築物内廃棄物について述べた次の文のうち、最も不適当なものはどれか。","o":["事後分別とは、ごみが出た時点より後で分別することである。","事前分別の基本は、収集・運搬用具を廃棄物の種類ごとに用意することである。","建築物内で収集するとき、廃棄物かどうかわからない書類などは、確認するまで処理しない。","ビルメンテナンス事業者は、建築物内廃棄物の管理責任者を選任する。","事後分別の注意点は、廃棄物と資源化物を大きく分け、さらに細かく分別することである。"],"a":3,"e":"この記述が誤り。廃棄物の管理責任者は、ビルメンテナンス事業者が選ぶものではない。","l":"法令外","c":""},{"id":"2024-163","s":5,"q":"建築物内廃棄物の中間処理について述べた次の文のうち、最も不適当なものはどれか。","o":["中間処理の目的の一つは、廃棄物を減らすことである。","建築物に入っている中間処理設備は、比較的小さいものが多い。","溶融固化装置は、厨芥(生ごみ)の中間処理に使う。","段ボールの中間処理の方法として、梱包がある。","プラスチック類の中間処理の方法として、圧縮がある。"],"a":2,"e":"溶融固化装置は、発泡スチロールを熱で溶かして固める装置である(2025年度問162でも正しい記述として出題)。生ごみの処理には使わない。","l":"法令外","c":""},{"id":"2024-164","s":5,"q":"産業廃棄物管理票(紙マニフェスト)について述べた次の文のうち、最も不適当なものはどれか。","o":["マニフェストのA票は、排出事業者の保存用である。","マニフェストのB1票は、収集運搬業者の保存用である。","中間処理が終わると、処分業者から排出事業者にD票が返送される。","排出事業者は、処理を頼んでから180日たってもE票が戻らないときは、業者に処分の状況を問い合わせる。","排出事業者は、引き渡し時のA票と返送された伝票を照合し、A票・B2票・D票・E票を3年間保存する。"],"a":4,"e":"返送された管理票の写しの保存期間は5年である(廃棄物処理法施行規則第8条の26)。180日は同規則第8条の28のとおり。","l":"廃棄物処理法施行規則 第8条の26・第8条の28","c":""},{"id":"2024-165","s":5,"q":"廃棄物処理法についての次の文の[ア]・[イ]に入る語句の組合せとして、最も適当なものはどれか。\n「昭和45年の制定時に、それまでの法律で衛生面から定めていた汚物に加えて[ア]という考え方を取り入れて廃棄物を定義し、産業廃棄物と一般廃棄物に分けるとともに、公衆衛生の向上に加えて[イ]を法の目的に加えた。」","o":["ア 不要物/イ 地球環境の保全","ア 不要物/イ 都市の健全な発達","ア 有害廃棄物/イ 生活環境の保全","ア 不要物/イ 生活環境の保全","ア 有害廃棄物/イ 都市の健全な発達"],"a":3,"e":"廃棄物処理法は廃棄物を「汚物又は不要物」と定義し(第2条第1項)、目的を「生活環境の保全及び公衆衛生の向上」としている(第1条)。","l":"廃棄物処理法 第1条・第2条第1項","c":""},{"id":"2024-166","s":6,"q":"蚊の生態に関する記述として、最も適当なものはどれか。","o":["ハマダラカの卵は、水面に卵の塊として産み付けられ、形は舟のようである。","日本にいるヒトスジシマカは、成虫の姿で冬を越す。","コガタアカイエカは、主に排水溝や雨水ますで発生する。","チカイエカは、最初の産卵を吸血しないで行うことができる。","アカイエカとチカイエカは、雌成虫の外見で見分けられる。"],"a":3,"e":"チカイエカは、羽化後の最初の産卵を吸血しないで行うことができる(2025年問166でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-167","s":6,"q":"湯沸室で次のゴキブリがとれた。体長は約12mmの成虫で、前胸背板にハの字形に見える太く縦長の黒い斑紋が2本あり、それ以外は全体が黄褐色だった。このゴキブリの生態などに関する記述として、最も適当なものはどれか。","o":["主に屋外にすむが、建物の中にも入ってくる。","毒餌(食毒剤)を食べようとしない、喫食抵抗性をもつ集団の存在が報告されている。","日本の気候では、卵から成虫になるまでに約1年かかる。","幼虫と成虫では、餌や活動する場所がちがう。","雌成虫は、卵鞘を唾液などでくぼみやすき間にくっつける。"],"a":1,"e":"特徴からチャバネゴキブリと考えられる。チャバネゴキブリでは毒餌への喫食抵抗性を示す個体が知られている(2017年問169でも正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-168","s":6,"q":"ゴキブリの防除に関する記述として、最も不適当なものはどれか。","o":["防除では食べ物の管理と環境の整備が大切だが、それだけで発生を完全に防ぐのは難しい。","ULV処理は、気門から殺虫剤を取り込ませることをねらった処理方法である。","毒餌(食毒剤)を置くとき、毒餌とその周りにピレスロイド剤を噴霧すると駆除効果が高まる。","防除作業の前のゴキブリ指数が12.0、作業後が1.2だった場合、防除率は90.0%である。","フェノトリンを有効成分とするエアゾール剤を潜み場所に吹き込むと、ゴキブリが飛び出すフラッシング効果がみられる。"],"a":2,"e":"毒餌とその周りに殺虫剤を噴霧すると効果が高まる、というのは誤り(2016年問169でも同様の記述が誤りとして出題)。なお(4)は(12.0−1.2)÷12.0=90%で正しい。","l":"法令外","c":""},{"id":"2024-169","s":6,"q":"ダニに関する記述として、最も不適当なものはどれか。","o":["ヒゼンダニは、ヒトの皮膚の下に寄生するダニとして知られている。","ヤケヒョウヒダニは、アレルゲンになることが知られている。","カベアナタカラダニは、ヒトを刺さない。","ミナミツメダニは、ほかの小さな生き物を捕まえて食べるダニである。","マダニの顎体部には、脚が付いている。"],"a":4,"e":"マダニの顎体部に脚が付いているとした記述が誤り。","l":"法令外","c":""},{"id":"2024-170","s":6,"q":"ダニの防除に関する記述として、最も不適当なものはどれか。","o":["イエダニやワクモの防除では、宿主になる動物の駆除や侵入防止の対策が必要である。","野外で活動するときの忌避剤の使用は、マダニ類に効果がある。","ケナガコナダニの対策では、乾燥した状態を保つことが大切である。","ヒョウヒダニ類の対策では、殺虫剤が効きにくいことなどから、殺虫剤処理は第一の選択肢にならない。","フタトゲチマダニの対策では、ほかのダニ類やチャタテムシ類の防除が重要である。"],"a":4,"e":"ヒョウヒダニ類やチャタテムシ類の防除が重要なのは、それらを捕食するツメダニ類の対策である(2021年問170で正しい記述として出題)。フタトゲチマダニの対策ではない。","l":"法令外","c":""},{"id":"2024-171","s":6,"q":"害虫とその防除に関する記述として、最も不適当なものはどれか。","o":["ニクバエ類の雌成虫は、ふんや腐った動物質などに卵を産み付ける。","チョウバエ類は、建物の中では浄化槽や排水溝などで発生する。","ユスリカ類が、建物内の排水溝やプールから発生することがある。","チャタテムシ類の防除では、カビの発生をおさえることも必要である。","ネッタイトコジラミが国内の宿泊施設で見つかった例がある。"],"a":0,"e":"ニクバエ類は卵ではなく幼虫を産む卵胎生のハエである(2016年問171・2017年問173で正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-172","s":6,"q":"薬剤と、その特徴・効き方・製剤の組合せとして、最も不適当なものはどれか。","o":["メトフルトリン ― 常温で揮散させる製剤","ジクロルボス ― 食毒剤","ブロフラニリド ― 有機リン剤などに抵抗性を示す集団への対策","フェノトリン ― ULV処理専用の水性乳剤","エトフェンプロックス ― ピレスロイド様化合物"],"a":1,"e":"ジクロルボスは樹脂蒸散剤として使われる(2023年問173で「ジクロルボス ― 樹脂蒸散剤」が正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2024-173","s":6,"q":"殺虫製剤とその有効成分(原体)に関する記述として、最も不適当なものはどれか。","o":["殺虫剤抵抗性が発達しないように、作用のしくみが同じ数種類の殺虫成分を選び、それらを有効成分とする製剤を順番に使う(ローテーション処理)。","ピレスロイドとは、除虫菊の花に含まれる殺虫成分と、それに似た化合物をまとめた呼び名である。","現在、日本では、有機塩素系の殺虫成分を有効成分とする乳剤が使われている。","ペット用のノミやマダニの駆除をうたう殺虫製剤は、農林水産省が受け持っている。","トコジラミ用の殺虫製剤や忌避製剤は、医薬品医療機器等法にもとづく医薬品・医薬部外品としての承認が必要である。"],"a":0,"e":"ローテーション処理は、作用のしくみ(作用機構)が異なる殺虫剤で行う(2021年問180で正しい記述として出題)。","l":"法令外","c":""},{"id":"2024-174","s":6,"q":"ネズミの生態や防除に関する記述として、最も適当なものはどれか。","o":["床がぬれていたり汚れていたりすると、ネズミは粘着トラップにかかりにくい。","殺鼠剤は、皮膚からネズミの体内に取り込ませることを目的にしている。","室内でネズミを押しつぶして捕るトラップ(圧殺式)を置くときは、毒餌皿に入れる。","餌を絶つための食べ物・食べ残しの管理だけで、ネズミの防除は達成できる。","ネズミの体の脂と汚れで壁や配管などに残った黒い跡を、ローチスポットという。"],"a":0,"e":"床がぬれていたり汚れていたりすると、粘着トラップの粘着力が落ち、ネズミがかかりにくくなる。","l":"法令外","c":""},{"id":"2024-175","s":6,"q":"殺鼠剤とそれに関連する記述として、最も不適当なものはどれか。","o":["ジフェチアロールは、第2世代の抗凝血性殺鼠剤である。","シリロシドは、ユリ科植物の球根からとれる成分である。","リン化亜鉛は、抗凝血性殺鼠剤である。","ブロマジオロン製剤は、動物用医薬部外品として売られている。","ワルファリンは、第1世代のクマリン系殺鼠剤である。"],"a":2,"e":"リン化亜鉛は抗凝血性殺鼠剤ではなく、1回食べるだけで死に至る急性の殺鼠剤である(2023年問175で「リン化亜鉛 ― 1回の経口摂取で致死」が正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2024-176","s":6,"q":"衛生動物と病気に関する記述として、最も不適当なものはどれか。","o":["日本脳炎を主に媒介する蚊は、コガタアカイエカである。","重症熱性血小板減少症候群(SFTS)の流行地は、主に西日本である。","持続可能な開発目標(SDGs)には、マラリアなど媒介動物がかかわる感染症の根絶への取組も入っている。","ライム病は、北海道を除く国内各地でばらばらに発生している。","つつが虫病は、北海道を除く国内で広い範囲に発生している。"],"a":3,"e":"ライム病について「北海道を除く国内各地で散発」とした記述が誤り。","l":"法令外","c":""},{"id":"2024-177","s":6,"q":"衛生動物と病気の対策に関する記述として、最も不適当なものはどれか。","o":["国内で殺虫剤抵抗性が確認されている衛生害虫は、イエバエ・蚊・ゴキブリなど多くの種類にわたる。","トコジラミは、疥癬の流行に関係している。","国内では、何種類かの蚊がウエストナイルウイルスを媒介する可能性がある。","アシナガバチに刺されると、アナフィラキシーショックの原因になることがある。","マダニ類は、日本紅斑熱を媒介する。"],"a":1,"e":"疥癬の原因はヒトの皮膚の下に寄生するヒゼンダニであり(2024年問169でも正しい記述として出題)、トコジラミではない。","l":"法令外","c":""},{"id":"2024-178","s":6,"q":"ねずみ・昆虫等の防除作業の安全管理に関する記述として、最も不適当なものはどれか。","o":["建築物衛生法の特定建築物の中で行うねずみ・昆虫等の防除では、医薬品または医薬部外品を使う。","薬剤を空間に噴霧したり、狭い場所で薬剤を散布したりするときは、N95マスクを着ける。","マンホールの中など、酸素欠乏や硫化水素発生のおそれがある場所での作業は、酸素欠乏症等防止規則に従って行う必要がある。","ネズミにかじられた電線は、ネズミの尿やふんがかかると燃え出すことがある。","屋内でULV処理をすると、煙感知器が誤って作動することがある。"],"a":1,"e":"N95マスクを着用するとした点が誤り(2023年問178でも、気化したガスを防ぐためにN95マスクを着けるという記述が誤りとされている)。なお(1)は建築物衛生法施行規則第4条の5第2項第2号の定めどおり。","l":"建築物衛生法施行規則 第4条の5第2項第2号(選択肢1)","c":""},{"id":"2024-179","s":6,"q":"建築物衛生法の特定建築物で行うねずみ・昆虫等の防除に関する記述として、最も適当なものはどれか。","o":["ニューサンスコントロールとは、感染症の媒介を断つための手段として行うねずみ等の防除である。","IPMの「許容水準」とは、そのままにすると今後問題になる可能性がある状況をいう。","IPMにもとづくねずみ等の防除では、定期的・統一的に薬剤処理を行う。","調査は、被害状況の聞き取り調査を中心に行えばよい。","ねずみ等の対策を行ったら、有害生物の密度調査などで、その効果を客観的に評価する。"],"a":4,"e":"対策の後は、生息密度の調査などによって効果を客観的に評価する。","l":"法令外","c":""},{"id":"2024-180","s":6,"q":"ねずみ・昆虫とその防除に関する記述として、最も適当なものはどれか。","o":["ノミバエ類とショウジョウバエ類の発生源は同じである。","昆虫成長制御剤(IGR)の羽化阻害の効力は、LC50の値で評価される。","ねずみと昆虫では、薬剤抵抗性が発達するしくみがちがう。","ヒアリ類は、要緊急対処特定外来生物に指定されている。","建築物環境衛生維持管理要領には、IPMの考え方にもとづく動物の種類ごとの防除法や手順が具体的に示されている。"],"a":3,"e":"ヒアリ類(ソレノプシス属の種群)は、外来生物法の要緊急対処特定外来生物に指定されている(外来生物法第2条第3項、同法施行令第4条・別表第四)。","l":"特定外来生物による生態系等に係る被害の防止に関する法律 第2条第3項、同法施行令 第4条・別表第四","c":""},{"id":"2025-1","s":0,"q":"医学の歴史に名を残した人物と、その功績の組合せとして、正しいものはどれか。","o":["ヒポクラテス ― 生命は自然に発生するという説に反対した","フローレンス・ナイチンゲール ― 西洋医学の体系の土台をつくった","ルイ・パスツール ― ペニシリンを発見した","ロベルト・コッホ ― コレラ菌を発見した","アレクサンダー・フレミング ― 破傷風菌を純粋に培養することに成功した"],"a":3,"e":"コッホはコレラ菌や結核菌を発見した。自然発生説を否定したのはパスツール、ペニシリンを発見したのはフレミング、西洋医学の基礎を築いたのはヒポクラテス、破傷風菌の純粋培養は北里柴三郎の功績。","l":"法令外","c":""},{"id":"2025-2","s":0,"q":"現在の行政組織(法律を受け持つ省庁)について、最も不適当なものはどれか。","o":["消防法を受け持つのは総務省である。","廃棄物の処理及び清掃に関する法律(廃棄物処理法)を受け持つのは厚生労働省である。","下水道法を受け持つのは国土交通省と環境省である。","建築基準法を受け持つのは国土交通省である。","旅館業法を受け持つのは厚生労働省である。"],"a":1,"e":"廃棄物処理法を所管しているのは環境省であり、厚生労働省ではない。","l":"法令外(各省設置法の所掌事務)","c":""},{"id":"2025-3","s":0,"q":"建築物における衛生的環境の確保に関する法律(建築物衛生法)について、誤っているものはどれか。","o":["建築物衛生法は、建築物を維持管理する面での決まりを定めている。","建築物衛生法にもとづく事業の登録の事務は、都道府県知事が行う。","特定建築物でなくても、多くの人が使う建築物は、建築物環境衛生管理基準に従って維持管理するよう努めなければならない。","建築物環境衛生管理技術者に、建築物環境衛生管理基準を守る義務を負わせている。","特定建築物の「所有者等」には、所有者のほか、その建物全部の管理について権原をもつ者も含まれる。"],"a":3,"e":"建築物環境衛生管理基準に従って維持管理する義務を負うのは、特定建築物の維持管理について権原をもつ者(特定建築物維持管理権原者)であり、管理技術者ではない。管理技術者は、必要なときに権原者へ意見を述べる立場である。","l":"建築物衛生法 第4条第1項、第6条第2項","c":""},{"id":"2025-4","s":0,"q":"次の複合用途の建築物について、正しいものはどれか。なお、A社・B社・C法人はお互いに関係がない。\n【建物の内訳】A社の事務所 2,000m²、B社の店舗 600m²、A社事務所とB社店舗の共用部分 300m²、B社店舗に付属する倉庫 200m²、C法人の歯科クリニック 400m²","o":["特定用途に使われる部分の延べ面積は3,500m²で、特定建築物に当たる。","特定用途に使われる部分の延べ面積は3,200m²で、特定建築物に当たる。","特定用途に使われる部分の延べ面積は3,100m²で、特定建築物に当たる。","特定用途に使われる部分の延べ面積は2,900m²で、特定建築物に当たらない。","特定用途に使われる部分の延べ面積は2,600m²で、特定建築物に当たらない。"],"a":2,"e":"事務所2,000+店舗600+共用部分300+店舗付属の倉庫200=3,100m²。歯科クリニック(診療所)は特定用途に含まれないので数えない。3,000m²以上なので特定建築物に当たる。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2025-5","s":0,"q":"特定建築物の用途に当たらないものはどれか。","o":["パチンコ店","水族館","結婚式場","幼稚園","寺院"],"a":4,"e":"寺院・教会などの宗教施設は、特定建築物の用途(興行場、百貨店、集会場、図書館、博物館、遊技場、店舗、事務所、学校、旅館など)に含まれない。","l":"建築物衛生法施行令 第1条","c":""},{"id":"2025-6","s":0,"q":"特定建築物の届出について、最も不適当なものはどれか。","o":["今使っている建築物が用途の変更で新たに特定建築物に当たることになった場合は、その用途で使い始めてから1か月以内に届け出なければならない。","届出をしなかったり、うその届出をしたりすると、30万円以下の罰金が科されることがある。","建築物を取り壊す場合は、前もって、特定建築物に当たらなくなることを届け出なければならない。","届け出る事項は、厚生労働省令で決められている。","届出をする義務があるのは、所有者、またはその特定建築物全部の管理について権原をもつ者である。"],"a":2,"e":"特定建築物に当たらなくなったときの届出は、「前もって」ではなく、当たらなくなった日から1か月以内に行う。","l":"建築物衛生法 第5条第3項、第16条","c":""},{"id":"2025-7","s":0,"q":"建築物環境衛生管理基準にもとづく飲料水の衛生上の措置について、最も不適当なものはどれか。","o":["水道水を直結給水で特定建築物に飲料水として供給する場合でも、その建物の維持管理権原者が定期の水質検査を行わなければならない。","水道水を建物内の貯水槽にためて供給する場合、貯水槽から先の飲料水を管理する責任者は、その建物の維持管理権原者である。","供給する水が健康を害するおそれがあると分かったときは、すぐに給水を止め、その水を使うと危険であることを関係者に知らせる。","飲むためだけでなく、炊事用など生活に使う水も、水道法の水質基準に合った水を供給しなければならない。","水道水以外の井戸水などを飲み水に使う場合は、給水栓で遊離残留塩素を保たなければならない。"],"a":0,"e":"管理基準の対象は、水道法の給水装置以外の給水設備(貯水槽など)を通して供給する水である。直結給水は水道事業者の給水装置から直接供給されるため、建物側の定期水質検査の義務はない。","l":"建築物衛生法施行令 第2条第2号、施行規則 第4条","c":""},{"id":"2025-8","s":0,"q":"建築物環境衛生管理基準にもとづく清掃とねずみ等の防除について、最も不適当なものはどれか。","o":["掃除は、日常の掃除のほか、大掃除を1年以内ごとに1回、定期的にまとめて行う。","ねずみ等の調査は、6か月以内ごとに1回、定期的にまとめて行う。","殺鼠剤や殺虫剤は、医薬品医療機器等法で承認を受けた医薬品または医薬部外品を使わなければならない。","掃除や廃棄物の処理を行うときは、厚生労働省の告示にもとづき、掃除用機器や廃棄物処理設備の維持管理に努めなければならない。","管理基準でいう「ねずみその他の厚生労働省令で定める動物」とは、ねずみ、昆虫など、人の健康を損なうおそれのある動物のことである。"],"a":0,"e":"正しくは、大掃除は「6か月以内ごとに1回」、定期に統一的に行う。","l":"建築物衛生法施行規則 第4条の5","c":""},{"id":"2025-9","s":0,"q":"建築物環境衛生管理技術者について、最も適当なものはどれか。","o":["免状の記載事項が変わったときは、厚生労働大臣に免状の再交付を申請しなければならない。","選任された特定建築物に常駐しなければならない。","特定建築物の所有者等と雇用関係がなければならない。","特定建築物維持管理権原者に対し、その建物の維持管理について意見を述べることができる。","環境衛生上必要な事項を記載した帳簿書類を備えておかなければならない。"],"a":3,"e":"管理技術者は、管理基準に従った維持管理のために必要なとき、権原者に意見を述べることができ、権原者はその意見を尊重しなければならない。帳簿書類を備える義務は特定建築物所有者等にある。","l":"建築物衛生法 第6条第2項、第10条","c":""},{"id":"2025-10","s":0,"q":"建築物環境衛生総合管理業の登録に必要な機械器具に当たらないものはどれか。","o":["真空掃除機","床みがき機","建築物空気環境測定業の登録に必要な測定器","残留塩素測定器","高圧洗浄機"],"a":4,"e":"総合管理業に必要なのは、真空掃除機、床みがき機、空気環境の測定器、残留塩素測定器など。高圧洗浄機は総合管理業の登録に必要な機械器具ではない。","l":"建築物衛生法施行規則(建築物環境衛生総合管理業の登録基準)","c":""},{"id":"2025-11","s":0,"q":"事業の登録に必要な人的要件について、最も不適当なものはどれか。","o":["特定建築物の建築物環境衛生管理技術者に選任されている人は、登録事業の監督者等を兼ねることができない。","同じ人が2つ以上の営業所の監督者等になることはできない。","同じ人が同じ営業所で2つ以上の登録事業の監督者等になることはできない。","登録事業で働くパート従業員は、従事者研修の対象ではない。","事業者は、研修の対象者全員が1年に1回以上研修を受けられる体制をとらなければならない。"],"a":3,"e":"従事者研修は、その作業に従事する者「すべて」が受講できるものでなければならず、パート従業員も対象になる。","l":"建築物衛生法施行規則 第25条ほか(各登録基準の研修の要件)","c":""},{"id":"2025-12","s":0,"q":"国や地方公共団体が使う特定建築物について、最も適当なものはどれか。","o":["国が使う特定建築物の使用開始の届出は、厚生労働大臣に行う。","建築物環境衛生管理技術者を選任するよう努めなければならない(努力義務にとどまる)。","国が使う特定建築物の立入検査は、都道府県知事等が行う。","建築物環境衛生管理基準に従って維持管理するよう努めなければならない(努力義務にとどまる)。","都道府県知事等は、改善の措置をとるよう勧告することができる。"],"a":4,"e":"国・地方公共団体の特定建築物には立入検査や改善命令の規定は適用されないが、都道府県知事等は必要な措置をとるよう勧告できる。届出・管理技術者の選任・管理基準の遵守は、一般の特定建築物と同じく義務である。","l":"建築物衛生法 第13条","c":""},{"id":"2025-13","s":0,"q":"地域保健法にもとづく保健所の事業として、最も適当なものはどれか。","o":["生活保護に関すること","人口動態統計に関すること","介護認定に関すること","身体障害者への援護に関すること","児童虐待の防止に関すること"],"a":1,"e":"人口動態統計その他地域保健に関する統計は、地域保健法で保健所の事業として定められている。","l":"地域保健法 第6条","c":""},{"id":"2025-14","s":0,"q":"学校保健安全法で定める学校薬剤師の職務として、最も不適当なものはどれか。","o":["学校安全計画の立案に関わること","水泳プールの水質検査","健康診断","学校での毒物・劇物の管理についての指導","教室の空気の検査"],"a":2,"e":"健康診断は学校医(歯科は学校歯科医)の職務であり、学校薬剤師の職務ではない。","l":"学校保健安全法施行規則 第22条〜第24条","c":""},{"id":"2025-15","s":0,"q":"ある特定建築物の飲料水の水質検査結果のうち、水道法の水質基準を満たしていないものはどれか。","o":["一般細菌(1mLの検水でできる集落数) 50個","色度 3度","pH値 6.3","塩化物イオン 100mg/L","有機物(全有機炭素(TOC)の量) 5mg/L"],"a":4,"e":"有機物(TOC)の基準は3mg/L以下なので、5mg/Lは基準を超えている。一般細菌は100以下、塩化物イオンは200mg/L以下など、ほかは基準内。","l":"水質基準に関する省令","c":""},{"id":"2025-16","s":0,"q":"次のア〜オの生活衛生関係営業のうち、開設や営業に「許可」がいらないものの組合せとして、正しいものはどれか。\nア 旅館　イ 美容所　ウ 公衆浴場　エ クリーニング所　オ 映画館","o":["アとイ","アとウ","イとエ","ウとオ","エとオ"],"a":2,"e":"美容所とクリーニング所は都道府県知事等への「届出」で開設できる。旅館、公衆浴場、映画館(興行場)は営業に「許可」が必要。","l":"美容師法 第11条、クリーニング業法 第5条、旅館業法 第3条、公衆浴場法 第2条、興行場法 第2条","c":""},{"id":"2025-17","s":0,"q":"悪臭防止法の特定悪臭物質に当たらないものはどれか。","o":["アンモニア","テトラクロロエチレン","硫化水素","トルエン","プロピオン酸"],"a":1,"e":"テトラクロロエチレンは特定悪臭物質(22物質)に含まれない。アンモニア、硫化水素、トルエン、プロピオン酸は含まれる。","l":"悪臭防止法施行令 第1条","c":""},{"id":"2025-18","s":0,"q":"水質汚濁防止法の目的を示した次の文の(ア)〜(ウ)に入る語句の組合せとして、正しいものはどれか。\n「この法律は、工場・事業場から公共用水域へ出る水の排出と地下へしみこむ水の浸透を規制するとともに、( ア )の実施を進めることなどによって、公共用水域と地下水の水質汚濁の防止を図り、国民の健康を保護するとともに( イ )し、あわせて工場・事業場から出る汚水・廃液で人の健康被害が生じた場合の( ウ )について定めて、被害者の保護を図ることを目的とする。」","o":["ア 生活排水対策　イ 生活環境を保全　ウ 事業者の損害賠償の責任","ア 下水対策　イ 生活環境を保全　ウ 緊急時の措置","ア 生活排水対策　イ 生活環境を保全　ウ 緊急時の措置","ア 下水対策　イ 衛生水準を維持　ウ 緊急時の措置","ア 生活排水対策　イ 衛生水準を維持　ウ 事業者の損害賠償の責任"],"a":0,"e":"第1条の目的は、生活排水対策の推進、生活環境の保全、そして健康被害が生じたときの事業者の損害賠償の責任を定めて被害者を保護すること。","l":"水質汚濁防止法 第1条","c":""},{"id":"2025-19","s":0,"q":"労働安全衛生法の定めについて、最も不適当なものはどれか。","o":["厚生労働大臣は、労働災害防止計画をつくらなければならない。","事業者は、有害な業務を行う屋内作業場で必要な作業環境測定を行い、その結果を記録しておかなければならない。","事業者は、規模に応じて、事業場ごとに衛生委員会を設けなければならない。","事業者は、規模に応じて労働者の健康診断を行ったとき、その結果を保健所長に提出しなければならない。","安全委員会の委員には、その事業場の労働者で安全に関する経験がある人のうち、事業者が指名した人が含まれなければならない。"],"a":3,"e":"健康診断結果の報告先は保健所長ではなく、所轄の労働基準監督署長である(常時50人以上の事業場の定期健康診断など)。","l":"労働安全衛生法 第100条、労働安全衛生規則 第52条","c":""},{"id":"2025-20","s":0,"q":"次の国際的な取り決めのうち、主に廃棄物対策に関するものはどれか。","o":["京都議定書","ラムサール条約","バーゼル条約","モントリオール議定書","ワシントン条約"],"a":2,"e":"バーゼル条約は、有害廃棄物の国境を越える移動と処分を規制する条約。京都議定書は温暖化、ラムサール条約は湿地、モントリオール議定書はオゾン層、ワシントン条約は野生動植物の取引に関するもの。","l":"法令外","c":""},{"id":"2025-21","s":1,"q":"健康に影響する環境要因のうち、「化学的要因」として最も不適当なものはどれか。","o":["酸素","硫黄酸化物","オゾン","し尿","超音波"],"a":4,"e":"超音波は音(振動)なので、化学的要因ではなく物理的要因に分類される。","l":"法令外","c":""},{"id":"2025-22","s":1,"q":"生体の恒常性(ホメオスタシス)などについて、最も不適当なものはどれか。","o":["外の環境が変わっても、体の内部の環境を一定に保つ仕組みを恒常性という。","恒常性は、主に神経系・内分泌系・免疫系のはたらきで保たれている。","体に刺激が加わると体内に変化が起こり、適応しようとする反応が非特異的に起こる。","外からの刺激は受容器で受け取られ、調節中枢に伝わり、効果器に興奮が伝わって反応が起こる。","熱を逃がすはたらきは、発汗、呼吸、皮下組織による熱の遮断、基礎代謝を高めることで行われる。"],"a":4,"e":"基礎代謝を高めることは熱をつくる(産熱)側のはたらきであり、熱を逃がす(放熱)はたらきではない。","l":"法令外","c":""},{"id":"2025-23","s":1,"q":"一般環境と労働環境について、最も不適当なものはどれか。","o":["一般環境の大気、水質、騒音、土壌などについて環境基準が定められている。","学校の環境衛生の基準は、学校保健安全法で定められている。","許容濃度でいう曝露濃度とは、呼吸用保護具をつけた状態で、労働者が作業中に吸い込むと考えられる空気中の物質の濃度である。","最大許容濃度とは、作業中のどの時間でも曝露濃度がこの値以下なら、ほとんどすべての労働者に健康上の悪い影響が見られないと判断される濃度である。","労働環境では、曝露時間が短い場合や労働の強さが弱い場合でも、許容濃度を超える曝露は避けるべきである。"],"a":2,"e":"許容濃度でいう曝露濃度は、呼吸用保護具を「つけていない」状態で吸い込む空気中の濃度である。","l":"法令外(日本産業衛生学会 許容濃度の勧告)","c":""},{"id":"2025-24","s":1,"q":"体温調節について、最も不適当なものはどれか。","o":["寒い環境では、暖かい環境と比べて、体の内部と体の表面との温度差が小さくなる。","平均皮膚温を求めるHardy-DuBoisの7点法で、皮膚温の重みが一番大きいのは腹である。","皮膚の血管の収縮・拡張、発汗、ふるえは、自律性体温調節である。","低温の環境では、体の熱をつくる量が増える。","核心温は、体の表面の温度に比べて、外気温の影響を受けにくい。"],"a":0,"e":"寒い環境では皮膚の血管が縮んで体表面の温度が下がるため、体の内部と表面との温度差は大きくなる。","l":"法令外","c":""},{"id":"2025-25","s":1,"q":"温熱環境の指数について、最も不適当なものはどれか。","o":["黒球温度は、熱放射と対流に関わる温度を測るのに使われる。","湿球黒球温度(WBGT)は、屋内外の暑い作業での暑熱ストレスを評価するのに使われる。","有効温度は、湿度100%・無風の部屋の気温に置きかえて表す、体感にもとづく指数である。","標準新有効温度は、気温・湿度・風速・熱放射・着衣量・代謝量の6つの要素を含んだ指標である。","不快指数は、気温に関係なく使える指標である。"],"a":4,"e":"不快指数は気温と湿度から求める夏の蒸し暑さの指標で、気温が低いときには使えない。","l":"法令外","c":""},{"id":"2025-26","s":1,"q":"体温調節について、最も不適当なものはどれか。","o":["快適と感じる温度は、一般に男性より女性のほうが数度高い。","高齢者は若い人と比べて、寒さによる血圧の変動が小さい。","服の保温性を表す量として、クロ値(clo)がある。","蒸発とは、水分が皮膚から気化するときに、潜熱として皮膚表面の熱をうばう現象である。","女性の核心温は、ホルモンの影響で周期的に変わる。"],"a":1,"e":"高齢者は体温調節の機能が低下しているため、寒さによる血圧の変動は若い人より大きい。","l":"法令外","c":""},{"id":"2025-27","s":1,"q":"アレルギーについて、最も不適当なものはどれか。","o":["学校保健安全法で、ダニまたはダニアレルゲンについての基準が定められている。","建築物衛生の面から、換気や清掃などの対策が大切である。","アレルゲンを特定することは、症状の予防や治療のうえで大切である。","アレルゲンとは、免疫グロブリンと呼ばれるたんぱく質のことである。","国民の約5割が、何らかのアレルギー疾患にかかっているとされる。"],"a":3,"e":"免疫グロブリン(IgEなど)は体がつくる抗体であり、アレルギーを引き起こす原因物質であるアレルゲン(抗原)とは別のものである。","l":"法令外","c":""},{"id":"2025-28","s":1,"q":"ヒトの発がんについて、最も不適当なものはどれか。","o":["ヒトのがんの3分の2以上は、食事や喫煙など生活環境に関わる要因が原因とされる。","日光を浴びることが、がんの原因になることがある。","細胞の増殖をうながす物質は、イニシエータである。","がんを促す因子を減らし、抑える因子を増やせば、がんのリスクを下げられる。","建物の空気中にある発がん物質への曝露を減らすことは、がんの一次予防になる。"],"a":2,"e":"細胞の増殖を促してがん化を進める物質はプロモータである。イニシエータは、最初に遺伝子(DNA)に傷をつける物質。","l":"法令外","c":""},{"id":"2025-29","s":1,"q":"シックビル症候群について、最も不適当なものはどれか。","o":["仕事のストレスは、発症の危険因子である。","症状と原因の因果関係は、必ずしもはっきりしていない。","特有の症状はなく、さまざまな症状が出る。","アトピー体質は、発症の危険因子である。","目やのどの刺激、くしゃみなどの症状は、加湿すると増える。"],"a":4,"e":"目やのどの刺激などの症状は空気の乾燥で起こりやすく、加湿によってむしろ減ると考えられる。","l":"法令外","c":""},{"id":"2025-30","s":1,"q":"労働安全衛生法にもとづく酸素欠乏症等防止規則(酸欠則)では、空気中の酸素濃度が(　)%未満の状態を「酸素欠乏」と定義している。(　)に入る数値として正しいものはどれか。","o":["20","18","16","14","10"],"a":1,"e":"酸欠則では、空気中の酸素濃度が18%未満の状態を酸素欠乏と定めている。","l":"酸素欠乏症等防止規則 第2条","c":""},{"id":"2025-31","s":1,"q":"空気汚染物質と健康障害の組合せとして、最も不適当なものはどれか。","o":["オゾン ― 気道の粘膜への刺激","ラドン ― 肺がん","ハウスダスト ― 喘息","たばこの煙 ― 慢性閉塞性肺疾患(COPD)","二酸化窒素 ― 過敏性肺炎"],"a":4,"e":"過敏性肺炎は、カビなどの有機物の粉じんを繰り返し吸い込むことで起こる病気であり、二酸化窒素による健康障害の組合せとしては不適当。","l":"法令外","c":""},{"id":"2025-32","s":1,"q":"ホルムアルデヒドについて、最も不適当なものはどれか。","o":["常温では気体である。","水に溶けにくい。","燃えやすい(可燃性がある)。","建築基準法で、ホルムアルデヒドを含む建材の使用が制限されている。","粘膜への刺激が強い。"],"a":1,"e":"ホルムアルデヒドは水によく溶ける。その水溶液がホルマリンである。","l":"法令外","c":""},{"id":"2025-33","s":1,"q":"騒音とその影響について、最も不適当なものはどれか。","o":["騒音による健康影響は、年齢や生活習慣などいくつもの要因によって変わる。","夜間の騒音レベルが20dB程度で、実際に生理的な影響が出る。","騒音によって4,000Hz付近の聴力が落ちることを、C5ディップという。","一定時間の騒音レベルは、等価騒音レベル(測定時間内の騒音レベルの平均値)で評価する。","騒音性難聴では、聴力の低下が高い周波数から低い周波数へとだんだん広がる。"],"a":1,"e":"20dBはとても静かなレベルで、この程度の夜間騒音では実質的な生理的影響は生じないとされる。","l":"法令外","c":""},{"id":"2025-34","s":1,"q":"振動について、最も不適当なものはどれか。","o":["都市部の全身振動の発生源には、建設機械、道路交通、工場などがある。","バスやフォークリフトに乗って感じる振動は、局所振動である。","ヒトは、全身に分布する知覚神経の末端の受容器で振動を感じる。","1秒間の振動の回数を周波数といい、単位はHzである。","局所振動による手指などの血行障害のきっかけの一つに、寒さがある。"],"a":1,"e":"乗り物に乗って体全体が揺れる振動は全身振動である。局所振動は、チェーンソーなど手で持つ工具から手腕に伝わる振動をいう。","l":"法令外","c":""},{"id":"2025-35","s":1,"q":"光と色の知覚、色の効果について、最も不適当なものはどれか。","o":["目が受け取った刺激で生じる感覚が視覚である。","視細胞のうち、錐体細胞は角膜に、杆体細胞は網膜にある。","暗い場所や明るい場所に合わせて目の感度が変わることを、順応という。","暗順応にかかる時間は、明順応より長い。","危険・注意などの警告のために使う配色を、識別配色という。"],"a":1,"e":"錐体細胞も杆体細胞も、どちらも網膜にある視細胞である。","l":"法令外","c":""},{"id":"2025-36","s":1,"q":"情報機器作業と健康について、最も不適当なものはどれか。","o":["情報機器作業とは、パソコンなどの情報機器を使って行う作業をいう。","パソコンを使うときは頭や手の位置が大きく制限され、これを「拘束性」という。","情報機器作業者が訴える自覚症状で最も多いのは、首や肩のこりである。","情報機器作業で最も重要な健康障害の要因は、作業時間である。","ディスプレイを使う場合、書類の上とキーボードの上の照度は300lx以上にする。"],"a":2,"e":"情報機器作業者の自覚症状で最も多いのは、首や肩のこりではなく目の疲れ・痛みなど目の症状である。","l":"法令外(情報機器作業における労働衛生管理のためのガイドライン)","c":""},{"id":"2025-37","s":1,"q":"電場・磁場・電磁波について、最も不適当なものはどれか。","o":["電磁波は、周波数が高いほど波長が短く、周波数が低いほど波長が長い。","電離放射線のうち、α線やβ線は電磁波に含まれない。","電磁波の波長には、1kmを超える長いものもある。","家庭用の電化製品や送電線から出る磁場を、静磁場という。","電磁波の発がん性の評価として代表的なものに、国際がん研究機関(IARC)の発がん分類がある。"],"a":3,"e":"静磁場は時間で変化しない磁場をいう。家庭用電化製品や送電線の磁場は交流電流による低周波の変動磁場であり、静磁場とは呼ばない。","l":"法令外","c":""},{"id":"2025-38","s":1,"q":"赤外線・マイクロ波・レーザー光線について、最も不適当なものはどれか。","o":["赤外線を浴びる作業として、炉の前での作業やガラス加工の作業がある。","赤外線は、熱中症の原因になる。","白内障は、一般に赤外線を短時間に強く浴びること(急性曝露)で起こる。","マイクロ波は、体の深いところまで届き、熱作用を起こす。","レーザー光線の健康影響として、網膜の損傷がある。"],"a":2,"e":"赤外線による白内障(ガラス工白内障など)は、長い年月にわたって浴び続ける慢性曝露で起こる。","l":"法令外","c":""},{"id":"2025-39","s":1,"q":"電離放射線について、最も不適当なものはどれか。","o":["電離放射線には、物質をイオン化するはたらきがある。","放射能とは、放射性物質が放射線を出して壊変していく性質をいう。","β線は、鉛や鉄の板を通り抜ける。","細胞のうち、放射線の影響を最も受けにくいのは神経細胞である。","体内に取り込んだ放射性物質が半分の量になるまでの時間を、生物学的半減期という。"],"a":2,"e":"β線はアルミニウムなどの薄い金属板で止められ、鉛や鉄の板は通り抜けない。","l":"法令外","c":""},{"id":"2025-40","s":1,"q":"電離放射線の健康影響について、最も不適当なものはどれか。","o":["脱毛は、放射線の早期影響の一つである。","電離放射線で起こる代表的な悪性腫瘍に、白血病がある。","急性放射線熱傷は、ふつうのやけどと比べて、初めは痛みがない。","妊娠の可能性がある女性へのX線の骨盤照射は、月経が始まってから10日以内に行う。","ごく少ない線量でも影響が出る可能性があることを、確定的影響という。"],"a":4,"e":"ごく少ない線量でも確率的に影響が出る可能性があるものは「確率的影響」(がん・遺伝的影響)である。確定的影響は、しきい線量を超えたときに起こる影響。","l":"法令外","c":""},{"id":"2025-41","s":1,"q":"体重に対する水分の不足の割合と脱水症状について、最も不適当なものはどれか。","o":["1%の不足で、のどの渇きが出る。","4%の不足で、体温上昇が起こる。","6%の不足で、呼吸数が増える。","10〜12%の不足で、筋肉のけいれんが起こる。","18%の不足で、尿がつくられなくなる。"],"a":1,"e":"この記述が誤り(4%の不足で起こる症状として不適当)。","l":"法令外","c":""},{"id":"2025-42","s":1,"q":"水を介して感染する病気(水系感染症)の病原体として、最も不適当なものはどれか。","o":["ポリオウイルス","A型肝炎ウイルス","コクサッキーウイルス","パラチフス菌","RSウイルス"],"a":4,"e":"RSウイルスは、せきやくしゃみなどの飛沫や接触で感染する呼吸器の感染症の病原体で、水系感染症の病原体ではない。","l":"法令外","c":""},{"id":"2025-43","s":1,"q":"クリプトスポリジウム症について、最も適当なものはどれか。","o":["病原体は細菌である。","病原体は、ヒトやほ乳類の消化管の中で増える。","病原体は、水道水の塩素消毒で死滅する。","水道におけるクリプトスポリジウム等対策指針では、レベル1が最もリスクが高い。","下痢の症状は、一般に1〜2日で治まる。"],"a":1,"e":"クリプトスポリジウムは原虫で、ヒトやほ乳類の消化管の中で増殖する。塩素に強く、通常の塩素消毒では死なない。","l":"法令外","c":""},{"id":"2025-44","s":1,"q":"感染症法(感染症の予防及び感染症の患者に対する医療に関する法律)の感染症の分類について、最も不適当なものはどれか。","o":["一類感染症では、交通が制限されることがある。","二類感染症では、建物への立入りは制限されない。","三類感染症では、就業が制限される職種がある。","四類感染症では、積極的疫学調査は行われない。","五類感染症には、ジアルジア症が含まれる。"],"a":3,"e":"積極的疫学調査は、一類から五類まで(新型インフルエンザ等感染症などを含む)の感染症について行うことができ、四類感染症も対象になる。","l":"感染症法 第15条","c":""},{"id":"2025-45","s":1,"q":"5%溶液として売られている次亜塩素酸ナトリウム50mLを水50Lに加えたとき、この溶液の次亜塩素酸ナトリウム濃度に最も近いものはどれか。","o":["25mg/L","50mg/L","100mg/L","500mg/L","1,000mg/L"],"a":1,"e":"有効成分は50mL×0.05=2.5mL(約2.5g=2,500mg)。これが50Lに溶けるので、2,500mg÷50L=50mg/L。","l":"法令外(計算)","c":""},{"id":"2025-46","s":2,"q":"用語と単位の組合せのうち、誤っているものはどれか。","o":["貫流熱流 ― W/(m²・K)","風圧 ― Pa","音の強さ ― W/m²","立体角 ― sr","色温度 ― K"],"a":0,"e":"W/(m²・K)は熱貫流率(温度差1Kあたりの熱の通りやすさ)の単位。熱流そのものの単位ではないので、この組合せが誤り。","l":"法令外","c":""},{"id":"2025-47","s":2,"q":"熱伝導率1.6W/(m・K)のコンクリートで厚さ16cmの外壁をつくった。外気側の熱伝達抵抗が0.05m²・K/W、室内側が0.1m²・K/Wのとき、この外壁の熱貫流抵抗として正しいものはどれか。","o":["0.25m²・K/W","4.0m²・K/W","10m²・K/W","20m²・K/W","30m²・K/W"],"a":0,"e":"熱貫流抵抗＝外側の熱伝達抵抗＋(厚さ÷熱伝導率)＋内側の熱伝達抵抗＝0.05＋0.16÷1.6＋0.1＝0.05＋0.1＋0.1＝0.25m²・K/W。","l":"計算","c":""},{"id":"2025-48","s":2,"q":"下の図は、外壁の断面図上に、冬期暖房時の壁内定常温度分布を示している。この図に関する次の記述のうち、最も適当なものはどれか。","o":["温度分布はAとなり、壁内結露の防止のためにアに防湿層を設けることは有効である。","温度分布はBとなり、壁内結露の防止のためにウに防湿層を設けることは有効である。","温度分布はCとなり、壁内結露の防止のためにイに防湿層を設けることは有効である。","温度分布はAとなり、壁内結露の防止のためにイに防湿層を設けることは有効である。","温度分布はCとなり、壁内結露の防止のためにウに防湿層を設けることは有効である。"],"a":3,"e":"熱伝導率の小さい断熱材の中で温度が大きく下がり、コンクリート内はゆるやかになるので温度分布はA。防湿層は断熱材の室内側(暖かい側)に設けるので、断熱材とコンクリートの境目のイが有効。","l":"法令外","c":"","g":["img/2025-48.png"]},{"id":"2025-49","s":2,"q":"熱の移動について述べた次の文のうち、最も不適当なものはどれか。","o":["同じ材料でも、内部に含む水分が多いほど熱伝導抵抗は一般に小さくなる。","密度の大きい材料ほど、熱伝導抵抗は一般に小さくなる。","均質な壁の中を流れる熱流は、壁の両面の温度差に熱伝導抵抗の逆数をかけて求める。","中空層の内面にアルミ箔を貼ると、中空層の熱抵抗は小さくなる。","硬質ウレタンフォームなどの断熱材の熱伝導率が小さいのは、気泡状にして内部の気体が動かないようにしているためである。"],"a":3,"e":"アルミ箔は放射率が小さく、中空層の中の放射による熱移動を減らすので、熱抵抗はむしろ大きくなる。","l":"法令外","c":""},{"id":"2025-50","s":2,"q":"熱放射について述べた次の文のうち、最も不適当なものはどれか。","o":["常温の物体が出す電磁波は、波長10μm付近の赤外線が中心である。","黒色ペイントは、光ったアルミ箔よりも長波長放射率が大きい。","熱放射を近似的に扱うときは、室内の壁面温度の代わりに室内の空気温度を使うことがある。","光ったアルミ箔は、酸化した亜鉛鉄板よりも日射吸収率が大きい。","放射熱伝達率は、放射をやりとりする各面の長波長放射率の積に比例する。"],"a":3,"e":"光ったアルミ箔は日射をよく反射するため、日射吸収率は小さい。酸化した亜鉛鉄板の方が日射吸収率は大きいので、この記述が誤り。","l":"法令外","c":""},{"id":"2025-51","s":2,"q":"自然換気の換気力について述べた次の文のうち、最も不適当なものはどれか。","o":["温度差による換気力は、開口部どうしの高さの差に比例する。","温度差による換気力は、室内と屋外の空気の密度差に比例する。","風力による換気力は、外部の風速に比例する。","風力による換気力は、開口部の風圧係数に比例する。","風力による換気力は、風向きが変わると変わる。"],"a":2,"e":"風圧は(1/2)×空気の密度×風速²で表されるので、風力による換気力は風速の2乗に比例する。","l":"法令外","c":""},{"id":"2025-52","s":2,"q":"下の図は、冷房時の各種吹出方式による室内気流を示したものである。一般的に、冷房時に好ましい方式の室内気流の組合せとして、最も適当なものはどれか。","o":["AとC","BとD","AとD","BとC","CとD"],"a":0,"e":"冷たい空気は重く下に沈むので、冷房では天井付近から横に吹き出して部屋全体に広げる方式が好ましい。壁上部から吹くAと、天井から水平に広げるCがこれにあたる。床から吹くBや、真下に吹き下ろすDは冷気が足元にたまりやすい。","l":"法令外","c":"","g":["img/2025-52.png"]},{"id":"2025-53","s":2,"q":"室内の気流について述べた次の文のうち、最も不適当なものはどれか。","o":["置換換気は、室温より少し低い空気を床近くから供給し、天井近くから排気する方式である。","ドラフトによる不快感は、気流の速さ、気流の変動の大きさ、空気の温度に影響される。","天井面に沿って流れる噴流の到達距離は、自由噴流よりも短くなる。","吹出しの影響は遠くまで届くが、吸込みの影響は吸込口の近くに限られる。","気流の性状から見た換気方式は、混合方式と一方向方式の2つに大きく分けられる。"],"a":2,"e":"天井に沿う噴流は天井に引き付けられて(コアンダ効果)拡散しにくいため、自由噴流より到達距離が長くなる。","l":"法令外","c":""},{"id":"2025-54","s":2,"q":"室内の空気汚染物質について述べた次の文のうち、最も不適当なものはどれか。","o":["建築物衛生法での一酸化炭素の管理基準値は6ppm以下である。","室内の二酸化炭素はおもに人の呼吸などから発生し、その濃度は換気量の目安として使われる。","室内の浮遊粉じんの発生源には、たばこ、人の活動、外気由来などがある。","建築物衛生法でのホルムアルデヒドの管理基準値は0.08mg/m³以下である。","省エネルギーのために取り入れる外気量を減らしすぎると、室内の空気の質に影響することがある。"],"a":3,"e":"ホルムアルデヒドの管理基準値は、空気1m³あたり0.1mg以下(施行令第2条)。一酸化炭素の6ppm以下は現行の条文どおり。","l":"建築物衛生法施行令 第2条第1号","c":""},{"id":"2025-55","s":2,"q":"室内汚染物質の特徴を示した次のア〜エのうち、オゾンの特徴にあたるものの組合せとして最も適当なものはどれか。\nア 常温で独特の刺激臭がある不安定な気体である。\nイ 室内の発生源はコピー機やレーザープリンタなどである。\nウ 大気中の発生源は火山や森林火災である。\nエ 比較的分子の小さい有機物質である。","o":["アとイ","アとウ","イとウ","イとエ","ウとエ"],"a":0,"e":"オゾンは刺激臭のある不安定な気体で、室内ではコピー機やレーザープリンタなどの高電圧を使う機器から出る。オゾンは有機物質ではない。","l":"法令外","c":""},{"id":"2025-56","s":2,"q":"揮発性有機化合物と発生源の組合せとして、最も不適当なものはどれか。","o":["ホルムアルデヒド ― 加熱式たばこ","トルエン ― 溶剤","パラジクロロベンゼン ― 防虫剤","テトラデカン ― プラスチックの可塑剤","ダイアジノン ― 防蟻剤"],"a":3,"e":"この組合せが誤り。テトラデカンは灯油などに含まれる炭化水素で、プラスチックの可塑剤ではない。","l":"法令外","c":""},{"id":"2025-57","s":2,"q":"エアロゾル粒子と、その測定される粒径の組合せとして、最も適当なものはどれか。","o":["細菌 ― 0.01μm","海塩粒子 ― 0.1μm","ウイルス ― 1.0μm","たばこ煙 ― 10μm","カビ胞子 ― 100μm"],"a":1,"e":"海塩粒子は0.1μm程度の範囲で測定される。ほかは桁がずれており、たとえばウイルスは細菌より小さいので、細菌0.01μm・ウイルス1.0μmという大小関係も逆になっている。","l":"法令外","c":""},{"id":"2025-58","s":2,"q":"浮遊粒子の動きにかかわる性質を表す次のア〜エのうち、粒径が大きくなるほど値が大きくなるものの組合せとして、最も適当なものはどれか。\nア 終末沈降速度\nイ 拡散係数\nウ 気流と平行な垂直面への沈着速度\nエ 粒子径を代表長さとしたレイノルズ数","o":["アとイ","アとウ","アとエ","イとエ","ウとエ"],"a":2,"e":"大きい粒子ほど速く沈むので終末沈降速度は大きく、レイノルズ数も粒子径に比例して大きくなる。拡散係数と、拡散による垂直面への沈着速度は、粒径が大きいほど小さくなる。","l":"法令外","c":""},{"id":"2025-59","s":2,"q":"暖房時における空気調和システムを図-Aに、空気の状態変化を湿り空気線図上に表したものを図-Bに示す。図-Aの各点に対する図-B中の状態点との組合せとして、最も適当なものはどれか。","o":["a ― エ","b ― ア","c ― イ","d ― ウ","e ― オ"],"a":2,"e":"冬の外気a=オ、室内e=ウ、その混合b=エ。加熱器で温めた点c=イ(絶対湿度はそのまま)、加湿器で加湿した吹出空気d=ア。","l":"法令外","c":"","g":["img/2025-59a.png","img/2025-59b.png"]},{"id":"2025-60","s":2,"q":"空調の熱負荷について述べた次の文のうち、最も不適当なものはどれか。","o":["照明の発熱による負荷は顕熱負荷である。","ダクトを通る間の熱負荷は、一般に潜熱負荷を無視する。","送風機による負荷は、一般に暖房時には無視する。","外気負荷には顕熱負荷と潜熱負荷の両方がある。","人体の発熱による負荷では、一般に潜熱負荷を無視する。"],"a":4,"e":"人体は体温による顕熱のほか、呼吸や汗による水蒸気(潜熱)も出す。人体負荷では潜熱も計算に入れるので、この記述が誤り。","l":"法令外","c":""},{"id":"2025-61","s":2,"q":"湿り空気と結露について述べた次の文のうち、最も不適当なものはどれか。","o":["湿り空気線図では、絶対湿度と露点温度がわかれば状態点が決まる。","絶対湿度を変えずに湿り空気を冷やすと、相対湿度は上がる。","相対湿度100%の湿り空気では、乾球温度も湿球温度も露点温度と同じになる。","表面結露を防ぐには、室内で発生させる水蒸気を必要以上に増やさないことも大切である。","熱橋(ヒートブリッジ)になった部分は局所的に結露しやすいので注意が必要である。"],"a":0,"e":"露点温度は絶対湿度だけで決まるため、この2つは同じ情報を表している。状態点を決めるには、ほかに乾球温度などの独立した値が必要。","l":"法令外","c":""},{"id":"2025-62","s":2,"q":"代表的な空気調和方式と、熱媒体による分類の組合せとして、最も不適当なものはどれか。","o":["変風量単一ダクト方式 ― 水・空気方式","マルチゾーン空調方式 ― 全空気方式","分散設置空気熱源ヒートポンプPAC方式 ― 冷媒方式","分散設置水熱源ヒートポンプPAC方式 ― 熱源水方式","ダクト併用ファンコイルユニット方式 ― 水・空気方式"],"a":0,"e":"変風量単一ダクト方式は、空調機でつくった空気だけで室内を冷暖房するので全空気方式にあたる。","l":"法令外","c":""},{"id":"2025-63","s":2,"q":"中央方式の空気調和設備について述べた次の文のうち、最も不適当なものはどれか。","o":["ダクト併用ファンコイルユニット方式は、単一ダクト方式より空調機を大きくする必要がある。","変風量単一ダクト方式では、熱負荷に合わせて給気風量を変えるので、外気の取入れ量も変わる。","マルチゾーン空調方式では、1台の空調機で複数のゾーンの温湿度を調整する。","定風量単一ダクト方式では、熱負荷の変化に給気温度を変えることで対応する。","放射冷暖房は、単独で設置すると、新鮮外気の導入や室内空気の循環による除じんの機能をもたない。"],"a":0,"e":"ダクト併用ファンコイルユニット方式では、熱負荷の一部をファンコイルユニットが受け持つため、単一ダクト方式より空調機は小さくできる。","l":"法令外","c":""},{"id":"2025-64","s":2,"q":"次の空気調和設備のうち、個別方式にあたらないものはどれか。","o":["空気熱源ヒートポンプパッケージ","ウォールスルー型ユニット","水熱源ヒートポンプパッケージ","ビル用マルチパッケージ","ターミナルエアハンドリングユニット"],"a":4,"e":"ターミナルエアハンドリングユニットは、中央の熱源から冷温水を受けて使う中央方式の機器。ほかの4つはパッケージ型などの個別方式。","l":"法令外","c":""},{"id":"2025-65","s":2,"q":"ヒートポンプについて述べた次の文のうち、最も不適当なものはどれか。","o":["電動機で動かすヒートポンプは、電動冷凍機とボイラを組み合わせる方式に比べ、夏と冬の使用電力量の差を小さくできる。","水熱源方式は、河川水や下水の熱などの未利用エネルギーの活用に向いている。","空気熱源方式が一般に熱をくみ取る相手は外気である。","ガスエンジン駆動方式は、エンジンの排熱を活用できるので、寒冷地の暖房熱源に向いている。","空気熱源方式と水熱源方式を比べると、現在の主流は水熱源方式である。"],"a":4,"e":"この記述が誤り。現在広く普及しているのは、外気を熱源とする空気熱源方式の方である。","l":"法令外","c":""},{"id":"2025-66","s":2,"q":"ボイラについて述べた次の文のうち、最も不適当なものはどれか。","o":["炉筒煙管ボイラは、直径の大きな横型ドラムを本体とし、燃焼室と煙管群でできている。","ボイラは、吸収冷凍機を動かす熱源として冷房時にも使われる。","鋳鉄製ボイラは、高温・高圧・大容量のボイラには向かない。","貫流ボイラを扱うには、容量に関係なくボイラー技士の資格が必要である。","真空式温水発生機は、容量に関係なくボイラの取扱い資格が不要である。"],"a":3,"e":"この記述が誤り。貫流ボイラは容量によって扱いが分かれ、小さいものはボイラー技士の資格がなくても取り扱える。","l":"法令外","c":""},{"id":"2025-67","s":2,"q":"蓄熱システムについて述べた次の文のうち、最も不適当なものはどれか。","o":["一般に、夏の冷房最盛期よりも冬の暖房最盛期の方が、電力負荷の平準化の効果が大きい。","躯体蓄熱システムは、氷蓄熱システムより熱損失が大きい。","蓄熱システムを使うと、熱源装置の容量を減らせる。","潜熱を利用する蓄熱材には、氷や無機水和塩類などがある。","顕熱を利用する蓄熱材には、水、土壌、RC躯体などがある。"],"a":0,"e":"電力需要のピークは夏の冷房期に生じやすく、夜間に蓄えた冷熱を昼に使う効果は夏の冷房最盛期の方が大きい。","l":"法令外","c":""},{"id":"2025-68","s":2,"q":"図は、蒸気圧縮冷凍サイクルにおける冷媒の標準的な状態変化をモリエル線図上に表したものである。蒸発器の出口直後に相当する図中の状態点として、最も適当なものはどれか。","o":["ア","イ","ウ","エ","オ"],"a":4,"e":"膨張弁を出た冷媒(エ)は蒸発器で熱を奪って蒸発し、圧力は低いまま比エンタルピーが増えてオになる。オが蒸発器の出口で、そのあと圧縮機でアへ。","l":"法令外","c":"","g":["img/2025-68.png"]},{"id":"2025-69","s":2,"q":"標準的なエアハンドリングユニットの機器を、上流側から並べた順番として最も適当なものはどれか。","o":["加湿器 → 送風機 → エアフィルタ","熱交換器(コイル) → 加湿器 → エアフィルタ","加湿器 → 熱交換器(コイル) → 送風機","熱交換器(コイル) → エアフィルタ → 加湿器","エアフィルタ → 熱交換器(コイル) → 加湿器"],"a":4,"e":"まずエアフィルタでほこりを除き、コイルで冷却・加熱し、その後で加湿器により加湿する順番が標準である。","l":"法令外","c":""},{"id":"2025-70","s":2,"q":"冷却塔について述べた次の文のうち、最も不適当なものはどれか。","o":["開放型冷却塔は、同じ容量の密閉型冷却塔より一般に大型である。","密閉型冷却塔は、電算室やクリーンルームの系統によく使われる。","開放型冷却塔は、密閉型冷却塔より送風機の動力が小さい。","密閉型冷却塔は、散布水系統の保有水量が少ないので、保有水中の不純物濃度が高くなる。","空調用の冷却塔は、おもに冷凍機の凝縮熱を大気に捨てる装置として使われる。"],"a":0,"e":"密閉型は冷却水をコイルの中に通して間接的に冷やすため、同じ容量なら開放型より大型になる。開放型の方が小さい。","l":"法令外","c":""},{"id":"2025-71","s":2,"q":"空気調和設備に使う全熱交換器について述べた次の文のうち、最も不適当なものはどれか。","o":["全熱交換器は、排気の顕熱と潜熱を同時に回収して省エネルギーを図る熱交換器である。","回転型全熱交換器では、エレメントがゆっくり回転し、吸湿と放湿が連続して切り替わる。","静止型全熱交換器の仕切り板には、熱を伝える性質と同時に湿気を通す性質が必要である。","水分の回収が不要な厨房や温水プールでは、全熱交換器の代わりに顕熱交換器が使われる。","空調した室内の空気を便所や給湯室などから直接排気する割合が高いと、全熱交換器の効率は上がる。"],"a":4,"e":"便所などから直接捨てる空気が多いと、全熱交換器を通る排気が減り、回収できる熱が少なくなる。効率は上がらず、むしろ下がる。","l":"法令外","c":""},{"id":"2025-72","s":2,"q":"加湿装置の方式について述べた次の文のうち、最も不適当なものはどれか。","o":["気化方式では、吹出し空気の温度が下がる。","気化方式は、結露するおそれが小さい。","水噴霧方式は、給水に含まれる不純物を放出しない。","水噴霧方式では、吹出し空気の温度が下がる。","蒸気方式では、吹出し空気の温度は下がらない。"],"a":2,"e":"水噴霧方式は水をそのまま霧にして飛ばすため、給水に含まれる不純物も一緒に室内へ放出される。","l":"法令外","c":""},{"id":"2025-73","s":2,"q":"吹出口と吸込口について述べた次の文のうち、最も不適当なものはどれか。","o":["ふく流吹出口は、ほかの吹出口より誘引効果が高く、ムラの少ない温度分布が得られる。","軸流吹出口は、誘引比が小さいので到達距離が長い。","線状吹出口は、ペリメータ負荷の処理のため窓の近くに設置されることが多い。","有孔天井による面状吹出口には、放射冷暖房の効果がある。","吸込口の吸込気流には方向性があるので、吸込気流の角度を調整する必要がある。"],"a":4,"e":"吸込みの影響は吸込口のすぐ近くにしか及ばず、吸込気流には吹出しのような方向性がほとんどない。角度調整の必要もない。","l":"法令外","c":""},{"id":"2025-74","s":2,"q":"ダクトの材料の選び方として、最も不適当なものはどれか。","o":["ダクト系の騒音を抑えるため、グラスウールダクトを使った。","塗装なしで見た目を整える必要があるダクトに、ステンレス鋼板を使った。","ボイラの高温空気や高温ガスが通るダクトに、亜鉛鉄板を使った。","さびや腐食を防ぐ必要があるダクトに、塩化ビニルで被覆した鋼板を使った。","腐食性ガスを排気するダクトに、硬質ポリ塩化ビニル板を使った。"],"a":2,"e":"この選び方が誤り。亜鉛鉄板は高温のガスが通る部分には向かない。","l":"法令外","c":""},{"id":"2025-75","s":2,"q":"ポンプについて述べた次の文のうち、最も不適当なものはどれか。","o":["キャビテーションが起きた部分は激しく浸食され、ポンプの寿命が短くなる。","フライホイールなどを付けて回転体の慣性を大きくすると、停電時の水撃作用を防げる。","配管系の流体摩擦損失や機器の損失は、管内流速の2乗に比例する。","一般に、全揚程は吐出し量がゼロのときに最小で、吐出し量が増えるほど高くなる。","揚程曲線が右下がりになっている部分に運転点をおくと、サージングを防げる。"],"a":3,"e":"一般的なポンプの揚程曲線は右下がりで、吐出し量ゼロ(締切り)のときに全揚程が最大となり、吐出し量が増えるほど下がる。","l":"法令外","c":""},{"id":"2025-76","s":2,"q":"換気設備について述べた次の文のうち、最も不適当なものはどれか。","o":["燃焼に必要な酸素を供給するための換気設備は、排気装置の種類ごとに必要な排気量などの構造基準が法律で決められている。","一般的なパッケージ型空調機には外気を取り入れる機能があり、室内の空気質を管理しやすい。","中央式空気調和設備で使う換気設備は、空調設備と兼ねたシステムとして設けられることが多い。","厨房や倉庫では、換気設備を単独で設けることが多い。","ヒートポンプデシカント調湿型外気処理装置では、冷房除湿時のドレン管や暖房加湿時の給水管を設けなくてもよい。"],"a":1,"e":"一般的なパッケージ型空調機は室内の空気を循環させるだけで、外気を取り入れる機能をもたない。そのため換気設備を別に設ける必要がある。","l":"法令外","c":""},{"id":"2025-77","s":2,"q":"揮発性有機化合物(VOCs)について述べた次の文のうち、最も不適当なものはどれか。","o":["VOCsの測定には、基本的にガスクロマトグラフ質量分析計を使う。","加熱脱着法は、溶媒抽出法に比べて測定感度が低い。","TVOCは、ヘキサンからヘキサデカンまでの範囲にあるVOCsの合計と定義される。","TVOCの測定にパッシブ法を使うのは難しい。","市販のTVOCモニタは、標準ガスによる定期的な校正が欠かせない。"],"a":1,"e":"加熱脱着法は採取した物質をすべて分析装置に送れるため、溶媒で薄める溶媒抽出法より測定感度が高い。","l":"法令外","c":""},{"id":"2025-78","s":2,"q":"環境要素などの測定について述べた次の文のうち、最も不適当なものはどれか。","o":["温度の測定には、液体の体積膨張を利用する方法がある。","風速の測定には、センサーの球体部が気流で冷やされる度合いと風速の関係を利用する方法がある。","相対湿度の測定には、金属の線膨張を利用する方法がある。","風速の測定には、ベルヌーイの定理を利用する方法がある。","風量の測定には、オリフィスを利用する方法がある。"],"a":2,"e":"金属の線膨張(バイメタルなど)は温度の測定に使う原理。相対湿度は、毛髪の伸び縮みや電気抵抗・静電容量の変化などで測る。","l":"法令外","c":""},{"id":"2025-79","s":2,"q":"汚染物質と、その濃度または強さを表す単位の組合せとして、最も不適当なものはどれか。","o":["ダイアジノン ― μg/m³","二酸化硫黄 ― ppm","放射能 ― Bq","ダニアレルゲン ― ng/m³","知覚空気汚染質濃度 ― olf"],"a":4,"e":"olf(オルフ)は汚染の発生量を表す単位。知覚される空気汚染の濃度はdecipol(デシポル)で表す。","l":"法令外","c":""},{"id":"2025-80","s":2,"q":"環境要素の測定について述べた次の文のうち、最も不適当なものはどれか。","o":["微生物の間接的な測定法として、核酸増幅法がある。","硫黄酸化物の測定法として、溶液導電率法がある。","酸素の測定法として、非分散型赤外線吸収法がある。","オゾンの測定法として、化学発光法がある。","浮遊粉じんの測定法として、β線吸収法がある。"],"a":2,"e":"非分散型赤外線吸収法は、二酸化炭素や一酸化炭素の測定に使う方法。酸素の測定には、ガルバニ電池方式などが使われる。","l":"法令外","c":""},{"id":"2025-81","s":2,"q":"空気調和・換気設備の維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["レジオネラ症は、レジオネラ属菌が空調・換気設備を通じて室内に入ることなどで起こる。","点検、整備、検査、修理を行う業務は、保全業務に含まれる。","平均故障間隔(MTBF)とは、システムや機器、部品などで起こる故障と故障の間の動作時間の平均である。","故障で止まったときの影響が大きい機器は、重要機器として点検レベルを高くし、重点的に管理する。","事後保全とは、部品の劣化を保全計画に組み込んで、計画的に修理・交換する方法である。"],"a":4,"e":"事後保全は、故障が起きてから修理する方法。劣化を見込んで計画的に修理・交換するのは予防保全である。","l":"法令外","c":""},{"id":"2025-82","s":2,"q":"冷却塔と冷却水の維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["冷却塔と冷却水の水管は、1年以内ごとに1回清掃する。","冷却塔は設置位置と型式を調べ、通常の冷却塔か要注意冷却塔かに分けて管理する。","冷却水の強制ブローは、冷却水の濃縮を防ぐのに役立つ。","スケール防止剤やレジオネラ属菌の殺菌剤などを含むパック剤の効果は、約1年間続く。","冷却塔に供給する水は、水道法第4条の水質基準に適合している必要がある。"],"a":3,"e":"この記述が誤り(パック剤の効果は1年も続かず、定期的な交換が必要)。冷却塔・冷却水の水管の清掃は1年以内ごとに1回(施行規則第3条の18)、供給水は水道法第4条の水質基準に適合させる(同条)ので、(1)(5)は正しい。","l":"建築物衛生法施行規則 第3条の18","c":""},{"id":"2025-83","s":2,"q":"遮音について述べた次の文のうち、最も不適当なものはどれか。","o":["遮音とは、壁などで音をさえぎり、通り抜ける音のエネルギーを小さくすることである。","断面の仕様が異なる複数の部材でできた壁の遮音性能は、総合透過損失で評価する。","複層壁では、共鳴によって音が通り抜けることがある。","コインシデンス効果が起きると、壁の透過損失は小さくなる。","床衝撃音の遮音等級Lr値は、値が大きいほど遮音性能が高いことを表す。"],"a":4,"e":"Lr値は、床の下の部屋に聞こえる音の大きさを表す等級なので、値が小さいほど遮音性能が高い。","l":"法令外","c":""},{"id":"2025-84","s":2,"q":"床衝撃音についての次の文の[ア]〜[ウ]に入る語句の組合せとして、最も適当なものはどれか。\n「重量床衝撃音は、[ア]ときに発生し、その衝撃音はおもに[イ]の成分を含む。対策としては[ウ]が効果的である。」","o":["ア 人が床の上で飛び跳ねたりした/イ 高周波数域/ウ 柔らかい床仕上げ材","ア 人が床の上で飛び跳ねたりした/イ 低周波数域/ウ 柔らかい床仕上げ材","ア 人が床の上で飛び跳ねたりした/イ 低周波数域/ウ 床躯体構造の質量を増やすこと","ア テーブルを引きずったりした/イ 高周波数域/ウ 柔らかい床仕上げ材","ア テーブルを引きずったりした/イ 低周波数域/ウ 床躯体構造の質量を増やすこと"],"a":2,"e":"重量床衝撃音は子どもの飛び跳ねなど重く柔らかいものの衝撃で生じ、低い周波数が中心。床仕上げを柔らかくしても効きにくく、床の躯体を重く(厚く)するのが効果的。テーブルを引きずる音は軽量床衝撃音。","l":"法令外","c":""},{"id":"2025-85","s":2,"q":"音圧レベル80dBの音源室と、面積10m²の隔壁で仕切られた受音室(等価吸音面積20m²)がある。受音室の平均音圧レベルを40dBにするために、隔壁に必要な音響透過損失に最も近いものはどれか。\nただし L1－L2＝TL＋10log10(A2/Sw) の関係がある(L1・L2:音源室・受音室の平均音圧レベル[dB]、A2:受音室の等価吸音面積[m²]、Sw:隔壁の面積[m²]、TL:隔壁の音響透過損失[dB])。log10 2＝0.3010、log10 3＝0.4771とする。","o":["37dB","38dB","39dB","40dB","43dB"],"a":0,"e":"80－40＝TL＋10log10(20/10)より、40＝TL＋10×0.3010＝TL＋3.01。よってTL＝36.99≒37dB。","l":"計算","c":""},{"id":"2025-86","s":2,"q":"音・振動環境の保守管理について述べた次の文のうち、最も不適当なものはどれか。","o":["室内の平均的な音の大きさを評価するには、できるだけ多くの点で測定し、平均する必要がある。","扉を毎日開け閉めするうちにゴムパッキンが切れたりずれたりして、遮音性能が下がることがある。","騒音・振動を測定するときは、暗騒音・暗振動が大きい時間帯を避ける。","風や地震などで建物に層間変位が起き、壁や床にすき間ができて遮音性能が下がることがある。","設備機器の振動による固体伝搬音の対策としては、壁や床などの遮音性能を高めることが重要である。"],"a":4,"e":"固体伝搬音は振動が建物の構造体を伝わって出る音なので、壁や床の遮音を強めても効きにくい。振動源側で防振する対策が重要。","l":"法令外","c":""},{"id":"2025-87","s":2,"q":"光と照明について述べた次の文のうち、最も不適当なものはどれか。","o":["事務所の製図室のグレア制限値は、事務室のグレア制限値より低い。","拡散グローブ照明は、間接照明型の照明器具である。","室内表面の輝度の差が大きすぎると、目が疲れやすくなる。","光が当たった面が滑らかな場合、光は正反射して光沢となる。","タスク・アンビエント照明方式では、高い照度が必要な作業領域を局部照明で明るくすることで、全般照明の照度を抑えられる。"],"a":1,"e":"拡散グローブ照明は、乳白色のガラス球などで光を全方向に広げる全般拡散照明型の器具で、間接照明型ではない。","l":"法令外","c":""},{"id":"2025-88","s":2,"q":"ランプと発光の原理の組合せとして、最も不適当なものはどれか。","o":["水銀ランプ ― 放電発光","メタルハライドランプ ― 放電発光","発光ダイオード(LED) ― 温度(熱)放射","白熱電球 ― 温度(熱)放射","蛍光ランプ ― 放電発光"],"a":2,"e":"LEDは半導体に電流を流して光らせる電界発光(エレクトロルミネセンス)で、熱放射ではない。熱放射で光るのは白熱電球。","l":"法令外","c":""},{"id":"2025-89","s":2,"q":"地表で直射日光による法線面照度が80,000lxのとき、直射日光による水平面照度に最も近いものはどれか。ただし太陽高度は45度とする。","o":["40,000lx","56,000lx","70,000lx","80,000lx","113,000lx"],"a":1,"e":"水平面照度＝法線面照度×sin(太陽高度)＝80,000×sin45°＝80,000×0.707≒56,600lxなので、56,000lxが最も近い。","l":"計算","c":""},{"id":"2025-90","s":2,"q":"照明施設の保守について述べた次の文のうち、最も不適当なものはどれか。","o":["室内の照度は、使ううちに光源や照明器具に付く汚れによって下がっていく。","保守率は、ある期間使った後の作業面の平均照度と、初期の平均照度との比で表す。","LED照明器具では、周りの環境の清浄度が同じなら、下面開放形と完全密閉形の設計光束維持率は同じである。","既設の蛍光ランプ用器具のランプを直管型LEDランプに替えるとき、正しいランプと器具の組合せでないと、器具の焼損や火災につながるおそれがある。","蛍光灯照明器具の寿命は、電源電圧や周囲温度などの使用条件によって短くなることがある。"],"a":2,"e":"器具の形によって汚れの付きやすさが違うため、同じ環境でも下面開放形と完全密閉形では設計光束維持率が異なる。","l":"法令外","c":""},{"id":"2025-91","s":3,"q":"日射・日照と、その調整の方法について、最も不適当なものはどれか。","o":["樹木の緑の葉の日射反射率は、一般にコンクリートより大きい。","ライトシェルフとは、直射日光を反射させて部屋の奥まで光を届ける庇である。","オーニングとは、窓に取り付ける日よけの一種である。","照り返しは、照り返す面での日射の反射と、その面からの熱放射とに分けられる。","室内側につけるブラインドの日射を遮る効果は、屋外側につけるブラインドより小さい。"],"a":0,"e":"樹木の緑の葉は日射をよく吸収するため、日射反射率はコンクリートより小さい。","l":"法令外","c":""},{"id":"2025-92","s":3,"q":"日射・日照について、最も不適当なものはどれか。","o":["直達日射と天空日射は、短波長放射と呼ばれる。","紫外線には、体内でビタミンDをつくるはたらきがある。","天空日射とは、太陽の光が大気中で散乱して地上に降り注いだものである。","夏至の晴れた日、南向きの垂直な壁が1日に受ける日射量は、那覇のほうが東京より多い。","日影曲線とは、地面に垂直に立てた長さ1の棒が水平面に落とす影の先端の軌跡を、季節ごとに描いたものである。"],"a":3,"e":"夏至の那覇は太陽高度が非常に高く、南向きの垂直な壁にはほとんど日が当たらないため、1日の受熱量は東京より少ない。","l":"法令外","c":""},{"id":"2025-93","s":3,"q":"建築計画と建築士法について、最も不適当なものはどれか。","o":["一級建築士は、建築士法にもとづき、国土交通大臣の免許を受ける資格である。","二級建築士は、建築士法にもとづき、都道府県知事の免許を受ける資格である。","建築設備士は、建築基準法の適合チェックが義務づけられた建築物に関わらなければならない。","貸事務所で、収益を生む部分の床面積を延べ面積で割ったものを、レンタブル比という。","工事監理とは、自分の責任で、工事を設計図書と照らし合わせて確認することである。"],"a":2,"e":"建築設備士は、建築士に対して建築設備について意見を述べる(助言する)資格であり、関与が義務づけられているわけではない。","l":"建築士法 第2条、第4条、第20条第5項","c":""},{"id":"2025-94","s":3,"q":"建築物の荷重と構造力学について、最も不適当なものはどれか。","o":["店舗の売場の床の構造計算に使う積載荷重は、教室より大きく決められている。","等分布荷重がかかる片持ち梁のせん断力は、固定端で最も大きい。","荷重には、集中荷重、曲げモーメント荷重、等分布荷重などがある。","固定荷重には、家具の重さが含まれる。","一般の区域の積雪荷重は、積雪量1cmごとに1m²あたり20N以上として計算する。"],"a":3,"e":"家具や人の重さは積載荷重に含まれる。固定荷重は、柱・梁・床・仕上げ材など建物そのものの重さである。","l":"建築基準法施行令 第84条〜第86条","c":""},{"id":"2025-95","s":3,"q":"鉄筋コンクリート造の建築物の用途を、法定耐用年数が短い順に並べたものはどれか。","o":["店舗 < 公衆浴場 < 住宅 < 事務所","店舗 < 公衆浴場 < 事務所 < 住宅","店舗 < 事務所 < 住宅 < 公衆浴場","公衆浴場 < 店舗 < 事務所 < 住宅","公衆浴場 < 店舗 < 住宅 < 事務所"],"a":4,"e":"鉄筋コンクリート造の法定耐用年数は、公衆浴場31年、店舗39年、住宅47年、事務所50年。","l":"減価償却資産の耐用年数等に関する省令 別表第1","c":""},{"id":"2025-96","s":3,"q":"仕上げ材料について、最も不適当なものはどれか。","o":["モルタルは、水とセメントと砂を練り混ぜたものである。","アルミニウムの比重は、鉄の約1/5である。","複層ガラスは、2枚の板ガラスの間に乾燥空気などを閉じこめて、断熱性・遮音性を高めたものである。","インシュレーションボード(軟質繊維板)は、木質の繊維板のうち比重が0.4未満のものをいう。","ALCパネルは、石灰質とケイ酸質を主な原料とした、軽量気泡コンクリートのパネルである。"],"a":1,"e":"アルミニウムの比重は約2.7、鉄は約7.9なので、アルミニウムは鉄の約1/3である。","l":"法令外","c":""},{"id":"2025-97","s":3,"q":"LPガスとその設備について、最も不適当なものはどれか。","o":["LPガスを燃やすのに必要な理論空気量は、都市ガス(13A)より小さい。","LPガスの容器は、いつも40℃以下に保てる場所に置く。","LPガスは空気より重いので、もれると低いところにたまるおそれがある。","LPガスは常温・常圧では気体だが、圧力をかけたり冷やしたりして液体にして貯蔵・運搬される。","LPガスには、1,000倍に薄めてもにおいで気づける付臭剤を加えることが法令で義務づけられている。"],"a":0,"e":"LPガスは都市ガス(13A)より発熱量が大きく、燃やすのに必要な理論空気量も大きい。","l":"法令外","c":""},{"id":"2025-98","s":3,"q":"電気と電気設備について、最も不適当なものはどれか。","o":["誘導灯は、災害のときに建物の利用者を安全に避難させるための設備である。","避雷設備を設ける義務は、電気事業法で定められている。","マイクログリッドとは、自然エネルギーの発電などを組み合わせて、地域の電力需要をまかなうシステムである。","RE100とは、企業が事業に使う電力を100%再生可能エネルギーでまかなうことを目指す国際的な取組である。","非常警報設備の設置基準は、消防法施行令で定められている。"],"a":1,"e":"避雷設備の設置義務は建築基準法で定められている(高さ20mを超える建築物)。","l":"建築基準法 第33条","c":""},{"id":"2025-99","s":3,"q":"電気と電気設備について、最も不適当なものはどれか。","o":["同じ定格の電力・同じ電流値なら、交流のピーク電圧は直流より高い。","設備に電力を送るケーブルの許容電流は、配線用遮断器の定格電流より大きくする。","モーターの起動時に大きな電流が流れて異常が起こらないよう、スターデルタ起動方式が使われる。","契約電力50kW以上の建物では、高圧(6.6kV)で受電し、自家用の変電設備で低圧(200V・100V)に変えて給電する。","高さ31mを超える建築物には、非常コンセント設備を設けることが義務づけられている。"],"a":4,"e":"非常コンセント設備の設置義務は、消防法で地階を除く階数が11以上の建物(11階以上の階)などに定められており、「高さ31m超」の基準ではない。","l":"消防法施行令 第29条の2","c":""},{"id":"2025-100","s":3,"q":"火災のときの排煙対策について、最も不適当なものはどれか。","o":["自然排煙方式では、排煙窓のほかに、その部屋の下のほうに給気の通り道を確保することが望ましい。","排煙設備の給気機の外気取入口は、新鮮な空気を取り入れるため屋上に設けるのが望ましい。","機械排煙方式では、火災の部屋が負圧になり廊下への煙もれを防げるが、避難扉が開け閉めしにくくなるおそれがある。","加圧防煙は、階段室に煙が入るのを防ぐため、階段室の付室や廊下によく使われる。","第2種排煙の煙を出す量は、排煙窓の位置での内外の圧力差と排煙窓の有効面積で決まる。"],"a":1,"e":"屋上は排煙口から出た煙が流れてきやすく、煙を吸い込むおそれがあるため、給気用の外気取入口の位置として望ましくない。","l":"法令外","c":""},{"id":"2025-101","s":3,"q":"建築物の防火対策と避難計画について、最も不適当なものはどれか。","o":["火災を早く見つけるため、自動火災報知設備などを設ける。","火災の広がりを防ぐため、特定防火設備で区切って防火区画をつくる。","避難の原則として、2方向以上の避難経路を確保する。","劇場や集会場などの客席からの出口の戸は、内開きにする。","避難の動線は、ふだんの動線と一致させる計画が望ましい。"],"a":3,"e":"劇場・集会場などの客席からの出口の戸は、内開きにしてはならない(避難の妨げになるため)。","l":"建築基準法施行令 第118条","c":""},{"id":"2025-102","s":3,"q":"防犯・防災の管理について、最も不適当なものはどれか。","o":["防犯用のネットワークカメラは、撮った高解像度の映像を送れるので、高画質なシステムをつくれる。","アクティブセンサとは、人などの熱を出すものを赤外線で検知し、それが動いたときに作動する防犯センサである。","夜間無人になる建物の機械警備では、異常が起きたとき25分以内に警備員がかけつけなければならない。","大規模な事業所では、防火管理者・自衛消防組織に加えて、大地震などに備えた防災管理者を置く必要がある。","入退室管理システムには、緊急避難のときに電気錠を一斉に開ける機能をもたせる必要がある。"],"a":1,"e":"人などが出す熱(赤外線)の変化を感じて作動するのはパッシブセンサである。アクティブセンサは、自ら赤外線を出し、その光がさえぎられたことで検知する。","l":"法令外","c":""},{"id":"2025-103","s":3,"q":"建築基準法の建築物の制限について、最も不適当なものはどれか。","o":["建築面積は、壁・柱などの内側で囲まれた部分の水平投影面積で求める。","敷地面積は、土地の高低差に関係なく、水平投影面積で求める。","建蔽率とは、建築面積を敷地面積で割った比である。","容積率とは、建築物の延べ面積を敷地面積で割った比である。","建築物の高さの制限として、北側高さ制限がある。"],"a":0,"e":"建築面積は、壁・柱などの「中心線」で囲まれた部分の水平投影面積で求める。","l":"建築基準法施行令 第2条第1項第2号","c":""},{"id":"2025-104","s":3,"q":"建築物に関係する法令について、最も不適当なものはどれか。","o":["消防法の特定防火対象物では、消防用設備等の設置・維持の規定が適用されるのは新しく建てる建物だけである。","高さ31mを超える高層建築物の管理者は、消防法の防火管理者を定め、消防計画をつくる。","バリアフリー法(高齢者、障害者等の移動等の円滑化の促進に関する法律)でいう建築物特定施設には、出入口・階段・便所がある。","建築主は、バリアフリー法の2,000m²以上の特別特定建築物を建てるときは、建築物移動等円滑化基準に適合させなければならない。","耐震改修促進法でいう耐震改修とは、地震への安全性を高めるために、増築・改築・修繕・模様替・一部の除却・敷地の整備をすることをいう。"],"a":0,"e":"特定防火対象物では、既存の建物にも現行の消防用設備等の基準が適用される(遡って適用される)。","l":"消防法 第17条の2の5","c":""},{"id":"2025-105","s":3,"q":"建築物の管理と空調技術について、最も不適当なものはどれか。","o":["クール・ヒートトレンチシステムとは、外気と地中の温度差を利用して、外気による負荷を減らす方法である。","ナイトパージとは、夜間の外気を取り入れて、空調機の冷房負荷を減らすものである。","放射空調は、温度ムラによる不快感が起こりにくい。","BCPとは、設備の経年劣化に対する保全計画のことである。","ファシリティマネジメントは、コストと品質の最適なバランスを目指すものである。"],"a":3,"e":"BCP(事業継続計画)は、災害や事故が起きても重要な業務を続けたり早く再開したりするための計画である。","l":"法令外","c":""},{"id":"2025-106","s":4,"q":"給水・排水の管理で使う用語と、その単位の組合せとして、最も不適当なものはどれか。","o":["濁度 ― 度","腐食速度 ― mm/年","陰イオン界面活性剤 ― mg/L","BOD容積負荷 ― g/(m³・人)","精密ろ過膜の有効径 ― μm"],"a":3,"e":"BOD容積負荷の単位は kg/(m³・日) で、「人」あたりではない(2022年問106でも kg/(m³・日) が正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2025-107","s":4,"q":"給水・排水に関する用語と説明の組合せとして、最も不適当なものはどれか。","o":["阻集器 ― 排水管を詰まらせる異物を分けて集めるための設備","逃し通気管 ― 排水系統内の下水ガスの臭いを取り除くための管","膨張管 ― 給湯配管系統の安全装置","水封式トラップ ― 封水で排水管内の悪臭などが室内に入るのを防ぐ装置","FRP ― ガラス繊維で強化したプラスチック"],"a":1,"e":"逃し通気管は臭気を除くための管ではない。排水管内の圧力変動をやわらげ、空気の流れを助けるための通気管である(2022年問129では結合通気管を「圧力変動を緩和する逃し通気管」と説明した記述が正しいとされている)。","l":"法令外","c":""},{"id":"2025-108","s":4,"q":"給水・排水に関する用語と説明の組合せとして、最も不適当なものはどれか。","o":["活性汚泥 ― 主に好気性微生物が集まったもの","クリープ劣化 ― 合成樹脂に力がかかり続けることで起こる材料の変形","スケール障害 ― トリハロメタンができること","青水 ― 銅イオンが溶け出すこと","ファージ ― 細菌を宿主細胞とするウイルスの総称"],"a":2,"e":"スケールとは炭酸カルシウムや炭酸マグネシウムなどが析出したもの(2017年問107・2023年問107で正しい組合せとして出題)。トリハロメタンの生成とは関係がない。","l":"法令外","c":""},{"id":"2025-109","s":4,"q":"水道に関する記述として、最も不適当なものはどれか。","o":["水道の目的は、きれいな水を豊富に、かつ安く供給することである。","水道水は飲み水だけでなく、洗面・風呂・水洗便所・清掃・噴水・散水など、さまざまな用途に使われる。","水道の規模は、目標年次の1日給水量の年間最大値をもとに計画される。","配水管から給水管が分かれる箇所では、配水管の最小動水圧として100kPa程度を確保する。","日本の水道普及率は、令和4年度時点で98%を超えている。"],"a":3,"e":"配水管から給水管を分岐する箇所の最小動水圧は150kPa以上を確保する(2016年問107・2023年問109で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-110","s":4,"q":"水道に関する記述として、最も不適当なものはどれか。","o":["水道事業とは、一般の需要に応じて水道で水を供給する事業で、計画上の給水人口が101人以上のものをいう。","簡易専用水道とは、水道事業の水道から受ける水だけを水源とし、水槽の有効容量の合計が10m³以下のものをいう。","上水道事業とは、一般に計画給水人口が5,001人以上の水道事業をいう。","専用水道には、寄宿舎などの自家用水道で、100人を超える人に居住に必要な水を供給するものが含まれる。","給水装置とは、需要者に水を届けるため、水道事業者が設けた配水管から分かれた給水管と、これに直結する給水用具をいう。"],"a":1,"e":"簡易専用水道から除かれるのは水槽の有効容量の合計が10m³以下のもので、簡易専用水道は10m³を超えるものをいう(水道法第3条第7項、水道法施行令第2条)。","l":"水道法 第3条、水道法施行令 第2条","c":""},{"id":"2025-111","s":4,"q":"給水設備の貯水槽に関する記述として、最も不適当なものはどれか。","o":["木製の貯水槽は断熱性能が低いので、結露対策が必要である。","ステンレス鋼板製の貯水槽は、気相部(水面より上の部分)の腐食対策が必要である。","鋼板製の貯水槽には、一体成型した槽にエポキシ樹脂を焼き付けてコーティングしたものがある。","FRP製の貯水槽は機械的強度が低いため、耐震補強が必要である。","FRP製の高置水槽は、槽内の照度が100lx以上になると、光合成で藻類が増えやすい。"],"a":0,"e":"木製貯水槽は断熱性に優れている(2023年問110で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-112","s":4,"q":"給水設備の配管材料と、その接合方法の組合せとして、最も不適当なものはどれか。","o":["水道用硬質塩化ビニルライニング鋼管 ― ねじ接合(管端防食継手を使う場合)","硬質ポリ塩化ビニル管 ― 接着接合","ステンレス鋼管 ― 溶接接合","架橋ポリエチレン管 ― 接着接合","銅管 ― 差込みろう接合"],"a":3,"e":"架橋ポリエチレン管は接着接合ではなく、メカニカル形接合などで接合する(2023年問113で「メカニカル形接合」が正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2025-113","s":4,"q":"給水設備で使う弁の説明として、最も不適当なものはどれか。","o":["仕切弁 ― 弁体が管路を垂直に仕切るようにして開け閉めする構造","バタフライ弁 ― 円筒形の弁本体の中心に円板状の弁体があり、これを回して管路を開け閉めする構造","減圧弁 ― ダイヤフラムと調節ばねのつり合いで弁体の開き具合を調整する仕組み","定水位弁 ― 副弁の開閉に合わせて弁体を開閉し、水槽の水位を保つ仕組み","ボール弁 ― 弁本体が球形で、弁体を弁座に押し付けて管路をふさぐ構造"],"a":4,"e":"ボール弁の説明が誤り。弁体と弁座のすき間を変えて流量を調節するのは玉形弁の特徴である(2017年問77で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-114","s":4,"q":"建築物の給水方式に関する記述として、最も不適当なものはどれか。","o":["直結増圧方式には、増圧ポンプを直列に複数つなぐ直列多段型がある。","高置水槽方式は、安定した水圧と水量が得られる。","直結増圧方式は、引込み管の管径に制限がある。","ポンプ直送方式は、流量や圧力を検知して、必要な水量に合わせて送水する。","高置水槽方式は、ほかの給水方式と比べて水質汚染の可能性が低い。"],"a":4,"e":"高置水槽方式は水槽を経由するため、ほかの方式より水質汚染の可能性が低いとはいえない(2017年問110・2020年問112でも「可能性が低い」は誤りの記述として扱われている)。","l":"法令外","c":""},{"id":"2025-115","s":4,"q":"給水設備に関する記述として、最も不適当なものはどれか。","o":["節水器具を使う事務所ビルの1日あたり設計給水量は、40〜60L/人である。","給水配管の管径は、管内の流速が2.0m/s以下になるように選ぶ。","衛生器具による節水方法の一つに、小便器の自動感知洗浄システムがある。","水資源を有効に使うため、雨水を便器の洗浄水に利用する。","高層ホテルの上限給水圧力は、0.7MPaである。"],"a":4,"e":"高層ホテルのゾーニングにおける給水の上限水圧は0.3MPaである(2023年問112で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-116","s":4,"q":"給水設備の汚染に関する記述として、最も不適当なものはどれか。","o":["逆サイホン作用とは、給水管内にできた負圧によって、いったん水受け容器に出た水が給水管に逆流することである。","クロスコネクションとは、飲料水の系統とほかの配管系統を、配管などで直接つなぐことである。","洗面器の吐水口空間とは、給水栓の吐水口から洗面器のあふれ縁までの垂直距離である。","散水用の水栓の上流側には、一般に大気圧式バキュームブレーカを設ける。","上水の配管から消火系統へ水を補給するときは、消火用補助水槽を設けて行う。"],"a":3,"e":"大気圧式バキュームブレーカは、常に圧力がかかる配管部分には設置できない(2022年問111で「常時圧力がかかる部分に設置する」が誤りとされている)。散水栓の上流側は常に圧力がかかる位置なので不適当。","l":"法令外","c":""},{"id":"2025-117","s":4,"q":"ポンプの点検項目のうち、点検の頻度を一般に6か月に1回程度としているものはどれか。","o":["吐出側の圧力","ポンプと電動機の芯狂い(軸のずれ)","振動・騒音","電流値","軸受の温度"],"a":1,"e":"ポンプと電動機の芯狂い(軸心のずれ)の点検は、一般に6か月に1回程度とされている。","l":"法令外","c":""},{"id":"2025-118","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["業務用の皿洗い機のすすぎに使う給湯の温度は、70〜80℃である。","ライニング鋼管に単式の伸縮管継手を設ける間隔は、50m程度とする。","総合病院で使う湯の量は、100〜200L/(床・日)程度である。","架橋ポリエチレン管の使用温度は、95℃以下とする。","循環式給湯設備で下向き配管方式とする場合、給湯横主管は1/200以上の下り勾配とする。"],"a":1,"e":"ライニング鋼管の単式伸縮管継手の設置間隔を50m程度とするのは誤り(2020年問118でも同じ記述が誤りとして出題)。","l":"法令外","c":""},{"id":"2025-119","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["業務用厨房のように連続して湯を使う給湯枝管には、返湯管を設けないことが多い。","貯湯槽の容量が小さいと、加熱装置の起動・停止の回数が多くなる。","エネルギーと水を節約するため、湯と水を別々の水栓から出すのではなく、混合水栓を使う。","中央式給湯方式の循環ポンプは、給湯主管に設置する。","加熱装置から逃し管を立ち上げるときは、水を供給する高置水槽の水面よりも高く立ち上げる。"],"a":3,"e":"中央式給湯方式の循環ポンプは、給湯主管ではなく返湯管に設置する(2016年問120で「ポンプは返湯管に設置する」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-120","s":4,"q":"給湯設備に関する記述として、最も不適当なものはどれか。","o":["強制循環方式では、湯を均等に循環させるため、リバースリターン方式にする。","密閉式膨張水槽を設けるときは、逃し弁を設ける。","給湯循環ポンプの循環流量は、循環配管系などからの熱損失と、加熱装置の給湯温度と返湯温度の差から計算する。","自動空気抜き弁は、配管内の湯に溶けている空気を抜くため、圧力の低い場所に設置する。","給湯循環ポンプは、背圧に耐えられるものを選ぶ。"],"a":0,"e":"強制循環方式では、必ずしもリバースリターン方式にする必要はない。湯を均等に循環させるには、返湯管に定流量弁を設ける方法がある(2021年問123・2023年問119で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-121","s":4,"q":"給湯設備で扱う水の性質に関する記述として、最も不適当なものはどれか。","o":["4℃以上の水は、温度が上がると密度が小さくなる。","配管内の水に溶ける気体の量(溶解度)は、水温が上がると増える。","15℃の水の比熱は、4.186kJ/(kg・℃)である。","水に溶けている空気は、配管内の圧力が高いと分離しにくい。","水温が高いほど、金属が腐食する速度は速くなる。"],"a":1,"e":"水中の気体の溶解度は、水温が上がると減少する(2016年問117・2024年問118で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-122","s":4,"q":"給湯設備の加熱装置に関する記述として、最も不適当なものはどれか。","o":["ガス瞬間湯沸器には、給湯のほかにセントラルヒーティング用の回路を組み込んだものがある。","給湯用の貫流ボイラは水管群でできていて、耐圧性に優れている。","無圧式温水発生機は、缶体の中を大気圧以下にし、熱媒水を蒸発させて内部の熱交換器で熱交換し、湯を供給する。","加熱コイル付き貯湯槽は、蒸気などの熱源が得られる場合に使われる。","ガスマルチ式給湯機は、小型の瞬間湯沸器を何台もつないでユニットにしたものである。"],"a":2,"e":"缶体内を大気圧より低く保って水を沸騰させるのは真空式温水発生機の説明である(2024年問123で正しい記述として出題)。無圧式温水発生機の説明としては誤り。","l":"法令外","c":""},{"id":"2025-123","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["給湯水からレジオネラ属菌が見つかった場合の対策として、高濃度の塩素で系統内を消毒する方法がある。","SUS444製の貯湯槽には、腐食を防ぐために電気防食を施す。","給湯設備には、給水設備に準じた保守管理が必要である。","給湯水を均等に循環させるため、返湯管に定流量弁を設ける。","ベローズ形の伸縮管継手は、ベローズの疲労破壊によって水漏れすることがある。"],"a":1,"e":"SUS444製の貯湯槽には電気防食を施してはならない(2020年問123で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-124","s":4,"q":"給湯設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["給湯循環ポンプは、作動の確認をかねて分解・清掃を行う。","自動空気抜き弁から水漏れがある場合は、分解・清掃を行う。","貯湯槽に流電陽極式の電気防食を施す場合は、外部電源が必要である。","逃し弁は、レバーハンドルを操作して作動を確認する。","配管系統の末端で定期的に滞留水を排出し、温度を測る。"],"a":2,"e":"流電陽極式は犠牲陽極を使う方式で、外部電源は使わない。そのため点検では犠牲陽極の消耗(腐食)状態を調べる(2024年問124で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-125","s":4,"q":"雑用水設備に関する記述として、最も不適当なものはどれか。","o":["排水再利用設備は、循環のしかたによって、個別循環方式・地区循環方式・広域循環方式に分けられる。","雑用水の原水には、1年を通して安定して確保できる排水を優先して使う。","散水・修景・清掃用水として使う場合、雑用水受水槽は6面点検ができるように設置することが望ましい。","建築物衛生法では、雑用水の水質基準の項目として浮遊物質(SS)が定められている。","上水管・雑用水管・給湯管などを並べて配管するときは、配管の並び順を途中で変えない。"],"a":3,"e":"建築物衛生法の雑用水の基準項目は、pH値・臭気・外観・大腸菌・濁度(散水・修景・清掃用)と遊離残留塩素で、浮遊物質(SS)は入っていない(施行規則第4条の2)。","l":"建築物衛生法施行規則 第4条の2","c":""},{"id":"2025-126","s":4,"q":"雑用水の処理設備で、色度(水の色)を取り除くのに使われる装置として、最も適当なものはどれか。","o":["沈砂槽","生物処理槽","膜分離装置","ろ過装置","活性炭処理装置"],"a":4,"e":"色度の除去には活性炭処理装置が使われる。","l":"法令外","c":""},{"id":"2025-127","s":4,"q":"排水の水質に関する記述として、最も不適当なものはどれか。","o":["透視度は、水がどれだけ澄んでいるかを示す指標である。","溶存酸素(DO)は、水中に溶けている分子状の酸素である。","生物化学的酸素要求量(BOD)は、主に有機物が酸化剤で酸化されるときに使われる酸素の量である。","全窒素は、有機性窒素・アンモニア性窒素・亜硝酸性窒素・硝酸性窒素を合計したものである。","大腸菌は、ふん便による汚染があるかどうかを判断する指標である。"],"a":2,"e":"BODは、主に水中の有機物が好気性微生物によって分解されるときに使われる酸素の量である(2023年問126で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-128","s":4,"q":"排水通気配管に関する記述として、最も不適当なものはどれか。","o":["器具排水管から各個通気管を取り出すときは、トラップのウェアから管径の2倍以上離れた位置で取り出す。","結合通気管は、高層建築でブランチ間隔10以上の排水立て管に、最上階から数えてブランチ間隔10以内ごとに設ける。","通気立て管の上部は、最も低い位置にある衛生器具のあふれ縁より150mm以上高い位置で、伸頂通気管につなぐ。","通気管の末端を窓や換気口などの近くで大気に開放するときは、窓・換気口の上端から600mm以上立ち上げて開口する。","伸頂通気方式では、排水立て管と排水横主管の接続に大曲がりベンドなどを使う。"],"a":2,"e":"通気立て管の上部は、最高位(最も高い位置)の衛生器具のあふれ縁から150mm以上高い位置で伸頂通気管に接続する(2016年問128・2024年問131で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-129","s":4,"q":"雨水排水設備に関する記述として、最も不適当なものはどれか。","o":["雨水ますの底には、150mm以上の泥だめを設ける。","雨水ますの流出管は、流入管より管底を20mm以上下げて設ける。","雨水排水管を合流式の敷地排水管につなぐときは、トラップますを設けて、ルーフドレンからの悪臭を防ぐ。","ルーフドレンのストレーナの開口面積は、つながる雨水排水管と同じ面積にする。","雨水浸透施設は、透水性舗装・浸透ます・浸透トレンチなどで構成される。"],"a":3,"e":"ルーフドレンのストレーナ部分の開口面積は、接続する排水管の断面積の2倍程度が必要である(2023年問128・2024年問129で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-130","s":4,"q":"排水通気設備に関する記述として、最も不適当なものはどれか。","o":["伸頂通気方式の排水横主管の水平曲がりは、排水立て管の底部から3m以内に設けてはならない。","排水立て管のオフセット部の上下600mm以内には、排水横枝管を設けてはならない。","飲料用水槽で、管径100mmの間接排水管に設ける排水口空間は、最小150mmとする。","排水槽の底の勾配は、吸込みピットに向かって1/15以上1/10以下とする。","自然流下式の排水横管の勾配は、管内の最小流速が2.0m/sになるように設ける。"],"a":4,"e":"自然流下式の排水横管の勾配は、管内流速が0.6〜1.5m/sになるように設ける(2020年問132・2023年問132で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-131","s":4,"q":"排水管の掃除口と排水ますに関する記述として、最も不適当なものはどれか。","o":["排水管の管径が100mmのとき、掃除口の口径は100mmとする。","排水ますの大きさは、配管を埋める深さ、つながる配管の大きさと本数、点検のしやすさなどを考えて決める。","排水横管に設ける掃除口の間隔は、管径100mm以下の場合15m以内とする。","敷地排水管の直管が長い場合、排水ますは管内径の150倍程度の間隔で設ける。","汚水や雑排水には、底に溝(インバート)のある排水ますを使う。"],"a":3,"e":"敷地排水管の直管が長い場合、排水ますは管内径の120倍を超えない範囲に設置する(2021年問132・2023年問130などで正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-132","s":4,"q":"排水設備と排水管の材料に関する記述として、最も不適当なものはどれか。","o":["排水ポンプは、排水槽の吸込みピットの壁面から100mm程度離して設置する。","排水用硬質塩化ビニルライニング鋼管の接続には、排水鋼管用可とう継手を使う。","トラップが組み込まれていない阻集器には、出口側にトラップを設ける。","厨房用の排水槽から排水を取り除くには、汚物ポンプを使う。","繊維くず阻集器には、網の目が13mm程度のバスケットストレーナを設ける。"],"a":0,"e":"排水ポンプは、吸込みピットの壁面から200mm以上離して設置する(2016年問130・2023年問131などで正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-133","s":4,"q":"排水通気設備に関する語句の組合せとして、最も不適当なものはどれか。","o":["排水トラップの深さ ― ディップからウェアまでの垂直距離","各個通気方式 ― トラップの自己サイホン作用を防ぐ","太陽熱給湯装置の排水管 ― 排水口開放による間接排水","トラップの封水強度 ― 排水管内に正圧や負圧が生じたときに封水を保つ能力","通気口の通気率 ― 管の断面積に対する通気口の開口面積の割合"],"a":2,"e":"(3)の組合せが誤り。","l":"法令外","c":""},{"id":"2025-134","s":4,"q":"排水管の清掃と診断に関する記述として、最も不適当なものはどれか。","o":["高圧洗浄法による排水管の清掃では、10〜20MPaの圧力の水を噴射して洗う。","スネークワイヤを使うワイヤ式清掃法を排水横管に使う場合、長さ25m程度が限界である。","排水管内の詰まり具合や腐食の状態は、内視鏡や超音波厚さ計などで確認する。","空気圧洗浄法による排水管の清掃では、0.1MPa程度の空気圧を管内に放出し、その衝撃波で詰まりを取り除く。","小便器の排水管に付いた尿石を取り除くには、酸性洗浄剤を使う。"],"a":3,"e":"(4)の記述が誤り。","l":"法令外","c":""},{"id":"2025-135","s":4,"q":"排水設備の保守管理の内容と、その実施頻度の組合せとして、最も不適当なものはどれか。","o":["グリース阻集器の槽内の底や壁面に付いたグリースの清掃 ― 1か月に1回","排水ポンプの絶縁抵抗の測定 ― 3か月に1回","排水槽の清掃 ― 6か月以内に1回","排水ポンプのメカニカルシールの交換 ― 1〜2年に1回","通気管の点検 ― 1年に1回"],"a":1,"e":"排水ポンプの絶縁抵抗の測定は1か月に1回行う(2023年問134で正しい記述として出題)。なお排水設備の清掃を6か月以内ごとに1回行うことは施行規則第4条の3で定められている。","l":"建築物衛生法施行規則 第4条の3(選択肢3)","c":""},{"id":"2025-136","s":4,"q":"衛生器具設備に関する記述として、最も不適当なものはどれか。","o":["小便器の洗浄水量は、JIS A 5207:2022で、Ⅱ形が4.0L以下と区分されている。","大便器の洗浄弁式は、給水管の水を直接便器に送る方式で、続けて使うことができる。","高断熱浴槽は、JIS A 1718:2011の高断熱試験で、4時間での温度低下が2.5℃以内という保温性能をもつ。","大便器洗浄弁に必要な水圧は、70kPaである。","事務所やホテルなど不特定の人が使う建物では、洗面器の水栓に、触れずに開閉できる自動水栓が使われる。"],"a":0,"e":"小便器Ⅱ形の洗浄水量の区分を4.0L以下とした記述が誤り。","l":"法令外(JIS A 5207)","c":""},{"id":"2025-137","s":4,"q":"浄化槽法で定める浄化槽の定義について、次の文の【 】内の語句のうち、誤っているものはどれか。\n「【(1)便所】と連結して、し尿とこれに併せて【(2)雨水】を処理し、下水道法の終末処理場をもつ公共下水道以外に放流するための【(3)設備又は施設】であって、同法の公共下水道と【(4)流域下水道】、ならびに廃棄物処理法の計画に従って市町村が設置した【(5)し尿処理施設】以外のものをいう。」","o":["便所","雨水","設備又は施設","流域下水道","し尿処理施設"],"a":1,"e":"浄化槽がし尿と併せて処理するのは「雑排水」である。雑排水からは工場廃水や雨水などの特殊な排水は除かれている(浄化槽法第2条第1号)。","l":"浄化槽法 第2条第1号","c":""},{"id":"2025-138","s":4,"q":"処理対象人員101〜500人の浄化槽について、下の図の処理の流れ(フローシート)の【ア】〜【ウ】に入る装置の組合せとして、最も適当なものはどれか。","o":["ア:流量調整槽 ― イ:沈殿槽 ― ウ:汚泥濃縮貯留槽","ア:流量調整槽 ― イ:沈殿槽 ― ウ:汚泥貯留槽","ア:沈殿分離槽 ― イ:沈砂槽 ― ウ:汚泥濃縮貯留槽","ア:沈殿分離槽 ― イ:沈殿槽 ― ウ:汚泥貯留槽","ア:流量調整槽 ― イ:沈砂槽 ― ウ:汚泥貯留槽"],"a":0,"e":"スクリーンの後で流入量をならすのが流量調整槽、生物反応槽の後で汚泥を沈めて水と分けるのが沈殿槽である。ウは汚泥を受けて濃縮し、分かれた脱離液をアへ戻しているので、汚泥濃縮貯留槽が入る。","l":"法令外","c":"","g":["img/2025-138.png"]},{"id":"2025-139","s":4,"q":"特殊設備に関する記述として、最も不適当なものはどれか。","o":["水景施設へ上水系統から補給する水は、必ず吐水口空間を設けて間接的に給水する。","水景施設の維持管理では、貯水部や流水部の底や側壁にたまった・付いた汚泥などの除去も必要である。","厨房機器の材質は、水を吸わず、耐水性と耐食性があるものにする。","オーバーフロー方式の浴槽循環ろ過設備では、循環水を浴槽の水面より高い位置から浴槽に入れる。","プールの循環ろ過の取水口には、吸い込み事故を防ぐための安全対策をする。"],"a":3,"e":"浴槽の循環水は、水面より高い位置からではなく、浴槽の底部に近い部分から供給する(2024年問138で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-140","s":4,"q":"防火設備と消防用設備の保守管理に関する記述として、最も不適当なものはどれか。","o":["消防法で定められた消防用設備は、火災のときに確実に起動し、求められる性能を発揮する必要がある。","特定防火対象物では、法定定期点検の結果と不備の是正措置の報告は1年に1回である。","消防用設備などに付いている自家発電装置は、6か月に1回「機器点検」を行う。","防火管理者は日常点検として消防用設備の異常信号などを確認し、異常があればすぐに修理して機能を回復させる。","非特定防火対象物では、法定定期点検の結果と不備の是正措置の報告は5年に1回である。"],"a":4,"e":"非特定防火対象物の点検結果の報告は3年に1回である(消防法施行規則第31条の6第3項。特定防火対象物は1年に1回)。","l":"消防法施行規則 第31条の6第3項","c":""},{"id":"2025-141","s":5,"q":"建築物衛生法での清掃の目的について述べた次の文のうち、最も不適当なものはどれか。","o":["人体に害のある汚染物質を人の活動空間から取り除き、衛生的な環境を保つことである。","きれいさや快適さを保つことである。","物の機能を回復させたり、長持ちさせたりすることである。","汚染物質をきちんと取り除くことで、事故や設備の不具合を防ぎ、安全を確保することである。","建築物の用途に関係なく、清掃の目的の重点の置き方は同じである。"],"a":4,"e":"病院、ホテル、事務所など建築物の用途によって、衛生・美観・安全のどれを重視するかは変わる。用途に関係なく同じではない。","l":"法令外","c":""},{"id":"2025-142","s":5,"q":"「建築物における維持管理マニュアル」(平成20年1月25日 健衛発第0125001号)に示された作業手順書の項目として、最も不適当なものはどれか。","o":["対象作業項目","作業内容","使用する清掃資機材の種類と数量","作業時間","最終点検"],"a":3,"e":"この選択肢が誤り。このマニュアルに示された作業手順書の項目に「作業時間」は含まれていない。","l":"法令外(建築物における維持管理マニュアル 平成20年健衛発第0125001号)","c":""},{"id":"2025-143","s":5,"q":"建築物清掃の作業計画について述べた次の文のうち、最も適当なものはどれか。","o":["窓台の除じんは、定期清掃で行う。","廊下の壁にあるスイッチまわりの洗剤拭きは、日常清掃で行う。","エレベーターかご内の除じんは、定期清掃で行う。","トイレ・洗面所の換気口の除じんは、日常清掃で行う。","流し台の洗浄は、定期清掃で行う。"],"a":0,"e":"窓台の除じんは定期清掃の作業として扱う。エレベーターかご内の除じんや流し台の洗浄は毎日行う日常清掃、スイッチまわりの洗剤拭きや換気口の除じんは定期清掃にあたる。","l":"法令外","c":""},{"id":"2025-144","s":5,"q":"建築物清掃のスケジュール管理について述べた次の文のうち、最も不適当なものはどれか。","o":["日常作業や定期作業の予定を、決められた時間内にやり遂げることである。","月間作業予定表は、定期清掃の人員配置をもとに予定を立てる。","従事者の増減、建築物内の工事などによる使用状況の変化、テナントの事情などを考えて作成する。","スケジュール管理では、時間の管理に重点がおかれている。","月間の作業実施記録をとる。"],"a":1,"e":"この記述が誤り。","l":"法令外","c":""},{"id":"2025-145","s":5,"q":"建築物清掃管理の評価について述べた次の文のうち、最も不適当なものはどれか。","o":["作業品質のよしあしは、基本的に仕様の多い少ないによって左右される。","組織品質は、事業所管理品質と現場管理品質の2つでできている。","事業所管理品質では、教育訓練やインスペクションの実施、現場への適切な指導などが確立しているかが評価される。","品質評価項目のうち安全衛生は、事業所管理品質に含まれる。","従事者の作業態度、服装・身だしなみ、あいさつなど、人の気持ちに働きかける項目も大切な品質要素である。"],"a":3,"e":"安全衛生は現場で日々守られているかを見る項目なので、事業所管理品質ではなく現場管理品質に含まれる。","l":"法令外","c":""},{"id":"2025-146","s":5,"q":"作業改善に役立つ問題解決の手順「QCストーリー」の項目として、最も不適当なものはどれか。","o":["現状の把握","目標の設定","活動計画の作成","要因の解析","仕様変更の要望"],"a":4,"e":"QCストーリーは、現状把握→目標設定→活動計画→要因解析→対策→効果確認→標準化という自分たちで改善する手順で、「仕様変更の要望」は含まれない。","l":"法令外","c":""},{"id":"2025-147","s":5,"q":"ほこりの除去について述べた次の文のうち、最も不適当なものはどれか。","o":["備品などに付いたわずかなほこりは、乾いた柔らかい綿布などで拭けば簡単に取れる。","布などの清掃用具にほこりを効率よく付けるには、付着力を高める物質を布に含ませる。","床に水を含ませたおがくずをまいて掃き取る方法は、ほこりを付着させる効果が大きい。","バキュームクリーニングは、カーペットの織り目に入り込んだほこりなどを取るのに使う。","ほこりは、長い間放置しても取りやすさは変わらない。"],"a":4,"e":"ほこりは長く放置すると湿気や油分などで固着し、取りにくくなる。早めに除去することが大切。","l":"法令外","c":""},{"id":"2025-148","s":5,"q":"ビルクリーニング用の器具について述べた次の文のうち、最も不適当なものはどれか。","o":["凹凸のある床は、ブラシを床磨き機に付けて洗う。","化学繊維のマイクロファイバー製ダストモップは、油剤を使わなくてもほこりを吸着して取れる。","自在ぼうきは、ほこりを舞い上げることが少ないので、おもに室内で使う。","改良ちり取り(文化ちり取り)は、移動するときにごみがこぼれないので、拾い掃きに向いている。","床維持剤を塗るためのフラット型モップは、房が壁に当たるので、壁や幅木を汚しやすい。"],"a":4,"e":"フラット型モップは房が平らにまとまっていて壁や幅木に当たりにくく、汚しにくいのが特徴である。","l":"法令外","c":""},{"id":"2025-149","s":5,"q":"洗剤に関する組合せのうち、最も不適当なものはどれか。","o":["界面活性剤 ― 対象物をぬらし、中にしみ込む作用がある","リン酸塩を含む洗剤 ― 湖や沼の富栄養化が進む","酸性洗剤 ― 油脂分を含む汚れを落とす","床の表面洗剤 ― 泡立ちが少ない","樹脂ワックスの剥離剤 ― 皮膚を傷める危険性が高い"],"a":2,"e":"油脂分を含む汚れにはアルカリ性洗剤が向く。酸性洗剤は尿石や水あかなど無機質の汚れを落とすのに使う。","l":"法令外","c":""},{"id":"2025-150","s":5,"q":"弾性床材の特徴と維持管理について述べた次の文のうち、最も適当なものはどれか。","o":["クッション性にすぐれたコルク床は、弾性床材に分類される。","リノリウム床材のフロアポリッシュは、アルカリ性の剥離剤で取り除く。","床維持剤を塗れば、土砂やほこりを取る作業の回数を減らせる。","塩化ビニルシートは、床維持剤の密着性がよい。","塩化ビニル系床材は、薬品や水に強い。"],"a":4,"e":"塩化ビニル系床材は耐薬品性・耐水性にすぐれる。リノリウムはアルカリに弱いのでアルカリ性剥離剤は使わない。床維持剤を塗っても土砂・ほこりの除去回数は減らせない。","l":"法令外","c":""},{"id":"2025-151","s":5,"q":"繊維床材の特徴と維持管理について述べた次の文のうち、最も適当なものはどれか。","o":["ポリプロピレン素材は耐久性が高い。","アクリル素材は、親水性の汚れが取れにくい。","ウィルトンカーペットは、ぬれると縮みやすい。","スポットクリーニングとは、通行量の多い共用部を掃除機で吸い取る作業である。","しみ取り作業は、定期清掃で行う。"],"a":2,"e":"ウィルトンカーペットは天然繊維などを使うことが多く、ぬれると収縮しやすいので水の使い方に注意する。しみはつきしだい日常的に取るのが基本。","l":"法令外","c":""},{"id":"2025-152","s":5,"q":"硬性床材の特徴と維持管理について述べた次の文のうち、最も不適当なものはどれか。","o":["セラミックタイルは吸水性が低い。","大理石は硬いので、土砂による摩耗は少ない。","油分をしみ込ませたダストモップは使わない。","残った洗剤分をできるだけ取り除くため、洗浄後は吸水式真空掃除機などで回収する。","目地のセメントモルタルは、酸性洗剤で傷みやすい。"],"a":1,"e":"大理石は比較的柔らかく、土砂で傷つき摩耗しやすい。また酸にも弱い。","l":"法令外","c":""},{"id":"2025-153","s":5,"q":"床維持剤のドライメンテナンス法について述べた次の文のうち、最も不適当なものはどれか。","o":["ウェットメンテナンス法より部分補修がしやすい。","前に進む作業が中心となるので、作業の安全性が高い。","一定期間を通した平均的な美観の度合いが高い。","ドライバフ法で使う床磨き機は、回転数が高いとフロアポリッシュの皮膜を傷めるので、低速で使う。","スプレーバフ法は、つや出し作用のある液を吹き付けながら、専用パッドを付けた超高速床磨き機で床を磨く方法である。"],"a":3,"e":"ドライバフ法は、高速で回る床磨き機で皮膜を磨いてつやを戻す方法で、回転数が高いほど効果が出る。低速で使うのではない。","l":"法令外","c":""},{"id":"2025-154","s":5,"q":"床以外の清掃作業について述べた次の文のうち、最も不適当なものはどれか。","o":["照明器具はほこりが付きやすいが、日常清掃で行う必要はない。","玄関ホールのフロアマットの管理のよしあしは、建築物全体に影響する。","トイレは汚れや材質がさまざまなので、それに合った作業方法と清掃用資材を選ぶ。","階段の壁は、ほかの場所よりほこりが付きやすい。","エレベーターは狭い空間なので、土砂の持ち込みやほこりの付着は少ない。"],"a":4,"e":"エレベーターは多くの人が出入りし、狭い空間に土砂が集中して持ち込まれるため汚れやすい。","l":"法令外","c":""},{"id":"2025-155","s":5,"q":"外装の清掃について述べた次の文のうち、最も不適当なものはどれか。","o":["ゴンドラによる外壁清掃では、厚生労働省令のゴンドラ安全規則を必ず守らなければならない。","ロープ高所作業を行う場合、労働安全衛生規則による特別教育の実施は努力義務である。","石材や陶磁器タイルの壁は、数年に1回の頻度で洗う。","田園地帯にある金属製の外壁は、1年に1回の頻度で洗う。","ガラスは、1〜2か月に1回の頻度で洗う。"],"a":1,"e":"ロープ高所作業は、労働安全衛生規則第36条第40号で特別教育が必要な業務に定められており、努力義務ではなく義務である。","l":"労働安全衛生規則 第36条第40号","c":""},{"id":"2025-156","s":5,"q":"建築物の衛生管理と消毒について述べた次の文のうち、最も不適当なものはどれか。","o":["清掃でほこり、汚れ、廃棄物、汚物などを取り除くことは、消毒の前処理として重要である。","清掃の衛生管理の基本はゾーニング管理で、使う清掃用具を区域ごとに分けて作業する。","ノロウイルスは、汚染された食品や、ふん便・吐いた物を通じて感染する。","ノロウイルス感染で吐いたと思われる場合は、吐いた物をふき取り、その部分を含む広い範囲を消毒する。","ノロウイルスに対して消毒効果が高い消毒薬として、第四級アンモニウム塩がある。"],"a":4,"e":"第四級アンモニウム塩(逆性石けん)はノロウイルスにはほとんど効かない。ノロウイルスには次亜塩素酸ナトリウムなどを使う。","l":"法令外","c":""},{"id":"2025-157","s":5,"q":"日本のごみ(令和4年度)と産業廃棄物(令和3年度)の排出・処理の状況について述べた次の文のうち、最も不適当なものはどれか。","o":["ごみの総排出量のうち、約70%が家庭系ごみ、約30%が事業系ごみである。","ごみの総資源化量は、市町村の直接資源化量に、住民団体による集団回収量も加えて集計している。","ごみの中間処理量のうち、約50%が直接焼却されている。","産業廃棄物の排出量を種類別に見ると、汚泥が最も多い。","産業廃棄物の総排出量の約2%が最終処分されている。"],"a":2,"e":"この記述が誤り(直接焼却の割合は約50%ではない)。統計の数字は年度で変わるので、問題文の年度の値として覚える。","l":"法令外(環境省の統計)","c":""},{"id":"2025-158","s":5,"q":"リサイクルを進めるための個別の法律と建築物内廃棄物の管理について述べた次の文のうち、法律上最も不適当なものはどれか。","o":["建築物内のテナントが家庭用エアコンを買い替えるとき、テナントの業者が小売業者にリサイクル料金を払い、古いエアコンを引き取ってもらった。","建築物内のテナントが事業活動で出たペットボトルを捨てるとき、容器包装リサイクル法にもとづく容器包装廃棄物として、自治体の資源回収に出した。","建築物内のテナントが携帯電話を捨てるとき、産業廃棄物として処理を委託した。","建築物内のテナントがデジタルカメラを捨てるとき、テナントの業者が主務大臣の認定を受けた事業者に引き渡してリサイクルした。","建築物内のテナントがテレビを買い替えずに捨てるとき、そのテレビを買った小売業者に頼み、リサイクル料金を払って引き取ってもらった。"],"a":1,"e":"事業活動で出たペットボトルは産業廃棄物(廃プラスチック類)で、事業者が自ら処理を委託する。家庭ごみ向けの自治体の資源回収に出すのは誤り。","l":"廃棄物処理法 第3条・第12条","c":""},{"id":"2025-159","s":5,"q":"産業廃棄物管理票(紙マニフェスト)の扱いについて述べた次の文のうち、最も不適当なものはどれか。","o":["返送されたマニフェストの伝票は、5年間保存しなければならない。","虚偽の記載があるマニフェストの写しを受け取ったときは、日本産業廃棄物処理振興センター(JWセンター)に報告しなければならない。","特別管理産業廃棄物以外の産業廃棄物で、処理を頼んでから90日たってもB2票とD票が戻らないときは、委託先に問い合わせる必要がある。","処理を頼んでから180日たってもE票が戻らないときは、委託先に問い合わせる必要がある。","マニフェストを交付した排出事業者は、産業廃棄物管理票交付等状況報告書を自治体に提出しなければならない。"],"a":1,"e":"虚偽の記載があるマニフェストの写しを受け取ったときは、知った日から30日以内に都道府県知事へ報告する(廃棄物処理法施行規則第8条の29)。保存5年は第8条の26、90日・180日は第8条の28のとおり。","l":"廃棄物処理法施行規則 第8条の26・第8条の28・第8条の29","c":""},{"id":"2025-160","s":5,"q":"廃棄物処理法での一般廃棄物と産業廃棄物について述べた次の文のうち、最も不適当なものはどれか。","o":["事務所の建築物から捨てられたスチール机は、産業廃棄物である。","スーパーマーケットから出た紙くずは、一般廃棄物である。","カフェテリアから捨てられた生ごみは、一般廃棄物である。","し尿を含まないビルピット汚泥は、一般廃棄物である。","レストランから出た廃てんぷら油は、産業廃棄物である。"],"a":3,"e":"し尿を含まないビルピット汚泥は、汚泥として産業廃棄物になる(し尿を含むものは一般廃棄物)。","l":"廃棄物処理法 第2条","c":""},{"id":"2025-161","s":5,"q":"建築物内廃棄物について述べた次の文のうち、最も不適当なものはどれか。","o":["燃えるおそれのある吸い殻などは、ステンレス製のコレクタで集める。","新築の建築物では、使い始めて一定期間たったら廃棄物処理計画を見直す。","雑芥とは、動植物性の残りかすの廃棄物で、レストランやホテルなどの調理場から出るごみである。","感染性のおそれのある産業廃棄物かどうかの判断は難しく、医療関係者に任されている。","個人によるインスリン注射が認められているため、ホテルや商業施設の一般ごみに注射針が捨てられ、回収時に手に刺さる事故が起きている。"],"a":2,"e":"調理場から出る動植物性の残りかすは「厨芥(ちゅうかい)」。雑芥は紙くずなどが混じった雑多なごみを指す。","l":"法令外","c":""},{"id":"2025-162","s":5,"q":"建築物内廃棄物の中間処理の方法について述べた次の文のうち、最も不適当なものはどれか。","o":["プラスチック類の中間処理の方法として、圧縮がある。","缶類の処理方法として、スチール缶とアルミ缶を自動で分けて圧縮し、ブロック状にする方式がある。","発泡スチロールの処理に使う溶融固形化装置は、熱を加えて溶かし固める方式である。","新聞・雑誌の処理には、保管スペースを確保するため、圧縮・切断設備が使われる。","建築物内に導入されている系内処理設備は、比較的小さいものが多い。"],"a":3,"e":"この記述が誤り。新聞・雑誌は資源としてそのまま回収されるため、圧縮・切断ではなく梱包(結束)して保管するのが一般的である。","l":"法令外","c":""},{"id":"2025-163","s":5,"q":"建築物内廃棄物の分類と、リサイクルを進めるための「見える化」について述べた次の文のうち、最も不適当なものはどれか。","o":["建築物内廃棄物は、有価物、事業系一般廃棄物、産業廃棄物に分けられる。","ごみ量の見える化によって、分別がリサイクル向上などにどれだけ役立っているかを実感できる。","ごみ置き場の見える化は、清掃員などの作業環境の改善や分別保管を可能にし、分別の意識付けに役立つ。","ごみ管理運営の見える化は、ごみ管理者などの日常業務の管理を楽にし、経済的なリサイクル対策を後押しする。","マニフェスト制度は、建築物の外へのごみの移動状況を見える化することが目的である。"],"a":4,"e":"マニフェスト制度は、排出事業者が委託した産業廃棄物の処理状況を把握し、不法投棄などの不適正な処理を防ぐための制度(廃棄物処理法第12条の3)で、見える化が目的ではない。","l":"廃棄物処理法 第12条の3","c":""},{"id":"2025-164","s":5,"q":"建築物内廃棄物の貯留・搬出方式について述べた次の文のうち、最も不適当なものはどれか。","o":["コンパクタ・コンテナ方式は、容器方式より防災性にすぐれる。","真空収集方式は、容器方式より衛生性にすぐれる。","貯留・排出機方式は、真空収集方式より初期費用が少ない。","コンパクタ・コンテナ方式は、小規模な建築物に向いている。","コンパクタ・コンテナ方式は、容器方式よりランニングコストが小さい。"],"a":3,"e":"コンパクタ・コンテナ方式は設備が大きく、廃棄物の多い大規模な建築物に向く方式である。小規模な建築物には容器方式などが向く。","l":"法令外","c":""},{"id":"2025-165","s":5,"q":"建築物内廃棄物の保管場所と帳簿書類について述べた次の文のうち、最も不適当なものはどれか。","o":["廃棄物の保管場所は、清掃用具置場、物品庫、清掃控室などと兼ねないようにする。","建築物の中に保管場所を設けるときは第1種換気設備(給排気設備)を、屋外に設けるときは近隣に影響しない有効な換気設備(通気口)を設ける。","建築物衛生法の特定建築物では、廃棄物処理に関する帳簿書類の保存期間は5年である。","建築物衛生法の特定建築物では、廃棄物保管設備のまわりなどねずみ等が発生しやすい場所のねずみの生息状況調査を、6か月以内ごとに1回行う。","保管場所の床の排水に支障がないよう、適度な床の勾配をつける。"],"a":3,"e":"廃棄物の保管設備の周辺など、特にねずみ等が発生しやすい箇所の生息状況調査は2か月以内ごとに1回(告示第119号 第6)。6か月以内ごとに1回は建築物全体の統一的な調査(施行規則第4条の5)。帳簿の5年保存は施行規則第20条。","l":"平成15年厚生労働省告示第119号 第6、建築物衛生法施行規則 第4条の5・第20条","c":""},{"id":"2025-166","s":6,"q":"蚊の生態に関する記述として、最も不適当なものはどれか。","o":["ヒトスジシマカの幼虫は、道路や公園の雨水ますなどで発生する。","コガタアカイエカの幼虫は、主に水田や湿地で発生する。","アカイエカは、主に昼間に屋外で吸血する。","チカイエカは、羽化して最初の産卵を吸血しないで行うことができる。","ヒトスジシマカは、ヒト以外のいろいろな動物からも吸血する。"],"a":2,"e":"アカイエカは夜間に吸血する性質をもつ(2021年問167で「アカイエカは夜間吸血性を示す」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-167","s":6,"q":"蚊の調査方法に関する記述として、最も不適当なものはどれか。","o":["成虫の調査方法として、ドライアイスを誘引源にしたトラップを使う方法がある。","捕虫網を使うスウィーピング法は、ヒトスジシマカの成虫の調査に向いている。","オビトラップは、産卵に来た雌成虫を誘い、産み付けられた卵を集めるトラップである。","幼虫の調査は、柄杓(ひしゃく)などで水面を決まった回数すくい取る方法で行う。","屋外の調査では、ハエ取りリボンやゴキブリ用粘着トラップを長期間つるしておく方法が効果的である。"],"a":4,"e":"(5)の記述が誤り。","l":"法令外","c":""},{"id":"2025-168","s":6,"q":"次の文を読んで、ゴキブリ指数と防除率について正しいものはどれか。\nある工場でゴキブリ用粘着トラップを使い、ゴキブリ指数を求めた。薬剤散布の前に10か所へ5日間トラップを置いたところ、合計200匹がとれた。その後、薬剤を散布し、同じ場所に同じ数のトラップを10日間置いたところ、合計2匹がとれた。","o":["散布前のゴキブリ指数は0.4である。","散布後のゴキブリ指数は0.05である。","散布前のゴキブリ指数は4である。","この作業による防除率は90%である。","散布後のゴキブリ指数は0.2である。"],"a":2,"e":"ゴキブリ指数は「捕獲数 ÷ トラップ数 ÷ 日数」で求める。散布前は200÷10÷5=4、散布後は2÷10÷10=0.02、防除率は(4−0.02)÷4=99.5%となる。","l":"法令外","c":""},{"id":"2025-169","s":6,"q":"ゴキブリの生態に関する記述として、最も適当なものはどれか。","o":["ゴキブリの食べ物の好みは、成長の段階によって変わる。","ゴキブリが集まるのは、気門から出る集合フェロモンの働きによる。","日本にいるゴキブリの種類の多くは、屋内で暮らしている。","ゴキブリは食べ物の好みがはっきりしていて、決まったものしか食べない。","ゴキブリには決まった条件の潜み場所があり、昼間はほとんどそこに隠れている。"],"a":4,"e":"ゴキブリは一定の条件を満たす潜み場所をもち、日中はほとんどそこに潜んでいる。","l":"法令外","c":""},{"id":"2025-170","s":6,"q":"屋内のダニ類の防除の進め方として、最も不適当なものはどれか。","o":["屋内のダニ類の防除は、日ごろの発生予防が基本である。","ダニ類によると思われる被害では、原因を突き止めるよりも、すばやく殺虫剤をまくことを優先する。","吸血性のダニ類の防除では、ヒト以外の宿主になっている動物への対策が必要である。","刺咬性のダニ類の防除では、掃除機でこまめにほこりを取ることの効果が高い。","アレルゲンになるダニ類の防除では、床や寝具への対策が重要である。"],"a":1,"e":"まず原因を特定することが先で、殺虫剤散布を優先するのは誤り。","l":"法令外","c":""},{"id":"2025-171","s":6,"q":"ダニの種類と、ヒトへの健康被害の組合せとして、最も適当なものはどれか。","o":["コナヒョウヒダニ ― 喘息などの原因","ヤケヒョウヒダニ ― ヒトを刺す","ミナミツメダニ ― 感染症を広める","イエダニ ― 皮膚の下に入り込んで寄生する","カベアナタカラダニ ― ヒトから血を吸う"],"a":0,"e":"コナヒョウヒダニ(チリダニ類)は、喘息などのアレルギーの原因になる。","l":"法令外","c":""},{"id":"2025-172","s":6,"q":"昆虫の体の特徴や生活史に関する記述として、最も不適当なものはどれか。","o":["昆虫の体全体をおおう表皮は、外骨格と呼ばれる。","休眠に入ることと目覚めることは、ホルモンによって調節されている。","1年に1世代だけ現れる昆虫を、一化性の昆虫という。","蛹(さなぎ)の時期がない昆虫を、完全変態の昆虫という。","幼虫が蛹になることを、蛹化という。"],"a":3,"e":"蛹の時期がない昆虫は不完全変態の昆虫である。完全変態の昆虫は蛹の時期をもつ。","l":"法令外","c":""},{"id":"2025-173","s":6,"q":"害虫に関する記述として、最も適当なものはどれか。","o":["イガの幼虫は、貯蔵した穀物の害虫である。","ノシメマダラメイガの幼虫は、繊維や衣類の害虫である。","コロモジラミは、発疹チフスなどの感染症を広める。","ネコノミは、哺乳類や鳥類の体内に寄生する昆虫である。","トコジラミは、日本紅斑熱リケッチアを運ぶ。"],"a":2,"e":"コロモジラミは発疹チフスなどの感染症を媒介する。","l":"法令外","c":""},{"id":"2025-174","s":6,"q":"殺虫剤・忌避剤の種類と、衛生害虫への効き方の組合せとして、最も不適当なものはどれか。","o":["有機リン剤 ― ノックダウンした害虫は生き返りにくい。","ピレスロイド剤 ― 直接かかったときの効き目が速い。","昆虫成長制御剤(IGR剤) ― 幼虫にも成虫にも効く。","ブロフラニリド ― 殺虫剤抵抗性をもつトコジラミにも効く。","ディート ― 処理した面にふれるのを嫌がらせて、吸血を防ぐ。"],"a":2,"e":"IGR剤は成虫を殺す効果がない(2016年問167で「成虫に対する致死効果がない」が正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-175","s":6,"q":"クマネズミの成獣に関する記述として、最も不適当なものはどれか。","o":["原産地は東南アジアで、もともとは森林の木の上で暮らしていた。","尾は体長より短い。","ドブネズミと比べて警戒心が強く、毒餌をなかなか食べない。","巣は天井裏や壁の中など、屋内に多い。","耳が大きく、折り返すと目をおおう。"],"a":1,"e":"クマネズミの尾は体長より長い(2021年問173で正しい記述として出題)。","l":"法令外","c":""},{"id":"2025-176","s":6,"q":"ネズミ用の薬剤に関する記述として、最も不適当なものはどれか。","o":["ブロマジオロン製剤は、動物用医薬部外品として承認されている。","シクロヘキシミドは忌避剤で、かじられるのを防ぐ目的などで使われる。","クマテトラリルなどの粉剤は、餌の材料にまぶして毒餌として使える。","ジフェチアロールは、第2世代の抗凝血性殺鼠剤である。","リン化亜鉛は、ネズミを死なせるために何回も食べさせる必要がある。"],"a":4,"e":"リン化亜鉛は急性毒の殺鼠剤で、1回食べさせるだけで致死する(2023年問175で正しい組合せとして出題)。","l":"法令外","c":""},{"id":"2025-177","s":6,"q":"殺鼠剤に関する記述として、最も適当なものはどれか。","o":["ネズミ防除の現場では、殺鼠剤と粘着トラップを同時に使えない。","同じ殺鼠剤ばかり続けて使うと、ネズミの集団の中で抵抗性が発達してくる。","殺鼠剤を食べて死んだネズミから、ハエなどが発生することはない。","殺鼠剤を食べたネズミが弱ってくると、体に寄生しているイエダニなども死に始める。","ネズミが食べやすいように、屋根裏などに殺鼠剤を広くまく。"],"a":1,"e":"同じ殺鼠剤を使い続けると、ネズミの集団の中で抵抗性が発達する。","l":"法令外","c":""},{"id":"2025-178","s":6,"q":"次の文を読んで、イエダニの密度とその評価について正しいものはどれか。\nAさんは、A事業所とB事業所の畳の上にいるダニの密度を調べるため、幅10cmのローラ式粘着クリーナを使った。A事業所では5cm転がし、粘着紙にイエダニが5匹付いていた。B事業所では10cm転がし、20匹付いていた。","o":["A事業所のイエダニの密度は500匹/m²である。","A事業所のイエダニの密度は2,500匹/m²である。","B事業所のイエダニの密度は1,000匹/m²である。","B事業所のイエダニの密度は2,000匹/m²である。","イエダニの密度はA事業所のほうが高い。"],"a":3,"e":"調べた面積はAが0.1m×0.05m=0.005m²、Bが0.1m×0.1m=0.01m²。密度はAが5÷0.005=1,000匹/m²、Bが20÷0.01=2,000匹/m²で、Bのほうが高い。","l":"法令外","c":""},{"id":"2025-179","s":6,"q":"ねずみ・害虫対策の考え方に関する記述として、最も不適当なものはどれか。","o":["ねずみ・害虫などの有害生物を防除することを、ペストコントロールという。","IPMに基づく防除では、ヒトの健康へのリスクと環境への負荷をできるだけ小さくする方法を取り入れる。","IPMの調査の考え方では、6か月以内または2か月以内ごとに行う調査を定期調査という。","粘着トラップは、ネズミやゴキブリなどを捕まえて防除するために使われる。","ねずみ・害虫対策でいちばん重要なのは、薬剤や器具などを使った発生時の対策である。"],"a":4,"e":"対策の基本は発生予防対策であり、発生時対策より発生予防対策に重点を置く(2020年問179・2022年問180で正しい記述として出題)。なお調査の頻度(6か月以内ごと、発生しやすい場所は2か月以内ごと)は施行規則第4条の5と告示119号第6に定められている。","l":"建築物衛生法施行規則 第4条の5、平成15年厚生労働省告示第119号 第6(選択肢3)","c":""},{"id":"2025-180","s":6,"q":"有害動物や防除に関する記述として、最も適当なものはどれか。","o":["補助者をつけ、ヘルメットや墜落制止用器具を着けなければならない高所作業は、労働安全衛生法で1.5m以上と決められている。","基礎的な殺虫力や羽化阻害の効力はLD50・LC50・IC50などで評価され、この値が大きいほど効力が高い。","ダニ類の成虫の体は、頭部・胸部・腹部の3つに分かれる。","ハトの巣を卵ごと取り除く場合は、自治体の長などの許可が必要になる。","ネコノミの幼虫は、吸血をくり返して成長する。"],"a":3,"e":"鳥類の卵の採取等は原則禁止で、行うには都道府県知事(場合により環境大臣)の許可が必要(鳥獣保護管理法第8条・第9条)。なお墜落防止措置が必要な高所作業は高さ2m以上である(労働安全衛生規則第518条)。","l":"鳥獣の保護及び管理並びに狩猟の適正化に関する法律 第8条・第9条、労働安全衛生規則 第518条","c":""}];
